(*====== 程序简介 ========================================================================================================
 @ 名称				:	FB_EipToIRayple
 @ 描述				:	华睿扫码枪功能块
 @ 作者				:	KZYK
 @ 日期				:	2024.06.14	
 @ 版本号			:	V1.00.00.240614
 @ 配套				:
 @ 限制等级		:	A2.原则上不允许改动	
 =========================================================================================================================
 @ 说明				:	用于EIP与华睿扫码枪通信
 @ 
 ===== 修改履历 ===========================================================================================================
 修改日期	| 版本			| 作者			| 备注 
 -------------------------------------------------------------------------------------------------------------------------
 2024.06.14	| V1.00.00		| KZYK		        | 初版发布
 ======= END ==============================================================================================================*)


//触发扫码
TON_PT[0]:=	T#100ms; 
TON_In[1]:=		H_Out.iStepAutoScan = 20;
TON_PT[1]:=	T#2S; 
TON_In[2]:=		H_Out.iStepAutoScan = 1;
TON_PT[2]:=	T#1000ms; 
TON_In[3]:=		TryAgainTime > 0 AND H_Out.iStepAutoScan = 20;
TON_PT[3]:=	T#100ms; 
TON_In[4]:=		H_Out.iStepAutoScan = 0;
TON_PT[4]:=	T#100ms; 
TON_In[5]:=	(In.Execute OR H_In.Execute) AND NOT Out.ReadSuccess AND 
	NOT Out.ReadFailure AND H_In.Enable AND NOT Reset;
TON_PT[5]:=	T#20s; 
//控制器有发生错误
TON_PT[6]:=	T#200ms; 

R_TRIG_Clk[0]:=In.Execute OR H_In.Execute;

//定时器和上升沿
FOR i:=0 TO 6 DO
	TON_instance[i](In:=TON_In[i],PT:=TON_PT[i],Q=>TON_Q[i]);//定时器
	R_TRIG_instance[i] (Clk:=R_TRIG_Clk[i],Q=>R_TRIG_Q[i]);//上升沿
END_FOR;

//清除信号
IF R_TRIG_Q[0] THEN
	H_Out.BarCodeString:='';
	H_Out.ReadSuccess:=FALSE;
	H_Out.ReadFailure:=FALSE;
END_IF;

//读取结果
(*
Byte[2].Bit0 Read Done
Byte[3].Bit0 Read Complete
Byte[3].Bit2 Read Failure
*)
//读取处理完成标志
MyDword_Bit.mByte[0]:=SR_To_PLC_Data[2].mByte;
SR_ReadDone:=MyDword_Bit.mWord[0].0;
//读取成功
MyDword_Bit.mByte[0]:=SR_To_PLC_Data[3].mByte;
SR_ReadComplete:=MyDword_Bit.mWord[0].0;
//读取失败
MyDword_Bit.mByte[0]:=SR_To_PLC_Data[3].mByte;
SR_ReadFailure:=MyDword_Bit.mWord[0].2;


(************************************扫码流程************************************)
IF H_In.Enable THEN
	//条码通信处理
	CASE H_Out.iStepAutoScan OF
		0://复位输出信号
			Clear(In:=PLC_To_SR_Data[0]);
			Clear(In:=PLC_To_SR_Data[1]);
			Clear(In:=PLC_To_SR_Data[2]);
			Clear(In:=PLC_To_SR_Data[3]);
			Clear(In:=PLC_To_SR_Data[4]);
			
			IF TON_Q[4] AND ErrorTemp.mWord=0 THEN
				H_Out.iStepAutoScan:=1;
			END_IF;
		1://重置扫码枪状态
			IF SR_ReadDone THEN 
				PLC_To_SR_Data[2].mByte:=BYTE#1;
			ELSE
				PLC_To_SR_Data[2].mByte:=BYTE#0;
				H_Out.iStepAutoScan:=5;
			END_IF;
				
			IF TON_Q[2] THEN
				PLC_To_SR_Data[2].mByte:=BYTE#0;
				ErrorTemp.mWord.1:=TRUE;//清除状态超时错误
				H_Out.iStepAutoScan:=0;
			END_IF;
		5://等待条码请求
			RequestReadSuccess_Temp:=FALSE;
			RequestReadFailure_Temp:=FALSE;
			Out.ReadSuccess:=FALSE;
			Out.ReadFailure:=FALSE;
			IF ((Auto AND In.Execute)
				OR (Manual AND H_In.Execute)
				OR ScanAgain)
				AND ErrorTemp.mWord=0
			THEN
				Clear(BarCodeArray);
				Clear(Out);
				H_Out.iStepAutoScan:=10;
			END_IF;
		10://扫码触发
			H_Out.ReadSuccess:=FALSE;
			H_Out.ReadFailure:=FALSE;
			PLC_To_SR_Data[1].mByte:=BYTE#1;
			H_Out.iStepAutoScan:=20;
		20://读取完成标志
			//条码读取成功
			IF  SR_ReadDone
				AND  SR_ReadComplete
				AND NOT SR_ReadFailure
			THEN//读取成功
				PLC_To_SR_Data[1].mByte:=BYTE#0;	//清除触发
				PLC_To_SR_Data[2].mByte:=BYTE#1;  //清除读取状态
				H_Out.iStepAutoScan:=25;
				NGTimes:=0;
			END_IF;
			//条码读取失败
			IF  SR_ReadDone
				AND SR_ReadFailure
			THEN //读取失败
				PLC_To_SR_Data[1].mByte:=BYTE#0;	//清除触发
				PLC_To_SR_Data[2].mByte:=BYTE#1;  //清除读取状态
				IF TryAgainTime > 1 THEN
					Inc(NGTimes);
					RequestReadFailure_Temp:=TRUE;
					H_Out.iStepAutoScan:=35;
				ELSE
					Inc(TryAgainTime);
					ScanAgain:=TRUE;//再次扫码
					H_Out.iStepAutoScan:=0;	//再次触发
				END_IF;
			END_IF;
			//条码读取超时
			IF  TON_Q[1] THEN //未成功
				PLC_To_SR_Data[1].mByte:=BYTE#0;	//清除触发
				PLC_To_SR_Data[2].mByte:=BYTE#1;  //清除读取状态
				IF TryAgainTime > 1 THEN
					Inc(NGTimes);
					RequestReadFailure_Temp:=TRUE;
					H_Out.iStepAutoScan:=35;
				ELSE
					Inc(TryAgainTime);
					ScanAgain:=TRUE;//再次扫码
					H_Out.iStepAutoScan:=0;	//再次触发
				END_IF;
			END_IF;
		25://条码读取成功
			//条码长度
			Out.BarCode_Size:=WORD_TO_UINT(SR_To_PLC_Data[42].mByte);
			SR_BarCodeSize:=WORD_TO_UINT(SR_To_PLC_Data[42].mByte);
			//条码转换
			IF SR_BarCodeSize <>0  THEN
				IF TRUE THEN
					RecvString_temp[0]:=SR_To_PLC_Data[44].mByte;
					RecvString_temp[1]:=SR_To_PLC_Data[45].mByte;
					RecvString_temp[2]:=SR_To_PLC_Data[46].mByte;
					RecvString_temp[3]:=SR_To_PLC_Data[47].mByte;
					RecvString_temp[4]:=SR_To_PLC_Data[48].mByte;
					RecvString_temp[5]:=SR_To_PLC_Data[49].mByte;
					RecvString_temp[6]:=SR_To_PLC_Data[50].mByte;
					RecvString_temp[7]:=SR_To_PLC_Data[51].mByte;
					RecvString_temp[8]:=SR_To_PLC_Data[52].mByte;
					RecvString_temp[9]:=SR_To_PLC_Data[53].mByte;
					RecvString_temp[10]:=SR_To_PLC_Data[54].mByte;
					RecvString_temp[11]:=SR_To_PLC_Data[55].mByte;
					RecvString_temp[12]:=SR_To_PLC_Data[56].mByte;
					RecvString_temp[13]:=SR_To_PLC_Data[57].mByte;
					RecvString_temp[14]:=SR_To_PLC_Data[58].mByte;
					RecvString_temp[15]:=SR_To_PLC_Data[59].mByte;
					RecvString_temp[16]:=SR_To_PLC_Data[60].mByte;
					RecvString_temp[17]:=SR_To_PLC_Data[61].mByte;
					RecvString_temp[18]:=SR_To_PLC_Data[62].mByte;
					RecvString_temp[19]:=SR_To_PLC_Data[63].mByte;
					RecvString_temp[20]:=SR_To_PLC_Data[64].mByte;
					RecvString_temp[21]:=SR_To_PLC_Data[65].mByte;
					RecvString_temp[22]:=SR_To_PLC_Data[66].mByte;
					RecvString_temp[23]:=SR_To_PLC_Data[67].mByte;
					RecvString_temp[24]:=SR_To_PLC_Data[68].mByte;
					RecvString_temp[25]:=SR_To_PLC_Data[69].mByte;
					RecvString_temp[26]:=SR_To_PLC_Data[70].mByte;
					RecvString_temp[27]:=SR_To_PLC_Data[71].mByte;
					RecvString_temp[28]:=SR_To_PLC_Data[72].mByte;
					RecvString_temp[29]:=SR_To_PLC_Data[73].mByte;
					RecvString_temp[30]:=SR_To_PLC_Data[74].mByte;
					RecvString_temp[31]:=SR_To_PLC_Data[75].mByte;
					RecvString_temp[32]:=SR_To_PLC_Data[76].mByte;
					RecvString_temp[33]:=SR_To_PLC_Data[77].mByte;
					RecvString_temp[34]:=SR_To_PLC_Data[78].mByte;
					RecvString_temp[35]:=SR_To_PLC_Data[79].mByte;
					RecvString_temp[36]:=SR_To_PLC_Data[80].mByte;
					RecvString_temp[37]:=SR_To_PLC_Data[81].mByte;
					RecvString_temp[38]:=SR_To_PLC_Data[82].mByte;
					RecvString_temp[39]:=SR_To_PLC_Data[83].mByte;
					RecvString_temp[40]:=SR_To_PLC_Data[84].mByte;
					RecvString_temp[41]:=SR_To_PLC_Data[85].mByte;
					RecvString_temp[42]:=SR_To_PLC_Data[86].mByte;
					RecvString_temp[43]:=SR_To_PLC_Data[87].mByte;
					RecvString_temp[44]:=SR_To_PLC_Data[88].mByte;
					RecvString_temp[45]:=SR_To_PLC_Data[89].mByte;
					RecvString_temp[46]:=SR_To_PLC_Data[90].mByte;
					RecvString_temp[47]:=SR_To_PLC_Data[91].mByte;
					RecvString_temp[48]:=SR_To_PLC_Data[92].mByte;
					RecvString_temp[49]:=SR_To_PLC_Data[93].mByte;
					RecvString_temp[50]:=SR_To_PLC_Data[94].mByte;
					RecvString_temp[51]:=SR_To_PLC_Data[95].mByte;
					RecvString_temp[52]:=SR_To_PLC_Data[96].mByte;
					RecvString_temp[53]:=SR_To_PLC_Data[97].mByte;
					RecvString_temp[54]:=SR_To_PLC_Data[98].mByte;
					RecvString_temp[55]:=SR_To_PLC_Data[99].mByte;
					RecvString_temp[56]:=SR_To_PLC_Data[100].mByte;
					RecvString_temp[57]:=SR_To_PLC_Data[101].mByte;
					RecvString_temp[58]:=SR_To_PLC_Data[102].mByte;
					RecvString_temp[59]:=SR_To_PLC_Data[103].mByte;
					RecvString_temp[60]:=SR_To_PLC_Data[104].mByte;
					RecvString_temp[61]:=SR_To_PLC_Data[105].mByte;
					RecvString_temp[62]:=SR_To_PLC_Data[106].mByte;
					RecvString_temp[63]:=SR_To_PLC_Data[107].mByte;
					RecvString_temp[64]:=SR_To_PLC_Data[108].mByte;
					RecvString_temp[65]:=SR_To_PLC_Data[109].mByte;
					RecvString_temp[66]:=SR_To_PLC_Data[110].mByte;
					RecvString_temp[67]:=SR_To_PLC_Data[111].mByte;
					RecvString_temp[68]:=SR_To_PLC_Data[112].mByte;
					RecvString_temp[69]:=SR_To_PLC_Data[113].mByte;
					RecvString_temp[70]:=SR_To_PLC_Data[114].mByte;
					RecvString_temp[71]:=SR_To_PLC_Data[115].mByte;
					RecvString_temp[72]:=SR_To_PLC_Data[116].mByte;
					RecvString_temp[73]:=SR_To_PLC_Data[117].mByte;
					RecvString_temp[74]:=SR_To_PLC_Data[118].mByte;
					RecvString_temp[75]:=SR_To_PLC_Data[119].mByte;
					RecvString_temp[76]:=SR_To_PLC_Data[120].mByte;
					RecvString_temp[77]:=SR_To_PLC_Data[121].mByte;
					RecvString_temp[78]:=SR_To_PLC_Data[122].mByte;
					RecvString_temp[79]:=SR_To_PLC_Data[123].mByte;
					RecvString_temp[80]:=SR_To_PLC_Data[124].mByte;
					RecvString_temp[81]:=SR_To_PLC_Data[125].mByte;
					RecvString_temp[82]:=SR_To_PLC_Data[126].mByte;
					RecvString_temp[83]:=SR_To_PLC_Data[127].mByte;
					RecvString_temp[84]:=SR_To_PLC_Data[128].mByte;
					RecvString_temp[85]:=SR_To_PLC_Data[129].mByte;
					RecvString_temp[86]:=SR_To_PLC_Data[130].mByte;
					RecvString_temp[87]:=SR_To_PLC_Data[131].mByte;
					RecvString_temp[88]:=SR_To_PLC_Data[132].mByte;
					RecvString_temp[89]:=SR_To_PLC_Data[133].mByte;
					RecvString_temp[90]:=SR_To_PLC_Data[134].mByte;
					RecvString_temp[91]:=SR_To_PLC_Data[135].mByte;
					RecvString_temp[92]:=SR_To_PLC_Data[136].mByte;
					RecvString_temp[93]:=SR_To_PLC_Data[137].mByte;
					RecvString_temp[94]:=SR_To_PLC_Data[138].mByte;
					RecvString_temp[95]:=SR_To_PLC_Data[139].mByte;
					RecvString_temp[96]:=SR_To_PLC_Data[140].mByte;
					RecvString_temp[97]:=SR_To_PLC_Data[141].mByte;
					RecvString_temp[98]:=SR_To_PLC_Data[142].mByte;
					RecvString_temp[99]:=SR_To_PLC_Data[143].mByte;
				END_IF
				AryToString(In:=RecvString_temp[0] , Size:=100 , Out=>Out.RecvString );
				FC_SplitString(strData:=Out.RecvString, strDiv:=',', SplitString=>BarCodeArray,nCount =>BarCodeCount);
				Out.BarCodeString:=BarCodeArray[0];
				Out.TotalClass:=BarCodeArray[1];
			END_IF;
			//读取条码失败 
			IF LEN( Out.BarCodeString) <=0  THEN
				RequestReadSuccess_Temp:=FALSE;
				RequestReadFailure_Temp:=TRUE;
			ELSIF LEN( Out.BarCodeString) >0 THEN
				RequestReadSuccess_Temp:=TRUE;
				RequestReadFailure_Temp:=FALSE;
			END_IF;
			H_Out.iStepAutoScan:=30;
		30://检查是否重码
			//比较字符串与上次是否一致
			IF  Out.BarCodeString <> BarCodeTemp OR CompareNo > 1 THEN		//与上次条码不同
				BarCodeTemp:=Out.BarCodeString;
				CompareNo:=0;
				H_Out.iStepAutoScan:=35;
			ELSE
				Inc(CompareNo);
				ScanAgain:=TRUE;//再次扫码
				H_Out.iStepAutoScan:=0;
			END_IF;
		35://条码读取结果输出
			Out.ReadSuccess:=RequestReadSuccess_Temp;
			Out.ReadFailure:=NOT RequestReadSuccess_Temp;
			H_Out.ReadSuccess:=Out.ReadSuccess;
			H_Out.ReadFailure:=Out.ReadFailure;
			//条码读取失败时产生一个错误的条码格式为ERR+S工位+时间
			DtToString(GetTime(),Out=>Dtstring);
			IF Out.ReadFailure THEN
				Out.BarCodeString:=LEFT(CONCAT('ERR', CONCAT(CONCAT('S',UINT_TO_STRING(In.StationNo)),Dtstring)),24);//条码
			END_IF;
			H_Out.iStepAutoScan:=40;
		40://等待外部条码请求断开
			TryAgainTime:=0;
			ScanAgain:=FALSE;//再次扫码
			IF NOT In.Execute AND NOT H_In.Execute THEN
				Out.ReadFailure:=FALSE;
				Out.ReadSuccess:=FALSE;
			END_IF;
			//所有数据复位
			IF NOT Out.ReadFailure AND NOT Out.ReadSuccess AND NOT In.Execute AND NOT H_In.Execute THEN
				H_Out.iStepAutoScan:=0;
			END_IF;
	END_CASE;
ELSE
	//未启用时直接回复成功
	Out.ReadSuccess:=In.Execute OR H_In.Execute;
	Out.ReadFailure:=FALSE;
	IF In.Execute OR H_In.Execute THEN
	H_Out.ReadSuccess:=Out.ReadSuccess;
	H_Out.ReadFailure:=Out.ReadFailure;
	END_IF;
	//产生一个虚拟条码 TES+S工位+时间
	HC_OmronUtils.DtToString(In:=GetTime() , Out=>Temp_Time );
	IF In.Execute OR H_In.Execute THEN
		Out.BarCodeString:=LEFT(CONCAT('TES', CONCAT(CONCAT('S',UINT_TO_STRING(In.StationNo)),Temp_Time)),24);//条码
		Out.TotalClass:='A';
	END_IF;
	H_Out.iStepAutoScan:=0;
END_IF;


(************************************HMI输出************************************)
H_Out.RecvString:=Out.RecvString;
H_Out.BarCodeString:=Out.BarCodeString;
H_Out.TotalClass:=Out.TotalClass;

(************************************报警信息************************************)
//连接失败  _EIP2_RegTargetSta 表示NX中2口的注册EIP  _EIP2_EstbTargetSta表示2口的EIP连接状态
	Node:=Parameter.IP_Node;
	IF Node>0 AND Node<64 
		AND H_In.Enable
		//AND NOT _EIP_EstbTargetSta[Node]//EIP模块通讯状态
	THEN
		ErrorTemp.mWord.0:=TRUE;
	END_IF;

//ErrorTemp.mBit[1] 清除状态超时错误

//连续NG报警
IF Parameter.NGTimesMax >0  AND NGTimes > Parameter.NGTimesMax THEN
	ErrorTemp.mWord.2:=TRUE;
END_IF;

//通信超时
IF TON_Q[5] THEN
	ErrorTemp.mWord.3:=TRUE;
END_IF;



(************************************报警复位************************************)
IF ErrorTemp.mWord.0
	OR ErrorTemp.mWord.1
	OR ErrorTemp.mWord.3
THEN
	PLC_To_SR_Data[0].mByte:=BYTE_temp;
	ScanAgain:=FALSE;
	H_Out.iStepAutoScan:=0;
END_IF;

IF Reset THEN
	NGTimes:=0;	//NG次数
	ErrorTemp.mWord:=0;
END_IF;



(************************************报警映射************************************)
//总错误
ErrOut.Alarm:=ErrorTemp.mWord<>0;
//EIP连接错误
ErrOut.Error[0] :=ErrorTemp.mWord.0;
//清除状态超时错误
ErrOut.Error[1] :=ErrorTemp.mWord.1;
//连续NG错误
ErrOut.Error[2] :=ErrorTemp.mWord.2;
//通信超时---流程超时错误
ErrOut.Error[3] :=ErrorTemp.mWord.3;

;

