IF HMI_RecipeData.PC_Sprial_n=0 THEN
	HMI_RecipeData.PC_Sprial_n:=3;
END_IF;
IF HMI_RecipeData.PC_Sprial_b=0 THEN
	HMI_RecipeData.PC_Sprial_b:=0.3;
END_IF;
PC_Sprial_n:=HMI_RecipeData.PC_Sprial_n;
PC_Sprial_b:=HMI_RecipeData.PC_Sprial_b;

IF CamTableSave_Step=1 THEN
	CamIndex:=0;
	IF HMI_RecipeData.Ellipse_Long >0.01 AND HMI_RecipeData.Ellipse_Short  >0.01 THEN
		Ellipse_K:=HMI_RecipeData.Ellipse_Long/HMI_RecipeData.Ellipse_Short;
	ELSE
		Ellipse_K:=1;
	END_IF;
	
	CamTable_SprialX[0].dX :=0;
	CamTable_SprialX[0].dY :=0;
		
	CamTable_SprialY[0].dX :=0;	
	CamTable_SprialY[0].dY :=0;	
	
	PC_Sprial_n_Temp:=REAL_TO_DINT(PC_Sprial_n);
	//等差数列:例如共计9圈，第一圈取20个点，第二圈向后每圈依次增加
	Cam_NodeCount:=32767;
	Cam_FisrtCyclePoint:=Cam_NodeCount / PC_Sprial_n_Temp / 2;  
	Cam_CycleAddPoint:=2* (Cam_NodeCount  -  Cam_FisrtCyclePoint * PC_Sprial_n_Temp) / 
																	 PC_Sprial_n_Temp/(PC_Sprial_n_Temp - 1); 
	IF NOT PC_Sprial_Dir THEN 
		FOR i:= 1 TO PC_Sprial_n_Temp DO
			Cam_CyclePointCount := Cam_FisrtCyclePoint + (i -1) * Cam_CycleAddPoint; 
			Cam_PointAngle:= 360.0 / DINT_TO_REAL(Cam_CyclePointCount); 
			FOR j:=1 TO Cam_CyclePointCount -1 DO
				Inc(CamIndex);
				SprialDeg:=LREAL_TO_REAL(360.0 * DINT_TO_REAL(i - 1) + Cam_PointAngle * DINT_TO_REAL(j));
				SprialRad:=RAD(fAngle:=SprialDeg );
				
				SprialRadius:= PC_Sprial_a + PC_Sprial_b * SprialRad;
				CamTable_SprialX[CamIndex].dX :=SprialDeg;	
				CamTable_SprialX[CamIndex].dY :=LREAL_TO_REAL(SprialRadius* COS(SprialRad));	
				CamTable_SprialY[CamIndex].dX :=SprialDeg;	
				CamTable_SprialY[CamIndex].dY :=LREAL_TO_REAL(Ellipse_K*SprialRadius * SIN(SprialRad));	
			END_FOR;
		END_FOR;
	ELSE
		FOR i:= 1 TO PC_Sprial_n_Temp DO
			Cam_CyclePointCount := Cam_FisrtCyclePoint + (i -1) * Cam_CycleAddPoint; //本圈的总点数
			Cam_PointAngle:= 360.0 / DINT_TO_REAL(Cam_CyclePointCount); //本圈的每个点的角度
			FOR j:=1 TO Cam_CyclePointCount -1 DO
				//每圈的点数 --- X轴的位置
				Inc(CamIndex);
				SprialDeg:=LREAL_TO_REAL(360.0 * DINT_TO_REAL(i - 1) + Cam_PointAngle * DINT_TO_REAL(j));
				temp:=360.0 * PC_Sprial_n - SprialDeg;
				SprialRad:=RAD(fAngle:=temp);
				SprialRadius:= PC_Sprial_a + PC_Sprial_b * SprialRad;
				//每圈的点数 --- X轴的位置
				CamTable_SprialX[CamIndex].dX :=SprialDeg;	//每个点位角度
				CamTable_SprialX[CamIndex].dY :=LREAL_TO_REAL( PC_Sprial_a +2*3.1416*PC_Sprial_n * PC_Sprial_b  - 
				SprialRadius* COS(SprialRad));	//每个点位角度
				//每圈的点数 --- Y轴的位置
				CamTable_SprialY[CamIndex].dX :=SprialDeg;	//每个点位角度
				CamTable_SprialY[CamIndex].dY :=LREAL_TO_REAL(SprialRadius * SIN(SprialRad));	//每个点位角度
			END_FOR;
		END_FOR;
	END_IF;
	CamTableSave_Step:=2;
END_IF;

IF CamTableSave_Step=2 THEN
	FOR i:=CamIndex + 1 TO 32767 DO
		CamTable_SprialX[i].dX :=0;
		CamTable_SprialX[i].dY :=0;
		CamTable_SprialY[i].dX :=0;
		CamTable_SprialY[i].dY :=0;
	END_FOR;
	CamTableSave_Step:=5;
END_IF;

