 -----------------------------------------------------------------------
 2023.08.11	| V1.0.0.0		 	| KZYK		        | 迭代发布
 2025.05.20	| V2.0.0.0		 	| KZYK		        | 迭代发布

 =============================== END =================================*)
 
 
(******************************************** Main *********************************************)
//请求按钮逻辑
TON_RequestButton(In:=Request, PT:=T#0.5S);
F_RequestButton(Clk:=TON_RequestButton.Q);


//复位按钮逻辑
TON_ResetButton(In:=DoorReset, PT:=T#0S);
F_ResetButton(Clk:=TON_ResetButton.Q);

DoorStatus_T(IN:=LockOut AND NOT  DoorStatus AND NOT Manul_Auto , PT:= T#3S);  //非自情况下，没有锁上，可以自动解锁

(******************************************** 控制逻辑 *********************************************)
IF F_RequestButton.Q
	AND NOT Manul_Auto
	AND Repair
	AND SafeCondition
THEN
	LockOutTemp :=  TRUE;
ELSE
	LockOutTemp  :=  FALSE;
END_IF

IF  NOT LockOutTemp
	AND EmgStop
	AND F_ResetButton.Q
THEN
	LockOut :=  TRUE;
ELSIF NOT EmgStop
	 OR  LockOutTemp
	 OR  DoorStatus_T.Q  //没有锁上1S自动解锁
THEN
	LockOut :=  FALSE;
END_IF


(******************************************** IO输出映射 *********************************************)
//复位按钮灯输出
ResetLight:= ( GetClk_1s()  AND NOT LockOut AND  DoorStatus   ) 
          OR ( GetClk_1s()  AND  LockOut AND  NOT DoorStatus    ) 
          OR ( NOT  DoorStatus  AND NOT LockOut );


//请求按钮灯输出
RequestLight:=	DoorStatus AND LockOut  
						;

