(*======================= 程序简介 ======================================
 @ 名称				:	FB_SecurityDoorLock
 @ 描述				:	安全门解锁功能块
 @ 作者				:	KZYK	
 @ 日期				:	2025.05.20
 @ 版本号			:	V2.0.0.0
 =======================================================================
 @ 说明				:	安全门解锁控制
 @ 
 ================================ 修改履历 ==============================
 修改日期 	| 版本				| 作者		 	| 备注 
 -----------------------------------------------------------------------
 2023.08.11	| V1.0.0.0		 	| KZYK		        | 迭代发布
 2025.05.20	| V2.0.0.0		 	| KZYK		        | 迭代发布

 =============================== END =================================*)
 
 
(******************************************** Main *********************************************)
//请求按钮逻辑
TON_RequestButton(In:=Request, PT:=T#0.5S);
F_RequestButton(Clk:=TON_RequestButton.Q);


//复位按钮逻辑
TON_ResetButton(In:=DoorReset, PT:=T#0S);
F_ResetButton(Clk:=TON_ResetButton.Q);

DoorStatus_T(IN:=LockOut AND NOT  DoorStatus AND NOT Manul_Auto , PT:= T#3S);  //非自情况下，没有锁上，可以自动解锁

(******************************************** 控制逻辑 *********************************************)
IF   F_RequestButton.Q
	AND NOT Manul_Auto
	AND Repair
	AND SafeCondition  
THEN
	LockOutTemp :=  TRUE;
ELSE
	LockOutTemp  :=  FALSE;
END_IF

IF  NOT LockOutTemp
	AND EmgStop
	AND F_ResetButton.Q
THEN
	LockOut :=  TRUE;
ELSIF NOT EmgStop
	 OR  LockOutTemp
	 OR  DoorStatus_T.Q  //没有锁上1S自动解锁
THEN
	LockOut :=  FALSE;
END_IF


(******************************************** IO输出映射 *********************************************)
//复位按钮灯输出
ResetLight:= ( GetClk_1s()  AND NOT LockOut AND  DoorStatus   ) 
          OR ( GetClk_1s()  AND  LockOut AND  NOT DoorStatus    ) 
          OR ( NOT  DoorStatus  AND NOT LockOut );


//请求按钮灯输出
RequestLight:=	DoorStatus AND LockOut  
						;

(*====== 程序简介 ========================================================================================================
 @ 名称				:	DL_EIP
 @ 描述				:	DL_EP1通讯模块转换
 @ 作者				:	DXD	
 @ 日期				:	2020.12.26
 @ 版本号			:	V1.01.00.201226
 @ 配套				:
 @ 限制等级			:	A1.有问题允许改动	
 =========================================================================================================================
 @ 说明				:	用于DL_EP1通讯模块带GT，IL, IX型号基恩士测距传感器的数据转换
 @ 
 ===== 修改履历 ===========================================================================================================
 修改日期	| 版本			| 作者			| 备注 
 -------------------------------------------------------------------------------------------------------------------------
 2020.12.26	| V1.01.00		| DXD	        | 初版发布
 2022.09.10	| V2.01.00		| KZYK 	        | 发布
 2024.05.01	| V3.01.00		| KZYK 	        | 更新

 ======= END ==============================================================================================================*)
(*
1.该功能做DL-EP1通讯模块，EIP通讯标签BTYE转换出实际的测量数值
2.同时附带DL-EP1通讯模块本体报警和传感器放大器报警监控
*)
//基数选择
IF ModeSelect =0 THEN
	BaseData:=1000;
ELSIF ModeSelect =1 THEN
	BaseData:=100;
END_IF;
//输入标签BTYE转换

FOR K:=0 TO 37 DO
	MyByte[K].mByte:=EIP_IN[K];
END_FOR;
//传感器数据无效
MyValueInvalid.mByte[0]:=EIP_IN[10];
MyValueInvalid.mByte[1]:=EIP_IN[11];

//传感器数值转换
FOR K:=1 TO 15 DO
	MyDword[K].mByte[0]:=EIP_IN[48+4*(K-1)];
	MyDword[K].mByte[1]:=EIP_IN[49+4*(K-1)];
	MyDword[K].mByte[2]:=EIP_IN[50+4*(K-1)];
	MyDword[K].mByte[3]:=EIP_IN[51+4*(K-1)];
	IF MyDword[K].mBit[31]
	THEN	    
		Dword_D:=NOT(MyDword[K].mDWord);
		Value[K]:=0-DWORD_TO_REAL(Dword_D)/BaseData;	
	ELSE
	    Value[K]:=DWORD_TO_REAL(MyDword[K].mDWord)/BaseData;
	END_IF;
	//传感器数据无效
	IF MyValueInvalid.mBit[K-1] THEN
		Value[K]:=-99.99;
	END_IF;
END_FOR;

//离焦量清零
MyDword[16].mBit[0]:=ClearMark[0];
MyDword[16].mBit[3]:=ClearMark[1];
EIP_OUT[2]:=MyDword[16].mByte[0];

//实际数值输出
SensorValue1:=Value[1];//1#传感器数值
SensorValue2:=Value[2];//2#传感器数值
SensorValue3:=Value[3];//3#传感器数值
SensorValue4:=Value[4];//4#传感器数值
SensorValue5:=Value[5];//5#传感器数值
SensorValue6:=Value[6];//6#传感器数值
SensorValue7:=Value[7];//7#传感器数值
SensorValue8:=Value[8];//8#传感器数值
SensorValue9:=Value[9];//9#传感器数值
SensorValue10:=Value[10];//10#传感器数值
SensorValue11:=Value[11];//11#传感器数值
SensorValue12:=Value[12];//12#传感器数值
SensorValue13:=Value[13];//13#传感器数值
SensorValue14:=Value[14];//14#传感器数值
SensorValue15:=Value[15];//15#传感器数值

//报警输出
Error[0]:=MyByte[0].mArray[0];//DL-EP1本体报错！
Error[1]:=MyByte[2].mArray[0];//1#传感器放大器报错！
Error[2]:=MyByte[2].mArray[3];//2#传感器放大器报错！

