		//////命令赋值//////
		Cy1.In.Manual_V:=Cy2.In.Manual_V;
		Cy3.In.Manual_V:=Cy2.In.Manual_V;
		Cy4.In.Manual_V:=Cy2.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Cy3.In.Manual_R:=FALSE;
		Cy4.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
		
	500://同步H_Cy1给其他
		//////命令赋值//////
		Cy1.In.Manual_R:=Cy3.In.Manual_R;
		Cy2.In.Manual_R:=Cy3.In.Manual_R;
		Cy4.In.Manual_R:=Cy3.In.Manual_R;
		
		Cy1.In.Manual_V:=FALSE;
		Cy2.In.Manual_V:=FALSE;
		Cy3.In.Manual_V:=FALSE;
		Cy4.In.Manual_V:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
	600://同步H_Cy1给其他
		//////命令赋值//////
		Cy1.In.Manual_V:=Cy3.In.Manual_V;
		Cy2.In.Manual_V:=Cy3.In.Manual_V;
		Cy4.In.Manual_V:=Cy3.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Cy3.In.Manual_R:=FALSE;
		Cy4.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;

	700://同步H_Cy2给其他
		//////命令赋值//////
		Cy1.In.Manual_R:=Cy4.In.Manual_R;
		Cy2.In.Manual_R:=Cy4.In.Manual_R;
		Cy3.In.Manual_R:=Cy4.In.Manual_R;
		
		Cy1.In.Manual_V:=FALSE;
		Cy2.In.Manual_V:=FALSE;
		Cy3.In.Manual_V:=FALSE;
		Cy4.In.Manual_V:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
	800://同步H_Cy2给其他
		//////命令赋值//////
		Cy1.In.Manual_V:=Cy4.In.Manual_V;
		Cy2.In.Manual_V:=Cy4.In.Manual_V;
		Cy3.In.Manual_V:=Cy4.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Cy3.In.Manual_R:=FALSE;
		Cy4.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
	END_CASE;

END_IF;

X1_0_Main();
X1_1_ParameterData();
X1_2_Function();
X1_3_MachineAlarm();
X1_4_Status();
X1_5_MachineControl();
X1_6_关联初始化();
X1_7_电池数据处理();
X1_8_Recipe();
X2_1_OEE();
X2_2_EIP通讯状态();
X2_3_多屏互锁();
X2_4_易损件();
X2_5_Top10报警();
X2_6_电能表();
X2_7_CT计时();
X2_8_FFU();

//============================================================================================================


 
(******************************************	0.	报警清除		******************************************)
IF TRUE THEN
	IF Axis_In.Alarm_Reset OR Status.AlarmReset THEN 
		Clear(Axis_Out.Alarm_Out);
		Clear(Axis_Out.Tips_Out);	//20250616_V2.00.02增加提示信息清除
		Axis_Out.Alarm_LocationNum:=0;
		Axis_Out.OperationTip:="";
	END_IF;
END_IF;

(******************************************	1.	默认参数赋值	******************************************)
IF TRUE THEN
	IF Axis_P.Home_Speed=0 THEN //回原速度
		Axis_P.Home_Speed							:=	10;
	END_IF;
// 	IF Axis_P.Home_AccDec =0 THEN //回原加速度
// 		Axis_P.Home_AccDec							:=	10;
// 	END_IF;
	Axis_P.Home_AccDec							:=	10;
	IF Axis_P.Home_Crawl=0 THEN //回原接近速度
		Axis_P.Home_Crawl							:=	5;
	END_IF;
	IF Axis_P.JOG_Speed=0 THEN //JOG速度
		Axis_P.JOG_Speed							:=	10												;
	END_IF;
	IF Axis_P.JOG_AutoSpeed=0 THEN //JOG Auto速度
		Axis_P.JOG_AutoSpeed						:=	100												;
	END_IF;
	IF Axis_P.JOG_AccDec=0 THEN //JOG加速度
		Axis_P.JOG_AccDec							:=	100												;
	END_IF;
	IF Axis_P.Location_MulVelLimit=0 THEN//手动速度限制
		Axis_P.Location_MulVelLimit					:=	100												;
	END_IF;
	IF Axis_P.Location_SpeedLimit[0]=0 THEN//点位速度限制值
		Axis_P.Location_SpeedLimit[0]				:=	5												;
	END_IF;
	IF Axis_P.Location_SpeedLimit[1]=0 THEN
		Axis_P.Location_SpeedLimit[1]				:=	100												;
	END_IF;
	IF Axis_P.Trq_Limit[0]=0 THEN //扭矩限制值
		Axis_P.Trq_Limit[0]							:=	240												;
	END_IF;
	IF Axis_P.Trq_Limit[1]=0 THEN 
		Axis_P.Trq_Limit[1]							:=	-240											;
	END_IF;
	IF Axis_P.Location_Acc=0 THEN//定位加速度
		Axis_P.Location_Acc							:=	600												;
	END_IF;
	IF Axis_P.Location_Dec=0 THEN//定位减速度
		Axis_P.Location_Dec							:=	1000											;
	END_IF;
//	IF Axis_P.Location_Jerk=0 THEN//定位跃度
//		Axis_P.Location_Jerk						:=	100												;
//	END_IF;	
	IF Axis_P.Stop_Dec=0 THEN //停止减速度
		Axis_P.Stop_Dec								:=	2000											;
	END_IF;
	IF Axis_P.Accuracy[0]=0 THEN //绝对定位精度
		Axis_P.Accuracy[0]							:=	0.25											;
	END_IF;
	IF Axis_P.Accuracy[1]=0 THEN //相对定位精度
		Axis_P.Accuracy[1]							:=	0.25											;
	END_IF;
	IF Axis_P.Accuracy[2]=0 THEN //扭矩定位精度
		Axis_P.Accuracy[2]							:=	0.3												;
	END_IF;
	IF Axis_P.Trq_Ramp=0 THEN//扭矩斜率
		Axis_P.Trq_Ramp								:=	10												;
	END_IF;
	IF Axis_P.Trq_Rated=0 THEN //扭矩额定值
		Axis_P.Trq_Rated							:=	120												;
	END_IF;
	IF Axis_P.Trq_Threshold=0 THEN //扭矩阈值
		Axis_P.Trq_Threshold						:=	130												;//20250325_扭矩报警上限有150改为130										;
	END_IF;
	IF Axis_P.AbortingPower<7 THEN//急停延时断使能
		Axis_P.AbortingPower						:=	7												;
	END_IF;
END_IF;

(******************************************	2.	手动参数限制	******************************************)
IF TRUE THEN
	//汇川软件上位机回原补丁
	Axis_P.Home_Crawl				:=	Axis_P.Home_Speed												;//待汇川软件>1.9.0.1版本后删除 临时补丁
	IF Status.AllowManual THEN
		//手动速度限制
		IF Axis_P.Location_MulVelLimit>500 THEN
			Axis_P.Location_MulVelLimit:=500;
		ELSE 
			Axis_P.Location_MulVelLimit:=Axis_P.Location_MulVelLimit;
		END_IF;//20250325_V5.3.25_手动点动速度上限500mm；
		Axis_P.JOG_Speed			:=LIMIT(REAL#30,Axis_P.JOG_Speed,Axis_P.Location_MulVelLimit);//手动模式下-JOG速度限制
		Axis_P.JOG_AutoSpeed		:=LIMIT(Axis_P.Location_SpeedLimit[0],Axis_P.JOG_AutoSpeed,Axis_P.Location_SpeedLimit[1]);//自动模式下 JOG速度限制
		Axis_P.Location_Speed[0]	:=LIMIT(Axis_P.Location_SpeedLimit[0],Axis_P.Location_Speed[0],Axis_P.Location_SpeedLimit[1]);//手动定位速度限制
		//大范围到位精度限制
		Axis_P.Accuracy[3]		:=LIMIT(REAL#0.05,Axis_P.Accuracy[3],REAL#3)		;
		Axis_P.Accuracy[2]		:=LIMIT(REAL#0.05,Axis_P.Accuracy[2],REAL#1);//20250325_V1.00.00增加扭矩到位限制；
		Axis_P.Accuracy[1]		:=LIMIT(REAL#0.05,Axis_P.Accuracy[1],REAL#1);//20250325_V1.00.00增加相对到位限制；
		Axis_P.Accuracy[0]		:=LIMIT(REAL#0.05,Axis_P.Accuracy[0],REAL#1);//20250325_V1.00.00增加绝对到位限制；
		//定位加速度限制
		Axis_P.Location_Acc							:=	LIMIT(Axis_P.Location_AccDecLimit[0],Axis_P.Location_Acc,Axis_P.Location_AccDecLimit[1]);
		//定位减速度限制
		Axis_P.Location_Dec							:=	LIMIT(Axis_P.Location_AccDecLimit[0],Axis_P.Location_Dec,Axis_P.Location_AccDecLimit[1]);
		//停止速度限制
		IF Axis_P.Stop_Dec<Axis_P.Location_Dec THEN
			Axis_P.Stop_Dec							:=	Axis_P.Location_Dec								;
		END_IF;
		//速度最小值限制
		IF Axis_P.Location_SpeedLimit[0]	>	Axis_P.Location_SpeedLimit[1] THEN 
			Axis_P.Location_SpeedLimit[0]			:=	Axis_P.Location_SpeedLimit[0]	-	Axis_P.Location_SpeedLimit[0];
		END_IF;
		//扭矩最小值限制
		IF Axis_P.Trq_Limit[1]>Axis_P.Trq_Limit[0] THEN 
			Axis_P.Trq_Limit[1]						:=	 Axis_P.Trq_Limit[1]	-	 Axis_P.Trq_Limit[1];
		END_IF;
		//点位数量判断
		SizeOfAry(In:=Axis_P.Location_Postion, Out=>Location_Num);
		IF Axis_P.Location_Num<=0 OR Axis_P.Location_Num>TO_INT(Location_Num) THEN
			Axis_P.Location_Num						:=	TO_INT(Location_Num)							;
		END_IF;
	END_IF;
	
END_IF

(******************************************	3.	轴倍率      	******************************************)
IF TRUE THEN 
	IF Axis_P.VelFactor	= 0 THEN 
		Axis_P.VelFactor							:=	100												;
	END_IF;
	Axis_P.VelFactor								:=	LIMIT(REAL#0.1,Axis_P.VelFactor,REAL#200)		;
END_IF;

(******************************************	4.	沟槽信号映射	******************************************)
IF TRUE THEN
	Axis_Out.OT_P								:=	Axis_Map.In.dwDigitalInputs.1;//正限位开关
	Axis_Out.OT_N								:=	Axis_Map.In.dwDigitalInputs.0;//负限位开关
	Axis_Out.Home_Sw							:=	Axis_Map.In.dwDigitalInputs.2;//原点开关
END_IF;

(******************************************	5.	回原参数提示	******************************************)
IF TRUE THEN
	Axis_P.Flexibility_Back:=LIMIT(REAL#0, Axis_P.Flexibility_Back, REAL#50);//20250325_V1.00.00增加柔性回退距离限制；;
END_IF

(******************************************	6.	使能管理    	******************************************)
IF TRUE THEN
	EmgDelay(IN:=Status.Aborting OR Status.DoorAborting, PT:=TO_TIME(Axis_P.AbortingPower*1000));
	IF  NOT Axis_Map.In.wStatusWord.3	//驱动器无错误
		AND NOT Axis_In.Enable_HMI		//伺服下使能按钮
		AND (NOT EmgDelay.Q OR
			(Status.ModeBit[4] AND EnableDebugHMI AND NOT Status.Aborting))//在C的维修模式下，小屏三段使能开启时，可直接使能
		AND Axis_Map.bCommunication	//通讯OK
		AND NOT EmgDelay.Q
	THEN
		EnableReady								:=	1;
	ELSE
		EnableReady								:=	0;
	END_IF;
	EnableDelay(IN:=EnableReady , PT:=T#0.2S);
END_IF;

(******************************************	6.	回原			******************************************)
IF TRUE THEN
	
	AxisHomeExecute_R(Clk:=(	Axis_In.Home_Auto 	AND Status.AllowAuto 
								OR 	Axis_In.Home_HMI 	AND Status.AllowManual
								OR 	Axis_In.Home_Reset 	AND Status.AllowReset)
								AND NOT HomeOverTime.Q);
	HomeOverTime(In:=(AxisHomeExecute_R.CLK AND Axis_In.Home_SafeCondition) 
								AND NOT AxisHomeWithP.Busy 
								AND NOT AxisHoming.Busy
								AND NOT HomeOverTime.Q
								AND NOT Axis_In.Home_HMI,
								PT:=T#3S);
	

	//脉冲计算
	HomeRatio									:=	DWORD_TO_REAL(Axis_Map.dwRatioTechUnitsDenom)/DINT_TO_REAL(Axis_Map.iRatioTechUnitsNum);
	AxisHomeOffset								:=	Axis_P.Home_Offest								;
	IF 	(	AxisHomeExecute_R.Q
		OR	Axis_In.Home_Auto 	AND Status.AllowAuto 
		OR 	Axis_In.Home_HMI 	AND Status.AllowManual
		OR 	Axis_In.Home_Reset 	AND Status.AllowReset
		)
	//	AND BackStep=0
		AND Axis_Out.Enable_Done			//使能OK
		AND Axis_In.Home_SafeCondition		//回原安全条件满足
		AND Axis_Out.Standstill 			//轴停止中
		AND NOT Axis_Out.Alarm_Out[3]		//回原条件不满足报警
		AND NOT Axis_Out.AlarmSum			//报警汇总
		AND NOT Axis_Map.In.wStatusWord.3	//无轴报警
		AND NOT AxisHomeWithP.Error	 		//Home功能块异常
		AND NOT AxisHoming.Error
	//	AND NOT Homeing	
		AND BackStop=0
		THEN
	//回原参数配置
		AxisHomePar.HomePositionOffset			:=	AXIS_P.Home_SetPos								;
	//原点回原后的设定位置
		AxisHomePar.Compensation				:=	AXIS_P.Home_Offest								;
	//回原方式选择
		CASE Axis_P.Home_Mode OF
		1://附近避让 / 近原点输入 OFF
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.PassHomeSwHomeSwTurn			;
		2://附近避让 / 近原点输入 ON
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.InHomeSwHomeSwTurn				;
		3://近原点输入 OFF
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.PassHomeSwHome					;
		4://近原点输入 ON 
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.InHomeSw						;
		5://极限输入 OFF
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.PassLimitSw						;
		6://附近避让 / 原点输入屏蔽距离
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.HomeSwMaskDistanceHomeSwTurn	;
		7://仅极限输入 
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.OnlyLimit						;
		8://附近避让 / 接触时间
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.HomeSwHoldTimeHomeSwTurn		;
		9://无近原点输入 / 接触原点输入
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.ZeroSw							;
		10://原点预设
			AxisHomePar.HomingMode				:=	HMC_HOMING_MODE.ZeroPositionPreset				;
        END_CASE
	//原点输入信号
		CASE Axis_P.Home_Input OF
			0://Z 相输入
				AxisHomePar.ZeroSignal			:=	HMC_ZERO_SIGNAL.ZPhase							;
			1://使用外部原点输入
				AxisHomePar.ZeroSignal			:=	HMC_ZERO_SIGNAL.ExternalSignal					;
        END_CASE
	//原点开始方向
		CASE Axis_P.Home_StartDir OF
			0://正方向
				AxisHomePar.StartDirection		:=	MC_DIRECTION.positive							;
			1://负方向
				AxisHomePar.StartDirection		:=	MC_DIRECTION.negative							;
        END_CASE
	//原点输入检测方向
		CASE Axis_P.Home_SwDir OF
			0://正方向
				AxisHomePar.EndDirection		:=	MC_DIRECTION.positive							;
			1://负方向
				AxisHomePar.EndDirection		:=	MC_DIRECTION.negative							;
        END_CASE
	//正方向极限输入时动作
		AxisHomePar.PosLimitMode				:=	HMC_LIMIT_REVERSE_MODE.RevImmediateStop			;
	//负方向极限输入时动作
		AxisHomePar.PosLimitMode				:=	HMC_LIMIT_REVERSE_MODE.RevImmediateStop			;
	//回原速度
		AxisHomePar.Vel							:=	Axis_P.Home_Speed								;
	//原点接近速度
		AxisHomePar.ApproachVel					:=	Axis_P.Home_Crawl								;
	//原点返回加速度
		AxisHomePar.Acc							:=	Axis_P.Home_AccDec								;
	//原点返回减速度
		AxisHomePar.Dec							:=	Axis_P.Home_AccDec								;
	//原点返回跃度
		AxisHomePar.Jerk						:=	Axis_P.Home_AccDec/0.1							;
	//原点补偿速度
		AxisHomePar.CompensationVel				:=	1000											;
	
	//	Axis_In.Home_HMI						:=	0												;
		Axis_In.Home_Auto						:=	0												;
		Axis_In.Home_Reset						:=	0												;
		Axis_Out.Homed							:=	0												;
		Axis_Out.Home_Done						:=	0												;
		AxisHomeExecute							:=	BackStop=0										;
	ELSIF AxisHomeWithP.Busy OR  AxisHoming.Busy OR Axis_Map.nAxisState=7 OR Axis_Map.nAxisState=2 THEN //回原过程 或者 静止 或者 停止中
		AxisHomeExecute							:=	0												;
	END_IF;
END_IF;

(******************************************	7.	JOG-			******************************************)
IF TRUE THEN 
	IF 	((Axis_In.JOG_Auto[0] AND Status.AllowAuto)
		OR(Axis_In.JOG_HMI[0] AND (Status.AllowManual OR Axis_Out.Alarm_Out[7]))
		OR(Axis_In.JOG_Reset[0]	AND Status.AllowReset))
		AND Axis_P.InchingDistance=0
		AND BackStep=0
		AND Axis_Out.Enable_Done			//使能OK
		AND Axis_In.JOG_SafeCondition[0]	//JOG-安全条件满足
		AND(	NOT Axis_Out.AlarmSum 		//报警汇总
			OR	Axis_Out.Alarm_Out[7]		//发生正方向异常时候 触发负方向运动
			)
		AND BackStep=0
		AND NOT Axis_Map.In.wStatusWord.3	//无轴报警
	THEN 
		NEGPos									:=  NOT	JogOverTime.Q								;
	ELSE
		NEGPos									:=	0												;
	END_IF;
END_IF;
JogOverTime(In:=(AxisJOG.JogForward OR AxisJOG.JogBackward) AND Axis_Out.Standstill, PT:=T#200MS);//超时动作防呆	
(******************************************	8.	JOG+			******************************************)
IF TRUE THEN 
	IF 	(	(Axis_In.JOG_Auto[1] AND Status.AllowAuto)
		OR	(Axis_In.JOG_HMI[1] AND (Status.AllowManual OR Axis_Out.Alarm_Out[8]))
		OR	(Axis_In.JOG_Reset[1] AND Status.AllowReset))
		AND Axis_P.InchingDistance=0
		AND BackStep=0
		AND Axis_Out.Enable_Done			//使能OK
		AND Axis_In.JOG_SafeCondition[1]	//JOG+安全条件满足
		AND(	NOT Axis_Out.AlarmSum		//报警汇总
			OR	Axis_Out.Alarm_Out[8])		//发生负方向异常时候 触发正方向运动
		AND BackStep=0
		AND NOT Axis_Map.In.wStatusWord.3	//无轴报警
	THEN 
		JOGPos									:=  NOT	JogOverTime.Q								;
	ELSE
		JOGPos									:=	0												;
	END_IF;
END_IF;

(******************************************	9.	Func			******************************************)
IF TRUE THEN 
	IF Status.AllowManual THEN
		FOR i[15]:=1 TO Axis_P.Location_Num-1 BY 1 DO
			//按钮互锁
			IF Axis_In.Location_Select_HMI[i[15]] AND i[15] <> PosNum   THEN 
				PosNum								:=	i[15];
				Clear(Axis_In.Location_Select_HMI);
				Axis_In.Location_Select_HMI[PosNum]	:=	1;
			END_IF;
			//点位速度参数选择
			IF NOT Axis_P.Location_SpeedSwitch THEN 
				Axis_P.Location_Speed[i[15]]		:=	Axis_P.Location_Speed[1];
			END_IF;
			//点位示教		
			IF Axis_In.Location_PosSave_HMI AND Axis_In.Location_Select_HMI[i[15]] AND Axis_Out.Homed THEN 
				i[14]									 :=	i[15]							;
				IF 		TO_REAL(Axis_Map.fActPosition) > Axis_P.Location_Postion[i[15]] +5
					OR	TO_REAL(Axis_Map.fActPosition) < Axis_P.Location_Postion[i[15]] -5
					THEN 
					//超出范围弹框
					Status.AxisLimitMsg				:=	1;
				ELSE
				    Clear(i[14]);
					Clear(Status.AxisLimitMsg);
					Clear(Status.AxisLimitCmd);
					Axis_P.Location_Postion[i[15]]	:=	TO_REAL(Axis_Map.fActPosition);
					Axis_In.Location_PosSave_HMI	:=	0;
				END_IF;
				IF Status.AxisLimitMsg AND Status.AxisLimitCmd[0] THEN 		//弹框+确认变更
					Clear(Status.AxisLimitMsg);
					Clear(Status.AxisLimitCmd);
					Axis_P.Location_Postion[i[14]]	:=	TO_REAL(Axis_Map.fActPosition);
					Clear(i[14]);
					Axis_In.Location_PosSave_HMI	:=	0;
				ELSIF Status.AxisLimitMsg AND Status.AxisLimitCmd[1] THEN	//弹框+取消变更	
					Clear(Status.AxisLimitMsg);
					Clear(Status.AxisLimitCmd);
					Clear(i[14]);
					Axis_In.Location_PosSave_HMI	:=	0;		
				END_IF;
			END_IF;
			//点位速度
			IF Axis_P.Location_Speed[i[15]]=0 THEN //点位速度
				Axis_P.Location_Speed[i[15]]		:=10;
			END_IF;
			IF Axis_P.Location_Speed[0]=0 THEN
				Axis_P.Location_Speed[0]			:=100;
			END_IF;
			//点位速度限制
			Axis_P.Location_Speed[i[15]]			:=	LIMIT(Axis_P.Location_SpeedLimit[0],Axis_P.Location_Speed[i[15]],Axis_P.Location_SpeedLimit[1]);
		END_FOR;
	END_IF;
	
	MsgTipOver(IN:=Status.AxisLimitMsg, PT:=T#10S);
	IF MsgTipOver.Q THEN 								//超时
		Clear(Status.AxisLimitMsg);
		Clear(Status.AxisLimitCmd);
		Clear(i[14]);
		Axis_In.Location_PosSave_HMI	:=	0;	
	END_IF;
	
END_IF;

(******************************************	10.	Empty			******************************************)
IF (AxisMoveAbs[0].Done OR AxisMoveRel.Done) AND  Axis_Out.Standstill THEN
	Axis_In.Location_Auto[Axis_Out.Location_FeedBackNum]:=0;
	Axis_In.Location_Reset[Axis_Out.Location_FeedBackNum]:=0;
END_IF

(******************************************	11.	多重指令处理	******************************************)
IF TRUE THEN
	ExecuteNum[0]	:=	0	;ExecuteNum[1]	:=	0	;ExecuteNum[2]	:=	0	;
	ExecuteInOut[0]	:=	0	;ExecuteInOut[1]:=	0	;ExecuteInOut[2]:=	0	;
	IF Status.AllowAuto THEN
		ArySearch(In:=Axis_In.Location_Auto[0] , Size:=INT_TO_UINT(Axis_P.Location_Num) , Key:=Have , InOutPos:=ExecuteInOut[0] , Num=>ExecuteNum[0] );
	ELSIF Status.AllowReset OR Status.AllowManual THEN
		ArySearch(In:=Axis_In.Location_Reset[0] , Size:=INT_TO_UINT(Axis_P.Location_Num) , Key:=Have , InOutPos:=ExecuteInOut[1] , Num=>ExecuteNum[1] );
		ArySearch(In:=Axis_In.Location_Select_HMI[0] , Size:=INT_TO_UINT(Axis_P.Location_Num) , Key:=Have , InOutPos:=ExecuteInOut[2] , Num=>ExecuteNum[2] );
	END_IF
	IF ExecuteNum[0]+ExecuteNum[1]+ExecuteNum[2]>1 THEN 
		Axis_Out.Tips_Out[7] := TRUE; //20250325_V1.00.00增加多重触发报警提示；
		Clear(Axis_In.Location_Auto);
		Clear(Axis_In.Location_Reset);
		Clear(Axis_In.Location_Select_HMI);
	END_IF;			
END_IF

(******************************************	12.	绝对定位_缓存   ******************************************)
IF TRUE THEN	
	//提取速度、位置
	IF 	( 	Status.AllowAuto
		AND Axis_In.Location_Auto[ExecuteInOut[0]]
		OR	Status.AllowReset
		AND Axis_In.Location_Reset[ExecuteInOut[1]]
		OR	Status.AllowManual
		AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI
		)
		AND NOT Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
		AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=0  THEN
		IF 	(	Status.AllowManual OR Status.AllowReset)
			AND NOT Status.AllowAuto THEN 
			AbsPosition[0]					:=	Axis_P.Location_Postion[ExecuteInOut[1]+ExecuteInOut[2]];
			AbsVelocity[0]					:=	Axis_P.JOG_Speed								;
		ELSIF 	Status.AllowAuto 
			AND NOT Status.AllowManual
			AND NOT Status.AllowReset THEN
			AbsPosition[0]					:=	Axis_P.Location_Postion[ExecuteInOut[0]]				;
			AbsVelocity[0]					:=	SEL(Axis_P.Location_SpeedSwitch,Axis_P.Location_Speed[1],Axis_P.Location_Speed[ExecuteInOut[0]]);
		END_IF;
		Axis_Out.Location_FeedBackNum		:=	UINT_TO_INT(ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2])		;
	END_IF;
	//绝对定位_缓存触发
	AbsExecute[0]	:=	ExecuteNum[0]+ExecuteNum[1]+ExecuteNum[2]<=1									//检索触发数量为1
					AND BackStep=0
					AND Axis_Out.Homed																	//有回原标记
					//AND((Axis_Map.nAxisState=3 OR Axis_Map.nAxisState=5 )OR FunSimulation)			//轴静止中 或者 连续运动中(扭矩)
					//AND NOT AxisMoveAbs[0].Busy
					AND NOT Axis_Out.AlarmSum															//无轴报警
					AND	(Axis_Map.In.wStatusWord.1 OR Axis_Map.nAxisState>1)													//轴准备好
					AND NOT Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]			//绝对定位模式为缓存模式
					AND NOT Axis_Out.PosDone[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]			//没有到位信号
					AND Axis_In.Location_SafeCondition[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]	//安全条件满足	
					AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=0	//点位定位模式为绝对定位
					AND (
							(	Status.AllowAuto AND Axis_In.Location_Auto[ExecuteInOut[0]]	)
						OR	( 	Status.AllowReset AND Axis_In.Location_Reset[ExecuteInOut[1]] )
						OR	(	Status.AllowManual AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI)
						);
END_IF;

(******************************************	13.	绝对定位_连续   ******************************************)
IF TRUE THEN
	//提取速度、位置
	IF 	( 	Status.AllowAuto
		AND Axis_In.Location_Auto[ExecuteInOut[0]]
		OR	Status.AllowReset
		AND Axis_In.Location_Reset[ExecuteInOut[1]]
		OR	Status.AllowManual
		AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI
		)
		AND Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
		AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=0  THEN
		IF 	(	Status.AllowManual OR Status.AllowReset)
			AND NOT Status.AllowAuto THEN 
			AbsPosition[1]					:=	Axis_P.Location_Postion[ExecuteInOut[1]+ExecuteInOut[2]];
			AbsVelocity[1]					:=	Axis_P.JOG_Speed								;
		ELSIF 	Status.AllowAuto 
			AND NOT Status.AllowManual
			AND NOT Status.AllowReset THEN
			AbsPosition[1]					:=	Axis_P.Location_Postion[ExecuteInOut[0]]				;
			AbsVelocity[1]					:=	SEL(Axis_P.Location_SpeedSwitch,Axis_P.Location_Speed[1],Axis_P.Location_Speed[ExecuteInOut[0]]);
		END_IF;
		Axis_Out.Location_FeedBackNum		:=	UINT_TO_INT(ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2])			;
	END_IF;
	//绝对定位_连续触发
	AbsExecute[1]	:=	ExecuteNum[0]+ExecuteNum[1]+ExecuteNum[2]<=1									//检索触发数量为1
					AND BackStep=0
					AND Axis_Out.Homed																	//有回原标记
					//AND Axis_Motor.nAxisState=4															//轴定位执行中
					//AND NOT AxisMoveAbs[1].Busy
					AND NOT Axis_Out.AlarmSum															//无轴报警
					AND	(Axis_Map.In.wStatusWord.1	OR Axis_Map.nAxisState>1)													//轴准备好
					AND Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]				//绝对定位模式为连续模式
					AND NOT Axis_Out.PosDone[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]			//没有到位信号
					AND Axis_In.Location_SafeCondition[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]	//安全条件满足	
					AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=0	//点位定位模式为绝对定位
					AND (
							(	Status.AllowAuto AND Axis_In.Location_Auto[ExecuteInOut[0]]	)
						OR	( 	Status.AllowReset AND Axis_In.Location_Reset[ExecuteInOut[1]] )
						OR	(	Status.AllowManual AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI)
						);
END_IF;

(******************************************	14.	相对定位    	******************************************)
IF TRUE THEN 
	//检索被触发的位
	IF 	(	Status.AllowAuto
		AND Axis_In.Location_Auto[ExecuteInOut[0]]
		OR	Status.AllowReset
		AND Axis_In.Location_Reset[ExecuteInOut[1]]
		OR	Status.AllowManual
		AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI
		)
		AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=1 
		AND Axis_Map.nAxisState=3
		AND NOT AxisMoveRel.Busy 
		THEN
		RelCyclMark	:=	0	;
		RelOldPos	:=	0	;
		RelResult	:=	0	;
		//手动、复位定位数据缓存
		IF 	(	Status.AllowManual OR Status.AllowReset)
			AND NOT Status.AllowAuto THEN 
			RelDistance						:=	Axis_P.Location_Postion[ExecuteInOut[1]+ExecuteInOut[2]];
			RelVelocity						:=	Axis_P.Location_Speed[0]								;
		ELSIF 	Status.AllowAuto 
			AND NOT Status.AllowManual
			AND NOT Status.AllowReset THEN
			RelDistance						:=	Axis_P.Location_Postion[ExecuteInOut[0]]				;
			RelVelocity						:=	SEL(Axis_P.Location_SpeedSwitch,Axis_P.Location_Speed[1],Axis_P.Location_Speed[ExecuteInOut[0]]);
		END_IF;
		IF RelOldPos = 0 THEN 
			RelOldPos						:=	TO_REAL(Axis_Map.fActPosition)				;
		END_IF;
		//线性模式
		IF Axis_Map.iMovementType=1 THEN 	
			RelResult						:=	TO_REAL(Axis_Map.fActPosition)	+	RelDistance;
		//旋转模式
		ELSIF	Axis_Map.iMovementType=0 THEN 	
			IF 	Axis_Out.CurrentPos+RelDistance	>=Axis_Map.fSWLimitPositive THEN //正向超360
				RelCyclMark					:=	1;
				RelResult					:=(	TO_REAL(Axis_Map.fActPosition)	+	RelDistance) -TO_REAL(Axis_Map.fSWLimitPositive);
			ELSIF  Axis_Out.CurrentPos+RelDistance	<= Axis_Map.fSWLimitNegative  THEN //反向超0
				RelCyclMark					:=	1;
				RelResult					:=(	TO_REAL(Axis_Map.fActPosition)	+	RelDistance) +TO_REAL(Axis_Map.fSWLimitPositive);
			ELSIF  Axis_Out.CurrentPos+RelDistance	>= Axis_Map.fSWLimitNegative AND Axis_Out.CurrentPos+RelDistance	<= Axis_Map.fSWLimitPositive THEN//0-360之间
			 	RelResult					:=(	TO_REAL(Axis_Map.fActPosition)	+	RelDistance);
			END_IF;
			IF ABS(RelResult-Axis_Map.fSWLimitPositive)<Axis_P.Accuracy[0] THEN
          		  RelResult		:=0;
          		  RelCyclMark   :=0;
            END_IF;
		END_IF;
		Axis_Out.Location_FeedBackNum		:=	UINT_TO_INT(ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2])			;
	END_IF;
	//相对触发
	RelExecute	:=	ExecuteNum[0]+ExecuteNum[1]+ExecuteNum[2]<=1									//检索数量为1
				AND BackStep=0
				AND	Axis_Out.Homed																	//有回原标记
				AND Axis_Map.nAxisState=3															//轴静止中
				AND (NOT AxisMoveRel.Busy OR FunSimulation)
				AND NOT Axis_Out.AlarmSum															//无轴报警
				AND	(Axis_Map.In.wStatusWord.1	OR Axis_Map.nAxisState>1)													//轴准备好
				AND Axis_Out.Location_FeedBackNum <> 0
				//AND NOT Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
				//AND NOT Axis_Out.PosDone[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
				AND Axis_In.Location_SafeCondition[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
				AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=1
				AND (
						(	Status.AllowAuto AND Axis_In.Location_Auto[ExecuteInOut[0]]	)
					OR	( 	Status.AllowReset AND Axis_In.Location_Reset[ExecuteInOut[1]] )
					OR	(	Status.AllowManual AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI)
					);
END_IF;

(******************************************	15.	寸动      		******************************************)
IF TRUE THEN 
	IF Axis_P.InchingDistance	>	10 THEN 
		Axis_P.InchingDistance					:=	10												;
	END_IF;
	IF Axis_P.InchingDistance	<	0 THEN 
		Axis_P.InchingDistance					:=	1												;
	END_IF;
	IF Status.AllowAuto THEN 
		Axis_P.InchingDistance					:=	0												;
	END_IF;
	InchR[0](Clk:=(	Axis_In.JOG_Auto[0] 	AND Status.AllowAuto
				OR	Axis_In.JOG_HMI[0] 		AND Status.AllowManual
				OR	Axis_In.JOG_Reset[0]	AND Status.AllowReset
				)
				AND Axis_P.InchingDistance<>0);
	IF 	InchR[0].Q
		AND Axis_In.JOG_SafeCondition[0]	//JOG-安全条件满足
		AND BackStep=0
		AND Axis_Out.Standstill 			//轴停止中
		AND NOT Axis_Out.AlarmSum			//报警汇总
		AND NOT Axis_Map.In.wStatusWord.3	//无轴报警
	THEN
		TargetInch								:=	Axis_P.InchingDistance*-1						;
		InchNeg									:=	1												;
	ELSE
		InchNeg									:=	0												;
	END_IF;
	
	InchR[1](Clk:=(	Axis_In.JOG_Auto[1] 	AND Status.AllowAuto
				OR	Axis_In.JOG_HMI[1] 		AND Status.AllowManual
				OR	Axis_In.JOG_Reset[1]	AND Status.AllowReset
				)
				AND Axis_P.InchingDistance<>0);
	IF 	InchR[1].Q
		AND Axis_In.JOG_SafeCondition[1]	//JOG+安全条件满足
		AND BackStep=0
		AND Axis_Out.Standstill 			//轴停止中
		AND NOT Axis_Out.AlarmSum			//报警汇总
		AND NOT Axis_Map.In.wStatusWord.3	//无轴报警
	THEN
		TargetInch								:=	Axis_P.InchingDistance							;
		InchPos									:=	1												;
	ELSE
		InchPos									:=	0												;
	END_IF;
END_IF;

(******************************************	16.	扭矩定位    	******************************************)
IF TRUE THEN 
	//提取位置、速度
	IF ( 	Status.AllowAuto
		AND Axis_In.Location_Auto[ExecuteInOut[0]]
		OR	Status.AllowReset
		AND Axis_In.Location_Reset[ExecuteInOut[1]]
		OR	Status.AllowManual
		AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI
		)
		AND NOT Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
		AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=2 THEN
		IF (	Status.AllowManual OR Status.AllowReset)
			AND NOT Status.AllowAuto THEN 
			TargetTorque					:=	Axis_P.Location_Postion[ExecuteInOut[1]+ExecuteInOut[2]]	;
			TorVelocity						:=	SEL(Axis_P.Location_SpeedSwitch,Axis_P.Location_Speed[1],Axis_P.Location_Speed[ExecuteInOut[1]+ExecuteInOut[2]]);
		ELSIF 	Status.AllowAuto 
			AND NOT Status.AllowManual
			AND NOT Status.AllowReset THEN
			TargetTorque					:=	Axis_P.Location_Postion[ExecuteInOut[0]]					;
			TorVelocity						:=	SEL(Axis_P.Location_SpeedSwitch,Axis_P.Location_Speed[1],Axis_P.Location_Speed[ExecuteInOut[0]]);
		END_IF;
		Axis_Out.Location_FeedBackNum		:=	UINT_TO_INT(ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2])			;
	END_IF;
	//触发扭矩定位
	TorExecute	:=	ExecuteNum[0]+ExecuteNum[1]+ExecuteNum[2]<=1
				AND BackStep=0
				AND 	Axis_Out.Homed
				AND(	Axis_Map.nAxisState=3 
					OR		Axis_Map.nAxisState=5
						AND NOT JOGPos AND NOT NEGPos AND NOT InchPos AND NOT InchNeg AND NOT AbsExecute[0] AND NOT AbsExecute[1] AND NOT RelExecute
					)
				AND NOT AxisMoveTor.Busy
				AND NOT Axis_Out.AlarmSum
				AND (Axis_Map.In.wStatusWord.1	OR Axis_Map.nAxisState>1)
				AND NOT Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
				AND NOT Axis_Out.PosDone[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
				AND Axis_In.Location_SafeCondition[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
				AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=2
				AND (
						(	Status.AllowAuto AND Axis_In.Location_Auto[ExecuteInOut[0]]	)
					OR	( 	Status.AllowReset AND Axis_In.Location_Reset[ExecuteInOut[1]] )
					OR	(	Status.AllowManual AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI)
					);
END_IF;

(******************************************	17.	速度定位    	******************************************)
IF TRUE THEN 
	//提取速度
	IF 	( 	Status.AllowAuto
		AND Axis_In.Location_Auto[ExecuteInOut[0]]
		OR	Status.AllowReset
		AND Axis_In.Location_Reset[ExecuteInOut[1]]
		OR	Status.AllowManual
		AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI
		)
		AND NOT Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
		AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=3 THEN
		IF 	(	Status.AllowManual OR Status.AllowReset)
			AND NOT Status.AllowAuto THEN 
			TargetVel						:=	Axis_P.Location_Speed[ExecuteInOut[1]+ExecuteInOut[2]];
		ELSIF 	Status.AllowAuto 
			AND NOT Status.AllowManual
			AND NOT Status.AllowReset THEN
			TargetVel						:=	Axis_P.Location_Speed[ExecuteInOut[0]]					;
		END_IF;
		Axis_Out.Location_FeedBackNum		:=	UINT_TO_INT(ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2])			;
	END_IF;
	VelExecute	:=		ExecuteNum[0]+ExecuteNum[1]+ExecuteNum[2]<=1
					AND BackStep=0
					AND Axis_Out.Homed
					AND Axis_Map.nAxisState=3
					AND NOT AxisMoveVel.Busy
					AND NOT Axis_Out.AlarmSum
					AND	(Axis_Map.In.wStatusWord.1 OR Axis_Map.nAxisState>1)
					AND NOT Axis_In.AbsModel[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
					AND NOT Axis_Out.PosDone[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
					AND Axis_In.Location_SafeCondition[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]
					AND Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]=3
					AND (
							(	Status.AllowAuto AND Axis_In.Location_Auto[ExecuteInOut[0]]	)
						OR	( 	Status.AllowReset AND Axis_In.Location_Reset[ExecuteInOut[1]] )
						OR	(	Status.AllowManual AND Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI)
						);
END_IF;
(******************************************	17.	扭矩阈值一键取值    	******************************************)
IF TRUE THEN
	//扭矩阈值一键取值
	//20250325_V5.3.25_增加扭矩一键取值（运行10次的每一次最大值的平均值的1.3倍）（只能执行绝对定位）；
	CTU_TrqMax_Abs(CU:=Status.AllowAuto AND AbsExecute[0] AND Axis_Out.PosDone[1], Reset:=Axis_Out.TipSum OR Axis_Out.AlarmSum OR NOT Axis_In.Trq_ClickValue, PV:=21);//自动模式下，触发计数
	R_TrqMax(Clk:=CTU_TrqMax_Abs.Q);//一键取值结束上升沿
	IF R_TrqMax.Q THEN
		Axis_In.Trq_ClickValue:=FALSE;
		AryMean(In:=Trq_Max_Value[1] , Size:=10 , Out:=fTempMean );
		Axis_P.Trq_Threshold:=fTempMean*1.3;
	END_IF;//流程结束，输出值，复位一键取值
	IF Axis_In.Trq_ClickValue THEN
		CASE CTU_TrqMax_Abs.CV OF
			1..2:IF Trq_Max_Value[1]<Axis_Out.CurrentTrq THEN Trq_Max_Value[1]:=Axis_Out.CurrentTrq;END_IF;//同一个位置触发2次为一个周期，防止一次未带电心一次带电芯；
			3..4:IF Trq_Max_Value[2]<Axis_Out.CurrentTrq THEN Trq_Max_Value[2]:=Axis_Out.CurrentTrq;END_IF;
			5..6:IF Trq_Max_Value[3]<Axis_Out.CurrentTrq THEN Trq_Max_Value[3]:=Axis_Out.CurrentTrq;END_IF;
			7..8:IF Trq_Max_Value[4]<Axis_Out.CurrentTrq THEN Trq_Max_Value[4]:=Axis_Out.CurrentTrq;END_IF;
			9..10:IF Trq_Max_Value[5]<Axis_Out.CurrentTrq THEN Trq_Max_Value[5]:=Axis_Out.CurrentTrq;END_IF;
			11..12:IF Trq_Max_Value[6]<Axis_Out.CurrentTrq THEN Trq_Max_Value[6]:=Axis_Out.CurrentTrq;END_IF;
			13..14:IF Trq_Max_Value[7]<Axis_Out.CurrentTrq THEN Trq_Max_Value[7]:=Axis_Out.CurrentTrq;END_IF;
			15..16:IF Trq_Max_Value[8]<Axis_Out.CurrentTrq THEN Trq_Max_Value[8]:=Axis_Out.CurrentTrq;END_IF;
			17..18:IF Trq_Max_Value[9]<Axis_Out.CurrentTrq THEN Trq_Max_Value[9]:=Axis_Out.CurrentTrq;END_IF;
			19..20:IF Trq_Max_Value[10]<Axis_Out.CurrentTrq THEN Trq_Max_Value[10]:=Axis_Out.CurrentTrq;END_IF;
			END_CASE;
	ELSE
		Clear(In:=Trq_Max_Value );
	END_IF;
END_IF;

(******************************************	18.	状态切换复位	******************************************)
IF TRUE THEN
	//设备运行中状态切换复位外部所有触发信号 相对定位不复位
	Status_F[0](Clk:=Status.StatusBit[4] OR Status.AllowAuto);	//自动运行下降沿
	Status_F[1](Clk:=(Status.AllowManual OR Status.AllowReset)	//手动允许条件
					AND Axis_In.Location_Move_HMI				//触摸屏输入定位移动
					AND Axis_Map.nAxisState<>3				//轴不在静止中	
					AND (AxisMoveTor.Busy OR AxisMoveVel.Busy) 	//轴扭矩或速度功能块执行中
				);//
	Status_F[2](Clk:=Status.AllowReset);//复位允许下降沿
	Status_F[3](Clk:=Status.AllowManual);//手动允许下降沿
	Status_R[0](Clk:=Status.StatusBit[6]);//暂停中上升沿
	Status_R[1](Clk:=Status.StatusBit[7]);//停止中上升沿
	Status_R[2](Clk:=Axis_Out.AlarmSum AND NOT Axis_Out.Alarm_Out[9] AND Axis_Map.nAxisState<>1);//轴报警上升沿
	Status_R[3](CLK:= );//HMI掉线信号
	
	IF Status.AllowManual THEN
		IF AxisMoveRel.Done THEN 
			Axis_In.Location_Move_HMI:=0;//相对定位到位后，自动复位一次触发。
		END_IF;
		Status_F[4](Clk:=Axis_In.Location_Move_HMI OR Axis_In.Home_HMI OR Axis_In.JOG_HMI[0] OR Axis_In.JOG_HMI[1]);//20241214:C公司特殊要求，定位移动按下动作，松开停止。//20250616_V2.00.02增加寸动松手停止
	END_IF;
	
	IF 	(	Status_F[0].Q AND(NOT AxisMoveRel.Busy OR AxisMoveRel.Busy AND NOT Axis_In.Location_SafeCondition[Axis_Out.Location_FeedBackNum]) )
		OR	Status_R[0].Q
		OR	Status_R[1].Q
		OR	Status_R[2].Q
		THEN
		Clear(JOGPos);
		Clear(NEGPos);
		Clear(InchPos);
		Clear(InchNeg);
		Clear(AbsExecute);
		Clear(RelExecute);
		Clear(VelExecute);
		Clear(TorExecute);
		Clear(AxisHomeExecute);
		Clear(Axis_In.Home_Auto);
		Clear(Axis_In.Home_HMI);
		Clear(Axis_In.Home_Reset);
		Clear(Axis_In.JOG_Auto);
		Clear(Axis_In.JOG_HMI);
		Clear(Axis_In.JOG_Reset);
		Clear(Axis_In.Location_Auto);
		Clear(Axis_In.Location_Reset);
		Clear(Axis_In.Location_Select_HMI);
		Clear(Axis_Out.Location_FeedBackNum);
		Clear(RelOldPosNum);
	END_IF;
	//不同模式 复位其他模式触发信号
	IF Status.AllowAuto THEN
		Clear(Axis_In.Location_Select_HMI);
		Clear(Axis_In.Location_Reset);
	ELSIF Status.AllowManual OR Status.AllowReset THEN
		Clear(Axis_In.Location_Auto);
	ELSIF 	NOT Status.AllowAuto 
		AND NOT	Status.AllowReset
		AND NOT Status.AllowManual
	THEN
		Clear(Axis_In.Location_Auto);
		Clear(Axis_In.Location_Reset);
		Clear(Axis_In.Location_Select_HMI);
	END_IF;
	//HMI输入掉线信号沿 复位手动信号
	IF Status_R[3].Q THEN 
		Clear(Axis_In.Location_Select_HMI);
		Clear(Axis_In.JOG_HMI);
		Clear(JOGPos);
		Clear(NEGPos);
	END_IF;
	//定位移动后清除位置选择按钮
	IF Axis_In.Location_Move_HMI THEN
		Clear(Axis_In.Location_Select_HMI);
	END_IF
	
END_IF;
	
(******************************************	19.	柔性回弹		******************************************)
IF Axis_In.FallbackEnabled THEN	
	Back_R(Clk:=Axis_In.Crash_Trigger AND NOT InchPos AND NOT  JOGPos
		OR(Axis_In.Crash_Trigger AND(InchPos OR JOGPos)));//轴柔性回弹触发上升沿
	IF Back_R.Q AND BackStep=0 AND Axis_In.Crash_Safe //
	THEN 
		BackStep								:=	10												;
	ELSIF 	Back_R.Q 
		AND(	
				NOT Axis_In.Crash_Safe 
			OR Axis_Map.nAxisState=1
			OR Axis_Map.nAxisState=2
			OR Axis_Map.nAxisState=3
			OR Axis_Map.nAxisState=7
			OR InchPos 
			OR JOGPos
			)
		OR(
			(
				BackAbs 
			OR	BackRel
			)
			AND NOT Axis_In.Crash_Safe
			)	
			THEN 
			BackAbs								:=	0												;
			BackRel								:=	0												;
			Axis_Out.Alarm_Out[6]				:=	1												;
	END_IF;
	BackStopCheck(IN:=BackStep<>0 , PT:=T#10S );
	CASE BackStep OF 
		0:
			BackAbs								:=	0												;
			BackRel								:=	0												;
			BackStop							:=	0												;
			
		10:
			Clear(Axis_In.Home_Auto);
			Clear(Axis_In.Home_HMI);
			Clear(Axis_In.Home_Reset);
			Clear(Axis_In.JOG_Auto);
			Clear(Axis_In.JOG_HMI);
			Clear(Axis_In.JOG_Reset);
			Clear(Axis_In.Location_Auto);
			Clear(Axis_In.Location_Reset);
			Clear(Axis_In.Location_Select_HMI);
			Clear(AxisHomeExecute);
			Clear(JOGPos);
			Clear(NEGPos);
			Clear(InchPos);
			Clear(InchNeg);
			Clear(AbsExecute);
			Clear(RelExecute);
			Clear(TorExecute);
			Clear(VelExecute);
			BackStop							:=	1												;
			IF AxisStop.Done THEN 
				BackStop						:=	0												;
				BackStep						:=	20												;
			END_IF;
		
		20://柔性退回方式选择
		
		    IF Status.ModeBit[3] OR Status.ModeBit[4] OR Status.AllowReset THEN //手动或者复位模式，回退一定位置
				//Axis_In.Location_ModeSelect[1]:=1;
				BackStep:=30;
			ELSIF Status.ModeBit[1] AND  ExecuteNum[3]=0 THEN  //自动模式，并且没有到达定位点，回退安全位置
				//Axis_In.Location_ModeSelect[1]:=0;
				BackStep:=40;
			ELSIF Status.ModeBit[1] AND  ExecuteNum[3]<>0 THEN //自动模式，并且到达定位点，停止不动，报警；
				//Axis_In.Location_ModeSelect[1]:=0;
				BackStep:=50;
			END_IF;	
		
// 			IF NOT Axis_Out.Homed THEN
// 			//	Axis_In.Location_ModeSelect[1]	:=	1												;
// 				BackStep						:=	30												;
// 			ELSIF Axis_Out.Homed AND NOT Axis_Out.PosDone[1] THEN
// 			//	Axis_In.Location_ModeSelect[1]	:=	0												;
// 				BackStep						:=	40												;
// 			ELSIF Axis_Out.Homed AND Axis_Out.PosDone[1] THEN
// 			//	Axis_In.Location_ModeSelect[1]	:=	0												;
// 				BackStep						:=	50												;
// 			END_IF;
		
		30://相对定位回退
			RelDistance			:=-Axis_P.Flexibility_Back;//20250325_V5.3.25_回退距离又100改为设定值；
			RelVelocity			:=SEL(Status.ModeBit[3] OR Status.ModeBit[4],Axis_P.Location_Speed[1],REAL#80);
			IF Axis_Map.iMovementType=1		//当前轴为线性模式
			THEN 
				RelResult						:=	Axis_Out.CurrentPos+RelDistance					;
			END_IF;
			BackRel								:=	1												;
			IF AxisMoveRel.Busy THEN 
				BackStep						:=	31												;
			END_IF;
		31:
			IF AxisMoveRel.Done 
				OR Axis_Out.PosDone[1] 
				OR NOT Axis_In.Location_SafeCondition[1] THEN 
				BackRel							:=	0												;
				BackStep						:=	50												;
			END_IF;
		
		40://绝对定位回退
		//	AbsPosition[0]						:=	Axis_P.Location_Postion[1]						;
			AbsPosition[0]						:=	Axis_P.AbsPosBackVal;
			AbsVelocity[0]						:=	SEL(Status.ModeBit[3] OR Status.ModeBit[4],Axis_P.Location_Speed[1],REAL#80);
			BackAbs								:=	1												;
			IF AxisMoveAbs[0].Busy	THEN
				BackStep						:=	41												;
			END_IF;
		
		41:
			IF 		AxisMoveAbs[0].Done
				OR	Axis_Out.PosDone[1] 
				OR 	NOT Axis_In.Location_SafeCondition[1] THEN 
				BackAbs							:=	0												;
				BackStep						:=	50												;
			END_IF;
		
		50://触发报警
			Axis_Out.Alarm_Out[6]				:=	1												;
			Axis_In.Location_ModeSelect[1]		:=	0												;
			BackAbs								:=	0												;
			BackRel								:=	0												;
			BackStep							:=	0												;
	END_CASE;
	IF BackStopCheck.Q OR Axis_Out.Alarm_Out[6] THEN 
		Axis_Out.Alarm_Out[6]					:=	1												;
		BackAbs									:=	0												;
		BackRel									:=	0												;
		BackStop								:=	0												;
		BackStep								:=	0												;
	END_IF;
	
	ELSE
	Axis_Out.Alarm_Out[6]:=	0;
	BackAbs:=0;
	BackRel:=0;
	BackStop:=0;
	BackStep:=0	;	
	
END_IF;

(******************************************	20.	FB实例			******************************************)
IF NOT FunSimulation THEN
	
	//轴使能
	AxisPower(
		Axis				:= Axis_Map 	, 
		Enable				:= TRUE			, 
		bRegulatorOn		:= EnableDelay.Q AND NOT AXIS_IN.Enable_HMI , 
		bDriveStart			:= EnableDelay.Q AND NOT AXIS_IN.Enable_HMI , 
		);	
		
	//轴基础回原
	AxisHoming(
		Axis 				:= Axis_Map,
		Execute 			:= AxisHomeExecute AND NOT Axis_In.Home_Mode,
		Done 				=> Axis_Out.Cmd_Done[6],
		Busy 				=> Axis_Out.Cmd_Busy[6])
							;
				
	//轴回原
	AxisHomeWithP(
		Axis 				:= Axis_Map 	, 
		HomingParameter		:= AxisHomePar	, 
		Execute				:= AxisHomeExecute AND Axis_In.Home_Mode,
		Done				=> Axis_Out.Cmd_Done[0], 
		Busy				=> Axis_Out.Cmd_Busy[0], 
		CommandAborted		=> HomeAborted, 
		Error				=> HomeError, 
		ErrorID				=> HomeErrorID
		);

	//增加位置置零指令
	
	


// 		保持Homed
// 		IF( AxisHome.Done OR Axis_In.EncoderSelect OR FunSimulation )AND NOT AxisHome.Busy THEN
// 			Axis_Out.Homed	:=	1;
// 		ELSIF((Status.StatusBit[7] OR Status.StatusBit[8])AND NOT Axis_In.EncoderSelect)OR AxisHome.Busy THEN
// 			Axis_Out.Homed	:=	0;
// 		END_IF;
//		一个周期 HomeDone
//		Axis_Out.Home_Done	:=	AxisHome.Done;	

	//保持Homed
	IF (AxisHomeWithP.Done AND Axis_In.Home_Mode OR Axis_In.EncoderSelect OR (FunSimulation)) AND NOT AxisHomeWithP.Busy 
	THEN
		Axis_Out.Homed := 1;
	ELSIF
		(AxisHoming.Done AND NOT Axis_In.Home_Mode OR Axis_In.EncoderSelect OR (FunSimulation)) AND NOT AxisHoming.Busy 
	THEN
		Axis_Out.Homed := 1;//20250325_V5.3.25_基础回原；
	ELSIF
		((Status.StatusBit[7] OR NOT Axis_Map.bCommunication )AND NOT Axis_In.EncoderSelect) OR AxisHomeWithP.Busy OR AxisHoming.Busy    //OR Status.StatusBit[8]
	THEN
		Axis_Out.Homed := 0;
	END_IF;
	//一个周期
	Axis_Out.Home_Done := (AxisHomeWithP.Done AND Axis_In.Home_Mode) OR (AxisHoming.Done AND NOT Axis_In.Home_Mode);


		IF AxisHomeWithP.Done 
			OR AxisHoming.Done
		THEN
			Clear(AxisHomeExecute);
			Clear(Axis_In.Home_Auto);
			Clear(Axis_In.Home_HMI);
			Clear(Axis_In.Home_Reset);
		END_IF

	//轴JOG
	AxisJOG(
		Axis            	:= Axis_Map , 
		JogForward			:= JOGPos AND NOT Axis_In.Crash_Trigger , 
		JogBackward			:= NEGPos , 
		Velocity			:= SEL(Status.AllowAuto,Axis_P.JOG_Speed,Axis_P.JOG_AutoSpeed), 
		Acceleration		:= Axis_P.JOG_AccDec , 
		Deceleration		:= Axis_P.JOG_AccDec ,
		Busy				=> Axis_Out.Cmd_Busy[7], 
		Error				=> , 
		ErrorId				=> );	

	//轴停止
	AxisStop(
		Axis            :=Axis_Map , 
		Execute			:=((	
						  ( Axis_In.Stop_Auto	AND Status.AllowAuto)
						OR(	Axis_In.Stop_HMI	AND Status.AllowManual)
						OR(	Axis_In.Stop_Reset	AND Status.AllowReset)
						OR	Status.Aborting		//急停
						OR((Status.StatusBit[6] OR Status_F[0].Q)	//暂停
							AND NOT Axis_Out.Alarm_Out[8] AND NOT JOGPos
							AND NOT Axis_Out.Alarm_Out[7] AND NOT NEGPos
							AND	Axis_In.Location_ModeSelect[Axis_Out.Location_FeedBackNum]<>1 
							AND BackStep=0
							)
						OR	NOT Axis_Out.Alarm_Out[7] AND Axis_Map.In.dwDigitalInputs.1 AND NOT Axis_Out.Cmd_Busy[0] AND NOT Axis_Out.Cmd_Busy[6]
						OR 	NOT Axis_Out.Alarm_Out[8] AND Axis_Map.In.dwDigitalInputs.0 AND NOT Axis_Out.Cmd_Busy[0] AND NOT Axis_Out.Cmd_Busy[6]
						OR	Status.StatusBit[7] //停止中
						OR	BackStop			//回弹
						OR	Status_R[2].Q		//轴报警上升沿
						OR	((Status_F[1].Q		//速度、扭矩+手动情况下的下降沿停止信号
						OR  Status_F[4].Q       //手动下，定位移动下降沿，触发轴停止。
						OR 	TorStop)
						AND BackStep=0) //未执行柔性回退的动作时，停止手动下降沿停止轴。执行退回则继续执行回退；//20250325_V5.3.25
						)
						AND NOT Axis_In.Stop_Shield//屏蔽停止
						AND NOT AxisStop.Busy),
		Deceleration	:=	Axis_P.Stop_Dec, 
		Jerk			:=	Axis_P.Location_Jerk 
						);
			
		IF 	(	Axis_In.Stop_Auto AND Status.AllowAuto
			OR	Axis_In.Stop_Reset AND Status.AllowReset) 
			AND AxisStop.Done
			THEN
			Axis_In.Stop_Auto:=0;
			Axis_In.Stop_Reset:=0;
		END_IF
					
	//绝对定位_缓存
	CASE Axis_In.AbsDirection OF
		0:AxisMoveAbs[0].Direction	:=	MC_DIRECTION.positive	;//正向移动
		1:AxisMoveAbs[0].Direction	:=	MC_DIRECTION.shortest	;//择近
		2:AxisMoveAbs[0].Direction	:=	MC_DIRECTION.negative	;//反向移动
		3:AxisMoveAbs[0].Direction	:=	MC_DIRECTION.current	;//按当前方向移动
		4:AxisMoveAbs[0].Direction	:=	MC_DIRECTION.fastest	;//无方向指定
    END_CASE	
	
	AxisMoveAbs[0](
		Axis            := Axis_Map , 
		Execute			:=(AbsExecute[0] OR BackAbs)AND  Axis_Map.byRealControllerMode=3,
		Position		:= AbsPosition[0] , 
		Velocity		:=(AbsVelocity[0]*(SEL(Axis_P.VelFactorCtrlSwatch,VelFactor, Axis_P.VelFactor)/100)), 
		Acceleration	:= Axis_P.Location_Acc , 
		Deceleration	:= Axis_P.Location_Dec , 
		Jerk			:= Axis_P.Location_Jerk , 
	//	Direction		:= MC_DIRECTION.shortest , 
		BufferMode		:= 5 , 
		Done			=> Axis_Out.Cmd_Done[1] , 
		Busy			=> Axis_Out.Cmd_Busy[1] , 
		Active			=> , 
		CommandAborted	=> , 
		Error			=> , 
		ErrorID			=> );
		
	//绝对定位_连续
	AxisMoveAbs[1](
		Axis            := Axis_Map , 
		Execute			:= AbsExecute[1] AND  Axis_Map.byRealControllerMode=3,
		Position		:= AbsPosition[1] , 
		Velocity		:=(AbsVelocity[1]*(SEL(Axis_P.VelFactorCtrlSwatch,VelFactor, Axis_P.VelFactor)/100)), 
		Acceleration	:= Axis_P.Location_Acc , 
		Deceleration	:= Axis_P.Location_Dec , 
		Jerk			:= Axis_P.Location_Jerk , 
		Direction		:= MC_DIRECTION.shortest , 
		BufferMode		:= 0 , 
		Done			=> Axis_Out.Cmd_Done[5] , 
		Busy			=> Axis_Out.Cmd_Busy[5] , 
		Active			=> , 
		CommandAborted	=> , 
		Error			=> , 
		ErrorID			=> );
		
	//相对定位
	AxisMoveRel(
		Axis			:= Axis_Map , 
		Execute			:=(RelExecute OR BackRel)AND  Axis_Map.byRealControllerMode=3, 
		Distance		:= RelDistance , 
		Velocity		:=(RelVelocity*(SEL(Axis_P.VelFactorCtrlSwatch,VelFactor, Axis_P.VelFactor)/100)), 
		Acceleration	:= Axis_P.Location_Acc , 
		Deceleration	:= Axis_P.Location_Dec , 
		Jerk			:= Axis_P.Location_Jerk , 
		BufferMode		:= , 
		Done			=> Axis_Out.Cmd_Done[2] , 
		Busy			=> Axis_Out.Cmd_Busy[2] , 
		Active			=> , 
		CommandAborted	=> , 
		Error			=> , 
		ErrorID			=> );
		IF AxisMoveRel.Busy AND RelOldPosNum=0 THEN
			RelOldPosNum:=INT_TO_UINT(Axis_Out.Location_FeedBackNum);
		END_IF
		
	IF AxisMoveRel.Busy THEN 
		RelOldPosNum:=INT_TO_UINT(Axis_Out.Location_FeedBackNum);
	END_IF;
	
	//扭矩控制	
	AxisMoveTor(
		Axis			:= Axis_Map , 
		Execute			:= TorExecute AND Axis_Map.byRealControllerMode=1 , 
		Torque			:= TargetTorque , 
		TorqueRamp		:= TorqueRampPara , 
 		Velocity		:=(TorVelocity*(SEL(Axis_P.VelFactorCtrlSwatch,VelFactor, Axis_P.VelFactor)/100)), 
		InTorque		=> Axis_Out.Cmd_Done[3] , 
		Busy			=> Axis_Out.Cmd_Busy[3] , 
		CommandAborted	=> , 
		Error			=> , 
		ErrorID			=> );
	
	//寸动
	AxisMovelnch(
		Axis			:= Axis_Map , 
		Execute			:= InchPos OR InchNeg , 
		Distance		:= TargetInch , 
		Velocity		:= Axis_P.JOG_Speed , 
		Acceleration	:= Axis_P.JOG_AccDec , 
		Deceleration	:= Axis_P.JOG_AccDec , 
		Jerk			:= , 
		BufferMode		:= , 
		Done			=> , 
		Busy			=> , 
		Active			=> , 
		CommandAborted	=> , 
		Error			=> , 
		ErrorID			=> );
		
		IF AxisMovelnch.Done THEN 
			Clear(Axis_In.JOG_Auto);
			Clear(Axis_In.JOG_HMI);
			Clear(Axis_In.JOG_Reset);
		END_IF;	
		
	//速度控制
	AxisMoveVel(
		Axis			:= Axis_Map , 
		Execute			:= VelExecute , 
		Velocity		:=(TargetVel*(SEL(Axis_P.VelFactorCtrlSwatch,VelFactor, Axis_P.VelFactor)/100)), 
		Acceleration	:= Axis_P.Location_Acc , 
		Deceleration	:= Axis_P.Location_Dec , 
		Jerk			:= , 
		Direction		:= , 
		BufferMode		:= , 
		InVelocity		=> Axis_Out.Cmd_Done[4] , 
		Busy			=> Axis_Out.Cmd_Busy[4] , 
		Active			=> , 
		CommandAborted	=> , 
		Error			=> , 
		ErrorID			=> );	
		
	//轴报警复位
	//AxisReset_MC(Axis:= Axis_Map, Execute:= Axis_In.Alarm_Reset OR Status.AlarmReset );//轴通信错误复位流程，以HMC Reset为例，在调用HMCReset之前调用一次MC Reset
	IF Axis_In.Alarm_Reset 
		OR  Status.AlarmReset
	THEN
		pwState := ADR(AxisReset_MC.wState);//内部指针变量
		pwState^ := 100;
	END_IF
	//AxisReset_MC(Axis:= Axis_Map, Execute:=FALSE);
	//xbool:=Axis_In.Alarm_Reset OR  Status.AlarmReset ;
	AxisReset_MC(Axis:=Axis_Map,
		Execute:=xbool OR  Axis_In.Alarm_Reset OR  Status.AlarmReset ,//xbool,//
		Done=> ,
		Busy=> , 
		Error=> , 
		ErrorID=> );
	AxisReset(
		ETC_Slave:= Axis_Drive,   
		Execute:= Axis_In.Alarm_Reset OR  Status.AlarmReset, 
		TimeOut:= , 
		Mode:= , 
		Done=> , 
		Busy=> , 
		Error=> , 
		ErrorID=> 
		);
		
END_IF;
(******************************************	21.	定位完成   		******************************************)
IF TRUE THEN 

		FOR i[8]:=0 TO Axis_P.Location_Num-1 BY 1 DO 
					 //绝对定位大范围到位
   		 Axis_Out.LargeScalePosDone[i[8]]	:=	ABS(Axis_Map.fActPosition	-	Axis_P.Location_Postion[i[8]])<Axis_P.Accuracy[3] 
                                                                		AND Axis_Out.Homed 
																		;	
			//绝对
			IF Axis_In.Location_ModeSelect[i[8]] =0 THEN
				Axis_Out.PosDone[i[8]]		:=(		(ABS(Axis_Map.fActPosition-Axis_P.Location_Postion[i[8]])<Axis_P.Accuracy[0] OR (Axis_Out.PosDone[i[8]] AND NOT FunSimulation)) )
												AND (ABS(Axis_Map.fActPosition-Axis_P.Location_Postion[i[8]])<Axis_P.Accuracy[0] OR FunSimulation)
												AND Axis_Out.Homed 
												AND(Axis_Map.nAxisState=3 OR Axis_Map.nAxisState=2)
												AND NOT AxisMoveAbs[0].Busy AND NOT AxisMoveAbs[1].Busy
												;
			IF Axis_Out.PosDone[i[8]] AND NOT Axis_In.InPlaceSensor[i[8]] THEN
			   ;//Axis_Out.Alarm_Out[10]:=TRUE;//20250616_V2.00.02增加传感器对比报警；
			END_IF;
			END_IF;
			//复位大范围到位
			IF Axis_Out.LargeScalePosDone[i[8]] AND Axis_Out.Location_FeedBackNum<>i[8] AND NOT Axis_Out.PosDone[i[8]] THEN 
				Axis_Out.LargeScalePosDone[i[8]]					:=	0		;
			END_IF;
				
			//相对
			IF Axis_In.Location_ModeSelect[i[8]]=1 THEN
				Axis_Out.PosDone[i[8]]		:= (
												NOT RelCyclMark //线性
												AND ABS(RelResult-RelOldPos-Axis_P.Location_Postion[i[8]])<Axis_P.Accuracy[0]
												AND ABS(Axis_Map.fActPosition       -        RelResult)<Axis_P.Accuracy[0]
												
												OR RelCyclMark AND Axis_P.Location_Postion[i[8]]>0//旋转正向
                                  			  	AND ABS(Axis_Map.fSWLimitPositive-RelOldPos + RelResult-Axis_P.Location_Postion[i[8]])<Axis_P.Accuracy[0]
												AND ABS(Axis_Map.fActPosition               - RelResult)<Axis_P.Accuracy[0]
									
												OR RelCyclMark AND Axis_P.Location_Postion[i[8]]<0//旋转反向
                                    			AND ABS(Axis_Map.fSWLimitPositive+(Axis_P.Location_Postion[i[8]]+(RelOldPos-Axis_Map.fSWLimitNegative))-RelResult)<Axis_P.Accuracy[0]
												AND ABS(Axis_Map.fActPosition        -        RelResult)<Axis_P.Accuracy[0]
                                   				)
                                   			    AND(Axis_Map.nAxisState=3 OR Axis_Map.nAxisState=2)
                                    			AND Axis_Out.Homed
                                    			AND NOT AxisMoveRel.Busy												
												;
				IF AxisMoveRel.Busy THEN//清除触发
					Axis_In.Location_Auto[i[8]]:=0;
					Axis_In.Location_Reset[i[8]]:=0;
				END_IF;
				IF Axis_Out.PosDone[i[8]] AND NOT Axis_In.InPlaceSensor[i[8]] THEN
			       ;//Axis_Out.Alarm_Out[10]:=TRUE;//20250616_V2.00.02增加传感器对比报警；
			    END_IF;
			END_IF;
	
			//扭矩
			IF Axis_In.Location_ModeSelect[i[8]]=2 THEN
				TrqTON(IN:=ABS(Axis_Map.fActTorque*0.1-Axis_P.Location_Postion[Axis_Out.Location_FeedBackNum])<Axis_P.Accuracy[2] 
							AND Axis_Out.Homed , 
							PT:=T#100MS);
				Axis_Out.PosDone[i[8]]	:=	ABS(Axis_Out.CurrentTrq	-	Axis_P.Location_Postion[i[8]])<Axis_P.Accuracy[2] 
											AND Axis_Out.Homed 
											AND(TrqTON.Q OR Axis_Out.PosDone[i[8]])
											;
			END_IF;
			//定位计时
			IF TRUE THEN 
				PosDoneR(Clk:=Axis_Out.PosDone[Axis_Out.Location_FeedBackNum]);
				IF PosDoneR.Q THEN	
					Axis_Out.Location_Timer					:=TIME_TO_REAL(PosTimer.ET)/1000;//使用Ton精确到小数点后三位
				END_IF;
				PosTimer(In:=Axis_Out.Location_FeedBackNum>0, PT:=T#60S);
			END_IF;		
	
		// 清除外部定位执行
			IF Axis_Out.PosDone[i[8]] THEN
				RelOldPosNum											:=	0							;
				Axis_In.Location_Auto[i[8]]								:=	0							;
				Axis_In.Location_Reset[i[8]]							:=	0							;
			END_IF;
		//定位控制模式切换
			TorStop:=0;
			IF TorExecute THEN
				fb_setcontrolMode.nControllerMode:=SMC_torque;
				fb_setcontrolMode.bExecute:= Axis_Map.byRealControllerMode<>1							;
			ELSIF
				ExecuteNum[0]+ExecuteNum[1]+ExecuteNum[2]=0                   
				AND  Axis_In.Location_ModeSelect[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]<>2
				AND (Axis_Map.byRealControllerMode=1
				OR  (Status.AllowManual OR Status.AllowReset))	//手动允许条件
					AND NOT Axis_In.Location_Move_HMI			//触摸屏输入定位移动
					AND Axis_Map.nAxisState<>1				//轴不在静止中	
					AND Axis_Map.nAxisState<>3
					AND  Axis_Map.byRealControllerMode=1
				THEN
							
				fb_setcontrolMode.nControllerMode:=SMC_position;
//				fb_setcontrolMode.bExecute:= Axis_Motor.byRealControllerMode<>3 AND TorStop AND AxisStop.Done		;
                fb_setcontrolMode.bExecute:= Axis_Map.byRealControllerMode<>3 ;
// 				fb_setcontrolMode.bExecute:= Axis_Motor.byRealControllerMode<>3  AND TON_50ms时钟.Q	AND  NOT TorStop	;
// 			ELSE
// 				TorStop:=0;
			END_IF;

			fb_setcontrolMode( Axis:= Axis_Map );	
            IF fb_setcontrolMode.bDone AND Axis_Map.byRealControllerMode=3 THEN
					TorStop:=1;	
			END_IF
			
			IF fb_setcontrolMode.bExecute AND Axis_Map.byRealControllerMode = fb_setcontrolMode.nControllerMode OR AxisStop.Done THEN
				fb_setcontrolMode.bExecute:=0;
			END_IF
			IF  Axis_Map.byRealControllerMode=1 THEN
						;
			ELSE
				Axis_Map.fmaxprofileVelocity	:=	Axis_P.Home_TorMaxVel								;	
			END_IF	
		END_FOR;	
		//定位计时
		IF TRUE THEN 
			PosTimer(In:=Axis_Out.Location_FeedBackNum>0, PT:=T#60S);
			PosDoneR(Clk:=Axis_Out.PosDone[Axis_Out.Location_FeedBackNum] AND Axis_Out.Location_FeedBackNum <>0);
			IF PosDoneR.Q AND TIME_TO_REAL(PosTimer.ET)>0 THEN
				Axis_Out.Location_Timer:=TIME_TO_REAL(PosTimer.ET)/1000;//使用Ton精确到小数点后三位
			END_IF;
		END_IF;
		//清除点编号
		ClearNum(IN:= Axis_Out.PosDone[Axis_Out.Location_FeedBackNum] AND Axis_Out.Location_FeedBackNum<>0, PT:= T#10MS);
		IF  ClearNum.Q THEN
			Axis_Out.Location_FeedBackNum							:=	0							;
		END_IF;	
END_IF;

(******************************************	22.	暂停对比		******************************************)
IF TRUE THEN
	CASE ClashMarkStep OF 
		0://进入模式 记录冲突值（报警后工位需要动作完停止时，状态机必须设置开启禁用赞停）
			ClashMark_R(Clk:=((Status.ModeBit[3] OR Status.ModeBit[4])  AND Status.StatusBit[3]  //在初始化或手动模式下,进入复位完成状态
							OR (Status.ModeBit[1] OR Status.ModeBit[2])  AND Status.StatusBit[6]) //在生成或维护模式下，进入暂停状态
							AND ABS(Axis_Map.fActVelocity)<0.5								//轴速度趋近于0
						);
			IF ClashMark_R.Q THEN 
				Axis_Out.ClashStopPos			:=	Axis_Out.CurrentPos								;
				ClashMarkStep					:=	1												;
			END_IF;
		
		1://对比输出
			IF 		Axis_Map.iMovementType=1 THEN //线性
				Axis_Out.Tips_Out[5]:=ABS(Axis_Out.ClashStopPos-Axis_Out.CurrentPos)>Axis_P.Accuracy[0];
				Contrast_Alarm:=ABS(Axis_Out.ClashStopPos-Axis_Out.CurrentPos)>Axis_P.Accuracy[0];
			ELSIF	Axis_Map.iMovementType=0 THEN //旋转
				IF 	(	Axis_Out.ClashStopPos	>	Axis_Map.fActPosition-Axis_P.Accuracy[0]
					OR	Axis_Out.ClashStopPos	<	Axis_Map.fActPosition+Axis_P.Accuracy[0]
					)
					AND(	RelResult	>	Axis_Map.fActPosition+Axis_P.Accuracy[0]
						OR	RelResult	<	Axis_Map.fActPosition-Axis_P.Accuracy[0]
						)
					AND Axis_Map.nAxisState=3
					THEN
					Axis_Out.Tips_Out[5]:=0;
					Contrast_Alarm:=0;
				ELSE
					Axis_Out.Tips_Out[5]:=ABS(Axis_Out.ClashStopPos-Axis_Out.CurrentPos)>Axis_P.Accuracy[0];
					Contrast_Alarm:=ABS(Axis_Out.ClashStopPos-Axis_Out.CurrentPos)>Axis_P.Accuracy[0];
				END_IF;
			END_IF;
			PauseComparFiltering(IN:= Status.StatusBit[1]
									OR	Status.StatusBit[4]
									OR	Status.StatusBit[5]
									OR	Status.StatusBit[7]
									OR	Status.StatusBit[8] , PT:=T#0S);
			IF 	PauseComparFiltering.Q	
			THEN
				ClashMarkStep					:=	2												;
			END_IF;
		
		
		2://结束对比 复位输出
			Axis_Out.Tips_Out[5]:=0;
			ClashMarkStep:=0;
			Contrast_Alarm:=0;
	END_CASE;
END_IF;

(******************************************	23.	Out信号输出		******************************************)
IF TRUE THEN
	Axis_Out.Alarm									:=	Axis_Map.In.wStatusWord.3 OR Axis_Map.nAxisState=1 OR NOT Axis_Map.bCommunication;//驱动器错误输入
	Axis_Out.Ready									:=	Axis_Map.In.wStatusWord.0						;//伺服准备好
	Axis_Out.CurrentPos								:=	LREAL_TO_REAL(Axis_Map.fActPosition)			;//轴实际位置反馈
	Axis_Out.CurrentVel								:=	ABS(LREAL_TO_REAL(Axis_Map.fActVelocity))		;//轴实际速度反馈
	Axis_Out.CurrentTrq								:=	ABS(LREAL_TO_REAL(Axis_Map.fActTorque))*0.1		;//轴实际扭矩反馈
	
	TorMaxDelay(IN:=ABS(Axis_Out.CurrentTrq)	>	Axis_P.Trq_Max, PT:=T#100MS);
	IF TorMaxDelay.Q THEN 
		Axis_P.Trq_Max								:=	Axis_Out.CurrentTrq								;//扭矩最大值记录
	END_IF;
	IF Axis_In.MaxTrqClear_HMI THEN 
		Axis_P.Trq_Max								:=	0												;
		Axis_In.MaxTrqClear_HMI						:=	0												;
	END_IF;
	
	Axis_Out.Enable_Done							:=	Axis_Map.In.wStatusWord.2	 OR Axis_Map.nAxisState>1					;//使能OK
	Axis_Out.Standstill								:=	Axis_Map.nAxisState=3							
														OR Axis_Map.nAxisState=2 
														OR Axis_Map.nAxisState=1						;//轴静止中
		
	Axis_Out.Mcode									:=	Axis_Drive.ErrorCode							;//轴监控代码
	Axis_Out.Ecode									:=	DWORD_TO_WORD(Axis_Map.dwErrorID)				;//轴轻度故障代码
	IF Axis_Map.nAxisState=0 THEN 
		Axis_Out.Status								:=	1												;//轴无效
	ELSIF Axis_Map.nAxisState=3 THEN 
		Axis_Out.Status								:=	2												;//停止中
	ELSIF Axis_Map.nAxisState=4 THEN 
		Axis_Out.Status								:=	3												;//定位动作中
	ELSIF Axis_Map.nAxisState=5 THEN 
		Axis_Out.Status								:=	4												;//连续动作中
	ELSIF Axis_Map.nAxisState=6 THEN 
		Axis_Out.Status								:=	5												;//同步动作中
	ELSIF Axis_Map.nAxisState=7 THEN 
		Axis_Out.Status								:=	6												;//原点复位中
	ELSIF Axis_Map.nAxisState=2 THEN 
		Axis_Out.Status								:=	7												;//减速停止中
	ELSIF Axis_Map.nAxisState=1 THEN 
		Axis_Out.Status								:=	8												;//错误减速停止中
	END_IF;
		
	Axis_Out.Tips_Out[0]							:=	NOT Axis_Map.In.wStatusWord.2 AND  Axis_Map.nAxisState<=1					;//未使能提示
	Axis_Out.Tips_Out[1]							:=	(Axis_Map.In.wStatusWord.2 OR  Axis_Map.nAxisState>1) AND NOT Axis_Out.Homed AND NOT AxisHomeWithP.Busy AND NOT AxisHoming.Busy;//未回原提示
	Axis_Out.Tips_Out[2]							:=	Axis_Map.In.wStatusWord.3 OR Axis_Map.nAxisState=1 OR NOT Axis_Map.bCommunication;//驱动器警告输入
	Axis_Out.Tips_Out[3]							:=	Axis_Out.CurrentTrq	> Axis_P.Trq_Rated			;//轴扭矩超过额定值提示
	Axis_Out.Tips_Out[4]							:= 	NOT Axis_Out.Standstill AND VelFactor<0.1		;//轴当前速度倍率小于0.1
	
	//Axis_Out.Tips_Out[5]:暂停对比异常提示
	
	IF Axis_P.Home_Speed	<	Axis_P.Home_Crawl THEN	
		Axis_P.Home_Speed	:=	Axis_P.Home_Crawl	;			//20250325_V5.3.25_回原接近速度过快提示
		Axis_Out.Tips_Out[6]:=	TRUE;
	END_IF;
	
	//Axis_Out.Tips_Out[7]:多重触发报警提示

	IF (Axis_In.JOG_Auto[0] AND Status.AllowAuto
		OR (Axis_In.JOG_HMI[0] OR Axis_In.JOG_HMI[1])AND(Status.AllowManual OR Axis_Out.Alarm_Out[7]		
			)
		OR Axis_In.JOG_Reset[0] AND Status.AllowReset ) AND NOT Axis_In.JOG_SafeCondition[0]	
	THEN
		Axis_Out.Tips_Out[8]					:=	TRUE	;	//20250325_V5.3.25_增加手动安全条件不满足报提示；
	END_IF; 


	IF NOT Axis_Map.bCommunication AND NOT FunSimulation THEN
		Axis_Out.Alarm_Out[0]					:=	1												;//驱动器通讯故障
	END_IF
	IF Axis_Map.In.wStatusWord.3 THEN
		Axis_Out.Alarm_Out[1]					:=	1												;//轴故障
	END_IF
	
	HomeSafeFiltering(In:=(	Axis_In.Home_Auto
		OR	Axis_In.Home_HMI
		OR	Axis_In.Home_Reset
		OR	Axis_Map.nAxisState=7)
		AND NOT Axis_In.Home_SafeCondition, PT:=T#1S);	//2S滤波，超1秒报警
	IF	HomeSafeFiltering.Q THEN 
		Axis_Out.Alarm_Out[2]						:=	1												;//回原安全条件不满足
	END_IF;	
	
	IF Axis_Out.Homed OR AxisHomeWithP.Error OR AxisHoming.Error THEN //回原执行完成后 复位外部home执行指令
		AxisHomeExecute		:=	0	;
		Axis_In.Home_Auto	:=	0	;
		//Axis_In.Home_HMI	:=	0	;
		Axis_In.Home_Reset	:=	0	;
	END_IF;
	
	//轴运动安全条件不满足报警及复位触发信号
	AutoNoSafe(In := Axis_In.Location_Auto[ExecuteInOut[0]] AND NOT Axis_In.Location_SafeCondition[ExecuteInOut[0]] AND Status.AllowAuto AND ExecuteNum[0]>0, PT := T#5S);//自动定位触发，未动作。等5S
	ResetNoSafe(In := Axis_In.Location_Reset[ExecuteInOut[1]] AND NOT Axis_In.Location_SafeCondition[ExecuteInOut[1]] AND Status.AllowReset AND ExecuteNum[1]>0, PT := T#5S);//复位定位触发，未动作。等5S
	SafeConAlarmDelay(In :=(	Axis_Out.Location_FeedBackNum<>0 AND NOT Axis_Out.Standstill AND NOT Axis_In.Location_SafeCondition[Axis_Out.Location_FeedBackNum]),PT:=T#200MS);//动作中闪断滤波
	//触发计时
	IF
		(AutoNoSafe.Q)
		OR( ResetNoSafe.Q)
		OR SafeConAlarmDelay.Q
		OR( Axis_In.Location_Select_HMI[ExecuteInOut[2]] AND Axis_In.Location_Move_HMI AND NOT Axis_In.Location_SafeCondition[ExecuteInOut[2]] AND Status.AllowManual AND ExecuteNum[2]>0 )//手动定位不满足时立马报
	THEN
		NEGPos																			:=	0												;
		JOGPos																			:=	0												;
		Axis_In.Location_Auto[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]			:=	0												;
		Axis_In.Location_Reset[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]			:=	0												;
		Axis_In.Location_Select_HMI[ExecuteInOut[0]+ExecuteInOut[1]+ExecuteInOut[2]]	:=	0												;
		Axis_Out.Alarm_LocationNum														:=	Axis_Out.Location_FeedBackNum					;
		Axis_Out.Location_FeedBackNum													:=	0												;
		Axis_Out.Alarm_Out[4]															:=	1;//轴运动安全条件不满足
	END_IF;

	TorMaxError(IN:=TO_REAL(ABS(Axis_Map.fActTorque))*0.1>Axis_P.Trq_Threshold AND Axis_Map.byRealControllerMode=3, PT:=T#100MS, Q=> , ET=> );
	IF TorMaxError.Q THEN 
		Axis_Out.Alarm_Out[5]					:=	1												;//扭矩值超过阈值警告
	END_IF;
	IF (Axis_Out.OT_P OR(Axis_P.Soft_PotLimit<>0 AND Axis_Out.CurrentPos>Axis_P.Soft_PotLimit)) AND Axis_Map.nAxisState<>7 THEN
		Axis_Out.Alarm_Out[7]					:=	1												;//正限位开关
	END_IF;
	IF (Axis_Out.OT_N OR(Axis_P.Soft_NotLlimit<>0 AND Axis_Out.CurrentPos<Axis_P.Soft_NotLlimit)) AND Axis_Map.nAxisState<>7 THEN
		Axis_Out.Alarm_Out[8]					:=	1												;//负限位开关
	END_IF;
	IF NOT Axis_Map.In.wStatusWord.2 AND (Status.ModeBit[1] OR Status.StatusBit[2]) THEN
		Axis_Out.Alarm_Out[9]					:=	 Axis_Map.nAxisState<=1												;//轴未使能报警
	END_IF;
END_IF;

Axis_P.Soft_PotLimit := 0 ;
Axis_P.Soft_NotLlimit := 0 ;


CTU_TrqAlarm(CU:=Axis_Out.Alarm_Out[5],Reset:=Axis_In.Trq_AlarmClear);//20250325_V1.00.00增加扭矩报警次数记录；
Axis_Out.Trq_Alarm		:=		WORD_TO_INT(CTU_TrqAlarm.CV);

CTU_TrqTips(CU:=Axis_Out.Tips_Out[3],Reset:=Axis_In.Trq_AlarmClear);//20250325_V1.00.00增加扭矩提示次数记录；
Axis_Out.Trq_Tips		:=		WORD_TO_INT(CTU_TrqTips.CV);
(******************************************	24.	报警汇总		******************************************)
IF TRUE THEN 
	//定位触发下降沿复位定位选择
	Move_HMI_F(CLK:=Axis_In.Location_Move_HMI);
	IF Move_HMI_F.Q THEN
		Clear(Axis_In.Location_Select_HMI);
	END_IF;
	Axis_Out.AlarmSum								:=	0												;
	Axis_Out.TipSum									:=	0												;
	SizeOfAry(In:=Axis_Out.Alarm_Out , Out=>Alarm_OutNum );
	Alarm_OutNumZ:=UINT_TO_INT(Alarm_OutNum);
	FOR i[9]:=0 TO (Alarm_OutNumZ-1) BY 1 DO 
		IF Axis_Out.Tips_Out[i[9]] THEN
			Axis_Out.TipSum							:=	1												;
		END_IF;
		IF Axis_Out.Alarm_Out[i[9]] AND NOT Status.AlarmShield THEN 
			Axis_Out.AlarmSum						:=	1												;
			EXIT;
		END_IF;
	END_FOR;
	IF Status.AlarmShield THEN
		Clear(Axis_Out.Alarm_Out) ;
		Axis_Out.Alarm :=FALSE;
	END_IF
END_IF;

(******************************************	25.	基础文字提示	******************************************)
IF 		(Axis_Out.AlarmSum
	OR	Axis_Out.TipSum)
	AND Axis_Out.OperationTip=""
	THEN
	IF Axis_Out.Alarm THEN
		Axis_Out.OperationTip						:=	"驱动器故障"										;
	ELSIF Axis_Out.Tips_Out[0] THEN
		Axis_Out.OperationTip						:=	"马达未使能"										;
	ELSIF Axis_Out.Tips_Out[1] THEN
		Axis_Out.OperationTip						:=	"马达未回原"										;
	ELSIF Axis_Out.Tips_Out[2] THEN
		Axis_Out.OperationTip						:=	"驱动器警告输入"									;		
	ELSIF Axis_Out.Tips_Out[3] THEN
		Axis_Out.OperationTip						:=	"轴扭矩超过额定值提示"								;			
	ELSIF Axis_Out.Tips_Out[4] THEN
		Axis_Out.OperationTip						:=	"请注意:轴当前速度倍率小于0.1"						;			
	ELSIF Axis_Out.Tips_Out[5] THEN
		Axis_Out.OperationTip						:=	"暂停对比异常提示"									;			
	ELSIF Axis_Out.Tips_Out[6] THEN
		Axis_Out.OperationTip						:=	"回原接近速度过快提示"								;	
	ELSIF Axis_Out.Tips_Out[7] THEN
		Axis_Out.OperationTip						:=	"多重触发报警提示"									;	
	ELSIF Axis_Out.Tips_Out[8] THEN
		Axis_Out.OperationTip						:=	"手动安全条件不满足报提示"							;		

	ELSIF Axis_Out.Alarm_Out[0] THEN
		Axis_Out.OperationTip						:=	"驱动器通讯故障"									;
	ELSIF Axis_Out.Alarm_Out[1] THEN
		Axis_Out.OperationTip						:=	"轴故障"											;
	ELSIF Axis_Out.Alarm_Out[2] THEN
		Axis_Out.OperationTip						:=	"回原安全条件不满足"								;
// 	ELSIF Axis_Out.Alarm_Out[3] THEN
// 		Axis_Out.OperationTip						:=	""													;
	ELSIF Axis_Out.Alarm_Out[4] THEN
		Axis_Out.OperationTip						:=	"轴运动安全条件不满足"								;
	ELSIF Axis_Out.Alarm_Out[5] THEN
		Axis_Out.OperationTip						:=	"扭矩值超过阈值警告"								;
	ELSIF Axis_Out.Alarm_Out[6] THEN
		Axis_Out.OperationTip						:=	"柔性回弹报警触发"									;
	ELSIF Axis_Out.Alarm_Out[7] THEN
		Axis_Out.OperationTip						:=	"正限位被感应，请检查结构或软限位参数"				;
	ELSIF Axis_Out.Alarm_Out[8] THEN
		Axis_Out.OperationTip						:=	"负限位被感应，请检查结构或软限位参数"				;
	ELSIF Axis_Out.Alarm_Out[9] THEN
		Axis_Out.OperationTip						:=	"轴未使能报警"				;
	ELSIF Axis_Out.Alarm_Out[10] THEN
		Axis_Out.OperationTip						:=	"在安全位置时请检查归零位感应器是否在此"				;  //未检测到安全感应,
		
	END_IF;


END_IF; 


