(********************************************	报警复位	*****************************************************)
IF TRUE
THEN
// 当轴出错，复位输入被触发后，执行轴复位功能块，并复位轴错误。
IF	ErrOut.Alarm
	AND Reset
THEN
	Reset_M						:=	TRUE										;
	FindHomeStep							:=	0											;
ELSE
	Reset_M						:=	FALSE										;
END_IF;

IF  (ErrOut.Alarm
	OR ErrOut.LimitError)
	AND	Reset
THEN
	ErrOut.CommandAborted					:=	FALSE										;//指令中断异常
	ErrOUT.SetingError						:=	FALSE										;//设置参数异常汇总
	ErrOUT.SetAutoVelErr					:=	FALSE										;//自动速度设置异常
	ErrOUT.SetManualVelErr					:=	FALSE										;//手动速度设置异常
	ErrOUT.SetOverrideError					:=	FALSE										;//速度比设置异常
	ErrOUT.LimitError						:=	FALSE										;//软限位设置异常
	ErrOUT.SwitchErr						:=	FALSE										;//正负限位同时接通错误
	ErrOUT.PosSwitchWarning					:=	FALSE										;//正限位异常
	ErrOUT.NegSwitchWarning					:=	FALSE										;//负限位异常
	ErrOUT.MovingHinderErr					:=	FALSE										;//移动中干涉异常
	ErrOUT.DriverAlarm						:=	FALSE										;//驱动器报警
	ErrOUT.Alarm							:=	FALSE										;//报警
	ErrOut.OrderError						:=	FALSE										;//指令出错
	ErrOut.NoHomedError						:=	FALSE										;//没有回原点标记
	OUT.Homing								:=	FALSE										;
	ErrOut.RatedTrqErr						:=	FALSE										;//超出额定扭矩值异常
	ErrOut.LimitTrqErr						:=	FALSE										;//超出限制扭矩值异常
	ErrOut.SetTorqueLimitErr				:=	FALSE										;//设置最大扭矩值异常	
	ErrOut.SetTrqValueError				:=	FALSE										;//设置额定扭矩值异常
	ErrOut.NoEnableErr						:=	FALSE										;//未使能错误
	ErrOut.AxisHomeSwErr				:=	FALSE										;//轴在安全位未检测到原点感应器异常
	ErrOut.DriverEstop						:=	FALSE										;//驱动器安全回路异常
END_IF;

END_IF;

(********************************************	错误信息	******************************************************)
IF TRUE
THEN

(********************************************	没有原点标记错误		*********************************************)
	Homed_F(Clk:= Homed);
	IF Homed_F.Q
		AND NOT Out.Homing
	THEN
		ErrOut.NoHomedError						:=	TRUE										;
	END_IF;

//在自动JOG过程中安全条件不满足报警	
		IF  Out.Busy
		AND ( In.AutoJogPos
		OR  In.AutoJogNeg)
		AND NOT In.JogAllow
	THEN
		ToPosHinderErr:=TRUE;
	END_IF;
(********************************************	运动中干涉报警		*********************************************)
	IF (Out.Busy
		)
		AND (NOT IN.MovingAllow)
	OR ToPosHinderErr
	THEN
		ErrOut.MovingHinderErr					:=	TRUE										;
		ToPosHinderErr:=FALSE;
	END_IF;

(********************************************	驱动器报警		*********************************************)
	IF	DriverAlarm
		OR DriverAlarm1_6030_01<>0
		OR DriverAlarm2_6030_02<>0
		OR DriverAlarm3_6030_03<>0
		OR DriverAlarm4_6030_04<>0
	THEN
		ErrOUT.DriverAlarm						:=	TRUE										;
	END_IF;
	IF DriverAlarm1_6030_01<>0
	THEN
		ErrOUT.DriveErrID					:=	USINT_TO_WORD(DriverAlarm1_6030_01	)					;
	ELSIF DriverAlarm2_6030_02<>0
	THEN
		ErrOUT.DriveErrID					:=	USINT_TO_WORD(DriverAlarm2_6030_02)					;
	ELSIF DriverAlarm3_6030_03<>0
	THEN
		ErrOUT.DriveErrID					:=	USINT_TO_WORD(DriverAlarm3_6030_03	)					;
	ELSIF DriverAlarm4_6030_04<>0
	THEN
		ErrOUT.DriveErrID					:=	USINT_TO_WORD(DriverAlarm4_6030_04)					;
	ELSE
		ErrOUT.DriveErrID					:=	0;
	END_IF;

(********************************************	轴参数设置错误		*********************************************)
