(************************************1、状态字****************************************)
//心跳
TON_HeartBeat(PT:=T#2S);
IF HeartBeatTemp <> GolytecInputToPLC.Resolution_6000_05 OR Reset THEN
 		HeartBeatTemp := GolytecInputToPLC.Resolution_6000_05;
		TON_HeartBeat.In:=FALSE;
ELSE
	TON_HeartBeat.In:=TRUE;
END_IF;
//心跳定时器
IF TON_HeartBeat.Q THEN
	ErrOut.HeartBeatErr:=TRUE;
END_IF;

StatusWord.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.sys_status_6000_01);
FC_WordToAryBool(StatusWord.mWord[0],0,StatusWord_mBit,0,16);
FC_WordToAryBool(StatusWord.mWord[1],0,StatusWord_mBit,16,16);
//初始化中
H_Out.Initializing:=StatusWord_mBit[0];
Out.Initializing:=StatusWord_mBit[0];

//初始化完成
H_Out.Inited:=StatusWord_mBit[1];
Out.Inited:=StatusWord_mBit[1];

//自动中
H_Out.Station_auto:=StatusWord_mBit[2];
//自动信号延时1S输出保证其他的到位信号先收到
TON_CQAuto(In:=StatusWord_mBit[2], PT:=T#1S, Q=>Out.Station_auto);
//Out.Station_auto:=StatusWord_mBit[2];

//自动暂停中
H_Out.Station_auto_pause:=StatusWord_mBit[3];
//Out.Station_auto_pause:=StatusWord_mBit[3];

//警告
H_Out.Warning:=StatusWord_mBit[7];
//Out.Warning:=StatusWord_mBit[7];
H_Out.SysErrID:=GolytecInputToPLC.sys_errno_6000_02;


//报警
H_Out.Error:=StatusWord_mBit[8];
Out.Error:=StatusWord_mBit[8];

IF StatusWord_mBit[8] OR ErrOut.HeartBeatErr THEN
	ErrOut.Alarm:=TRUE;
END_IF;

//总线状态
H_Out.EcatStatus:=StatusWord_mBit[12];
//Out.EcatStatus:=StatusWord_mBit[12];

//报警信息处理
H_Out.SysErrID:=GolytecInputToPLC.sys_errno_6000_02;
H_Out.ErrInfoCode:=GolytecInputToPLC.error_information_6000_14;
H_Out.ErrMoveNum:=GolytecInputToPLC.err_mover_id_6000_15;
H_Out.ErrStatorNum:=GolytecInputToPLC.err_stator_id_6000_16;


ErrInfoCodeWord.mWord:=UINT_TO_WORD(GolytecInputToPLC.error_information_6000_14);	//报警信息
FC_WordToAryBool(ErrInfoCodeWord.mWord,0,ErrInfoCodeWord_mBit,0,16);

//bit0	定子驱动板温度报警	检查风扇是否开启
IF ErrInfoCodeWord_mBit[0] THEN	
	ErrOut.AlarmrInfo[0]:=TRUE;
END_IF;	
//bit1	模块温度报警	检查风扇是否开启
IF ErrInfoCodeWord_mBit[1] THEN	
	ErrOut.AlarmrInfo[1]:=TRUE;
END_IF;	
//bit2	模块电压过低	检查定子的动力电保险丝、电源、电源线是否正常，电源电力是否充足
IF ErrInfoCodeWord_mBit[2] THEN	
	ErrOut.AlarmrInfo[2]:=TRUE;
END_IF;
//bit3	供电电流过大	检查是否动子是否堵转或者碰撞
IF ErrInfoCodeWord_mBit[3] THEN	
	ErrOut.AlarmrInfo[3]:=TRUE;
END_IF;	
//bit4	风扇0转速过低	检查风扇0是否连接或者损坏
IF ErrInfoCodeWord_mBit[4] THEN	
	;//ErrOut.AlarmrInfo[4]:=TRUE;//20250322果栗供应商说取消
END_IF;
//bit5	风扇1转速过低	检查风扇1是否连接或者损坏
IF ErrInfoCodeWord_mBit[5] THEN	
	;//ErrOut.AlarmrInfo[5]:=TRUE;//20250322果栗供应商说取消
END_IF;	
//bit6	驱动板温度报警	检查风扇是否开启
IF ErrInfoCodeWord_mBit[6] THEN	
	ErrOut.AlarmrInfo[6]:=TRUE;
END_IF;	
//bit7	模块温度报警	检查风扇是否开启
IF ErrInfoCodeWord_mBit[7] THEN	
	ErrOut.AlarmrInfo[7]:=TRUE;
END_IF;
//bit8	通讯报警	检查光纤未插好、光纤线损坏、通讯模块损坏
IF ErrInfoCodeWord_mBit[8] THEN	
	ErrOut.AlarmrInfo[8]:=TRUE;
END_IF;	
//bit9	模块电源被切断	检查报错的定子保险丝是否烧坏，电源供电是否正常
IF ErrInfoCodeWord_mBit[9] THEN	
	ErrOut.AlarmrInfo[9]:=TRUE;
END_IF;	
//bit10	模块电路报错	检查报错的定子保险丝是否烧坏，电源供电是否正常
IF ErrInfoCodeWord_mBit[10] THEN	
	ErrOut.AlarmrInfo[10]:=TRUE;
END_IF;	
//bit11	模块电路电流报错	检查报错的定子保险丝是否烧坏，电源供电是否正常。如果全部正常，需使用万用表测量该定子电源接口的24V接插口是否有短路。如果短路，则需要更换定子线圈。
IF ErrInfoCodeWord_mBit[11] THEN	
	ErrOut.AlarmrInfo[11]:=TRUE;
END_IF;	
//bit12	模块电路电流报错	检查报错的定子保险丝是否烧坏，电源供电是否正常。如果全部正常，需使用万用表测量该定子电源接口的24V接插口是否有短路。如果短路，则需要更换定子线圈。
IF ErrInfoCodeWord_mBit[12] THEN	
	ErrOut.AlarmrInfo[12]:=TRUE;
END_IF;
//bit13 动子振荡报错  检查动子是否有异常
IF ErrInfoCodeWord_mBit[13] THEN	
	ErrOut.AlarmrInfo[13]:=TRUE;
END_IF;	
//bit14	动子急停报错	检查动子是否撞机
IF ErrInfoCodeWord_mBit[14] THEN	
	ErrOut.AlarmrInfo[14]:=TRUE;
END_IF;	
IF ErrInfoCodeWord_mBit[15] THEN	
	ErrOut.AlarmrInfo[15]:=TRUE;
END_IF;	



