(******************************************** 名称 *********************************************) NameString( In := In.Name, Out => H_Out.Name ); (******************************************** 参数初始化 *********************************************) IF Parameter.sHost ='' //IP地址 THEN Parameter.sHost := '192.168.0.93'; END_IF; IF Parameter.nPort =0 // 端口号 THEN Parameter.nPort := 5004; END_IF; (********************************************TCP功能块调用 *********************************************) PowerMeterTCP ( ServerSelect := TCP_PowerMeter.ServerSelect ,// FALSE为客户端 sHost := TCP_PowerMeter.sHost ,// 客户端需填IP地址 nPort := TCP_PowerMeter.nPort ,// 端口号 bReset :=TCP_PowerMeter.bReset ,// 复位 bEnable :=TCP_PowerMeter.bEnable ,// 功能块使能 sSendData :=TCP_PowerMeter.bySendData ,// 发送数据 bSendExecute :=TCP_PowerMeter.bSendExecute ,// 发送触发 bConnected =>TCP_PowerMeter.bConnected ,// 链接标志 bSendDone =>TCP_PowerMeter.bSendDone ,// 发送完成 sReadData :=TCP_PowerMeter.byReadData ,// 接收数据(Byte) nReadDaSize :=TCP_PowerMeter.nReadDaSize ,// 接收数据长度 bReadDone :=TCP_PowerMeter.bReadDone ,// 接收完成 bConnectedErr =>TCP_PowerMeter.bConnectedErr ,// 连接错误 bBusy =>TCP_PowerMeter.bBusy ,// 忙碌 bError =>TCP_PowerMeter.bError ,// 错误 nErrorID =>TCP_PowerMeter.nErrorID // 错误ID // HSocket =>TCP_PowerMeter.HSocket //链接句柄 ); //配置 TCP_PowerMeter.ServerSelect := FALSE ;// FALSE为客户端 TCP_PowerMeter.sHost :=Parameter.sHost;// IP地址 TCP_PowerMeter.nPort := Parameter.nPort ;// 端口号
//客服端掉线,服务器使能复位 IF TCP_PowerMeter.bError OR TCP_PowerMeter.bConnectedErr OR H_In.Disabled THEN TCP_PowerMeter.bEnable := FALSE ; ELSIF NOT TCP_PowerMeter.bError AND NOT TCP_PowerMeter.bConnectedErr AND NOT H_In.Disabled THEN TCP_PowerMeter.bEnable := TRUE ; END_IF;
(******************************************** 错误信息汇总 *********************************************)
IF (NOT TCP_PowerMeter.bConnected //诊断异常报警！请检查终端！ OR TCP_PowerMeter.bConnectedErr) AND NOT Reset AND NOT H_In.Disabled THEN ErrOut.ErrorID := 1; //电能表TCPIP通讯连接错误,请检查！ END_IF;
(******************************************** 报警复位 *********************************************) IF (ErrOut.Error AND Reset) OR H_In.Disabled OR ErrOut.Error THEN AutoStep:=0; Clear(ErrOut.ErrorID); END_IF;
IF ErrOut.ErrorID<>0 //变为TRUE的时间:本指令的启动条件或输入参数中含有异常因素时 THEN ErrOut.Error :=TRUE ; ELSE ErrOut.Error :=FALSE ; //变为FALSE的时间: 异常已解除时 END_IF;

