	IF 	Parameter.ExecutePT_ON = 0 OR Parameter.ExecutePT_ON>50			//启动延时设定ms
	THEN
		Parameter.ExecutePT_ON			:=	50						;
	END_IF;
	IF 	Parameter.RespondTimeOutPT_ON = 0		//反馈接收触发信号完成超时设定ms
	THEN
