	IF 	Parameter.ResultTimeOutPT_ON = 0		//反馈结果超时设定ms
	THEN
		Parameter.ResultTimeOutPT_ON			:=	3000					;
	END_IF;
	IF Parameter.RetryNumMax = 0  		//重发计数次数设定
	THEN
		Parameter.RetryNumMax:=	3;
	END_IF;	
(********************************************	定时器		*********************************************)
	TON_ExecutePT_ON(In:=In.Execute , PT:=Hymson_Functions.NanoSecToTime(REAL_TO_LINT(Parameter.ExecutePT_ON*REAL#1000000)));		//启动延时定时器
	TON_RespondTimeOutAlarm(In:= AutoStep=20 , PT:=Hymson_Functions.NanoSecToTime(REAL_TO_LINT(Parameter.RespondTimeOutPT_ON*REAL#1000000)));		//反馈接收触发信号完成超时定时器
	TON_ResultTimeOutAlarm(In:= AutoStep=30 , PT:=Hymson_Functions.NanoSecToTime(REAL_TO_LINT(Parameter.ResultTimeOutPT_ON*REAL#1000000)));		//反馈结果超时定时器					
(********************************************	交互流程		*********************************************)
ManualTrigger(CLK:=H_In.Execute AND H_In.CheckExecute  );	//手动上升沿触发						 
AutoTrigger(CLK:= In.Execute AND Auto AND  TON_ExecutePT_ON.Q);	//自动上升沿触发		
//触发记录
IF ManualTrigger.Q   //手动触发
THEN
	TriggerMemory :=  FALSE ;  //FALSE为手动触发
END_IF;			
IF AutoTrigger.Q     //自动触发
THEN
	TriggerMemory :=  TRUE ;  //TRUE为自动触发
END_IF;
//	触发启动
IF ( ManualTrigger.Q
	AND Manual
	OR AutoTrigger.Q
	AND Auto)
	AND  NOT ErrOut.Error  //无报警
	AND  AutoStep=0
THEN	
		Clear(Out);  //清除输出数据		
		//Clear(H_Out);  //清除输出数据	
		RetryNumber := 0 ;//重发计数初始零	
		Clear(TCP_PowerMeter.bySendData);
		ExecuteType  := 'ExpEp'	;
		AutoStep:=10;
END_IF;	
CASE AutoStep OF
	
	10: 	//	发送数据处理
									IF 		 ExecuteType = 'Uab' //三相线电压数据，单位 V(×0.1V)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#61;//起始地址低字节
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节
									ELSIF ExecuteType = 'Ubc' //三相线电压数据，单位 V(×0.1V)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#62;//起始地址低字节
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节
									ELSIF ExecuteType = 'Uca' //三相线电压数据，单位 V(×0.1V)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#63;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节			
									ELSIF ExecuteType = 'Ia' //三相电流数据,单位 A(×0.001A)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#64;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节	
									ELSIF ExecuteType = 'Ib'//三相电流数据,单位 A(×0.001A)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#65;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节		
									ELSIF ExecuteType = 'Ic'//三相电流数据,单位 A(×0.001A)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#66;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节	
									ELSIF ExecuteType = 'Pt' //合相有功功率，单位 W(×0.1W)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#01;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#6A;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#02;//读取个数低字节
									ELSIF ExecuteType = 'ImpEp'//（当前）正向有功总电能
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#0A;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#02;//读取个数低字节	
									ELSIF ExecuteType = 'ExpEp' //（当前）反向有功总电能
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#14;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#02;//读取个数低字节
									END_IF;
									TCP_PowerMeter.bySendData[0] := BYTE#16#01;//从站号
									TCP_PowerMeter.bySendData[1] := BYTE#16#03;//功能代码(读取通道过程值命令）
									TempWord.mWord := MEM.CRC16_Modbus(ADR(TCP_PowerMeter.bySendData), 6);//CRC_16校验				
									TCP_PowerMeter.bySendData[6] := TempWord.mByte[0];//CRC_16高字节	  
									TCP_PowerMeter.bySendData[7] := TempWord.mByte[1];//CRC_16低字节		
									
			//Clear(TCP_PowerMeter.byReadData);  //清除数据				
			AutoStep:=20;	
	20: 	//	等待反馈接收触发信号完成	
				IF 	TCP_PowerMeter.bySendData[0] = BYTE#00 
					OR TCP_PowerMeter.bSendDone
					//接收端清空发送数据为发送完成
				THEN
						AutoStep:=30;
				END_IF; 	
	 30:	//	等待反馈结果	
				IF  TCP_PowerMeter.byReadData[0] <> BYTE#00 //接收字节不为0
					AND TCP_PowerMeter.bReadDone
				THEN
						AutoStep:=40;
				END_IF;
	 40:	//	解析和采集数据
				//TempWord.mWord := MEM.CRC16_Modbus(ADR(TCP_PowerMeter.byReadData), 7);//CRC_16校验		
				//IF  TCP_PowerMeter.byReadData[7] = TempWord.mByte[0] //CRC_16高字节	  
				//	AND TCP_PowerMeter.byReadData[8] = TempWord.mByte[1] //CRC_16低字节
			//	THEN
						IF 		 ExecuteType = 'Uab' //三相线电压数据，单位 V(×0.1V)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.UabValue :=DWORD_TO_REAL(TempUn_DWord.mDword)	* 0.1 ;
								  ExecuteType :=  'Ubc' ;
						ELSIF  ExecuteType = 'Ubc'//三相线电压数据，单位 V(×0.1V)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.UbcValue :=DWORD_TO_REAL(TempUn_DWord.mDword)	* 0.1 ;	
								  ExecuteType :=  'Uca' ;
						ELSIF  ExecuteType = 'Uca'//三相线电压数据，单位 V(×0.1V)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.UcaValue :=DWORD_TO_REAL(TempUn_DWord.mDword)	* 0.1 ;	
								  ExecuteType :=  'Ia' ;
						ELSIF ExecuteType = 'Ia' //三相电流数据,单位 A(×0.001A)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.IaValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * 0.01;	
								  ExecuteType :=  'Ib' ;
						ELSIF ExecuteType = 'Ib'	//三相电流数据,单位 A(×0.001A)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.IbValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * 0.01;	
								  ExecuteType :=  'Ic' ;
						ELSIF ExecuteType = 'Ic'	//三相电流数据,单位 A(×0.001A)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.IcValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * 0.01;
								  ExecuteType :=  'Pt' ;
						ELSIF ExecuteType = 'Pt' //合相有功功率，单位 W(×0.1W)
						THEN		
								TempUn_DWord.mByte[3] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[2] :=TCP_PowerMeter.byReadData[4];
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[5];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[6];
								  Out.PtValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * (1.00 * 0.001) ;	
								  ExecuteType :=  'ImpEp' ;
						ELSIF ExecuteType = 'ImpEp'//（当前）正向有功总电能
						THEN
								TempUn_DWord.mByte[3] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[2] :=TCP_PowerMeter.byReadData[4];
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[5];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[6];
								  Out.ImpEpValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * (1.00 * 0.01) ;	
								  ExecuteType :=  'ExpEp' ;
						ELSIF  ExecuteType = 'ExpEp'  //（当前）反向有功总电能
						THEN
								TempUn_DWord.mByte[3] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[2] :=TCP_PowerMeter.byReadData[4];
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[5];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[6];
								  Out.ExpEpValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * (1.00 * 0.01) ;	
								  ExecuteType :=  'Uab' ;
						END_IF;																						
			//	END_IF;
				IF  NOT TriggerMemory AND NOT H_In.Execute
					OR TriggerMemory AND NOT In.Execute
				THEN
						AutoStep:=50;	
				ELSE
						AutoStep:=10;	
				END_IF;										
	 50:	//	数据结果处理
		 		IF NOT TriggerMemory
					AND NOT H_In.Execute
				THEN
					AutoStep			:=		0;	
				ELSIF NOT In.Execute
						AND TriggerMemory
				THEN
					AutoStep			:=		0;	
				END_IF;
END_CASE;	
(******************************************** TCP功能块控制  *********************************************)
PowerMeterTCP.SendLen:=8;
 //发送间隔
 TP_SendInterval(In:=NOT TCP_PowerMeter.bSendDone, PT:=T#200MS);
//发送
IF AutoStep =20 
	AND (*NOT*) TP_SendInterval.Q
THEN
	TCP_PowerMeter.bSendExecute :=TRUE  ; //自动触发
ELSE
	TCP_PowerMeter.bSendExecute :=FALSE  ; //自动触发	
END_IF;
//等待接收反馈
IF Out.Busy
	AND NOT Out.Active
	AND TCP_PowerMeter.bSendDone 
THEN
		Clear(TCP_PowerMeter.bySendData);	
END_IF;
//等待接收完成
(********************************************	错误信息汇总		*********************************************)
IF NOT Reset
	AND NOT H_In.Disabled
THEN
		IF TON_RespondTimeOutAlarm.Q
		THEN
			ErrOut.ErrorID := 2;   //电能表反馈接收触发信号完成超时报警！请检查电能表和串口服务器是否正常运行！
		ELSIF TON_ResultTimeOutAlarm.Q
		THEN
			ErrOut.ErrorID := 3;   //电能表反馈结果超时报警！请检查电能表和串口服务器是否正常运行！
		ELSIF ( TCP_PowerMeter.byReadData[7] <> TempWord.mByte[1] //CRC_16高字节	  
					OR  TCP_PowerMeter.byReadData[8] <> TempWord.mByte[0]) //CRC_16低字节
				AND AutoStep > 40
		THEN
			ErrOut.ErrorID := 4;   //电能表反馈结果数据异常报警！请检查电能表和串口服务器是否正常运行！
		END_IF;
		IF RetryNumber < Parameter.RetryNumMax //重发计数
			AND ErrOut.ErrorID > 1
			AND ErrOut.ErrorID < 5
		THEN
				ErrOut.ErrorID := 0; 
				RetryNumber :=RetryNumber+1 ;
				AutoStep			:=		10;	
		END_IF;		
END_IF;
(********************************************	信号输出		*********************************************)
F_ManualTrigger(CLK:=H_In.Execute );	//手动下降沿触发						 
F_AutoTrigger(CLK:= In.Execute );	//自动下降沿触发	
IF  	NOT TriggerMemory	AND (F_ManualTrigger.Q OR 	NOT H_In.Execute  AND  Out.Done	)	
		OR  TriggerMemory	AND (F_AutoTrigger.Q OR NOT In.Execute  AND  Out.Done )	
THEN  //变为FALSE的时间: • Execute为TRUE时，与Execute的FALSE同时 • Execute为FALSE时，1个周期后
		Out.Done 		:= FALSE  ;
ELSIF AutoStep >40
THEN //变为TRUE的时间:指令完成时
		Out.Done 		:= TRUE  ;		
END_IF;								
Out.Busy			:= AutoStep <>0				//变为TRUE的时间:Execute的上升沿
							AND NOT Out.Done	//变为FALSE的时间:• Done变为TRUE时• Error变为TRUE时• CommandAborted变为TRUE时
							AND NOT ErrOut.Error
							AND NOT Out.CommandAborted ;			
Out.Active		:= AutoStep >20	//变为TRUE的时间:开始指令后
							AND NOT Out.Done	//变为FALSE的时间• Done变为TRUE时• Error变为TRUE时• CommandAborted变为TRUE时		
							AND NOT ErrOut.Error
							AND NOT Out.CommandAborted ;
IF 	TriggerMemory AND AutoStep <>0 AND ManualTrigger.Q   
	OR NOT TriggerMemory AND AutoStep <>0 AND AutoTrigger.Q	
	OR ErrOut.Error AND( ManualTrigger.Q  OR  AutoTrigger.Q	)
THEN //变为TRUE的时间:• 利用其它指令多重启动指令(中断)，中止本指令时• 因发生异常，中止本指令时• 发生异常过程中，启动本指令时• 停止指令执行中，启动本指令后
		Out.CommandAborted := TRUE;
ELSIF  NOT TriggerMemory	AND (F_ManualTrigger.Q OR 	NOT H_In.Execute  AND  Out.CommandAborted)	
		  OR  TriggerMemory	AND (F_AutoTrigger.Q OR NOT In.Execute  AND  Out.CommandAborted ) 
THEN //变为FALSE的时间• Execute为TRUE时，与Execute的FALSE同时 • Execute为FALSE时，1个周期后	
		Out.CommandAborted := FALSE;
END_IF;														
(********************************************	HMI信号输出		*********************************************)
H_Out.Done 				:= Out.Done ;
H_Out.Busy				:= Out.Busy;
H_Out.Active			:= Out.Active;	
H_Out.CommandAborted	:= Out.CommandAborted ;	
H_Out.UabValue			:= Out.UabValue;	
H_Out.UbcValue			:= Out.UbcValue;	
H_Out.UcaValue			:= Out.UcaValue;	
H_Out.IaValue			:= Out.IaValue;	
H_Out.IbValue			:= Out.IbValue;		
H_Out.IcValue			:= Out.IcValue;	
H_Out.PtValue			:= Out.PtValue;	
H_Out.ImpEpValue		:= Out.ImpEpValue;	
H_Out.ExpEpValue		:= Out.ExpEpValue;

(********************************************	参数初始化		*********************************************)	
		//TCP_PowerMeter.nSendDaSize	:=16;
	(************************************电能采集ModBus_RTU**************************************)			
	IF H_In.Disabled 	
	THEN
		Clear(Energy_DTSU666); 
		Clear(AutoStep); 
	END_IF; 
	//发送
	IF  NOT H_In.Disabled 					 //电能表启用
		AND Pulse.T_10s.Q
	THEN
				IF  AutoStep  = 0 					//组合有功总电能读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#33;//读取个数高字节
						EnSend[13] := BYTE#16#33;//读取个数低字节
						AutoStep := 150 ;
				END_IF;
				IF  AutoStep  = 10 					//正向有功总电能读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#34;//读取个数高字节
						EnSend[13] := BYTE#16#33;//读取个数低字节
						AutoStep := 160 ;
				END_IF;
				IF  AutoStep  =20 					//反向有功总电能读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#35;//读取个数高字节
						EnSend[13] := BYTE#16#33;//读取个数低字节
						AutoStep := 170 ;
				END_IF;
				IF AutoStep  = 30 					//A相电流读取
				   AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#34;//起始地址低字节
						EnSend[12] := BYTE#16#35;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 180 ;	
				END_IF;
				IF  AutoStep  = 40 			//B相电流读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[2] := BYTE#16#33;//起始地址高字节
						EnSend[3] := BYTE#16#35;//起始地址低字节
						EnSend[4] := BYTE#16#35;//读取个数高字节
						EnSend[5] := BYTE#16#35;//读取个数低字节
						AutoStep := 190 ;	
				END_IF; 
				IF  AutoStep  = 50				//C相电流读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#36;//起始地址低字节
						EnSend[12] := BYTE#16#35;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 200 ;	
				END_IF;
				IF  AutoStep  = 60				//A相电压读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#34;//起始地址低字节
						EnSend[12] := BYTE#16#34;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 210 ;	
				END_IF;
				IF  AutoStep  = 70					//B相电压读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#35;//起始地址低字节
						EnSend[12] := BYTE#16#34;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 220 ;	
				END_IF;
				IF  AutoStep  = 80				//C相电压读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#36;//起始地址低字节
						EnSend[12] := BYTE#16#34;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 230 ;	
				END_IF;
				IF  AutoStep  = 90				//总功率因数
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#39;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 240 ;	
				END_IF;
				IF  AutoStep  = 100			//瞬时总有功功率
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#36;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 250 ;	
				END_IF;
				IF  AutoStep  = 110			//瞬时A相有功功率
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#34;//起始地址低字节
						EnSend[12] := BYTE#16#36;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 260 ;	
				END_IF;
				IF  AutoStep  = 120			//瞬时B相有功功率
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#35;//起始地址低字节
						EnSend[12] := BYTE#16#36;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 270 ;	
				END_IF;
				IF  AutoStep  = 130			//瞬时C相有功功率
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#36;//起始地址低字节
						EnSend[12] := BYTE#16#36;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 280 ;	
				END_IF;
				EnSend[0] := BYTE#16#68;//电能表起始帧
				EnSend[1] :=Parameter.DTSU666_Data[5];//电能表域地址A0，高低字节调换
				EnSend[2] := Parameter.DTSU666_Data[4];//电能表域地址A1
				EnSend[3] := Parameter.DTSU666_Data[3];//电能表域地址A2
				EnSend[4] := Parameter.DTSU666_Data[2];//电能表域地址A3
				EnSend[5] := Parameter.DTSU666_Data[1];//电能表域地址A4
				EnSend[6] := Parameter.DTSU666_Data[0];//电能表域地址A5
				EnSend[7] := BYTE#16#68;//电能表起始帧
				EnSend[8] := BYTE#16#11;//电能表控制码
				EnSend[9] := BYTE#16#04;//数据长度域
				EnSend[15] := BYTE#16#16;//结束符
			//运算校验码（从第一个帧起始符开始到校验码之前的所有个字节的模256的和）
				EnSend_INT[0]   :=  BYTE_TO_INT(EnSend[0]);
				EnSend_INT[1]   :=  BYTE_TO_INT(EnSend[1]);
				EnSend_INT[2]   :=  BYTE_TO_INT(EnSend[2]);
				EnSend_INT[3]   :=  BYTE_TO_INT(EnSend[3]);
				EnSend_INT[4]   :=  BYTE_TO_INT(EnSend[4]);
				EnSend_INT[5]   :=  BYTE_TO_INT(EnSend[5]);
				EnSend_INT[6]   :=  BYTE_TO_INT(EnSend[6]);
				EnSend_INT[7]   :=  BYTE_TO_INT(EnSend[7]);
				EnSend_INT[8]   :=  BYTE_TO_INT(EnSend[8]);
				EnSend_INT[9]   :=  BYTE_TO_INT(EnSend[9]);
                EnSend_INT[10]   :=  BYTE_TO_INT(EnSend[10]);
				EnSend_INT[11]   :=  BYTE_TO_INT(EnSend[11]);
				EnSend_INT[12]   :=  BYTE_TO_INT(EnSend[12]);
				EnSend_INT[13]   :=  BYTE_TO_INT(EnSend[13]);
				EnSend_SUM:=EnSend_INT[0]+EnSend_INT[1]+EnSend_INT[2]+EnSend_INT[3]+EnSend_INT[4]+EnSend_INT[5]+
				                         EnSend_INT[6]+EnSend_INT[7]+EnSend_INT[8]+EnSend_INT[9]+EnSend_INT[10]+EnSend_INT[11]+
										 EnSend_INT[12]+EnSend_INT[13];//相加
				EnSend_Word.mWord:=INT_TO_WORD(EnSend_SUM);
				EnSend[14]:=EnSend_Word.mByte[0];//校验码
				AryMove(EnSend[0],TCP_PowerMeter.bySendData[0],16);
				TCP_PowerMeter.bSendExecute:=TRUE;
	END_IF;
	//接收

	IF TCP_PowerMeter.bReadDone 
	THEN	
			AryMove(TCP_PowerMeter.byReadData[0],EnRead[0],30);		
			EnRead_Size:=TCP_PowerMeter.nReadDaSize;
			IF AutoStep  = 150 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	组合有功总电能读取
			        EnRead_INT[0]:=(BYTE_TO_INT(EnRead[EnRead_Size-6]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[0]);//32位的word运算
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[3]);
					Energy_DTSU666[0]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.01;	
					AutoStep := 10 ;
			END_IF;
			IF AutoStep  = 160 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	正向有功总电能读取
			        EnRead_INT[0]:=(BYTE_TO_INT(EnRead[EnRead_Size-6]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[0]);//32位的word运算
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[3]);
					Energy_DTSU666[1]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.01;	
					AutoStep := 20 ;
			END_IF;
			IF AutoStep  = 170 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	反向有功总电能读取
			        EnRead_INT[0]:=(BYTE_TO_INT(EnRead[EnRead_Size-6]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[0]);//32位的word运算
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[3]);
					Energy_DTSU666[2]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.01;	
					AutoStep := 30 ;
			END_IF;
			IF AutoStep  = 180 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	A相电流读取
			        EnRead_INT[0]:=INT#00;//电流读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[3]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.001;	//当前A相电流
					Energy_DTSU666[4] :=MAX(Energy_DTSU666[3],Energy_DTSU666[4]);//最大A相电流 		
					AutoStep := 40 ;
			END_IF;
			IF AutoStep  = 190 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	B相电流读取
			        EnRead_INT[0]:=INT#00;//电流读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[5]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.001;	//当前B相电流
					Energy_DTSU666[6] :=MAX(Energy_DTSU666[5],Energy_DTSU666[6]);//最大B相电流 		
					AutoStep := 50 ;
			END_IF;
			IF AutoStep  = 200 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	C相电流读取
			        EnRead_INT[0]:=INT#00;//电流读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[7]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.001;	//当前C相电流
					Energy_DTSU666[8] :=MAX(Energy_DTSU666[7],Energy_DTSU666[8]);//最大C相电流 		
					AutoStep := 60 ;
			END_IF;
			IF AutoStep  = 210 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	A相电压读取
			        EnRead_INT[0]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[1]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[2]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[3]);//32位的word运算，需要错位读取
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[9]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.1;	//当前A相电压
					Energy_DTSU666[10] :=MAX(Energy_DTSU666[9],Energy_DTSU666[10]);//最大A相电压	
					AutoStep := 70 ;
			END_IF;
			IF AutoStep  = 220 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	B相电压读取
			        EnRead_INT[0]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[1]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[2]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[3]);//32位的word运算，需要错位读取
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[11]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.1;	//当前B相电压
					Energy_DTSU666[12] :=MAX(Energy_DTSU666[11],Energy_DTSU666[12]);//最大B相电压	
					AutoStep := 80 ;
			END_IF;
			IF AutoStep  = 230 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	C相电压读取
			        EnRead_INT[0]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[1]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[2]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[3]);//32位的word运算，需要错位读取
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[13]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.1;	//当前C相电压
					Energy_DTSU666[14] :=MAX(Energy_DTSU666[13],Energy_DTSU666[14]);//最大C相电压	
					AutoStep := 90 ;
			END_IF;
			IF AutoStep  = 240 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	总功率因数
			        EnRead_INT[0]:=INT#00;//总功率因数读取只需读两个BYTE位
					EnRead_INT[1]:=INT#00;//总功率因数读取只需读两个BYTE位
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[2]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[3]);//32位的word运算，需要错位读取
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[15]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.001;	//总功率因数
					AutoStep := 100 ;
			END_IF;
			IF AutoStep  = 250 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	瞬时总有功功率
			        EnRead_INT[0]:=INT#00;//功率读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[16]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.0001;	//瞬时总有功功率
					AutoStep := 110 ;
			END_IF;
			IF AutoStep  = 260 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	瞬时A相有功功率
			        EnRead_INT[0]:=INT#00;//功率读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[17]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.0001;	//瞬时A相有功功率
					AutoStep := 120 ;
			END_IF;
			IF AutoStep  = 270 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	瞬时B相有功功率
			        EnRead_INT[0]:=INT#00;//功率读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[18]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.0001;	//瞬时B相有功功率
					AutoStep := 130 ;
			END_IF;
			IF AutoStep  = 280 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	瞬时C相有功功率
			        EnRead_INT[0]:=INT#00;//功率读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[19]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.0001;	//瞬时C相有功功率
					AutoStep := 0 ;
			END_IF;
			
	END_IF;
	//复位触发
	IF TCP_PowerMeter.bSendDone  
		OR TCP_PowerMeter.bReadDone 
		OR (Pulse.T_2s.Q
		AND TCP_PowerMeter.bSendExecute)
	THEN
			TCP_PowerMeter.bSendExecute:=FALSE;
	END_IF;


Out.ImpEpValue                  :=Energy_DTSU666[1];
Out.ExpEpValue                  :=Energy_DTSU666[2];
Out.IaValue                     :=Energy_DTSU666[3];
Out.IbValue                    	:=Energy_DTSU666[5];
Out.IcValue                     :=Energy_DTSU666[7];
Out.UabValue                   	:=Energy_DTSU666[9];
Out.UbcValue                  	:=Energy_DTSU666[11];
Out.UcaValue                  	:=Energy_DTSU666[13];
Out.Cos_tValue                  :=Energy_DTSU666[15];
Out.PtValue                  	:=Energy_DTSU666[16];
Out.PaValue                   	:=Energy_DTSU666[17];
Out.PbValue                     :=Energy_DTSU666[18];
Out.PcValue                     :=Energy_DTSU666[19];


H_Out.UabValue					:= Out.UabValue;	
H_Out.UbcValue					:= Out.UbcValue;	
H_Out.UcaValue					:= Out.UcaValue;	
H_Out.IaValue					:= Out.IaValue;	
H_Out.IbValue					:= Out.IbValue;		
H_Out.IcValue					:= Out.IcValue;	
H_Out.PtValue					:= Out.PtValue;	
H_Out.ImpEpValue				:= Out.ImpEpValue;	
H_Out.ExpEpValue				:= Out.ExpEpValue;

FOR i:=INT#0 TO INT#47 BY INT#1 DO
IF HMI_LOSS_Button[i] AND LOSSAlarm_Temp=FALSE THEN
	HMI_LOSS_Alarm[i] S=TRUE;
	LOSSAlarm_Temp S=TRUE;
	Trigger R=TRUE;
	LossID_UpLoading:=DINT#9455-i;
END_IF
END_FOR;

		
SizeOfAry(In:=Vac_Out.Tips_Out, Out=>uiTipsSize );
SetBlock(xFALSE,Vac_Out.Tips_Out[0],uiTipsSize);//复位提示

SizeOfAry(In:=Vac_Out.Alarm_Out, Out=>uiAlarmSize );
SetBlock(xFALSE,Vac_Out.Alarm_Out[0],uiAlarmSize);//复位报警

IF ETC_axLinkUp[0] THEN
	ECAT_SlaveInoCHA[Finish_uiSlaveAddr*10+1]:=1;
ELSE
    ECAT_SlaveInoCHA[Finish_uiSlaveAddr*10+1]:=2;
END_IF
ECAT_SlaveInoCHA[Finish_uiSlaveAddr*10+2]:=UINT_TO_INT(ECT_uiSlaveAddr);
ECAT_SlaveInoCHA[Finish_uiSlaveAddr*10+4]:=BYTE_TO_INT(ETC_abyInvalidFrameCount[0]);
ECAT_SlaveInoCHA[Finish_uiSlaveAddr*10+5]:=BYTE_TO_INT(ETC_abyInvalidFrameCount[1]);
ECAT_SlaveInoCHA[Finish_uiSlaveAddr*10+6]:=BYTE_TO_INT(ETC_abyInvalidFrameCount[2]);
ECAT_SlaveInoCHA[Finish_uiSlaveAddr*10+7]:=BYTE_TO_INT(ETC_abyInvalidFrameCount[3]);

(******************************************** 名称 *********************************************) NameString( In := In.Name, Out => H_Out.Name ); (******************************************** 参数初始化 *********************************************) IF Parameter.sHost ='' //IP地址 THEN Parameter.sHost := '192.168.0.93'; END_IF; IF Parameter.nPort =0 // 端口号 THEN Parameter.nPort := 5004; END_IF; (********************************************TCP功能块调用 *********************************************) PowerMeterTCP ( ServerSelect := TCP_PowerMeter.ServerSelect ,// FALSE为客户端 sHost := TCP_PowerMeter.sHost ,// 客户端需填IP地址 nPort := TCP_PowerMeter.nPort ,// 端口号 bReset :=TCP_PowerMeter.bReset ,// 复位 bEnable :=TCP_PowerMeter.bEnable ,// 功能块使能 sSendData :=TCP_PowerMeter.bySendData ,// 发送数据 bSendExecute :=TCP_PowerMeter.bSendExecute ,// 发送触发 bConnected =>TCP_PowerMeter.bConnected ,// 链接标志 bSendDone =>TCP_PowerMeter.bSendDone ,// 发送完成 sReadData :=TCP_PowerMeter.byReadData ,// 接收数据(Byte) nReadDaSize :=TCP_PowerMeter.nReadDaSize ,// 接收数据长度 bReadDone :=TCP_PowerMeter.bReadDone ,// 接收完成 bConnectedErr =>TCP_PowerMeter.bConnectedErr ,// 连接错误 bBusy =>TCP_PowerMeter.bBusy ,// 忙碌 bError =>TCP_PowerMeter.bError ,// 错误 nErrorID =>TCP_PowerMeter.nErrorID // 错误ID // HSocket =>TCP_PowerMeter.HSocket //链接句柄 ); //配置 TCP_PowerMeter.ServerSelect := FALSE ;// FALSE为客户端 TCP_PowerMeter.sHost :=Parameter.sHost;// IP地址 TCP_PowerMeter.nPort := Parameter.nPort ;// 端口号
//客服端掉线,服务器使能复位 IF TCP_PowerMeter.bError OR TCP_PowerMeter.bConnectedErr OR H_In.Disabled THEN TCP_PowerMeter.bEnable := FALSE ; ELSIF NOT TCP_PowerMeter.bError AND NOT TCP_PowerMeter.bConnectedErr AND NOT H_In.Disabled THEN TCP_PowerMeter.bEnable := TRUE ; END_IF;
(******************************************** 错误信息汇总 *********************************************)
IF (NOT TCP_PowerMeter.bConnected //诊断异常报警！请检查终端！ OR TCP_PowerMeter.bConnectedErr) AND NOT Reset AND NOT H_In.Disabled THEN ErrOut.ErrorID := 1; //电能表TCPIP通讯连接错误,请检查！ END_IF;
(******************************************** 报警复位 *********************************************) IF (ErrOut.Error AND Reset) OR H_In.Disabled OR ErrOut.Error THEN AutoStep:=0; Clear(ErrOut.ErrorID); END_IF;
IF ErrOut.ErrorID<>0 //变为TRUE的时间:本指令的启动条件或输入参数中含有异常因素时 THEN ErrOut.Error :=TRUE ; ELSE ErrOut.Error :=FALSE ; //变为FALSE的时间: 异常已解除时 END_IF;

(*=========================== 程序简介 =================================
 @ 名称				:	FB_PowerMeterControl
 @ 描述				:	电能表控制功能块
 @ 作者				:	HongJianFeng
 @ 日期				:	2023.02.17
 @ 版本号			:	V1.0.0.0
 ======================================================================
 @ 说明				:	电能表控制功能块，已实现模块化，在外部调用引脚即可

	-----------------------------------------------------------------------------------------------------------------------------

	-----------------------------------------------------------------------------------------------------------------------------

 @ ========================= 修改履历 ===================================
 修改日期 	| 版本					| 作者		    	| 备注 
 ------------------------------------------------------------------------
 2023.02.17	| V1.0.0.0				| H			        | 初版发布
 -----------------------------------------------------------------------
 ============================= END ===================================*)
		
	IF 	Parameter.ExecutePT_ON = 0 OR Parameter.ExecutePT_ON>50		//启动延时设定ms
	THEN
		Parameter.ExecutePT_ON			:=	50						;
	END_IF;
	IF 	Parameter.RespondTimeOutPT_ON = 0		//反馈接收触发信号完成超时设定ms
	THEN
		Parameter.RespondTimeOutPT_ON			:=	2000						;
	END_IF;
	IF 	Parameter.ResultTimeOutPT_ON = 0		//反馈结果超时设定ms
	THEN
		Parameter.ResultTimeOutPT_ON			:=	3000					;
	END_IF;
	IF Parameter.RetryNumMax = 0  		//重发计数次数设定
	THEN
		Parameter.RetryNumMax:=	3;
	END_IF;	
(********************************************	定时器		*********************************************)
	TON_ExecutePT_ON(In:=In.Execute , PT:=Hymson_Functions.NanoSecToTime(REAL_TO_LINT(Parameter.ExecutePT_ON*REAL#1000000)));		//启动延时定时器
	TON_RespondTimeOutAlarm(In:= AutoStep=20 , PT:=Hymson_Functions.NanoSecToTime(REAL_TO_LINT(Parameter.RespondTimeOutPT_ON*REAL#1000000)));		//反馈接收触发信号完成超时定时器
	TON_ResultTimeOutAlarm(In:= AutoStep=30 , PT:=Hymson_Functions.NanoSecToTime(REAL_TO_LINT(Parameter.ResultTimeOutPT_ON*REAL#1000000)));		//反馈结果超时定时器					
(********************************************	交互流程		*********************************************)
ManualTrigger(CLK:=H_In.Execute AND H_In.CheckExecute  );	//手动上升沿触发						 
AutoTrigger(CLK:= In.Execute AND Auto AND  TON_ExecutePT_ON.Q);	//自动上升沿触发		
//触发记录
IF ManualTrigger.Q   //手动触发
THEN
	TriggerMemory :=  FALSE ;  //FALSE为手动触发
END_IF;			
IF AutoTrigger.Q     //自动触发
THEN
	TriggerMemory :=  TRUE ;  //TRUE为自动触发
END_IF;
//	触发启动
IF ( ManualTrigger.Q AND 
	   Manual
	OR AutoTrigger.Q
	AND Auto)
	AND  NOT ErrOut.Error  //无报警
	AND  AutoStep=0
THEN	
		Clear(Out);  //清除输出数据		
		//Clear(H_Out);  //清除输出数据	
		RetryNumber := 0 ;//重发计数初始零	
		Clear(TCP_PowerMeter.bySendData);
		ExecuteType  := 'ExpEp'	;
		AutoStep:=10;
END_IF;	
CASE AutoStep OF
	
	10: 	//	发送数据处理
									IF 		 ExecuteType = 'Uab' //三相线电压数据，单位 V(×0.1V)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#61;//起始地址低字节
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节
									ELSIF ExecuteType = 'Ubc' //三相线电压数据，单位 V(×0.1V)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#62;//起始地址低字节
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节
									ELSIF ExecuteType = 'Uca' //三相线电压数据，单位 V(×0.1V)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#63;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节			
									ELSIF ExecuteType = 'Ia' //三相电流数据,单位 A(×0.001A)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#64;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节	
									ELSIF ExecuteType = 'Ib'//三相电流数据,单位 A(×0.001A)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#65;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节		
									ELSIF ExecuteType = 'Ic'//三相电流数据,单位 A(×0.001A)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#66;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#01;//读取个数低字节	
									ELSIF ExecuteType = 'Pt' //合相有功功率，单位 W(×0.1W)
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#01;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#6A;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#02;//读取个数低字节
									ELSIF ExecuteType = 'ImpEp'//（当前）正向有功总电能
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#0A;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#02;//读取个数低字节	
									ELSIF ExecuteType = 'ExpEp' //（当前）反向有功总电能
									THEN
											  TCP_PowerMeter.bySendData[2] := BYTE#16#00;//起始地址高字节
										 	  TCP_PowerMeter.bySendData[3] := BYTE#16#14;//起始地址低字节	
											  TCP_PowerMeter.bySendData[4] := BYTE#16#00;//读取个数高字节
											  TCP_PowerMeter.bySendData[5] := BYTE#16#02;//读取个数低字节
									END_IF;
									TCP_PowerMeter.bySendData[0] := BYTE#16#01;//从站号
									TCP_PowerMeter.bySendData[1] := BYTE#16#03;//功能代码(读取通道过程值命令）
									TempWord.mWord := MEM.CRC16_Modbus(ADR(TCP_PowerMeter.bySendData), 6);//CRC_16校验				
									TCP_PowerMeter.bySendData[6] := TempWord.mByte[0];//CRC_16高字节	  
									TCP_PowerMeter.bySendData[7] := TempWord.mByte[1];//CRC_16低字节		
									
			//Clear(TCP_PowerMeter.byReadData);  //清除数据				
			AutoStep:=20;	
	20: 	//	等待反馈接收触发信号完成	
				IF 	TCP_PowerMeter.bySendData[0] = BYTE#00 
					OR TCP_PowerMeter.bSendDone
					//接收端清空发送数据为发送完成
				THEN
						AutoStep:=30;
				END_IF; 	
	 30:	//	等待反馈结果	
				IF  TCP_PowerMeter.byReadData[0] <> BYTE#00 //接收字节不为0
					AND TCP_PowerMeter.bReadDone
				THEN
						AutoStep:=40;
				END_IF;
	 40:	//	解析和采集数据
				//TempWord.mWord := MEM.CRC16_Modbus(ADR(TCP_PowerMeter.byReadData), 7);//CRC_16校验		
				//IF  TCP_PowerMeter.byReadData[7] = TempWord.mByte[0] //CRC_16高字节	  
				//	AND TCP_PowerMeter.byReadData[8] = TempWord.mByte[1] //CRC_16低字节
			//	THEN
						IF 		 ExecuteType = 'Uab' //三相线电压数据，单位 V(×0.1V)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.UabValue :=DWORD_TO_REAL(TempUn_DWord.mDword)	* 0.1 ;
								  ExecuteType :=  'Ubc' ;
						ELSIF  ExecuteType = 'Ubc'//三相线电压数据，单位 V(×0.1V)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.UbcValue :=DWORD_TO_REAL(TempUn_DWord.mDword)	* 0.1 ;	
								  ExecuteType :=  'Uca' ;
						ELSIF  ExecuteType = 'Uca'//三相线电压数据，单位 V(×0.1V)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.UcaValue :=DWORD_TO_REAL(TempUn_DWord.mDword)	* 0.1 ;	
								  ExecuteType :=  'Ia' ;
						ELSIF ExecuteType = 'Ia' //三相电流数据,单位 A(×0.001A)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.IaValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * 0.01;	
								  ExecuteType :=  'Ib' ;
						ELSIF ExecuteType = 'Ib'	//三相电流数据,单位 A(×0.001A)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.IbValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * 0.01;	
								  ExecuteType :=  'Ic' ;
						ELSIF ExecuteType = 'Ic'	//三相电流数据,单位 A(×0.001A)
						THEN
								TempUn_DWord.mByte[3] :=0;
								TempUn_DWord.mByte[2] :=0;
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[4];
								  Out.IcValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * 0.01;
								  ExecuteType :=  'Pt' ;
						ELSIF ExecuteType = 'Pt' //合相有功功率，单位 W(×0.1W)
						THEN		
								TempUn_DWord.mByte[3] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[2] :=TCP_PowerMeter.byReadData[4];
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[5];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[6];
								  Out.PtValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * (1.00 * 0.001) ;	
								  ExecuteType :=  'ImpEp' ;
						ELSIF ExecuteType = 'ImpEp'//（当前）正向有功总电能
						THEN
								TempUn_DWord.mByte[3] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[2] :=TCP_PowerMeter.byReadData[4];
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[5];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[6];
								  Out.ImpEpValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * (1.00 * 0.01) ;	
								  ExecuteType :=  'ExpEp' ;
						ELSIF  ExecuteType = 'ExpEp'  //（当前）反向有功总电能
						THEN
								TempUn_DWord.mByte[3] :=TCP_PowerMeter.byReadData[3];
								TempUn_DWord.mByte[2] :=TCP_PowerMeter.byReadData[4];
								TempUn_DWord.mByte[1] :=TCP_PowerMeter.byReadData[5];
								TempUn_DWord.mByte[0] :=TCP_PowerMeter.byReadData[6];
								  Out.ExpEpValue :=DWORD_TO_REAL(TempUn_DWord.mDword) * 40.00 * (1.00 * 0.01) ;	
								  ExecuteType :=  'Uab' ;
						END_IF;																						
			//	END_IF;
				IF  NOT TriggerMemory AND NOT H_In.Execute
					OR TriggerMemory AND NOT In.Execute
				THEN
						AutoStep:=50;	
				ELSE
						AutoStep:=10;	
				END_IF;										
	 50:	//	数据结果处理
		 		IF NOT TriggerMemory
					AND NOT H_In.Execute
				THEN
					AutoStep			:=		0;	
				ELSIF NOT In.Execute
						AND TriggerMemory
				THEN
					AutoStep			:=		0;	
				END_IF;
END_CASE;	
(******************************************** TCP功能块控制  *********************************************)
PowerMeterTCP.SendLen:=8;
 //发送间隔
 TP_SendInterval(In:=NOT TCP_PowerMeter.bSendDone, PT:=T#200MS);
//发送
IF AutoStep =20 
	AND (*NOT*) TP_SendInterval.Q
THEN
	TCP_PowerMeter.bSendExecute :=TRUE  ; //自动触发
ELSE
	TCP_PowerMeter.bSendExecute :=FALSE  ; //自动触发	
END_IF;
//等待接收反馈
IF Out.Busy
	AND NOT Out.Active
	AND TCP_PowerMeter.bSendDone 
THEN
		Clear(TCP_PowerMeter.bySendData);	
END_IF;
//等待接收完成
(********************************************	错误信息汇总		*********************************************)
IF NOT Reset
	AND NOT H_In.Disabled
THEN
		IF TON_RespondTimeOutAlarm.Q
		THEN
			ErrOut.ErrorID := 2;   //电能表反馈接收触发信号完成超时报警！请检查电能表和串口服务器是否正常运行！
		ELSIF TON_ResultTimeOutAlarm.Q
		THEN
			ErrOut.ErrorID := 3;   //电能表反馈结果超时报警！请检查电能表和串口服务器是否正常运行！
		ELSIF ( TCP_PowerMeter.byReadData[7] <> TempWord.mByte[1] //CRC_16高字节	  
					OR  TCP_PowerMeter.byReadData[8] <> TempWord.mByte[0]) //CRC_16低字节
				AND AutoStep > 40
		THEN
			ErrOut.ErrorID := 4;   //电能表反馈结果数据异常报警！请检查电能表和串口服务器是否正常运行！
		END_IF;
		IF RetryNumber < Parameter.RetryNumMax //重发计数
			AND ErrOut.ErrorID > 1
			AND ErrOut.ErrorID < 5
		THEN
				ErrOut.ErrorID := 0; 
				RetryNumber :=RetryNumber+1 ;
				AutoStep			:=		10;	
		END_IF;		
END_IF;
(********************************************	信号输出		*********************************************)
F_ManualTrigger(CLK:=H_In.Execute );	//手动下降沿触发						 
F_AutoTrigger(CLK:= In.Execute );	//自动下降沿触发	
IF  	NOT TriggerMemory	AND (F_ManualTrigger.Q OR 	NOT H_In.Execute  AND  Out.Done	)	
		OR  TriggerMemory	AND (F_AutoTrigger.Q OR NOT In.Execute  AND  Out.Done )	
THEN  //变为FALSE的时间: • Execute为TRUE时，与Execute的FALSE同时 • Execute为FALSE时，1个周期后
		Out.Done 		:= FALSE  ;
ELSIF AutoStep >40
THEN //变为TRUE的时间:指令完成时
		Out.Done 		:= TRUE  ;		
END_IF;								
Out.Busy			:= AutoStep <>0				//变为TRUE的时间:Execute的上升沿
							AND NOT Out.Done	//变为FALSE的时间:• Done变为TRUE时• Error变为TRUE时• CommandAborted变为TRUE时
							AND NOT ErrOut.Error
							AND NOT Out.CommandAborted ;			
Out.Active		:= AutoStep >20	//变为TRUE的时间:开始指令后
							AND NOT Out.Done	//变为FALSE的时间• Done变为TRUE时• Error变为TRUE时• CommandAborted变为TRUE时		
							AND NOT ErrOut.Error
							AND NOT Out.CommandAborted ;
IF 	TriggerMemory AND AutoStep <>0 AND ManualTrigger.Q   
	OR NOT TriggerMemory AND AutoStep <>0 AND AutoTrigger.Q	
	OR ErrOut.Error AND( ManualTrigger.Q  OR  AutoTrigger.Q	)
THEN //变为TRUE的时间:• 利用其它指令多重启动指令(中断)，中止本指令时• 因发生异常，中止本指令时• 发生异常过程中，启动本指令时• 停止指令执行中，启动本指令后
		Out.CommandAborted := TRUE;
ELSIF  NOT TriggerMemory	AND (F_ManualTrigger.Q OR 	NOT H_In.Execute  AND  Out.CommandAborted)	
		  OR  TriggerMemory	AND (F_AutoTrigger.Q OR NOT In.Execute  AND  Out.CommandAborted ) 
THEN //变为FALSE的时间• Execute为TRUE时，与Execute的FALSE同时 • Execute为FALSE时，1个周期后	
		Out.CommandAborted := FALSE;
END_IF;														
(********************************************	HMI信号输出		*********************************************)
H_Out.Done 				:= Out.Done ;
H_Out.Busy				:= Out.Busy;
H_Out.Active			:= Out.Active;	
H_Out.CommandAborted	:= Out.CommandAborted ;	
H_Out.UabValue			:= Out.UabValue;	
H_Out.UbcValue			:= Out.UbcValue;	
H_Out.UcaValue			:= Out.UcaValue;	
H_Out.IaValue			:= Out.IaValue;	
H_Out.IbValue			:= Out.IbValue;		
H_Out.IcValue			:= Out.IcValue;	
H_Out.PtValue			:= Out.PtValue;	
H_Out.ImpEpValue		:= Out.ImpEpValue;	
H_Out.ExpEpValue		:= Out.ExpEpValue;

(********************************************	参数初始化		*********************************************)	
		//TCP_PowerMeter.nSendDaSize	:=16;
	(************************************电能采集ModBus_RTU**************************************)			
	IF H_In.Disabled 	
	THEN
		Clear(Energy_DTSU666); 
		Clear(AutoStep); 
	END_IF; 
	//发送
	IF  NOT H_In.Disabled 					 //电能表启用
		AND Pulse.T_10s.Q
	THEN
				IF  AutoStep  = 0 					//组合有功总电能读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#33;//读取个数高字节
						EnSend[13] := BYTE#16#33;//读取个数低字节
						AutoStep := 150 ;
				END_IF;
				IF  AutoStep  = 10 					//正向有功总电能读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#34;//读取个数高字节
						EnSend[13] := BYTE#16#33;//读取个数低字节
						AutoStep := 160 ;
				END_IF;
				IF  AutoStep  =20 					//反向有功总电能读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#35;//读取个数高字节
						EnSend[13] := BYTE#16#33;//读取个数低字节
						AutoStep := 170 ;
				END_IF;
				IF AutoStep  = 30 					//A相电流读取
				   AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#34;//起始地址低字节
						EnSend[12] := BYTE#16#35;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 180 ;	
				END_IF;
				IF  AutoStep  = 40 			//B相电流读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[2] := BYTE#16#33;//起始地址高字节
						EnSend[3] := BYTE#16#35;//起始地址低字节
						EnSend[4] := BYTE#16#35;//读取个数高字节
						EnSend[5] := BYTE#16#35;//读取个数低字节
						AutoStep := 190 ;	
				END_IF; 
				IF  AutoStep  = 50				//C相电流读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#36;//起始地址低字节
						EnSend[12] := BYTE#16#35;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 200 ;	
				END_IF;
				IF  AutoStep  = 60				//A相电压读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#34;//起始地址低字节
						EnSend[12] := BYTE#16#34;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 210 ;	
				END_IF;
				IF  AutoStep  = 70					//B相电压读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#35;//起始地址低字节
						EnSend[12] := BYTE#16#34;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 220 ;	
				END_IF;
				IF  AutoStep  = 80				//C相电压读取
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#36;//起始地址低字节
						EnSend[12] := BYTE#16#34;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 230 ;	
				END_IF;
				IF  AutoStep  = 90				//总功率因数
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#39;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 240 ;	
				END_IF;
				IF  AutoStep  = 100			//瞬时总有功功率
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#33;//起始地址低字节
						EnSend[12] := BYTE#16#36;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 250 ;	
				END_IF;
				IF  AutoStep  = 110			//瞬时A相有功功率
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#34;//起始地址低字节
						EnSend[12] := BYTE#16#36;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 260 ;	
				END_IF;
				IF  AutoStep  = 120			//瞬时B相有功功率
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#35;//起始地址低字节
						EnSend[12] := BYTE#16#36;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 270 ;	
				END_IF;
				IF  AutoStep  = 130			//瞬时C相有功功率
					AND TCP_PowerMeter.bSendDone
				THEN
						EnSend[10] := BYTE#16#33;//起始地址高字节
						EnSend[11] := BYTE#16#36;//起始地址低字节
						EnSend[12] := BYTE#16#36;//读取个数高字节
						EnSend[13] := BYTE#16#35;//读取个数低字节
						AutoStep := 280 ;	
				END_IF;
				EnSend[0] := BYTE#16#68;//电能表起始帧
				EnSend[1] :=Parameter.DTSU666_Data[5];//电能表域地址A0，高低字节调换
				EnSend[2] := Parameter.DTSU666_Data[4];//电能表域地址A1
				EnSend[3] := Parameter.DTSU666_Data[3];//电能表域地址A2
				EnSend[4] := Parameter.DTSU666_Data[2];//电能表域地址A3
				EnSend[5] := Parameter.DTSU666_Data[1];//电能表域地址A4
				EnSend[6] := Parameter.DTSU666_Data[0];//电能表域地址A5
				EnSend[7] := BYTE#16#68;//电能表起始帧
				EnSend[8] := BYTE#16#11;//电能表控制码
				EnSend[9] := BYTE#16#04;//数据长度域
				EnSend[15] := BYTE#16#16;//结束符
			//运算校验码（从第一个帧起始符开始到校验码之前的所有个字节的模256的和）
				EnSend_INT[0]   :=  BYTE_TO_INT(EnSend[0]);
				EnSend_INT[1]   :=  BYTE_TO_INT(EnSend[1]);
				EnSend_INT[2]   :=  BYTE_TO_INT(EnSend[2]);
				EnSend_INT[3]   :=  BYTE_TO_INT(EnSend[3]);
				EnSend_INT[4]   :=  BYTE_TO_INT(EnSend[4]);
				EnSend_INT[5]   :=  BYTE_TO_INT(EnSend[5]);
				EnSend_INT[6]   :=  BYTE_TO_INT(EnSend[6]);
				EnSend_INT[7]   :=  BYTE_TO_INT(EnSend[7]);
				EnSend_INT[8]   :=  BYTE_TO_INT(EnSend[8]);
				EnSend_INT[9]   :=  BYTE_TO_INT(EnSend[9]);
                EnSend_INT[10]   :=  BYTE_TO_INT(EnSend[10]);
				EnSend_INT[11]   :=  BYTE_TO_INT(EnSend[11]);
				EnSend_INT[12]   :=  BYTE_TO_INT(EnSend[12]);
				EnSend_INT[13]   :=  BYTE_TO_INT(EnSend[13]);
				EnSend_SUM:=EnSend_INT[0]+EnSend_INT[1]+EnSend_INT[2]+EnSend_INT[3]+EnSend_INT[4]+EnSend_INT[5]+
				                         EnSend_INT[6]+EnSend_INT[7]+EnSend_INT[8]+EnSend_INT[9]+EnSend_INT[10]+EnSend_INT[11]+
										 EnSend_INT[12]+EnSend_INT[13];//相加
				EnSend_Word.mWord:=INT_TO_WORD(EnSend_SUM);
				EnSend[14]:=EnSend_Word.mByte[0];//校验码
				AryMove(EnSend[0],TCP_PowerMeter.bySendData[0],16);
				TCP_PowerMeter.bSendExecute:=TRUE;
	END_IF;
	//接收

	IF TCP_PowerMeter.bReadDone 
	THEN	
			AryMove(TCP_PowerMeter.byReadData[0],EnRead[0],30);		
			EnRead_Size:=TCP_PowerMeter.nReadDaSize;
			IF AutoStep  = 150 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	组合有功总电能读取
			        EnRead_INT[0]:=(BYTE_TO_INT(EnRead[EnRead_Size-6]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[0]);//32位的word运算
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[3]);
					Energy_DTSU666[0]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.01;	
					AutoStep := 10 ;
			END_IF;
			IF AutoStep  = 160 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	正向有功总电能读取
			        EnRead_INT[0]:=(BYTE_TO_INT(EnRead[EnRead_Size-6]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[0]);//32位的word运算
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[3]);
					Energy_DTSU666[1]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.01;	
					AutoStep := 20 ;
			END_IF;
			IF AutoStep  = 170 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	反向有功总电能读取
			        EnRead_INT[0]:=(BYTE_TO_INT(EnRead[EnRead_Size-6]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[0]);//32位的word运算
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[3]);
					Energy_DTSU666[2]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.01;	
					AutoStep := 30 ;
			END_IF;
			IF AutoStep  = 180 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	A相电流读取
			        EnRead_INT[0]:=INT#00;//电流读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[3]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.001;	//当前A相电流
					Energy_DTSU666[4] :=MAX(Energy_DTSU666[3],Energy_DTSU666[4]);//最大A相电流 		
					AutoStep := 40 ;
			END_IF;
			IF AutoStep  = 190 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	B相电流读取
			        EnRead_INT[0]:=INT#00;//电流读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[5]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.001;	//当前B相电流
					Energy_DTSU666[6] :=MAX(Energy_DTSU666[5],Energy_DTSU666[6]);//最大B相电流 		
					AutoStep := 50 ;
			END_IF;
			IF AutoStep  = 200 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	C相电流读取
			        EnRead_INT[0]:=INT#00;//电流读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[7]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.001;	//当前C相电流
					Energy_DTSU666[8] :=MAX(Energy_DTSU666[7],Energy_DTSU666[8]);//最大C相电流 		
					AutoStep := 60 ;
			END_IF;
			IF AutoStep  = 210 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	A相电压读取
			        EnRead_INT[0]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[1]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[2]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[3]);//32位的word运算，需要错位读取
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[9]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.1;	//当前A相电压
					Energy_DTSU666[10] :=MAX(Energy_DTSU666[9],Energy_DTSU666[10]);//最大A相电压	
					AutoStep := 70 ;
			END_IF;
			IF AutoStep  = 220 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	B相电压读取
			        EnRead_INT[0]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[1]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[2]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[3]);//32位的word运算，需要错位读取
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[11]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.1;	//当前B相电压
					Energy_DTSU666[12] :=MAX(Energy_DTSU666[11],Energy_DTSU666[12]);//最大B相电压	
					AutoStep := 80 ;
			END_IF;
			IF AutoStep  = 230 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	C相电压读取
			        EnRead_INT[0]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[1]:=INT#00;//电压读取只需读两个BYTE位
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[2]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[3]);//32位的word运算，需要错位读取
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[13]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.1;	//当前C相电压
					Energy_DTSU666[14] :=MAX(Energy_DTSU666[13],Energy_DTSU666[14]);//最大C相电压	
					AutoStep := 90 ;
			END_IF;
			IF AutoStep  = 240 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	总功率因数
			        EnRead_INT[0]:=INT#00;//总功率因数读取只需读两个BYTE位
					EnRead_INT[1]:=INT#00;//总功率因数读取只需读两个BYTE位
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[2]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[3]);//32位的word运算，需要错位读取
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[1]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[15]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.001;	//总功率因数
					AutoStep := 100 ;
			END_IF;
			IF AutoStep  = 250 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	瞬时总有功功率
			        EnRead_INT[0]:=INT#00;//功率读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[16]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.0001;	//瞬时总有功功率
					AutoStep := 110 ;
			END_IF;
			IF AutoStep  = 260 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	瞬时A相有功功率
			        EnRead_INT[0]:=INT#00;//功率读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[17]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.0001;	//瞬时A相有功功率
					AutoStep := 120 ;
			END_IF;
			IF AutoStep  = 270 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	瞬时B相有功功率
			        EnRead_INT[0]:=INT#00;//功率读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[18]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.0001;	//瞬时B相有功功率
					AutoStep := 130 ;
			END_IF;
			IF AutoStep  = 280 
				AND EnRead_Size<>0
				AND EnRead[4]=BYTE#16#68
			THEN//	瞬时C相有功功率
			        EnRead_INT[0]:=INT#00;//功率读取只需读三个BYTE位
					EnRead_INT[1]:=(BYTE_TO_INT(EnRead[EnRead_Size-5]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[2]:=(BYTE_TO_INT(EnRead[EnRead_Size-4]))-INT#16#33;//需要减去16进制的33
					EnRead_INT[3]:=(BYTE_TO_INT(EnRead[EnRead_Size-3]))-INT#16#33;//需要减去16进制的33
					EnRead_Dword.mByte[0]:=INT_TO_BYTE(EnRead_INT[1]);//32位的word运算，需要错位读取
                    EnRead_Dword.mByte[1]:=INT_TO_BYTE(EnRead_INT[2]);
					EnRead_Dword.mByte[2]:=INT_TO_BYTE(EnRead_INT[3]);
					EnRead_Dword.mByte[3]:=INT_TO_BYTE(EnRead_INT[0]);
					Energy_DTSU666[19]:= STRING_TO_REAL(DWORD_TO_STRING(EnRead_Dword.mDword))*REAL#0.0001;	//瞬时C相有功功率
					AutoStep := 0 ;
			END_IF;
			
	END_IF;
	//复位触发
	IF TCP_PowerMeter.bSendDone  
		OR TCP_PowerMeter.bReadDone 
		OR (Pulse.T_2s.Q
		AND TCP_PowerMeter.bSendExecute)
	THEN
			TCP_PowerMeter.bSendExecute:=FALSE;
	END_IF;


Out.ImpEpValue                  :=Energy_DTSU666[1];
Out.ExpEpValue                  :=Energy_DTSU666[2];
Out.IaValue                     :=Energy_DTSU666[3];
Out.IbValue                    	:=Energy_DTSU666[5];
Out.IcValue                     :=Energy_DTSU666[7];
Out.UabValue                   	:=Energy_DTSU666[9];
Out.UbcValue                  	:=Energy_DTSU666[11];
Out.UcaValue                  	:=Energy_DTSU666[13];
Out.Cos_tValue                  :=Energy_DTSU666[15];
Out.PtValue                  	:=Energy_DTSU666[16];
Out.PaValue                   	:=Energy_DTSU666[17];
Out.PbValue                     :=Energy_DTSU666[18];
Out.PcValue                     :=Energy_DTSU666[19];


H_Out.UabValue					:= Out.UabValue;	
H_Out.UbcValue					:= Out.UbcValue;	
H_Out.UcaValue					:= Out.UcaValue;	
H_Out.IaValue					:= Out.IaValue;	
H_Out.IbValue					:= Out.IbValue;		
H_Out.IcValue					:= Out.IcValue;	
H_Out.PtValue					:= Out.PtValue;	
H_Out.ImpEpValue				:= Out.ImpEpValue;	
H_Out.ExpEpValue				:= Out.ExpEpValue;

