//============================================================================================================
// Function block: Event_FC
//============================================================================================================
 // initialize
MsgBools_Alarm_Mark[Msg_Bools.Wrk_StartBit]:=FALSE;

// Event trrigger
IF Trigger AND Active_Precondition THEN                                                       
	Msg_Bools.B[Msg_Bools.Wrk_StartBit] := TRUE;//有报警标志
ELSIF Reset OR Msg_Category=10 OR Msg_Category=20   THEN  
	Msg_Bools.B[Msg_Bools.Wrk_StartBit] := FALSE;//无报警标志
	EventActive := FALSE;  
ELSIF Msg_Bools.B[Msg_Bools.Wrk_StartBit] THEN 
	Unit.EM[EM_Num].EventStatus.RequestReset:=TRUE;
END_IF;

IF Msg_Bools.B[Msg_Bools.Wrk_StartBit] THEN 
Unit.EM[EM_Num].EventStatus.Sts_CategoryFlag[Msg_Category]:=TRUE;
	IF Msg_Bools.FirstOutAlarm=0 AND Msg_Category<10  THEN 
		Msg_Bools.FirstOutAlarm:=Msg_Bools.Wrk_StartBit;
		Msg_Bools.FirstOutAlarmCat:=Msg_Category;
	END_IF;
	// 停机报警的标记
	IF Msg_Category < 10  THEN
		MsgBools_Alarm_Mark[Msg_Bools.Wrk_StartBit]:=TRUE;
	END_IF;	

END_IF;

// Msg_Bit +1，Msg_word +1
Msg_Bools.Wrk_StartBit := Msg_Bools.Wrk_StartBit + 1;

