	//额定扭矩
	Parameter.Axis_X1.TrqRatedValue:=100;
	Parameter.Axis_Y1.TrqRatedValue:=100;
	Parameter.Axis_Z1.TrqRatedValue:=100;
	Parameter.Axis_R1.TrqRatedValue:=100;
	//扭矩限制值
	Parameter.Axis_X1.TrqLimitValue:=900;
	Parameter.Axis_Y1.TrqLimitValue:=900;
	Parameter.Axis_Z1.TrqLimitValue:=900;
	Parameter.Axis_R1.TrqLimitValue:=900;
	//电流额定值
	Parameter.Axis_X1.ElectricRatedValue:=5000;
	Parameter.Axis_Y1.ElectricRatedValue:=5000;
	Parameter.Axis_Z1.ElectricRatedValue:=5000;
	Parameter.Axis_R1.ElectricRatedValue:=5000;
	//电流限制值
	Parameter.Axis_X1.ElectricLimitValue:=20000;
	Parameter.Axis_Y1.ElectricLimitValue:=20000;
	Parameter.Axis_Z1.ElectricLimitValue:=20000;
	Parameter.Axis_R1.ElectricLimitValue:=20000;
	//程序ID
	Parameter.ProgramID:=1;
	//参数初始化标志
	Parameter.DataInit:=TRUE;
END_IF;

(******************************************** 停止控制 *********************************************)
//手动下降沿
F_Manual(Clk:=Manual);
//机器人控制错误上升沿
R_Alarm(Clk:=ErrOut.Alarm);


(******************************************** EIP输入映射 *********************************************)
IF TRUE THEN
(*====状态字====*)
StatusWord_Bit.mByte[0]:=EIP_Input[0];
StatusWord_Bit.mByte[1]:=EIP_Input[1];
FC_WordToAryBool(StatusWord_Bit.mWord,0,StatusWord_mBit,0,16);
Out.Ready	:=	StatusWord_mBit[0]	;//	系统就绪
Out.Running	:=	StatusWord_mBit[1]	;//	运行中
Out.Paused	:=	StatusWord_mBit[2]	;//	暂停中
Out.Stopped	:=	StatusWord_mBit[3]	;//	停止中
Out.ProgramError	:=	StatusWord_mBit[4]	;//	软件程序错误
Out.SafetyDoorOK	:=	StatusWord_mBit[5]	;//	安全门OK
Out.EmgStopOK	:=	StatusWord_mBit[6]	;//	急停OK
Out.RobotError	:=	StatusWord_mBit[7]	;//	控制器故障
Out.RobotWarning	:=	StatusWord_mBit[8]	;//	控制器警告
Out.EnableOK	:=	StatusWord_mBit[9]	;//	伺服使能OK
Out.Acknowledged	:=	StatusWord_mBit[10]	;//	ACK确认按钮状态
Out.RobotMode      :=  StatusWord_mBit[12]	;//	远程模式（等于1远程，等于0手动）

(*====实时坐标读取====*)
FOR K:=0 TO 3 DO 
 EIP_Input_TempDWord[K+0].mByte[0]:=EIP_Input[K*4+13];
 EIP_Input_TempDWord[K+0].mByte[1]:=EIP_Input[K*4+14];
 EIP_Input_TempDWord[K+0].mByte[2]:=EIP_Input[K*4+15];
 EIP_Input_TempDWord[K+0].mByte[3]:=EIP_Input[K*4+16];
END_FOR;
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[0].mDWord , Out=>Out.Axis_X1.ActPos );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[1].mDWord , Out=>Out.Axis_Y1.ActPos );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[2].mDWord , Out=>Out.Axis_Z1.ActPos );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[3].mDWord , Out=>Out.Axis_R1.ActPos );
(*====控制器故障代码====*)
EIP_Input_TempWord[0].mByte[0]:=EIP_Input[47];
EIP_Input_TempWord[0].mByte[1]:=EIP_Input[48];
Out.RobotErrID:=EIP_Input_TempWord[0].mWord;

(*====实时扭矩读取====*)
FOR K:=0 TO 3 DO 
 EIP_Input_TempDWord[K+4].mByte[0]:=EIP_Input[K*4+31];
 EIP_Input_TempDWord[K+4].mByte[1]:=EIP_Input[K*4+32];
 EIP_Input_TempDWord[K+4].mByte[2]:=EIP_Input[K*4+33];
 EIP_Input_TempDWord[K+4].mByte[3]:=EIP_Input[K*4+34];
END_FOR;
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[4].mDWord , Out=>Out.Axis_X1.ActTorque );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[5].mDWord , Out=>Out.Axis_Y1.ActTorque );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[6].mDWord , Out=>Out.Axis_Z1.ActTorque );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[7].mDWord , Out=>Out.Axis_R1.ActTorque );
(*====实时电流读取====*)
FOR K:=0 TO 3 DO 
 EIP_Input_TempDWord[K+8].mByte[0]:=EIP_Input[K*4+49];
 EIP_Input_TempDWord[K+8].mByte[1]:=EIP_Input[K*4+50];
 EIP_Input_TempDWord[K+8].mByte[2]:=EIP_Input[K*4+51];
 EIP_Input_TempDWord[K+8].mByte[3]:=EIP_Input[K*4+52];
END_FOR;
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[8].mDWord , Out=>Out.Axis_X1.ActElectric );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[9].mDWord , Out=>Out.Axis_Y1.ActElectric );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[10].mDWord , Out=>Out.Axis_Z1.ActElectric );
HC_OmronUtils.CopyDwordToReal(In:=EIP_Input_TempDWord[11].mDWord , Out=>Out.Axis_R1.ActElectric );
(*====安全区域信号读取====*)
//EIP_Input_TempByte[6].mByte:=EIP_Input[6];
BYTE_UNPACK_IN[6](
	B:=EIP_Input[6] , 
	B0=> EIP_Input_Tempmbit[6,0], 
	B1=> EIP_Input_Tempmbit[6,1], 
	B2=> EIP_Input_Tempmbit[6,2], 
	B3=> EIP_Input_Tempmbit[6,3], 
	B4=> EIP_Input_Tempmbit[6,4], 
	B5=> EIP_Input_Tempmbit[6,5], 
	B6=> EIP_Input_Tempmbit[6,6], 
	B7=> EIP_Input_Tempmbit[6,7]);
Out.SafetyArea[0]	:=	EIP_Input_TempmBit[6,0]	;
Out.SafetyArea[1]	:=	EIP_Input_TempmBit[6,1]	;
Out.SafetyArea[2]	:=	EIP_Input_TempmBit[6,2]	;
Out.SafetyArea[3]	:=	EIP_Input_TempmBit[6,3]	;
Out.SafetyArea[4]	:=	EIP_Input_TempmBit[6,4]	;
Out.SafetyArea[5]	:=	EIP_Input_TempmBit[6,5]	;
Out.SafetyArea[6]	:=	EIP_Input_TempmBit[6,6]	;
Out.SafetyArea[7]	:=	EIP_Input_TempmBit[6,7]	;

END_IF;

(******************************************** EIP输出映射 *********************************************)
IF TRUE THEN
(*====控制字====*)
//停止
IF  ( In.Stop
	OR H_In.Stop)
	AND Out.Running
THEN 
ControlWord_mBit[0]:=TRUE;
ELSE
ControlWord_mBit[0]:=FALSE;
END_IF;

//启动
IF ((In.Run AND Auto
	OR H_In.Run AND Manual)
	AND NOT Aborting
	AND NOT ErrOut.Alarm)
	OR (Rebound_Execute AND NOT Out.Paused)
THEN 
ControlWord_mBit[1]:=TRUE ;
ELSE
ControlWord_mBit[1]:=FALSE ;
END_IF;

//暂停
IF (Aborting
	OR R_Alarm.Q
	OR In.Pause AND Auto
	OR H_In.Pause AND Manual)
THEN 
ControlWord_mBit[2]:=TRUE ;
ELSE
ControlWord_mBit[2]:=FALSE ;
END_IF;

//继续运行
IF ((In.bContinue AND Auto
	OR H_In.bContinue AND Manual)
	AND NOT Aborting
	AND NOT ErrOut.Alarm)
	OR (Rebound_Execute AND Out.Paused)
THEN 
ControlWord_mBit[3]:=TRUE ;
ELSE
ControlWord_mBit[3]:=FALSE ;
END_IF;

//终止并卸载程序
IF  (In.SystemStop AND Auto
	OR H_In.SystemStop AND Manual
	OR Out.ProgramError AND Reset)
THEN 
ControlWord_mBit[4]:=TRUE;
ELSE
ControlWord_mBit[4]:=FALSE;
END_IF;

//伺服使能
TON_Enable(
	In:=EmgStop
	AND Out.Ready
	AND NOT H_In.DisEnable
	AND NOT ErrOut.NoEnableErr
	, PT:=T#500MS);
IF TON_Enable.Q
THEN
Enable_M:=TRUE;
ELSE
Enable_M:=FALSE;
END_IF;
ControlWord_mBit[5]:=Enable_M;

//程序ID转换
ProgramIDWord_Bit.mWord:=INT_TO_WORD(Parameter.ProgramID);
FC_WordToAryBool(ProgramIDWord_Bit.mWord,0,ProgramIDWord_mBit,0,16);
ControlWord_mBit[6]	:=	ProgramIDWord_mBit[0]	;//	远程 ID 中的第一位（AppID0）
ControlWord_mBit[7]	:=	ProgramIDWord_mBit[1]	;//	远程 ID 中的第二位
ControlWord_mBit[8]	:=	ProgramIDWord_mBit[2]	;//	远程 ID 中的第三位
ControlWord_mBit[9]	:=	ProgramIDWord_mBit[3]	;//	远程 ID 中的第四位
ControlWord_mBit[10]	:=	ProgramIDWord_mBit[4]	;//	远程 ID 中的第五位
ControlWord_mBit[11]	:=	ProgramIDWord_mBit[5]	;//	远程 ID 中的第六位

//报警复位
IF  (Reset OR H_In.bReset)
THEN 
ControlWord_mBit[12]:=TRUE;
ELSE
ControlWord_mBit[12]:=FALSE;
END_IF;

//控制字写入
FC_AryBoolToWord(AryBool:=ControlWord_mBit , AryWord:=ControlWord_Bit );
EIP_Output[0]:=ControlWord_Bit.mByte[0];
EIP_Output[1]:=ControlWord_Bit.mByte[1];


(*====机器人的速度====*)
R_Add(Clk:=H_In.SpeedAdd);
R_Dec(Clk:=H_In.SpeedDec);
IF Parameter.Speed<=95 AND R_Add.Q THEN
	Parameter.Speed:=Parameter.Speed+5;
END_IF;
IF Parameter.Speed>=10 AND R_Dec.Q THEN
	Parameter.Speed:=Parameter.Speed-5;
END_IF;
//急停触发判断
IF EmgStop THEN
	EmgStopTemp:=TRUE;
END_IF;
IF EmgStopTemp
	AND NOT EmgStop
THEN
	EmgStopTemp:=FALSE;
	//Parameter.SpeedLimitTemp:=FALSE;
END_IF;

Parameter.SpeedLimitTemp:=NOT EmgStopTemp;
			
//限制指令速度
IF Parameter.SpeedLimitTemp THEN
	Parameter.CmdSpeed:=5;
ELSE
	Parameter.CmdSpeed:=Parameter.Speed;
END_IF;
//机器人速度控制
IF Manual//手动
	OR In.Rebound_Execute
THEN
	RobotSpeedWord_Bit.mWord:=REAL_TO_WORD(3);
ELSIF Auto//自动
THEN
	RobotSpeedWord_Bit.mWord:=REAL_TO_WORD(MIN(GeneralOverride, Parameter.CmdSpeed));
END_IF;
IF RobotSpeedWord_Bit.mWord=0 THEN
	RobotSpeedWord_Bit.mWord:=REAL_TO_WORD(5);
END_IF;
EIP_Output[2]:=RobotSpeedWord_Bit.mByte[0];
EIP_Output[3]:=RobotSpeedWord_Bit.mByte[1];

(*====机器人偏移量====*)
HC_OmronUtils.CopyRealToDword(In:=Parameter.Axis_X1.OffsetValue , Out=>EIP_Output_TempDWord[0].mDWord );
HC_OmronUtils.CopyRealToDword(In:=Parameter.Axis_Y1.OffsetValue , Out=>EIP_Output_TempDWord[1].mDWord );
HC_OmronUtils.CopyRealToDword(In:=Parameter.Axis_Z1.OffsetValue , Out=>EIP_Output_TempDWord[2].mDWord );
HC_OmronUtils.CopyRealToDword(In:=Parameter.Axis_R1.OffsetValue , Out=>EIP_Output_TempDWord[3].mDWord );
FOR K:=0 TO 3 DO 
	EIP_Output[K*4+31]:=EIP_Output_TempDWord[K].mByte[0];
	EIP_Output[K*4+32]:=EIP_Output_TempDWord[K].mByte[1];
	EIP_Output[K*4+33]:=EIP_Output_TempDWord[K].mByte[2];
	EIP_Output[K*4+34]:=EIP_Output_TempDWord[K].mByte[3];
END_FOR;

END_IF;

(******************************************** 确认按钮 *********************************************)
TOF_ConfirmOutput(
	In:=(EmgStop
	AND (NOT Out.Ready
	OR NOT Out.EnableOK)
	AND Reset)
	OR H_In.ConfirmButton
	, PT:=T#1S);
IF TOF_ConfirmOutput.Q
THEN
	Out.ConfirmOutput:=TRUE;
ELSE
	Out.ConfirmOutput:=FALSE;
END_IF;

(******************************************** 指令复位 *********************************************)
IF Aborting
	OR R_Alarm.Q
THEN
	Clear(In.ToPos);
	Clear(H_In.ToPos);
END_IF;

IF Manual THEN
	Clear(In.ToPos);
ELSIF Auto THEN
	Clear(H_In.ToPos);
END_IF;


(******************************************** 机器人定位控制 *********************************************)
IF EIP_Output[4]<>0 THEN
EIP_Output[4]:=0;
END_IF;
FOR K:=0 TO 40 DO 
		IF In.Location_SafeCondition[K]
			AND ((In.ToPos[K] AND Auto )
			OR (H_In.ToPoS[K] AND Manual))
        THEN
			IF EIP_Output[4] =0 THEN
				EIP_Output[4]:=INT_TO_BYTE(K+1);
			END_IF;
        END_IF;
END_FOR;


(******************************************** 机器人到位状态 *********************************************)
FOR K:=0 TO 40 DO
Out.PosDone[K]:=EIP_Input[4] = INT_TO_BYTE(K+1);
END_FOR;
//复位定位指令
FOR K:=0 TO 40 DO 
	IF Out.PosDone[K]
	THEN
		In.ToPos[K]:=FALSE;
		H_In.ToPos[K]:=FALSE;
	END_IF;
END_FOR;


(******************************************** 模式切换 *********************************************)
EIP_Output_TempMBit[81,0] := NOT (Parameter.RobotMode AND Manual);
EIP_Output_TempMBit[81,1] :=  Parameter.RobotMode AND Manual;


(******************************************** P点写入 *********************************************)		
//写入P点信号输入
EIP_Output_TempWord[44].mWord := INT_TO_WORD(H_In.H_Pos_Number);
EIP_Output_TempByte[87]:= EIP_Output_TempWord[44].mByte[0];
EIP_Output_TempByte[88]:= EIP_Output_TempWord[44].mByte[1];
//写入点位成功信号
H_Out.GetPosDone:=EIP_Input_TempmBit[81,0]; 
//运动超限报警信号
H_Out.ROB_OUT_OFFS_AREA:=EIP_Input_TempmBit[81,1]; 
//机器人在JOG移动中信号
H_Out.ROB_BUSY:=EIP_Input_TempmBit[81,2]; 

//EIP_Input_TempByte[81].mByte :=	EIP_Input[81];
BYTE_UNPACK_IN[81](
	B:=EIP_Input[81] , 
	B0=> EIP_Input_TempmBit[81,0], 
	B1=> EIP_Input_TempmBit[81,1], 
	B2=> EIP_Input_TempmBit[81,2], 
	B3=> EIP_Input_TempmBit[81,3], 
	B4=> EIP_Input_TempmBit[81,4], 
	B5=> EIP_Input_TempmBit[81,5], 
	B6=> EIP_Input_TempmBit[81,6], 
	B7=> EIP_Input_TempmBit[81,7]);
	
	TON_Write_P(In:=Write_P_Step=10, PT:=T#10S);
CASE Write_P_Step OF
	0://判断写入信号
		IF Parameter.RobotMode
			AND Manual
			AND H_In.H_Position
			AND H_In.H_Pos_Number <>0
			AND NOT EIP_Input_TempmBit[81,0]
		THEN 
			Write_P_Step :=10;
		END_IF;
	10://触发写入P点
		EIP_Output_TempmBit[81,3] := TRUE;
		IF EIP_Input_TempmBit[81,0]
		THEN 			
			Write_P_Step :=20;
			TON_Write_P(In:=FALSE, PT:=T#10S);
		ELSIF TON_Write_P.Q		//写入超时
		THEN 
			Write_P_Step :=20;
			EIP_Output_TempmBit[81,3] := FALSE;
			TON_Write_P(In:=FALSE, PT:=T#10S);
		END_IF;
	20://复位信号	
		EIP_Output_TempmBit[81,3] := FALSE; 
		H_In.H_Position := FALSE;
		H_In.H_Pos_Number := 0;
		IF NOT EIP_Input_TempmBit[81,0]
		THEN 
			Write_P_Step :=0;	
		END_IF;
END_CASE;


(******************************************** 机器人运动方式写入 *********************************************)
EIP_Output_TempWord[42].mWord := REAL_TO_WORD(1);


EIP_Output_TempByte[83]:= EIP_Output_TempWord[42].mByte[0];

EIP_Output_TempByte[84]:= EIP_Output_TempWord[42].mByte[1];


(******************************************** 示教模式机器人微动控制 *********************************************)
//轴JOG控制模式
EIP_Output_TempmBit[81,2] := H_In.IN_IS_INCH;
//轴JOG控制寸动距离
IF H_In.IN_IS_INCH THEN 
	IF H_In.RelPOS >1 AND H_In.RelPOS<=100 THEN 
		EIP_Output_TempWord[43].mWord := REAL_TO_WORD(H_In.RelPOS);
		EIP_Output_TempByte[85]:= EIP_Output_TempWord[43].mByte[0];
		EIP_Output_TempByte[86]:= EIP_Output_TempWord[43].mByte[1];
	ELSE
		EIP_Output_TempWord[43].mWord :=0;
		EIP_Output_TempByte[85]:= 0;
		EIP_Output_TempByte[86]:= 0;
	END_IF;
ELSE
		EIP_Output_TempWord[43].mWord :=0;
		EIP_Output_TempByte[85]:= 0;
		EIP_Output_TempByte[86]:= 0;
END_IF;

//轴JOG速度
EIP_Output_TempWord[45].mWord := REAL_TO_WORD(5);
EIP_Output_TempByte[89]:= EIP_Output_TempWord[45].mByte[0];
EIP_Output_TempByte[90]:= EIP_Output_TempWord[45].mByte[1];

///轴JOG控制
EIP_Output_TempmBit[82,0] :=	H_In.X_JOG_ADD	;	//	X_Jog+
EIP_Output_TempmBit[82,2] :=	H_In.Y_JOG_ADD	;	//	Y_Jog+
EIP_Output_TempmBit[82,4] :=	H_In.Z_JOG_ADD	;	//	Z_Jog+
EIP_Output_TempmBit[82,6] :=	H_In.R_JOG_ADD	;	//	R_Jog+
               
EIP_Output_TempmBit[82,1]:=	H_In.X_JOG_SUB	;	//	X_Jog-
EIP_Output_TempmBit[82,3]:=	H_In.Y_JOG_SUB	;	//	Y_Jog-
EIP_Output_TempmBit[82,5]:=	H_In.Z_JOG_SUB	;	//	Z_Jog-
EIP_Output_TempmBit[82,7]:=	H_In.R_JOG_SUB	;	//	R_Jog-

Bit_As_Out[81](
	B0:= EIP_OUTput_TempmBit[81,0], 
	B1:= EIP_OUTput_TempmBit[81,1], 
	B2:= EIP_OUTput_TempmBit[81,2], 
	B3:= EIP_OUTput_TempmBit[81,3], 
	B4:= EIP_OUTput_TempmBit[81,4], 
	B5:= EIP_OUTput_TempmBit[81,5], 
	B6:= EIP_OUTput_TempmBit[81,6], 
	B7:= EIP_OUTput_TempmBit[81,7], 
	B=> EIP_Output_TempByte[81]);
Bit_As_Out[82](
	B0:= EIP_OUTput_TempmBit[82,0], 
	B1:= EIP_OUTput_TempmBit[82,1], 
	B2:= EIP_OUTput_TempmBit[82,2], 
	B3:= EIP_OUTput_TempmBit[82,3], 
	B4:= EIP_OUTput_TempmBit[82,4], 
	B5:= EIP_OUTput_TempmBit[82,5], 
	B6:= EIP_OUTput_TempmBit[82,6], 
	B7:= EIP_OUTput_TempmBit[82,7], 
	B=> EIP_Output_TempByte[82]);
	

EIP_Output[81] := EIP_Output_TempByte[81];
EIP_Output[82] := EIP_Output_TempByte[82];
EIP_Output[83] := EIP_Output_TempByte[83];
EIP_Output[84] := EIP_Output_TempByte[84];
EIP_Output[85] := EIP_Output_TempByte[85];
EIP_Output[86] := EIP_Output_TempByte[86];
EIP_Output[87] := EIP_Output_TempByte[87];
EIP_Output[88] := EIP_Output_TempByte[88];
EIP_Output[89] := EIP_Output_TempByte[89];
EIP_Output[90] := EIP_Output_TempByte[90];


(******************************************** 防撞回弹程序 *********************************************)
TON_ReboundCondition(In:=In.Rebound_Execute AND NOT Out.Running AND ReboundStep=0, PT:=T#100ms);
TP_Rebound_Execute(In:=TON_ReboundCondition.Q, PT:=T#2S);
Rebound_Execute:=TP_Rebound_Execute.Q;
TON_ReboundOverTimes(In:=ReboundStep<>0, PT:=T#10S);

//反弹步骤
CASE ReboundStep OF
	0://反弹触发
		IF Rebound_Execute THEN
			ReboundStep:=100;
		END_IF;
	100://等待恢复
		IF (NOT In.Rebound_Execute
			AND TON_ReboundOverTimes.Q
			OR NOT Out.Running)
			AND NOT Rebound_Execute
		THEN
			ReboundStep:=110;
		END_IF;
	110://
		ReboundStep:=0;
END_CASE;

ReboundWord_Bit.mByte[0].0:=Rebound_Execute ;
EIP_Output[29]:=ReboundWord_Bit.mByte[0];


(******************************************** 报警复位 *********************************************)
IF H_In.bReset OR Reset THEN
	ErrOut:=ErrOut_Clear;
END_IF;


(******************************************** 错误信息 *********************************************)
// IF _EIP_RegTargetSta[Node]
// 	AND NOT _EIP_EstbTargetSta[Node]
// 	AND (Manual OR Auto)
// THEN
// 	ErrOut.ConnectedErr:=TRUE;//网络链接错误
// END_IF;

IF NOT Out.EmgStopOK THEN
	ErrOut.EmgStopErr:=TRUE;//安全急停错误
END_IF;

IF NOT Out.SafetyDoorOK THEN
	ErrOut.SafetyDoorErr:=TRUE;//安全门错误
END_IF;

IF NOT Out.Ready THEN
	ErrOut.NoReadyErr:=TRUE;//未准备就绪错误
END_IF;

TON_EnableErr(
	In:=Enable_M
	AND NOT Out.EnableOK
	, PT:=T#10S);
IF TON_EnableErr.Q
	OR (Auto AND NOT Out.EnableOK)
THEN
	ErrOut.NoEnableErr:=TRUE;//未使能错误
END_IF;

TON_RunningErr(
	In:=Auto
	AND (In.Run OR In.bContinue)
	AND NOT Out.Running
	, PT:=T#5S);
IF TON_RunningErr.Q
THEN
	ErrOut.NoRunningErr:=TRUE;//未运行错误
END_IF;

TON_UnExcutedErr(
	In:=Auto
	AND Out.Running
	AND EIP_Output[4]<>0
	AND EIP_Output[4]<>EIP_Input[4]
	, PT:=T#60S);
IF TON_UnExcutedErr.Q
THEN
	ErrOut.UnExcutedErr:=TRUE;//未执行命令错误
END_IF;

FOR K:=0 TO 40 DO
	IF ((In.ToPos[K] AND NOT In.Location_SafeCondition[K])
		OR (H_In.ToPos[K] AND NOT In.Location_SafeCondition[K]))
		AND Out.Running
	THEN
		ErrOut.MovingHinderErr:=TRUE;//移动中干涉
	END_IF;
END_FOR;

IF In.Rebound_Execute THEN
	ErrOut.AvoidErr:=TRUE;//防撞感应错误
END_IF;


IF H_Out.Axis_X1.ActTrqMaxClear
THEN
	Out.Axis_X1.ActTorqueMax:=0;
ELSIF NOT ErrOut.AxisXLimitTrqErr
THEN
	Out.Axis_X1.ActTorqueMax:=MAX(ABS(Out.Axis_X1.ActTorque),ABS(Out.Axis_X1.ActTorqueMax));
END_IF;
IF Out.Axis_X1.ActTorqueMax>=Parameter.Axis_X1.TrqLimitValue THEN
	ErrOut.AxisXLimitTrqErr:=TRUE;//X轴超出限制扭矩值错误
END_IF;
IF H_Out.Axis_Y1.ActTrqMaxClear
THEN
	Out.Axis_Y1.ActTorqueMax:=0;
ELSIF NOT ErrOut.AxisYLimitTrqErr
THEN
	Out.Axis_Y1.ActTorqueMax:=MAX(ABS(Out.Axis_Y1.ActTorque), ABS(Out.Axis_Y1.ActTorqueMax));
END_IF;
IF Out.Axis_Y1.ActTorqueMax>=Parameter.Axis_Y1.TrqLimitValue THEN
	ErrOut.AxisYLimitTrqErr:=TRUE;//Y轴超出限制扭矩值错误
END_IF;
