IF Out.Axis_R1.ActElectricMax>=Parameter.Axis_R1.ElectricLimitValue THEN
	ErrOut.AxisRLimitElectricErr:=TRUE;//R轴超出限制电流值错误
END_IF;

(*====自定义故障====*)
EIP_Input_TempByte[10]:=EIP_Input[10];
BYTE_UNPACK_IN[10](
	B:= EIP_Input_TempByte[10], 
	B0=> Eip_Input_TempmBit[10,0], 
	B1=> Eip_Input_TempmBit[10,1], 
	B2=> Eip_Input_TempmBit[10,2], 
	B3=> Eip_Input_TempmBit[10,3], 
	B4=> Eip_Input_TempmBit[10,4], 
	B5=> Eip_Input_TempmBit[10,5], 
	B6=> Eip_Input_TempmBit[10,6], 
	B7=> Eip_Input_TempmBit[10,7]);
IF Eip_Input_TempmBit[10,0] THEN
	ErrOut.RobotUseAlarm[0]:=TRUE;//机器人点位手系示教错误报警
END_IF;
IF Eip_Input_TempmBit[10,1] THEN
	ErrOut.RobotUseAlarm[1]:=TRUE;//机器人不在安全位置报警
END_IF;
IF Eip_Input_TempmBit[10,2] THEN
	ErrOut.RobotUseAlarm[2]:=TRUE;//PLC程序号发送错误报警
END_IF;
IF Eip_Input_TempmBit[10,3] THEN
	ErrOut.RobotUseAlarm[3]:=TRUE;//PLC偏移数据发送错误，超出安全范围报警
END_IF;
IF Eip_Input_TempmBit[10,4] THEN
	ErrOut.RobotUseAlarm[4]:=TRUE;//机器人防撞报警触发报警
END_IF;
IF Eip_Input_TempmBit[10,5] THEN
	ErrOut.RobotUseAlarm[5]:=TRUE;//机器人模拟模式被打开报警
END_IF;



(******************************************** 机器人报警汇总 *********************************************)
IF FALSE
	OR ErrOut.ConnectedErr//网络链接错误
	OR ErrOut.EmgStopErr//安全急停错误
	OR ErrOut.SafetyDoorErr//安全门错误
	OR ErrOut.NoReadyErr//未准备就绪错误
	OR ErrOut.NoEnableErr//未使能错误
	OR ErrOut.NoRunningErr//未运行错误
	OR ErrOut.UnExcutedErr//未执行命令错误
	OR ErrOut.MovingHinderErr//移动中干涉
	OR ErrOut.AvoidErr//防撞感应错误
	OR ErrOut.AxisXLimitTrqErr//X轴超出限制扭矩值错误
	OR ErrOut.AxisYLimitTrqErr//Y轴超出限制扭矩值错误
	OR ErrOut.AxisZLimitTrqErr//Z轴超出限制扭矩值错误
	OR ErrOut.AxisRLimitTrqErr//R轴超出限制扭矩值错误
	OR ErrOut.AxisXLimitElectricErr//X轴超出限制电流值错误
	OR ErrOut.AxisYLimitElectricErr//Y轴超出限制电流值错误
	OR ErrOut.AxisZLimitElectricErr//Z轴超出限制电流值错误
	OR ErrOut.AxisRLimitElectricErr//R轴超出限制电流值错误
	OR ErrOut.RobotUseAlarm[0]//机器人点位手系示教错误报警
	OR ErrOut.RobotUseAlarm[1]//机器人不在安全位置报警
	OR ErrOut.RobotUseAlarm[2]//PLC程序号发送错误报警
	OR ErrOut.RobotUseAlarm[3]//PLC偏移数据发送错误，超出安全范围报警
	OR ErrOut.RobotUseAlarm[4]//机器人防撞报警触发报警
	OR ErrOut.RobotUseAlarm[5]//机器人模拟模式被打开报警
	OR Out.RobotError//控制器故障
	OR Out.ProgramError//软件程序错误
THEN
	ErrOut.Alarm:=TRUE;
END_IF;


(******************************************** 机器人错误代码输出 *********************************************)
IF TRUE THEN;

	IF ErrOut.ConnectedErr
	THEN
		ErrOut.bErrID:=1;//网络链接错误
		
	ELSIF ErrOut.EmgStopErr
	THEN
		ErrOut.bErrID:=2;//安全急停错误
		
	ELSIF ErrOut.SafetyDoorErr
	THEN
		ErrOut.bErrID:=3;//安全门错误
		
	ELSIF ErrOut.NoReadyErr
	THEN
		ErrOut.bErrID:=4;//未准备就绪错误
		
	ELSIF ErrOut.NoEnableErr
	THEN
		ErrOut.bErrID:=5;//未使能错误
		
	ELSIF ErrOut.NoRunningErr
	THEN
		ErrOut.bErrID:=6;//未运行错误
		
	ELSIF ErrOut.UnExcutedErr
	THEN
		ErrOut.bErrID:=7;//未执行命令错误
		
	ELSIF ErrOut.MovingHinderErr
	THEN
		ErrOut.bErrID:=8;//移动中干涉
		
	ELSIF ErrOut.AxisXLimitTrqErr
	THEN
		ErrOut.bErrID:=9;//X轴超出限制扭矩值错误
		
	ELSIF ErrOut.AxisYLimitTrqErr
	THEN
		ErrOut.bErrID:=10;//Y轴超出限制扭矩值错误
		
	ELSIF ErrOut.AxisZLimitTrqErr
	THEN
		ErrOut.bErrID:=11;//Z轴超出限制扭矩值错误
		
	ELSIF ErrOut.AxisRLimitTrqErr
	THEN
		ErrOut.bErrID:=12;//R轴超出限制扭矩值错误
		
	ELSIF ErrOut.AvoidErr
	THEN
		ErrOut.bErrID:=13;//防撞感应错误
	
	ELSIF ErrOut.AxisXLimitElectricErr
	THEN
		ErrOut.bErrID:=14;//X轴超出限制电流值错误
		
	ELSIF ErrOut.AxisYLimitElectricErr
	THEN
		ErrOut.bErrID:=15;//Y轴超出限制电流值错误
		
	ELSIF ErrOut.AxisZLimitElectricErr
	THEN
		ErrOut.bErrID:=16;//Z轴超出限制电流值错误
		
	ELSIF ErrOut.AxisRLimitElectricErr
	THEN
		ErrOut.bErrID:=17;//R轴超出限制电流值错误
	
	
	ELSIF ErrOut.RobotUseAlarm[0]
	THEN
		ErrOut.bErrID:=50;//机器人点位手系示教错误报警
		
	ELSIF ErrOut.RobotUseAlarm[1]
	THEN
		ErrOut.bErrID:=51;//机器人不在安全位置报警
		
	ELSIF ErrOut.RobotUseAlarm[2]
	THEN
		ErrOut.bErrID:=52;//PLC程序号发送错误报警
		
	ELSIF ErrOut.RobotUseAlarm[3]
	THEN
		ErrOut.bErrID:=53;//PLC偏移数据发送错误，超出安全范围报警
		
	ELSIF ErrOut.RobotUseAlarm[4]
	THEN
		ErrOut.bErrID:=54;//机器人防撞报警触发报警
		
	ELSIF ErrOut.RobotUseAlarm[5]
	THEN
		ErrOut.bErrID:=55;//机器人模拟模式被打开报警
		
		
	ELSIF Out.RobotError
	THEN
		ErrOut.bErrID:=98;//控制器故障
		
	ELSIF Out.ProgramError
	THEN
		ErrOut.bErrID:=99;//软件程序错误
		
	ELSIF ErrOut.Alarm
	THEN
		ErrOut.bErrID:=100;//其他错误
	END_IF;


END_IF;


(******************************************** HMI信号输出 *********************************************)
H_Out.Ready	:=	Out.Ready	;//	系统就绪
H_Out.Running	:=	Out.Running	;//	运行中
H_Out.Paused	:=	Out.Paused	;//	暂停中
H_Out.Stopped	:=	Out.Stopped	;//	停止中
H_Out.ProgramError	:=	Out.ProgramError	;//	软件程序错误
H_Out.SafetyDoorOK	:=	Out.SafetyDoorOK	;//	安全门OK
H_Out.EmgStopOK	:=	Out.EmgStopOK	;//	急停OK
H_Out.RobotError	:=	Out.RobotError	;//	控制器故障
H_Out.RobotWarning	:=	Out.RobotWarning	;//	控制器警告
H_Out.EnableOK	:=	Out.EnableOK	;//	伺服使能OK
H_Out.Acknowledged	:=	Out.Acknowledged	;//	ACK确认按钮状态
H_Out.PosDone	:=	Out.PosDone	;//	点位到位信号
H_Out.Axis_X1.ActPos	:=	Out.Axis_X1.ActPos	;//	X轴坐标
H_Out.Axis_Y1.ActPos	:=	Out.Axis_Y1.ActPos	;//	Y轴坐标
H_Out.Axis_Z1.ActPos	:=	Out.Axis_Z1.ActPos	;//	Z轴坐标
H_Out.Axis_R1.ActPos	:=	Out.Axis_R1.ActPos	;//	R轴坐标
H_Out.Axis_X1.ActTorque	:=	Out.Axis_X1.ActTorque	;//	X轴扭矩
H_Out.Axis_Y1.ActTorque	:=	Out.Axis_Y1.ActTorque		;//	Y轴扭矩
H_Out.Axis_Z1.ActTorque	:=	Out.Axis_Z1.ActTorque	;//	Z轴扭矩
H_Out.Axis_R1.ActTorque	:=	Out.Axis_R1.ActTorque	;//	R轴扭矩
H_Out.Axis_X1.ActTorqueMax	:=	Out.Axis_X1.ActTorqueMax	;//	X轴扭矩最大值
H_Out.Axis_Y1.ActTorqueMax	:=	Out.Axis_Y1.ActTorqueMax		;//	Y轴扭矩最大值
H_Out.Axis_Z1.ActTorqueMax	:=	Out.Axis_Z1.ActTorqueMax	;//	Z轴扭矩最大值
H_Out.Axis_R1.ActTorqueMax	:=	Out.Axis_R1.ActTorqueMax	;//	R轴扭矩最大值
H_Out.Axis_X1.ActElectric	:=	Out.Axis_X1.ActElectric	;//	X轴电流
H_Out.Axis_Y1.ActElectric	:=	Out.Axis_Y1.ActElectric		;//	Y轴电流
H_Out.Axis_Z1.ActElectric	:=	Out.Axis_Z1.ActElectric	;//	Z轴电流
H_Out.Axis_R1.ActElectric	:=	Out.Axis_R1.ActElectric	;//	R轴电流
H_Out.Axis_X1.ActElectricMax	:=	Out.Axis_X1.ActElectricMax	;//	X轴电流最大值
H_Out.Axis_Y1.ActElectricMax	:=	Out.Axis_Y1.ActElectricMax		;//	Y轴电流最大值
H_Out.Axis_Z1.ActElectricMax	:=	Out.Axis_Z1.ActElectricMax	;//	Z轴电流最大值
H_Out.Axis_R1.ActElectricMax	:=	Out.Axis_R1.ActElectricMax	;//	R轴电流最大值
H_Out.Alarm	:=	ErrOut.Alarm	;//	机器人控制错误
H_Out.bErrID	:=	ErrOut.bErrID	;//	机器人控制错误代码
H_Out.RobotErrID	:=	Out.RobotErrID	;//	控制器故障代码
H_Out.SafetyArea	:=	Out.SafetyArea	;//	区域安全信号
H_Out.RobotMode      :=  Out.RobotMode	;//	远程模式（等于1远程，等于0手动）

	//发送数据
	IF nSendDaSize > 0 OR sSendData = ''
	THEN
		AryMove(
			In										:=	bySendData[0]		, 
			AryOut									:=	SendData[0]			, 
			Size									:=	nSendDaSize
			);
		SendDaSize									:=	nSendDaSize;
	ELSE
		StringToAry(
			In										:=	sSendData			, 
			AryOut									:=	SendData[0]		
			);
		SendDaSize									:=	TO_UINT(LEN( sSendData));	
	END_IF
	
	//链接参数
	IF NOT bEnable 
	THEN
		stConnect.byConnectType			:=	0		;
		IF ServerSelect THEN
			stConnect.byMode			:=	0		;
			stConnect.diConnectID		:=	ConnectID;	
			stConnect.stLocal.strIPAddr	:=	sHost	;
			stConnect.stLocal.uiPort	:=	nPort	;	
			stConnect.stRemote.strIPAddr:=	''		;
			stConnect.stRemote.uiPort	:=	0		;

		ELSE
			stConnect.byMode			:=	1		;
			stConnect.diConnectID		:=	ConnectID;	
			stConnect.stLocal.strIPAddr	:=	''		;
			stConnect.stLocal.uiPort	:=	0		;	
			stConnect.stRemote.strIPAddr:=	sHost	;
			stConnect.stRemote.uiPort	:=	nPort	;	
		END_IF
		;
	END_IF
	
// 	fbConnDelay_T(PT:=T#500MS );
// 	fbExc_R(CLK:=bSendExecute , Q=> );	
// 	IF bEnable 
// 	THEN
// 		CASE uiStep OF
// 			0 :
// 				IF  fbExc_R.Q
// 					AND NOT bBusy
// 				THEN 					
// 					bBusy	:=	TRUE ;
// 					uiStep	:=	10	 ;
// 				END_IF			
// 			10 :
// 				fbConnDelay_T.IN		:=	TRUE ;
// 				IF fbTCPSend.eStatus = TCP_STATUS.TCP_ESTABLISHED 
// 				THEN
// 					fbTCPSend.xExecute	:=	TRUE ;
// 				END_IF				
// 				IF fbTCPSend.xDone
// 				THEN
// 					fbTCPSend.xExecute	:=	FALSE;
// 					fbConnDelay_T.IN	:=	FALSE;
// 					uiStep	:=	20	 ;
// 				END_IF
// 			
// 			30 :
// 				fbConnDelay_T.IN		:=	TRUE ;
// 				IF fbTCPRecv.eStatus = TCP_STATUS.TCP_ESTABLISHED 
// 					AND NOT fbTCPClearBuffer.xBusy 
// 				THEN
// 					fbTCPRecv.xEnable	:=	TRUE ;
// 				END_IF
// 				
// 				IF fbTCPRecv.xReady
// 				THEN
// 					fbTCPRecv.xEnable	:=	FALSE;
// 					fbConnDelay_T.IN	:=	FALSE;
// 					uiStep	:=	40	 ;
// 				END_IF
// 
// 			40 ://
// 				bBusy				:=	FALSE;
// 				uiStep				:=	0	 ;				
// 		END_CASE
// 		
// 	END_IF
// 	
// 	IF NOT bEnable
// 		OR bReset
// 	THEN
// 		fbTCPSend.xExecute	:=	FALSE;
// 		fbTCPRecv.xEnable	:=	FALSE;
// 		fbConnDelay_T.IN	:=	FALSE;
// 		bReadDone			:=	FALSE;
// 		bBusy				:=	FALSE;
// 		uiStep				:=	0	 ;
// 	END_IF
	
	IF NOT bEnable
	THEN
		nReadDaSize		:=	0		;
		Clear(In:=byReadData );
		Clear(In:=sReadData);
	END_IF
	
	fbTCPSend(
		xExecute		:= bEnable AND bSendExecute AND fbTCPSend.eStatus = TCP_STATUS.TCP_ESTABLISHED, 
		xEnCont			:= bEnable AND NOT (bReset AND fbTCPSend.eStatus <> TCP_STATUS.TCP_ESTABLISHED), 
		stConnect		:= stConnect, 
		abyData			:= SendData[0], 
		uiDataSize		:= SendDaSize, 
		uiTimeOut		:= 500, 
		xDone			=> bSendDone, 
		xBusy			=> , 
		xError			=> , 
		wErrorID		=> , 
		eStatus			=> , 
		stConnectInfo	=> 
		);
		
	IF xRecExc <> fbTCPSend.xExecute
		AND fbTCPSend.xExecute = TRUE 
	THEN
		fbTCPClearBuffer.xExecute	:=	TRUE 	;
		nReadDaSize					:=	0		;
		Clear(In:=byReadData );
		Clear(In:=sReadData);
	ELSE
		fbTCPClearBuffer.xExecute	:=	FALSE 	;
	END_IF	
	
	fbTCPClearBuffer(
		xExecute		:= , 
		diConnectID		:= fbTCPRecv.stConnectInfo.diConnectID, 
		xDone			=> , 
		xBusy			=> , 
		xError			=> , 
		wErrorID		=> 
		);
	xRecExc				:=	fbTCPSend.xExecute;
		
	fbTCPRecv(
		xEnable			:= bEnable AND fbTCPRecv.eStatus = TCP_STATUS.TCP_ESTABLISHED AND NOT fbTCPClearBuffer.xBusy , 
		xEnCont			:= bEnable AND NOT (bReset AND fbTCPRecv.eStatus <> TCP_STATUS.TCP_ESTABLISHED), 
		stConnect		:= stConnect, 
		abyData			:= RecvData[0], 
		uiDataSize		:= 0, 
		xDone			=> , 
		xBusy			=> , 
		xError			=> , 
		wErrorID		=> , 
		xReady			=> bReadDone, 
		uiCount			=> , 
		eStatus			=> , 
		stConnectInfo	=> 
		);
	
	IF bReadDone 
	THEN
		byReadData	:=	RecvData;
		nReadDaSize	:=	fbTCPRecv.uiCount;
		AryToString(In:=byReadData[0] , Size:=nReadDaSize , Out=>sReadData );
	END_IF


	bConnected			:=	fbTCPSend.eStatus = TCP_STATUS.TCP_ESTABLISHED
							AND fbTCPRecv.eStatus = TCP_STATUS.TCP_ESTABLISHED
							;
	
	bConnectedErr		:=	fbConnDelay_T.Q	;
	
	
	bError				:=	fbTCPSend.xError
							OR fbTCPRecv.xError
							OR fbConnDelay_T.Q
							;
							
	bBusy				:=	fbTCPSend.xBusy
							OR fbTCPRecv.xBusy
							;
							
	IF fbTCPSend.xError
	THEN
		nErrorID	:=	fbTCPSend.wErrorID;
	ELSIF fbTCPRecv.xError
	THEN 
		nErrorID	:=	fbTCPRecv.wErrorID;
	END_IF

data.STCode:
FOR n:=INT#0 TO INT#19 BY INT#1 DO
    TRIG[n](Clk:=CycleTime>=RealRangeValueTime1+CycleTimeArg*n);
	IF TRIG[n].Q THEN
	    ServoTorqueAvgTemp[n]:=ServoTorqueCurrentActual;
		ServoSpeedAvgTemp[n]:=ServoSpeedCurrentActual;
	END_IF;
END_FOR;

ServoTorqueAvgStatic:=REAL#0;
ServoSpeedAvgStatic:=REAL#0;
FOR m:=INT#0 TO INT#19 BY INT#1 DO
    ServoTorqueAvgStatic:=ServoTorqueAvgStatic+ServoTorqueAvgTemp[m];
	ServoSpeedAvgStatic:=ServoSpeedAvgStatic+ServoSpeedAvgTemp[m];
END_FOR;
ServoTorqueAvgStatic:=ServoTorqueAvgStatic/REAL#20.0;
ServoSpeedAvgStatic:=ServoSpeedAvgStatic/REAL#20.0;

IF ServoStart=TRUE THEN
	CycleTimeMaxFwdTemp:=0;
	CycleTimeMaxBkdTemp:=0;
	FOR CycleTimeNumFor:=0 TO 20 BY 1 DO
		IF CycleTimeFwd[CycleTimeNumFor]>CycleTimeMaxFwdTemp THEN
			CycleTimeMaxFwdTemp:=CycleTimeFwd[CycleTimeNumFor];
		END_IF;
		IF CycleTimeBkd[CycleTimeNumFor]>CycleTimeMaxBkdTemp THEN
			CycleTimeMaxBkdTemp:=CycleTimeBkd[CycleTimeNumFor];
		END_IF;
	END_FOR;
END_IF;
CycleTimeMaxFwd:=CycleTimeMaxFwdTemp;
CycleTimeMaxBkd:=CycleTimeMaxBkdTemp;

