SC00_Mapping();
SC01_Main();
SC02_Initial();
SC02_Initial01_顶盖中转机器人();
SC02_Initial02_NG();
SC03_Call();
SC04_Run();
SC04_RUN02_下层顶盖NG拉带();
SC04_RUN01_顶盖中转机器人();
SC04_RUN03_上层自动首件();
SC05_Manual();
SC06_Alram();
SC07_Communicate();

//*  轴使能
fbPower(
	Axis:= 										RealAxis, 
	Enable:= 									1, 
	bRegulatorOn:= 	 					Input.xPowerEnable AND (RealAxis.wCommunicationState= 100), 
	bDriveStart:= 							Input.xPowerEnable AND (RealAxis.wCommunicationState= 100), 
	Status=>									Output.xPowerStatus,
	Error=>									Output.xPowerError);
IF fbPower.Error  THEN
	Output.eFbErrorID :=				fbPower.ErrorID;
END_IF

// * 轴快速停止
	xTempClear :=						(Input.xResetExecute AND NOT fbReset.Execute AND NOT ReinitDrive.bExecute) OR NOT Input.xResetInputCmd;
	xStopClear :=						(Input.xStopExecute AND NOT fbStop.Execute) OR xTempClear;
fbStop(
	Axis:= 									RealAxis, 
	Execute:= 								Input.xStopExecute, 
	Deceleration:= 						Input.fMoveDeceleration, 
	Jerk:= 									Input.fMoveJerk);
	Input.xStopExecute R=			Input.xResetInputCmd ;
	Output.xStopBusy :=				fbStop.Busy;
	Output.xStopDone :=				fbStop.Done OR (NOT xStopClear AND Output.xStopDone );
	Output.xStopError :=				fbStop.Error OR (NOT xStopClear AND Output.xStopError);
IF fbStop.Error  THEN
	Output.eFbErrorID :=				fbStop.ErrorID;
END_IF
	
//*  驱动器回原点

	xHomeClear :=						(Input.xHomeExecute AND NOT fbHome.Execute) OR xTempClear;
fbHome(
	Axis:= RealAxis, 
	Execute:= Input.xHomeExecute, 
	Position:= Input.fHomePosition, 
	Done=> , 
	Busy=> , 
	CommandAborted=> , 
	Error=> , 
	ErrorID=> );											//回原完成后，设置当前点位置
	Input.xHomeExecute R=		Input.xResetInputCmd ;	
	Output.xHomeBusy :=			fbHome.Busy;
	Output.xHomeError :=			fbHome.Error 	   OR (NOT xHomeClear AND Output.xHomeError);	
	Output.xHomeDone :=			fbHome.Done	   OR (NOT xHomeClear AND Output.xHomeDone);	
	Output.xHomeAborted :=		fbHome.CommandAborted  OR (NOT xHomeClear AND Output.xHomeAborted);
IF fbHome.Error  THEN
	Output.eFbErrorID :=				fbHome.ErrorID;
END_IF
	
//*  轴点动运行
fbJog(
	Axis:= RealAxis, 
	JogForward:= Input.xJogForward, 
	JogBackward:= Input.xJogBackward, 
	Velocity:= Input.fMoveVelocity, 
	Acceleration:= Input.fMoveAcceleration, 
	Deceleration:= Input.fMoveDeceleration, 
	Jerk:= Input.fMoveJerk, 
	Busy=> , 
	CommandAborted=> , 
	Error=> , 
	ErrorId=> );
	xJogClear :=							(Input.xJogForward AND NOT fbJog.JogForward) OR (Input.xJogBackward AND NOT fbJog.JogBackward) OR xTempClear;
	Output.xJogBusy :=				fbJog.Busy;
	Output.xJogAborted :=			fbJog.CommandAborted OR (NOT xJogClear AND Output.xJogAborted);
	Output.xJogError :=				fbJog.Error 	  OR (NOT xJogClear AND Output.xJogError);
IF  fbJog.Error  THEN
	Output.eFbErrorID :=				fbJog.ErrorID;
END_IF
	
//*  轴匀速运行	
	xVeloClear :=							(Input.xVelocityExecute AND NOT fbVelocity.Execute) OR xTempClear;
fbVelocity(
	Axis:= RealAxis, 
	Execute:= Input.xVelocityExecute OR Output.xVelocityBusy, 
	Velocity:= Input.fMoveVelocity, 
	Acceleration:= Input.fMoveAcceleration, 
	Deceleration:= Input.fMoveDeceleration, 
	Jerk:= Input.fMoveJerk, 
	Direction:= Input.eMoveDirection, 
	InVelocity=> , 
	Busy=> , 
	CommandAborted=> , 
	Error=> , 
	ErrorID=> );	
	Input.xVelocityExecute R=		Input.xResetInputCmd ;
	Output.xVelocityBusy :=			fbVelocity.Busy;
	Output.xVelocityDone :=		fbVelocity.InVelocity;
	Output.xVelocityError :=			fbVelocity.Error    OR (NOT xVeloClear  AND Output.xVelocityError);	
	Output.xVelocityAborted :=	fbVelocity.CommandAborted OR (NOT xVeloClear AND Output.xVelocityAborted);	
IF fbVelocity.Error  THEN
	Output.eFbErrorID :=				fbVelocity.ErrorID;
END_IF
		
//*  轴绝对定位
	xAbsoClear :=							(Input.xAbsoluteExecute AND NOT fbAbsolute.Execute) OR xTempClear;
fbAbsolute(
	Axis:= RealAxis, 
	Execute:= Input.xAbsoluteExecute , 
	Position:= Input.fMovePosition, 
	Velocity:= Input.fMoveVelocity, 
	Acceleration:= Input.fMoveAcceleration, 
	Deceleration:= Input.fMoveDeceleration, 
	Jerk:= Input.fMoveJerk, 
	Direction:= Input.eMoveDirection, 
	Done=> , 
	Busy=> , 
	CommandAborted=> , 
	Error=> , 
	ErrorID=> );	
	Input.xAbsoluteExecute R=		Input.xResetInputCmd ;
	Output.xAbsoluteBusy :=			fbAbsolute.Busy 	   	AND NOT fbAbsolute.Done;
	Output.xAbsoluteDone :=			fbAbsolute.Done OR (NOT xAbsoClear AND Output.xAbsoluteDone);	
	Output.xAbsoluteError :=			fbAbsolute.Error     	OR (NOT xAbsoClear AND Output.xAbsoluteError);	
	Output.xAbsoluteAborted :=		fbAbsolute.CommandAborted   	OR (NOT xAbsoClear AND Output.xAbsoluteAborted);	
IF fbAbsolute.Error  THEN
	Output.eFbErrorID :=				fbAbsolute.ErrorID;
END_IF
	
//*  轴相对定位
	xRelaClear :=						(Input.xRelativeExecute AND NOT fbRelative.Execute) OR xTempClear;
fbRelative(
	Axis:= 									RealAxis,	
	Execute:= 								Input.xRelativeExecute, 
	Distance:= 							Input.fMoveDistance,
	Velocity:= 								Input.fMoveVelocity, 
	Acceleration:= 						Input.fMoveAcceleration, 
	Deceleration:= 						Input.fMoveDeceleration, 
	Jerk:= 									Input.fMoveJerk); 
	Input.xRelativeExecute R=		Input.xResetInputCmd ;
	Output.xRelativeBusy :=			fbRelative.Busy;
	Output.xRelativeDone :=			fbRelative.Done					 OR (NOT xRelaClear AND Output.xRelativeDone);	
	Output.xRelativeError :=			fbRelative.Error     	  			 OR (NOT xRelaClear AND Output.xRelativeError);	
	Output.xRelativeAborted :=		fbRelative.CommandAborted OR (NOT xRelaClear AND Output.xRelativeAborted);	
IF fbRelative.Error  THEN
	Output.eFbErrorID :=				fbRelative.ErrorID;
END_IF
		
//*  轴位置设置
	xSetPosClear :=					(Input.xSetPosExecute AND NOT fbSetPosition.Execute) OR xTempClear;
fbSetPosition(
	Axis:= 									RealAxis,	
	Execute:= 								Input.xSetPosExecute, 
	Position:= 								Input.fSetPosition,
	Mode:= 								FALSE); 
	Input.xSetPosExecute R=		Input.xResetInputCmd ;
	Output.xSetPosBusy :=			fbSetPosition.Busy;	
	Output.xSetPosDone :=			fbSetPosition.Done OR (NOT xSetPosClear AND Output.xSetPosDone);	
	Output.xSetPosError :=			fbSetPosition.Error OR (NOT xSetPosClear AND Output.xSetPosError);		
IF fbSetPosition.Error  THEN
	Output.eFbErrorID :=				fbSetPosition.ErrorID;
END_IF

//* 故障复位
fbReset(
	Axis:= RealAxis, 
	Execute:= Input.xResetExecute AND RealAxis.wCommunicationState=100, 
	Done=> , 
	Busy=> , 
	Error=> , 
	ErrorID=> );	
	
ReinitDrive(
	Axis:= RealAxis, 
	bExecute:= Input.xResetExecute  AND RealAxis.wCommunicationState<>100, 
	bVirtual:= , 
	bDone=> , 
	bBusy=> , 
	bError=> , 
	nErrorID=> );	
	
	Input.xResetExecute R=			Input.xResetInputCmd ;
	Output.xResetBusy :=				fbReset.Busy OR ReinitDrive.bBusy;	
	Output.xResetDone :=				fbReset.Done OR (NOT xTempClear AND Output.xResetDone) OR ReinitDrive.bDone;	
	Output.xResetError :=				fbReset.Error  OR (NOT xTempClear AND Output.xResetError) OR ReinitDrive.bError;	
IF fbReset.Error  THEN
	Output.eFbErrorID :=				fbReset.ErrorID;
ELSIF  ReinitDrive.bError THEN
	Output.eFbErrorID :=				ReinitDrive.nErrorID;
END_IF	

//* 轴输出状态
	Output.xFbBusy	:=					Output.xRelativeBusy OR Output.xStopBusy OR Output.xVelocityBusy OR Output.xHomeBusy OR Output.xAbsoluteBusy OR Output.xJogBusy OR Output.xResetBusy OR Output.xSetPosBusy ;	
	Output.xFbError :=					Output.xRelativeError OR Output.xStopError OR Output.xVelocityError OR Output.xHomeError OR Output.xAbsoluteError OR Output.xJogError  OR Output.xResetError OR Output.xSetPosError OR Output.xPowerError;		// 功能块故障
IF NOT Output.xFbError THEN
	Output.eFbErrorID :=				0;
END_IF

	Output.pAxis :=						ADR(RealAxis);								// 轴指针地址
	Output.eAxisState :=				RealAxis.nAxisState;						// 轴状态		
	Output.xAxisError :=				RealAxis.nAxisState = 1;				// 轴故障	
	Output.xAxisBusy :=				RealAxis.nAxisState > 3 OR (RealAxis.nAxisState = 2);		// 轴运行中
	Output.xServoAlarm :=			RealAxis.In.wStatusWord.7;			// 驱动器警告	
	Output.xServoError :=				RealAxis.In.wStatusWord.3;			// 驱动器故障
	Output.dwServoErrorID :=		RealAxis.dwErrorID;						// 驱动器故障代码
	Output.xPotLimitSensor := 		RealAxis.In.dwDigitalInputs.1;			// 正限位信号
	Output.xNotLimitSensor :=		RealAxis.In.dwDigitalInputs.0;			// 负限位信号
	Output.xHomeSensor	:=			RealAxis.In.dwDigitalInputs.2;			// 原点信号
	
	Output.xETCError :=				Servo.wState <> 8;

// 隐含生成代码：这里只是对代码实现的建议
IF  index < lower THEN
	CheckBounds := lower;
ELSIF  index > upper THEN
	CheckBounds := upper;
ELSE  
	CheckBounds := index;
END_IF

