IF NOT In THEN
	
	Cy2.In.Auto_R:=Cy1.In.Auto_R;
	Cy2.In.Auto_V:=Cy1.In.Auto_V;
	Cy3.In.Auto_R:=Cy1.In.Auto_R;
	Cy3.In.Auto_V:=Cy1.In.Auto_V;
	Cy4.In.Auto_R:=Cy1.In.Auto_R;
	Cy4.In.Auto_V:=Cy1.In.Auto_V;

END_IF;


TON_Hold(In:=Process_steps=500, PT:=T#300MS);

IF In THEN

	//同步H_Cy1给其他
	Permit[0]:=	Cy1.In.Manual_R XOR Command_Temp[0]	;
	Permit[1]:=	Cy1.In.Manual_V XOR Command_Temp[1]	;
	
	
	//同步H_Cy2给其他
	Permit[2]:=	Cy2.In.Manual_R XOR Command_Temp[2]	;
	Permit[3]:=	Cy2.In.Manual_V XOR Command_Temp[3]	;
	
	//同步H_Cy3给其他
	Permit[4]:=	Cy3.In.Manual_R XOR Command_Temp[4]	;
	Permit[5]:=	Cy3.In.Manual_V XOR Command_Temp[5]	;
	
	//同步H_Cy4给其他
	Permit[6]:=	Cy4.In.Manual_R XOR Command_Temp[6]	;
	Permit[7]:=	Cy4.In.Manual_V XOR Command_Temp[7]	;


	CASE Process_steps OF
	0://流程开始
		IF Permit[0] THEN
			Process_steps			:=100;
		ELSIF Permit[1] THEN
			Process_steps			:=200;
		ELSIF Permit[2] THEN
			Process_steps			:=300;
		ELSIF Permit[3] THEN
			Process_steps			:=400;
		ELSIF Permit[4] THEN
			Process_steps			:=500;
		ELSIF Permit[5] THEN
			Process_steps			:=600;
		ELSIF Permit[6] THEN
			Process_steps			:=700;
		ELSIF Permit[7] THEN
			Process_steps			:=800;
		END_IF;
	
	100://同步H_Cy1给其他
		//////命令赋值//////
		Cy2.In.Manual_R:=Cy1.In.Manual_R;
		Cy3.In.Manual_R:=Cy1.In.Manual_R;
		Cy4.In.Manual_R:=Cy1.In.Manual_R;
		
		Cy1.In.Manual_V:=FALSE;
		Cy2.In.Manual_V:=FALSE;
		Cy3.In.Manual_V:=FALSE;
		Cy4.In.Manual_V:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
	200://同步H_Cy1给其他
		//////命令赋值//////
		Cy2.In.Manual_V:=Cy1.In.Manual_V;
		Cy3.In.Manual_V:=Cy1.In.Manual_V;
		Cy4.In.Manual_V:=Cy1.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Cy3.In.Manual_R:=FALSE;
		Cy4.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;

	300://同步H_Cy2给其他
		//////命令赋值//////
		Cy1.In.Manual_R:=Cy2.In.Manual_R;
		Cy3.In.Manual_R:=Cy2.In.Manual_R;
		Cy4.In.Manual_R:=Cy2.In.Manual_R;
		
		Cy1.In.Manual_V:=FALSE;
		Cy2.In.Manual_V:=FALSE;
		Cy3.In.Manual_V:=FALSE;
		Cy4.In.Manual_V:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
	400://同步H_Cy2给其他
		//////命令赋值//////
		Cy1.In.Manual_V:=Cy2.In.Manual_V;
		Cy3.In.Manual_V:=Cy2.In.Manual_V;
		Cy4.In.Manual_V:=Cy2.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Cy3.In.Manual_R:=FALSE;
		Cy4.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
		
	500://同步H_Cy1给其他
		//////命令赋值//////
		Cy1.In.Manual_R:=Cy3.In.Manual_R;
		Cy2.In.Manual_R:=Cy3.In.Manual_R;
		Cy4.In.Manual_R:=Cy3.In.Manual_R;
		
		Cy1.In.Manual_V:=FALSE;
		Cy2.In.Manual_V:=FALSE;
		Cy3.In.Manual_V:=FALSE;
		Cy4.In.Manual_V:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
	600://同步H_Cy1给其他
		//////命令赋值//////
		Cy1.In.Manual_V:=Cy3.In.Manual_V;
		Cy2.In.Manual_V:=Cy3.In.Manual_V;
		Cy4.In.Manual_V:=Cy3.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Cy3.In.Manual_R:=FALSE;
		Cy4.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;

	700://同步H_Cy2给其他
		//////命令赋值//////
		Cy1.In.Manual_R:=Cy4.In.Manual_R;
		Cy2.In.Manual_R:=Cy4.In.Manual_R;
		Cy3.In.Manual_R:=Cy4.In.Manual_R;
		
		Cy1.In.Manual_V:=FALSE;
		Cy2.In.Manual_V:=FALSE;
		Cy3.In.Manual_V:=FALSE;
		Cy4.In.Manual_V:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
	800://同步H_Cy2给其他
		//////命令赋值//////
		Cy1.In.Manual_V:=Cy4.In.Manual_V;
		Cy2.In.Manual_V:=Cy4.In.Manual_V;
		Cy3.In.Manual_V:=Cy4.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Cy3.In.Manual_R:=FALSE;
		Cy4.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;
		Command_Temp[4]:=Cy3.In.Manual_R;
		Command_Temp[5]:=Cy3.In.Manual_V;
		Command_Temp[6]:=Cy4.In.Manual_R;
		Command_Temp[7]:=Cy4.In.Manual_V;

		////跳步
		Process_steps				:=0;
		
	END_CASE;

END_IF;

SC00_Mapping();
SC01_Main();
SC02_Initial();
SC02_Initial_贴胶();
SC03_Call();
SC04_Run();
SC04_Run_备胶();
