ActPos									:=	Actpos_6020											;//实时位置
ActVelo									:=	ActVelo_6021										;//实时速度
ActTorque								:=	ActTorque_6022										;//实时扭矩

FC_WordToAryBool(IN:=Un_Input.mword , begin1:=0 , out:=Un_Input_mBit , begin2:=0 , Size:=16 );
FC_WordToAryBool(IN:=Un_Ready.mword , begin1:=0 , out:=Un_Ready_mBit , begin2:=0 , Size:=16 );
Busy										:=	Un_Input_mBit[8]									;//Busy
EnableOK								:=	Un_Input_mBit[9]									;//使能完成
Homed									:=	Un_Input_mBit[10]									;//回原完成
INP										:=	Un_Input_mBit[11]									;//定位完成
Estop									:=	Un_Input_mBit[14]									;//安全回路异常
DriverAlarm								:=	Un_Input_mBit[15]									;//驱动器异常


//绝对定位完成
Out.AbsDone							:=	INP													;
//Busy
Out.Busy									:=	Busy													;
//使能OK
Out.EnableOK							:=	EnableOK											;
//实时位置
Out.ActPos								:=	DINT_TO_REAL(ActPos)/100.0			;
//实时速度
Out.ActVelo								:=	ActVelo											;
//实时扭矩
Out.ActTorque							:=	ActTorque										;


(*信号输出*)
Output_7010								:=	WORD_TO_UINT(Un_Output.mWord)					;
ControlWord_7011						:=	WORD_TO_UINT(Un_ControlWord.mWord)		;
StartFlag_7012								:=	BYTE_TO_USINT(Un_StartFlag.mByte)					;
OperationMode_7020					:=	BYTE_TO_USINT(Un_OperationMode.mByte)		;
Speed_7021									:=	REAL_TO_UINT(Speed)										;//速度值
Position_7022								:=	REAL_TO_DINT(AbsPosition*100)						;//位置值
Acc_7023										:=	REAL_TO_UINT(AxisAccDec)								;//加减速值
Dec_7024										:=	REAL_TO_UINT(AxisAccDec)								;//加减速值


Un_Output_mBit[8]						:=	Hold_M											;//暂停
Un_Output_mBit[9]						:=	Enable_M											;//使能
Un_Output_mBit[11]						:=	Reset_M											;//复位
Un_Output_mBit[12]						:=	HomedExecute_M							;//回原触发
Un_Output_mBit[14]						:=	JogPos_M											;//JOG+
Un_Output_mBit[13]						:=	JogNeg_M										;//JOG-

Un_ControlWord_mBit[5]				:=	TRUE												;//速度启用
Un_ControlWord_mBit[6]				:=	TRUE												;//位置启用
Un_ControlWord_mBit[7]				:=	TRUE												;//加速度启用
Un_ControlWord_mBit[8]				:=	TRUE												;//减速度启用

Un_StartFlag_mBit[0]					:=	AbsExecute_M		OR  Rel_TON.Q		;//定位触发

Un_OperationMode_mBit[0]				:=TRUE	;//绝对定位模式
ARRAY_TO_BYTETemp(
	B0:=Un_operationMode_mBit[0] , 
	B1:=Un_operationMode_mBit[1] , 
	B2:=Un_operationMode_mBit[2] , 
	B3:=Un_operationMode_mBit[3] , 
	B4:=Un_operationMode_mBit[4] , 
	B5:=Un_operationMode_mBit[5] , 
	B6:=Un_operationMode_mBit[6] , 
	B7:=Un_operationMode_mBit[7] , 
	B=> Un_OperationMode.mByte );

FC_AryBoolToWord(AryBool:=Un_Output_mBit , AryWord:=Un_Output );
FC_AryBoolToWord(AryBool:=Un_ControlWord_mBit , AryWord:=Un_ControlWord );

ARRAY_TO_BYTETemp(
	B0:=Un_StartFlag_mBit[0] , 
	B1:=Un_StartFlag_mBit[1] , 
	B2:=Un_StartFlag_mBit[2] , 
	B3:=Un_StartFlag_mBit[3] , 
	B4:=Un_StartFlag_mBit[4] , 
	B5:=Un_StartFlag_mBit[5] , 
	B6:=Un_StartFlag_mBit[6] , 
	B7:=Un_StartFlag_mBit[7] , 
	B=> Un_StartFlag.mByte );
//相对位置赋值
Rel_R(Clk:=H_IN.ToRelPOS AND Manual);
IF Rel_R.Q  THEN
AbsPosition:=Out.ActPos+H_IN.RelPOS;
END_IF;
Rel_TON(In:=H_IN.ToRelPOS AND Manual, PT:=T#100MS);


(************************************ 轴参初始化 ****************************************)
IF Manual
THEN
//整机速率比
IF GeneralOverride=0
THEN
	GeneralOverride					:=	100													;
END_IF;

//手动速度
IF 	Parameter.ManualVelocity <= 0
THEN
	Parameter.ManualVelocity			:=	10.0						;
ELSIF Parameter.ManualVelocity > 200
THEN
	Parameter.ManualVelocity			:=	200.0						;
END_IF;

//自动速度
IF 	Parameter.AutoVelocity = 0
THEN
	Parameter.AutoVelocity				:=	100.0						;
END_IF;
IF 	Parameter.AutoVelocity_Low = 0
THEN
	Parameter.AutoVelocity_Low				:=	50.0						;
END_IF;
IF 	Parameter.AutoVelocity_High = 0
THEN
	Parameter.AutoVelocity_High				:=	100.0						;
END_IF;

//回原速度
IF 	Parameter.HomeFastSpeed = 0
THEN
	Parameter.HomeFastSpeed				:=	10.0						;
END_IF;

//速度比率
IF 	Parameter.Overrid = 0
THEN
	Parameter.Overrid					:=	100.0						;
END_IF;

IF GeneralOverride = 0
THEN
	GeneralOverride						:=	100.0						;
END_IF;

//加减速
IF 	Parameter.AccDec = 0
THEN
	Parameter.AccDec					:=	1000.0						;
END_IF;

//加加速
IF 	Parameter.Jerk = 0
THEN
	Parameter.Jerk						:=	10000.0						;
END_IF;

//额定扭矩值
IF 	Parameter.RatedTrqValue = 0
THEN
	Parameter.RatedTrqValue			:=	100.0						;
END_IF;

//扭矩限制值
IF 	Parameter.SetTrqLimitValue = 0
THEN
	Parameter.SetTrqLimitValue			:=	150.0						;
END_IF;

END_IF;


(***************************************************3D联合仿真程序******************************************************************)

(********************************************  轴手动状态  *****************************************************)
	H_Out.Manual						:=	Manual												;

	IF	Manual
	THEN
		DisEnable								:=	H_In.DisEnable										;
		ChangeConflictPos				:=	H_In.ChangeConflictPos						;
	END_IF;

(********************************************  速度比例  *************************************************)
IF GeneralOverride>=1 AND GeneralOverride<=100
THEN
	Overrid:=GeneralOverride/100;
ELSIF GeneralOverride<1
THEN
	Overrid:=0.01;
ELSIF GeneralOverride>100
THEN
	Overrid:=1;
END_IF;

(********************************************  暂停控制  *************************************************)
IF TRUE
THEN

Pause_R(CLK:= Pause	);

PauseTOF(IN:= Pause	, PT:= T#100MS );

Pause_F(CLK:= PauseTOF.Q);

IF 	Out.Busy
	AND Pause_R.Q
THEN
	PauseM								:=	TRUE												;
END_IF;
IF NOT In.MovingAllow 
	OR Aborting
	OR In.StopExecute
THEN
	PauseM								:=	FALSE												;
END_IF;

(****  手动下降沿触发停止  ********)
Manual_F(
	Clk									:=	Manual	
	);

END_IF;

(********************************************	获取沟槽感应信号  **********************************************)
// 汇总通过PDO对象获取到的轴的原点、极限点信号 //

(********************************************	指令复位	******************************************************)
//发生报警瞬间&触发停止复位自动触发指令
Abort_R(Clk:=Aborting);
IF Abort_R.Q OR In.StopExecute
THEN
	Clear(In.ToPos);
	Clear(H_In.ToPos);
	In.AbsExecute            				:=	FALSE										;//	轴绝对定位触发复位
	In.HomeExecute           			:=	FALSE										;//	轴回原点触发复位
	In.AutoJogPos            				:=	FALSE										;//	轴JOG+触发复位
	In.AutoJogNeg            			:=	FALSE										;//	轴JOG-触发复位
	In.RelExecute							:=	FALSE										;
	In.TorqueExecute						:=	FALSE										;
	In.VeloExecute							:=	FALSE										;
END_IF;


(********************************************	轴使能管理	**************************************************)
IF TRUE
THEN
(*
1、驱动器没有报警且没有禁止使能时，延时500ms以后触发轴使能，并将速率比设置为指定值。
2、使能完成与速率比均设置完成后，EnableOK设置为TRUE。
3、当速率比大于100时，会默认设置为100。
*)

IF	NOT DriverAlarm
	AND NOT DisEnable
	AND NOT EmgStop
THEN
	EnableTONReady							:=	TRUE										;
ELSE
	EnableTONReady							:=	FALSE										;
END_IF;

TON_Ready(
	IN										:= 	EnableTONReady								,
	PT										:= 	TIME#500ms									,
	Q										=> 	Readyed
	);


END_IF;

(********************************************	马达寻参	******************************************************)
IF TRUE
THEN
// 寻参允许 //
IF	NOT ErrOUT.DriverAlarm	//驱动器报警
	AND NOT Aborting				//触发停止
	AND NOT Pause					//没有暂停
	AND H_Out.EnableOK				//使能OK
	AND In.MovingAllow				//移动允许
	AND In.HomeAllow				//回原点允许
THEN
	Out.HomePermit							:=	TRUE										;
ELSE
	Out.HomePermit							:=	FALSE										;
	HomedExecute_M						:=	FALSE										;
END_IF;

//	采集启动寻参上升沿信号 	//	
HomeExecute_R(
	CLK									:=	(In.HomeExecute AND Auto )
											OR (H_In.HomeExecute AND Manual)
	);

// 允许回原的前提下，接收到启动寻参的上升沿信号，轴开始寻参 //
IF	NOT Aborting				//触发停止
	AND NOT Pause				//没有暂停
	AND Out.EnableOK			//使能OK
	AND (In.MovingAllow			//移动允许
	AND In.HomeAllow)			//回原点允许
	AND	HomeExecute_R.Q
THEN
	OUT.Homing							:=	TRUE										;
	Out.HomeDone						:=	FALSE										;
END_IF;

IF 	NOT In.HomeExecute
	AND NOT H_In.HomeExecute
THEN
	Out.HomeDone						:=	FALSE										;
END_IF;

IF 	NOT Aborting				//触发停止
	AND NOT Pause				//没有暂停
	AND Out.EnableOK			//使能OK
	AND (In.MovingAllow			//移动允许
	AND In.HomeAllow)			//回原点允许
	AND OUT.Homing
THEN
	CASE FindHomeStep OF
		0://选择寻参功能块寻参
			OUT.Homed					:=	FALSE										;
			FindHomeStep				:=	100											;

		100://正常寻参
			HomedExecute_M				:=	TRUE										;
			HomedTON.IN					:=	TRUE										;
			IF HomedTON.Q
			THEN
				FindHomeStep			:=	110											;
				HomedTON.IN				:=	FALSE										;
			END_IF;
		110://正常寻参
			IF Homed 
			THEN
				HomedExecute_M			:=	FALSE										;
				FindHomeStep			:=	120											;
			END_IF;
		120:
			Out.HomeDone				:=	TRUE										;
			OUT.Homed					:=	TRUE										;
			OUT.Homing					:=	FALSE										;
			FindHomeStep				:=	0											;

	END_CASE;
ELSE
	
//	轴没有进行寻参时，将寻参过程中用到的变量进行初始化	//
	OUT.Homing							:=	FALSE										;
	FindHomeStep						:=	0											;
END_IF;

///// 没有原点标记复位原点记忆输出 ///////
IF NOT Homed
THEN
	OUT.Homed							:=	FALSE										;
END_IF;

HomedTON(
	PT	:=	T#0.5S
	);

END_IF;


(********************************************	轴速度设置		*********************************************)
IF TRUE
THEN
	//	设置轴定位的速度，自动运行时使用自动速度，其他情况下使用手动速度	//
	IF	Manual
	THEN
		AxisVelocity						:=	Parameter.ManualVelocity;
	ELSIF Auto
	THEN 
		AxisVelocity						:=	Parameter.AutoVelocity*Overrid;	
	END_IF;

	//	点动速度设置	//
	IF	OUT.Homing
	THEN
		AxisJogVelocity						:=	10	;
	ELSIF	Auto
	THEN
		AxisJogVelocity						:=	Parameter.AutoVelocity*Overrid;
	ELSE
		AxisJogVelocity						:=	Parameter.ManualVelocity;
	END_IF;
	
	//	设置轴加速度
	AxisAccDec						:=	Parameter.AccDec*Overrid;
		
	//	设置轴跃度
	AxisJerk						:=	Parameter.Jerk*Overrid;

END_IF;


(********************************************	JOG控制	******************************************************)
IF TRUE
THEN
	//自动复位手自触发
	IF	Auto
	THEN
		H_In.ManualJogNeg					:=	FALSE										;
		H_In.ManualJogPos					:=	FALSE										;
	ELSIF Manual
	THEN
		In.AutoJogNeg						:=	FALSE										;
		In.AutoJogPos						:=	FALSE										;
	ELSE
		H_In.ManualJogNeg					:=	FALSE										;
		H_In.ManualJogPos					:=	FALSE										;
		In.AutoJogNeg						:=	FALSE										;
		In.AutoJogPos						:=	FALSE										;
	END_IF;

	//	JOG+	//
	IF	((H_In.ManualJogPos AND Manual)
		OR	(In.AutoJogPos	AND Auto ))
		AND H_Out.EnableOK
		AND NOT JOGNeg
		AND NOT	Out.Homing
		AND NOT AbsExecute
		AND NOT Aborting
		AND NOT Pause
		AND In.JogAllow
		AND	IN.MovingAllow
	THEN
		JOGPos								:=	TRUE										;
	ELSE
		JOGPos								:=	FALSE										;
	END_IF;

	//	JOG-	//
	IF	((H_In.ManualJogNeg AND Manual)
		OR	(In.AutoJogNeg	AND Auto ))
		AND	H_Out.EnableOK
		AND NOT JOGPos
		AND NOT	Out.Homing
		AND NOT AbsExecute
		AND NOT Aborting
		AND NOT Pause
		AND In.JogAllow
		AND	IN.MovingAllow
	THEN
		JOGNeg								:=	TRUE										;
	ELSE	
		JOGNeg								:=	FALSE										;
	END_IF;

END_IF;

//在绝对定位过程中没有安全条件报警
	FOR k:=0 TO 40 DO
	IF  Out.Busy
		AND  (In.ToPos[k]
				AND NOT  In.AbsAllow[k])
	THEN
		ToPosHinderErr:=TRUE;
	END_IF;
	END_FOR;
(********************************************	定位控制（C公司用）	******************************************************)
//非手动模式下复位HMI操作按钮
IF Auto 
	OR NOT Auto AND NOT Manual
THEN
	H_In.SelectLocation:=ARRAY_40FALSE;
	H_In.ActivateInput:=FALSE;
	H_In.ToPosExe:=FALSE;
	H_In.PositionDemonstration:=FALSE;
END_IF;

//切换选择
IF Manual THEN
	IF SelectLocationDone THEN
		FOR i:=0 TO 40 BY 1 DO
		IF H_In.SelectLocation[i] AND SelectLocationTemp<>i+1 THEN
			SelectLocationTemp:=i+1;
			SelectLocationDone:=FALSE;
			EXIT;
		END_IF;
		END_FOR;
	ELSIF NOT SelectLocationDone THEN
		FOR i:=0 TO 40 BY 1 DO
		IF SelectLocationTemp<>i+1 THEN
			H_In.SelectLocation[i]:=FALSE;
		END_IF;
			SelectLocationDone:=TRUE;
		END_FOR;
	END_IF;
END_IF;

//手动模式下触发定位
IF Manual THEN
	FOR i:=0 TO 40 BY 1 DO
		H_In.ToPos[i]:=H_In.SelectLocation[i] AND H_In.ToPosExe;
		IF Out.PosDone[i]
		THEN
			H_In.ToPos[i]:=FALSE;
		END_IF;
	END_FOR;
END_IF;


//手动模式下点位示教
IF Manual THEN
	FOR i:=0 TO 40 BY 1 DO
		IF H_In.SelectLocation[i] THEN
			IF H_In.PositionDemonstration THEN
				Parameter.Position[i]:=Out.ActPos;
			END_IF;
		END_IF;
	END_FOR;
END_IF;

//定位触发下降沿控制轴停止
IF NOT H_In.ToPosExe
	AND ToPosExeTemp
THEN
	F_ToPosExe:=TRUE;
ELSE
	F_ToPosExe:=FALSE;
END_IF;
ToPosExeTemp:=H_In.ToPosExe;

(********************************************	定位控制	******************************************************)
IF TRUE
THEN
AbsTON(In:=Out.Homed
		AND NOT Out.Homing
		AND NOT JOGNeg
		AND NOT JOGPos, 
		PT:=T#10MS);
	IF AbsTON.Q
	THEN
		IF	In.AbsExecute
			AND In.MovingAllow
		THEN
			AbsPosition						:=	In.AbsPosition								;
		END_IF;

		IF H_In.ConflictStopToPos AND Manual 
			AND In.ConflictStopToPosAllow 
		THEN
			AbsPosition						:=	H_Out.ConflictStopPos						;
		END_IF;

		IF ((H_In.ToPos[0] AND Manual)
			OR (In.ToPos[0]AND Auto))
			AND In.AbsAllow[0]
			AND NOT Out.PosDone[0]
		THEN
			AbsPosition						:=	Parameter.Position[0]						;
		ELSE 
			In.ToPos[0]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[1] AND Manual)
			OR (In.ToPos[1]AND Auto))
			AND In.AbsAllow[1] 
			AND NOT Out.PosDone[1]
		THEN
			AbsPosition						:=	Parameter.Position[1]						;
		ELSE 
			In.ToPos[1]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[2] AND Manual)
			OR (In.ToPos[2]AND Auto))
			AND In.AbsAllow[2] 
			AND NOT Out.PosDone[2]
		THEN
			AbsPosition						:=	Parameter.Position[2]						;
		ELSE 
			In.ToPos[2]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[3] AND Manual)
			OR (In.ToPos[3]AND Auto))
			AND In.AbsAllow[3] 
			AND NOT Out.PosDone[3]
		THEN
			AbsPosition						:=	Parameter.Position[3]						;
		ELSE 
			In.ToPos[3]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[4] AND Manual)
			OR (In.ToPos[4]AND Auto))
			AND In.AbsAllow[4] 
			AND NOT Out.PosDone[4]
		THEN
			AbsPosition						:=	Parameter.Position[4]						;
		ELSE 
			In.ToPos[4]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[5] AND Manual)
			OR (In.ToPos[5]AND Auto))
			AND In.AbsAllow[5] 
			AND NOT Out.PosDone[5]
		THEN
			AbsPosition						:=	Parameter.Position[5]						;
		ELSE 
			In.ToPos[5]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[6] AND Manual)
			OR (In.ToPos[6]AND Auto))
			AND In.AbsAllow[6] 
			AND NOT Out.PosDone[6]
		THEN
			AbsPosition						:=	Parameter.Position[6]						;
		ELSE 
			In.ToPos[6]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[7] AND Manual)
			OR (In.ToPos[7]AND Auto))
			AND In.AbsAllow[7]
			AND NOT Out.PosDone[7]
		THEN
			AbsPosition						:=	Parameter.Position[7]						;
		ELSE 
			In.ToPos[7]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[8] AND Manual)
			OR (In.ToPos[8]AND Auto))
			AND In.AbsAllow[8] 
			AND NOT Out.PosDone[8]
		THEN
			AbsPosition						:=	Parameter.Position[8]						;
		ELSE 
			In.ToPos[8]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[9] AND Manual)
			OR (In.ToPos[9]AND Auto))
			AND In.AbsAllow[9] 
			AND NOT Out.PosDone[9]
		THEN
			AbsPosition						:=	Parameter.Position[9]						;
		ELSE 
			In.ToPos[9]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[10] AND Manual)
			OR (In.ToPos[10]AND Auto))
			AND In.AbsAllow[10] 
			AND NOT Out.PosDone[10]
		THEN
			AbsPosition						:=	Parameter.Position[10]						;
		ELSE 
			In.ToPos[10]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[11] AND Manual)
			OR (In.ToPos[11]AND Auto))
			AND In.AbsAllow[11] 
			AND NOT Out.PosDone[11]
		THEN
			AbsPosition						:=	Parameter.Position[11]						;
		ELSE 
			In.ToPos[11]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[12] AND Manual)
			OR (In.ToPos[12]AND Auto))
			AND In.AbsAllow[12] 
			AND NOT Out.PosDone[12]
		THEN
			AbsPosition						:=	Parameter.Position[12]						;
		ELSE 
			In.ToPos[12]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[13] AND Manual)
			OR (In.ToPos[13]AND Auto))
			AND In.AbsAllow[13] 
			AND NOT Out.PosDone[13]
		THEN
			AbsPosition						:=	Parameter.Position[13]						;
		ELSE 
			In.ToPos[13]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[14] AND Manual)
			OR (In.ToPos[14]AND Auto))
			AND In.AbsAllow[14] 
			AND NOT Out.PosDone[14]
		THEN
			AbsPosition						:=	Parameter.Position[14]						;
		ELSE 
			In.ToPos[14]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[15] AND Manual)
			OR (In.ToPos[15]AND Auto))
			AND In.AbsAllow[15] 
			AND NOT Out.PosDone[15]
		THEN
			AbsPosition						:=	Parameter.Position[15]						;
		ELSE 
			In.ToPos[15]						:=FALSE												;
		END_IF;

		IF ((H_In.ToPos[16] AND Manual)
			OR (In.ToPos[16]AND Auto))
			AND In.AbsAllow[16] 
			AND NOT Out.PosDone[16]
		THEN
			AbsPosition						:=	Parameter.Position[16]						;
		ELSE 
