(********************************************	手自动冲突	*************************************************)

IF bConflictEnable
THEN
	(* 手自动冲突状态记录 *)
	AStateOut_F(
		Clk:=	bConflictState
		);
	IF AStateOut_F.Q
	THEN
		AStateMark				:=	TRUE													;
	END_IF;
	BusyTON(
		IN								:=	AStateMark AND NOT Out.Busy,
		PT								:=	T#200MS
		);
	InitDone_R(	Clk	:=InitDone	);
	(* 状态跳出时记住停下来的位置 *)
	IF	BusyTON.Q
		OR InitDone_R.Q
		OR NOT InitDone
	THEN
		H_Out.ConflictStopPos	:=	OUT.ActPos											;
		AStateMark						:=	FALSE													;
		ErrOut.ConflictErr:=FALSE;
	END_IF;

	(**** 手自动冲突报警 ****)
	IF Manual
		AND InitDone
	THEN
		ErrOut.ConflictErr				:= 	ABS(H_Out.ConflictStopPos - OUT.ActPos	) > rScope		;
	END_IF;

	(*把当前位置传给手自动冲突位置*)
	IF ChangeConflictPos
	THEN
		H_Out.ConflictStopPos	:=	OUT.ActPos											;
	END_IF;
ELSE
	AStateMark							:=	FALSE													;
	H_Out.ConflictStopPos		:=	0															;
	ErrOut.ConflictErr					:=	FALSE													;
END_IF;

H_Out.ConflictErr						:=	ErrOut.ConflictErr									;


