	B2:= EIP_OUTput_TempmBit[82,2], 
	B3:= EIP_OUTput_TempmBit[82,3], 
	B4:= EIP_OUTput_TempmBit[82,4], 
	B5:= EIP_OUTput_TempmBit[82,5], 
	B6:= EIP_OUTput_TempmBit[82,6], 
	B7:= EIP_OUTput_TempmBit[82,7], 
	B=> EIP_Output_TempByte[82]);
	

EIP_Output[81] := EIP_Output_TempByte[81];
EIP_Output[82] := EIP_Output_TempByte[82];
EIP_Output[83] := EIP_Output_TempByte[83];
EIP_Output[84] := EIP_Output_TempByte[84];
EIP_Output[85] := EIP_Output_TempByte[85];
EIP_Output[86] := EIP_Output_TempByte[86];
EIP_Output[87] := EIP_Output_TempByte[87];
EIP_Output[88] := EIP_Output_TempByte[88];
EIP_Output[89] := EIP_Output_TempByte[89];
EIP_Output[90] := EIP_Output_TempByte[90];


(******************************************** 防撞回弹程序 *********************************************)
TON_ReboundCondition(In:=In.Rebound_Execute AND NOT Out.Running AND ReboundStep=0, PT:=T#100ms);
TP_Rebound_Execute(In:=TON_ReboundCondition.Q, PT:=T#2S);
Rebound_Execute:=TP_Rebound_Execute.Q;
TON_ReboundOverTimes(In:=ReboundStep<>0, PT:=T#10S);

//反弹步骤
CASE ReboundStep OF
	0://反弹触发
		IF Rebound_Execute THEN
			ReboundStep:=100;
		END_IF;
	100://等待恢复
		IF (NOT In.Rebound_Execute
			AND TON_ReboundOverTimes.Q
			OR NOT Out.Running)
			AND NOT Rebound_Execute
		THEN
			ReboundStep:=110;
		END_IF;
END_CASE;

ReboundWord_Bit.mByte[0].0:=Rebound_Execute;
EIP_Output[29]:=ReboundWord_Bit.mByte[0];


(******************************************** 报警复位 *********************************************)
IF H_In.bReset OR Reset THEN
	ErrOut:=ErrOut_Clear;
END_IF;


(******************************************** 错误信息 *********************************************)
// IF _EIP_RegTargetSta[Node]
// 	AND NOT _EIP_EstbTargetSta[Node]
// 	AND (Manual OR Auto)
// THEN
// 	ErrOut.ConnectedErr:=TRUE;//网络链接错误
// END_IF;

IF NOT Out.EmgStopOK THEN
	ErrOut.EmgStopErr:=TRUE;//安全急停错误
END_IF;

IF NOT Out.SafetyDoorOK THEN
	ErrOut.SafetyDoorErr:=TRUE;//安全门错误
END_IF;

IF NOT Out.Ready THEN
	ErrOut.NoReadyErr:=TRUE;//未准备就绪错误
END_IF;

TON_EnableErr(
	In:=Enable_M
	AND NOT Out.EnableOK
	, PT:=T#10S);
IF TON_EnableErr.Q
	OR (Auto AND NOT Out.EnableOK)
THEN
	ErrOut.NoEnableErr:=TRUE;//未使能错误
END_IF;

TON_RunningErr(
	In:=Auto
	AND (In.Run OR In.bContinue)
	AND NOT Out.Running
	, PT:=T#5S);
IF TON_RunningErr.Q
THEN
	ErrOut.NoRunningErr:=TRUE;//未运行错误
END_IF;

TON_UnExcutedErr(
	In:=Auto
	AND Out.Running
	AND EIP_Output[4]<>0
	AND EIP_Output[4]<>EIP_Input[4]
	, PT:=T#60S);
IF TON_UnExcutedErr.Q
THEN
	ErrOut.UnExcutedErr:=TRUE;//未执行命令错误
END_IF;

FOR K:=0 TO 40 DO
	IF ((In.ToPos[K] AND NOT In.Location_SafeCondition[K])
		OR (H_In.ToPos[K] AND NOT In.Location_SafeCondition[K]))
		AND Out.Running
	THEN
		ErrOut.MovingHinderErr:=TRUE;//移动中干涉
	END_IF;
END_FOR;

IF In.Rebound_Execute THEN
	ErrOut.AvoidErr:=TRUE;//防撞感应错误
END_IF;


IF H_Out.Axis_X1.ActTrqMaxClear
THEN
	Out.Axis_X1.ActTorqueMax:=0;
ELSIF NOT ErrOut.AxisXLimitTrqErr
THEN
	Out.Axis_X1.ActTorqueMax:=MAX(ABS(Out.Axis_X1.ActTorque),ABS(Out.Axis_X1.ActTorqueMax));
END_IF;
IF Out.Axis_X1.ActTorqueMax>=Parameter.Axis_X1.TrqLimitValue THEN
	ErrOut.AxisXLimitTrqErr:=TRUE;//X轴超出限制扭矩值错误
END_IF;
IF H_Out.Axis_Y1.ActTrqMaxClear
THEN
	Out.Axis_Y1.ActTorqueMax:=0;
ELSIF NOT ErrOut.AxisYLimitTrqErr
THEN
	Out.Axis_Y1.ActTorqueMax:=MAX(ABS(Out.Axis_Y1.ActTorque), ABS(Out.Axis_Y1.ActTorqueMax));
END_IF;
IF Out.Axis_Y1.ActTorqueMax>=Parameter.Axis_Y1.TrqLimitValue THEN
	ErrOut.AxisYLimitTrqErr:=TRUE;//Y轴超出限制扭矩值错误
END_IF;
IF H_Out.Axis_Z1.ActTrqMaxClear
THEN
	Out.Axis_Z1.ActTorqueMax:=0;
ELSIF NOT ErrOut.AxisZLimitTrqErr
THEN
	Out.Axis_Z1.ActTorqueMax:=MAX(ABS(Out.Axis_Z1.ActTorque), ABS(Out.Axis_Z1.ActTorqueMax));
END_IF;
IF Out.Axis_Z1.ActTorqueMax>=Parameter.Axis_Z1.TrqLimitValue THEN
	ErrOut.AxisZLimitTrqErr:=TRUE;//Z轴超出限制扭矩值错误
END_IF;
IF H_Out.Axis_R1.ActTrqMaxClear
THEN
	Out.Axis_R1.ActTorqueMax:=0;
ELSIF NOT ErrOut.AxisRLimitTrqErr
THEN
	Out.Axis_R1.ActTorqueMax:=MAX(ABS(Out.Axis_R1.ActTorque), ABS(Out.Axis_R1.ActTorqueMax));
END_IF;
IF Out.Axis_R1.ActTorqueMax>=Parameter.Axis_R1.TrqLimitValue THEN
	ErrOut.AxisRLimitTrqErr:=TRUE;//R轴超出限制扭矩值错误
END_IF;

IF H_Out.Axis_X1.ActElectricMaxClear
THEN
	Out.Axis_X1.ActElectricMax:=0;
ELSIF NOT ErrOut.AxisXLimitElectricErr
THEN
	Out.Axis_X1.ActElectricMax:=MAX(ABS(Out.Axis_X1.ActElectric), ABS(Out.Axis_X1.ActElectricMax));
END_IF;
IF Out.Axis_X1.ActElectricMax>=Parameter.Axis_X1.ElectricLimitValue THEN
	ErrOut.AxisXLimitElectricErr:=TRUE;//X轴超出限制电流值错误
END_IF;
IF H_Out.Axis_Y1.ActElectricMaxClear
THEN
	Out.Axis_Y1.ActElectricMax:=0;
ELSIF NOT ErrOut.AxisYLimitElectricErr
THEN
	Out.Axis_Y1.ActElectricMax:=MAX(ABS(Out.Axis_Y1.ActElectric), ABS(Out.Axis_Y1.ActElectricMax));
END_IF;
IF Out.Axis_Y1.ActElectricMax>=Parameter.Axis_Y1.ElectricLimitValue THEN
	ErrOut.AxisYLimitElectricErr:=TRUE;//Y轴超出限制电流值错误
END_IF;
IF H_Out.Axis_Z1.ActElectricMaxClear
THEN
	Out.Axis_Z1.ActElectricMax:=0;
ELSIF NOT ErrOut.AxisZLimitElectricErr
THEN
	Out.Axis_Z1.ActElectricMax:=MAX(ABS(Out.Axis_Z1.ActElectric), ABS(Out.Axis_Z1.ActElectricMax));
END_IF;
IF Out.Axis_Z1.ActElectricMax>=Parameter.Axis_Z1.ElectricLimitValue THEN
	ErrOut.AxisZLimitElectricErr:=TRUE;//Z轴超出限制电流值错误
END_IF;
IF H_Out.Axis_R1.ActElectricMaxClear
THEN
	Out.Axis_R1.ActElectricMax:=0;
ELSIF NOT ErrOut.AxisRLimitElectricErr
THEN
	Out.Axis_R1.ActElectricMax:=MAX(ABS(Out.Axis_R1.ActElectric), ABS(Out.Axis_R1.ActElectricMax));
END_IF;
IF Out.Axis_R1.ActElectricMax>=Parameter.Axis_R1.ElectricLimitValue THEN
	ErrOut.AxisRLimitElectricErr:=TRUE;//R轴超出限制电流值错误
END_IF;

(*====自定义故障====*)
EIP_Input_TempByte[10]:=EIP_Input[10];
BYTE_UNPACK_IN[10](
	B:= EIP_Input_TempByte[10], 
	B0=> Eip_Input_TempmBit[10,0], 
	B1=> Eip_Input_TempmBit[10,1], 
	B2=> Eip_Input_TempmBit[10,2], 
	B3=> Eip_Input_TempmBit[10,3], 
	B4=> Eip_Input_TempmBit[10,4], 
	B5=> Eip_Input_TempmBit[10,5], 
	B6=> Eip_Input_TempmBit[10,6], 
	B7=> Eip_Input_TempmBit[10,7]);
IF Eip_Input_TempmBit[10,0] THEN
	ErrOut.RobotUseAlarm[0]:=TRUE;//机器人点位手系示教错误报警
END_IF;
IF Eip_Input_TempmBit[10,1] THEN
	ErrOut.RobotUseAlarm[1]:=TRUE;//机器人不在安全位置报警
END_IF;
IF Eip_Input_TempmBit[10,2] THEN
	ErrOut.RobotUseAlarm[2]:=TRUE;//PLC程序号发送错误报警
END_IF;
IF Eip_Input_TempmBit[10,3] THEN
	ErrOut.RobotUseAlarm[3]:=TRUE;//PLC偏移数据发送错误，超出安全范围报警
END_IF;
IF Eip_Input_TempmBit[10,4] THEN
	ErrOut.RobotUseAlarm[4]:=TRUE;//机器人防撞报警触发报警
END_IF;
IF Eip_Input_TempmBit[10,5] THEN
	ErrOut.RobotUseAlarm[5]:=TRUE;//机器人模拟模式被打开报警
END_IF;



(******************************************** 机器人报警汇总 *********************************************)
IF FALSE
	OR ErrOut.ConnectedErr//网络链接错误
	OR ErrOut.EmgStopErr//安全急停错误
	OR ErrOut.SafetyDoorErr//安全门错误
	OR ErrOut.NoReadyErr//未准备就绪错误
	OR ErrOut.NoEnableErr//未使能错误
	OR ErrOut.NoRunningErr//未运行错误
	OR ErrOut.UnExcutedErr//未执行命令错误
	OR ErrOut.MovingHinderErr//移动中干涉
	OR ErrOut.AvoidErr//防撞感应错误
	OR ErrOut.AxisXLimitTrqErr//X轴超出限制扭矩值错误
	OR ErrOut.AxisYLimitTrqErr//Y轴超出限制扭矩值错误
	OR ErrOut.AxisZLimitTrqErr//Z轴超出限制扭矩值错误
	OR ErrOut.AxisRLimitTrqErr//R轴超出限制扭矩值错误
	OR ErrOut.AxisXLimitElectricErr//X轴超出限制电流值错误
	OR ErrOut.AxisYLimitElectricErr//Y轴超出限制电流值错误
	OR ErrOut.AxisZLimitElectricErr//Z轴超出限制电流值错误
	OR ErrOut.AxisRLimitElectricErr//R轴超出限制电流值错误
	OR ErrOut.RobotUseAlarm[0]//机器人点位手系示教错误报警
	OR ErrOut.RobotUseAlarm[1]//机器人不在安全位置报警
	OR ErrOut.RobotUseAlarm[2]//PLC程序号发送错误报警
	OR ErrOut.RobotUseAlarm[3]//PLC偏移数据发送错误，超出安全范围报警
	OR ErrOut.RobotUseAlarm[4]//机器人防撞报警触发报警
	OR ErrOut.RobotUseAlarm[5]//机器人模拟模式被打开报警
	OR Out.RobotError//控制器故障
	OR Out.ProgramError//软件程序错误
THEN
	ErrOut.Alarm:=TRUE;
END_IF;


(******************************************** 机器人错误代码输出 *********************************************)
IF TRUE THEN;

	IF ErrOut.ConnectedErr
	THEN
		ErrOut.bErrID:=1;//网络链接错误
		
	ELSIF ErrOut.EmgStopErr
	THEN
		ErrOut.bErrID:=2;//安全急停错误
		
	ELSIF ErrOut.SafetyDoorErr
	THEN
		ErrOut.bErrID:=3;//安全门错误
		
	ELSIF ErrOut.NoReadyErr
	THEN
		ErrOut.bErrID:=4;//未准备就绪错误
		
	ELSIF ErrOut.NoEnableErr
	THEN
		ErrOut.bErrID:=5;//未使能错误
		
	ELSIF ErrOut.NoRunningErr
	THEN
		ErrOut.bErrID:=6;//未运行错误
		
	ELSIF ErrOut.UnExcutedErr
	THEN
		ErrOut.bErrID:=7;//未执行命令错误
		
	ELSIF ErrOut.MovingHinderErr
	THEN
		ErrOut.bErrID:=8;//移动中干涉
		
	ELSIF ErrOut.AxisXLimitTrqErr
	THEN
		ErrOut.bErrID:=9;//X轴超出限制扭矩值错误
		
	ELSIF ErrOut.AxisYLimitTrqErr
	THEN
		ErrOut.bErrID:=10;//Y轴超出限制扭矩值错误
		
	ELSIF ErrOut.AxisZLimitTrqErr
	THEN
		ErrOut.bErrID:=11;//Z轴超出限制扭矩值错误
		
	ELSIF ErrOut.AxisRLimitTrqErr
	THEN
		ErrOut.bErrID:=12;//R轴超出限制扭矩值错误
		
	ELSIF ErrOut.AvoidErr
	THEN
		ErrOut.bErrID:=13;//防撞感应错误
	
	ELSIF ErrOut.AxisXLimitElectricErr
	THEN
		ErrOut.bErrID:=14;//X轴超出限制电流值错误
		
	ELSIF ErrOut.AxisYLimitElectricErr
	THEN
		ErrOut.bErrID:=15;//Y轴超出限制电流值错误
		
	ELSIF ErrOut.AxisZLimitElectricErr
	THEN
		ErrOut.bErrID:=16;//Z轴超出限制电流值错误
		
	ELSIF ErrOut.AxisRLimitElectricErr
	THEN
		ErrOut.bErrID:=17;//R轴超出限制电流值错误
	
	
	ELSIF ErrOut.RobotUseAlarm[0]
	THEN
		ErrOut.bErrID:=50;//机器人点位手系示教错误报警
		
	ELSIF ErrOut.RobotUseAlarm[1]
	THEN
		ErrOut.bErrID:=51;//机器人不在安全位置报警
		
	ELSIF ErrOut.RobotUseAlarm[2]
	THEN
		ErrOut.bErrID:=52;//PLC程序号发送错误报警
		
	ELSIF ErrOut.RobotUseAlarm[3]
	THEN
		ErrOut.bErrID:=53;//PLC偏移数据发送错误，超出安全范围报警
		
	ELSIF ErrOut.RobotUseAlarm[4]
	THEN
		ErrOut.bErrID:=54;//机器人防撞报警触发报警
		
	ELSIF ErrOut.RobotUseAlarm[5]
	THEN
		ErrOut.bErrID:=55;//机器人模拟模式被打开报警
		
		
	ELSIF Out.RobotError
	THEN
		ErrOut.bErrID:=98;//控制器故障
		
	ELSIF Out.ProgramError
	THEN
		ErrOut.bErrID:=99;//软件程序错误
		
	ELSIF ErrOut.Alarm
	THEN
		ErrOut.bErrID:=100;//其他错误
	END_IF;


END_IF;


(******************************************** HMI信号输出 *********************************************)
H_Out.Ready	:=	Out.Ready	;//	系统就绪
H_Out.Running	:=	Out.Running	;//	运行中
H_Out.Paused	:=	Out.Paused	;//	暂停中
H_Out.Stopped	:=	Out.Stopped	;//	停止中
H_Out.ProgramError	:=	Out.ProgramError	;//	软件程序错误
H_Out.SafetyDoorOK	:=	Out.SafetyDoorOK	;//	安全门OK
H_Out.EmgStopOK	:=	Out.EmgStopOK	;//	急停OK
H_Out.RobotError	:=	Out.RobotError	;//	控制器故障
