H_Out.Axis_Y1.ActPos	:=	Out.Axis_Y1.ActPos	;//	Y轴坐标
H_Out.Axis_Z1.ActPos	:=	Out.Axis_Z1.ActPos	;//	Z轴坐标
H_Out.Axis_R1.ActPos	:=	Out.Axis_R1.ActPos	;//	R轴坐标
