H_Out.Axis_R1.ActTorqueMax	:=	Out.Axis_R1.ActTorqueMax	;//	R轴扭矩最大值
H_Out.Axis_X1.ActElectric	:=	Out.Axis_X1.ActElectric	;//	X轴电流
