H_Out.Axis_Z1.ActElectric	:=	Out.Axis_Z1.ActElectric	;//	Z轴电流
H_Out.Axis_R1.ActElectric	:=	Out.Axis_R1.ActElectric	;//	R轴电流
H_Out.Axis_X1.ActElectricMax	:=	Out.Axis_X1.ActElectricMax	;//	X轴电流最大值
H_Out.Axis_Y1.ActElectricMax	:=	Out.Axis_Y1.ActElectricMax		;//	Y轴电流最大值
H_Out.Axis_Z1.ActElectricMax	:=	Out.Axis_Z1.ActElectricMax	;//	Z轴电流最大值
H_Out.Axis_R1.ActElectricMax	:=	Out.Axis_R1.ActElectricMax	;//	R轴电流最大值
H_Out.Alarm	:=	ErrOut.Alarm	;//	机器人控制错误
H_Out.bErrID	:=	ErrOut.bErrID	;//	机器人控制错误代码
H_Out.RobotErrID	:=	Out.RobotErrID	;//	控制器故障代码
H_Out.SafetyArea	:=	Out.SafetyArea	;//	区域安全信号

