(*//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//Reading Section
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*)
(*	//****************************************
	//Copy Input words to array input Buffer
	//*****************************************)
		(**修改替换数据,看看是否正确,功能就是把2个byte变量拼接成一个INT变量,注意高低字节不能反**)
		FOR w_Cnt:=0 TO 7 DO
			//AryByteTo(In:=IO_inputByte[2*w_Cnt], Size:=2, Order:=_HIGH_LOW , OutVal:=arr_w_InputBuffer[w_Cnt]);	
			arr_w_InputBuffer[w_Cnt]:=WORD_TO_INT(MEM.PackBytesToWord(byHighByte:=IO_inputByte[2*w_Cnt] , byLowByte:=IO_inputByte[2*w_Cnt+1]));
		END_FOR;
		
(*	//***********************************************************************
	//This section is to Create array FOR parameter reading index
	//Because all prarmeters are read in 6 word a time,
	//some only use the first one,this array is used to
	//record the reading value length,either 1 word OR 6 word
	//************************************************************************)
	FOR w_Cnt:= 0 TO w_Max_Read_Cnt DO
		IF arr_Para[w_Cnt].w_Index <> 0 AND arr_Para[w_Cnt].w_Channel >0 THEN
			arr_ValueIndex[w_Cnt] := 6;
			ELSE IF arr_Para[w_Cnt].w_Index <>0 AND arr_Para[w_Cnt].w_Channel =0 THEN
				arr_ValueIndex[w_Cnt] := 1;
			END_IF;
		END_IF;
	END_FOR;
(*	//**********************
	//Create Reading Tick
	//***********************)
	tm_Read_Tick (IN := (NOT b_tick AND NOT b_WriteEvent AND NOT b_CycleCtrl), PT := T#200ms, Q =>b_tick);

	(*//*****************************************************************
	//Create Fast Read Section FOR PLC TO read any fast read data more
	//frequently than others, i_CounterRemain is the tick.
	//******************************************************************)
	IF b_tick OR b_CycleCtrl THEN
		w_ReadOldPtr := w_ReadPtr;
	    w_Counter := w_Counter + 1;
	   	b_CommComp := 0;
	    IF w_Counter > 10000 THEN
	        w_Counter := 0;
	    END_IF;
	END_IF;

	w_CounterReMain := w_Counter MOD 2;
	b_FastRead := 0;
	IF w_CounterReMain =1 THEN
	    b_FastRead := 1;
	END_IF;

	(*//*****************************************************************************
	//PrevPtr store pointer OF pervious pointer , no matter in faster read OR NOT
	//TmpPtr temperary store pointer in faster read section , so that when move out
	//fast read pointer will know where to start.
	//******************************************************************************)
	IF (b_tick OR b_CycleCtrl)AND  NOT b_FastRead THEN
	    w_PrevPtr := w_ReadPtr;
	    w_ReadPtr := w_TmpPtr;
	    w_ReadPtr := w_ReadPtr + 1;
	END_IF;

	IF (b_tick OR b_CycleCtrl)AND  b_FastRead THEN
	    w_PrevPtr := w_ReadPtr;
	    w_FastReadPtr := w_FastReadPtr + 1;
	    IF w_FastReadPtr >w_Max_FastRead_Cnt THEN
	        w_FastReadPtr := 0;
	    END_IF;
	    w_TmpPtr := w_ReadPtr;
	    w_ReadPtr := w_FastReadPtr;
	END_IF;

	IF w_ReadPtr > w_Max_Read_Cnt THEN
	    w_ReadPtr := w_Max_FastRead_Cnt;
	END_IF;

	w_Command :=3; (*// Command FOR reading parameters*)
(*	//*******************************************************************
	//When Write Event, transfer the write ptr TO current ptr
	//When write event, get the write index number AND locate inside
	//Para array AND start read from there
	//********************************************************************)
	IF b_WriteEvent THEN
	    FOR w_Cnt:=0 TO w_Max_Read_Cnt BY 1 DO
	     IF (w_WriteIndex =arr_Para[w_Cnt].w_Index )THEN
	           w_WritePtr := w_Cnt-1;
	           IF w_WritePtr  <0  THEN
	           	w_WritePtr :=0;
	           END_IF;
	        EXIT; (*//Reason to EXIT loop is ,write in setpoint will have mulitple results with same index, only the first index need to BE read.*)
	     END_IF;
	    END_FOR;
	    w_ReadPtr := w_WritePtr;
	    w_TmpPtr := w_ReadPtr;
	    w_PrevPtr := w_ReadPtr;
	END_IF;

	(*//**********************************************************************
	//To prevent jumping numbers during writing event,it is required to 
	//copy back the writing value to arr_Value[], otherwise, arr_value[]
	//will keep the old value AND when they copy to HMI structure,
	//you will see the value you just changed jump back to old value AND 
	//when IO updated, it change back the writen value.
	//***********************************************************************)
	w_SumIndex := 0;
	    FOR w_Cnt := 0 TO w_PrevPtr DO
	        w_SumIndex := w_SumIndex + arr_ValueIndex[w_Cnt];
	    END_FOR;
	IF b_WriteEvent THEN
	    IF w_WriteChannel <> 0 THEN 
	        arr_Value[w_SumIndex+w_WriteChannel] := w_WriteValue ; 
	    	ELSE
	        arr_Value[w_SumIndex+1+w_WriteChannel] := w_WriteValue ;
	     END_IF;
	END_IF;

	(*//******************************************************************************************
	//Reading Data Section
	//******************************************************************************************
	//******************************************************************************************
	//Based on pointer, the melter send command with pointer, but it won't give you the value
	//right away, have to wait the next cycle to get the value, that is why have to use prevPtr
	//to store the previous pointer
	//*******************************************************************************************)
	b_ReadActive := 0;
	IF (w_ReadPtr <> w_ReadOldPtr) AND (NOT b_WriteEvent)  THEN
	    b_ReadActive := 1;
		w_ReadOldPtr := w_ReadPtr;
	END_IF;
	w_Index := arr_Para[w_ReadPtr].w_Index;
	w_Channel := arr_Para[w_ReadPtr].w_Channel;
	w_IndexChannel := w_Index + w_Channel*256;

	(*//Detect Falling Edge OF write Event*)
	IF NOT b_WriteEvent AND b_WriteEventFallingEdge THEN
		b_WriteFallingEdgeDetect :=1;
	END_IF;
	b_WriteEventFallingEdge := b_WriteEvent;
	
	IF b_ReadActive AND NOT b_WriteEvent THEN
	    (*//Read value *)
		arr_w_OutputBuffer[1] := w_IndexChannel;		(*// Second Output word is Channel/ Index word*)
	    w_PrevIndex := arr_Para[w_PrevPtr].w_index;
	    w_PrevChannel := arr_Para[w_PrevPtr].w_Channel;
		w_PrevIndexChannel := w_PrevIndex + w_PrevChannel*256;
	    (*//*****************************************************
	    //SumIndex indicate the index OF value in value array,
	    //starting form 1
	    //******************************************************)
	    w_SumIndex := 0;
	    FOR w_Cnt := 0 TO w_PrevPtr DO
	        w_SumIndex := w_SumIndex + arr_ValueIndex[w_Cnt];
	    END_FOR;
		(*//******************************************************************************************************************
		//When Write Event Falling Edge occurs, write back the previous variable value into arr_w_InputBuffer[2] temperary
		//to prevent arr_w_InputBuffer[2] turn to zero when reading start which will cause the previous value turn to 0
		//*******************************************************************************************************************)
		IF b_WriteFallingEdgeDetect THEN 
			w_PrevIndexChannel := arr_w_InputBuffer[1];
		END_IF;  
	  	w_ReturnIndexChannel := arr_w_InputBuffer[1];
		(*//When detect the input[1] match the output[1]*)
	    IF w_ReturnIndexChannel = w_PrevIndexChannel  THEN
	        (*//**********************************
	        //FOR any parameter only read once 
	        //***********************************)
	        IF arr_ValueIndex[w_PrevPtr] = 1  THEN
	            arr_Value[w_SumIndex] := arr_w_InputBuffer[2];
			END_IF;
	        (*//***********************************
	        //FOR any parameter read 6 words
	        //************************************)
	        IF arr_ValueIndex[w_PrevPtr] = 6 THEN
	            arr_Value[w_SumIndex] := arr_w_InputBuffer[7];
	            arr_Value[w_SumIndex - 1] := arr_w_InputBuffer[6];
	            arr_Value[w_SumIndex - 2] := arr_w_InputBuffer[5];
	            arr_Value[w_SumIndex - 3] := arr_w_InputBuffer[4];
	            arr_Value[w_SumIndex - 4] := arr_w_InputBuffer[3];
	            arr_Value[w_SumIndex - 5] := arr_w_InputBuffer[2];
	        END_IF;
	    END_IF;
	    IF NOT b_CommunicateOK OR b_ControlSwitchOff THEN
        	 IF arr_ValueIndex[w_PrevPtr] = 1  THEN
            		arr_Value[w_SumIndex] := 0;
        	 END_IF;
        	IF arr_ValueIndex[w_PrevPtr] = 6  THEN
            		arr_Value[w_SumIndex] :=0;
		            arr_Value[w_SumIndex - 1] := 0;
		            arr_Value[w_SumIndex - 2] := 0;
		            arr_Value[w_SumIndex - 3] := 0;
		            arr_Value[w_SumIndex - 4] := 0;
		            arr_Value[w_SumIndex - 5] := 0;
        	END_IF;
	   END_IF;

		(*//******************************************************************************************
		//Communication section
		//This section compare the Index value AND Input[1], i_CommTemp is used as a filter
		//to filter out some noise during write event
		//*******************************************************************************************)
	    IF (w_ReturnIndexChannel <>  w_PrevIndexChannel)  AND NOT  b_CommComp THEN
	        w_CommTemp := w_CommTemp +1;
	        b_CommComp := 1;
	    END_IF;
	    IF w_ReturnIndexChannel = w_PrevIndexChannel AND (w_PrevIndexChannel<>0) AND w_ReturnIndexChannel <> w_ReturnIndexChannelTemp THEN
	            b_ReadSuccess := 1;
	            w_CommTemp :=0;
	    END_IF; 
			    IF w_CommTemp > 10 THEN 
	           b_ReadSuccess := 0;
	    END_IF;

	IF NOT b_ReadSuccess AND b_ReadSuccessTemp THEN
					w_ReturnIndexChannelTemp:=w_ReturnIndexChannel;
		END_IF;
		b_ReadSuccessTemp:=b_ReadSuccess;
	END_IF;
		b_CycleCtrl := 0;
	  IF (arr_w_InputBuffer[1]= arr_w_OutputBuffer[1])  AND (w_OldIndexChannel <>arr_w_OutputBuffer[1]) THEN
	    	b_CycleCtrl := 1;
	    	w_OldIndexChannel  := arr_w_OutputBuffer[1];
	 END_IF;

	IF b_WriteEvent THEN 
		b_ReadSuccess :=1;
	END_IF;
	b_CommunicateOK := b_ReadSuccess;
	b_WriteFallingEdgeDetect := b_WriteEvent; 
	//Communication being established
	tm_CommStarting(IN := b_CommunicateOK, PT:= T#1000MS); 
	//b_CommStarting := b_CommunicateOK AND NOT tm_CommStarting.Q;
	(*******************************************************************************************************************************************************************************)
	//This section is used on Motor Enable Logic, When comm created, write 4660 to index 245 to disable the ctrl function of motor enable in control word,and 
	//Enable the index 245 for this index to control motor enable/disable.
	//When comm lost, remember the enable state and clear control words for motor enables,because these bits rely on rising edge ,when comm recreated
	//store back these bits into control word
	(********************************************************************************************************************************************************************************)	
	IF b_CommunicateOK AND b_CommRising THEN
		b_WriteDisableMotorCtrlWrd :=1;
	    b_ControlSwitchOff := FALSE;
	END_IF;
	b_CommRising := NOT 	b_CommunicateOK;
	tm_WriteWhenStartup(IN := b_WriteDisableMotorCtrlWrd, PT:= T#300MS);
	IF tm_WriteWhenStartup.Q THEN
		b_WriteDisableMotorCtrlWrd :=0;
		b_WriteEvent :=0;
	END_IF;
	IF b_WriteDisableMotorCtrlWrd THEN
		w_Command :=6;  
		arr_w_OutputBuffer[1] := 245;
		arr_w_OutputBuffer[2] := 4660;
		b_WriteEvent :=1;
	END_IF;
	
	(*//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	//Mapping Section
	//--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*)
	(*//**********************************************
	//Create Reading Tick to Generate Read Request
	//***********************************************)
	(*//Create Reading Tick*)
	tm_HMIRefresh(IN := NOT tm_HMIRefresh.Q , PT:= T#300MS); 
	(*//**************************************************************
	//Read Only Parameters
	//***************************************************************)
	(*//**************************************************************
	//Split Melter status word into status bits OF HMI structure
	//***************************************************************)
	IF NOT b_CommunicateOK OR b_ControlSwitchOff THEN
		arr_w_InputBuffer[0]	 :=0;
	END_IF;
	
	//arr_b_Status[0]												:= INT_TO_BITARR(arr_w_InputBuffer[0], 16);
	(*修改INT_TO_WORD的写法,修改TestABit的写法*)
	arr_b_Status:=IntToBit16(Input:=arr_w_InputBuffer[0]);
	//INT_TO_BITARR_Word:=INT_TO_WORD(In:=arr_w_InputBuffer[0]);
//	FOR INT_TO_BITARR_Cnt:=0 TO 15 BY 1 DO
//		arr_b_Status[INT_TO_BITARR_Cnt]:=TestABit(In:=INT_TO_BITARR_Word, Pos:=INT_TO_BITARR_Cnt);
//	END_FOR;
	
	w_ClearFaultWarning.mWord :=INT_TO_WORD(arr_Value[67]);
	Melter[MachineNum].b_r_Alert 							:= arr_b_Status[2];
	Melter[MachineNum].b_r_Fault 							:= arr_b_Status[3];
	Melter[MachineNum].b_r_LoseCommunication 				:= NOT b_CommunicateOK ;
	Melter[MachineNum].b_r_HeatOn 							:= arr_b_Status[5] OR Melter[MachineNum].b_r_StandbyOn OR Melter[MachineNum].b_r_ReadyForOperation;
	Melter[MachineNum].b_r_StandbyOn 						:= arr_b_Status[6];
	Melter[MachineNum].b_r_arrPumpRunning[0] 				:= arr_b_Status[7];
	Melter[MachineNum].b_r_arrPumpRunning[1]				:= arr_b_Status[8];
	Melter[MachineNum].b_r_ReadyForOperation 				:=arr_b_Status[0];
	
	//arr_b_CurrentAlarm[0]									:= INT_TO_BITARR(arr_Value[1], 16);
(*修改INT_TO_WORD的写法,修改TestABit的写法*)
	arr_b_CurrentAlarm :=IntToBit16(Input:= arr_Value[1]);
	//INT_TO_BITARR_Word:=INT_TO_WORD(In:=arr_Value[1]);
//	FOR INT_TO_BITARR_Cnt:=0 TO 15 BY 1 DO
//		arr_b_CurrentAlarm[INT_TO_BITARR_Cnt]:=TestABit(In:=INT_TO_BITARR_Word, Pos:=INT_TO_BITARR_Cnt);
//	END_FOR;
	
	Melter[MachineNum].b_r_TankLevelLow 							:= arr_b_CurrentAlarm[4];
	//arr_b_StatusAlarm[0]									:= INT_TO_BITARR(arr_Value[2], 16);
(*修改INT_TO_WORD的写法,修改TestABit的写法*)
	arr_b_StatusAlarm  :=IntToBit16(Input:= arr_Value[2]);
	//INT_TO_BITARR_Word:=INT_TO_WORD(In:=arr_Value[2]);
//	FOR INT_TO_BITARR_Cnt:=0 TO 15 BY 1 DO
//		arr_b_StatusAlarm[INT_TO_BITARR_Cnt]:=TestABit(In:=INT_TO_BITARR_Word, Pos:=INT_TO_BITARR_Cnt);
//	END_FOR;
	
	
	Melter[MachineNum].b_r_ServiceReminder						:= arr_b_StatusAlarm[3];
	Melter[MachineNum].b_r_PumpsOn									:= arr_b_Status[7] OR arr_b_Status[8] OR arr_b_Status[9] OR arr_b_Status[10];
	(*Motor Speed*)
	Melter[MachineNum].i_r_arrActualMotorSpeed[0]			:= arr_Value[5];
	Melter[MachineNum].i_r_arrActualMotorSpeed[1]			:= arr_Value[6];
	(*Motor Board Available*)
	
	//arr_b_BoardsInstalled[0]								:= INT_TO_BITARR(arr_Value[68],16);
	(*修改INT_TO_WORD的写法,修改TestABit的写法*)
	 arr_b_BoardsInstalled := IntToBit16(Input:=arr_Value[68] );
	//INT_TO_BITARR_Word:=INT_TO_WORD(In:=arr_Value[68]);
	//FOR INT_TO_BITARR_Cnt:=0 TO 15 BY 1 DO
	//	arr_b_BoardsInstalled[INT_TO_BITARR_Cnt]:=TestABit(In:=INT_TO_BITARR_Word, Pos:=INT_TO_BITARR_Cnt);
	//END_FOR;
	
	
	Melter[MachineNum].b_r_arrMotorBoardPresent[0]		:= arr_b_BoardsInstalled[4];
	Melter[MachineNum].b_r_arrMotorBoardPresent[1]		:= arr_b_BoardsInstalled[5];
	(*Control Switch Status*)
	
	IF arr_w_InputBuffer[1] = 10 AND arr_w_InputBuffer[2] = 6 AND NOT b_CtrlSwitchTemp THEN
		i_CtrlSwitchCNT :=i_CtrlSwitchCNT +1;
	END_IF;
	b_CtrlSwitchTemp :=(arr_w_InputBuffer[1] = 10 AND arr_w_InputBuffer[2] = 6);
	Melter[MachineNum].b_r_ControlSwitchOff :=(i_CtrlSwitchCNT>3);
	IF arr_w_InputBuffer[1] = 10 AND arr_w_InputBuffer[2] <> 6 THEN
			i_CtrlSwitchCNT :=0;
	END_IF;
	b_ControlSwitchOff :=Melter[MachineNum].b_r_ControlSwitchOff;
	
	(*Melter Temperature Reading and Status*)
	//BMOV(TRUE,arr_Value[30],18,Melter[MachineNum].i_r_arrTemperatureActual[0]);
	//BMOV(TRUE,arr_Value[11],18,Melter[MachineNum].i_r_arrTemperatureStatus[0]);
	
	FOR BMOV_Cnt :=0 TO 17 BY 1 DO 
		Melter[MachineNum].i_r_arrTemperatureActual[BMOV_Cnt]:= arr_Value[30+BMOV_Cnt];
		Melter[MachineNum].i_r_arrTemperatureStatus[BMOV_Cnt]:=arr_Value[11+BMOV_Cnt];
	END_FOR;
	
	
	Melter[MachineNum].i_r_TemperatureUnit := arr_Value[29];
	(*System Status bit*)
	Melter[MachineNum].i_r_SystemStatus :=7;
	IF Melter[MachineNum].b_r_ControlSwitchOff THEN
		Melter[MachineNum].i_r_SystemStatus :=10;
	END_IF;		
	IF Melter[MachineNum].b_r_HeatOn THEN
		Melter[MachineNum].i_r_SystemStatus :=6;
	END_IF;		
	IF Melter[MachineNum].b_r_ReadyForOperation THEN
		Melter[MachineNum].i_r_SystemStatus :=5;
	END_IF;	
	IF Melter[MachineNum].b_r_StandByOn THEN
		Melter[MachineNum].i_r_SystemStatus :=4;
	END_IF;
	IF Melter[MachineNum].b_r_Alert THEN
		Melter[MachineNum].i_r_SystemStatus :=3;
	END_IF;
	IF Melter[MachineNum].b_r_Fault THEN
		Melter[MachineNum].i_r_SystemStatus :=2;
	END_IF;
	IF Melter[MachineNum].b_r_LoseCommunication THEN
		Melter[MachineNum].i_r_SystemStatus :=1;
	END_IF;

	(*//******************************************************************************
	//Fill in the write buffer array with Index AND Channel
	//To generate write event correctly, the sequence OF  arr_WriteBuffer[i]
	//MUST match the sequence OF arr_WriteValueBuffer[i]
	//********************************************************************************)
	arr_WriteBuffer[0].w_Index := 116; arr_WriteBuffer[0].w_Channel:= 0;	(*//Global Setpoint*)

	FOR w_Cnt := 0 TO 17 BY 1 DO          															(*//Temperature Setpoints*)
	    arr_WriteBuffer[w_Cnt+1].w_Index := 115;
	    arr_WriteBuffer[w_Cnt+1].w_Channel := w_Cnt+1;
	END_FOR;
	arr_WriteBuffer[19].w_Index := 7;  arr_WriteBuffer[19].w_Channel:= 0;		(*//Clear Fault Warning*)
 	arr_WriteBuffer[20].w_Index := 32; arr_WriteBuffer[20].w_Channel := 1;	(*//Motor1 Speed Setpoint*)
  	arr_WriteBuffer[21].w_Index := 32; arr_WriteBuffer[21].w_Channel := 2;	(*//Motor1 Speed Setpoint*)
	arr_WriteBuffer[22].w_Index:=244;arr_WriteBuffer[22].w_Channel := 0;		(*//Motor Enables*)
	(*//*******************************************************************************************
	//This section is FOR the read AND write Variables
	//Every Refresh scan, get value from In_Value AND copy TO Out_Melter structure
	//IF the parameter is writable, it needs to BE writen to arr_WriteBuffer to generate write event.
	//********************************************************************************************)
	IF (tm_HMIRefresh.Q) THEN
		
		(*//Temperature Setpoints*)
		Melter[MachineNum].i_rw_TemperatureSp_Global := arr_Value[48];
		arr_WriteValueBuffer[0] := arr_Value[48];
	    
		//BMOV(TRUE,arr_Value[49],18,Melter[MachineNum].i_rw_arrTemperatureSp[0]);
	    //BMOV(TRUE,arr_Value[49],18,arr_WriteValueBuffer[1]);
		FOR BMOV_Cnt :=0 TO 17 BY 1 DO 
		Melter[MachineNum].i_rw_arrTemperatureSp[BMOV_Cnt]:= arr_Value[49+BMOV_Cnt];
		arr_WriteValueBuffer[1+BMOV_Cnt]:=arr_Value[49+BMOV_Cnt];
	    END_FOR;
		

	    (*//Temperature Activation*)
	    FOR w_Cnt :=0 TO 17 BY 1 DO
	    	IF Melter[MachineNum].i_rw_arrTemperatureSp[w_Cnt] >0 THEN
	    		Melter[MachineNum].b_rw_arrActiveHeaterZone[w_Cnt] := TRUE;
	    	ELSE 
	    		Melter[MachineNum].b_rw_arrActiveHeaterZone[w_Cnt] := FALSE;
	    	END_IF;
	    END_FOR;
	   		    
	    (*//Clear Fault  and Alarms*)
	   // arr_b_ClearFault[0]:= INT_TO_BITARR(arr_Value[67], 16);
	(*修改INT_TO_WORD的写法,修改TestABit的写法*)
	
	//INT_TO_BITARR_Word:=INT_TO_WORD(In:=arr_Value[67]);
	//FOR INT_TO_BITARR_Cnt:=0 TO 15 BY 1 DO
	//	arr_b_ClearFault[INT_TO_BITARR_Cnt]:=TestABit(In:=INT_TO_BITARR_Word, Pos:=INT_TO_BITARR_Cnt);
	//END_FOR;
	//original	
		(*
		arr_b_ClearFault:=IntToBit16(In:=arr_Value[67]);
	    Melter[MachineNum].b_w_ClearFaultWarning := arr_b_ClearFault[0]	;
		arr_WriteValueBuffer[19] := arr_Value[67];*)
	//modified
		Melter[MachineNum].b_w_ClearFaultWarning := w_ClearFaultWarning.mWord.0;
		arr_WriteValueBuffer[19] := arr_Value[67];
	
		(*//Motor Spd Setpoint*)
		FOR w_Cnt :=0 TO 1 BY 1 DO
			Melter[MachineNum].r_rw_arrManualMotorSpd_RPM[w_Cnt] := INT_TO_REAL (arr_Value[69+w_Cnt]);
			arr_WriteValueBuffer[20+w_Cnt] := arr_Value[69+w_Cnt];		
		END_FOR;
		(*Motor Enable Disable*)
		//arr_b_MotorEnable[0]					:= INT_TO_BITARR(arr_Value[4], 16);
	(*修改INT_TO_WORD的写法,修改TestABit的写法*)
	arr_b_MotorEnable :=IntToBit16(Input:= arr_Value[4]);
//	INT_TO_BITARR_Word:=INT_TO_WORD(In:=arr_Value[4]);
//	FOR INT_TO_BITARR_Cnt:=0 TO 15 BY 1 DO
//		arr_b_MotorEnable[INT_TO_BITARR_Cnt]:=TestABit(In:=INT_TO_BITARR_Word, Pos:=INT_TO_BITARR_Cnt);
//	END_FOR;	
		
		
		
	    (*Melter[MachineNum].i_rw_arrPumpMode[0]		:= BOOL_TO_INT( arr_b_MotorEnable[0]);*)
		IF  arr_b_MotorEnable[0]=TRUE THEN
			Melter[MachineNum].i_rw_arrPumpMode[0] := 0;
		ELSE
			Melter[MachineNum].i_rw_arrPumpMode[0] := 1;	
		END_IF;
		Melter[MachineNum].b_rw_arrPumpEnable[0]	:= arr_b_MotorEnable[1];
		b_Motor1AutoStart						:= arr_b_MotorEnable[2];
		
		(*Melter[MachineNum].i_rw_arrPumpMode[1]		:= BOOL_TO_INT(arr_b_MotorEnable[3]);*)
		IF   arr_b_MotorEnable[3]=TRUE THEN
			Melter[MachineNum].i_rw_arrPumpMode[1] := 0;
		ELSE
			Melter[MachineNum].i_rw_arrPumpMode[1] := 1;	
		END_IF;
			Melter[MachineNum].b_rw_arrPumpEnable[1]		:= arr_b_MotorEnable[4];
		b_Motor2AutoStart						:= arr_b_MotorEnable[5];
		Melter[MachineNum].b_rw_MasterPumpEnable := arr_b_MotorEnable[12];
		arr_WriteValueBuffer[22] 	 		:= arr_Value[4]; 
	END_IF;
	(*//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
	//Write Section
	//--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------*)
	(*//***********************************************************************************************************
	// Heater On Control Bit Logic
	//***********************************************************************************************************
	//**************************************
	//Heater command only detect rising edge
	//***************************************)
	IF Melter[MachineNum].b_w_HeatersOnOff AND NOT b_HeaterRisingTemp 	THEN 
		b_HeaterCommand :=1;
		b_HeaterRisingTemp :=1;
		ELSE b_HeaterCommand :=0;
	END_IF;

	IF NOT Melter[MachineNum].b_w_HeatersOnOff THEN  
		b_HeaterRisingTemp :=0;
	END_IF;
	(*//**********************************************************************
	//The folloiwng logic is to detect the status changing from melter side, 
	//so that the output command will match the status.
	//***********************************************************************)
	IF (NOT Melter[MachineNum].b_r_StandByOn) AND NOT Melter[MachineNum].b_r_ReadyForOperation AND NOT Melter[MachineNum].b_r_HeatOn AND b_TempStore1 AND NOT b_CommStarting AND b_CommunicateOK THEN
		b_HeaterOn := 0;
	END_IF;
	b_TempStore1 := Melter[MachineNum].b_r_HeatOn ;

	IF Melter[MachineNum].b_r_HeatOn AND b_TempStore2 THEN 
		b_HeaterOn := 1; 
	END_IF; 
	b_TempStore2 := NOT Melter[MachineNum].b_r_HeatOn ;

	(*//*********************************************************************************************************
	//melter V2.019, when heater is out OF standby mode,IF original status is ready,
	//AND at the time when standby is off, heater is NOT ready, the heateron status bit will turn off BY itself
	//The following logic is to turn the heat back on IF under this condition
	//**********************************************************************************************************)
	(*//***************************************************************************
	//tm_StandbyOffDetectDelay is used to delay when there is a falling edge
	//OF b_r_Standby,after this timer, detect IF there is heater on bit 
	//IF there is no heaton bit, which means the melter bug occurs(send back
	//b_r_heaterOn to zero),THEN it is needed to turn on the b_StandbyOffByitself
	//in heater control bit logic, it will turn on the heater.
	//****************************************************************************)
	tm_StandbyOff(IN := b_StandbyOffByItself, PT:= T#3000MS); 
	IF tm_StandbyOff.Q OR Melter[MachineNum].b_r_StandByOn THEN 
		b_StandbyOffByItself :=0; 
	END_IF;
	IF tm_StandbyOff.Q AND (NOT Melter[MachineNum].b_r_HeatOn) THEN 
		b_HeaterCommand :=1;
	END_IF;

	(*//************************************************************************
	//This section is to determine the output based on the status OF Melter[MachineNum].
	//*************************************************************************)
	IF b_HeaterCommand AND NOT Melter[MachineNum].b_r_HeatOn THEN 
		b_HeaterOn :=1; 
	END_IF;
	IF b_HeaterCommand AND Melter[MachineNum].b_r_HeatOn AND NOT (tm_CommStarting.In AND NOT tm_CommStarting.Q) AND b_CommunicateOK THEN 
		b_HeaterOn :=0;
		b_StandbyOn :=0; 
	END_IF;

	(*//***************************************************************
	//Below logic is to prevent HeaterOn OR HeaterOff stuck situation
	//****************************************************************)
	tm_HeaterOnStuck(IN := (NOT Melter[MachineNum].b_r_HeatOn) AND b_HeaterOn , PT:= T#3000MS); 
	b_HeaterOnStuck := tm_HeaterOnStuck.Q;

	tm_HeaterOffStuck(IN := Melter[MachineNum].b_r_HeatOn AND NOT b_HeaterOn , PT:= T#3000MS); 
	b_HeaterOffStuck := tm_HeaterOffStuck.Q;

	IF b_HeaterOnStuck AND b_HeaterOn AND NOT (tm_CommStarting.In AND NOT tm_CommStarting.Q) AND  b_CommunicateOK THEN 
		b_HeaterOn :=0;
		b_HeaterOnStuck:=0; 
	END_IF;
	IF b_HeaterOffStuck AND NOT b_HeaterOn AND NOT (tm_CommStarting.In AND NOT tm_CommStarting.Q) AND b_CommunicateOK  THEN 
		b_HeaterOn :=1; 
		b_HeaterOffStuck:=0; 
	END_IF;

	(*//********************************************************************
	// Need to set the command back to zero after the command is processed
	// to make the b_w_HeatersOnOff as a pulsing logic
	//*********************************************************************)
	IF Melter[MachineNum].b_w_HeatersOnOff THEN 
		Melter[MachineNum].b_w_HeatersOnOff :=0; 
	END_IF;
	arr_b_Control[0] := b_HeaterOn;
	
	(*//********************************************************************************************************************************
	//Standby Logic
	//*********************************************************************************************************************************)
	(*//*********************************************************************
	//The following section is to generate risng edge b_StandbyOnOffCommand 
	//from Melter[MachineNum].b_w_StandbyOnOff
	//**********************************************************************)
	IF Melter[MachineNum].b_w_StandbyOnOff AND NOT b_StandbyRisingTemp	THEN 
		b_StandbyOnOFFCommand :=1;
		b_StandbyRisingTemp:=1;
		ELSE b_StandbyOnOFFCommand :=0;
	END_IF;

	IF NOT Melter[MachineNum].b_w_StandbyOnOff	THEN 
		b_StandbyRisingTemp :=0;
	END_IF;

	(*//*************************************************************************************
	//This section is to detect the status change on Standby mode BY melter itself.
	//Detecting falling edge OF standby mode, at this moment IF heater is still on
	//THEN set b_StandbyOffByItself to 1 to enable standbyOff timer to fix the melter bug.
	//**************************************************************************************)
	tm_StandbyOffDetectDelay(IN := b_StandbyOffFallingEdge , PT:= T#200MS); 
	IF tm_StandbyOffDetectDelay.Q THEN
		IF Melter[MachineNum].b_r_HeatOn THEN 
			b_StandbyOffByItself :=1; 
		END_IF;
		b_StandbyOffFallingEdge :=0;
	END_IF;
	IF NOT Melter[MachineNum].b_r_StandByOn AND b_TempStore5 AND b_CommunicateOK  THEN 
		b_StandbyOn :=0;
		b_StandbyOffFallingEdge  :=1;
	END_IF; 
	b_TempStore5 := Melter[MachineNum].b_r_StandByOn;

	IF Melter[MachineNum].b_r_StandByOn AND b_TempStore6 THEN 
		b_StandbyOn :=1; 
	END_IF; 
	b_TempStore6 := NOT Melter[MachineNum].b_r_StandByOn;

	(*//*****************************************************************************
	//This section is to determine the standby output based on the status OF melter
	//with the rising edge standby on command b_StandbyOnOFFCommand.
	//******************************************************************************)
	IF (Melter[MachineNum].b_r_ReadyForOperation OR Melter[MachineNum].b_r_HeatOn) AND (NOT Melter[MachineNum].b_r_StandByOn) AND b_StandbyOnOFFCommand THEN 
		b_StandbyOn :=1;
	END_IF;
	IF Melter[MachineNum].b_r_StandByOn AND b_StandbyOnOFFCommand AND b_CommunicateOK THEN 
		b_StandbyOn :=0;
	END_IF;
	(*//********************************************************************
	// Need to set the command back to zero after the command is processed
	// to make the Melter[MachineNum].b_w_StandbyOnOff as a pulsing logic
	//*********************************************************************)
	IF Melter[MachineNum].b_w_StandbyOnOff THEN Melter[MachineNum].b_w_StandbyOnOff :=0; END_IF;

	(*//Below logic is to prevent StandbyOn OR StandbyOff stuck situation*)
	tm_StandbyOnStuck(IN := (NOT Melter[MachineNum].b_r_StandByOn) AND b_StandbyOn , PT:= T#3000MS); 
	b_StandbyOnStuck := tm_StandbyOnStuck.Q;

	tm_StandbyOffStuck(IN := Melter[MachineNum].b_r_StandByOn AND NOT b_StandbyOn , PT:= T#3000MS); 

	b_StandbyOffStuck := tm_StandbyOffStuck.Q;
	IF b_StandbyOnStuck AND b_StandbyOn AND b_CommunicateOK THEN 
		b_StandbyOn :=0;
		b_StandbyOnStuck:=0; 
	END_IF;
	IF b_HeaterOffStuck AND NOT b_StandbyOn THEN 
		b_StandbyOn :=1; 
		b_StandbyOffStuck:=0; 
	END_IF;
	arr_b_Control[6] := b_StandbyOn;

	(*//********************************************************************
	// Write Function :
	// Write Event is generated in PLC , first program will copy from 
	// Melter structure into a buffer array: arr_HMI_Buffer, THEN compare 
	// this array with the array coming from NDSN_FB_Map routing, to see 
	// IF there is any change in Melter structure, IF any difference, which 
	// means, there is an writing event inside Melter, THEN locate the index
	// AND channel number , THEN write to output channel 
	//*********************************************************************)
	arr_HMI_Buffer[0] := Melter[MachineNum].i_rw_TemperatureSp_Global;
	//BMOV(TRUE,Melter[MachineNum].i_rw_arrTemperatureSp[0],18,arr_HMI_Buffer[1]);
		FOR BMOV_Cnt :=0 TO 17 BY 1 DO 
		arr_HMI_Buffer[1+BMOV_Cnt]:=Melter[MachineNum].i_rw_arrTemperatureSp[BMOV_Cnt];
	    END_FOR;


	(*Clear Fault And Alarm*)
	//arr_HMI_Buffer[19] := BOOL_TO_INT(Melter[MachineNum].b_w_ClearFaultWarning);
	//original
	(*
		IF Melter[MachineNum].b_w_ClearFaultWarning THEN
			arr_HMI_Buffer[19+w_Cnt] :=1;
		ELSE 
			arr_HMI_Buffer[19+w_Cnt] :=0;
		END_IF;*)
	//modified---wei
	w_ClearFaultWarning.mWord.0 := Melter[MachineNum].b_w_ClearFaultWarning;
	arr_HMI_Buffer[19]:=WORD_TO_INT(w_ClearFaultWarning.mWord);
	
	(*Motor Setpoint*)
	arr_HMI_Buffer[20] :=REAL_TO_INT( Melter[MachineNum].r_rw_arrManualMotorSpd_RPM[0]);
	arr_HMI_Buffer[21] :=REAL_TO_INT(Melter[MachineNum].r_rw_arrManualMotorSpd_RPM[1]);	
	(*Motor Enable*)
	(*arr_b_MotorEnableWrite[0] 	:= INT_TO_BOOL( Melter[MachineNum].i_rw_arrPumpMode[0]);*)
	IF  Melter[MachineNum].i_rw_arrPumpMode[0] = 1 THEN
		arr_b_MotorEnableWrite[0] 	:= FALSE;
	ELSE
		arr_b_MotorEnableWrite[0] 	:= TRUE;
	END_IF;
	arr_b_MotorEnableWrite[1] 	:= Melter[MachineNum].b_rw_arrPumpEnable[0] ;
	arr_b_MotorEnableWrite[2] 	:= arr_b_MotorEnable[2];
	(*arr_b_MotorEnableWrite[3] 	:= INT_TO_BOOL(Melter[MachineNum].i_rw_arrPumpMode[1]);*)
		IF  Melter[MachineNum].i_rw_arrPumpMode[1] = 1 THEN
		arr_b_MotorEnableWrite[3] 	:= FALSE;
	ELSE
		arr_b_MotorEnableWrite[3] 	:= TRUE;
	END_IF;
	arr_b_MotorEnableWrite[4] 	:= Melter[MachineNum].b_rw_arrPumpEnable[1] ;
	FOR w_Cnt := 0 TO 6 BY 1 DO
			arr_b_MotorEnableWrite[5+w_Cnt] 	:= arr_b_MotorEnable[5+w_Cnt];	
	END_FOR;	
	arr_b_MotorEnableWrite[12] 	:= Melter[MachineNum].b_rw_MasterPumpEnable ;
		FOR w_Cnt := 0 TO 2 BY 1 DO
			arr_b_MotorEnableWrite[13+w_Cnt] 	:= arr_b_MotorEnable[13+w_Cnt];	
	END_FOR;	
	
	//arr_HMI_Buffer[22] 					:= BITARR_TO_INT(arr_b_MotorEnableWrite[0],16);
	(*修改写法*)
	arr_HMI_Buffer[22]:=Bit16ToInt(Input:=arr_b_MotorEnableWrite );
(*	
	BITARR_TO_INT_Word:=0;
	FOR BITARR_TO_INT_Cnt :=0 TO 15 BY 1 DO
		IF arr_b_MotorEnableWrite[BITARR_TO_INT_Cnt]  THEN
			SetABit(InOut:=BITARR_TO_INT_Word, Pos:=BITARR_TO_INT_Cnt);
		ELSE
	        ResetABit(InOut:=BITARR_TO_INT_Word, Pos:=BITARR_TO_INT_Cnt);
		END_IF;
	END_FOR;
		arr_HMI_Buffer[22] :=WORD_TO_INT(In:=BITARR_TO_INT_Word);
*)
	(*//*************************************************************************
	//Locate the write parameter AND find the  FOR Read TO read instantly
	//**************************************************************************)
	FOR w_Cnt := 0 TO w_Max_Write_Cnt BY 1 DO
	    (*//*******************************************************************************************************************************
	    //Event must happen when WriteActive is On, arr_Buffer_Pre[i] <> arr_HMI_Buffer[i] is to prevent multiple event FOR one parameter
	    //********************************************************************************************************************************)
	    IF arr_HMI_Buffer[w_Cnt] <> arr_WriteValueBuffer[w_Cnt] AND NOT b_WriteEvent AND (arr_Buffer_Pre[w_Cnt] <> arr_HMI_Buffer[w_Cnt]) AND b_CommunicateOK THEN
	        b_WriteEvent := 1;
	        w_WriteIndex := arr_WriteBuffer[w_Cnt].w_Index;
	        w_WriteChannel := arr_WriteBuffer[w_Cnt].w_Channel;
	        w_WriteValue := arr_HMI_Buffer[w_Cnt];
	    END_IF;
	    arr_Buffer_Pre[w_Cnt] := arr_HMI_Buffer[w_Cnt];
	END_FOR;

	(*//************************************************************
	//Get the index channel word to compare with the incoming word
	//*************************************************************)
	w_WriteIndexChannel := w_WriteIndex+ w_WriteChannel*256;
	tm_WriteEvent(IN := b_WriteEvent , PT:= T#300MS);

	(*//***************************
	//Write value to outputbuffer
	//****************************)
	IF b_WriteEvent AND NOT b_WriteDisableMotorCtrlWrd THEN 
		w_Command :=6;    (*//When Write Event, i_Command change to 6            //Command FOR Write*)
		arr_w_OutputBuffer[1] := w_WriteIndexChannel ;
		arr_w_OutputBuffer[2] := w_WriteValue;
	END_IF;      
	(*//Check the IF melter send any responde back*)
	IF tm_WriteEvent.Q THEN 
	    b_WriteEvent :=0; 
	END_IF;
	
	(*//************************************************
	//Output word0 including command AND control byte
	//*************************************************)
	 
	 //w_Control := BITARR_TO_INT(arr_b_Control[0], 8);
	(*修改写法*)
	 w_Control:=Bit16ToInt(Input:=arr_b_Control );
	 (*
	 BITARR_TO_INT_Word:=0;
	 FOR BITARR_TO_INT_Cnt :=0 TO 7 BY 1 DO
		IF arr_b_Control[BITARR_TO_INT_Cnt]  THEN
			SetABit(InOut:=BITARR_TO_INT_Word, Pos:=BITARR_TO_INT_Cnt);
		else
	        ResetABit(InOut:=BITARR_TO_INT_Word, Pos:=BITARR_TO_INT_Cnt);
		END_IF;
	END_FOR;
	w_Control :=WORD_TO_INT(In:=BITARR_TO_INT_Word);
	*) 
	arr_w_OutputBuffer[0] := w_Command*256 + w_Control; 
	
	(*//*********************************************
	//Copy output array buffer into Output
	//**********************************************)
	//BMOV(TRUE,arr_w_OutputBuffer[0],8, arr_w_Output[0]);
		FOR BMOV_Cnt :=0 TO 7 BY 1 DO 
		arr_w_Output[BMOV_Cnt]:=arr_w_OutputBuffer[BMOV_Cnt];
	    END_FOR;
	
	(**修改替换数据,看看是否正确,功能就是把2个byte变量拼接成一个INT变量,注意高低字节不能反**)	
	FOR w_Cnt:=0 TO 7 DO
		//ToAryByte(In:=arr_w_Output[w_Cnt], Order:=_HIGH_LOW, AryOut:=IO_outputByte[2*w_Cnt]);	
		UnPackWord1(wValue:=INT_TO_WORD(arr_w_Output[w_Cnt]) , 
					byLowByte=>IO_outputByte[2*w_Cnt+1] , 
					byHighByte=>IO_outputByte[2*w_Cnt] , );
	END_FOR;

