// ======工位到位======
StationVar.MoverInplace:=StationVar.MotionDone AND StationVar.InplaceSenser;
IF StationVar.MoverInplace THEN
	MoverInplaceTemp:=TRUE;
ELSIF NOT StationVar.MotionDone THEN
	MoverInplaceTemp:=FALSE;
END_IF;

// ======工位到位异常======
TON_MoverInplaceError(In:=StationVar.MotionDone, PT:=T#500MS);
StationVar.MoverInplaceError:=(TON_MoverInplaceError.Q OR MoverInplaceTemp) AND NOT StationVar.InplaceSenser;

// ======动子未到位======
TON_MotionNotDone(In:=Auto AND NOT StationVar.MotionDone, PT:=T#2S, Q=>StationVar.MotionNotDone);

// ======工位到位延时信号======
TON_MoverInplaceDelay(In:=StationVar.MoverInplace, PT:=T#500MS, Q=>StationVar.MoverInplaceDelay);

// ======动子ID有效======
StationVar.MoverIDEffective:=StationVar.MotionDone
												AND StationVar.MoverID>=0
												AND StationVar.MoverID<=Parameter.MaxCarNo;
IF StationVar.MoverIDEffective THEN
	StationVar.MoverIDEffectiveValue:=StationVar.MoverID;
ELSE
	StationVar.MoverIDEffectiveValue:=0;
END_IF;

// ======工位请求======
StationVar.StationRequest:=Auto
											AND StationVar.MoverInplace
											AND StationVar.StationRequestCondition
											AND (StationVar.MoverIDEffective
											AND NOT Persistent1.VehicleShielding[StationVar.MoverIDEffectiveValue]
											OR NOT StationVar.MoverIDEffective);

// ======工位允许======
StationVar.StationAllow:=StationVar.StationRequest AND StationVar.StationStatus;

// ======工位状态异常======
StationVar.StationStatusError:=Auto
											AND StationVar.MoverInplace
											AND StationVar.MoverIDEffective
											AND NOT Persistent1.VehicleShielding[StationVar.MoverIDEffectiveValue]
											AND NOT StationVar.StationStatus
											AND StationVar.StationRequest ;
											;

// ======工位完成======
StationVar.StationComplete:=Auto
												AND StationVar.MoverInplace
												AND NOT StationVar.StationRequest
												AND StationCompleteTemp;																				
StationCompleteTemp:=Auto
												AND StationVar.MoverInplace
												AND NOT StationVar.StationRequest;

// ======工位ID跳变异常======
IF StationVar.MotionDone
	AND StationAllowTemp
	AND MoverIDTemp<>StationVar.MoverID
THEN
	StationVar.MoverIDError:=TRUE;
END_IF;
IF StationVar.StationAllow THEN
	StationAllowTemp:=TRUE;
ELSIF NOT StationVar.MotionDone THEN
	StationAllowTemp:=FALSE;
END_IF;
MoverIDTemp:=StationVar.MoverID;

// ======工位加工状态显示======
IF StationVar.MoverInplace
	AND StationVar.StationComplete
	AND StationVar.StationMovingAllow
THEN
	StationVar.H_StationStatus:=2;//工位完成
ELSIF StationVar.MoverInplace
THEN
	StationVar.H_StationStatus:=1;//工位到位
ELSE
	StationVar.H_StationStatus:=0;//未到位
END_IF;

