	Permit[6]:=	Cy4.In.Manual_R XOR Command_Temp[6]	;
	Permit[7]:=	Cy4.In.Manual_V XOR Command_Temp[7]	;


	CASE Process_steps OF
	0://流程开始
		IF Permit[0] THEN
			Process_steps			:=100;
		ELSIF Permit[1] THEN
			Process_steps			:=200;
		ELSIF Permit[2] THEN
