CASE iMODE OF
    0:;
    1: // 托盘段滚轮对接
        // 取料准备
        stInteractive.bPickRdy_A := bPickRdyCon; // 上下料输送滚轮接料运行中，伺服在下层取空盘位置
        // 取料完成
        stInteractive.bPickComplete_A := bPickCompleteCon; // 托盘脱离上下料输送滚轮进料安全光电
        // 取料可移动
        stInteractive.bPickMoveEnable_A := bPickMoveEnableCon; // N.A
        // 放料准备
        stInteractive.bPutRdy_A := bPutRdyCon; // 上下料输送滚轮有盘，伺服在上层送盘位置
        // 放料完成
        stInteractive.bPutComplete_A := bPutCompleteCon; // 脱离上下料输送滚轮进料安全光电
        // 放料可移动
        stInteractive.bPutMoveEnable_A := bPutMoveEnableCon; // N.A
        // 扫码完成
        stInteractive.bReadOk_A := bReadOkCon; // N.A
        //设备就绪
        stInteractive.bMachineRdy_A := bSafetyOk;
    2: // 托盘段夹爪对接
        // 取料准备
        stInteractive.bPickRdy_A := bPickRdyCon; // 主机台取料夹爪为空或主机台在执行取料任务中
        // 取料完成
        stInteractive.bPickComplete_A := bPickCompleteCon; // 主机台取料夹爪从物流线上完成取料，且Z轴回到了安全高度；
        // 取料可移动
        stInteractive.bPickMoveEnable_A := bPickMoveEnableCon; // 1-主机台取料夹爪Z轴在安全高度，且没有Z轴伺服P2P取料指令；
															   // 2-或主机台取料夹爪横移轴不在物流取料区间；
        // 放料准备
        stInteractive.bPutRdy_A := bPutRdyCon; // 主机台放料夹爪有料或主机台在执行放料任务中；
        // 放料完成
        stInteractive.bPutComplete_A := bPutCompleteCon; // 主机台放料夹爪从物流线上完成放料，且Z轴回到了安全高度；
        // 放料可移动
        stInteractive.bPutMoveEnable_A := bPutMoveEnableCon; // 1-主机台放料夹爪Z轴在安全高度，且没有Z轴伺服P2P放料指令；
															 // 2-或主机台放料夹爪横移轴不在物流放料区间；
        // 扫码完成
        stInteractive.bReadOk_A := bReadOkCon;
        //设备就绪
        stInteractive.bMachineRdy_A := bSafetyOk;
    3: // 电池段皮带对接
        // 取料准备
        stInteractive.bPickRdy_A := bPickRdyCon; // 接料输送皮带接料运行中
        // 取料完成
        stInteractive.bPickComplete_A := bPickCompleteCon; // 托盘脱离接料输送皮带进料安全光电
        // 取料可移动
        stInteractive.bPickMoveEnable_A := bPickMoveEnableCon; // N.A
        // 放料准备
        stInteractive.bPutRdy_A := bPutRdyCon; // 送料输送皮带有电池,且电池已运行到出料位置
        // 放料完成
        stInteractive.bPutComplete_A := bPutCompleteCon; // 脱离送料输送皮带出料安全光电
        // 放料可移动
        stInteractive.bPutMoveEnable_A := bPutMoveEnableCon; // N.A
        // 扫码完成
        stInteractive.bReadOk_A := bReadOkCon;
        //设备就绪
        stInteractive.bMachineRdy_A := bSafetyOk;
    4: // 电池段夹爪对接
        // 取料准备
        stInteractive.bPickRdy_A := bPickRdyCon; // 主机台取料夹爪为空或主机台在执行取料任务中
        // 取料完成
        stInteractive.bPickComplete_A := bPickCompleteCon; // 主机台取料夹爪从物流线上完成取料，且Z轴回到了安全高度；
        // 取料可移动
        stInteractive.bPickMoveEnable_A := bPickMoveEnableCon; // 1-主机台取料夹爪Z轴在安全高度，且没有Z轴伺服P2P取料指令；
															   // 2-或主机台取料夹爪横移轴不在物流取料区间；
        // 放料准备
        stInteractive.bPutRdy_A := bPutRdyCon; // 主机台放料夹爪有料或主机台在执行放料任务中；
        // 放料完成
        stInteractive.bPutComplete_A := bPutCompleteCon; // 主机台放料夹爪从物流线上完成放料，且Z轴回到了安全高度；
        // 放料可移动
        stInteractive.bPutMoveEnable_A := bPutMoveEnableCon; // 1-主机台放料夹爪Z轴在安全高度，且没有Z轴伺服P2P放料指令；
															 // 2-或主机台放料夹爪横移轴不在物流放料区间；
        // 扫码完成
        stInteractive.bReadOk_A := bReadOkCon;
        //设备就绪
        stInteractive.bMachineRdy_A := bSafetyOk;
    ELSE
        ;
END_CASE

{REGION 输出}
    //取料准备
    stInteractive.bPickRdyOut := (bAuto AND stInteractive.bPickRdy_A AND NOT stInteractive.bDisableLgs)
    OR (bManual AND stInteractive.bPickRdy_M);

    //取料完成
    stInteractive.bPickCompleteOut := (bAuto AND stInteractive.bPickComplete_A AND NOT stInteractive.bDisableLgs)
    OR (bManual AND stInteractive.bPickComplete_M);

    //取料可移动
    stInteractive.bPickMoveEnableOut := ( (*bAuto AND *)
    stInteractive.bPickMoveEnable_A AND NOT stInteractive.bDisableLgs)
    OR (bManual AND stInteractive.bPickMoveEnable_M);

    //放料准备
    stInteractive.bPutRdyOut := (bAuto AND stInteractive.bPutRdy_A AND NOT stInteractive.bDisableLgs)
    OR (bManual AND stInteractive.bPutRdy_M);

    //放料完成
    stInteractive.bPutCompleteOut := (bAuto AND stInteractive.bPutComplete_A AND NOT stInteractive.bDisableLgs)
    OR (bManual AND stInteractive.bPutComplete_M);

    //放料可移动
    stInteractive.bPutMoveEnableOut := ( (*bAuto AND *)
    stInteractive.bPutMoveEnable_A AND NOT stInteractive.bDisableLgs)
    OR (bManual AND stInteractive.bPutMoveEnable_M);

    //扫码完成
    stInteractive.bReadOkOut := (bAuto AND stInteractive.bReadOk_A AND NOT stInteractive.bDisableLgs)
    OR (bManual AND stInteractive.bReadOk_M);

    //设备就绪
    stInteractive.bMachineRdyOut := ( (*bAuto AND *)stInteractive.bMachineRdy_A (*AND NOT stInteractive.bDisableLgs*))
    OR (bManual AND stInteractive.bMachineRdy_M);
{ENDREGION}

(*====== 程序简介 ========================================================================================================
 @ 名称				:	FB_CommandFollow
 @ 描述				:	命令同步功能块
 @ 作者				:	ZZT
 @ 日期				:	2024.05.01
 @ 版本号			:	V1.00.00.240501
 @ 配套				:
 @ 限制等级		:	A2.原则上不允许改动	
 =========================================================================================================================
 @ 说明				:	
 @ 主要功能        :	
 
 ===== 修改履历 ===========================================================================================================
 修改日期	| 版本			| 作者			| 备注 
 -------------------------------------------------------------------------------------------------------------------------
 2024.05.01	| V1.00.00		| ZZT	        | 初版发布

 ======= END ==============================================================================================================*)

IF NOT In THEN
	
	Cy2.In.Auto_R:=Cy1.In.Auto_R;
	Cy2.In.Auto_V:=Cy1.In.Auto_V;

END_IF;

TON_Hold(In:=Process_steps=500, PT:=T#300MS);

IF In THEN

	//同步H_Cy1给其他
	Permit[0]:=	Cy1.In.Manual_R XOR Command_Temp[0]	;
	Permit[1]:=	Cy1.In.Manual_V XOR Command_Temp[1]	;
	
	
	//同步H_Cy2给其他
	Permit[2]:=	Cy2.In.Manual_R XOR Command_Temp[2]	;
	Permit[3]:=	Cy2.In.Manual_V XOR Command_Temp[3]	;


	CASE Process_steps OF
	0://流程开始
		IF Permit[0] THEN
			Process_steps			:=100;
		ELSIF Permit[1] THEN
			Process_steps			:=200;
		ELSIF Permit[2] THEN
			Process_steps			:=300;
		ELSIF Permit[3] THEN
			Process_steps			:=400;
		END_IF;
	
	100://同步H_Cy1给其他
		//////命令赋值//////
		Cy2.In.Manual_R:=Cy1.In.Manual_R;
		
		Cy1.In.Manual_V:=FALSE;
		Cy2.In.Manual_V:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;

		////跳步
		Process_steps				:=500;
	200://同步H_Cy1给其他
		//////命令赋值//////
		Cy2.In.Manual_V:=Cy1.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;

		////跳步
		Process_steps				:=500;

	300://同步H_Cy2给其他
		//////命令赋值//////
		Cy1.In.Manual_R:=Cy2.In.Manual_R;
		
		Cy1.In.Manual_V:=FALSE;
		Cy2.In.Manual_V:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;

		////跳步
		Process_steps				:=500;
		
	400://同步H_Cy2给其他
		//////命令赋值//////
		Cy1.In.Manual_V:=Cy2.In.Manual_V;
		
		Cy1.In.Manual_R:=FALSE;
		Cy2.In.Manual_R:=FALSE;
		Command_Temp[0]:=Cy1.In.Manual_R;
		Command_Temp[1]:=Cy1.In.Manual_V;
		Command_Temp[2]:=Cy2.In.Manual_R;
		Command_Temp[3]:=Cy2.In.Manual_V;

		////跳步
		Process_steps				:=500;
		
	500://命令挂起
		IF TON_Hold.Q THEN
			Process_steps				:=0;
		END_IF;
	
	END_CASE;

END_IF;

(*====== 程序简介 ==========================================================================================================
 @ 名称               :   "Hymson_CycleTime"                                                                                               
 @ 描述               :   工位计时功能块                                                                                 
 @ 作者               :   李传俊                                                                                                
 @ 日期               :   2023.03.03                                                                                         
 @ 版本号             :   V3.03.00
 @ 配套               :                                                                                                       
 @ 限制等级           :   A1.不允许改动                                                            
 ==========================================================================================================================
 @ 说明               :   用于工位流程步骤计时，已经接口化，在外部调用引脚即可
 @                      
 ===== 修改履历 ===========================================================================================================
 修改日期   | 版本                | 作者            | 备注 
 ---------------------------------------------------------------------------------------------------------------------------
 2021.12.13 | V3.02.00            | 李传俊          | 迭代发布
 ---------------------------------------------------------------------------------------------------------------------------
 2023.03.03 | V3.03.00            | 李传俊          | 输出时间转换为实数单位秒
 													  上位采集增加输出“本次有效步数”
 ======= END ==============================================================================================================*)
//Stepdata		:=	UPPER_BOUND(InStepCycleTime.StepNum,1)		;


//HMI完成信号采样自动复位
Complete_TON(
            IN  :=  HMICycleTime.RecordDone_R                                                                     ,
            PT  :=  T#3S
            );
IF Complete_TON.Q
THEN
    HMICycleTime.RecordDone_R                  := FALSE                                                            ;
    IF  HMICycleTime.ScadaStart
    THEN
        ;//InCollectionErr                        :=  TRUE                                                            ;
    END_IF;
END_IF;


StepTimeTON(
            IN:=    StepTimeTON_IN                                                                                 ,
            PT:=    T#9999S
            );

StepCycleTime(
            IN:=    StepCycleTime_IN                                                                               ,
            PT:=    T#9999S
            );


(*******************************************************************************************************)
Complete_R(CLK := Complete);   

IF ClearData(*清除*)
    OR HMICycleTime.ClearData
THEN
	Clear(InStepCycleTime);
    HMICycleTime.StepCycleTime                 	:=  InStepCycleTime                                                	;
    InStationCycleTime                         	:=  T#0S                                                         	;
	InCollectionErr            					:= 	FALSE                        									;
    InOverflowErr                              	:= 	FALSE                        									;  
    MemProgramStep                             	:=  ProgramStep                                                    	;
	ClearData              						:= 	FALSE                       									;
    HMICycleTime.ClearData                  	:= 	FALSE                       									;
  	StepTimeTON_IN                     			:= 	FALSE                                                         	;
	StepCycleTime_IN                       		:= 	FALSE                                                       	;
	i                                          	:=  0                                                             	;
ELSIF 	Execute   
    	AND NOT InOverflowErr
THEN
    IF Condition (*内部，总周期时间计算标志*)    (*当TRUE时才会计算步骤时间*)
    THEN
        StepTimeTON_IN                       	:= TRUE                                                         	;
        StepCycleTime_IN                     	:= TRUE                                                          	;

        InStepCycleTime.StepTime[i]         	:=  TO_REAL(StepTimeTON.ET)/1000.0                         		;
        InStepCycleTime.StepNum[i]          	:=  MemProgramStep                                             		;
    END_IF;

    IF Complete_R.Q
    THEN
        HMICycleTime.StepCycleTime 				:= InStepCycleTime                                            		;
        InStationCycleTime                     	:= StepCycleTime.ET                                                	;
        StepCycleTime_IN                       	:= FALSE                                                       		;
        StepTimeTON_IN                         	:= FALSE                                                        	;
        Clear(InStepCycleTime);                                                                                 	;
		HMICycleTime.EnableStepNo				:= i																;
        i                                      	:= 1                                                             	;
        HMICycleTime.RecordDone_R              	:= TRUE                                                           	;
		HMICycleTime.ScadaStart					:= TRUE																;
    ELSIF MemProgramStep <> ProgramStep
    THEN
        IF Condition
        THEN
            StepTimeTON_IN                     	:= FALSE                                                         	;
            i                                  	:=  i + 1                                                        	;
        END_IF;

        IF  i>=StepNum+1
        THEN
            InOverflowErr                   	:=  TRUE                                                        	;
            InStationCycleTime                 	:=  T#0S                                                       		;
            HMICycleTime.StepCycleTime         	:=  InStepCycleTime                                                	;
            Clear(InStepCycleTime);
            i                                  	:=  0                                                             	;
        END_IF;
    END_IF;
      
    IF Condition
    THEN
        InStepCycleTime.StepNum[i]            	:=  ProgramStep                                                    ;
    END_IF;
    MemProgramStep                             	:=  ProgramStep                                                    ;
ELSIF   InOverflowErr
    AND Reset
THEN
    InOverflowErr                              	:=  FALSE                                                         	;
ELSIF   InCollectionErr
    	AND Reset
THEN
  	StepTimeTON_IN                     			:= 	FALSE                                                         	;
	StepCycleTime_IN                       		:= 	FALSE                                                       	;
    InCollectionErr                            	:=  FALSE                                                         	;
END_IF;

Complete                                       	:=  FALSE                                                       	;

HMICycleTime.OverflowErr                       	:=  InOverflowErr                                                  	;
HMICycleTime.CollectionErr                     	:=  InCollectionErr                                                	;

CT_I                 	:=  TO_REAL(InStationCycleTime)/1000.0                         	;
IF CT_I > 99 THEN
	HMICycleTime.StationCycleTime                  	:=  99.99                       	;
	ELSE
	HMICycleTime.StationCycleTime                  	:=  CT_I                       	;
END_IF  ;

IF HMICycleTime.StationCycleTime  > 0    THEN
	PPM_I 	:=  60/ HMICycleTime.StationCycleTime  ; 
ELSE  PPM_I 	:=  0                      	; 
END_IF ;

IF PPM_I >99   THEN
   HMICycleTime.PPM 	:=  99.99 	; 
ELSE
   HMICycleTime.PPM 	:=  PPM_I 	; 
END_IF ;

RT 							:= 	FALSE									;

TON_PULSE(IN:=TRUE)														;

IF TON_PULSE.Q
	AND Q
THEN
	TON_PULSE(
		IN					:=	FALSE  									,
		PT					:= 	PT_OFF
		);
	TON_PULSE(IN:=TRUE)													;
	RT 						:= 	Q										;
	Q 						:= 	FALSE									;
ELSIF TON_PULSE.Q
	AND NOT Q
THEN
	RT 						:= 	NOT Q									;
	TON_PULSE(
		IN					:= 	FALSE 									,
		PT					:= 	PT_ON
		);
	TON_PULSE(IN:=TRUE)													;
	Q 						:= 	TRUE									;
END_IF

(*====== 程序简介 ========================================================================================================
 @ 名称				:	FB_GolytecControl	
 @ 描述				:	果栗磁轨控制功能块
 @ 作者				:	FGQ
 @ 日期				:	2022.5.11
 @ 版本号			:	V3.00.02
 @ 配套				:
 @ 限制等级		:	A2.原则上不允许改动	
 =========================================================================================================================
 @ 说明				:	用于果栗磁轨控制控制，已经接口化，在外部调用引脚即可，已封装了32个动子和16个工位的控制
 								使用注意事项：Out.StationMotionDone信号外部判断使用上升沿
 @ 
 ===== 修改履历 ===========================================================================================================
 修改日期		| 版本			| 作者			| 备注 
 -------------------------------------------------------------------------------------------------------------------------
 2021.12.09	| V1.00.00		| MXM	        | 初版发布
 2022.5.11	| V2.00.00		| FGQ	        | 正式版发布
 2022.10.12	| V3.00.00		| KZYK	        | 工位，动子从5个增加到127个，增加动子单独动作，增加ID写入，增加动子偏移，增加动态指向
 2022.12.17	| V3.00.01		| KZYK	        | 增加心跳，干涉报警
 2023.03.13	| V3.00.02		| KZYK	        | 自动运行或者自动暂停的状态都是在自动状态，修改ControlWord0.9在非自动状态进入自动状态时输出
 2023.03.13	| V3.00.02		| KZYK	        | 修改动态指向导致动子位置无法写入
 
 ======= END ==============================================================================================================*)

(************************************1、状态字****************************************)
//心跳
TON_HeartBeat(PT:=T#2S);
IF HeartBeatTemp <> GolytecInputToPLC.Resolution_6000_05 OR Reset THEN
 		HeartBeatTemp := GolytecInputToPLC.Resolution_6000_05;
		TON_HeartBeat.In:=FALSE;
ELSE
	TON_HeartBeat.In:=TRUE;
END_IF;
//心跳定时器
IF TON_HeartBeat.Q THEN
	ErrOut.HeartBeatErr:=TRUE;
END_IF;

StatusWord.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.sys_status_6000_01);
FC_WordToAryBool(StatusWord.mWord[0],0,StatusWord_mBit,0,16);
FC_WordToAryBool(StatusWord.mWord[1],0,StatusWord_mBit,16,16);
//初始化中
H_Out.Initializing:=StatusWord_mBit[0];
Out.Initializing:=StatusWord_mBit[0];

//初始化完成
H_Out.Inited:=StatusWord_mBit[1];
Out.Inited:=StatusWord_mBit[1];

//自动中
H_Out.Station_auto:=StatusWord_mBit[2];
//自动信号延时1S输出保证其他的到位信号先收到
TON_CQAuto(In:=StatusWord_mBit[2], PT:=T#1S, Q=>Out.Station_auto);
//Out.Station_auto:=StatusWord_mBit[2];

//自动暂停中
H_Out.Station_auto_pause:=StatusWord_mBit[3];
//Out.Station_auto_pause:=StatusWord_mBit[3];

//警告
H_Out.Warning:=StatusWord_mBit[7];
//Out.Warning:=StatusWord_mBit[7];
H_Out.SysErrID:=GolytecInputToPLC.sys_errno_6000_02;


//报警
H_Out.Error:=StatusWord_mBit[8];
Out.Error:=StatusWord_mBit[8];

IF StatusWord_mBit[8] OR ErrOut.HeartBeatErr THEN
	ErrOut.Alarm:=TRUE;
END_IF;

//总线状态
H_Out.EcatStatus:=StatusWord_mBit[12];
//Out.EcatStatus:=StatusWord_mBit[12];

//报警信息处理
H_Out.SysErrID:=GolytecInputToPLC.sys_errno_6000_02;
H_Out.ErrInfoCode:=GolytecInputToPLC.error_information_6000_14;
H_Out.ErrMoveNum:=GolytecInputToPLC.err_mover_id_6000_15;
H_Out.ErrStatorNum:=GolytecInputToPLC.err_stator_id_6000_16;


ErrInfoCodeWord.mWord:=UINT_TO_WORD(GolytecInputToPLC.error_information_6000_14);	//报警信息
FC_WordToAryBool(ErrInfoCodeWord.mWord,0,ErrInfoCodeWord_mBit,0,16);

//bit0	定子驱动板温度报警	检查风扇是否开启
IF ErrInfoCodeWord_mBit[0] THEN	
	ErrOut.AlarmrInfo[0]:=TRUE;
END_IF;	
//bit1	模块温度报警	检查风扇是否开启
IF ErrInfoCodeWord_mBit[1] THEN	
	ErrOut.AlarmrInfo[1]:=TRUE;
END_IF;	
//bit2	模块电压过低	检查定子的动力电保险丝、电源、电源线是否正常，电源电力是否充足
IF ErrInfoCodeWord_mBit[2] THEN	
	ErrOut.AlarmrInfo[2]:=TRUE;
END_IF;
//bit3	供电电流过大	检查是否动子是否堵转或者碰撞
IF ErrInfoCodeWord_mBit[3] THEN	
	ErrOut.AlarmrInfo[3]:=TRUE;
END_IF;	
//bit4	风扇0转速过低	检查风扇0是否连接或者损坏
IF ErrInfoCodeWord_mBit[4] THEN	
	;//ErrOut.AlarmrInfo[4]:=TRUE;//20250322果栗供应商说取消
END_IF;
//bit5	风扇1转速过低	检查风扇1是否连接或者损坏
IF ErrInfoCodeWord_mBit[5] THEN	
	;//ErrOut.AlarmrInfo[5]:=TRUE;//20250322果栗供应商说取消
END_IF;	
//bit6	驱动板温度报警	检查风扇是否开启
IF ErrInfoCodeWord_mBit[6] THEN	
	ErrOut.AlarmrInfo[6]:=TRUE;
END_IF;	
//bit7	模块温度报警	检查风扇是否开启
IF ErrInfoCodeWord_mBit[7] THEN	
	ErrOut.AlarmrInfo[7]:=TRUE;
END_IF;
//bit8	通讯报警	检查光纤未插好、光纤线损坏、通讯模块损坏
IF ErrInfoCodeWord_mBit[8] THEN	
	ErrOut.AlarmrInfo[8]:=TRUE;
END_IF;	
//bit9	模块电源被切断	检查报错的定子保险丝是否烧坏，电源供电是否正常
IF ErrInfoCodeWord_mBit[9] THEN	
	ErrOut.AlarmrInfo[9]:=TRUE;
END_IF;	
//bit10	模块电路报错	检查报错的定子保险丝是否烧坏，电源供电是否正常
IF ErrInfoCodeWord_mBit[10] THEN	
	ErrOut.AlarmrInfo[10]:=TRUE;
END_IF;	
//bit11	模块电路电流报错	检查报错的定子保险丝是否烧坏，电源供电是否正常。如果全部正常，需使用万用表测量该定子电源接口的24V接插口是否有短路。如果短路，则需要更换定子线圈。
IF ErrInfoCodeWord_mBit[11] THEN	
	ErrOut.AlarmrInfo[11]:=TRUE;
END_IF;	
//bit12	模块电路电流报错	检查报错的定子保险丝是否烧坏，电源供电是否正常。如果全部正常，需使用万用表测量该定子电源接口的24V接插口是否有短路。如果短路，则需要更换定子线圈。
IF ErrInfoCodeWord_mBit[12] THEN	
	ErrOut.AlarmrInfo[12]:=TRUE;
END_IF;
//bit13 动子振荡报错  检查动子是否有异常
IF ErrInfoCodeWord_mBit[13] THEN	
	ErrOut.AlarmrInfo[13]:=TRUE;
END_IF;	
//bit14	动子急停报错	检查动子是否撞机
IF ErrInfoCodeWord_mBit[14] THEN	
	ErrOut.AlarmrInfo[14]:=TRUE;
END_IF;	
IF ErrInfoCodeWord_mBit[15] THEN	
	ErrOut.AlarmrInfo[15]:=TRUE;
END_IF;	



(************************************2、工位上是否有动子****************************************)
//工位上是否有动子0~63
StationInposLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_REACHED0_31_6002_17);
StationInposLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_REACHED32_63_6002_18);
FC_WordToAryBool(StationInposLWord1.mWord[0],0,StationInposLWord_mBit,0,16);
FC_WordToAryBool(StationInposLWord1.mWord[1],0,StationInposLWord_mBit,16,16);
FC_WordToAryBool(StationInposLWord2.mWord[0],0,StationInposLWord_mBit,32,16);
FC_WordToAryBool(StationInposLWord2.mWord[1],0,StationInposLWord_mBit,48,16);

//动子运动到位(工位上有动子且动子编号切换)
FOR i:=0 TO 63 DO
	//注意：自动流程要判断的是此信号上升沿
	Out.StationMotionDone[i]:=StationInposLWord_mBit[i]  //AND RecordLastStationMoverID[i]<>RecordCurStationMoverID[i]
												AND Out.Inited AND NOT StatusWord_mBit[8];
END_FOR;

//工位上是否有动子64~127
StationInposLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_REACHED64_95_6003_01);
StationInposLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_REACHED96_127_6003_02);
FC_WordToAryBool(StationInposLWord1.mWord[0],0,StationInposLWord_mBit,0,16);
FC_WordToAryBool(StationInposLWord1.mWord[1],0,StationInposLWord_mBit,16,16);
FC_WordToAryBool(StationInposLWord2.mWord[0],0,StationInposLWord_mBit,32,16);
FC_WordToAryBool(StationInposLWord2.mWord[1],0,StationInposLWord_mBit,48,16);
//动子运动到位(工位上有动子且动子编号切换)
FOR i:=0 TO 63 DO
	//注意：自动流程要判断的是此信号上升沿
	Out.StationMotionDone[i+64]:=StationInposLWord_mBit[i]  //AND RecordLastStationMoverID[i]<>RecordCurStationMoverID[i]
												AND StatusWord_mBit[2] AND NOT StatusWord_mBit[8];
END_FOR;
//HMI显示数据
H_Out.StationMotionDone:=Out.StationMotionDone;

(************************************3、工位上动子编号****************************************)

//工位上的动子编号 0-7   动子编号尽量不要用0
StationMoverIDLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_REACHED_AXIS_ID0_3_6002_29);
