(************************************4、安全条件****************************************)
//汇总所有安全条件
SumMotionAllow:=NOT ArySearch(In:=In.StationMotionAllow[0], Size:=Parameter.StationNoTotal, Key:=FKey, InOutPos:=Temp);

//汇总工位动子状态和安全条件
FOR i:=0 TO 97 DO
	SafeCondition[i]:=Out.StationMotionDone[i] AND In.StationMotionAllow[i];  //工位有动子时复位停止不会产生移动，为安全状态
END_FOR;

(************************************5、工位急停输入****************************************)
//获取0~63工位急停反馈
StationEMGLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_QSTOP0_31_6002_1F);
StationEMGLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_QSTOP32_63_6002_20);
FC_WordToAryBool(StationEMGLWord1.mWord[0],0,StationEMGLWord_mBit,0,16);
FC_WordToAryBool(StationEMGLWord1.mWord[1],0,StationEMGLWord_mBit,16,16);
FC_WordToAryBool(StationEMGLWord2.mWord[0],0,StationEMGLWord_mBit,32,16);
FC_WordToAryBool(StationEMGLWord2.mWord[1],0,StationEMGLWord_mBit,48,16);
 AryMove(In:=StationEMGLWord_mBit[0], AryOut:=Out.StationEMGStop[0], Size:=UINT#64);
 //获取64~127工位急停反馈
StationEMGLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_QSTOP64_95_6003_09);
StationEMGLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_QSTOP96_127_6003_0A);
FC_WordToAryBool(StationEMGLWord1.mWord[0],0,StationEMGLWord_mBit,0,16);
FC_WordToAryBool(StationEMGLWord1.mWord[1],0,StationEMGLWord_mBit,16,16);
FC_WordToAryBool(StationEMGLWord2.mWord[0],0,StationEMGLWord_mBit,32,16);
FC_WordToAryBool(StationEMGLWord2.mWord[1],0,StationEMGLWord_mBit,48,16);
 AryMove(In:=StationEMGLWord_mBit[0], AryOut:=Out.StationEMGStop[64], Size:=UINT#64);
 H_Out.StationEMGStop:=Out.StationEMGStop;
 
 (************************************6、工位暂停输入****************************************)
//获取0~63工位暂停反馈
StationStopLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_PAUSE0_31_6002_21);
StationStopLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_PAUSE32_63_6002_22);
FC_WordToAryBool(StationStopLWord1.mWord[0],0,StationStopLWord_mBit,0,16);
FC_WordToAryBool(StationStopLWord1.mWord[1],0,StationStopLWord_mBit,16,16);
FC_WordToAryBool(StationStopLWord2.mWord[0],0,StationStopLWord_mBit,32,16);
FC_WordToAryBool(StationStopLWord2.mWord[1],0,StationStopLWord_mBit,48,16);
 AryMove(In:=StationStopLWord_mBit[0], AryOut:=Out.StationPause[0], Size:=UINT#64);
//获取64~127工位暂停反馈
StationStopLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_PAUSE64_95_6003_0B);
StationStopLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_PAUSE96_127_6003_0C);
FC_WordToAryBool(StationStopLWord1.mWord[0],0,StationStopLWord_mBit,0,16);
FC_WordToAryBool(StationStopLWord1.mWord[1],0,StationStopLWord_mBit,16,16);
FC_WordToAryBool(StationStopLWord2.mWord[0],0,StationStopLWord_mBit,32,16);
FC_WordToAryBool(StationStopLWord2.mWord[1],0,StationStopLWord_mBit,48,16);
 AryMove(In:=StationStopLWord_mBit[0], AryOut:=Out.StationPause[64], Size:=UINT#64);
 H_Out.StationPause:=Out.StationPause;

 (************************************7、获取所有动子实时位置及状态显示****************************************)
//获取所有动子实时位置及状态显示
FOR i:=0 TO 97 DO
	H_Out.ActPos[i] := DINT_TO_REAL(GolytecInputToPLC.Mover_act_pos[i])/1000.0; //单位微米转换为毫米
//	H_Out.MoverCurrent[i] :=ABS(In:=INT_TO_REAL(UINT_TO_INT(GolytecInputToPLC.Mover_current_rd_id_6000_11)));//动子电流(单位mA)
	//H_Out.MoverCurrent[GolytecInputToPLC.max_mover_torque_id_6000_13] :=INT_TO_REAL(UINT_TO_INT(GolytecInputToPLC.max_mover_torque_6000_12));//动子电流(单位mA)	
	H_Out.MoverStatus_Available[i] 					:=	GolytecInputToPLC.Mover_status[i].mWord.0;//动子自由控制使能
	H_Out.MoverStatus_ServoOn[i] 					:=		GolytecInputToPLC.Mover_status[i].mWord.1;//动子是否已伺服
	H_Out.MoverStatus_Moving[i] 					:=		GolytecInputToPLC.Mover_status[i].mWord.2;//是否动作中
	H_Out.MoverStatus_QuickStop[i] 				:=		GolytecInputToPLC.Mover_status[i].mWord.3;//急停
	H_Out.MoverStatus_Locked[i]						:=		GolytecInputToPLC.Mover_status[i].mWord.4;//是否被锁定禁止移动
	H_Out.MoverStatus_TargetPosReached[i] 	:=		GolytecInputToPLC.Mover_status[i].mWord.5;//到达目标位置	
	H_Out.MoverStatus_QueuedBlock[i]			:=		GolytecInputToPLC.Mover_status[i].mWord.6;//动子临时排队等候中
	H_Out.MoverStatus_PosError[i] 					:=		GolytecInputToPLC.Mover_status[i].mWord.7;//位置误差超限错误
END_FOR;

 
//获取动子状态
IF UINT_TO_INT(MoverNum)>Parameter.MaxCarNo THEN
	MoverNum:=0;
END_IF;
PLCOutputToGolytec.mover_id_read_of_pos_7000_14:=MoverNum;  //映射需要读取位置的动子编号
ReadMoverActPos_TON(IN:=TRUE, PT:=T#20MS);
IF ReadMoverActPos_TON.Q AND GolytecInputToPLC.mover_id_read_of_pos_6001_06=PLCOutputToGolytec.mover_id_read_of_pos_7000_14 THEN
	H_Out.MoverCurrent[MoverNum]  :=UINT_TO_INT(GolytecInputToPLC.mover_current_rd_id_6000_11);//当前动子电流(单位mA)
	Inc(MoverNum);
	ReadMoverActPos_TON(IN:=FALSE);
END_IF;

 (************************************10、系统初始化****************************************)
//初始化
IF ((In.IniExecute AND NOT Hmx_Manual)  //Auto
	OR (H_In.IniExecute ))  //AND Hmx_Manual
	AND NOT StatusWord_mBit[1]						//未初始化		
	AND NOT StatusWord_mBit[8]						//无报警
	AND StatusWord_mBit[12]							//总线正常
	//AND SumMotionAllow								//安全条件
THEN
	ControlWord_mBit[0]:=TRUE;
ELSE
	ControlWord_mBit[0]:=FALSE;
END_IF;

 (************************************11、系统终止****************************************)
//系统终止,上升沿触发，需要重新初始化
IF H_In.SystemStop THEN
	ControlWord_mBit[1]:=TRUE;
ELSE
	ControlWord_mBit[1]:=FALSE;
END_IF;

(************************************12、移动到上次工位****************************************)
 //1、进入自动前给bit[9]，延时50ms再自动
 //2、磁驱有报警、未自动、已自动延时100ms，或手动禁止时   复位掉bit[9]
 
 //切自动
IF Auto AND  
	NOT (StatusWord_mBit[2] OR StatusWord_mBit[3])      //未自动运行或暂停中
	AND StatusWord_mBit[1]										//初始化完成	
	AND NOT StatusWord_mBit[2]						//未自动
	AND NOT StatusWord_mBit[8]						//无报警
	AND StatusWord_mBit[12]							//总线正常
	AND NOT Aborting
	AND NOT H_In.ToLastPos
THEN
 	ControlWord_mBit[9]:=TRUE;
END_IF;
 
TON_Delay1(In:=StatusWord_mBit[2]  OR StatusWord_mBit[3],PT:=T#100MS); //自动状态
IF  TON_Delay1.Q
	OR NOT  StatusWord_mBit[1]   //未初始化
	OR  StatusWord_mBit[8]	//报警
	OR NOT StatusWord_mBit[12] //总线异常
	OR H_In.ToLastPos
THEN
	ControlWord_mBit[9]:=FALSE;
END_IF;
 
 

 (************************************13、切自动****************************************)
//手自动切换变量复位
IF NOT Auto THEN
	Clear(In.StationMotion);
END_IF;
IF NOT Hmx_Manual THEN
	Clear(H_In.StationMotion);
END_IF;

//回到上次位置延时再进入自动   H_In.ToLastPos TRUE时是不回
TON_Bit9On(In:=ControlWord_mBit[9]  OR H_In.ToLastPos OR StatusWord_mBit[2] OR StatusWord_mBit[3], PT:=T#50ms);
//切自动
IF Auto      //自动状态
	AND StatusWord_mBit[1]										//初始化完成	
	AND NOT StatusWord_mBit[2]						//未自动
	AND NOT StatusWord_mBit[3]						//未暂停自动
	AND NOT StatusWord_mBit[8]						//无报警
	AND StatusWord_mBit[12]							//总线正常
	//AND SumMotionAllow								ll//安全条件
	AND NOT Aborting
THEN
	//1 bit9先为1 或者屏蔽bit9
	IF TON_Bit9On.Q
	THEN
		//H_In.ToLastPos:=FALSE;
		ControlWord_mBit[2]:=TRUE;
	END_IF;
ELSE
	ControlWord_mBit[2]:=FALSE;
END_IF;	
 (************************************14、自动运行中止****************************************)
//自动终止,上升沿触发
IF  H_In.StationAutoRunStop  AND ( StatusWord_mBit[2] OR StatusWord_mBit[3] )   THEN
	ControlWord_mBit[3]:=TRUE;
ELSE
	ControlWord_mBit[3]:=FALSE;
END_IF;

 (************************************15、整机暂停****************************************)
 //暂停,上升沿触发
IF (Aborting OR H_In.PauseExcute   OR  Hmx_Manual )  AND (StatusWord_mBit[2] OR StatusWord_mBit[8] OR StatusWord_mBit[7]) THEN
	ControlWord_mBit[4]:=TRUE;
ELSE
	ControlWord_mBit[4]:=FALSE;
END_IF;

  (************************************16、整 机暂停恢复****************************************)
 //复位停止状态，中间动子会移动到最近工位
IF StatusWord_mBit[3] 
	AND (Auto OR H_In.ResumeAuto)
THEN
	ControlWord_mBit[5]:=TRUE;
ELSE
	ControlWord_mBit[5]:=FALSE;
END_IF;

 (************************************17、保留****************************************)


 (************************************18、所有动子停止运动,停止后动子不断电****************************************)
  

 (************************************19、系统急停****************************************)
 //系统急停,上升沿触发
IF H_In.SystemEMG THEN
	ControlWord_mBit[8]:=TRUE;
ELSE
	ControlWord_mBit[8]:=FALSE;
END_IF;


 (************************************20、报警复位****************************************)
//报警复位
IF ( Auto OR DS_Stop ) AND Reset AND (StatusWord_mBit[8] OR StatusWord_mBit[7]) THEN
	ControlWord_mBit[12]:=TRUE;
ELSE
	ControlWord_mBit[12]:=FALSE;
END_IF;

 (************************************21、所有动子上电****************************************)
//所有动子上电,上升沿触发
IF H_In.AllMoversPowerOn 
	AND NOT StatusWord_mBit[2] //不在自动运行中
	AND StatusWord_mBit[1] //系统初始化完成
	THEN
	ControlWord_mBit[16]:=TRUE;
ELSE
	ControlWord_mBit[16]:=FALSE;
END_IF;
 (************************************22、所有动子断电****************************************)
//所有动子断电,上升沿触发
IF H_In.AllMoversPowerOff 
	AND NOT StatusWord_mBit[2] //不在自动运行中
	AND StatusWord_mBit[1] //系统初始化完成
	THEN
	ControlWord_mBit[17]:=TRUE;
ELSE
	ControlWord_mBit[17]:=FALSE;
END_IF;

//系统控制字中转映射
FC_AryBoolToAryWord(AryBool:=ControlWord_mBit , AryWord:=ControlWord.mWord );
PLCOutputToGolytec.sys_control_7000_01:=DWORD_TO_UDINT(ControlWord.mDWord);

IF StatusWord_mBit[8] THEN
	ErrOut.Alarm:=TRUE;
END_IF;
IF Reset THEN
	Clear(ErrOut);
END_IF;


 (************************************自动状态不允许操作驰驱****************************************)
IF (Auto OR NOT HMI_MaintenanceMode[2] )  AND NOT HMI_MaintenanceMode[3]  THEN   //自动 时 不允许修改
	ControlWord_mBit[20]:=FALSE;
	ControlWord_mBit[21]:=TRUE;	
	ControlWord_mBit[22]:=TRUE;	
	ControlWord_mBit[23]:=FALSE;	
ELSIF (HMI_MaintenanceMode[1] AND HMI_MaintenanceMode[2]) OR HMI_MaintenanceMode[3]  THEN  // 手动、有安全门信号 释放权限
	ControlWord_mBit[20]:=TRUE;
	ControlWord_mBit[21]:=TRUE;	
	ControlWord_mBit[22]:=TRUE;	
	ControlWord_mBit[23]:=FALSE;	
END_IF  ;



 (************************************23、动子静态偏移****************************************)
//触发工位动子运动
FOR i:=0 TO 127 DO
	//动子静态偏移
	IF H_In.MoverOffsetExecute[i] AND Hmx_Manual
		AND StatusWord_mBit[1]								//导轨初始化完成
		AND StatusWord_mBit[12]							//总线正常
		AND NOT StatusWord_mBit[8]						//无报警
		AND NOT SetMoverOffsetBusy
	THEN
		SetMoverOffsetBusy:=TRUE;
		PLCOutputToGolytec.mover_pos_offset_7001_08:=REAL_TO_INT(Parameter.MoverOffset[i]*1000);//单位毫米转微米
		PLCOutputToGolytec.mover_id_to_op_7001_0A:=INT_TO_USINT(i);  //要更新pos offset的动子id
		PLCOutputToGolytec.mover_op_7001_09:=16#F4;	//低8位依次写入0xf4，0xf5触发更新并永	
	END_IF;
	SetMoverOffsetPos_Ton[0](IN:=SetMoverOffsetBusy, PT:=T#50MS);
END_FOR;
//延时到
	IF SetMoverOffsetPos_Ton[0].Q THEN
		H_Out.MoverOffsetDone[PLCOutputToGolytec.mover_id_to_op_7001_0A]:=TRUE;
		PLCOutputToGolytec.mover_op_7001_09:=16#F5;
		SetMoverOffsetPos_Ton[1](IN:=TRUE, PT:=T#50MS);
	END_IF;
	IF SetMoverOffsetPos_Ton[1].Q AND NOT H_In.MoverOffsetExecute[PLCOutputToGolytec.mover_id_to_op_7001_0A] THEN
		H_Out.MoverOffsetDone[PLCOutputToGolytec.mover_id_to_op_7001_0A]:=FALSE;
		PLCOutputToGolytec.mover_pos_offset_7001_08:=0;//单位毫米转微米
		PLCOutputToGolytec.mover_id_to_op_7001_0A:=USINT#0;  //要更新pos offset的动子id
		PLCOutputToGolytec.mover_op_7001_09:=16#0;
		SetMoverOffsetBusy:=FALSE;
		SetMoverOffsetPos_Ton[0](IN:=FALSE, PT:=T#50MS);
		SetMoverOffsetPos_Ton[1](IN:=FALSE, PT:=T#50MS);
	END_IF;

 (************************************24、动态指向****************************************)

 (************************************40、工位急停暂停恢复****************************************)
//工位急停操作
FOR i:=0 TO 127 DO 
	//触发工位急停，上升沿有效
	IF ((H_In.StationEMGStop[i] AND Hmx_Manual)   //AND Hmx_Manual
	OR (In.StationEMGStop[i] ))  //AND Auto
	AND NOT Out.StationEMGStop[i]  //模拟拟时屏蔽  实际时开启
	 THEN
	 	IF i<32 THEN
			ControlEMGLWord0_63_1_mBit[i]:=TRUE;
		ELSIF i>=32 AND i <64
		THEN
			ControlEMGLWord0_63_2_mBit[i-32]:=TRUE;	
		ELSIF i>=64 AND i <96
		THEN
			ControlEMGLWord64_127_1_mBit[i-64]:=TRUE;	
		ELSE
			ControlEMGLWord64_127_2_mBit[i-96]:=TRUE;
		END_IF;
	ELSE
	 	IF i<32 THEN
			ControlEMGLWord0_63_1_mBit[i]:=FALSE;
		ELSIF i>=32 AND i <64
		THEN
			ControlEMGLWord0_63_2_mBit[i-32]:=FALSE;	
		ELSIF i>=64 AND i <96
		THEN
			ControlEMGLWord64_127_1_mBit[i-64]:=FALSE;	
		ELSE
			ControlEMGLWord64_127_2_mBit[i-96]:=FALSE;
		END_IF;
		//In.StationEMGStop[i]:=FALSE;
	END_IF;

	// 急停暂停恢复（急停暂停共用）
	IF i<32 THEN
		IF ((H_In.StationEMGResume[i] OR In.StationEMGResume[i]) AND Out.StationEMGStop[i])
		OR ((H_In.StationPauseResume[i] OR  FALSE) AND StationStopLWord_mBit[i])
		THEN 
					ControlEMG_StopResumeLWord0_63_1_mBit[i]:=TRUE;
		ELSE
					ControlEMG_StopResumeLWord0_63_1_mBit[i]:=FALSE;
		END_IF;
	ELSIF i>=32 AND i <64
	THEN
		IF ((H_In.StationEMGResume[i] OR In.StationEMGResume[i]) AND Out.StationEMGStop[i])
		OR ((H_In.StationPauseResume[i] OR  FALSE) AND StationStopLWord_mBit[i])
		THEN 
					ControlEMG_StopResumeLWord0_63_2_mBit[i-32]:=TRUE;
		ELSE
					ControlEMG_StopResumeLWord0_63_2_mBit[i-32]:=FALSE;
		END_IF;
	
	ELSIF i>=64 AND i <96
	THEN
		IF ((H_In.StationEMGResume[i] OR In.StationEMGResume[i]) AND Out.StationEMGStop[i])
			OR ((H_In.StationPauseResume[i] OR  FALSE) AND StationStopLWord_mBit[i-64])
			THEN 
				ControlEMG_StopResumeLWord64_127_1_mBit[i-64]:=TRUE;
		ELSE
				 ControlEMG_StopResumeLWord64_127_1_mBit[i-64]:=FALSE;
		END_IF;	
	ELSE		
		IF ((H_In.StationEMGResume[i] OR In.StationEMGResume[i]) AND Out.StationEMGStop[i])
			OR ((H_In.StationPauseResume[i] OR  FALSE) AND StationStopLWord_mBit[i-64])
			THEN 
				ControlEMG_StopResumeLWord64_127_1_mBit[i-96]:=TRUE;
		ELSE
				 ControlEMG_StopResumeLWord64_127_1_mBit[i-96]:=FALSE;
		END_IF;
	END_IF;
		
		
		
		
		
		
		
	
	//触发工位暂停，上升沿有效
	
	IF i<32
	THEN
		IF (H_In.StationPause[i] OR FALSE) AND NOT StationStopLWord_mBit[i] THEN 
			ControlStopLWord0_63_1_mBit[i]:=TRUE;
		ELSE
			ControlStopLWord0_63_1_mBit[i]:=FALSE;
		END_IF
	ELSIF   i>=32 AND i <64
	THEN 
		IF (H_In.StationPause[i] OR FALSE) AND NOT StationStopLWord_mBit[i] THEN 
			ControlStopLWord0_63_1_mBit[i-32]:=TRUE;
		ELSE
			ControlStopLWord0_63_1_mBit[i-32]:=FALSE;
		END_IF
	ELSIF   i>=64 AND i <96
	THEN 
		IF (H_In.StationPause[i] OR FALSE) AND NOT StationStopLWord_mBit[i-64] THEN 
				ControlStopLWord64_127_1_mBit[i-64]:=TRUE;
		ELSE
				ControlStopLWord64_127_1_mBit[i-64]:=FALSE;
		END_IF;
	ELSE
		IF (H_In.StationPause[i] OR FALSE) AND NOT StationStopLWord_mBit[i-64] THEN 
				ControlStopLWord64_127_1_mBit[i-96]:=TRUE;
		ELSE
				ControlStopLWord64_127_1_mBit[i-96]:=FALSE;
		END_IF;	
    END_IF
	
	//自动恢复急停
	IF  In.StationEMGResume[i] AND NOT Out.StationEMGStop[i]
	THEN 
		 In.StationEMGResume[i]:=FALSE;
	END_IF;
	
END_FOR;

 //0~127工位急停
 
FC_AryBoolToAryWord(AryBool:=ControlEMGLWord0_63_1_mBit , AryWord:=ControlEMGLWord0_63_1.mWord );
FC_AryBoolToAryWord(AryBool:=ControlEMGLWord0_63_2_mBit , AryWord:=ControlEMGLWord0_63_2.mWord );
FC_AryBoolToAryWord(AryBool:=ControlEMGLWord64_127_1_mBit , AryWord:=ControlEMGLWord64_127_1.mWord );
FC_AryBoolToAryWord(AryBool:=ControlEMGLWord64_127_2_mBit , AryWord:=ControlEMGLWord64_127_2.mWord );
PLCOutputToGolytec.STN_QSTOP0_31_7003_03:=DWORD_TO_UDINT(ControlEMGLWord0_63_1.mDWord);
PLCOutputToGolytec.STN_QSTOP32_63_7003_04:=DWORD_TO_UDINT(ControlEMGLWord0_63_2.mDWord);
PLCOutputToGolytec.STN_QSTOP64_95_7003_1B  :=DWORD_TO_UDINT(ControlEMGLWord64_127_1.mDWord);
PLCOutputToGolytec.STN_QSTOP96_127_7003_1C:=DWORD_TO_UDINT(ControlEMGLWord64_127_2.mDWord);
 //0~127工位暂停
FC_AryBoolToAryWord(AryBool:=ControlStopLWord0_63_1_mBit , AryWord:=ControlStopLWord0_63_1.mWord );
FC_AryBoolToAryWord(AryBool:=ControlStopLWord0_63_2_mBit , AryWord:=ControlStopLWord0_63_2.mWord );
FC_AryBoolToAryWord(AryBool:=ControlStopLWord64_127_1_mBit , AryWord:=ControlStopLWord64_127_1.mWord );
FC_AryBoolToAryWord(AryBool:=ControlStopLWord64_127_2_mBit , AryWord:=ControlStopLWord64_127_2.mWord );
PLCOutputToGolytec.STN_PAUSE0_31_7003_17:=DWORD_TO_UDINT(ControlStopLWord0_63_1.mDWord);
PLCOutputToGolytec.STN_PAUSE32_63_7003_18:=DWORD_TO_UDINT(ControlStopLWord0_63_2.mDWord);
PLCOutputToGolytec.STN_PAUSE64_95_7003_19:=DWORD_TO_UDINT(ControlStopLWord64_127_1.mDWord);
PLCOutputToGolytec.STN_PAUSE96_127_7003_1A:=DWORD_TO_UDINT(ControlStopLWord64_127_2.mDWord);
 //0~31工位急停/暂停恢复
FC_AryBoolToAryWord(AryBool:=ControlEMG_StopResumeLWord0_63_1_mBit , AryWord:=ControlEMG_StopResumeLWord0_63_1.mWord );
FC_AryBoolToAryWord(AryBool:=ControlEMG_StopResumeLWord0_63_2_mBit , AryWord:=ControlEMG_StopResumeLWord0_63_2.mWord );
FC_AryBoolToAryWord(AryBool:=ControlEMG_StopResumeLWord64_127_1_mBit , AryWord:=ControlEMG_StopResumeLWord64_127_1.mWord );
FC_AryBoolToAryWord(AryBool:=ControlEMG_StopResumeLWord64_127_2_mBit , AryWord:=ControlEMG_StopResumeLWord64_127_2.mWord );
PLCOutputToGolytec.STN_QSTOP_RESUME0_31_7003_11:=DWORD_TO_UDINT(ControlEMG_StopResumeLWord0_63_1.mDWord);
PLCOutputToGolytec.STN_QSTOP_RESUME32_63_7003_12:=DWORD_TO_UDINT(ControlEMG_StopResumeLWord0_63_2.mDWord);
PLCOutputToGolytec.STN_QSTOP_RESUME64_95_7003_1D:=DWORD_TO_UDINT(ControlEMG_StopResumeLWord64_127_1.mDWord);
PLCOutputToGolytec.STN_QSTOP_RESUME96_127_7003_1E:=DWORD_TO_UDINT(ControlEMG_StopResumeLWord64_127_2.mDWord);

 (************************************41、工位移动****************************************)
//
TON_AutoReady(In:=StatusWord_mBit[2], PT:=T#100ms);
//触发工位动子运动
//
FOR i:=0 TO 127 DO
	IF ((In.StationMotion[i] AND Auto)
		OR (H_In.StationMotion[i] AND Hmx_Manual))
		AND In.StationMotionAllow[i]						//安全条件
		AND Out.StationMotionDone[i]					//工位有动子
		AND StatusWord_mBit[1]								//导轨初始化完成
		AND TON_AutoReady.Q								//导轨自动中
		AND StatusWord_mBit[12]							//总线正常
		AND NOT StatusWord_mBit[8]						//无报警
	THEN
		RecordLastStationMoverID[i]:=RecordCurStationMoverID[i];//记录上一次停留在工位上的电池
		IF i <32 THEN
			StationMoveLWord0_63_1_mBit[i]:=TRUE;
		ELSIF i>=32 AND i<64
		THEN 
			StationMoveLWord0_63_2_mBit[i-32]:=TRUE;
		ELSIF i>=64 AND i<96
		THEN 
			StationMoveLWord64_127_1_mBit[i-64]:=TRUE;
		ELSE
			StationMoveLWord64_127_2_mBit[i-96]:=TRUE;
		END_IF;
	END_IF;
	//只判断在启动时的干涉报警
	IF ((In.StationMotion[i] AND Auto)
		//OR (H_In.StationMotion[i] AND Hmx_Manual)
		)
		AND NOT In.StationMotionAllow[i]						//安全条件
	THEN
		ErrOut.MovingHinderErr:=TRUE;//干涉报警
		ErrOut.MovingHinderErrDetail[i]:=TRUE;
	END_IF;
	//工位触发信号复位
	IF (NOT Out.StationMotionDone[i] OR NOT StatusWord_mBit[1])
		THEN
		IF i <32 THEN
			StationMoveLWord0_63_1_mBit[i]:=FALSE;
		ELSIF i>=32 AND i<64
		THEN 
			StationMoveLWord0_63_2_mBit[i-32]:=FALSE;
		ELSIF i>=64 AND i<96
		THEN 
			StationMoveLWord64_127_1_mBit[i-64]:=FALSE;
		ELSE
			StationMoveLWord64_127_2_mBit[i-96]:=FALSE;
		END_IF;
		In.StationMotion[i]:=FALSE;
		H_In.StationMotion[i]:=FALSE;
	END_IF;
END_FOR;

FC_AryBoolToAryWord(AryBool:=StationMoveLWord0_63_1_mBit , AryWord:=StationMoveLWord0_63_1.mWord );
FC_AryBoolToAryWord(AryBool:=StationMoveLWord0_63_2_mBit , AryWord:=StationMoveLWord0_63_2.mWord );
FC_AryBoolToAryWord(AryBool:=StationMoveLWord64_127_1_mBit , AryWord:=StationMoveLWord64_127_1.mWord );
FC_AryBoolToAryWord(AryBool:=StationMoveLWord64_127_2_mBit , AryWord:=StationMoveLWord64_127_2.mWord );
PLCOutputToGolytec.STN_MV2NEXT0_31_7003_01:=DWORD_TO_UDINT(StationMoveLWord0_63_1.mDWord);
PLCOutputToGolytec.STN_MV2NEXT32_63_7003_02:=DWORD_TO_UDINT(StationMoveLWord0_63_2.mDWord);
PLCOutputToGolytec.STN_MV2NEXT64_95_7003_0B:=DWORD_TO_UDINT(StationMoveLWord64_127_1.mDWord);
PLCOutputToGolytec.STN_MV2NEXT96_127_7003_0C:=DWORD_TO_UDINT(StationMoveLWord64_127_2.mDWord);
 (************************************42、动子绑定****************************************)

CASE iStepMoverIDBinding OF
	0:
	//判断是否需要进行工位动子绑定ID
	TONMoverIDBinding(In:=FALSE, PT:=T#30MS);
	TONMoverIDBindingErr(In:=FALSE, PT:=T#2S);
	Out.BindingDone:=FALSE;
	IF ((Hmx_Manual AND H_In.MoverIDBangding AND Out.StationMotionDone[H_In.StationNo]	) //工位有动子
		OR (Auto AND In.MoverIDBangding AND Out.StationMotionDone[In.StationNo]	 )) //工位有动子			
		AND StatusWord_mBit[1]								//导轨初始化完成
		AND NOT StatusWord_mBit[8]						//无报警
		AND StatusWord_mBit[12]							//总线正常
		//AND StatusWord_mBit[2]                          //自动运行中
	THEN
		IF Hmx_Manual THEN
			StationNo:= UINT_TO_USINT( H_In.StationNo);	//工位号
			MoverID:= UINT_TO_USINT( H_In.MoverID);				//工位ID
	  ELSE
		  	StationNo:= UINT_TO_USINT( In.StationNo);	//工位号
			MoverID:= UINT_TO_USINT( In.MoverID);				//工位ID
	  END_IF;
		iStepMoverIDBinding:=10;
	END_IF;
	10:
	//工位动子绑定ID
		PLCOutputToGolytec.Rfid_by_stn_id_or_virtal_id_7000_15:= StationNo;	//工位号
		PLCOutputToGolytec.Mover_dyn_id_to_op_7000_16:= MoverID;				//工位ID
		TONMoverIDBinding(In:=TRUE, PT:=T#10MS);
		IF TONMoverIDBinding.Q THEN
			TONMoverIDBinding(In:=FALSE, PT:=T#10MS);
			ControlMoverDyn_mBit[0]:=TRUE;//触发绑定
			ControlMoverDyn_mBit[15]:=TRUE;//触发绑定
			iStepMoverIDBinding:=20;
		END_IF;
	20:
	//判断是否绑定成功
	TONMoverIDBindingErr(In:=TRUE, PT:=T#2S);
	IF Out.StationMoverID[StationNo] =MoverID THEN
		ControlMoverDyn_mBit[0]:=FALSE;//触发绑定
		ControlMoverDyn_mBit[15]:=FALSE;//触发绑定
		TONMoverIDBindingErr(In:=FALSE, PT:=T#2S);
		Out.BindingDone:=TRUE;
		iStepMoverIDBinding:=40;
	END_IF;
	//绑定失败
	IF TONMoverIDBindingErr.Q THEN
		TONMoverIDBindingErr(In:=FALSE, PT:=T#2S);
		ErrOut.BindingError:=TRUE;
		iStepMoverIDBinding:=100;
	END_IF;
	40:
	//等待复位结束绑定
	IF NOT 
		((Hmx_Manual AND H_In.MoverIDBangding ) //工位有动子
		OR (Auto AND In.MoverIDBangding )) //工位有动子		
	THEN
		iStepMoverIDBinding:=0;
		Out.BindingDone:=FALSE;
	END_IF;
	100:
	ControlMoverDyn_mBit[0]:=FALSE;//触发绑定
	ControlMoverDyn_mBit[15]:=FALSE;//触发绑定
	IF NOT ErrOut.BindingError THEN
		iStepMoverIDBinding:=0;
	END_IF;
END_CASE;

FC_AryBoolToWord(AryBool:=ControlMoverDyn_mBit , AryWord:=ControlMoverDyn );
PLCOutputToGolytec.mover_dyn_control_7001_04:=WORD_TO_UINT(ControlMoverDyn.mWord);



 (************************************43、当前工位位置显示，位置设置，速度设定****************************************)
//获取工位当前设置位置
IF StationNum<0 OR StationNum>Parameter.StationNoTotal (*StationNum>=GolytecInputToPLC.ActStationNum_6000_0D*) THEN
	StationNum:=0;
END_IF;

CASE iStepStation OF
	0:
		//设置工位编号
		PLCOutputToGolytec.station_id_to_op_7002_04:=StationNum;  //映射需要读取位置的工位编号
		ReadStationActPos_Ton(IN:=TRUE, PT:=T#10MS);
		IF ReadStationActPos_Ton.Q THEN
			ReadStationActPos_Ton(IN:=FALSE, PT:=T#10MS);
     		iStepStation:=10;
		END_IF;
	10:
		//读取工位当前位置
		H_Out.StationActPos[StationNum] := DINT_TO_REAL(GolytecInputToPLC.station_base_pos_6002_06)/1000; //单位微米转换为毫米
		//读取工位当前速度
		H_Out.StationActVel[StationNum] := DINT_TO_REAL(GolytecInputToPLC.station_vel_6002_09); //mm/s
		iStepStation:=20;
	20:
	//设置工位位置
	IF NOT StatusWord_mBit[2]	AND H_In.StationSetPosExecute[StationNum]
	THEN
		iStepStation:=50;
	ELSIF NOT StatusWord_mBit[2] AND  H_In.StationSetVelExecute[StationNum] 
	THEN
		iStepStation:=70;
	ELSE
		iStepStation:=100;
	END_IF;
	50:
	(*
	** 修改工位位置
	1、将动子停留的工位ID输入station_id_to_op （0047）
	2、将新的位置写入 station_base_pos（004C）
	3、将station_op（0046） 先写入0x104
	4、延时10ms 再将station_op（0046） 先写入0x05
	6、延时，复位station_op（0x46）  读取工位位置可比较
	*)
		PLCOutputToGolytec.station_base_pos_7002_07:=REAL_TO_DINT(Parameter.StationPosition[StationNum]*1000);//单位毫米转微米
		PLCOutputToGolytec.station_op_7002_03:=16#04;
		SetStationPos_Ton[0](IN:=TRUE, PT:=T#50MS);
		IF SetStationPos_Ton[0].Q AND NOT SetStationPos_Ton[1].Q THEN
			PLCOutputToGolytec.station_op_7002_03:=16#05;
			SetStationPos_Ton[1](IN:=TRUE, PT:=T#50MS);
		END_IF;
		IF SetStationPos_Ton[1].Q THEN
			iStepStation:=100;
		END_IF;
	70:
	(*
	1、将动子停留的工位ID输入station_id_to_op （0047）
	2、将新的运行速度写入 station_vel（0058）
	3、将station_op（0046） 先写入0x14
	4、延时10ms 再将station_op（0046） 先写入0x15
	*)
		PLCOutputToGolytec.station_vel_7002_0A:=REAL_TO_DINT(Parameter.StationVel[StationNum]*1000);//单位毫米转微米
		PLCOutputToGolytec.station_op_7002_03:=16#14;
		SetStationVel_Ton[0](IN:=TRUE, PT:=T#50MS);
		IF SetStationVel_Ton[0].Q AND NOT SetStationVel_Ton[1].Q THEN
			PLCOutputToGolytec.station_op_7002_03:=16#15;
			SetStationVel_Ton[1](IN:=TRUE, PT:=T#50MS);
		END_IF;
		IF SetStationVel_Ton[1].Q THEN
			iStepStation:=100;
		END_IF;
	100:
		Inc(StationNum);
		ReadStationActPos_Ton(IN:=FALSE);
		SetStationPos_Ton[0](IN:=FALSE);
		SetStationPos_Ton[1](IN:=FALSE);
		SetStationVel_Ton[0](IN:=FALSE);
		SetStationVel_Ton[1](IN:=FALSE);
		iStepStation:=0;
		PLCOutputToGolytec.station_base_pos_7002_07:=0;
		PLCOutputToGolytec.station_vel_7002_0A:=0;
		PLCOutputToGolytec.station_op_7002_03:=16#00;
END_CASE;

 (************************************44、全局速度显示和设定****************************************)

//获取当前运行速度
H_Out.ActVelo:=GolytecInputToPLC.global_vel_6000_0F;
//使能设置速度功能
IF NOT StatusWord_mBit[2]	AND H_In.SetVeloSevo THEN
	PLCOutputToGolytec.global_vel_wr_en_7000_10:=16#3B5A;
ELSE
	PLCOutputToGolytec.global_vel_wr_en_7000_10:=16#0;
END_IF;
//设置全局运行速度
IF GeneralOverride <= 0 OR GeneralOverride >100 THEN
	Overrid:=100;
ELSE
	Overrid:=GeneralOverride;
END_IF;

//R_InitDone(Clk:=InitDone);
AutoVeloSevo:=DINT_TO_UINT ((LREAL_TO_INT(UINT_TO_REAL(Parameter.GlobalVelocity) * GeneralOverride/REAL#100.0) /INT#10 * INT#10));
SetGlobalVelo_Ton(PT:=T#20MS);
//自动速度设定
IF NOT StatusWord_mBit[2]	AND (H_In.SetVeloSevo OR R_InitDone.Q)
	AND H_Out.ActVelo <> AutoVeloSevo 
THEN
	PLCOutputToGolytec.global_vel_7000_11:=Parameter.GlobalVelocity;
	SetGlobalVelo_Ton.In:=TRUE;
END_IF;

IF SetGlobalVelo_Ton.Q THEN
		PLCOutputToGolytec.global_vel_7000_11:=Parameter.GlobalVelocity+1;
		SetGlobalVelo_Ton.In:=FALSE;
	END_IF;


 (************************************45、操作某个动子做相对运动****************************************)
FOR i:=0 TO 97 DO
	IF ((Hmx_Manual AND H_In.MoverRelExecute[i])
		OR (Auto AND In.MoverRelExecute[i]))
		AND Out.StationMotionDone[i]					//工位有动子  这个信号可能要屏蔽掉
		AND StatusWord_mBit[1]								//导轨初始化完成
		AND NOT StatusWord_mBit[8]						//无报警
		AND StatusWord_mBit[12]							//总线正常
	THEN
		//输入目标位置
		IF Hmx_Manual THEN
			PLCOutputToGolytec.Mover_target_pos[i]:=REAL_TO_DINT(H_In.MoverRelPosition[i]); //动子设置的目标位置，单位um
		ELSE
			PLCOutputToGolytec.Mover_target_pos[i]:=REAL_TO_DINT(In.MoverRelPosition[i]);//动子设置的目标位置，单位um
		END_IF;
		Mover_control_mBit[0]:=TRUE;  //动子控制使能，必须为1下发的命令才会生效
		Mover_control_mBit[4]:=TRUE;  //启动相对运动，上升沿有效
	END_IF;
	IF NOT
		((Hmx_Manual AND H_In.MoverRelExecute[i]) OR (Auto AND In.MoverRelExecute[i]))
	THEN
		Mover_control_mBit[0]:=FALSE;  //动子控制使能，必须为1下发的命令才会生效
		Mover_control_mBit[4]:=FALSE;  //启动相对运动，上升沿有效
	END_IF;
	FC_AryBoolToWord(AryBool:= Mover_control_mBit, AryWord:=  PLCOutputToGolytec.Mover_control[i] );

END_FOR;



 (************************************45、升降机信息显示及操作****************************************)
//bit0~bit15：lift0~15移动前准备状态已经 就绪
 LiftReady.mWord := UINT_TO_WORD(GolytecInputToPLC.Lift0_15_movement_ready_6002_13);
//0: 有动子进入了与接驳模组运动干涉的区域 1：lift0~15升降机可以安全运动
LiftSafety.mWord := UINT_TO_WORD(GolytecInputToPLC.Lift0_15_movement_safety_6002_14);

FC_WordToAryBool(LiftReady.mWord,0,LiftReady_mBit,0,16);
FC_WordToAryBool(LiftSafety.mWord,0,LiftSafety_mBit,0,16);

//升降机位置，例如两层接驳模组， 1/2/3分别是升降机位于顶层/中间区域/底层---- 0号升降机位置
IF In.Lift0PosDone[0] AND NOT In.Lift0PosDone[1] AND NOT In.Lift0Error THEN
	ControlLiftPos1_mBit[0]:=TRUE;
	ControlLiftPos1_mBit[1]:=FALSE;
ELSIF In.Lift0PosDone[1] AND NOT In.Lift0PosDone[0] AND NOT In.Lift0Error THEN
	ControlLiftPos1_mBit[1]:=TRUE;
	ControlLiftPos1_mBit[0]:=TRUE;
ELSE
	ControlLiftPos1_mBit[1]:=TRUE;
	ControlLiftPos1_mBit[0]:=FALSE;
END_IF;
//lift 状态， 0:NOT Moving,1:Moving 0-15升降机运动状态---升降机0
ControlLiftnError_mBit[0]:=NOT In.Lift0Error;
Out.Lift0Ready:=LiftReady_mBit[0];  //升降准备好
Out.Lift0Safety:=LiftSafety_mBit[0];  //升降准备好


//升降机位置，例如两层接驳模组， 1/2/3分别是升降机位于顶层/中间区域/底层---- 1号升降机位置
IF In.Lift1PosDone[0] AND NOT In.Lift1PosDone[1] AND NOT In.Lift1Error THEN
	ControlLiftPos1_mBit[4]:=TRUE;
	ControlLiftPos1_mBit[5]:=FALSE;
ELSIF In.Lift1PosDone[1] AND NOT In.Lift1PosDone[0] AND NOT In.Lift1Error THEN
	ControlLiftPos1_mBit[5]:=TRUE;
	ControlLiftPos1_mBit[4]:=TRUE;
ELSE
	ControlLiftPos1_mBit[5]:=TRUE;
	ControlLiftPos1_mBit[4]:=FALSE;
END_IF;
//Lift 状态， 0:NOT Moving,1:Moving 0-15升降机运动状态---升降机1
ControlLiftnError_mBit[1]:=NOT In.Lift1Error;
Out.Lift1Ready:=LiftReady_mBit[1];  //升降准备好
Out.Lift1Safety:=LiftSafety_mBit[1];  //升降准备好

//升降机位置，例如两层接驳模组， 1/2/3分别是升降机位于顶层/中间区域/底层---- 2号升降机位置
IF In.Lift2PosDone[0] AND NOT In.Lift2PosDone[1] AND NOT In.Lift2Error THEN
	ControlLiftPos1_mBit[8]:=TRUE;
	ControlLiftPos1_mBit[9]:=FALSE;
ELSIF In.Lift2PosDone[1] AND NOT In.Lift2PosDone[0] AND NOT In.Lift2Error THEN
	ControlLiftPos1_mBit[9]:=TRUE;
	ControlLiftPos1_mBit[8]:=TRUE;
ELSE
	ControlLiftPos1_mBit[9]:=TRUE;
	ControlLiftPos1_mBit[8]:=FALSE;
END_IF;
//Lift 状态， 0:NOT Moving,1:Moving 0-15升降机运动状态---升降机2号
ControlLiftnError_mBit[2]:=NOT In.Lift2Error;
Out.Lift2Ready:=LiftReady_mBit[2];  //升降准备好
Out.Lift2Safety:=LiftSafety_mBit[2];  //升降准备好

//升降机位置，例如两层接驳模组， 1/2/3分别是升降机位于顶层/中间区域/底层---- 3号升降机位置
IF In.Lift2PosDone[0] AND NOT In.Lift2PosDone[1] AND NOT In.Lift2Error THEN
	ControlLiftPos1_mBit[12]:=TRUE;
	ControlLiftPos1_mBit[13]:=FALSE;
ELSIF In.Lift2PosDone[1] AND NOT In.Lift2PosDone[0] AND NOT In.Lift2Error THEN
	ControlLiftPos1_mBit[13]:=TRUE;
	ControlLiftPos1_mBit[12]:=TRUE;
ELSE
	ControlLiftPos1_mBit[13]:=TRUE;
	ControlLiftPos1_mBit[12]:=FALSE;
END_IF;
//Lift 状态， 0:NOT Moving,1:Moving 0-15升降机运动状态---升降机3号
ControlLiftnError_mBit[2]:=NOT In.Lift2Error;
Out.Lift2Ready:=LiftReady_mBit[2];  //升降准备好
Out.Lift2Safety:=LiftSafety_mBit[2];  //升降准备好

//升降机位置，例如两层接驳模组， 1/2/3分别是升降机位于顶层/中间区域/底层---- 4号升降机位置
IF In.Lift4PosDone[0] AND NOT In.Lift4PosDone[1] AND NOT In.Lift4Error THEN
	ControlLiftPos1_mBit[16]:=TRUE;
	ControlLiftPos1_mBit[17]:=FALSE;
ELSIF In.Lift4PosDone[1] AND NOT In.Lift4PosDone[0] AND NOT In.Lift4Error THEN
	ControlLiftPos1_mBit[17]:=TRUE;
	ControlLiftPos1_mBit[16]:=TRUE;
ELSE
	ControlLiftPos1_mBit[17]:=TRUE;
	ControlLiftPos1_mBit[16]:=FALSE;
END_IF;
//Lift状态， 0:NOT Moving,1:Moving 0-15升降机运动状态---升降机4号
ControlLiftnError_mBit[4]:=NOT In.Lift4Error;
Out.Lift4Ready:=LiftReady_mBit[4];  //升降准备好
Out.Lift4Safety:=LiftSafety_mBit[4];  //升降准备好

//升降机位置，例如两层接驳模组， 1/2/3分别是升降机位于顶层/中间区域/底层---- 5号升降机位置
IF In.Lift5PosDone[0] AND NOT In.Lift5PosDone[1] AND NOT In.Lift5Error THEN
	ControlLiftPos1_mBit[20]:=TRUE;
	ControlLiftPos1_mBit[21]:=FALSE;
ELSIF In.Lift5PosDone[1] AND NOT In.Lift5PosDone[0] AND NOT In.Lift5Error THEN
	ControlLiftPos1_mBit[21]:=TRUE;
	ControlLiftPos1_mBit[20]:=TRUE;
ELSE
	ControlLiftPos1_mBit[21]:=TRUE;
	ControlLiftPos1_mBit[20]:=FALSE;
END_IF;
//Lift状态， 0:NOT Moving,1:Moving 0-15升降机运动状态---升降机5号
ControlLiftnError_mBit[4]:=NOT In.Lift5Error;
Out.Lift5Ready:=LiftReady_mBit[4];  //升降准备好
Out.Lift5Safety:=LiftSafety_mBit[4];  //升降准备好


FC_AryBoolToAryWord(AryBool:=ControlLiftPos1_mBit , AryWord:=ControlLiftPos1.mWord );
FC_AryBoolToWord(AryBool:=ControlLiftnError_mBit , AryWord:=ControlLiftnError);
PLCOutputToGolytec.lift0_1_Pos_7000_05:=BYTE_TO_SINT(ControlLiftPos1.mByte[0]);
PLCOutputToGolytec.lift2_3_Pos_7000_06:=BYTE_TO_SINT(ControlLiftPos1.mByte[1]);
PLCOutputToGolytec.lift4_5_Pos_7000_07:=BYTE_TO_SINT(ControlLiftPos1.mByte[2]);
PLCOutputToGolytec.lift0_15_nERR_7000_0E:=WORD_TO_UINT(ControlLiftnError.mWord);



 (************************************46、有动子在安全区域内****************************************)
//工位0-127有动子在安全区域内
StationOCCUPIEDLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_OCCUPIED0_31_6002_19);
StationOCCUPIEDLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_OCCUPIED32_63_6002_1A);

FC_WordToAryBool(StationOCCUPIEDLWord1.mWord[0],0,StationOCCUPIEDLWord_mBit,0,16);
FC_WordToAryBool(StationOCCUPIEDLWord1.mWord[1],0,StationOCCUPIEDLWord_mBit,16,16);
FC_WordToAryBool(StationOCCUPIEDLWord2.mWord[0],0,StationOCCUPIEDLWord_mBit,32,16);
FC_WordToAryBool(StationOCCUPIEDLWord2.mWord[1],0,StationOCCUPIEDLWord_mBit,48,16);
AryMove(In:=StationOCCUPIEDLWord_mBit[0], AryOut:=Out.StationMoverInSafety[0], Size:=UINT#64);

StationOCCUPIEDLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_OCCUPIED64_95_6003_03);
StationOCCUPIEDLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.STN_OCCUPIED96_127_6003_04);
FC_WordToAryBool(StationOCCUPIEDLWord1.mWord[0],0,StationOCCUPIEDLWord_mBit,0,16);
FC_WordToAryBool(StationOCCUPIEDLWord1.mWord[1],0,StationOCCUPIEDLWord_mBit,16,16);
FC_WordToAryBool(StationOCCUPIEDLWord2.mWord[0],0,StationOCCUPIEDLWord_mBit,32,16);
FC_WordToAryBool(StationOCCUPIEDLWord2.mWord[1],0,StationOCCUPIEDLWord_mBit,48,16);

 (************************************47、模块的头部接缝处是否有动子存在****************************************)
//模块的头部接缝处是否有动子存在
ModelBeginOccLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.MD_BEGIN_OCC0_31_6002_1D);
ModelBeginOccLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.MD_BEGIN_OCC32_63_6003_07);
FC_WordToAryBool(ModelBeginOccLWord1.mWord[0],0,ModelBeginOccLWord_mBit,0,16);
FC_WordToAryBool(ModelBeginOccLWord1.mWord[1],0,ModelBeginOccLWord_mBit,16,16);
FC_WordToAryBool(ModelBeginOccLWord2.mWord[0],0,ModelBeginOccLWord_mBit,32,16);
FC_WordToAryBool(ModelBeginOccLWord2.mWord[1],0,ModelBeginOccLWord_mBit,48,16);
AryMove(In:=ModelBeginOccLWord_mBit[0], AryOut:=Out.ModelBeginOcc[0], Size:=UINT#64);

 (************************************48、模块的尾部接缝处是否有动子存在****************************************)
//模块的尾部接缝处是否有动子存在
ModelEndOccLWord1.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.MD_END_OCC0_31_6002_1E);
ModelEndOccLWord2.mDWord:=UDINT_TO_DWORD(GolytecInputToPLC.MD_END_OCC32_63_6003_08);
FC_WordToAryBool(ModelEndOccLWord1.mWord[0],0,ModelEndOccLWord_mBit,0,16);
FC_WordToAryBool(ModelEndOccLWord1.mWord[1],0,ModelEndOccLWord_mBit,16,16);
FC_WordToAryBool(ModelEndOccLWord2.mWord[0],0,ModelEndOccLWord_mBit,32,16);
FC_WordToAryBool(ModelEndOccLWord2.mWord[1],0,ModelEndOccLWord_mBit,48,16);
AryMove(In:=ModelEndOccLWord_mBit[0], AryOut:=Out.ModelEndOcc[0], Size:=UINT#64);
 (************************************50、动态指向***************************************
1、station_dyn_redir_en  0045 ---3B
2、station_allow_entering  0048---用2个BYTE  低起始工位  高BYTE 目标工位
3、station_allow_entering  0048  bit7 写1 上升沿生效一次
4、当动子离开当前工位后(reach 为FALSE)  复位station_allow_entering  0048  bit7 写0
48/49 可以用作一组
4A/4B也可以用作一组
 *)
FOR i:=0 TO 3 DO
	IF Auto AND In.StnDynRedirExe[i]		//动态指向请求
		AND Out.Inited								//导轨初始化完成
		AND NOT ErrOut.Alarm					//无报警
		AND H_Out.EcatStatus							//总线正常
	THEN
		//使能工位动态指向命令功能
		PLCOutputToGolytec.station_dyn_redir_en_7002_02:=16#3B;	//station_dyn_redir_en  0045 ---3B
		//第一组动态指向
		IF i =0 THEN
			IF Out.StationMotionDone[In.StnDynRedirID[0]] THEN	//工位有到位信号
				//原工位----0048
				StationDynRedirIDLWord1.mByte[0]:=UINT_TO_BYTE(In.StnDynRedirID[0]);
				//目标工位--0049
				StationDynRedirIDLWord1.mByte[1]:=UINT_TO_BYTE(In.StnDynRedirNextID[0]);
				//bit7 写1 上升沿生效一次
				StationDynRedirIDLWord1_mBit[7]:=TRUE;
				Out.StnDynRedirBusy[0]:=TRUE;
			ELSE
				//原工位----0048
				StationDynRedirIDLWord1.mByte[0]:=0;
				//目标工位--0049
				StationDynRedirIDLWord1.mByte[1]:=0;
				Out.StnDynRedirBusy[0]:=FALSE;
				In.StnDynRedirExe[0]:=FALSE;
				StationDynRedirIDLWord1_mBit[7]:=FALSE;
			END_IF;
		END_IF;
		//第二组动态指向
		IF i =1 THEN
			IF Out.StationMotionDone[In.StnDynRedirID[1]] THEN
				//原工位----004A
				StationDynRedirIDLWord1.mByte[2]:=UINT_TO_BYTE(In.StnDynRedirID[1]);
				//目标工位--004B
				StationDynRedirIDLWord1.mByte[3]:=UINT_TO_BYTE(In.StnDynRedirNextID[1]);
				//bit7 写1 上升沿生效一次
				StationDynRedirIDLWord1_mBit[23]:=TRUE;
				Out.StnDynRedirBusy[1]:=TRUE;
			ELSE
				//原工位----004A
				StationDynRedirIDLWord1.mByte[2]:=0;
				//目标工位--004B
				StationDynRedirIDLWord1.mByte[3]:=0;
				Out.StnDynRedirBusy[1]:=FALSE;
				In.StnDynRedirExe[1]:=FALSE;
				StationDynRedirIDLWord1_mBit[23]:=FALSE;
			END_IF;
		END_IF;
		//第三组动态指向
		IF i =2 THEN
			IF Out.StationMotionDone[In.StnDynRedirID[2]] THEN
				//原工位----004C
				StationDynRedirIDLWord2.mByte[0]:=UINT_TO_BYTE(In.StnDynRedirID[2]);
				//目标工位--004D
				StationDynRedirIDLWord2.mByte[1]:=UINT_TO_BYTE(In.StnDynRedirNextID[2]);
				//bit7 写1 上升沿生效一次
				StationDynRedirIDLWord2_mBit[7]:=TRUE;
				Out.StnDynRedirBusy[2]:=TRUE;
			ELSE
				//原工位----004C
				StationDynRedirIDLWord2.mByte[0]:=0;
				//目标工位--004D
				StationDynRedirIDLWord2.mByte[1]:=0;
				Out.StnDynRedirBusy[2]:=FALSE;
				In.StnDynRedirExe[2]:=FALSE;
				StationDynRedirIDLWord2_mBit[7]:=FALSE;
			END_IF;
		END_IF;
		//第四组动态指向
		IF i =3 THEN
			IF Out.StationMotionDone[In.StnDynRedirID[3]] THEN
				//原工位----004E
				StationDynRedirIDLWord2.mByte[2]:=UINT_TO_BYTE(In.StnDynRedirID[3]);
				//目标工位--004F
				StationDynRedirIDLWord2.mByte[3]:=UINT_TO_BYTE(In.StnDynRedirNextID[3]);
				//bit7 写1 上升沿生效一次
				StationDynRedirIDLWord2_mBit[23]:=TRUE;
				Out.StnDynRedirBusy[3]:=TRUE;
			ELSE
				//原工位----004E
				StationDynRedirIDLWord2.mByte[2]:=0;
				//目标工位--004F
				StationDynRedirIDLWord2.mByte[3]:=0;
				Out.StnDynRedirBusy[3]:=FALSE;
				In.StnDynRedirExe[3]:=FALSE;
				StationDynRedirIDLWord2_mBit[23]:=FALSE;
			END_IF;
		END_IF;
		
		//0048 0049
		FC_AryBoolToAryWord(AryBool:=StationDynRedirIDLWord1_mBit , AryWord:=StationDynRedirIDLWord1.mWord );
		FC_AryBoolToAryWord(AryBool:=StationDynRedirIDLWord2_mBit , AryWord:=StationDynRedirIDLWord2.mWord );
		PLCOutputToGolytec.station_allow_entering_7002_05:=WORD_TO_UINT(StationDynRedirIDLWord1.mWord[0]);
		//004A 004B
		PLCOutputToGolytec.station_independent_7002_06:=WORD_TO_UINT(StationDynRedirIDLWord1.mWord[1]);
		//004C 004D 004E 004F
		PLCOutputToGolytec.station_base_pos_7002_07:=DWORD_TO_DINT(StationDynRedirIDLWord2.mDWord);
	END_IF;
	
END_FOR;
//未初始化
IF NOT Out.Inited THEN
	PLCOutputToGolytec.station_dyn_redir_en_7002_02:=0;
	StationDynRedirIDLWord1.mDWord:=0;
	StationDynRedirIDLWord2.mDWord:=0;
	Clear(Out.StnDynRedirBusy);
END_IF;



 (************************************55、显示映射***************************************)
H_Out.StationMotionAllow:=In.StationMotionAllow;
;

(*====== 程序简介 ========================================================================================================
 @ 名称				:	DL_EIP	
 @ 描述				:	DL_EP1通讯模块转换
 @ 作者				:	DXD	
 @ 日期				:	2020.12.26
 @ 版本号			:	V1.01.00.201226
 @ 配套				:
 @ 限制等级			:	A1.有问题允许改动	
 =========================================================================================================================
 @ 说明				:	用于DL_EP1通讯模块带GT，IL, IX型号基恩士测距传感器的数据转换
 @ 
 ===== 修改履历 ===========================================================================================================
 修改日期	| 版本			| 作者			| 备注 
 -------------------------------------------------------------------------------------------------------------------------
 2020.12.26	| V1.01.00		| DXD	        | 初版发布
 2022.09.10	| V2.01.00		| KZYK 	        | 发布

 ======= END ==============================================================================================================*)
(*
1.该功能做DL-EP1通讯模块，EIP通讯标签BTYE转换出实际的测量数值
2.同时附带DL-EP1通讯模块本体报警和传感器放大器报警监控
*)

//辨率选择，0为0.01mm，1为0.001mm
IF DPISelect =0 THEN
	BaseData:=1000;
ELSIF DPISelect =1 THEN
	BaseData:=100;
ELSIF DPISelect =2 THEN
	BaseData:=10;
END_IF;

//输入标签BTYE转换
FOR K:=0 TO 37 DO
	MyByte[K].mByte:=EIP_IN[K];
END_FOR;
//传感器输入值异常
MyValueError.mByte[0]:=EIP_IN[24];
MyValueError.mByte[1]:=EIP_IN[25];
//传感器数值转换
FOR K:=1 TO 15 DO
	MyDword[K].mByte[0]:=EIP_IN[48+4*(K-1)];
	MyDword[K].mByte[1]:=EIP_IN[49+4*(K-1)];
	MyDword[K].mByte[2]:=EIP_IN[50+4*(K-1)];
	MyDword[K].mByte[3]:=EIP_IN[51+4*(K-1)];
	IF ModelSelect=0 THEN
		IF MyDword[K].mBit[31]
		THEN	    
			Dword_D:=NOT(MyDword[K].mDWord);
			Value[K]:=0-DWORD_TO_REAL(Dword_D);	
		ELSE
			Value[K]:=DWORD_TO_REAL(MyDword[K].mDWord);
		END_IF;	
		//传感器错误输出
		IF MyValueError.mBit[K-1] THEN
			Value[K]:=-32767;
		END_IF;
	ELSIF ModelSelect=1 THEN
		Value[K]:=DINT_TO_REAL( DWORD_TO_DINT(MyDword[K].mDword))/BaseData;
	END_IF;
END_FOR;
//清零操作
IF ModelSelect=0 THEN
	FOR K:=0 TO 15 DO
		IF ClearMark[K] THEN
			MyDword[16].mBit[K]:=TRUE;
		ELSE
			MyDword[16].mBit[K]:=FALSE;
		END_IF;
	END_FOR;	
	EIP_OUT[0]:=MyDword[16].mByte[0];
ELSIF ModelSelect=1 THEN
	MyDword[16].mByte[0].0:=ClearMark_Master;
	MyDword[16].mByte[0].3:=ClearMark_Slave;
	EIP_OUT[2]:=MyDword[16].mByte[0];
END_IF

//实际数值输出
SensorValue1:=Value[1]/BaseData;//1#传感器数值
SensorValue2:=Value[2]/BaseData;//2#传感器数值
SensorValue3:=Value[3]/BaseData;//3#传感器数值
SensorValue4:=Value[4]/BaseData;//4#传感器数值
SensorValue5:=Value[5]/BaseData;//5#传感器数值
SensorValue6:=Value[6]/BaseData;//6#传感器数值
SensorValue7:=Value[7]/BaseData;//7#传感器数值
SensorValue8:=Value[8]/BaseData;//8#传感器数值
SensorValue9:=Value[9]/BaseData;//9#传感器数值
SensorValue10:=Value[10]/BaseData;//10#传感器数值
SensorValue11:=Value[11]/BaseData;//11#传感器数值
SensorValue12:=Value[12]/BaseData;//12#传感器数值
SensorValue13:=Value[13]/BaseData;//13#传感器数值
SensorValue14:=Value[14]/BaseData;//14#传感器数值
SensorValue15:=Value[15]/BaseData;//15#传感器数值
//报警输出
Error[0]:=MyByte[0].mArray[0];//DL-EP1本体报错！
Error[1]:=MyByte[2].mArray[0];//1#传感器放大器报错！
