usiEM02Index:=USINT#4;//工位号
bEM02_Start:=EM02V.Process_steps[2]=120;//计时开始									
bEM02_Stop:=EM02V.Process_steps[2]=120;//计时结束
bEM02_Run:=Act.Act05_Auto_Station[2,1];//工位自动	

abEM02ActionStart[3] :=EM02V.Process_steps[2]=120; //3.升降Z轴下降到取顶盖位						
abEM02ActionDone[3]	 :=EM02V.Process_steps[2]=130; 
ausiEM02ActionParallelNum[3]:=0;
abEM02ActionStart[4] :=EM02V.Process_steps[2]=130; //4.翻转夹爪气缸1夹紧					
abEM02ActionDone[4]	 :=EM02V.Process_steps[2]=150; 
ausiEM02ActionParallelNum[4]:=0;
abEM02ActionStart[5] :=EM02V.Process_steps[2]=150; //5.升降Z轴上升到放顶盖位					
abEM02ActionDone[5]	 :=EM02V.Process_steps[2]=220; 
ausiEM02ActionParallelNum[5]:=0;
abEM02ActionStart[6] :=EM02V.Process_steps[2]=220; //6.翻转R轴到放顶盖位		
abEM02ActionDone[6]	 :=EM02V.Process_steps[2]=230; 	
ausiEM02ActionParallelNum[6]:=0;
abEM02ActionStart[7] :=EM02V.Process_steps[2]=230; //7.顶盖下料夹爪气缸夹紧						
abEM02ActionDone[7]	 :=EM02V.Process_steps[2]=240; 
ausiEM02ActionParallelNum[7]:=0;
abEM02ActionStart[8] :=EM02V.Process_steps[2]=240; //8.翻转夹爪气缸1打开					
abEM02ActionDone[8]	 :=EM02V.Process_steps[2]=0; 
ausiEM02ActionParallelNum[8]:=0;
