ausiEM02ActionParallelNum[11]:=0;
abEM02ActionStart[12] :=EM02V.Process_steps[2]=340; //12.翻转夹爪气缸1夹紧				
abEM02ActionDone[12]:=EM02V.Process_steps[2]=350; 
ausiEM02ActionParallelNum[12]:=0;
abEM02ActionStart[13] :=EM02V.Process_steps[2]=350; //13.升降Z轴上升到放顶盖位		
abEM02ActionDone[13] :=EM02V.Process_steps[2]=410; 	
ausiEM02ActionParallelNum[13]:=0;
abEM02ActionStart[14] :=EM02V.Process_steps[2]=420; //14.翻转R轴到放顶盖位		
abEM02ActionDone[14] :=EM02V.Process_steps[2]=430; 	
