auiEMTime[usiEM02Index,63]	:=auiEMTime[usiEM02Index,63]	; //第63个动作时间

 IF HMI_Function_Enable[2,48] AND  MyStatus.StatusManual THEN
 	Clear(In:= SR_ScanCode1.SaveCode );
	Clear(In:= SR_ScanCode2.SaveCode );
 END_IF  ;
 
 
 
(******************************************** 批次码扫码流程 *********************************************)
TON_Scan1(In:=SR_ScanCode1.ScanStep>0, PT:=T#15S);
CASE SR_ScanCode1.ScanStep	OF
	0://流程开始
		IF Act.Act05_Auto_Station[2,0]
			AND EM02V.Axis_InPlace_Flag
			AND Cell_Info[2,1].Quality=60
			AND (EM01V.Robot1_SafetySignal_ToEM02
			AND NOT EM01V.Robot1ToEM02
 			OR MyStation.EM[1].Shielding)
		THEN
			EM02V.ScanCode1.In.Execute:=FALSE;
			SR_ScanCode1.ScanStep:=10;
		END_IF;
	10://扫码触发
		EM02V.ScanCode1.In.Execute:=TRUE;
		SR_ScanCode1.ScanStep:=20;
	20://判断扫码结果
		IF EM02V.ScanCode1.Out.ReadSuccess//扫码OK
			OR HMI_Function_Enable[2,0]
			OR HMI_TestMode_Enable
		THEN
			Cell_Info[2,1].OriginalCodeSN:=EM02V.ScanCode1.Out.BarCodeString;
			SR_ScanCode1.ScanCodeNGNum:=0;//连续NG清零
			SR_ScanCode1.ScanStep:=30;
		ELSIF EM02V.ScanCode1.Out.ReadFailure//扫码NG
		THEN
			Cell_Info[2,1].OriginalCodeSN:=EM02V.ScanCode1.Out.BarCodeString;
			Cell_Info[2,1].Quality:=30;
			SR_ScanCode1.ScanCodeNGNum:=SR_ScanCode1.ScanCodeNGNum+1;//连续NG+1
			SR_ScanCode1.ScanStep:=40;
		ELSIF TON_Scan1.Q
		THEN
			SR_ScanCode1.ErrOut.Err_OverTime:=TRUE;//超时错误
			SR_ScanCode1.ScanStep:=40;
		END_IF;
	30://规则校验+重码检测
		IF NOT HMI_Function_Enable[2,0] AND NOT HMI_TestMode_Enable THEN
			//=========================================
			//批次码规则校验
			SR_ScanCode1.CodeSNCheck1:=HMI_RecipeData.OriginalCodeSNCheck;
			SR_ScanCode1.CodeSNCheck2:=LEFT(Cell_Info[2,1].OriginalCodeSN, SIZE:=LEN(HMI_RecipeData.OriginalCodeSNCheck));
			IF NOT HMI_Function_Enable[2,4]
				AND SR_ScanCode1.CodeSNCheck1<>SR_ScanCode1.CodeSNCheck2
			THEN
				Cell_Info[2,1].Quality:=30;
				SR_ScanCode1.ErrOut.Err_Check:=TRUE;//规则校验错误
			END_IF;
			//=========================================
			//批次码重码检测
			IF NOT HMI_Function_Enable[2,6]
			THEN
				FOR i:=0 TO 19  DO
					IF Cell_Info[2,1].OriginalCodeSN=SR_ScanCode1.SaveCode[i] THEN
						Cell_Info[2,1].Quality:=30;
						SR_ScanCode1.ErrOut.Err_Repeat:=TRUE;//重码错误
					END_IF;
				END_FOR;
				SR_ScanCode1.SaveCode[SR_ScanCode1.SaveCodeNum]:=Cell_Info[2,1].OriginalCodeSN;//存码
				SR_ScanCode1.SaveCodeNum:=SR_ScanCode1.SaveCodeNum+1;//入栈序号+1
				IF SR_ScanCode1.SaveCodeNum>19 THEN SR_ScanCode1.SaveCodeNum:=0; END_IF;
			END_IF;
		END_IF;
		//=========================================
		//改变物料记忆
		IF Cell_Info[2,1].Quality=60 THEN
			Cell_Info[2,1].Quality:=65;
		END_IF;
		//=========================================
		//跳步
		SR_ScanCode1.ScanStep:=40;
	40://流程结束
		EM02V.ScanCode1.In.Execute:=FALSE;
		SR_ScanCode1.ScanStep:=0;
		
END_CASE;

(******************************************** 刻码条码扫码流程 *********************************************)
TON_Scan2(In:=SR_ScanCode2.ScanStep>0, PT:=T#15S);
CASE SR_ScanCode2.ScanStep	OF
	0://流程开始
		IF Act.Act05_Auto_Station[2,0]
			AND EM02V.Axis_InPlace_Flag
			AND Cell_Info[2,4].Quality=80
		THEN
			EM02V.ScanCode2.In.Execute:=FALSE;
			SR_ScanCode2.ScanStep:=10;
		END_IF;
	10://扫码触发
		EM02V.ScanCode2.In.Execute:=TRUE;
		SR_ScanCode2.ScanStep:=20;
	20://判断扫码结果
		IF EM02V.ScanCode2.Out.ReadSuccess//扫码OK
			OR HMI_Function_Enable[2,2]
			OR HMI_TestMode_Enable
		THEN
			Cell_Info[2,4].CodeSN:=EM02V.ScanCode2.Out.BarCodeString;
			Cell_Info[2,4].CodeSNLevel:=EM02V.ScanCode2.Out.TotalClass;
			SR_ScanCode2.ScanCodeNGNum:=0;//连续NG清零
			SR_ScanCode2.ScanStep:=30;
		ELSIF EM02V.ScanCode2.Out.ReadFailure//扫码NG
		THEN
			Cell_Info[2,4].CodeSN:=EM02V.ScanCode2.Out.BarCodeString;
			Cell_Info[2,4].CodeSNLevel:=EM02V.ScanCode2.Out.TotalClass;
			Cell_Info[2,4].Quality:=41;
			SR_ScanCode2.ScanCodeNGNum:=SR_ScanCode2.ScanCodeNGNum+1;//连续NG+1
			SR_ScanCode2.ScanStep:=40;
		ELSIF TON_Scan2.Q
		THEN
			SR_ScanCode2.ErrOut.Err_OverTime:=TRUE;//超时错误
			SR_ScanCode2.ScanStep:=40;
		END_IF;
	30://规则校验+重码检测+等级判断+一致性校验+非法字符检测
		IF NOT HMI_Function_Enable[2,2] AND NOT HMI_TestMode_Enable THEN
			//=========================================
			//刻码条码规则校验
			SR_ScanCode2.CodeSNCheck1:=HMI_RecipeData.CodeSNCheck;
			SR_ScanCode2.CodeSNCheck2:=LEFT(STR:=Cell_Info[2,4].CodeSN , SIZE:=LEN(HMI_RecipeData.CodeSNCheck) );
			IF NOT HMI_Function_Enable[2,5]
				AND SR_ScanCode2.CodeSNCheck1<>SR_ScanCode2.CodeSNCheck2
			THEN
				Cell_Info[2,4].Quality:=41;
				SR_ScanCode2.ErrOut.Err_Check:=TRUE;//规则校验错误
			END_IF;
			//=========================================
			//刻码条码重码检测
			IF NOT HMI_Function_Enable[2,7]
			THEN
				FOR i:=0 TO 19  DO
					IF Cell_Info[2,4].CodeSN=SR_ScanCode2.SaveCode[i] THEN
						Cell_Info[2,4].Quality:=41;
						SR_ScanCode2.ErrOut.Err_Repeat:=TRUE;//重码错误
					END_IF;
				END_FOR;
				SR_ScanCode2.SaveCode[SR_ScanCode2.SaveCodeNum]:=Cell_Info[2,4].CodeSN;//存码
				SR_ScanCode2.SaveCodeNum:=SR_ScanCode2.SaveCodeNum+1;//入栈序号+1
				IF SR_ScanCode2.SaveCodeNum>19 THEN SR_ScanCode2.SaveCodeNum:=0; END_IF;
			END_IF;
			//=========================================
			//刻码条码等级判断
			CodeSNLevel_INT1:=STRING_TO_INT(Cell_Info[2,4].CodeSNLevel);
			CodeSNLevel_INT2:=STRING_TO_INT(HMI_RecipeData.CodeSNLevel);
			
			IF NOT HMI_Function_Enable[2,8]
				//AND  CodeSNLevel_INT1<CodeSNLevel_INT2
				AND Cell_Info[2,4].CodeSNLevel>HMI_RecipeData.CodeSNLevel
			THEN
				Cell_Info[2,4].Quality:=42;
				SR_ScanCode2.CodeLevelNGNum:=SR_ScanCode2.CodeLevelNGNum+1;
			ELSE
				SR_ScanCode2.CodeLevelNGNum:=0;
			END_IF;
			//=========================================
			//刻码条码一致性校验
			IF Cell_Info[2,4].CodeSN<>Cell_Info[2,4].CodeSNBuffer
				AND Cell_Info[2,4].CodeSNBuffer<>'1'
			THEN
				Cell_Info[2,4].Quality:=41;
				SR_ScanCode2.ErrOut.Err_Consistency:=TRUE;//一致性错误
			END_IF;
			//=========================================
			//刻码条码非法字符“I”,“Z”,“O”检测
			IF FC_FindForbidString(EN:=TRUE , Code:=Cell_Info[2,4].CodeSN )
			THEN
				Cell_Info[2,4].Quality:=41;
				SR_ScanCode2.ErrOut.Err_ImproperChar:=TRUE;//非法字符错误
			END_IF;
		END_IF;
		//=========================================
		//改变物料记忆
		IF Cell_Info[2,4].Quality=80 THEN
			Cell_Info[2,4].Quality:=90;
		END_IF;
		//=========================================
		//跳步
		SR_ScanCode2.ScanStep:=40;
	40://流程结束
		EM02V.ScanCode2.In.Execute:=FALSE;
		SR_ScanCode2.ScanStep:=0;
		
END_CASE;

(******************************************** 治具码扫码流程 *********************************************)
TON_Scan3(In:=SR_ScanCode3.ScanStep>0, PT:=T#15S);
CASE SR_ScanCode3.ScanStep	OF
	0://流程开始
		IF Act.Act05_Auto_Station[2,0]
			AND EM02V.Axis_InPlace_Flag
			AND NOT Cell_Info[2,1].CoverLineJigScanFinish
		THEN
			EM02V.ScanCode3.In.Execute:=FALSE;
			SR_ScanCode3.ScanStep:=10;
		END_IF;
	10://扫码触发
		EM02V.ScanCode3.In.Execute:=TRUE;
		SR_ScanCode3.ScanStep:=20;
	20://判断扫码结果
		IF HMI_Function_Enable[2,3]
		THEN
			FOR i:=1 TO 40 BY 1 DO
			    IF EM02V.Axis_X1.Out.PosDone[i] THEN
					//板链线x轴定位1，最靠上料的第一个治具号就是1
					Cell_Info[2,1].CoverLineJigSN:=INT_TO_STRING(((14+i-2) MOD 14));
					//板链线x轴定位1，最靠上料的第一个治具号就是2，所以需要加1
					//Cell_Info[2,1].CoverLineJigSN:=INT_TO_STRING(((14+i-2) MOD 14)+1);
					EXIT;
				END_IF;
			END_FOR;
			Cell_Info[2,1].CoverLineJigScanFinish:=TRUE;
			SR_ScanCode3.ScanStep:=40;
		ELSIF EM02V.ScanCode3.Out.ReadSuccess//扫码OK
		THEN
			Cell_Info[2,1].CoverLineJigSN:=EM02V.ScanCode3.Out.BarCodeString;
			Cell_Info[2,1].CoverLineJigScanFinish:=TRUE;
			SR_ScanCode3.ScanStep:=40;
		ELSIF EM02V.ScanCode3.Out.ReadFailure//扫码NG
		THEN
			SR_ScanCode3.ErrOut.Err_ScanFailure:=TRUE;//扫码失败
			SR_ScanCode3.ScanStep:=40;
		ELSIF TON_Scan3.Q
		THEN
			SR_ScanCode3.ErrOut.Err_OverTime:=TRUE;//超时错误
			SR_ScanCode3.ScanStep:=40;
		END_IF;
	40://流程结束
		EM02V.ScanCode3.In.Execute:=FALSE;
		SR_ScanCode3.ScanStep:=0;
		
END_CASE;

ST.xhtml:
//////////////////////////////////刻码条码请求 ///////////////////////////////////////////////////////////

(********************************************	顶盖刻码结果	*********************************************)
//清除上一次数据
R_EngraveCodeExcute(Clk:=Catl_MesData.PlcToPc_Int[0]=1);
IF R_EngraveCodeExcute.Q THEN
	Catl_MesData.PcToPlc_Real[0]:=0;
	Catl_MesData.PcToPlc_Real[1]:=0;
	Catl_MesData.PcToPlc_Real[2]:=0;
	Clear(Catl_MesBar.PcToPlc_String[6]);
	Clear(Catl_MesBar.PcToPlc_String[8]);
END_IF;

//上位机下发条码超时
TON11(In:=Catl_MesData.PlcToPc_Int[0]=1 AND NOT H_Messages.Station[2].User_Alarm[67], PT:=T#10S);
IF
	TON11.Q
THEN
	H_Messages.Station[2].User_Alarm[67]:=TRUE;//上位机下发刻码条码超时
	Catl_MesData.PlcToPc_Int[0]:=0;
	EM02V.Process_steps[1]:=0;
END_IF

//刻码流程计时
TON_EngraveCode1(In:=CoverLaser_Step <>0, PT:=T#10S);
IF CoverLaser_Step <>0 THEN
	HC_OmronUtils.TimeToNanoSec(In:=TON_EngraveCode1.ET/1000000 , Out=>EngraveCodeTime_LINT );
	EM02V.EngraveCodeTime:=LINT_TO_REAL(EngraveCodeTime_LINT) ;
END_IF;

IF Catl_MesData.PlcToPc_Int[0]=100//刻码OK
	OR Catl_MesData.PlcToPc_Int[0]=50//刻码条码中存在WM字符
THEN
	//=========================================
	IF Cell_Info[2,3].Quality = 70 
		AND Catl_MesData.PlcToPc_Int[0]=100	
	THEN
		Cell_Info[2,3].Quality := 73;
	END_IF
	Cell_Info[2,3].MICode:=Catl_MesBar.PcToPlc_String[6];//顶盖MI条码(上位机)
	Cell_Info[2,3].CodeSNBuffer:=Catl_MesBar.PcToPlc_String[8];//顶盖刻码条码(上位机)
	
	//=========================================
	//50 刻码条码中存在WM字符
	IF Catl_MesData.PlcToPc_Int[0]=50
	THEN
		H_Messages.Station[2].User_Alarm[53]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码条码中存在WM字符，请检查刻码条码字符是否重叠；
	END_IF;
	
	//=========================================
	//MI条码空字符检查
	IF NOT HMI_Function_Enable[2,9]
		AND LEN(Catl_MesBar.PcToPlc_String[6])=0
	THEN
		H_Messages.Station[2].User_Alarm[0]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码结果OK，但返回的MI条码是空字符，请检查上位机软件是否出错！
		
		IF Cell_Info[2,3].Quality = 70 
		THEN
			Cell_Info[2,3].Quality := 40;
		END_IF
	END_IF;
	//MI条码规则校验
	IF NOT HMI_Function_Enable[2,9]
		AND Catl_MesBar.PcToPlc_String[6]<>HMI_RecipeData.MICodeCheck
	THEN
		H_Messages.Station[2].User_Alarm[1]:=TRUE;//EM02刻码拉带模组：顶盖刻码MI条码规则校验错误，请检查刻码MI条码规则，或触摸屏刻码MI条码规则是否设置错误！		
		IF Cell_Info[2,3].Quality = 70 
		THEN
			Cell_Info[2,3].Quality := 40;
		END_IF
	END_IF;

	//=========================================
	//返回的刻码条码空字符检查
	IF LEN(Catl_MesBar.PcToPlc_String[8])=0
	THEN
		H_Messages.Station[2].User_Alarm[2]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码结果OK，但返回的顶盖刻码条码是空字符，请检查上位机软件是否出错！
	END_IF;
	
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[0]:=0;
	
ELSIF Catl_MesData.PlcToPc_Int[0]=35//NG
	OR Catl_MesData.PlcToPc_Int[0]=40//拍照定位失败
	OR Catl_MesData.PlcToPc_Int[0]=45//跳码失败
	OR TON_EngraveCode1.Q//流程长时间未响应
THEN
	//=========================================
	
	//=========================================
	//40 拍照定位失败
	IF Catl_MesData.PlcToPc_Int[0]=40
	THEN
		H_Messages.Station[2].User_Alarm[3]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码拍照定位失败，请打开上位机软件检查刻码功能；
	END_IF;
	
	//=========================================
	//45 跳码失败
	IF Catl_MesData.PlcToPc_Int[0]=45
	THEN
		EngraveCodeRefreshErr1:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码跳码失败，请打开上位机软件检查刻码功能；
	END_IF;
	//=========================================
	//流程长时间未响应
	IF TON_EngraveCode1.Q
	THEN
		MyStation.EMStation[2,0].ResetComplete:=FALSE;//需要重新初始化模组
		H_Messages.Station[2].User_Alarm[5]:=TRUE;//EM02刻码拉带模组：等待上位机反馈顶盖刻码完成，流程长时间未响应，请打开上位机软件检查刻码功能；
	END_IF;
	EngraveCodeNGNum1:=EngraveCodeNGNum1+1;//连续NG+1
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[0]:=0;

END_IF;





	//=========================================
	//返回的刻码条码空字符检查
	ton02_1(IN:= 
	  ( LEN(Catl_MesBar.PcToPlc_String[8])=0 OR 
		Catl_MesBar.PcToPlc_String[8] =''  ) AND 
		Cell_Info[2,3].Quality = 73	 AND 
		Act.Act05_Auto_Station[2,0]  AND
		NOT HMI_TestMode_Enable  AND 
		NOT HMI_Function_Enable[2,1]  
		, PT:= T#5S
		, Q=> 
		, ET=> );
	IF  ton02_1.Q
	THEN
		H_Messages.Station[2].User_Alarm[2]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码结果OK，但返回的顶盖刻码条码是空字符，请检查上位机软件是否出错！
		Cell_Info[2,3].Quality := 40;
	END_IF;







//////////////////////////////////刻码CCD引导 ///////////////////////////////////////////////////////////
//数据发送 ：stationName+ “: ”+ code     工位号 + : +  条码 
//数据接收：OK;1.000000;2.000000;3.000000   //结果 +  X偏移量+Y偏移量 +R角度
IF  NOT  HMI_Function_Enable[2,1] THEN
	CASE CoverCCD_Step OF
		0://判断请求CCD拍照条件
		TON_2(IN:=EM02V.Cy_Up1.Out.XV , PT:= T#200MS, Q=> , ET=> );
			IF Cell_Info[2,3].Quality  = 73 			//未引导CCD
				AND LEN(Cell_Info[2,3].CodeSNBuffer) >0	//条码长度大于0
				AND NOT EM02P.AxisMovingFlag			//板链线不在移动中
				AND EM02V.Axis_InPlace_Delay			//板链线到位
				AND EM02V.Cy_Up1.Out.XV
				AND Act.Act05_Auto_Station[2,0]
				AND TON_2.Q
			THEN
				CoverCCD_Step :=10	;
				Catl_CcdData.PlcToCcd_Int[25]	:=  0;//A线顶盖刻码引导CCD 1触发
				Catl_CcdData.CcdToPlc_Real[12]	:=  0;//A线刻码顶盖偏移值X
				Catl_CcdData.CcdToPlc_Real[13]	:=  0;//A线刻码顶盖偏移值Y
				Catl_CcdData.CcdToPlc_Real[14]	:=  0;//A线刻码顶盖偏移值R
				Catl_CcdBar.PlcToCcd_String[30]	:='';//A线刻码引导顶盖条码
				Catl_CcdData.CcdToPlc_Int[19]	:=0;//A线顶盖刻码引导CCD触发  2OK 3NG
			END_IF
		10://触发刻码	
			Catl_CcdBar.PlcToCcd_String[30]	:=Cell_Info[2,3].CodeSNBuffer;//A线刻码引导顶盖条码
			Catl_CcdData.PlcToCcd_Int[25]	:=  1;//A线顶盖刻码引导CCD 1触发
			CoverCCD_Step :=20	;
			
		20://等待CCD反馈结果数据
			TON_CoverCCD_Read(IN:=TRUE, PT:=  T#5S);
			IF Catl_CcdData.CcdToPlc_Int[19] <>0
			THEN
				IF Catl_CcdData.CcdToPlc_Int[19] =	2  
			        AND Catl_CcdData.CcdToPlc_Real[12] < 5  AND  Catl_CcdData.CcdToPlc_Real[12] > -5 
					AND Catl_CcdData.CcdToPlc_Real[13] < 5  AND  Catl_CcdData.CcdToPlc_Real[13] > -5 
					AND Catl_CcdData.CcdToPlc_Real[14] < 5  AND  Catl_CcdData.CcdToPlc_Real[14] > -5 
				THEN
					Cell_Info[2,3].EngraveCodeOffsetXValue := Catl_CcdData.CcdToPlc_Real[12];
					Cell_Info[2,3].EngraveCodeOffsetYValue := Catl_CcdData.CcdToPlc_Real[13];
					Cell_Info[2,3].EngraveCodeOffsetRValue := Catl_CcdData.CcdToPlc_Real[14];
					Cell_Info[2,3].Quality := 75;//未刻码
					CoverCCD_NGNum := 0;
					CoverCCD_NGNum1:= 0 ;
					CoverCCD_Step :=0	;	
					
				ELSIF Catl_CcdData.CcdToPlc_Int[19] =	3
					AND CoverCCD_NGNum	<5
					OR (Catl_CcdData.CcdToPlc_Real[12] >= 5  OR   Catl_CcdData.CcdToPlc_Real[12] <= -5  OR
						Catl_CcdData.CcdToPlc_Real[13] >= 5  OR   Catl_CcdData.CcdToPlc_Real[13] <= -5  OR
						Catl_CcdData.CcdToPlc_Real[14] >= 5  OR   Catl_CcdData.CcdToPlc_Real[14] <= -5   
						)					
				THEN 
					CoverCCD_NGNum := CoverCCD_NGNum+1;
					CoverCCD_Step :=0	;
				ELSIF //Catl_CcdData.CcdToPlc_Int[19] =	3  OR 
					  CoverCCD_NGNum	>=5
				THEN
				    Cell_Info[2,3].Quality := 40;//刻码引导NG
					H_Messages.Station[2].User_Alarm[60] := TRUE;//EM02_刻码拉带模组:刻码激光引导CCD连续拍照NG，请检查引导CCD是否正常开启；											
					CoverCCD_NGNum := 0 ;
					CoverCCD_Step :=0	;	
			//	ELSIF CoverCCD_Count <4
			//	THEN 		
			//		CoverLaser_Step :=0	;
			//		H_Messages.Station[2].User_Alarm[61] := TRUE;//EM02_刻码拉带模组:接收刻码激光引导CCD数据异常，缺少部分数据，请检查引导CCD是否正常开启；			
				END_IF  ;

				
				TON_CoverCCD_Read(IN:=FALSE, PT:=  T#5S);			
				Catl_CcdData.PlcToCcd_Int[25]	:=	0;
			ELSIF	TON_CoverCCD_Read.Q
			THEN 
				CoverCCD_Step :=0	;
				TON_CoverCCD_Read(IN:=FALSE, PT:=  T#5S);
				Catl_CcdData.PlcToCcd_Int[25]	:=	0;
				H_Messages.Station[2].User_Alarm[62] := TRUE;//EM02_刻码拉带模组:接收刻码激光引导CCD数据超时，请检查引导CCD是否正常开启；
			END_IF		
	END_CASE
ELSE
	CoverCCD_Step :=  0;
	TON_CoverCCD_Send(IN:=FALSE, PT:= T#3S);
	TON_CoverCCD_Read(IN:=FALSE, PT:=  T#5S);
END_IF  ;

IF  CoverCCD_NGNum	>=1 THEN  //1个不复测 
	Cell_Info[2,3].Quality := 40;//刻码引导NG										
	CoverCCD_NGNum := 0 ;
	CoverCCD_NGNum1:= CoverCCD_NGNum1 + 1 ;
	CoverCCD_Step  :=0	;
END_IF  ;


IF  CoverCCD_NGNum1	>=3 THEN  //连续3个报警
	Cell_Info[2,3].Quality := 40;//刻码引导NG
	H_Messages.Station[2].User_Alarm[60] := TRUE;//EM02_刻码拉带模组:刻码激光引导CCD连续拍照NG，请检查引导CCD是否正常开启；											
	CoverCCD_NGNum := 0 ;
	CoverCCD_NGNum1:= 0 ;
	CoverCCD_Step  := 0	;
END_IF  ;







IF TRUE THEN
	;;
