// END_IF

END_IF




//////////////////////////////////刻码激光 ///////////////////////////////////////////////////////////
//数据发送 ：update_code1;00CB7T000000BFBC2416648;001CB7T00000;0BFBC2416648;39524;-1.5;1.38;0.18   
			//update_code + 工位号 + ; + 条码前12位 + ; +条码剩余数据 + ; + MI码 + X偏移量+Y偏移量 +R角度
//数据接收：OK;   //结果 +  
IF  NOT  HMI_Function_Enable[2,1] THEN
	CASE CoverLaser_Step OF
		0://判断请求刻码条件
			IF Cell_Info[2,3].Quality  = 75 			//未刻码
				AND LEN(Cell_Info[2,3].CodeSNBuffer) >0	//条码长度大于0
				AND NOT EM02P.AxisMovingFlag			//板链线不在移动中
				AND EM02V.Axis_InPlace_Delay			//板链线到位
				AND TCP_CoverLaser.bConnected				//TCP连接OK
				AND NOT TCP_CoverLaser.bError		
				AND  Act.Act05_Auto_Station[2,0]
			THEN
				CoverLaser_Step :=10	;
				Clear( TCP_CoverLaser.sSendData)       ;
				Clear( TCP_CoverLaser.sReadData)       ;
			END_IF
		10://触发刻码	
			TON_CoverLaser_Send(IN:=TRUE, PT:= T#5S);
		CoverLaser_SendDataTemp[0]:='update_code';//
	CoverLaser_SendDataTemp[1]:='1';//工位号
	CoverLaser_SendDataTemp[2]:=';';//
	CoverLaser_SendDataTemp[3]:=Cell_Info[2,3].CodeSNBuffer;//工位号
	CoverLaser_SendDataTemp[4]:=';';//
	CoverLaser_SendDataTemp[5]:=MID(STR:= Cell_Info[2,3].CodeSNBuffer, LEN:= 12, POS:= 1);//条码前12位
	CoverLaser_SendDataTemp[6]:=';';//
	CoverLaser_SendDataTemp[7]:=DELETE(STR:=Cell_Info[2,3].CodeSNBuffer, LEN:= 12, POS:= 1);//条码剩余数据
	CoverLaser_SendDataTemp[8]:=';';//
	CoverLaser_SendDataTemp[9]:=HMI_RecipeData.MICodeCheck;
	CoverLaser_SendDataTemp[10]:=';';//
	CoverLaser_SendDataTemp[11]:=REAL_TO_STRING(Cell_Info[2,3].EngraveCodeOffsetXValue);//
	CoverLaser_SendDataTemp[12]:=';';//
	CoverLaser_SendDataTemp[13]:=REAL_TO_STRING(Cell_Info[2,3].EngraveCodeOffsetYValue);//
	CoverLaser_SendDataTemp[14]:=';';//
	CoverLaser_SendDataTemp[15]:=REAL_TO_STRING(Cell_Info[2,3].EngraveCodeOffsetRValue);//
	//TCP_CoverLaser.sSendData:=FC_StrConcat(CoverLaser_SendDataTemp);
	TCP_CoverLaser.sSendData:=CONCAT(STR1:= CoverLaser_SendDataTemp[0], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[1], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[2], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[3], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[4], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[5], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[6], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[7], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[8], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[9], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[10], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[11], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[12], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[13], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[14], STR2:= CoverLaser_SendDataTemp[15]
							)))))))))))))));
						
			;
			TCP_CoverLaser.bSendExecute	:= TRUE;
			IF TCP_CoverLaser.bSendDone THEN
				TCP_CoverLaser.bSendExecute	:= FALSE; 
				CoverLaser_SendNGNum := 0 ;
				CoverLaser_Step :=20	;
				TON_CoverLaser_Send(IN:=FALSE, PT:= T#5S);
			ELSIF CoverLaser_SendNGNum <3
				AND TON_CoverLaser_Send.Q			//发送失败 重新发送
			THEN 
				TCP_CoverLaser.bSendExecute	:= FALSE;
				TON_CoverLaser_Send(IN:=FALSE, PT:= T#5S);
				CoverLaser_SendNGNum := CoverLaser_SendNGNum+1;
				CoverLaser_Step :=0	;
			ELSIF CoverLaser_SendNGNum >=3
				AND TON_CoverLaser_Send.Q			//发送失败 报警人工检测连接
			THEN 
				TCP_CoverLaser.bSendExecute	:= FALSE;
				TON_CoverLaser_Send(IN:=FALSE, PT:= T#5S);
				CoverLaser_SendNGNum := 0 ;
				CoverLaser_Step :=0	;
				H_Messages.Station[2].User_Alarm[63] := TRUE;//EM02_刻码拉带模组:刻码激光器刻码发送连续三次超时，请检查刻码激光器是否正常；
			END_IF
		20://等待CCD反馈结果数据
			TON_CoverLaser_Read(IN:=NOT TCP_CoverLaser.bReadDone, PT:=  T#5S);
			IF TCP_CoverLaser.bReadDone
			THEN 
				FC_SplitString(
					strData:= TCP_CoverLaser.sReadData, 
					strDiv:= ';', 
					SplitString=> CoverLaser_ReadDataTemp, 
					nCount=>CoverLaser_Count )
					;
				IF CoverLaser_ReadDataTemp[1] = 'ok' THEN
					Cell_Info[2,3].Quality := 80;//未刻码扫码
					Cell_Info[2,3].EngraveCodeResult:=1;//刻码结果：1/OK,2/NG
					Cell_Info[2,3].EngraveCodeWindSpeed:=EM02V.EngraveCodeWindSpeed1;//刻码除尘风速
					Cell_Info[2,3].EngraveCodeTime:=EM02V.EngraveCodeTime;//刻码时间
					CoverLaser_Step :=0	;
				ELSIF CoverLaser_ReadDataTemp[1] = 'ng'
				THEN 	
					Cell_Info[2,3].Quality := 40;//刻码NG
					CoverLaser_Step :=0	;			
				ELSIF CoverLaser_ReadDataTemp[1] <> 'ok' 
					AND CoverLaser_ReadDataTemp[1] <> 'ng' 
				THEN 		
					CoverLaser_Step :=0	;
					Cell_Info[2,3].Quality := 40;//刻码NG
					H_Messages.Station[2].User_Alarm[64] := TRUE;//EM02_刻码拉带模组:接收刻码激光器数据异常，缺少部分数据，请检查刻码激光器是否正常；			
				END_IF
				TON_CoverLaser_Read(IN:=FALSE, PT:=  T#5S);
			ELSIF	TON_CoverLaser_Read.Q
			THEN 
				CoverLaser_Step :=0	;
				Cell_Info[2,3].Quality := 40;//刻码NG
				TON_CoverLaser_Read(IN:=FALSE, PT:=  T#5S);
				H_Messages.Station[2].User_Alarm[65] := TRUE;//EM02_刻码拉带模组:接收刻码激光器数据超时，请检查刻码激光器是否正常；
			END_IF		
	END_CASE
ELSE
	CoverLaser_Step :=  0;
	Clear( TCP_CoverLaser.sSendData)       ;
	Clear( TCP_CoverLaser.sReadData)       ;
	TON_CoverLaser_Send(IN:=FALSE, PT:= T#5S);
	TON_CoverLaser_Read(IN:=FALSE, PT:=  T#5S);
END_IF

///////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////

//////////////////////////////////手动请求刻码条码 ///////////////////////////////////////////////////////////
IF HMI_Button[2,2] 
	AND MyStatus.StatusManual
	AND EM02V.Axis_InPlace_Flag
	AND EM02V.Sen_HaveCover4.Out.Filtered_Q
	AND Cell_Info[2,3].Quality =0
THEN
	Catl_MesData.PlcToPc_Int[0]:=1;
	Catl_CcdData.CcdToPlc_Real[12] := 0;
	Catl_CcdData.CcdToPlc_Real[13] := 0;
	Catl_CcdData.CcdToPlc_Real[14] := 0;		
	HMI_Button[2,2]	:=	FALSE;
END_IF


//////////////////////////////////手动刻码CCD引导 ///////////////////////////////////////////////////////////
//激光刻码触发
//触发超时
TON_ManCoverCCD(IN:= HMI_Button[2,5]
	AND Catl_CcdData.PlcToCcd_Int[25] =1
	, PT:= T#3S);

R_CoverCCD(Clk:=HMI_Button[2,5]);
IF NOT HMI_Function_Enable[2,1]
	AND CoverCCD_Step = 0 
	AND R_CoverCCD.Q
	AND EM02V.Axis_InPlace_Flag
	AND EM02V.Sen_HaveCover4.Out.Filtered_Q
	AND MyStatus.StatusManual
THEN
			Catl_CcdBar.PlcToCcd_String[30]	:=Cell_Info[2,3].CodeSNBuffer;//A线刻码引导顶盖条码
			Catl_CcdData.PlcToCcd_Int[25]	:=  1;//A线顶盖刻码引导CCD 1触发
ELSIF TON_ManCoverCCD.Q
THEN 
	Catl_CcdData.PlcToCcd_Int[25]	:=  0;//A线顶盖刻码引导CCD 1触发
	HMI_Button[2,5] 		  := FALSE;
ELSIF NOT MyStatus.StatusManual
THEN 
	HMI_Button[2,5] 		  := FALSE;
END_IF

TON_ManCoverCCD_1(IN:= HMI_Button[2,5]	
	, PT:= T#1S);

//接收反馈数据
IF   HMI_Button[2,5]   
	//AND  Catl_CcdData.PlcToCcd_Int[25] =1
	AND		Catl_CcdData.CcdToPlc_Int[19] <>0
	AND  ( Catl_CcdData.CcdToPlc_Real[12] <> 0 OR 
		   Catl_CcdData.CcdToPlc_Real[13] <> 0 OR 
		   Catl_CcdData.CcdToPlc_Real[14] <> 0 OR 
	       TON_ManCoverCCD_1.Q  
		   )
THEN
	;//OK;1.000000;2.000000;3.000000   //结果 +  X偏移量+Y偏移量 +R角度
	Cell_Info[2,3].EngraveCodeOffsetXValue := Catl_CcdData.CcdToPlc_Real[12];
	Cell_Info[2,3].EngraveCodeOffsetYValue := Catl_CcdData.CcdToPlc_Real[13];
	Cell_Info[2,3].EngraveCodeOffsetRValue := Catl_CcdData.CcdToPlc_Real[14];
	HMI_Button[2,5] := FALSE;
	Catl_CcdData.PlcToCcd_Int[25]	:=	0;
	Catl_CcdData.CcdToPlc_Int[19]	:=	0;
END_IF		
	



//////////////////////////////////手动刻码激光 ///////////////////////////////////////////////////////////
//激光刻码触发

R_CoverLaser(Clk:=HMI_Button[2,6]);
IF NOT HMI_Function_Enable[2,1]
	AND CoverLaser_Step = 0 
	AND R_CoverLaser.Q
	AND EM02V.Axis_InPlace_Flag
	AND EM02V.Sen_HaveCover4.Out.Filtered_Q
	AND MyStatus.StatusManual
THEN
	CoverLaser_SendDataTemp[0]:='update_code';//
	CoverLaser_SendDataTemp[1]:='1';//工位号
	CoverLaser_SendDataTemp[2]:=';';//
	CoverLaser_SendDataTemp[3]:=Cell_Info[2,3].CodeSNBuffer;//工位号
	CoverLaser_SendDataTemp[4]:=';';//
	CoverLaser_SendDataTemp[5]:=MID(STR:= Cell_Info[2,3].CodeSNBuffer, LEN:= 12, POS:= 1);//条码前12位
	CoverLaser_SendDataTemp[6]:=';';//
	CoverLaser_SendDataTemp[7]:=DELETE(STR:=Cell_Info[2,3].CodeSNBuffer, LEN:= 12, POS:= 1);//条码剩余数据
	CoverLaser_SendDataTemp[8]:=';';//
	CoverLaser_SendDataTemp[9]:=HMI_RecipeData.MICodeCheck;
	CoverLaser_SendDataTemp[10]:=';';//
	CoverLaser_SendDataTemp[11]:=REAL_TO_STRING(Cell_Info[2,3].EngraveCodeOffsetXValue);//
	CoverLaser_SendDataTemp[12]:=';';//
	CoverLaser_SendDataTemp[13]:=REAL_TO_STRING(Cell_Info[2,3].EngraveCodeOffsetYValue);//
	CoverLaser_SendDataTemp[14]:=';';//
	CoverLaser_SendDataTemp[15]:=REAL_TO_STRING(Cell_Info[2,3].EngraveCodeOffsetRValue);//
	//TCP_CoverLaser.sSendData:=FC_StrConcat(CoverLaser_SendDataTemp);
	TCP_CoverLaser.sSendData:=CONCAT(STR1:= CoverLaser_SendDataTemp[0], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[1], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[2], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[3], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[4], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[5], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[6], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[7], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[8], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[9], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[10], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[11], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[12], STR2:=
						CONCAT(STR1:= CoverLaser_SendDataTemp[13], STR2:= 
						CONCAT(STR1:= CoverLaser_SendDataTemp[14], STR2:= CoverLaser_SendDataTemp[15]
							)))))))))))))));
	TCP_CoverLaser.bSendExecute	:= TRUE;
ELSIF HMI_Button[2,6]
	AND TCP_CoverLaser.bSendExecute	
	AND TCP_CoverLaser.bSendDone
	OR TON_ManCoverLaser.Q
THEN 
	TCP_CoverLaser.bSendExecute := FALSE;
	HMI_Button[2,6] 		  := FALSE;
	Cell_Info[2,3].CodeSNBuffer :='';
	Cell_Info[2,3].EngraveCodeOffsetXValue := 0;
	Cell_Info[2,3].EngraveCodeOffsetYValue := 0;
	Cell_Info[2,3].EngraveCodeOffsetRValue := 0;
ELSIF NOT MyStatus.StatusManual
THEN 
	HMI_Button[2,6] 		  := FALSE;
END_IF

//触发超时
TON_ManCoverLaser(IN:= HMI_Button[2,6]
	AND TCP_CoverLaser.bSendExecute
	AND NOT TCP_CoverLaser.bSendDone, PT:= T#3S);


//激光刻码触发
IF  R_CoverLaser.Q AND NOT HMI_Function_Enable[2,1] AND 
	 MyStatus.StatusManual AND
	(NOT EM02V.Sen_HaveCover4.Out.Filtered_Q OR NOT EM02V.Axis_InPlace_Flag)
THEN
	H_Messages.Station[2].User_Alarm[6]:=TRUE;//EM02刻码拉带模组：激光刻码手动触发，但是检测到刻码位无顶盖或移栽X轴不在工位上，禁止触发激光刻码；
END_IF;

data.STCode:
IF Act.Act06_IOCall_FB[2]  THEN
(*
	//CT计算
	CycleTime(
		Enable			:=	Act.Act05_Auto							,//计时使能
		Reset			:=	MyInput.Reset_Input						,//错误复位
		bClear			:=	CycleTime_bClear						,//清除计时，在初始化程序清除
		Complete		:=	CycleTime_Complete						,//完成计时，在自动程序中触发
		ProgramStep		:=	AutoStep								,//步骤变量
		Condition		:=	AutoStep >= 0							,//需要计时的步骤条件
		SysCycleTime	:=	SystemCycleTime							,//系统扫描周期
		HMICycleTime	:=	HMICycleTime[0]							//输出给HMI用的步骤时间
		);
	//工位时间汇总
	MyStation.EM[2].CT	:=	HMICycleTime[0].StationCycleTime	;

*)


(*****************************CY0刻码除尘避位气缸X070102/X070101/Y070112/Y070111*****************************)

EM02V.Cy_Up1.In.Shield :=Act.Act10_Call_Status[2,0].AlarmShield;

Cy_Up1(
	Enable							:=TRUE, //功能块使能
