(******************************** 工位动作节拍 ****************************************) // 刻码拉带动作节拍 EM02CycleTime[0]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM02_CycleTime[0].ClearData , //清除步骤时间列表计时 Complete := EM02_CycleTime[0].Complete , //完成计时输出列表 ProgramStep := EM02V.Process_steps[0] , //步骤变量 Condition := EM02V.Process_steps[0] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM02_CycleTime[0] //输出步骤号和时间 );
// 刻码动作节拍 EM02CycleTime[1]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM02_CycleTime[1].ClearData , //清除步骤时间列表计时 Complete := EM02_CycleTime[1].Complete , //完成计时输出列表 ProgramStep := EM02V.Process_steps[1] , //步骤变量 Condition := EM02V.Process_steps[1] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM02_CycleTime[1] //输出步骤号和时间 );
// 翻转动作节拍 EM02CycleTime[2]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM02_CycleTime[2].ClearData , //清除步骤时间列表计时 Complete := EM02_CycleTime[2].Complete , //完成计时输出列表 ProgramStep := EM02V.Process_steps[2] , //步骤变量 Condition := EM02V.Process_steps[2] >= 10 AND EM02V.Process_steps[2]<>230 AND EM02V.Process_steps[2]<>430, //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM02_CycleTime[2] //输出步骤号和时间 );
// 刻码偏移CCD动作节拍 EM02CycleTime[3]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM02_CycleTime[3].ClearData , //清除步骤时间列表计时 Complete := EM02_CycleTime[3].Complete , //完成计时输出列表 ProgramStep := EM02V.Process_steps[3] , //步骤变量 Condition := EM02V.Process_steps[3] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM02_CycleTime[3] //输出步骤号和时间 );

//上料位
EM02V.Done[0]:=Cell_Info[2,0].Quality<>0
							OR Cell_Info[2,1].Quality<>0
							OR AutoClearCover.Q 	
							OR (HMI_Button[1,3]AND Cell_Info[2,6].Quality=0 AND NOT AutoClearCover.Q
								AND (
								Cell_Info[2,0].Quality>0 OR Cell_Info[2,1].Quality>0 OR Cell_Info[2,2].Quality>0 
								OR Cell_Info[2,3].Quality>0 OR Cell_Info[2,4].Quality>0 OR Cell_Info[2,5].Quality>0 ))
							OR MyStation.EMStation[1,3].Shielding AND HMI_TestMode_Enable;
//批次码扫码位完
EM02V.Done[1]:=Cell_Info[2,1].Quality<>60
							AND Cell_Info[2,1].Quality<>65
							AND Cell_Info[2,1].CoverLineJigScanFinish;
//缓存位
EM02V.Done[2]:=TRUE;
//刻码位
EM02V.Done[3]:=Cell_Info[2,3].Quality<>70
						AND 	Cell_Info[2,3].Quality<>73
						AND 	Cell_Info[2,3].Quality<>75
							AND EM02V.Cy_Up1.Out.XR;
//刻码扫码位
EM02V.Done[4]:=Cell_Info[2,4].Quality<>80
							AND Cell_Info[2,4].Quality<>90;
//刻码CCD检测位
EM02V.Done[5]:=Cell_Info[2,5].Quality<>95;
//下料位
EM02V.Done[6]:=Cell_Info[2,6].Quality=0;

//下料位属性改变
StateEnd_R1(CLK:= HMI_Button[2,7]  AND Cell_Info[2,6].Quality <>0 , Q=> );
IF StateEnd_R1.Q THEN
	Cell_Info[2,6].Quality:=40 ;
END_IF  ;


//自动清料条件计时
AutoClearCover_Condition(
	In:=Act.Act05_Auto_Station[2,0]
		AND Cell_Info[1,5].Quality=0
		AND Cell_Info[1,6].Quality=0
		AND Cell_Info[2,0].Quality=0
		AND Cell_Info[2,1].Quality=0
		AND NOT HMI_Button[2,1]
	, PT:=T#10S);

//自动清料计时
AutoClearCover(
	In:=AutoClearCover_Condition.Q
	AND (Cell_Info[2,2].Quality<>0
	OR Cell_Info[2,3].Quality<>0
	OR Cell_Info[2,4].Quality<>0
	OR Cell_Info[2,5].Quality<>0)
	AND Cell_Info[2,6].Quality=0
	AND NOT EM02V.Done[0]
	AND EM02V.Done[1]
	AND EM02V.Done[2]
	AND EM02V.Done[3]
	AND EM02V.Done[4]
	AND EM02V.Done[5]
	AND EM02V.Done[6]
	AND EM02V.MovingAllow[0]
	, PT:=T#2S);

TON2_4(
	  IN:= Act.Act05_Auto_Station[2,0]
		AND Cell_Info[1,5].Quality=0
		AND Cell_Info[1,6].Quality=0
		AND Cell_Info[2,6].Quality=0
		AND NOT HMI_Button[2,1]
		AND NOT EM02V.Done[0]
		AND EM02V.Done[1]
		AND EM02V.Done[2]
		AND EM02V.Done[3]
		AND EM02V.Done[4]
		AND EM02V.Done[5]
		AND EM02V.Done[6]
		AND EM02V.MovingAllow[0]
		AND NOT EM02_Q.Q
	, PT:= T#3S
	, Q=> 
	, ET=> );
	
EM02_Q(
	 IN:= Cell_Info[2,0].Quality = 0 AND 
         Cell_Info[2,1].Quality = 0 AND 
         Cell_Info[2,2].Quality = 0 AND 
         Cell_Info[2,3].Quality = 0 AND 
         Cell_Info[2,4].Quality = 0 AND 
         Cell_Info[2,5].Quality = 0 AND 
         Cell_Info[2,6].Quality = 0  
	, PT:=  T#4S
	, Q=> 
	, ET=> );		 		 
;


//工位完成状态显示
EM02P.Done:=EM02V.Done;

(********************************************	治具屏蔽		*********************************************)
FOR i:=1 TO 14  DO
	IF i=14 THEN
		IF EM02P.VehicleShielding[i]
		AND EM02V.Axis_X1.Out.PosDone[1]
		AND Cell_Info[2,0].Quality=0
		THEN
			Cell_Info[2,0].Quality:=1;
		END_IF;
	ELSE
		IF EM02P.VehicleShielding[i]
		AND EM02V.Axis_X1.Out.PosDone[i+1]
		AND Cell_Info[2,0].Quality=0
		THEN
			Cell_Info[2,0].Quality:=1;
		END_IF;
		
	END_IF
	
END_FOR;

(********************************************	人工上料		*********************************************)
F_Button(Clk:=HMI_Button[2,1]);
IF F_Button.Q
	AND Cell_Info[2,0].Quality=0
	AND NOT HMI_TestMode_Enable
THEN
	Cell_Info[2,0].Quality:=60;
END_IF;

(********************************************	顶盖批次码进站校验流程		*********************************************)
IF Act.Act05_Auto_Station[2,0]
	AND EM02V.Axis_InPlace_Flag
	AND NOT EM02P.AxisMovingFlag
	AND Cell_Info[2,1].Quality=65
	AND Catl_MesData.PlcToPc_Int[10]=0
THEN
	Catl_MesBar.PlcToPc_String[1]:=Cell_Info[2,1].OriginalCodeSN;//顶盖批次码
	Catl_MesData.PlcToPc_Int[10]:=1;
END_IF;

IF Catl_MesData.PlcToPc_Int[10]=100//校验OK
	OR HMI_Function_Enable[0,0]
	OR HMI_TestMode_Enable
	OR HMI_Function_Enable[2,0]  //批次码
THEN
	IF Cell_Info[2,1].Quality=65 THEN
		Cell_Info[2,1].Quality:=70;
	END_IF;
	Catl_MesData.PlcToPc_Int[10]:=0;
ELSIF Catl_MesData.PlcToPc_Int[10]=35//校验NG
THEN
	IF Cell_Info[2,1].Quality=65 THEN
		Cell_Info[2,1].Quality:=50;
	END_IF;
	Catl_MesData.PlcToPc_Int[10]:=0;
	H_Messages.Station[2].User_Alarm[25]:=TRUE;//EM02刻码拉带模组：上位机反馈1#顶盖批次码进站校验结果NG，请打开上位机软件，查看批次码规则错误的详细信息；
END_IF;

(********************************************	顶盖进站流程		*********************************************)
IF Act.Act05_Auto_Station[2,0]
	AND EM02V.Axis_InPlace_Flag
	AND NOT EM02P.AxisMovingFlag
	AND Cell_Info[2,4].Quality=90
	AND Catl_MesData.PlcToPc_Int[2]=0
THEN
	Catl_MesBar.PlcToPc_String[0]:=Cell_Info[2,4].CodeSN;//顶盖刻码条码
	Catl_MesData.PlcToPc_Int[2]:=1;
END_IF;


IF Catl_MesData.PlcToPc_Int[2]=100//MES OK
	OR (Catl_MesData.PlcToPc_Int[2]=1 AND HMI_Function_Enable[0,0])
	OR (Catl_MesData.PlcToPc_Int[2]=1 AND HMI_TestMode_Enable  )
	OR (Catl_MesData.PlcToPc_Int[2]=1 AND HMI_Function_Enable[2,1]  )
THEN
	//=========================================
	//传递记忆
	IF Cell_Info[2,4].Quality=90 THEN
		Cell_Info[2,4].Quality:=95;
	END_IF;
	Cell_Info[2,4].LoadTime_Cover:=Catl_MesBar.PcToPlc_String[0];
	EntranceNGNum1:=0;
	
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[2]:=0;
	
ELSIF Catl_MesData.PlcToPc_Int[2]=35//MES NG
	OR Catl_MesData.PlcToPc_Int[2]=45//禁用字符NG
	OR Catl_MesData.PlcToPc_Int[2]=55//重码NG
THEN
	//=========================================
	//传递记忆
	IF Cell_Info[2,4].Quality=90 THEN
		Cell_Info[2,4].Quality:=50;
	END_IF;
	Cell_Info[2,4].LoadTime_Cover:=Catl_MesBar.PcToPlc_String[0];
	EntranceNGNum1:=EntranceNGNum1+1;
	
	//=========================================
	//45 禁用字符NG
	IF Catl_MesData.PlcToPc_Int[2]=45
	THEN
		H_Messages.Station[2].User_Alarm[51]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖进站结果是禁用字符NG，请检查顶盖刻码条码是否存在禁用字符，打开上位机软件查看详细信息；
	END_IF;
	
	//=========================================
	//55 重码NG
	IF Catl_MesData.PlcToPc_Int[2]=55
	THEN
		H_Messages.Station[2].User_Alarm[52]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖进站结果是重码NG，请检查顶盖刻码条码或顶盖批次码是否正常；
	END_IF;
	
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[2]:=0;
	
END_IF;

FOR StationSum := 0 TO StationNum BY 1 DO
	StationInit_R[StationSum](Clk:=MyStation.EMStation[EMNumber,StationSum].Init OR Act.Act04_Init[EMNumber]);
	IF  StationInit_R[StationSum].Q 
	THEN 
		MyStation.EMStation[EMNumber,StationSum].ResetComplete :=FALSE;
	END_IF;
    IF 	(MyStation.EMStation[EMNumber,StationSum].Init 
		OR Act.Act04_Init[EMNumber])
		AND Inital_Runing
		AND MyInput.AutoSwitch_Input
		AND NOT MyStation.EM[EMNumber].Shielding
		AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
		AND NOT MyStation.EM[EMNumber].IsAlarm
		AND NOT MyStation.EM[0].Running
		AND NOT OperationOut.Abort
		AND NOT OperationOut.Stop
		AND NOT OperationOut.Hold
		AND NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete
	THEN 
		Act.Act04_Init_Station[EMNumber,StationSum] := TRUE;
	ELSE
		Act.Act04_Init_Station[EMNumber,StationSum] := FALSE;
	END_IF;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	IF  MyStation.EMStation[EMNumber,StationSum].ResetComplete OR  MyStation.EMStation[EMNumber,StationSum].Shielding THEN 
		MyStation.EM[EMNumber].ResetComplete :=TRUE;
	ELSIF NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
	THEN 
		MyStation.EM[EMNumber].ResetComplete := FALSE;
		EXIT;
	END_IF;
END_FOR;

IF Act.Act09_AlmAndMesg[2] THEN MyStation.EM[2].IsAlarm:= Search_Alarm(H_Messages.Station[2].Object_Alarm) OR H_Messages.Station[2].Alarm; (********************报警信息********************) //SV05刻码移栽X轴报警 H_Messages.Station[2].Object_Alarm[0] := EM02V.Axis_X1.Out.Alarm; //EM02刻码拉带模组:SV05刻码移栽X轴驱动器发生错误 H_Messages.Station[2].Object_Alarm[1] := EM02V.Axis_X1.Out.Alarm_Out[0]; //EM02刻码拉带模组:SV05刻码移栽X轴驱动器通讯故障报警 H_Messages.Station[2].Object_Alarm[2] := EM02V.Axis_X1.Out.Alarm_Out[1]; //EM02刻码拉带模组:SV05刻码移栽X轴轴故障报警 H_Messages.Station[2].Object_Alarm[3] := EM02V.Axis_X1.Out.Alarm_Out[2]; //EM02刻码拉带模组:SV05刻码移栽X轴回原安全条件不满足报警 H_Messages.Station[2].Object_Alarm[4] := EM02V.Axis_X1.Out.Alarm_Out[3]; //EM02刻码拉带模组:SV05刻码移栽X轴回原中原点或负限位异常 H_Messages.Station[2].Object_Alarm[5] := EM02V.Axis_X1.Out.Alarm_Out[4]; //EM02刻码拉带模组:SV05刻码移栽X轴轴运动安全条件不满足报警 H_Messages.Station[2].Object_Alarm[6] := EM02V.Axis_X1.Out.Alarm_Out[5]; //EM02刻码拉带模组:SV05刻码移栽X轴扭矩当前值超过阈值报警 H_Messages.Station[2].Object_Alarm[7] := EM02V.Axis_X1.Out.Alarm_Out[6]; //EM02刻码拉带模组:SV05刻码移栽X轴柔性回弹报警 H_Messages.Station[2].Object_Alarm[8] := EM02V.Axis_X1.Out.Alarm_Out[7]; //EM02刻码拉带模组:SV05刻码移栽X轴正限位开关报警 H_Messages.Station[2].Object_Alarm[9] := EM02V.Axis_X1.Out.Alarm_Out[8]; //EM02刻码拉带模组:SV05刻码移栽X轴负限位开关报警 H_Messages.Station[2].Object_Alarm[10] := EM02V.Axis_X1.Out.Alarm_Out[9]; //EM02刻码拉带模组:SV05刻码移栽X轴未使能报警 //SV06刻码翻转R轴报警 H_Messages.Station[2].Object_Alarm[11] := EM02V.Axis_R1.Out.Alarm; //EM02刻码拉带模组:SV06刻码翻转R轴驱动器发生错误 H_Messages.Station[2].Object_Alarm[12] := EM02V.Axis_R1.Out.Alarm_Out[0]; //EM02刻码拉带模组:SV06刻码翻转R轴驱动器通讯故障报警 H_Messages.Station[2].Object_Alarm[13] := EM02V.Axis_R1.Out.Alarm_Out[1]; //EM02刻码拉带模组:SV06刻码翻转R轴轴故障报警 H_Messages.Station[2].Object_Alarm[14] := EM02V.Axis_R1.Out.Alarm_Out[2]; //EM02刻码拉带模组:SV06刻码翻转R轴回原安全条件不满足报警 H_Messages.Station[2].Object_Alarm[15] := EM02V.Axis_R1.Out.Alarm_Out[3]; //EM02刻码拉带模组:SV06刻码翻转R轴回原中原点或负限位异常 H_Messages.Station[2].Object_Alarm[16] := EM02V.Axis_R1.Out.Alarm_Out[4]; //EM02刻码拉带模组:SV06刻码翻转R轴轴运动安全条件不满