THEN H_Messages.Station[2].Alarm := TRUE ; // 工位自定义报警汇总 ELSIF MyInput.Reset_Input THEN H_Messages.Station[2].Alarm := FALSE ; // 工位自定义报警汇总 END_IF; //(******************* 复位自定义报警 *************************************) IF MyInput.Reset_Input THEN Clear(H_Messages.Station[2].User_Alarm); H_Messages.Station[2].Alarm := FALSE ; // 工位自定义报警汇总 END_IF;

