//EM02刻码拉带模组：SV07_刻码升降Z轴运动干涉，未检测到刻码下料机器人在取料区域安全信号 IF (EM02V.Axis_Z1.In.Location_Select_HMI[0] // EM02刻码拉带模组SV07刻码升降Z轴定位0触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[1] // EM02刻码拉带模组SV07刻码升降Z轴定位1触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[2] // EM02刻码拉带模组SV07刻码升降Z轴定位2触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[3] // EM02刻码拉带模组SV07刻码升降Z轴定位3触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[4] // EM02刻码拉带模组SV07刻码升降Z轴定位4触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[5] // EM02刻码拉带模组SV07刻码升降Z轴定位5触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[6] // EM02刻码拉带模组SV07刻码升降Z轴定位6触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[7] // EM02刻码拉带模组SV07刻码升降Z轴定位7触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[8] // EM02刻码拉带模组SV07刻码升降Z轴定位8触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[9] // EM02刻码拉带模组SV07刻码升降Z轴定位9触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[10]) // EM02刻码拉带模组SV07刻码升降Z轴定位10触发 AND EM02V.Axis_Z1.In.Location_Move_HMI AND NOT HMI_SafetyCondition_Enable AND NOT MyStation.EM[3].Shielding AND NOT EM03V.Robot1_SafetySignal_ToEM02 THEN H_Messages.Station[2].HinderToPos[2,1] :=TRUE;//EM02刻码拉带模组：SV07_刻码升降Z轴运动干涉，未检测到刻码下料机器人在取料区域安全信号 HMI_EQ.ConflictPopups:=TRUE; END_IF;
IF (EM02V.Axis_Z1.In.Location_Select_HMI[2] // EM02刻码拉带模组SV07刻码升降Z轴定位2触发 OR EM02V.Axis_Z1.In.Location_Select_HMI[3]) // EM02刻码拉带模组SV07刻码升降Z轴定位3触发 AND EM02V.Axis_Z1.In.Location_Move_HMI AND NOT HMI_SafetyCondition_Enable AND NOT EM02V.X1_SafetySignal THEN H_Messages.Station[2].HinderToPos[2,2] :=TRUE;//EM02刻码拉带模组：SV07_刻码升降Z轴运动干涉，SV05_刻码移栽X轴不在工位上 HMI_EQ.ConflictPopups:=TRUE; END_IF;
// EM02刻码拉带模组:手自动冲突 IF NOT Signal_ResetCompleteRT AND MyInput.Start_Input AND NOT MyStation.EM[2].Shielding AND MyStation.EM[2].Conflict THEN H_Messages.Station[2].HinderToPos[25,0] := TRUE ;// EM02刻码拉带模组:手自动冲突 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 IF EM02V.Axis_X1.Out.Tips_Out[5] THEN H_Messages.Station[2].HinderToPos[25,1] := TRUE ;// EM02刻码拉带模组:SV05_刻码移栽X轴-手自动冲突 END_IF IF EM02V.Axis_R1.Out.Tips_Out[5] THEN H_Messages.Station[2].HinderToPos[25,2] := TRUE ;// EM02刻码拉带模组:SV06_刻码翻转R轴-手自动冲突 END_IF IF EM02V.Axis_Z1.Out.Tips_Out[5] THEN H_Messages.Station[2].HinderToPos[25,3] := TRUE ;// EM02刻码拉带模组:SV07_刻码升降Z轴-手自动冲突 END_IF IF EM02V.Cy_Up1.Out.Tips_Out[3] THEN H_Messages.Station[2].HinderToPos[25,4] := TRUE ;// EM02刻码拉带模组:刻码除尘避让气缸-手自动冲突 END_IF IF EM02V.Cy_Clamp1.Out.Tips_Out[3] THEN H_Messages.Station[2].HinderToPos[25,5] := TRUE ;// EM02刻码拉带模组:顶盖夹爪气缸1-手自动冲突 END_IF IF EM02V.Cy_Clamp2.Out.Tips_Out[3] THEN H_Messages.Station[2].HinderToPos[25,6] := TRUE ;// EM02刻码拉带模组:顶盖夹爪气缸2-手自动冲突 END_IF END_IF;
(*关闭弹框消除提示*) IF NOT HMI_EQ.ConflictPopups AND NOT H_Messages.ConflictPopups THEN Clear(H_Messages.Station[2].HinderToPos); END_IF;

(******************************************** 批次码扫码枪 *********************************************)
//使能
EM02H_ScanCode[0].H_In.Enable := NOT HMI_Function_Enable[2,0];
//连续NG次数
EM02P.ScanCode1.NGTimesMax:=0;
//IP节点地址
EM02P.ScanCode1.IP_Node:=71;
//工位编号
EM02V.ScanCode1.In.StationNo:=1;

// ScanCode1(
// 	Reset						:=MyInput.Reset_Input								,//复位
// 	Auto							:=MyStatus.StatusAuto								,//自动
// 	Manual					:=MyStatus.StatusManual							,//手动
// 	In								:=EM02V.ScanCode1.In								,//程序输入
// 	H_In							:=EM02H_ScanCode[0].H_In						,//HMI输入
// 	H_Out						:=EM02H_ScanCode[0].H_Out						,//HMI输出
// 	Out							=>EM02V.ScanCode1.Out							,//程序输出
// 	ErrOut						=>EM02V.ScanCode1.ErrOut						,//程序错误
// 	Parameter				:=EM02P.ScanCode1									,//参数设置
// 	SR_To_PLC_Data		:=EM02ScanCode1_EIP.In								,//EIP输入
// 	PLC_To_SR_Data		:=EM02ScanCode1_EIP.Out							//EIP输出
// 	);
	
ScanCode1(
	Reset						:=MyInput.Reset_Input								,//复位
	Auto							:=MyStatus.StatusAuto								,//自动
	Manual					:=MyStatus.StatusManual							,//手动
	In								:=EM02V.ScanCode1.In								,//程序输入
	H_In							:=EM02H_ScanCode[0].H_In						,//HMI输入
	H_Out						:=EM02H_ScanCode[0].H_Out						,//HMI输出
	Out							=>EM02V.ScanCode1.Out							,//程序输出
	ErrOut						=>EM02V.ScanCode1.ErrOut						,//程序错误
	Parameter				:=EM02P.ScanCode1									,//参数设置
	SR_To_PLC_Data		:=EM02ScanCode1_EIPIn								,//EIP输入
	PLC_To_SR_Data		:=EM02ScanCode1_EIPOut							//EIP输出
	);

(******************************************** 刻码条码扫码枪 *********************************************)
//使能
EM02H_ScanCode[1].H_In.Enable:=NOT HMI_Function_Enable[2,2];
//连续NG次数
EM02P.ScanCode2.NGTimesMax:=0;
//IP节点地址
EM02P.ScanCode2.IP_Node:=74;
//工位编号
EM02V.ScanCode2.In.StationNo:=1;

ScanCode2(
	Reset						:=MyInput.Reset_Input								,//复位
	Auto							:=MyStatus.StatusAuto								,//自动
	Manual					:=MyStatus.StatusManual							,//手动
	In								:=EM02V.ScanCode2.In								,//程序输入
	H_In							:=EM02H_ScanCode[1].H_In						,//HMI输入
	H_Out						:=EM02H_ScanCode[1].H_Out						,//HMI输出
	Out							=>EM02V.ScanCode2.Out							,//程序输出
	ErrOut						=>EM02V.ScanCode2.ErrOut						,//程序错误
	Parameter				:=EM02P.ScanCode2									,//参数设置
	SR_To_PLC_Data		:=EM02ScanCode2_EIPIn								,//EIP输入
	PLC_To_SR_Data		:=EM02ScanCode2_EIPOut							//EIP输出
	);

(******************************************** 顶盖板链线治具码扫码枪 *********************************************)
//使能
EM02H_ScanCode[2].H_In.Enable:=NOT HMI_Function_Enable[2,3];
//连续NG次数
EM02P.ScanCode3.NGTimesMax:=0;
//IP节点地址
EM02P.ScanCode3.IP_Node:=73;
//工位编号
EM02V.ScanCode3.In.StationNo:=1;

ScanCode3(
	Reset						:=MyInput.Reset_Input								,//复位
	Auto							:=MyStatus.StatusAuto								,//自动
	Manual					:=MyStatus.StatusManual							,//手动
	In								:=EM02V.ScanCode3.In								,//程序输入
	H_In							:=EM02H_ScanCode[2].H_In						,//HMI输入
	H_Out						:=EM02H_ScanCode[2].H_Out						,//HMI输出
	Out							=>EM02V.ScanCode3.Out							,//程序输出
	ErrOut						=>EM02V.ScanCode3.ErrOut						,//程序错误
	Parameter				:=EM02P.ScanCode3									,//参数设置
	SR_To_PLC_Data		:=EM02ScanCode3_EIPIn								,//EIP输入
	PLC_To_SR_Data		:=EM02ScanCode3_EIPOut							//EIP输出
	);

