(********************************************TCP功能块调用 *********************************************)
//StringToAry(IN:= TCP_CoverLaser.sSendData, AryOut:= TCP_CoverLaser.bySendData[0], Out=> sSendDataSize); CoverLaserTCP( ServerSelect:= TCP_CoverLaser.ServerSelect ,// FALSE为客户端 ConnectID:= 2 ,//链接句柄 sHost:= TCP_CoverLaser.sHost ,// 客户端需填IP地址 nPort:= TCP_CoverLaser.nPort ,// 端口号 bEnable:= TCP_CoverLaser.bEnable ,// 功能块使能 bReset:= TCP_CoverLaser.bReset ,// 复位 sSendData:= TCP_CoverLaser.sSendData ,// 发送数据 bySendData:= TCP_CoverLaser.sSendData_AryByte ,// 发送数据 bSendExecute:= TCP_CoverLaser.bSendExecute ,// 发送触发 bConnected=> TCP_CoverLaser.bConnected ,// 链接标志 bSendDone=> TCP_CoverLaser.bSendDone ,// 发送完成 sReadData=> TCP_CoverLaser.sReadData ,// 接收数据(Byte) bReadDone=>TCP_CoverLaser.bReadDone ,// 接收完成 bConnectedErr =>TCP_CoverLaser.bConnectedErr ,// 连接错误 bBusy =>TCP_CoverLaser.bBusy ,// 忙碌 bError =>TCP_CoverLaser.bError ,// 错误 nErrorID =>TCP_CoverLaser.nErrorID // 错误ID );
//配置 TCP_CoverLaser.ServerSelect := FALSE ;// FALSE为客户端 TCP_CoverLaser.sHost :='192.168.0.208';// IP地址 TCP_CoverLaser.nPort := 8006 ;// 端口号
//客服端掉线,服务器使能复位 IF TCP_CoverLaser.bError OR TCP_CoverLaser.bConnectedErr OR HMI_Function_Enable[2,1] THEN TCP_CoverLaser.bEnable := FALSE ; ELSIF NOT TCP_CoverLaser.bError AND NOT TCP_CoverLaser.bConnectedErr AND NOT HMI_Function_Enable[2,1] AND TCP_Dly.Q THEN TCP_CoverLaser.bEnable := TRUE ; END_IF;
TCP_Dly(IN:= NOT HMI_Function_Enable[2,1] , PT:= T#1S);//防止两个TCP同时触发连接

(********************************************	检测流程		*********************************************)
TON_Check1(In:=Check1Step>0, PT:=T#10S);
CASE Check1Step	OF
	0://流程开始
		IF Act.Act05_Auto_Station[2,0]
			AND Check1Start
		THEN
			//清除交互信号
			Catl_CcdData.PlcToCcd_Int[12]:=0;
			Catl_CcdData.CcdToPlc_Int[10]:=0;
			Check1Step:=10;
		END_IF;
	10://检测触发
		Catl_CcdBar.PlcToCcd_String[16]:=Cell_Info[2,5].CodeSN;
		Catl_CcdData.PlcToCcd_Int[12]:=1;
		Check1Step:=20;
	20://判断检测结果
		IF Catl_CcdData.CcdToPlc_Int[10]=2//检测OK
			OR HMI_TestMode_Enable//空机模式
			OR HMI_Function_Enable[2,10]//检测功能未启用
		THEN
			Cell_Info[2,5].Quality:=100;
			EngraveCodeOffsetNGNum1:=0;
			Check1Step:=30;
		ELSIF Catl_CcdData.CcdToPlc_Int[10]=3//检测NG
// 		      OR ( Catl_CcdBar.PlcToCcd_String[16] ='' AND 
// 			  NOT HMI_Function_Enable[2,10]  )
		THEN
			Cell_Info[2,5].Quality:=43;
			EngraveCodeOffsetNGNum1:=EngraveCodeOffsetNGNum1+1;
			Check1Step:=30;
		ELSIF TON_Check1.Q
		THEN
			H_Messages.Station[2].User_Alarm[49]:=TRUE;//EM02刻码拉带模组：等待刻码偏移量检测CCD返回检测结果超时，请打开CCD软件查看原因！
			Check1Step:=30;
		END_IF;
	30://流程结束
		Check1Start:=FALSE;
		Catl_CcdData.PlcToCcd_Int[12]:=0;
		Catl_CcdData.CcdToPlc_Int[10]:=0;
		Check1Step:=0;
END_CASE;

R_Check1(Clk:=HMI_Button[2,4]);
F_Check1(Clk:=HMI_Button[2,4]);

//1#检测触发
IF R_Check1.Q THEN
	Catl_CcdBar.PlcToCcd_String[16]:='1#CoverHymson0123456789';
	Catl_CcdData.PlcToCcd_Int[12]:=1;
	Catl_CcdData.CcdToPlc_Int[10]:=0;
END_IF;
IF F_Check1.Q THEN
	Catl_CcdData.PlcToCcd_Int[12]:=0;
END_IF;

FOR StationSum := 0 TO StationNum BY 1 DO
	Act.Act05_Auto_Station[EMNumber,StationSum] := Act.Act05_Auto[EMNumber] AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding;
END_FOR;

(********************************************	顶盖刻码结果	*********************************************)
//清除上一次数据
R_EngraveCodeExcute(Clk:=Catl_MesData.PlcToPc_Int[0]=1);
IF R_EngraveCodeExcute.Q THEN
	Catl_MesData.PcToPlc_Real[0]:=0;
	Catl_MesData.PcToPlc_Real[1]:=0;
	Catl_MesData.PcToPlc_Real[2]:=0;
	Clear(Catl_MesBar.PcToPlc_String[6]);
	Clear(Catl_MesBar.PcToPlc_String[8]);
END_IF;
//刻码流程计时
TON_EngraveCode1(In:=Catl_MesData.PlcToPc_Int[0]=1, PT:=T#10S);
IF Catl_MesData.PlcToPc_Int[0]=1 THEN
	HC_OmronUtils.TimeToNanoSec(In:=TON_EngraveCode1.ET/1000000 , Out=>EngraveCodeTime_LINT );
	EM02V.EngraveCodeTime:=LINT_TO_REAL(EngraveCodeTime_LINT) ;
END_IF;

IF Catl_MesData.PlcToPc_Int[0]=100//刻码OK
	OR Catl_MesData.PlcToPc_Int[0]=50//刻码条码中存在WM字符
THEN
	//=========================================
	//记忆传递
	IF Cell_Info[2,3].Quality=70
		AND EM02V.Process_steps[1]=120
	THEN
		Cell_Info[2,3].Quality:=80;//刻码OK
		Cell_Info[2,3].EngraveCodeResult:=1;//刻码结果：1/OK,2/NG
		Cell_Info[2,3].EngraveCodeWindSpeed:=EM02V.EngraveCodeWindSpeed1;//刻码除尘风速
		Cell_Info[2,3].EngraveCodeTime:=EM02V.EngraveCodeTime;//刻码时间
		Cell_Info[2,3].EngraveCodeOffsetXValue:=Catl_MesData.PcToPlc_Real[0];//刻码X方向偏移量
		Cell_Info[2,3].EngraveCodeOffsetYValue:=Catl_MesData.PcToPlc_Real[1];//刻码Y方向偏移量
		Cell_Info[2,3].EngraveCodeOffsetRValue:=Catl_MesData.PcToPlc_Real[2];//刻码R方向偏移量
		Cell_Info[2,3].MICode:=Catl_MesBar.PcToPlc_String[6];//MI条码
		Cell_Info[2,3].CodeSNBuffer:=Catl_MesBar.PcToPlc_String[8];//顶盖刻码条码(上位机)
	END_IF;
	EngraveCodeNGNum1:=0;//连续NG清零
	
	//=========================================
	//50 刻码条码中存在WM字符
	IF Catl_MesData.PlcToPc_Int[0]=50
	THEN
		H_Messages.Station[2].User_Alarm[53]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码条码中存在WM字符，请检查刻码条码字符是否重叠；
	END_IF;
	
	//=========================================
	//MI条码空字符检查
	IF NOT HMI_Function_Enable[2,9]
		AND LEN(Catl_MesBar.PcToPlc_String[6])=0
	THEN
		H_Messages.Station[2].User_Alarm[0]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码结果OK，但返回的MI条码是空字符，请检查上位机软件是否出错！
	END_IF;
	//MI条码规则校验
	IF NOT HMI_Function_Enable[2,9]
		AND Catl_MesBar.PcToPlc_String[6]<>HMI_RecipeData.MICodeCheck
	THEN
		H_Messages.Station[2].User_Alarm[1]:=TRUE;//EM02刻码拉带模组：顶盖刻码MI条码规则校验错误，请检查刻码MI条码规则，或触摸屏刻码MI条码规则是否设置错误！
	END_IF;

	//=========================================
	//返回的刻码条码空字符检查
	IF LEN(Catl_MesBar.PcToPlc_String[8])=0
	THEN
		H_Messages.Station[2].User_Alarm[2]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码结果OK，但返回的顶盖刻码条码是空字符，请检查上位机软件是否出错！
	END_IF;
	
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[0]:=0;
	
ELSIF Catl_MesData.PlcToPc_Int[0]=35//NG
	OR Catl_MesData.PlcToPc_Int[0]=40//拍照定位失败
	OR Catl_MesData.PlcToPc_Int[0]=45//跳码失败
	OR TON_EngraveCode1.Q//流程长时间未响应
THEN
	//=========================================
	//记忆传递
	IF Cell_Info[2,3].Quality=70
		AND EM02V.Process_steps[1]=120
	THEN
		Cell_Info[2,3].Quality:=40;//刻码NG
		Cell_Info[2,3].EngraveCodeResult:=2;//刻码结果：1/OK,2/NG
		Cell_Info[2,3].EngraveCodeWindSpeed:=EM02V.EngraveCodeWindSpeed1;//刻码除尘风速
		Cell_Info[2,3].EngraveCodeTime:=EM02V.EngraveCodeTime;//刻码时间
		Cell_Info[2,3].EngraveCodeOffsetXValue:=Catl_MesData.PcToPlc_Real[0];//刻码X方向偏移量
		Cell_Info[2,3].EngraveCodeOffsetYValue:=Catl_MesData.PcToPlc_Real[1];//刻码Y方向偏移量
		Cell_Info[2,3].EngraveCodeOffsetRValue:=Catl_MesData.PcToPlc_Real[2];//刻码R方向偏移量
		Cell_Info[2,3].MICode:=Catl_MesBar.PcToPlc_String[6];//MI条码
		Cell_Info[2,3].CodeSNBuffer:=Catl_MesBar.PcToPlc_String[8];//顶盖刻码条码(上位机)
	END_IF;
	
	//=========================================
	//40 拍照定位失败
	IF Catl_MesData.PlcToPc_Int[0]=40
	THEN
		H_Messages.Station[2].User_Alarm[3]:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码拍照定位失败，请打开上位机软件检查刻码功能；
	END_IF;
	
	//=========================================
	//45 跳码失败
	IF Catl_MesData.PlcToPc_Int[0]=45
	THEN
		EngraveCodeRefreshErr1:=TRUE;//EM02刻码拉带模组：上位机反馈顶盖刻码跳码失败，请打开上位机软件检查刻码功能；
	END_IF;
	//=========================================
	//流程长时间未响应
	IF TON_EngraveCode1.Q
	THEN
		MyStation.EM[2].ResetComplete:=FALSE;//需要重新初始化模组
		H_Messages.Station[2].User_Alarm[5]:=TRUE;//EM02刻码拉带模组：等待上位机反馈顶盖刻码完成，流程长时间未响应，请打开上位机软件检查刻码功能；
	END_IF;
	EngraveCodeNGNum1:=EngraveCodeNGNum1+1;//连续NG+1
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[0]:=0;

END_IF;

(********************************************	手动刻码		*********************************************)
//激光刻码触发
R_EngraveCode1(Clk:=HMI_Button[2,2]);

IF NOT MyStatus.StatusManual
THEN
	HMI_Button[2,2]:=FALSE;
ELSIF R_EngraveCode1.Q
	AND EM02V.Axis_InPlace_Flag
	AND EM02V.Sen_HaveCover4.Out.Filtered_Q
	AND MyStatus.StatusManual
THEN
	IF Catl_MesData.PlcToPc_Int[0]<>0
	THEN
		Catl_MesData.PlcToPc_Int[0]:=0;
	ELSIF Catl_MesData.PlcToPc_Int[0]=0
	THEN
		Catl_MesData.PlcToPc_Int[0]:=1;
	END_IF;
ELSIF R_EngraveCode1.Q
THEN
	H_Messages.Station[2].User_Alarm[6]:=TRUE;//EM02刻码拉带模组：激光刻码手动触发，但是检测到刻码位无顶盖或移栽X轴不在工位上，禁止触发激光刻码；
END_IF;

//激光刻码中
HMI_Button[2,3]:=Catl_MesData.PlcToPc_Int[0]=1;

//上料位 EM08V.Done[0]:=Cell_Info[8,0].Quality<>0 AND Cell_Info[8,0].CellLineJigScanFinish OR AutoClearCell.Q OR (MyStation.EM[7].Shielding AND HMI_TestMode_Enable); //除尘位 EM08V.Done[1]:=(HMI_Function_Enable[9,0] AND (Cell_Info[8,1].Quality=100 AND Cell_Info[8,1].WeldSealClearFinish OR Cell_Info[8,1].Quality<>100)) OR (NOT HMI_Function_Enable[9,0] AND (Cell_Info[8,1].Quality>=20 AND Cell_Info[8,1].WeldSealClearFinish OR Cell_Info[8,1].Quality<20)) OR MyStation.EM[9].Shielding; //焊印检测位 EM08V.Done[2]:=(HMI_Function_Enable[8,2] AND (Cell_Info[8,2].Quality=100 AND Cell_Info[8,2].WeldSeal2DFinish OR Cell_Info[8,2].Quality<>100)) OR (NOT HMI_Function_Enable[8,2] AND (Cell_Info[8,2].Quality>=20 AND Cell_Info[8,2].WeldSeal2DFinish OR Cell_Info[8,2].Quality<20)) OR ( Cell_Info[8,2].Quality<> 0 AND Cell_Info[8,2].SampleProductFlag ); //极耳检测位 EM08V.Done[3]:=(HMI_Function_Enable[8,5] AND (Cell_Info[8,3].Quality=100 AND Cell_Info[8,3].WeldSealTearFinish OR Cell_Info[8,3].Quality<>100)) OR (NOT HMI_Function_Enable[8,5] AND (Cell_Info[8,3].Quality>=20 AND Cell_Info[8,3].WeldSealTearFinish OR Cell_Info[8,3].Quality<20)) OR ( Cell_Info[8,3].Quality<> 0 AND Cell_Info[8,3].SampleProductFlag ); //点胶位 EM08V.Done[4]:=(HMI_Function_Enable[10,2] AND (Cell_Info[8,4].Quality=100 AND Cell_Info[8,4].WeldSealSprayGlue OR Cell_Info[8,4].Quality<>100)) OR (NOT HMI_Function_Enable[10,2] AND (Cell_Info[8,4].Quality>=20 AND Cell_Info[8,4].WeldSealSprayGlue OR Cell_Info[8,4].Quality<20)) OR ( Cell_Info[8,4].Quality<> 0 AND Cell_Info[8,4].SampleProductFlag ) OR MyStation.EM[10].Shielding //OR ( HMI_TestMode_Enable AND Cell_Info[8,4].Quality = 100 ) ; //焊印点胶检测位 EM08V.Done[5]:=(HMI_Function_Enable[8,17] AND (Cell_Info[8,5].Quality=100 AND Cell_Info[8,5].WeldSealCoverOffset OR Cell_Info[8,5].Quality<>100)) OR (NOT HMI_Function_Enable[8,17] AND (Cell_Info[8,5].Quality>=20 AND Cell_Info[8,5].WeldSealCoverOffset OR Cell_Info[8,5].Quality<20)) OR ( Cell_Info[8,5].Quality<> 0 AND Cell_Info[8,5].SampleProductFlag ); //贴胶位 EM08V.Done[6]:=(HMI_Function_Enable[11,0] AND (Cell_Info[8,6].Quality=100 AND Cell_Info[8,6].WeldSealGlue OR Cell_Info[8,6].Quality<>100)) OR (NOT HMI_Function_Enable[11,0] AND (Cell_Info[8,6].Quality>=20 AND Cell_Info[8,6].WeldSealGlue OR Cell_Info[8,6].Quality<20)) OR ( Cell_Info[8,6].Quality<> 0 AND Cell_Info[8,6].SampleProductFlag ) OR MyStation.EM[11].Shielding; //焊印胶检测位（PET胶） EM08V.Done[7]:=(HMI_Function_Enable[8,8] AND (Cell_Info[8,7].Quality=100 AND Cell_Info[8,7].WeldSealGlueFinish OR Cell_Info[8,7].Quality<>100)) OR (NOT HMI_Function_Enable[8,8] AND (Cell_Info[8,7].Quality>=20 AND Cell_Info[8,7].WeldSealGlueFinish OR Cell_Info[8,7].Quality<20)) OR ( Cell_Info[8,7].Quality<> 0 AND Cell_Info[8,7].SampleProductFlag ); //扣支架位-取消 EM08V.Done[8]:=(HMI_Function_Enable[12,0] AND (Cell_Info[8,8].Quality=100 AND Cell_Info[8,8].WeldSealSupport OR Cell_Info[8,8].Quality<>100)) OR (NOT HMI_Function_Enable[12,0] AND (Cell_Info[8,8].Quality>=20 AND Cell_Info[8,8].WeldSealSupport OR Cell_Info[8,8].Quality<20)) OR MyStation.EM[12].Shielding OR TRUE; //扣支架检测位-取消 EM08V.Done[9]:=(HMI_Function_Enable[8,11] AND (Cell_Info[8,9].Quality=100 AND Cell_Info[8,9].WeldSealSupportFinish OR Cell_Info[8,9].Quality<>100)) OR (NOT HMI_Function_Enable[8,11] AND (Cell_Info[8,9].Quality>=20 AND Cell_Info[8,9].WeldSealSupportFinish OR Cell_Info[8,9].Quality<20)) OR TRUE; //下料位 EM08V.Done[10]:=Cell_Info[8,10].Quality=0 OR MyStation.EM[13].Shielding AND HMI_TestMode_Enable;
//自动清料条件计时 AutoClearCell_Condition( In:=Act.Act05_Auto_Station[8,0] AND (Cell_Info[5,1].Quality=70 OR CEll_Info[5,1].Quality = 0 ) AND (Cell_Info[5,2].Quality=70 OR CEll_Info[5,2].Quality = 0 ) AND (Cell_Info[5,3].Quality=70 OR CEll_Info[5,3].Quality = 0 ) AND (Cell_Info[5,4].Quality=70 OR CEll_Info[5,4].Quality = 0 ) AND (Cell_Info[5,5].Quality=70 OR CEll_Info[5,5].Quality = 0 ) AND (Cell_Info[5,6].Quality=70 OR CEll_Info[5,6].Quality = 0 ) AND (Cell_Info[5,7].Quality=70 OR CEll_Info[5,7].Quality = 0 ) AND (Cell_Info[5,8].Quality=70 OR CEll_Info[5,8].Quality = 0 ) AND (Cell_Info[5,9].Quality=70 OR CEll_Info[5,9].Quality = 0 ) AND (Cell_Info[5,10].Quality=70 OR CEll_Info[5,10].Quality = 0 ) AND Cell_Info[7,0].Quality=0 AND Cell_Info[8,0].Quality=0 AND NOT HMI_Button[8,1] , PT:=T#5S);
//自动清料计时 AutoClearCell( In:=AutoClearCell_Condition.Q AND (Cell_Info[8,1].Quality<>0 OR Cell_Info[8,2].Quality<>0 OR Cell_Info[8,3].Quality<>0 OR Cell_Info[8,4].Quality<>0 OR Cell_Info[8,5].Quality<>0 OR Cell_Info[8,6].Quality<>0 OR Cell_Info[8,7].Quality<>0 //OR Cell_Info[8,8].Quality<>0 //OR Cell_Info[8,9].Quality<>0 ) AND Cell_Info[8,10].Quality=0 AND NOT EM08V.Done[0] AND EM08V.Done[1] AND EM08V.Done[2] AND EM08V.Done[3] AND EM08V.Done[4] AND EM08V.Done[5] AND EM08V.Done[6] AND EM08V.Done[7] //AND EM08V.Done[8] //AND EM08V.Done[9] AND EM08V.Done[10] AND EM08V.MovingAllow[0] , PT:=T#2S);
//工位完成状态显示 EM08P.Done:=EM08V.Done;

(********************************************	治具屏蔽		*********************************************)
FOR i:=1 TO 18  DO
	IF EM08P.VehicleShielding[i]
		AND EM08V.Axis_X1.Out.PosDone[i]
		AND Cell_Info[8,0].Quality=0
	THEN
		Cell_Info[8,0].Quality:=1;
	END_IF;
END_FOR;

(********************************************	人工上料		*********************************************)
F_Button(Clk:=HMI_Button[8,1]);
IF F_Button.Q
	AND Cell_Info[8,0].Quality=0
	AND NOT HMI_TestMode_Enable
THEN
	Cell_Info[8,0].CodeSN:='TEST12345678';
	Cell_Info[8,0].BettarySN:='TEST12345678';
	Cell_Info[8,0].Quality:=100;
END_IF;

(*****************************EM08_下料拉带模组状态机*****************************) 

EMNumber := 8;//模组编号
StationNum :=1-1 ;//工位数量--数组编号最大为0..9

Act.Act01_Status[8]:=TRUE;//工位状态机程序
Act.Act02_Condition[8]:=TRUE;//循环扫描程序
//手动动运行程序
Act.Act03_Manual[8]:=  MyStatus.StatusManual;	
//初始化程序
MyStation.EM[8].Resting:=Act.Act04_Init[8];
//自动运行程序			
MyStation.EM[8].Running:=Act.Act05_Auto[8];										
//功能块调用程序						 
Act.Act06_IOCall_FB[8]:=TRUE;
//轴功能块调用程序						 
Act.Act07_AxisCall_FB[8]:=TRUE;
//通讯程序						 
Act.Act08_Communication[8]:=TRUE;
//报警信息程序						 
Act.Act09_AlmAndMesg[8]:=NOT MyStation.EM[8].Shielding
					AND MyStation.EmgStop
					AND MyStation.SafetyDoor
					AND MyStation.SafetyRaster;


FOR StationSum := 0 TO StationNum BY 1 DO
//功能状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowAuto		:=	Act.Act05_Auto_Station[EMNumber,StationSum] OR Act.Act04_Init_Station[EMNumber,StationSum]					;//自动状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowManual	:=	Act.Act03_Manual[EMNumber]																		;//手动状态
Act.Act10_Call_Status[EMNumber,StationSum].AlarmReset	:=	MyInput.Reset_Input																		;//复位状态
Act.Act10_Call_Status[EMNumber,StationSum].Aborting		:= NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor				;//急停中止
Act.Act10_Call_Status[EMNumber,StationSum].StopCmd		:=	MyStation.EM[EMNumber].Stopping	AND NOT MyStation.EM[EMNumber].Resting		;//停止
Act.Act10_Call_Status[EMNumber,StationSum].DoorAborting:=	NOT MyStation.EmgStop	OR NOT MyStation.SafetyDoor				;//门禁中止																		
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[1]	:= MyStation.ProductionMode															;//生产模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[2]	:= MyStation.MaintenanceMode														;//维护模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[3]	:= Act.Act04_Init_Station[EMNumber,StationSum];//初始化模式												
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[4] 	:= Act.Act03_Manual[EMNumber];//手动模式									
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[5] 	:= MyStation.MaintenanceMode;//维修模式			
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[0]	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[1]	:= NOT	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //未复
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[2]	:=	MyStation.EMStation[EMNumber,StationSum].Resting;  //复位中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[3]	:=	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //复位完成
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[4]	:=	Device_Starting;  //自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[5]	:=	Device_Starting;  //单步自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[6]	:=	MyStation.EM[EMNumber].Stopping;  //暂停中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[7]	:=	NOT MyStation.SafetyDoor AND FALSE;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[8]	:=	NOT MyStation.EmgStop;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].AlarmShield	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
END_FOR;


Act.Act10_Call_Status[EMNumber,0].AllowAuto:=Act.Act10_Call_Status[EMNumber,1].AllowAuto OR	Act.Act10_Call_Status[EMNumber,1].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,2].AllowAuto OR	Act.Act10_Call_Status[EMNumber,3].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,4].AllowAuto OR	Act.Act10_Call_Status[EMNumber,5].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,6].AllowAuto OR	Act.Act10_Call_Status[EMNumber,7].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,8].AllowAuto OR	Act.Act10_Call_Status[EMNumber,9].AllowAuto
																				OR	(Act.Act05_Auto_Station[EMNumber,0] OR Act.Act04_Init_Station[EMNumber,0]);

//--------------输入-----------------------------------//
usiEM01Index:=USINT#11;//工位号
bEM01_Start:=EM08V.Process_steps[0]=140;//计时开始									
bEM01_Stop:=NOT (EM08V.Process_steps[4]=110);//计时结束
bEM01_Run:=Act.Act05_Auto_Station[8,0];//工位自动									
														
abEM01ActionStart[1] :=EM08V.Process_steps[0]=140; //1.链板到位			
abEM01ActionDone[1]	 :=EM08V.Process_steps[0]=0; 
ausiEM01ActionParallelNum[1]:=0;
abEM01ActionStart[2] :=EM08V.Process_steps[1]=110; //2.焊印CCD检测	
abEM01ActionDone[2]	 :=EM08V.Process_steps[1]=0; 
ausiEM01ActionParallelNum[2]:=2;
abEM01ActionStart[3] :=EM08V.Process_steps[2]=110; //3.极耳CCD检测			
abEM01ActionDone[3]	 :=EM08V.Process_steps[2]=0; 
ausiEM01ActionParallelNum[3]:=2;
abEM01ActionStart[4] :=EM08V.Process_steps[3]=110; //4.焊印胶CCD检测	
abEM01ActionDone[4]	 :=EM08V.Process_steps[3]=0; 
ausiEM01ActionParallelNum[4]:=2;
abEM01ActionStart[5] :=EM08V.Process_steps[4]=110; //5.点胶CCD检测			
abEM01ActionDone[5]	 :=EM08V.Process_steps[4]=0; 
ausiEM01ActionParallelNum[5]:=2;

//最多62个动作	

//--------------计时-----------------------------------//	
//计时结束 把工位总时间存储进63步									
rtgEM01_Stop(CLK:=bEM01_Stop);									
IF rtgEM01_Stop.Q AND bEM01TimerStart THEN 									
	bEM01TimerStart:=FALSE;	
	FOR uiIndex:=1 TO 62 BY 1 DO															
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);														
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;
	HC_OmronUtils.TimeToNanoSec(In:=tEM01,Out=>liEM01ActionTimeTemp2);
	liEM01ActionTimeTemp2:=liEM01ActionTimeTemp2/1000000;								
	IF liEM01ActionTimeTemp2>LINT#65535 THEN //UINT 范围0-65535，越界处理								
		auiEMTime[usiEM01Index,63]:=65535;							
	ELSE								
		auiEMTime[usiEM01Index,63]:=TO_UINT(liEM01ActionTimeTemp2);							
	END_IF;		
	ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储 
	ausiActionParallelNum[uiFIFOlen]:=USINT#0;//动作并行号 
	auiActionNum[uiFIFOlen]:=UINT#63;//动作号	
	auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,63];//动作时间								
	uiFIFOlen:=uiFIFOlen+1;								
	IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)								
		uiFIFOlen:=166;							
	END_IF;								
END_IF;	

//开始计时									
rtgEM01_Start(CLK:=bEM01_Start);									
IF rtgEM01_Start.Q THEN 									
	bEM01TimerStart:=TRUE;								
	Clear(atEM01ActionStart);								
	Clear(atEM01ActionDone);								
	Clear(abEM01ActionRun);																
END_IF;									
									
//计时									
bEM01TimerEnable:=bEM01TimerStart AND bEM01_Run;									
atEM01(In:=bEM01TimerEnable,PT:=T#1D,Reset:=rtgEM01_Start.Q,ET=>tEM01);									
									
//动作时间计算&数据进缓存									
IF bEM01TimerStart THEN 									
	FOR uiIndex:=1 TO 62 BY 1 DO								
		artgEM01ActionStart[uiIndex](CLK:=abEM01ActionStart[uiIndex]);							
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);							
	    IF artgEM01ActionStart[uiIndex].Q THEN  //开始时刻								
			atEM01ActionStart[uiIndex]:=tEM01;						
			abEM01ActionRun[uiIndex]:=TRUE;//防止动作完成信号反复触发，导致数据量激增						
		END_IF;							
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;								
END_IF;									
									
								
									
//--------------输出-----------------------------------//									
auiEMTime[usiEM01Index,1]	:=auiEMTime[usiEM01Index,1]	; //第1个动作时间							
auiEMTime[usiEM01Index,2]	:=auiEMTime[usiEM01Index,2]	; //第2个动作时间							
