TON_Check1(In:=Check1Step>0, PT:=T#10S);
CASE Check1Step	OF
	0://流程开始
		IF Act.Act05_Auto_Station[8,0]
			AND Check1Start
		THEN
			//清除交互信号
			Catl_CcdData.PlcToCcd_Int[0]:=0;
			Catl_CcdData.CcdToPlc_Int[0]:=0;
			Check1Step:=10;
		END_IF;
	10://检测触发
		Catl_CcdBar.PlcToCcd_String[0]:=Cell_Info[8,2].BettarySN;
		Catl_CcdBar.PlcToCcd_String[1]:=Cell_Info[8,2].CodeSN;
		Catl_CcdData.PlcToCcd_Int[0]:=1;
		Check1Step:=20;
	20://判断检测结果
		IF Catl_CcdData.CcdToPlc_Int[0]=2//检测OK
			OR HMI_TestMode_Enable//空机模式
			OR HMI_Function_Enable[8,0]//检测功能未启用
			OR HMI_Function_Enable[8,1] //AND Catl_CcdData.CcdToPlc_Int[0]=3//检测结果功能未启用
		THEN
			Cell_Info[8,2].WeldSeal2DFinish:=TRUE;
			Cell_Info[8,2].WeldSeal2DQuality:=1;
			Cell_Info[8,2].WeldSeal2DResult1:=1;
			Cell_Info[8,2].WeldSeal2DResult2:=1;
			WeldSeal2DNGNum1:=0;
			Check1Step:=30;
		ELSIF Catl_CcdData.CcdToPlc_Int[0]=3//检测NG
		THEN
			IF Cell_Info[8,2].Quality=100 THEN
				Cell_Info[8,2].Quality:=32;
			END_IF;
			Cell_Info[8,2].WeldSeal2DFinish:=TRUE;
			Cell_Info[8,2].WeldSeal2DQuality:=2;
			Cell_Info[8,2].WeldSeal2DResult1:=2;
			Cell_Info[8,2].WeldSeal2DResult2:=2;
			WeldSeal2DNGNum1:=WeldSeal2DNGNum1+1;
			Check1Step:=30;
		ELSIF TON_Check1.Q
		THEN
			IF Cell_Info[8,2].Quality=100 THEN
				Cell_Info[8,2].Quality:=32;
			END_IF;
			Cell_Info[8,2].WeldSeal2DFinish:=TRUE;
			Cell_Info[8,2].WeldSeal2DQuality:=3;
			Cell_Info[8,2].WeldSeal2DResult1:=3;
			Cell_Info[8,2].WeldSeal2DResult2:=3;
			WeldSeal2DNGNum1:=WeldSeal2DNGNum1+1;
			H_Messages.Station[8].User_Alarm[15]:=TRUE;//EM08下料拉带模组：等待焊印检测CCD返回检测结果超时，请打开CCD软件查看原因！
			Check1Step:=30;
		END_IF;
	30://流程结束
		Check1Start:=FALSE;
		Catl_CcdData.PlcToCcd_Int[0]:=0;
		Catl_CcdData.CcdToPlc_Int[0]:=0;
		Check1Step:=0;
END_CASE;

