(******************************************** 治具码扫码流程 *********************************************)
TON_Scan1(In:=SR_ScanCode1.ScanStep>0, PT:=T#15S);
CASE SR_ScanCode1.ScanStep	OF
	0://流程开始
		IF Act.Act05_Auto_Station[8,0]
			AND EM08V.Axis_InPlace_Flag
			AND Cell_Info[8,0].Quality<>0
			AND NOT Cell_Info[8,0].CellLineJigScanFinish
		THEN
			EM08V.ScanCode1.In.Execute:=FALSE;
			SR_ScanCode1.ScanStep:=10;
		END_IF;
	10://扫码触发
		EM08V.ScanCode1.In.Execute:=TRUE;
		SR_ScanCode1.ScanStep:=20;
	20://判断扫码结果
		IF HMI_Function_Enable[8,14]
		THEN
			FOR i:=1 TO 40 BY 1 DO
			    IF EM08V.Axis_X1.Out.PosDone[i] THEN
					Cell_Info[8,0].CellLineJigSN:=INT_TO_STRING(((22+i-1) MOD 22)+1);
					EXIT;
				END_IF;
			END_FOR;
			Cell_Info[8,0].CellLineJigScanFinish:=TRUE;
			SR_ScanCode1.ScanStep:=40;
		ELSIF EM08V.ScanCode1.Out.ReadSuccess//扫码OK
		THEN
			Cell_Info[8,0].CellLineJigSN:=EM08V.ScanCode1.Out.BarCodeString;
			Cell_Info[8,0].CellLineJigScanFinish:=TRUE;
			SR_ScanCode1.ScanStep:=40;
		ELSIF EM08V.ScanCode1.Out.ReadFailure//扫码NG
		THEN
			SR_ScanCode1.ErrOut.Err_ScanFailure:=TRUE;//扫码失败
			SR_ScanCode1.ScanStep:=40;
		ELSIF TON_Scan1.Q
		THEN
			SR_ScanCode1.ErrOut.Err_OverTime:=TRUE;//超时错误
			SR_ScanCode1.ScanStep:=40;
		END_IF;
	40://流程结束
		EM08V.ScanCode1.In.Execute:=FALSE;
		SR_ScanCode1.ScanStep:=0;
		
END_CASE;

