	Enable							:=TRUE, //功能块使能
	DisableSelflock_V						:=FALSE,//输入自锁
	DisableSelflock_R						:=FALSE,//输出自锁
	SynControl_V						:=FALSE,//同步控制
	SynControl_R						:=FALSE,//同步控制
	ManualTrigDelay_V						:=1,//手动触发延时
	ManualTrigDelay_R						:=1,//手动触发延时
	AirPressure_Alarm						:=FALSE,//关联气源报警信号
	CL_In							:=EM08V.Cy_Check1.In,//控制输入
	CL_P							:=HMI_RecipeData.EM08.Cy_Check1,//控制输出
	Status							:=Act.Act10_Call_Status[8,0],//工位状态
	CL_Out							=>EM08V.Cy_Check1.Out//控制输出
	);
	
EM08V.Cy_Check2.In.Shield :=TRUE;
