(********************************************	检测流程		*********************************************)
TON_Check5(In:=Check5Step>0, PT:=T#10S);
CASE Check5Step	OF
	0://流程开始
		IF Act.Act05_Auto_Station[8,0]
			AND Check5Start
		THEN
			//清除交互信号
			Catl_CcdData.PlcToCcd_Int[3]:=0;
			Catl_CcdData.CcdToPlc_Int[3]:=0;
			Check5Step:=10;
		END_IF;
	10://检测触发
		Catl_CcdBar.PlcToCcd_String[6]:=Cell_Info[8,9].BettarySN;
		Catl_CcdBar.PlcToCcd_String[7]:=Cell_Info[8,9].CodeSN;
		Catl_CcdData.PlcToCcd_Int[3]:=1;
		Check5Step:=20;
	20://判断检测结果
		IF Catl_CcdData.CcdToPlc_Int[3]=2//检测OK
			OR HMI_TestMode_Enable//空机模式
			OR HMI_Function_Enable[8,9]//检测功能未启用
			OR HMI_Function_Enable[8,10] AND Catl_CcdData.CcdToPlc_Int[3]=3//检测结果功能未启用
		THEN
			Cell_Info[8,9].WeldSealSupportFinish:=TRUE;
			Cell_Info[8,9].WeldSealSupportQuality:=1;
			Cell_Info[8,9].WeldSealSupportResult1:=1;
			Cell_Info[8,9].WeldSealSupportResult2:=1;
			WeldSealSupportNGNum1:=0;
			Check5Step:=30;
		ELSIF Catl_CcdData.CcdToPlc_Int[3]=3//检测NG
		THEN
			IF Cell_Info[8,9].Quality=100 THEN
				Cell_Info[8,9].Quality:=62;
			END_IF;
			Cell_Info[8,9].WeldSealSupportFinish:=TRUE;
			Cell_Info[8,9].WeldSealSupportQuality:=2;
			Cell_Info[8,9].WeldSealSupportResult1:=2;
			Cell_Info[8,9].WeldSealSupportResult2:=2;
			WeldSealSupportNGNum1:=WeldSealSupportNGNum1+1;
			Check5Step:=30;
		ELSIF TON_Check5.Q
		THEN
			IF Cell_Info[8,9].Quality=100 THEN
				Cell_Info[8,9].Quality:=62;
			END_IF;
			Cell_Info[8,9].WeldSealSupportFinish:=TRUE;
			Cell_Info[8,9].WeldSealSupportQuality:=3;
			Cell_Info[8,9].WeldSealSupportResult1:=3;
			Cell_Info[8,9].WeldSealSupportResult2:=3;
			WeldSealSupportNGNum1:=WeldSealSupportNGNum1+1;
			H_Messages.Station[8].User_Alarm[20]:=TRUE;//EM08下料拉带模组：等待扣支架检测CCD返回检测结果超时，请打开CCD软件查看原因！
			Check5Step:=30;
		END_IF;
	30://流程结束
		Check5Start:=FALSE;
		Catl_CcdData.PlcToCcd_Int[3]:=0;
		Catl_CcdData.CcdToPlc_Int[3]:=0;
		Check5Step:=0;
END_CASE;

R_Check5(Clk:=HMI_Button[8,6]);
F_Check5(Clk:=HMI_Button[8,6]);

//1#检测触发
IF R_Check5.Q THEN
	Catl_CcdBar.PlcToCcd_String[6]:='1#CellHymson0123456789';
	Catl_CcdBar.PlcToCcd_String[7]:='1#CoverHymson0123456789';
	Catl_CcdData.PlcToCcd_Int[3]:=1;
	Catl_CcdData.CcdToPlc_Int[3]:=0;
END_IF;
IF F_Check5.Q THEN
	Catl_CcdData.PlcToCcd_Int[3]:=0;
END_IF;

FOR StationSum := 0 TO StationNum BY 1 DO
	Act.Act05_Auto_Station[EMNumber,StationSum] := Act.Act05_Auto[EMNumber] AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding;
