// EM13电芯下料模组:手自动冲突 IF NOT Signal_ResetCompleteRT AND MyInput.Start_Input AND NOT MyStation.EM[13].Shielding AND MyStation.EM[13].Conflict THEN H_Messages.Station[13].HinderToPos[25,0] := TRUE ;// EM13电芯下料模组:手自动冲突 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 IF EM13V.Axis_X1.Out.Tips_Out[5] THEN H_Messages.Station[13].HinderToPos[25,1] := TRUE ;// EM13电芯下料模组:SV49_1#电芯下料X轴-手自动冲突 END_IF IF EM13V.Axis_X2.Out.Tips_Out[5] THEN H_Messages.Station[13].HinderToPos[25,2] := TRUE ;// EM13电芯下料模组:SV50_2#电芯下料X轴-手自动冲突 END_IF IF EM13V.Axis_Z1.Out.Tips_Out[5] THEN H_Messages.Station[13].HinderToPos[25,3] := TRUE ;// EM13电芯下料模组:SV51_1#电芯下料Z轴-手自动冲突 END_IF IF EM13V.Axis_R1.Out.Tips_Out[5] THEN H_Messages.Station[13].HinderToPos[25,4] := TRUE ;// EM13电芯下料模组:SV52_1#电芯下料R轴-手自动冲突 END_IF IF EM13V.Axis_Z2.Out.Tips_Out[5] THEN H_Messages.Station[13].HinderToPos[25,5] := TRUE ;// EM13电芯下料模组:SV53_2#电芯下料Z轴-手自动冲突 END_IF IF EM13V.Axis_Z3.Out.Tips_Out[5] THEN H_Messages.Station[13].HinderToPos[25,6] := TRUE ;// EM13电芯下料模组:SV54_1#下料提升机Z轴-手自动冲突 END_IF IF EM13V.Axis_Z4.Out.Tips_Out[5] THEN H_Messages.Station[13].HinderToPos[25,7] := TRUE ;// EM13电芯下料模组:SV55_2#下料提升机Z轴-手自动冲突 END_IF IF EM13V.Axis_Y1.Out.Tips_Out[5] THEN H_Messages.Station[13].HinderToPos[25,8] := TRUE ;// EM13电芯下料模组:SV56_下料NG拉带平移Y轴-手自动冲突 END_IF IF EM13V.Cy_Clamp1.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,9] := TRUE ;// EM13电芯下料模组:1#下料夹爪气缸-手自动冲突 END_IF IF EM13V.Cy_Clamp2.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,10] := TRUE ;// EM13电芯下料模组:2#下料夹爪气缸-手自动冲突 END_IF IF EM13V.Cy_Block5_1.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,11] := TRUE ;// EM13电芯下料模组:1#NG料托盘阻挡气缸1-手自动冲突 END_IF IF EM13V.Cy_Block5_2.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,12] := TRUE ;// EM13电芯下料模组:1#NG料托盘阻挡气缸2-手自动冲突 END_IF IF EM13V.Cy_Block1_1.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,13] := TRUE ;// EM13电芯下料模组:1#升降位托盘阻挡气缸1-手自动冲突 END_IF IF EM13V.Cy_Block1_2.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,14] := TRUE ;// EM13电芯下料模组:1#升降位托盘阻挡气缸2-手自动冲突 END_IF IF EM13V.Cy_Block1_3.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,15] := TRUE ;// EM13电芯下料模组:1#升降位托盘阻挡气缸3-手自动冲突 END_IF IF EM13V.Cy_Block1_4.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,16] := TRUE ;// EM13电芯下料模组:1#升降位托盘阻挡气缸4-手自动冲突 END_IF IF EM13V.Cy_Block3_1.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,17] := TRUE ;// EM13电芯下料模组:上层托盘阻挡气缸1-手自动冲突 END_IF IF EM13V.Cy_Block3_2.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,18] := TRUE ;// EM13电芯下料模组:上层托盘阻挡气缸2-手自动冲突 END_IF IF EM13V.Cy_Block4_1.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,19] := TRUE ;// EM13电芯下料模组:下层托盘阻挡气缸-手自动冲突 END_IF IF EM13V.Cy_Block2_1.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,20] := TRUE ;// EM13电芯下料模组:2#升降位托盘阻挡气缸1-手自动冲突 END_IF IF EM13V.Cy_Block2_2.Out.Tips_Out[3] THEN H_Messages.Station[13].HinderToPos[25,21] := TRUE ;// EM13电芯下料模组:2#升降位托盘阻挡气缸2-手自动冲突 END_IF IF EM13V.Clamp1.ErrOut.ConflictErr THEN H_Messages.Station[13].HinderToPos[25,22] := TRUE ;// EM13电芯下料模组:电动夹爪1-手自动冲突 END_IF IF EM13V.Clamp2.ErrOut.ConflictErr THEN H_Messages.Station[13].HinderToPos[25,23] := TRUE ;// EM13电芯下料模组:电动夹爪2-手自动冲突 END_IF END_IF;
(*关闭弹框消除提示*) IF NOT HMI_EQ.ConflictPopups AND NOT H_Messages.ConflictPopups THEN Clear(H_Messages.Station[13].HinderToPos); END_IF;

(********************************************	成品出站流程		*********************************************)
IF Act.Act05_Auto_Station[13,0]
	AND Cell_Info[13,0].Quality>=10
	AND NOT Cell_Info[13,0].OutboundFinish
	AND Catl_MesData.PlcToPc_Int[6]=0
THEN
	Catl_MesData.PlcToPc_Int[6]:=1;
END_IF;


IF Catl_MesData.PlcToPc_Int[6]=100//MES OK
	OR (Catl_MesData.PlcToPc_Int[6]=1 AND HMI_Function_Enable[0,0])
	OR (Catl_MesData.PlcToPc_Int[6]=1 AND HMI_TestMode_Enable)
THEN
	Cell_Info[13,0].OutboundFinish:=TRUE;
	Catl_MesData.PlcToPc_Int[6]:=0;
	OutboundNGNum1:=0;
ELSIF Catl_MesData.PlcToPc_Int[6]=35//MES NG
THEN
	IF Cell_Info[13,0].Quality=100 THEN
		Cell_Info[13,0].Quality:=70;
	END_IF;
	Cell_Info[13,0].OutboundFinish:=TRUE;
	Catl_MesData.PlcToPc_Int[6]:=0;
	OutboundNGNum1:=OutboundNGNum1+1;
END_IF;


IF Catl_MesData.PlcToPc_Int[6]<0 AND MyInput.Reset_Input THEN
	Catl_MesData.PlcToPc_Int[6]:=0;
END_IF

(********************************************	首件出站流程		*********************************************)
IF Act.Act05_Auto_Station[13,0]
	AND Cell_Info[13,0].Quality <> 0
	AND NOT Cell_Info[13,0].OutboundFinish
	AND Cell_Info[13,0].SampleProductFlag   //首件
	AND WDD1_Result1=0
	AND Catl_MesData.PlcToPc_Int[8]=0
THEN
	Catl_MesData.PlcToPc_Int[8]:=1;
END_IF;


IF Catl_MesData.PlcToPc_Int[8]=100//MES OK
	AND WDD1_Result1=0
	OR (Catl_MesData.PlcToPc_Int[8]=1 AND HMI_Function_Enable[0,0])
	OR (Catl_MesData.PlcToPc_Int[8]=1 AND HMI_TestMode_Enable)
THEN
	Cell_Info[13,0].OutboundFinish:=TRUE;
	Catl_MesData.PlcToPc_Int[8]:=0;
ELSIF Catl_MesData.PlcToPc_Int[8]=35//MES NG 
		AND WDD1_Result1=0
THEN
	IF Cell_Info[13,0].Quality=100 THEN
		Cell_Info[13,0].Quality:=70;
	END_IF;
	Cell_Info[13,0].OutboundFinish:=TRUE;
	Catl_MesData.PlcToPc_Int[8]:=0;
END_IF;


IF 	 WDD1_SpotCheckDone=1 
	 AND WDD1_SpotCheckResult<>0	 
THEN
	WDD1_Result1:=1;
ELSE
	WDD1_Result1:=0;
END_IF
//WDD点检结果出站
	IF  WDD1_SpotCheckDone=1 
	 	AND WDD1_SpotCheckResult<>0
		AND Catl_MesData.PlcToPc_Int[8]=0
	THEN
		IF WDD1_SpotCheckResult=1
		THEN
		Catl_MesData.PlcToPc_Real[343]:=WDD1_Result1;
		Catl_MesData.PlcToPc_Real[344]:=0;
		Catl_MesData.PlcToPc_Int[8]:=1;
		ELSE
		Catl_MesData.PlcToPc_Real[343]:=WDD1_Result1;
		Catl_MesData.PlcToPc_Real[344]:=1;
		Catl_MesData.PlcToPc_Int[8]:=1;
		END_IF;
	END_IF;

IF Catl_MesData.PlcToPc_Int[8]=100  //MES OK 
   OR Catl_MesData.PlcToPc_Int[8]=35
THEN
	Catl_MesData.PlcToPc_Int[8]:=0;
	WDD1_SpotCheckResult:=0;
	WDD1_SpotCheckDone:=0;
END_IF

(******************************************** 1#焊接首件出站数据 *********************************************) //REAL数据 Catl_MesData.PlcToPc_Real[200] := Cell_Info[13,0].Quality ;// NG类型 Catl_MesData.PlcToPc_Real[201] := Cell_Info[13,0].ProductionLineNumber ;// 产线编号 Catl_MesData.PlcToPc_Real[202] := Cell_Info[13,0].EngraveCodeResult ;// 顶盖刻码结果:1/OK,2/NG Catl_MesData.PlcToPc_Real[203] := Cell_Info[13,0].EngraveCodeWindSpeed ;// 刻码除尘风速（m/s） Catl_MesData.PlcToPc_Real[204] := Cell_Info[13,0].EngraveCodeOffsetXValue ;// 刻码X方向偏移量 Catl_MesData.PlcToPc_Real[205] := Cell_Info[13,0].EngraveCodeOffsetYValue ;// 刻码Y方向偏移量 Catl_MesData.PlcToPc_Real[206] := Cell_Info[13,0].WeldCenterPower1 ;// 1#焊点中心功率（W） Catl_MesData.PlcToPc_Real[207] := Cell_Info[13,0].WeldAnnularPower1 ;// 1#焊点环形功率（W） Catl_MesData.PlcToPc_Real[208] := Cell_Info[13,0].WeldPower1 ;// 1#焊点总功率（W） Catl_MesData.PlcToPc_Real[209] := Cell_Info[13,0].WeldSpeed1 ;// 1#焊点焊接速度（mm/s） Catl_MesData.PlcToPc_Real[210] := Cell_Info[13,0].WeldTime1 ;// 1#焊点焊接时间（ms） Catl_MesData.PlcToPc_Real[211] := Cell_Info[13,0].WeldDefocusingValue1 ;// 1#焊点焊接离焦量（mm） Catl_MesData.PlcToPc_Real[212] := Cell_Info[13,0].LaserCheckValue1 ;// 1#焊点激光位移检测值（mm） Catl_MesData.PlcToPc_Real[213] := Cell_Info[13,0].WeldNitrogenFlow1 ;// 1#焊点氮气流量（l/min） Catl_MesData.PlcToPc_Real[214] := Cell_Info[13,0].WeldWindSpeed1 ;// 1#焊点除尘风速（m/s） Catl_MesData.PlcToPc_Real[215] := Cell_Info[13,0].LaserCheckValueProcess1[0] ;// 1#焊点激光位移检测过程值1（mm） Catl_MesData.PlcToPc_Real[216] := Cell_Info[13,0].LaserCheckValueProcess1[1] ;// 1#焊点激光位移检测过程值2（mm） Catl_MesData.PlcToPc_Real[217] := Cell_Info[13,0].LaserCheckValueProcess1[2] ;// 1#焊点激光位移检测过程值3（mm） Catl_MesData.PlcToPc_Real[218] := Cell_Info[13,0].LaserCheckValueProcess1[3] ;// 1#焊点激光位移检测过程值4（mm） Catl_MesData.PlcToPc_Real[219] := Cell_Info[13,0].WeldCenterPowerProcess1[0] ;// 1#焊点中心过程功率1（W） Catl_MesData.PlcToPc_Real[220] := Cell_Info[13,0].WeldCenterPowerProcess1[1] ;// 1#焊点中心过程功率2（W） Catl_MesData.PlcToPc_Real[221] := Cell_Info[13,0].W