(******************************************** NG人工取料扫码枪 *********************************************)

//使能
EM13H_ScanCode[0].H_In.Enable:=NOT HMI_Function_Enable[13,1];
//连续NG次数
EM13P.ScanCode1.NGTimesMax:=0;
//IP节点地址
EM13P.ScanCode1.IP_Node:=89;
//工位编号
EM13V.ScanCode1.In.StationNo:=1;

ScanCode1(
	Reset						:=MyInput.Reset_Input								,//复位
	Auto							:=MyStatus.StatusAuto								,//自动
	Manual					:=MyStatus.StatusManual							,//手动
	In								:=EM13V.ScanCode1.In								,//程序输入
	H_In							:=EM13H_ScanCode[0].H_In						,//HMI输入
	H_Out						:=EM13H_ScanCode[0].H_Out						,//HMI输出
	Out							=>EM13V.ScanCode1.Out							,//程序输出
	ErrOut						=>EM13V.ScanCode1.ErrOut						,//程序错误
	Parameter				:=EM13P.ScanCode1									,//参数设置
	SR_To_PLC_Data		:=EM13ScanCode1_EIPIn								,//EIP输入
	PLC_To_SR_Data		:=EM13ScanCode1_EIPOut							//EIP输出
	);
	
(******************************************** 电芯NG扫码枪 *********************************************)

//使能
