//连续NG次数
EM13P.ScanCode2.NGTimesMax:=0;
//IP节点地址
EM13P.ScanCode2.IP_Node:=87;
//工位编号
EM13V.ScanCode2.In.StationNo:=1;

ScanCode2(
	Reset						:=MyInput.Reset_Input								,//复位
	Auto							:=MyStatus.StatusAuto								,//自动
	Manual					:=MyStatus.StatusManual							,//手动
	In								:=EM13V.ScanCode2.In								,//程序输入
