	);	
	


(******************************************** 物流线交互信号 *********************************************)

EM13V.LinkOut_Request	:=	Act.Act05_Auto[13]
											AND Act.Act05_Auto_Station[13,0]
											AND NOT HMI_Function_Enable[13,0]
											AND NOT HMI_TestMode_Enable
											AND NOT EM13V.Sen_HaveCell5.Out.Filtered_Q
											AND Cell_Info[13,1].Quality<>0
											;//	设备To物流线：请求放料
EM13V.LinkOut_Assign	:=	Act.Act05_Auto[13]
											AND Act.Act05_Auto_Station[13,0]
											AND NOT HMI_Function_Enable[13,0]
											AND EM13V.LinkOut_Request
											AND EM13V.LinkIn_Allow
											;//	设备To物流线：请求分配
// EM13V.LinkOut_Done	:=	
// 											;//EM13V.LinkOut_Done	设备To物流线：放料完成
EM13V.LinkOut_MovingAllow	:=	EM13V.Z2_SafetySignal_ToLine
													AND NOT EM13V.LinkOut_Assign
													;//	设备To物流线：移动允许
EM13V.LinkOut_SafetySD	:=	 (MyStation.EmgStop
												AND MyInput.SafetyDoor_Input[31]
												AND MyInput.SafetyDoor_Input[32]
												AND MyInput.SafetyDoor_Input[33]
												AND MyInput.SafetyDoor_Input[34]
												AND MyInput.SafetyDoor_Input[35]
												AND MyInput.SafetyDoor_Input[36]
												AND MyInput.SafetyDoor_Input[37]
												AND MyInput.SafetyDoor_Input[38]
												AND MyInput.SafetyDoor_Input[39]
												AND MyInput.SafetyDoor_Input[40]
												);//	设备To物流线：安全门禁
//分配响应计时
TON_Assigned(
	In:=EM13V.LinkOut_Assign
	AND EM13V.LinkIn_Allow
	AND EM13V.LinkIn_SafetySD
	, PT:=T#200MS);
EM13V.LinkIn_Assigned	:=	TON_Assigned.Q;//	物流线To设备：分配响应

data.STCode:
FOR StationSum := 0 TO StationNum BY 1 DO
	StationInit_R[StationSum](Clk:=MyStation.EMStation[EMNumber,StationSum].Init OR Act.Act04_Init[EMNumber]);
	IF  StationInit_R[StationSum].Q 
	THEN 
		MyStation.EMStation[EMNumber,StationSum].ResetComplete :=FALSE;
	END_IF;
    IF 	(MyStation.EMStation[EMNumber,StationSum].Init 
		OR Act.Act04_Init[EMNumber])
		AND Inital_Runing
		AND MyInput.AutoSwitch_Input
		AND NOT MyStation.EM[EMNumber].Shielding
		AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
		AND NOT MyStation.EM[EMNumber].IsAlarm
		AND NOT MyStation.EM[0].Running
		AND NOT OperationOut.Abort
		AND NOT OperationOut.Stop
		AND NOT OperationOut.Hold
		AND NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete
	THEN 
		Act.Act04_Init_Station[EMNumber,StationSum] := TRUE;
	ELSE
		Act.Act04_Init_Station[EMNumber,StationSum] := FALSE;
	END_IF;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	IF  MyStation.EMStation[EMNumber,StationSum].ResetComplete OR  MyStation.EMStation[EMNumber,StationSum].Shielding THEN 
		MyStation.EM[EMNumber].ResetComplete :=TRUE;
	ELSIF NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
	THEN 
		MyStation.EM[EMNumber].ResetComplete := FALSE;
		EXIT;
	END_IF;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	Act.Act05_Auto_Station[EMNumber,StationSum] := Act.Act05_Auto[EMNumber] AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding;
END_FOR;

IF Act.Act09_AlmAndMesg[9] THEN MyStation.EM[9].IsAlarm:= Search_Alarm(H_Messages.Station[9].Object_Alarm) OR H_Messages.Station[9].Alarm; (********************报警信息********************)
