,14] := TRUE ;// EM06振镜焊接模组:1#上保护盖气缸-手自动冲突 END_IF IF EM06V.Cy_LaserCheckProtection1.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,15] := TRUE ;// EM06振镜焊接模组:1#离焦量遮光气缸-手自动冲突 END_IF IF EM06V.Cy_WeldDustRemoval1.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,16] := TRUE ;// EM06振镜焊接模组:1#焊接遮光气缸-手自动冲突 END_IF IF EM06V.Cy_Clamp1_1.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,17] := TRUE ;// EM06振镜焊接模组:1#保护盖侧边压紧气缸1-手自动冲突 END_IF IF EM06V.Cy_Clamp1_2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,18] := TRUE ;// EM06振镜焊接模组:1#保护盖侧边压紧气缸2-手自动冲突 END_IF IF EM06V.Cy_Press2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,19] := TRUE ;// EM06振镜焊接模组:2#保护盖下压气缸-手自动冲突 END_IF IF EM06V.Cy_Clamp2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,20] := TRUE ;// EM06振镜焊接模组:2#上保护盖叉料气缸-手自动冲突 END_IF IF EM06V.Cy_Up2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,21] := TRUE ;// EM06振镜焊接模组:2#上保护盖升降气缸-手自动冲突 END_IF IF EM06V.Cy_Shift2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,22] := TRUE ;// EM06振镜焊接模组:2#上保护盖气缸-手自动冲突 END_IF IF EM06V.Cy_LaserCheckProtection2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,23] := TRUE ;// EM06振镜焊接模组:2#离焦量遮光气缸-手自动冲突 END_IF IF EM06V.Cy_WeldDustRemoval2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,24] := TRUE ;// EM06振镜焊接模组:2#焊接遮光气缸-手自动冲突 END_IF IF EM06V.Cy_Clamp2_1.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,25] := TRUE ;// EM06振镜焊接模组:2#保护盖侧边压紧气缸1-手自动冲突 END_IF IF EM06V.Cy_Clamp2_2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,26] := TRUE ;// EM06振镜焊接模组:2#保护盖侧边压紧气缸2-手自动冲突 END_IF IF EM06V.Cy_Location1.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,27] := TRUE ;// EM06振镜焊接模组:1#保护盖替罪羊气缸-手自动冲突 END_IF IF EM06V.Cy_Location2.Out.Tips_Out[3] THEN H_Messages.Station[6].HinderToPos[25,28] := TRUE ;// EM06振镜焊接模组:2#保护盖替罪羊气缸-手自动冲突 END_IF END_IF;
(*关闭弹框消除提示*) IF NOT HMI_EQ.ConflictPopups AND NOT H_Messages.ConflictPopups THEN Clear(H_Messages.Station[6].HinderToPos); END_IF;

;// //A保护盖上料Y轴无原点，需要人工确认并回零
