// //B保护盖上料Y轴无原点，需要人工确认并回零
// H_Messages.Station[7].User_Warning[1] :=   
// Act.Act04_Init_Station[6,3]
// AND NOT EM06V.Axis_Y2.Out.Homed
// ;

(******************************************** 自动焊接首件 *********************************************)
//信号生成
R_FunctionEnable(Clk:=EM06P.SampleProductWeldEnable);
F_FunctionEnable(Clk:=EM06P.SampleProductWeldEnable);
//执行命令信号生成
FOR i:=0 TO 15 BY 1 DO
	R_CommandExecute[i](Clk:=EM06P.CommandExecute[i]);
END_FOR;
//功能启用上升沿
// IF R_FunctionEnable.Q THEN
// 	MyStation.EM[5].ResetComplete:=FALSE;
// 	MyStation.EM[6].ResetComplete:=FALSE;
// 	EM06P.SampleProductWeldDone:=FALSE;
// 	FOR i:=0 TO 10 BY 1 DO
// 		Cell_Info[5,i].SampleProductFlag:=FALSE;
// 	END_FOR;
// 	Clear(EM06P.CommandExecute);
// 	EM06P.WeldJigSelect[EM06P.WeldJigSelectNum[0]]:=TRUE;
// 	EM06P.WeldJigSelect[EM06P.WeldJigSelectNum[1]]:=TRUE;
// END_IF;

//功能启用下降沿
IF F_FunctionEnable.Q THEN
	MyStation.EM[5].ResetComplete:=FALSE;
	MyStation.EM[6].ResetComplete:=FALSE;
	FOR i:=0 TO 10 BY 1 DO
		Cell_Info[5,i].SampleProductFlag:=FALSE;
		EM06P.WeldJigSelect[i]:=FALSE;
	END_FOR;
	Clear(EM06P.CommandExecute);
	EM06P.SampleProductWeldDone:=FALSE;
END_IF;

//功能启用条件
EM06P.FunctionEnableCondition:=MyStatus.StatusAuto
													AND NOT HMI_EQ.HMI_SelectChange_Enable[10]
													AND NOT MyStation.EM[0].Running
													OR EM06P.SampleProductWeldEnable;
//手动模式下关闭焊接首件功能
IF NOT MyStatus.StatusAuto
THEN
	EM06P.SampleProductWeldEnable:=FALSE;
END_IF;

//焊接治具选择条件
FOR i:=0 TO 10 BY 1 DO
EM06P.WeldJigSelectCondition[i]:=MyStatus.StatusAuto
													AND EM06P.SampleProductWeldEnable
													AND NOT EM05P.VehicleShielding[i];
END_FOR;
// 
// //序号相同计算
// R_SelectNum(Clk:=EM06P.WeldJigSelectNum[0]=EM06P.WeldJigSelectNum[1]);
// IF R_SelectNum.Q THEN
// 	FC_NumberAlgorithm(
// 		EN:=TRUE,
// 		Shielding:=EM05P.VehicleShielding, 
// 		Num1:=EM06P.WeldJigSelectNum[0], 
// 		Num2:=EM06P.WeldJigSelectNum[1], 
// 		OutNum1=>EM06P.WeldJigSelectNum[0],
// 		OutNum2=>EM06P.WeldJigSelectNum[1]
// 		);
// END_IF;
// //治具被屏蔽时计算
// IF (EM05P.VehicleShielding[EM06P.WeldJigSelectNum[0]]
// 	OR EM05P.VehicleShielding[EM06P.WeldJigSelectNum[1]])
// 	AND R_FunctionEnable.Q
// THEN
// 	FC_NumberAlgorithm(
// 		EN:=TRUE,
// 		Shielding:=EM05P.VehicleShielding, 
// 		Num1:=EM06P.WeldJigSelectNum[0], 
// 		Num2:=EM06P.WeldJigSelectNum[1], 
// 		OutNum1=>EM06P.WeldJigSelectNum[0],
// 		OutNum2=>EM06P.WeldJigSelectNum[1]
// 		);
// END_IF;
// //焊接完成后计算
// R_WeldDone(Clk:=EM06P.SampleProductWeldDone);
// IF R_WeldDone.Q THEN
// 	FC_NumberAlgorithm(
// 		EN:=TRUE,
// 		Shielding:=EM05P.VehicleShielding, 
// 		Num1:=EM06P.WeldJigSelectNum[0], 
// 		Num2:=EM06P.WeldJigSelectNum[1], 
// 		OutNum1=>EM06P.WeldJigSelectNum[0],
// 		OutNum2=>EM06P.WeldJigSelectNum[1]
// 		);
// END_IF;

//物料记忆状态
EM05P.Memory[0]:=(Cell_Info[5,1].Quality=0 OR NOT EM06P.WeldJigSelect[1])
								AND (Cell_Info[5,2].Quality=0 OR NOT EM06P.WeldJigSelect[2])
								AND (Cell_Info[5,3].Quality=0 OR NOT EM06P.WeldJigSelect[3])
								AND (Cell_Info[5,4].Quality=0 OR NOT EM06P.WeldJigSelect[4])
								AND (Cell_Info[5,5].Quality=0 OR NOT EM06P.WeldJigSelect[5])
								AND (Cell_Info[5,6].Quality=0 OR NOT EM06P.WeldJigSelect[6])
								AND (Cell_Info[5,7].Quality=0 OR NOT EM06P.WeldJigSelect[7])
								AND (Cell_Info[5,8].Quality=0 OR NOT EM06P.WeldJigSelect[8])
								AND (Cell_Info[5,9].Quality=0 OR NOT EM06P.WeldJigSelect[9])
								AND (Cell_Info[5,10].Quality=0 OR NOT EM06P.WeldJigSelect[10]);

//焊接启动条件
EM06P.CommandExecuteCondition[1]:=MyStatus.StatusAuto
											AND EM06P.SampleProductWeldEnable
											AND NOT MyStation.EM[0].IsAlarm
											AND NOT MyStation.EM[5].IsAlarm
											AND NOT MyStation.EM[6].IsAlarm
											AND NOT MyStation.EM[5].Shielding
											AND NOT MyStation.EM[6].Shielding
											AND NOT MyStation.EM[5].Conflict
											AND NOT MyStation.EM[6].Conflict
											AND MyStation.EM[5].ResetComplete
											AND MyStation.EM[6].ResetComplete
											AND EM05P.Memory[0]
											AND EM06P.CommandExecute[3];
EM06P.CommandExecuteCondition[2]:=EM06P.CommandExecuteCondition[1];

//焊接启动
IF MyStatus.StatusAuto
	AND NOT MyInput.Stop_Input
	AND NOT MyStation.EM[0].IsAlarm
	AND NOT MyStation.EM[5].IsAlarm
	AND NOT MyStation.EM[6].IsAlarm
	AND NOT MyStation.EM[5].Shielding
	AND NOT MyStation.EM[6].Shielding
	AND NOT MyStation.EM[5].Conflict
	AND NOT MyStation.EM[6].Conflict
	AND MyStation.EM[5].ResetComplete
	AND MyStation.EM[6].ResetComplete
	AND EM06P.SampleProductWeldEnable
THEN
	IF R_CommandExecute[2].Q THEN
	EM06P.SampleProductWeldProcess:=TRUE;
	EM06P.SampleProductWeldDone:=FALSE;
	FOR i:=0 TO 10 BY 1 DO
	IF EM06P.WeldJigSelect[i] AND Cell_Info[5,i].Quality=0 THEN
		Cell_Info[5,i].SampleProductFlag:=TRUE;
	END_IF;
	END_FOR;
	END_IF;
ELSE
	EM06P.SampleProductWeldProcess:=FALSE;
END_IF;

//运行中，关闭二次确认弹窗
IF EM06P.SampleProductWeldProcess
	AND NOT EM06P.CommandExecute[2]
THEN
	EM06P.CommandExecute[1]:=FALSE;
END_IF;


//焊接首件条件
EM06P.SampleProductWeldProcessCondition:=Cell_Info[5,1].SampleProductFlag
																OR Cell_Info[5,2].SampleProductFlag
																OR Cell_Info[5,3].SampleProductFlag
																OR Cell_Info[5,4].SampleProductFlag
																OR Cell_Info[5,5].SampleProductFlag
																OR Cell_Info[5,6].SampleProductFlag
																OR Cell_Info[5,7].SampleProductFlag
																OR Cell_Info[5,8].SampleProductFlag
																OR Cell_Info[5,9].SampleProductFlag
																OR Cell_Info[5,10].SampleProductFlag;

//焊接首件完成
IF EM06P.SampleProductWeldProcess
	AND NOT EM06P.SampleProductWeldProcessCondition
	AND EM06V.Process_steps[0]=0
	AND EM06V.Process_steps[2]=0
THEN
	EM06P.SampleProductWeldProcess:=FALSE;
	EM06P.SampleProductWeldDone:=TRUE;
END_IF;

//完成后，关闭焊接首件功能
TON_WeldDone(In:=EM06P.SampleProductWeldDone
	AND EM06P.SampleProductWeldEnable
, PT:=T#5S);
IF TON_WeldDone.Q THEN
	EM06P.SampleProductWeldEnable:=FALSE;
END_IF;

//每天0点0分0秒，传送数据
IF Signal_NewDayRT THEN
	EM06P.WeldJigOldData2:=EM06P.WeldJigOldData1;
	EM06P.WeldJigOldData1:=EM06P.WeldJigData;
	Clear(EM06P.WeldJigData);
END_IF;

(******************************************** 焊接治具检索 *********************************************)
//检索启动条件
EM06P.CommandExecuteCondition[4]:=MyStatus.StatusAuto
											AND EM06P.SampleProductWeldEnable
											AND NOT MyStation.EM[0].IsAlarm
											AND NOT MyStation.EM[5].IsAlarm
											AND NOT MyStation.EM[6].IsAlarm
											AND NOT MyStation.EM[5].Shielding
											AND NOT MyStation.EM[6].Shielding
											AND NOT MyStation.EM[5].Conflict
											AND NOT MyStation.EM[6].Conflict
											AND MyStation.EM[5].ResetComplete
											AND MyStation.EM[6].ResetComplete;

// EM06P.WeldJigSearchProcessCodition:=NOT (EM05V.ST_CellLocation1.MoverInplace
// 																AND EM05V.ST_CellLocation1.MoverID=EM06P.WeldJigSelectNum[0]);
//检索启动
IF MyStatus.StatusAuto
	AND NOT MyInput.Stop_Input
	AND NOT MyStation.EM[0].IsAlarm
	AND NOT MyStation.EM[5].IsAlarm
	AND NOT MyStation.EM[6].IsAlarm
	AND NOT MyStation.EM[5].Shielding
	AND NOT MyStation.EM[6].Shielding
	AND NOT MyStation.EM[5].Conflict
	AND NOT MyStation.EM[6].Conflict
	AND MyStation.EM[5].ResetComplete
	AND MyStation.EM[6].ResetComplete
	AND EM06P.SampleProductWeldEnable
THEN
	IF R_CommandExecute[4].Q THEN
	EM06P.WeldJigSearchProcess:=TRUE;
	END_IF;
ELSE
	EM06P.WeldJigSearchProcess:=FALSE;
END_IF;

//检索完成
IF EM06P.WeldJigSearchProcess
	AND NOT EM06P.WeldJigSearchProcessCodition
THEN
	EM06P.WeldJigSearchProcess:=FALSE;
END_IF;

//检索编号
IF EM06P.SampleProductWeldEnable
	AND Catl_MesData.PlcToPc_Int[8]=0
THEN
	OutboundNum1:=OutboundNum1+1;
END_IF;
IF OutboundNum1>10 THEN
	OutboundNum1:=0;
END_IF;

// //数据获取
// IF EM06P.SampleProductWeldEnable
// 	AND Cell_Info[5,OutboundNum1].SampleProductFlag
// 	AND (Cell_Info[5,OutboundNum1].Quality>=10
// 	AND Cell_Info[5,OutboundNum1].Quality<70
// 	OR Cell_Info[5,OutboundNum1].Quality=100)
// THEN
// 	Inc(InOut:=EM06P.WeldJigData[OutboundNum1]);
// 	EM06P.WeldJigCell_Info[OutboundNum1]:=Cell_Info[5,OutboundNum1];
