// END_IF;

ST.xhtml:
(********************************************	焊接工艺参数		*********************************************)

//焊接工位编号
EM06P.ST_Weld1.WeldStationNum:=1;
EM06P.ST_Weld2.WeldStationNum:=2;

//焊接速度
EM06P.ST_Weld1.WeldSpeed1:=HMI_RecipeData.WeldSpeed1;
EM06P.ST_Weld1.WeldSpeed2:=HMI_RecipeData.WeldSpeed2;
EM06P.ST_Weld2.WeldSpeed1:=HMI_RecipeData.WeldSpeed1;
EM06P.ST_Weld2.WeldSpeed2:=HMI_RecipeData.WeldSpeed2;

//1#振镜功率(%)
EM06P.ST_Weld1.ZJ_InsidePower1:=HMI_RecipeData.ZJ_InsidePower1[0];
EM06P.ST_Weld1.ZJ_OutsidePower1:=HMI_RecipeData.ZJ_OutsidePower1[0];
EM06P.ST_Weld1.ZJ_InsidePower2:=HMI_RecipeData.ZJ_InsidePower2[0];
EM06P.ST_Weld1.ZJ_OutsidePower2:=HMI_RecipeData.ZJ_OutsidePower2[0];


//2#振镜功率(%)
EM06P.ST_Weld2.ZJ_InsidePower1:=HMI_RecipeData.ZJ_InsidePower1[1];
EM06P.ST_Weld2.ZJ_OutsidePower1:=HMI_RecipeData.ZJ_OutsidePower1[1];
EM06P.ST_Weld2.ZJ_InsidePower2:=HMI_RecipeData.ZJ_InsidePower2[1];
EM06P.ST_Weld2.ZJ_OutsidePower2:=HMI_RecipeData.ZJ_OutsidePower2[1];


//铝极三段圆弧半径
EM06P.ST_Weld1.WeldAlArcRadius:=HMI_RecipeData.WeldAlArcRadius;
EM06P.ST_Weld2.WeldAlArcRadius:=HMI_RecipeData.WeldAlArcRadius;

//振经内环功率
IF EM06V.KLAB_Input1[0].mByte[3]=BYTE#01//图档信息
THEN
	EM06P.ST_Weld1.LaserZJ_InsidePower1[0]:=DWORD_TO_REAL(EM06V.KLAB_Input1[1].mDword)/1000;//1#焊接铝极
ELSIF
	EM06V.KLAB_Input1[0].mByte[3]=BYTE#02//图档信息
THEN
	EM06P.ST_Weld1.LaserZJ_InsidePower2[0]:=DWORD_TO_REAL(EM06V.KLAB_Input1[1].mDword)/1000;//1#焊接铜极
END_IF

IF EM06V.KLAB_Input2[0].mByte[3]=BYTE#01//图档信息
THEN
	EM06P.ST_Weld1.LaserZJ_InsidePower1[1]:=DWORD_TO_REAL(EM06V.KLAB_Input2[1].mDword)/1000;//2#焊接铝极
ELSIF
	EM06V.KLAB_Input2[0].mByte[3]=BYTE#02//图档信息
THEN
	EM06P.ST_Weld1.LaserZJ_InsidePower2[1]:=DWORD_TO_REAL(EM06V.KLAB_Input2[1].mDword)/1000;//2#焊接铜极
END_IF


//振经焊接速度
IF EM06V.KLAB_Input1[0].mByte[3]=BYTE#01//图档信息
THEN
	EM06P.ST_Weld1.LaserZJWeldSpeed1[0]:=DWORD_TO_REAL(EM06V.KLAB_Input1[2].mDword)/1000;//1#焊接铝极
ELSIF
	EM06V.KLAB_Input1[0].mByte[3]=BYTE#02//图档信息
THEN
	EM06P.ST_Weld1.LaserZJWeldSpeed2[0]:=DWORD_TO_REAL(EM06V.KLAB_Input1[2].mDword)/1000;//1#焊接铜极
END_IF

IF EM06V.KLAB_Input2[0].mByte[3]=BYTE#01//图档信息
THEN
	EM06P.ST_Weld1.LaserZJWeldSpeed1[1]:=DWORD_TO_REAL(EM06V.KLAB_Input2[2].mDword)/1000;//2#焊接铝极
ELSIF
	EM06V.KLAB_Input2[0].mByte[3]=BYTE#02//图档信息
THEN
	EM06P.ST_Weld1.LaserZJWeldSpeed2[1]:=DWORD_TO_REAL(EM06V.KLAB_Input2[2].mDword)/1000;//2#焊接铜极
END_IF

//振经外环功率
IF EM06V.KLAB_Input1[0].mByte[3]=BYTE#01//图档信息
THEN
	EM06P.ST_Weld1.LaserZJ_OutsidePower1[0]:=DWORD_TO_REAL(EM06V.KLAB_Input1[14].mDword)/1000;//1#焊接铝极
ELSIF
	EM06V.KLAB_Input1[0].mByte[3]=BYTE#02//图档信息
THEN
	EM06P.ST_Weld1.LaserZJ_OutsidePower2[0]:=DWORD_TO_REAL(EM06V.KLAB_Input1[14].mDword)/1000;//1#焊接铜极
END_IF

IF EM06V.KLAB_Input2[0].mByte[3]=BYTE#01//图档信息
THEN
	EM06P.ST_Weld1.LaserZJ_OutsidePower1[1]:=DWORD_TO_REAL(EM06V.KLAB_Input2[14].mDword)/1000;//2#焊接铝极
ELSIF
	EM06V.KLAB_Input2[0].mByte[3]=BYTE#02//图档信息
THEN
	EM06P.ST_Weld1.LaserZJ_OutsidePower2[1]:=DWORD_TO_REAL(EM06V.KLAB_Input2[14].mDword)/1000;//2#焊接铜极
END_IF

//振经离焦量
IF EM06V.KLAB_Input1[0].mByte[3]=BYTE#01//图档信息
THEN
	EM06P.ST_Weld1.LaserZJDefocusingValue1[0]:=DWORD_TO_REAL(EM06V.KLAB_Input1[15].mDword)/1000;//1#焊接铝极
ELSIF
	EM06V.KLAB_Input1[0].mByte[3]=BYTE#02//图档信息
THEN
	EM06P.ST_Weld1.LaserZJDefocusingValue2[0]:=DWORD_TO_REAL(EM06V.KLAB_Input1[15].mDword)/1000;//1#焊接铜极
END_IF

IF EM06V.KLAB_Input2[0].mByte[3]=BYTE#01//图档信息
THEN
	EM06P.ST_Weld1.LaserZJDefocusingValue1[1]:=DWORD_TO_REAL(EM06V.KLAB_Input2[15].mDword)/1000;//2#焊接铝极
ELSIF
	EM06V.KLAB_Input2[0].mByte[3]=BYTE#02//图档信息
THEN
	EM06P.ST_Weld1.LaserZJDefocusingValue2[1]:=DWORD_TO_REAL(EM06V.KLAB_Input2[15].mDword)/1000;//2#焊接铜极
END_IF



(********************************************	离焦量计算		*********************************************)

//1#焊接位焊接离焦量（计算公式：离焦量=Z轴焊接位-Z轴焦点位）
HMI_RecipeData.EM06.Axis_Z2.Location_Postion[2]:=HMI_RecipeData.EM06.Axis_Z2.Location_Postion[4]-EM06P.ST_Weld1.WeldDefocusingValue1;
HMI_RecipeData.EM06.Axis_Z2.Location_Postion[3]:=HMI_RecipeData.EM06.Axis_Z2.Location_Postion[4]-EM06P.ST_Weld1.WeldDefocusingValue2;
//====离焦量在振镜中设置，计算公式不适用====

//2#焊接位焊接离焦量（计算公式：离焦量=Z轴焊接位-Z轴焦点位）
HMI_RecipeData.EM06.Axis_Z4.Location_Postion[2]:=HMI_RecipeData.EM06.Axis_Z4.Location_Postion[4]-EM06P.ST_Weld2.WeldDefocusingValue1;
HMI_RecipeData.EM06.Axis_Z4.Location_Postion[3]:=HMI_RecipeData.EM06.Axis_Z4.Location_Postion[4]-EM06P.ST_Weld2.WeldDefocusingValue2;//====离焦量在振镜中设置，计算公式不适用====

//初始参数
IF ABS(EM06P.ST_Weld1.WeldDefocusingValue1)>10 THEN
EM06P.ST_Weld1.WeldDefocusingValue1:=0;
END_IF;
IF ABS(EM06P.ST_Weld1.WeldDefocusingValue2)>10 THEN
EM06P.ST_Weld1.WeldDefocusingValue2:=0;
END_IF;
IF ABS(EM06P.ST_Weld2.WeldDefocusingValue1)>10 THEN
EM06P.ST_Weld2.WeldDefocusingValue1:=0;
END_IF;
IF ABS(EM06P.ST_Weld2.WeldDefocusingValue2)>10 THEN
EM06P.ST_Weld2.WeldDefocusingValue2:=0;
END_IF;



