//除尘风速
EM06P.ST_Weld1.WeldWindSpeed1:=(EM00P.WindSpeed[1]+EM00P.WindSpeed[2])/2;
EM06P.ST_Weld1.WeldWindSpeed2:=(EM00P.WindSpeed[10]+EM00P.WindSpeed[11])/2;
EM06P.ST_Weld2.WeldWindSpeed1:=(EM00P.WindSpeed[12]+EM00P.WindSpeed[13])/2;
EM06P.ST_Weld2.WeldWindSpeed2:=(EM00P.WindSpeed[14]+EM00P.WindSpeed[15])/2;

//冷水机启动
