data.STCode:
IF Act.Act04_Init_Station[6,1] AND EM06V.Init_Steps[1]=60 THEN
	IF Cell_Info[6,1].Quality<>0
		AND EM06V.Axis_Z3.Out.CurrentPos>=HMI_RecipeData.EM06.Axis_Z3.Location_Postion[3]-3
		AND EM06V.Axis_Z3.Out.CurrentPos<=HMI_RecipeData.EM06.Axis_Z3.Location_Postion[4]+3
		AND EM06V.Axis_Z3.Out.Homed
		//判断EM10动作状态
		AND EM06V.Axis_Y2.Out.CurrentPos>=HMI_RecipeData.EM06.Axis_Y2.Location_Postion[3]-3
		AND EM06V.Axis_Y2.Out.Homed
		AND EM06V.Cy_Up2.Out.XV
	THEN
		EM06V.Init_Steps[1]:=70;
	ELSE 
		EM06V.Init_Steps[1]:=90;
	END_IF;
END_IF;

IF Act.Act04_Init_Station[6,2] AND EM06V.Init_Steps[2]=70 THEN
	IF Cell_Info[6,0].Quality<>0
		AND EM06V.Axis_Y1.Out.CurrentPos>=HMI_RecipeData.EM06.Axis_Y1.Location_Postion[3]-3
		AND EM06V.Axis_Y1.Out.Homed
		AND EM06V.Cy_Up1.Out.XV
	THEN
		EM06V.Init_Steps[2]:=80;
	ELSE 
		EM06V.Init_Steps[2]:=110;
	END_IF;
END_IF;

