(******************************** 工位动作节拍 ****************************************) // 1#焊接模组动作节拍 EM06CycleTime[0]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM06_CycleTime[0].ClearData , //清除步骤时间列表计时 Complete := EM06_CycleTime[0].Complete , //完成计时输出列表 ProgramStep := EM06V.Process_steps[0] , //步骤变量 Condition := EM06V.Process_steps[0] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM06_CycleTime[0] //输出步骤号和时间 );
// 1#激光器焊接动作节拍 EM06CycleTime[1]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM06_CycleTime[1].ClearData , //清除步骤时间列表计时 Complete := EM06_CycleTime[1].Complete , //完成计时输出列表 ProgramStep := EM06V.Process_steps[1] , //步骤变量 Condition := EM06V.Process_steps[1] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM06_CycleTime[1] //输出步骤号和时间 );
// 2#焊接模组动作节拍 EM06CycleTime[2]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM06_CycleTime[2].ClearData , //清除步骤时间列表计时 Complete := EM06_CycleTime[2].Complete , //完成计时输出列表 ProgramStep := EM06V.Process_steps[2] , //步骤变量 Condition := EM06V.Process_steps[2] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM06_CycleTime[2] //输出步骤号和时间 );
// 2#激光器焊接动作节拍 EM06CycleTime[3]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM06_CycleTime[3].ClearData , //清除步骤时间列表计时 Complete := EM06_CycleTime[3].Complete , //完成计时输出列表 ProgramStep := EM06V.Process_steps[3] , //步骤变量 Condition := EM06V.Process_steps[3] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM06_CycleTime[3] //输出步骤号和时间 );
// 1#保护盖模组动作节拍 EM06CycleTime[4]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM06_CycleTime[4].ClearData , //清除步骤时间列表计时 Complete := EM06_CycleTime[4].Complete , //完成计时输出列表 ProgramStep := EM06V.Process_steps[4] , //步骤变量 Condition := EM06V.Process_steps[4] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM06_CycleTime[4] //输出步骤号和时间 );
// 2#保护盖模组动作节拍 EM06CycleTime[5]( Execute := TRUE , //使能 Reset := MyInput.Reset_Input , //复位 ClearData := EM06_CycleTime[5].ClearData , //清除步骤时间列表计时 Complete := EM06_CycleTime[5].Complete , //完成计时输出列表 ProgramStep := EM06V.Process_steps[5] , //步骤变量 Condition := EM06V.Process_steps[5] >= 10 , //开始监控条件 StepNum := 100 , //监控程序步骤数 HMICycleTime := EM06_CycleTime[5] //输出步骤号和时间 );

(*****************************EM06_振镜焊接模组状态机*****************************) 

EMNumber := 6;//模组编号
StationNum :=4-1 ;//工位数量--数组编号最大为0..9
//0-----
Act.Act01_Status[6]:=TRUE;//工位状态机程序
Act.Act02_Condition[6]:=TRUE;//循环扫描程序
//手动动运行程序
Act.Act03_Manual[6]:=  MyStatus.StatusManual;	
//初始化程序
MyStation.EM[6].Resting:=Act.Act04_Init[6];
//自动运行程序			
MyStation.EM[6].Running:=Act.Act05_Auto[6];										
//功能块调用程序						 
Act.Act06_IOCall_FB[6]:=TRUE;
//轴功能块调用程序						 
Act.Act07_AxisCall_FB[6]:=TRUE;
//通讯程序						 
Act.Act08_Communication[6]:=TRUE;
//报警信息程序						 
Act.Act09_AlmAndMesg[6]:=NOT MyStation.EM[6].Shielding
					AND MyStation.EmgStop
					AND MyStation.SafetyDoor
					AND MyStation.SafetyRaster;


FOR StationSum := 0 TO StationNum BY 1 DO
//功能状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowAuto		:=	Act.Act05_Auto_Station[EMNumber,StationSum] OR Act.Act04_Init_Station[EMNumber,StationSum]					;//自动状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowManual	:=	Act.Act03_Manual[EMNumber]																		;//手动状态
Act.Act10_Call_Status[EMNumber,StationSum].AlarmReset	:=	MyInput.Reset_Input																		;//复位状态
Act.Act10_Call_Status[EMNumber,StationSum].Aborting		:= NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor				;//急停中止
Act.Act10_Call_Status[EMNumber,StationSum].StopCmd		:=	MyStation.EM[EMNumber].Stopping	AND NOT MyStation.EM[EMNumber].Resting		;//停止
Act.Act10_Call_Status[EMNumber,StationSum].DoorAborting:=	NOT MyStation.EmgStop	OR NOT MyStation.SafetyDoor				;//门禁中止																		
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[1]	:= MyStation.ProductionMode															;//生产模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[2]	:= MyStation.MaintenanceMode														;//维护模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[3]	:= Act.Act04_Init_Station[EMNumber,StationSum];//初始化模式												
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[4] 	:= Act.Act03_Manual[EMNumber];//手动模式									
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[5] 	:= MyStation.MaintenanceMode;//维修模式			
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[0]	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[1]	:= NOT	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //未复
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[2]	:=	MyStation.EMStation[EMNumber,StationSum].Resting;  //复位中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[3]	:=	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //复位完成
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[4]	:=	Device_Starting;  //自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[5]	:=	Device_Starting;  //单步自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[6]	:=	MyStation.EM[EMNumber].Stopping;  //暂停中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[7]	:=	NOT MyStation.SafetyDoor AND FALSE;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[8]	:=	NOT MyStation.EmgStop;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].AlarmShield	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
END_FOR;

Act.Act10_Call_Status[EMNumber,0].AllowAuto:=Act.Act10_Call_Status[EMNumber,1].AllowAuto OR	Act.Act10_Call_Status[EMNumber,1].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,2].AllowAuto OR	Act.Act10_Call_Status[EMNumber,3].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,4].AllowAuto OR	Act.Act10_Call_Status[EMNumber,5].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,6].AllowAuto OR	Act.Act10_Call_Status[EMNumber,7].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,8].AllowAuto OR	Act.Act10_Call_Status[EMNumber,9].AllowAuto
																				OR	(Act.Act05_Auto_Station[EMNumber,0] OR Act.Act04_Init_Station[EMNumber,0]);

//--------------输入-----------------------------------//
usiEM01Index:=USINT#9;//工位号
bEM01_Start:=EM06V.Process_steps[0]=100;//计时开始									
bEM01_Stop:=NOT (EM06V.Process_steps[0]=220);//计时结束
bEM01_Run:=Act.Act05_Auto_Station[6,0];//工位自动									
														
abEM01ActionStart[1] :=EM06V.Process_steps[0]=100; //1.压保护盖Z轴到焊接位，激光焊接Z轴到对焦位，离焦量遮光焊接遮光气缸伸出					
abEM01ActionDone[1]	 :=EM06V.Process_steps[0]=110; 
ausiEM01ActionParallelNum[1]:=0;
abEM01ActionStart[2] :=EM06V.Process_steps[0]=110; //2.激光位移检测				
abEM01ActionDone[2]	 :=EM06V.Process_steps[0]=120; 
ausiEM01ActionParallelNum[2]:=0;
abEM01ActionStart[3] :=EM06V.Process_steps[0]=120; //3.离焦量遮光气缸回退		
abEM01ActionDone[3]	 :=EM06V.Process_steps[0]=140; 
ausiEM01ActionParallelNum[3]:=0;
abEM01ActionStart[4] :=EM06V.Process_steps[0]=140; //4.焊接		
abEM01ActionDone[4]	 :=EM06V.Process_steps[0]=0; 
ausiEM01ActionParallelNum[4]:=0;
abEM01ActionStart[5] :=EM06V.Process_steps[0]=210; //5.激光焊接Z轴到对焦位2，离焦量遮光退回，焊接遮光气缸伸出，焊接
abEM01ActionDone[5]	 :=EM06V.Process_steps[0]=220; 
ausiEM01ActionParallelNum[5]:=0;
abEM01ActionStart[6] :=EM06V.Process_steps[0]=220; //6.激光焊接Z轴到等待位，离焦量遮光伸出，焊接遮光气缸伸出		
abEM01ActionDone[6]	 :=EM06V.Process_steps[0]=0; 
ausiEM01ActionParallelNum[6]:=0;
//最多62个动作	

//--------------计时-----------------------------------//	
//计时结束 把工位总时间存储进63步									
rtgEM01_Stop(CLK:=bEM01_Stop);									
IF rtgEM01_Stop.Q AND bEM01TimerStart THEN 									
	bEM01TimerStart:=FALSE;	
	FOR uiIndex:=1 TO 62 BY 1 DO															
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);														
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;
	HC_OmronUtils.TimeToNanoSec(In:=tEM01,Out=>liEM01ActionTimeTemp2);
	liEM01ActionTimeTemp2:=liEM01ActionTimeTemp2/1000000;								
	IF liEM01ActionTimeTemp2>LINT#65535 THEN //UINT 范围0-65535，越界处理								
		auiEMTime[usiEM01Index,63]:=65535;							
	ELSE								
		auiEMTime[usiEM01Index,63]:=TO_UINT(liEM01ActionTimeTemp2);							
	END_IF;		
	ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储 
	ausiActionParallelNum[uiFIFOlen]:=USINT#0;//动作并行号 
	auiActionNum[uiFIFOlen]:=UINT#63;//动作号	
	auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,63];//动作时间								
	uiFIFOlen:=uiFIFOlen+1;								
	IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)								
		uiFIFOlen:=166;							
	END_IF;								
END_IF;	

//开始计时									
rtgEM01_Start(CLK:=bEM01_Start);									
IF rtgEM01_Start.Q THEN 									
	bEM01TimerStart:=TRUE;								
	Clear(atEM01ActionStart);								
	Clear(atEM01ActionDone);								
	Clear(abEM01ActionRun);																
END_IF;									
									
//计时									
bEM01TimerEnable:=bEM01TimerStart AND bEM01_Run;									
atEM01(In:=bEM01TimerEnable,PT:=T#1D,Reset:=rtgEM01_Start.Q,ET=>tEM01);									
									
//动作时间计算&数据进缓存									
IF bEM01TimerStart THEN 									
	FOR uiIndex:=1 TO 62 BY 1 DO								
		artgEM01ActionStart[uiIndex](CLK:=abEM01ActionStart[uiIndex]);							
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);							
	    IF artgEM01ActionStart[uiIndex].Q THEN  //开始时刻								
			atEM01ActionStart[uiIndex]:=tEM01;						
			abEM01ActionRun[uiIndex]:=TRUE;//防止动作完成信号反复触发，导致数据量激增						
		END_IF;							
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;								
END_IF;									
									
								
									
//--------------输出-----------------------------------//									
auiEMTime[usiEM01Index,1]	:=auiEMTime[usiEM01Index,1]	; //第1个动作时间							
auiEMTime[usiEM01Index,2]	:=auiEMTime[usiEM01Index,2]	; //第2个动作时间							
auiEMTime[usiEM01Index,3]	:=auiEMTime[usiEM01Index,3]	; //第3个动作时间							
auiEMTime[usiEM01Index,4]	:=auiEMTime[usiEM01Index,4]	; //第4个动作时间							
auiEMTime[usiEM01Index,5]	:=auiEMTime[usiEM01Index,5]	; //第5个动作时间							
auiEMTime[usiEM01Index,6]	:=auiEMTime[usiEM01Index,6]	; //第6个动作时间							
// auiEMTime[usiEM01Index,7]	:=auiEMTime[usiEM01Index,7]	; //第7个动作时间							
// auiEMTime[usiEM01Index,8]	:=auiEMTime[usiEM01Index,8]	; //第8个动作时间							
// auiEMTime[usiEM01Index,9]	:=auiEMTime[usiEM01Index,9]	; //第9个动作时间							
// auiEMTime[usiEM01Index,10]	:=auiEMTime[usiEM01Index,10]	; //第10个动作时间
// auiEMTime[usiEM01Index,11]	:=auiEMTime[usiEM01Index,11]	; //第11个动作时间							
// auiEMTime[usiEM01Index,12]	:=auiEMTime[usiEM01Index,12]	; //第12个动作时间							
auiEMTime[usiEM01Index,63]	:=auiEMTime[usiEM01Index,63]	; //第63个动作时间

(********************************************	1#保护盖条码扫码流程		*********************************************)
IF HMI_Function_Enable[6,13] THEN
   Cell_Info[6,2].ProtectCoverScanFinish:=TRUE;
   Cell_Info[6,2].ProtectCoverSN:='1' ;
   
   Cell_Info[6,3].ProtectCoverScanFinish:=TRUE;
   Cell_Info[6,3].ProtectCoverSN:='2' ;   
END_IF ;


TON_Scan1(In:=SR_ScanCode1.ScanStep>0, PT:=T#15S);
CASE SR_ScanCode1.ScanStep	OF
	0://流程开始
		IF Act.Act05_Auto_Station[6,2]
			AND EM06V.Process_steps[4]=150
			AND NOT HMI_Function_Enable[6,13]
			AND NOT Cell_Info[6,2].ProtectCoverScanFinish
		THEN
			EM06V.ScanCode1.In.Execute:=FALSE;
			SR_ScanCode1.ScanStep:=10;
		END_IF;
	10://扫码触发
		EM06V.ScanCode1.In.Execute:=TRUE;
		SR_ScanCode1.ScanStep:=20;
	20://判断扫码结果
		//保护盖条码规则校验
		SR_ScanCode1.CodeSNCheck1:=HMI_RecipeData.ProtectCoverSNCheck;
		SR_ScanCode1.CodeSNCheck2:=LEFT(STR:=EM06V.ScanCode1.Out.BarCodeString, SIZE:=LEN(STR:=HMI_RecipeData.ProtectCoverSNCheck));
		IF HMI_Function_Enable[6,13]
		THEN
			Cell_Info[6,2].ProtectCoverScanFinish:=TRUE;
			Cell_Info[6,2].ProtectCoverSN:=EM06V.ScanCode1.Out.BarCodeString;
			SR_ScanCode1.ScanStep:=40;
		ELSIF EM06V.ScanCode1.Out.ReadSuccess//扫码OK
			AND (NOT HMI_Function_Enable[6,14]
			AND SR_ScanCode1.CodeSNCheck1=SR_ScanCode1.CodeSNCheck2
			OR HMI_Function_Enable[6,14])
		THEN
			Cell_Info[6,2].ProtectCoverScanFinish:=TRUE;
			Cell_Info[6,2].ProtectCoverSN:=EM06V.ScanCode1.Out.BarCodeString;
			SR_ScanCode1.ScanStep:=40;
		ELSIF EM06V.ScanCode1.Out.ReadSuccess
			AND NOT HMI_Function_Enable[6,14]
			AND SR_ScanCode1.CodeSNCheck1<>SR_ScanCode1.CodeSNCheck2//扫码OK+规则校验NG
		THEN
			Cell_Info[6,2].ProtectCoverSN:=EM06V.ScanCode1.Out.BarCodeString;
				SR_ScanCode1.ErrOut.Err_Check:=TRUE;//规则校验错误
			SR_ScanCode1.ScanStep:=40;
		ELSIF EM06V.ScanCode1.Out.ReadFailure//扫码NG
		THEN
			SR_ScanCode1.ErrOut.Err_ScanFailure:=TRUE;//扫码失败
			SR_ScanCode1.ScanStep:=40;
		ELSIF TON_Scan1.Q
		THEN
			SR_ScanCode1.ErrOut.Err_OverTime:=TRUE;//超时错误
			SR_ScanCode1.ScanStep:=40;
		END_IF;
	40://流程结束
		EM06V.ScanCode1.In.Execute:=FALSE;
		SR_ScanCode1.ScanStep:=0;
		
END_CASE;

(********************************************	2#保护盖条码扫码流程		*********************************************)
TON_Scan2(In:=SR_ScanCode2.ScanStep>0, PT:=T#15S);
CASE SR_ScanCode2.ScanStep	OF
	0://流程开始
		IF Act.Act05_Auto_Station[6,3]
			AND EM06V.Process_steps[5]=150
			AND NOT HMI_Function_Enable[6,13]
			AND NOT Cell_Info[6,3].ProtectCoverScanFinish
		THEN
			EM06V.ScanCode2.In.Execute:=FALSE;
			SR_ScanCode2.ScanStep:=10;
		END_IF;
	10://扫码触发
		EM06V.ScanCode2.In.Execute:=TRUE;
		SR_ScanCode2.ScanStep:=20;
	20://判断扫码结果
		//保护盖条码规则校验
		SR_ScanCode2.CodeSNCheck1:=HMI_RecipeData.ProtectCoverSNCheck;
		SR_ScanCode2.CodeSNCheck2:=LEFT(STR:=EM06V.ScanCode2.Out.BarCodeString, SIZE:=LEN(STR:=HMI_RecipeData.ProtectCoverSNCheck));
		IF HMI_Function_Enable[6,13]
		THEN
			Cell_Info[6,3].ProtectCoverScanFinish:=TRUE;
			Cell_Info[6,3].ProtectCoverSN:=EM06V.ScanCode2.Out.BarCodeString;
			SR_ScanCode2.ScanStep:=40;
		ELSIF EM06V.ScanCode2.Out.ReadSuccess//扫码OK
			AND (NOT HMI_Function_Enable[6,14]
			AND SR_ScanCode2.CodeSNCheck1=SR_ScanCode2.CodeSNCheck2
			OR HMI_Function_Enable[6,14])
		THEN
			Cell_Info[6,3].ProtectCoverScanFinish:=TRUE;
			Cell_Info[6,3].ProtectCoverSN:=EM06V.ScanCode2.Out.BarCodeString;
			SR_ScanCode2.ScanStep:=40;
		ELSIF EM06V.ScanCode2.Out.ReadSuccess
			AND NOT HMI_Function_Enable[6,14]
			AND SR_ScanCode2.CodeSNCheck1<>SR_ScanCode2.CodeSNCheck2//扫码OK+规则校验NG
		THEN
			Cell_Info[6,3].ProtectCoverSN:=EM06V.ScanCode2.Out.BarCodeString;
				SR_ScanCode2.ErrOut.Err_Check:=TRUE;//规则校验错误
			SR_ScanCode2.ScanStep:=40;
		ELSIF EM06V.ScanCode2.Out.ReadFailure//扫码NG
		THEN
			SR_ScanCode2.ErrOut.Err_ScanFailure:=TRUE;//扫码失败
			SR_ScanCode2.ScanStep:=40;
		ELSIF TON_Scan2.Q
		THEN
			SR_ScanCode2.ErrOut.Err_OverTime:=TRUE;//超时错误
			SR_ScanCode2.ScanStep:=40;
		END_IF;
	40://流程结束
		EM06V.ScanCode2.In.Execute:=FALSE;
		SR_ScanCode2.ScanStep:=0;
		
END_CASE;

IF Act.Act04_Init_Station[6,3] AND EM06V.Init_Steps[3]=70 THEN
	IF Cell_Info[6,1].Quality<>0
		AND EM06V.Axis_Y2.Out.CurrentPos>=HMI_RecipeData.EM06.Axis_Y2.Location_Postion[3]-3
		AND EM06V.Axis_Y2.Out.Homed
		AND EM06V.Cy_Up2.Out.XV
	THEN
		EM06V.Init_Steps[3]:=80;
	ELSE 
		EM06V.Init_Steps[3]:=110;
	END_IF;
END_IF;

//SV22_电芯下板链线Z轴安全信号
EM07V.Z1_SafetySignal:=EM07V.Axis_Z1.Out.CurrentPos<=HMI_RecipeData.EM07.Axis_Z1.Location_Postion[1]+3
													AND EM07V.Axis_Z1.Out.Homed;
//SV24_电芯上板链线X轴安全信号-->EM05环轨模组
EM07V.X1_SafetySignal_ToEM05:=(ABS(EM07V.Axis_X1.Out.CurrentPos-HMI_RecipeData.EM07.Axis_X1.Location_Postion[1])>=3
													AND EM07V.Axis_X1.Out.Homed)
													OR EM07V.Z1_SafetySignal;
//SV24_电芯上板链线X轴安全信号-->EM08下料拉带模组
EM07V.X1_SafetySignal_ToEM08:=(ABS(EM07V.Axis_X1.Out.CurrentPos-HMI_RecipeData.EM07.Axis_X1.Location_Postion[2])>=3
													AND EM07V.Axis_X1.Out.Homed)
													OR EM07V.Z1_SafetySignal;

FOR StationSum := 0 TO StationNum BY 1 DO
	StationInit_R[StationSum](Clk:=MyStation.EMStation[EMNumber,StationSum].Init OR Act.Act04_Init[EMNumber]);
	IF  StationInit_R[StationSum].Q 
	THEN 
		MyStation.EMStation[EMNumber,StationSum].ResetComplete :=FALSE;
	END_IF;
    IF 	(MyStation.EMStation[EMNumber,StationSum].Init 
		OR Act.Act04_Init[EMNumber])
		AND Inital_Runing
		AND MyInput.AutoSwitch_Input
		AND NOT MyStation.EM[EMNumber].Shielding
		AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
		AND NOT MyStation.EM[EMNumber].IsAlarm
		AND NOT MyStation.EM[0].Running
		AND NOT OperationOut.Abort
		AND NOT OperationOut.Stop
		AND NOT OperationOut.Hold
		AND NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete
	THEN 
		Act.Act04_Init_Station[EMNumber,StationSum] := TRUE;
	ELSE
		Act.Act04_Init_Station[EMNumber,StationSum] := FALSE;
	END_IF;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	IF  MyStation.EMStation[EMNumber,StationSum].ResetComplete OR  MyStation.EMStation[EMNumber,StationSum].Shielding THEN 
		MyStation.EM[EMNumber].ResetComplete :=TRUE;
	ELSIF NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
	THEN 
		MyStation.EM[EMNumber].ResetComplete := FALSE;
		EXIT;
	END_IF;
END_FOR;

IKey:=TRUE; IF Act.Act09_AlmAndMesg[7] THEN MyStation.EM[7].IsAlarm:= Search_Alarm(H_Messages.Station[7].Object_Alarm) OR H_Messages.Station[7].Alarm; (********************报警信息********************)
