m[18] := EM07V.Axis_R1.Out.Alarm_Out[6]; //EM07电芯中转模组:SV23电芯上板链线R轴柔性回弹报警 H_Messages.Station[7].Object_Alarm[19] := EM07V.Axis_R1.Out.Alarm_Out[7]; //EM07电芯中转模组:SV23电芯上板链线R轴正限位开关报警 H_Messages.Station[7].Object_Alarm[20] := EM07V.Axis_R1.Out.Alarm_Out[8]; //EM07电芯中转模组:SV23电芯上板链线R轴负限位开关报警 H_Messages.Station[7].Object_Alarm[21] := EM07V.Axis_R1.Out.Alarm_Out[9]; //EM07电芯中转模组:SV23电芯上板链线R轴未使能报警 //SV24电芯上板链线X轴报警 H_Messages.Station[7].Object_Alarm[22] := EM07V.Axis_X1.Out.Alarm; //EM07电芯中转模组:SV24电芯上板链线X轴驱动器发生错误 H_Messages.Station[7].Object_Alarm[23] := EM07V.Axis_X1.Out.Alarm_Out[0]; //EM07电芯中转模组:SV24电芯上板链线X轴驱动器通讯故障报警 H_Messages.Station[7].Object_Alarm[24] := EM07V.Axis_X1.Out.Alarm_Out[1]; //EM07电芯中转模组:SV24电芯上板链线X轴轴故障报警 H_Messages.Station[7].Object_Alarm[25] := EM07V.Axis_X1.Out.Alarm_Out[2]; //EM07电芯中转模组:SV24电芯上板链线X轴回原安全条件不满足报警 H_Messages.Station[7].Object_Alarm[26] := EM07V.Axis_X1.Out.Alarm_Out[3]; //EM07电芯中转模组:SV24电芯上板链线X轴回原中原点或负限位异常 H_Messages.Station[7].Object_Alarm[27] := EM07V.Axis_X1.Out.Alarm_Out[4]; //EM07电芯中转模组:SV24电芯上板链线X轴轴运动安全条件不满足报警 H_Messages.Station[7].Object_Alarm[28] := EM07V.Axis_X1.Out.Alarm_Out[5]; //EM07电芯中转模组:SV24电芯上板链线X轴扭矩当前值超过阈值报警 H_Messages.Station[7].Object_Alarm[29] := EM07V.Axis_X1.Out.Alarm_Out[6]; //EM07电芯中转模组:SV24电芯上板链线X轴柔性回弹报警 H_Messages.Station[7].Object_Alarm[30] := EM07V.Axis_X1.Out.Alarm_Out[7]; //EM07电芯中转模组:SV24电芯上板链线X轴正限位开关报警 H_Messages.Station[7].Object_Alarm[31] := EM07V.Axis_X1.Out.Alarm_Out[8]; //EM07电芯中转模组:SV24电芯上板链线X轴负限位开关报警 H_Messages.Station[7].Object_Alarm[32] := EM07V.Axis_X1.Out.Alarm_Out[9]; //EM07电芯中转模组:SV24电芯上板链线X轴未使能报警 //CY0焊接治具下料夹爪气缸报警 H_Messages.Station[7].Object_Alarm[33] := EM07V.Cy_Clamp1.Out.Alarm_Out[0]; //EM07电芯中转模组:焊接治具下料夹爪气缸气缸R缩回安全条件不满足报警标志 H_Messages.Station[7].Object_Alarm[34] := EM07V.Cy_Clamp1.Out.Alarm_Out[1]; //EM07电芯中转模组:焊接治具下料夹爪气缸气缸V伸出安全条件不满足报警标志 H_Messages.Station[7].Object_Alarm[35] := EM07V.Cy_Clamp1.Out.Alarm_Out[2]; //EM07电芯中转模组:焊接治具下料夹爪气缸气缸缩回R/X100202 超时报警标志 H_Messages.Station[7].Object_Alarm[36] := EM07V.Cy_Clamp1.Out.Alarm_Out[3]; //EM07电芯中转模组:焊接治具下料夹爪气缸气缸伸出V/X100201 超时报警标志
