[18] := EM07V.Axis_R1.Out.Tips_Out[7]; //EM07电芯中转模组:SV23电芯上板链线R轴多重触发报警提示 H_Messages.Station[7].Object_Warning[19] := EM07V.Axis_R1.Out.Tips_Out[8]; //EM07电芯中转模组:SV23电芯上板链线R轴整机倍率为0提示 //SV24电芯上板链线X轴警告 H_Messages.Station[7].Object_Warning[20] := EM07V.Axis_X1.Out.Warning; //EM07电芯中转模组:SV24电芯上板链线X轴驱动器发生警告 H_Messages.Station[7].Object_Warning[21] := EM07V.Axis_X1.Out.Tips_Out[0]; //EM07电芯中转模组:SV24电芯上板链线X轴未使能提示 H_Messages.Station[7].Object_Warning[22] := EM07V.Axis_X1.Out.Tips_Out[1]; //EM07电芯中转模组:SV24电芯上板链线X轴未回原提示 H_Messages.Station[7].Object_Warning[23] := EM07V.Axis_X1.Out.Tips_Out[2]; //EM07电芯中转模组:SV24电芯上板链线X轴驱动器警告输入 H_Messages.Station[7].Object_Warning[24] := EM07V.Axis_X1.Out.Tips_Out[3]; //EM07电芯中转模组:SV24电芯上板链线X轴轴扭矩超过额定值提示 H_Messages.Station[7].Object_Warning[25] := EM07V.Axis_X1.Out.Tips_Out[4]; //EM07电芯中转模组:SV24电芯上板链线X轴驱动器通讯故障 H_Messages.Station[7].Object_Warning[26] := EM07V.Axis_X1.Out.Tips_Out[5]; //EM07电芯中转模组:SV24电芯上板链线X轴暂停对比提示 H_Messages.Station[7].Object_Warning[27] := EM07V.Axis_X1.Out.Tips_Out[6]; //EM07电芯中转模组:SV24电芯上板链线X轴回零接近速度过快提示 H_Messages.Station[7].Object_Warning[28] := EM07V.Axis_X1.Out.Tips_Out[7]; //EM07电芯中转模组:SV24电芯上板链线X轴多重触发报警提示 H_Messages.Station[7].Object_Warning[29] := EM07V.Axis_X1.Out.Tips_Out[8]; //EM07电芯中转模组:SV24电芯上板链线X轴整机倍率为0提示 //CY0焊接治具下料夹爪气缸警告 H_Messages.Station[7].Object_Warning[30] := EM07V.Cy_Clamp1.Out.Tips_Out[0]; //EM07电芯中转模组:焊接治具下料夹爪气缸气缸缩回R预测性提示。动作时间超过记录时间时 ON H_Messages.Station[7].Object_Warning[31] := EM07V.Cy_Clamp1.Out.Tips_Out[1]; //EM07电芯中转模组:焊接治具下料夹爪气缸气缸伸出V预测性提示。动作时间大于记录时间时 ON H_Messages.Station[7].Object_Warning[32] := EM07V.Cy_Clamp1.Out.Tips_Out[2]; //EM07电芯中转模组:焊接治具下料夹爪气缸气缸暂停对比提示X100201/X100202 H_Messages.Station[7].Object_Warning[33] := EM07V.Cy_Clamp1.Out.Tips_Out[3]; //EM07电芯中转模组:焊接治具下料夹爪气缸点动时工位状态不对报警
