(********************自定义报警********************)
IF (Cell_Info[7,0].Quality<>0 AND NOT EM07V.Sen_HaveCell1.Out.Filtered_Q OR Cell_Info[7,0].Quality=0 AND EM07V.Sen_HaveCell1.Out.Filtered_Q ) AND NOT HMI_TestMode_Enable AND EM07V.Z1_SafetySignal AND Act.Act05_Auto[7] AND NOT HMI_Function_Enable[7,49] THEN H_Messages.Station[7].User_Alarm[0]:=TRUE;//EM07电芯中转模组：夹爪电芯有料感应与有料记忆不相符；请检查焊接治具下料电缸感应 SQ01-17/SQ02-114 END_IF;
