IF EM07H_Cy[0].H_Out.ErrCode = 1 THEN H_Messages.Station[7].User_Alarm[9]:=TRUE;//EM07电芯中转模组：电动夹爪报警1：位置超差报警 END_IF; IF EM07H_Cy[0].H_Out.ErrCode = 2 THEN H_Messages.Station[7].User_Alarm[10]:=TRUE;//EM07电芯中转模组：电动夹爪报警2：速度超差报警 END_IF; IF EM07H_Cy[0].H_Out.ErrCode = 3 THEN H_Messages.Station[7].User_Alarm[11]:=TRUE;//EM07电芯中转模组：电动夹爪报警3：堵转报警 END_IF; IF EM07H_Cy[0].H_Out.ErrCode = 4 THEN H_Messages.Station[7].User_Alarm[12]:=TRUE;//EM07电芯中转模组：电动夹爪报警4：伺服未就绪报警 END_IF; IF EM07H_Cy[0].H_Out.ErrCode = 5 THEN H_Messages.Station[7].User_Alarm[13]:=TRUE;//EM07电芯中转模组：电动夹爪报警5：过流报警 END_IF; IF EM07H_Cy[0].H_Out.ErrCode = 6 THEN H_Messages.Station[7].User_Alarm[14]:=TRUE;//EM07电芯中转模组：电动夹爪报警6：欠压报警 END_IF;
IF EM07H_Cy[0].H_Out.ErrCode = 10 THEN H_Messages.Station[7].User_Alarm[15]:=TRUE;//EM07电芯中转模组：电动夹爪报警A：夹爪气缸张开超时 END_IF; IF EM07H_Cy[0].H_Out.ErrCode = 11 THEN H_Messages.Station[7].User_Alarm[16]:=TRUE;//EM07电芯中转模组：电动夹爪报警B：夹爪气缸夹紧超时 END_IF; IF EM07H_Cy[0].H_Out.ErrCode = 12 THEN H_Messages.Station[7].User_Alarm[17]:=TRUE;//EM07电芯中转模组：电动夹爪报警C：下压气缸上升超时 END_IF; IF EM07H_Cy[0].H_Out.ErrCode = 13 THEN H_Messages.Station[7].User_Alarm[18]:=TRUE;//EM07电芯中转模组：电动夹爪报警D：下压气缸下压超时 END_IF;
