//EM07电芯中转模组：SV22_电芯下板链线Z轴运动干涉，SV24_电芯上板链线X轴不在放料位 IF EM07V.Axis_Z1.In.Location_Select_HMI[3] // EM07电芯中转模组SV22电芯上板链线Z轴定位3触发 AND EM07V.Axis_Z1.In.Location_Move_HMI AND NOT HMI_SafetyCondition_Enable AND NOT EM07V.Axis_X1.Out.PosDone[2] THEN H_Messages.Station[7].HinderToPos[0,2] :=TRUE;//EM07电芯中转模组：SV22_电芯下板链线Z轴运动干涉，SV24_电芯上板链线X轴不在放料位 HMI_EQ.ConflictPopups:=TRUE; END_IF;
