IF R_Change.Q AND Cell_Info[12,12].Quality=0 THEN
	Cell_Info[12,12].Quality:=100;
ELSIF R_Change.Q AND Cell_Info[12,12].Quality=100 THEN
	Cell_Info[12,12].Quality:=90;
ELSIF R_Change.Q AND Cell_Info[12,12].Quality=90 THEN
	Cell_Info[12,12].Quality:=0;
END_IF;

(******************************************料盘参数**************************************************)
IF HMI_RecipeData.EM12PlateSumX<1 THEN//料盘X方向总数，不能小于1
	HMI_RecipeData.EM12PlateSumX:=1;
END_IF;
IF HMI_RecipeData.EM12PlateSumRobot<1 THEN//料盘Y方向总数，不能小于1
	HMI_RecipeData.EM12PlateSumRobot:=1;
END_IF;

//当前取料次数>=总次数，改变料盘属性
IF EM12P.PlateTakeNum>=HMI_RecipeData.EM12PlateSumX*HMI_RecipeData.EM12PlateSumRobot
THEN
	IF Cell_Info[12,12].Quality=100 THEN
		Cell_Info[12,12].Quality:=90;
	END_IF;
	EM12P.PlateTakeNum:=0;
END_IF;
//无料时当前取料次数清零
IF Cell_Info[12,12].Quality=0 THEN
	EM12P.PlateTakeNum:=0;
END_IF;

//料盘X方向位置
EM12P.PlateTakePositionX:=(EM12P.PlateTakeNum/HMI_RecipeData.EM12PlateSumRobot)+1;
//料盘Y方向位置
EM12P.PlateTakePositionRobot:=(EM12P.PlateTakeNum MOD HMI_RecipeData.EM12PlateSumRobot)+1;
//料盘Y方向等待位
EM12P.PlateTakeWaitPositionRobot:=EM12P.PlateTakePositionRobot+10;
//料盘变距轴跟随模式
IF NOT HMI_Function_Enable[12,1] THEN
	EM12P.PlateSumChange:=HMI_RecipeData.EM12PlateSumX;
	EM12P.PlateTakePositionChange:=EM12P.PlateTakePositionX;
ELSE
	EM12P.PlateSumChange:=HMI_RecipeData.EM12PlateSumRobot;
	EM12P.PlateTakePositionChange:=EM12P.PlateTakePositionRobot;
END_IF;

