//EM12扣支架模组：支架上料机器人运动干涉，未检测到支架上板链线机器人区域安全信号 IF EM12H_Robot[0].In.Location_Auto[22] AND NOT HMI_SafetyCondition_Enable AND NOT EM12V.Robot2_SafetySignal_ToRobot1 THEN EM12H_Robot[0].Out.HinderRobot[3]:=TRUE;//EM12扣支架模组：支架上料机器人运动干涉，未检测到支架上板链线机器人区域安全信号 HMI_EQ.ConflictPopups:=TRUE; END_IF;
(******************************************** 支架上板链线机器人 ********************************************) IF (EM12H_Robot[0].In.Location_Auto[1] OR EM12H_Robot[0].In.Location_Auto[2] OR EM12H_Robot[0].In.Location_Auto[5] OR EM12H_Robot[0].In.Location_Auto[6]) AND NOT HMI_SafetyCondition_Enable AND NOT EM12V.Robot1_SafetySignal_ToRobot2 THEN EM12H_Robot[1].Out.HinderRobot[0]:=TRUE;//EM12扣支架模组：支架上板链线机器人运动干涉，未检测到支架上料机器人区域安全信号 HMI_EQ.ConflictPopups:=TRUE; END_IF;
//EM12扣支架模组：支架上板链线机器人运动干涉，SV48_板链线治具移栽X轴不在工位上 IF EM12H_Robot[0].In.Location_Auto[4] AND NOT HMI_SafetyCondition_Enable AND NOT EM08V.X1_SafetySignal AND NOT MyStation.EM[8].Shielding THEN EM12H_Robot[1].Out.HinderRobot[1]:=TRUE;//EM12扣支架模组：支架上板链线机器人运动干涉，SV48_板链线治具移栽X轴不在工位上 HMI_EQ.ConflictPopups:=TRUE; END_IF;
//EM12扣支架模组：支架上板链线机器人运动干涉，SV47_支架NG缓存Y轴不在NG上料位 IF EM12H_Robot[0].In.Location_Auto[6] AND NOT HMI_SafetyCondition_Enable AND NOT EM12V.Axis_Y1.Out.PosDone[0] THEN EM12H_Robot[1].Out.HinderRobot[2]:=TRUE;//EM12扣支架模组：支架上板链线机器人运动干涉，SV47_支架NG缓存Y轴不在NG上料位 HMI_EQ.ConflictPopups:=TRUE; END_IF;
(*关闭弹框消除提示*) IF NOT HMI_EQ.ConflictPopups THEN Clear(H_Messages.Station[12].HinderToPos); Clear(EM12H_Robot[0].Out.HinderRobot); Clear(EM12H_Robot[1].Out.HinderRobot); END_IF;

(********************************************	检测流程		*********************************************)
TON_Check1(In:=Check1Step>0, PT:=T#10S);
CASE Check1Step	OF
	0://流程开始
		IF Act.Act05_Auto_Station[12,7]
			AND Check1Start
		THEN
			//清除交互信号
			Catl_CcdData.PlcToCcd_Int[18]:=0;
			Catl_CcdData.PlcToCcd_Int[15]:=0;
			EM12V.CCDStart:=FALSE;
			Check1Step:=10;
		END_IF;
	10://检测触发
		Catl_CcdBar.PlcToCcd_String[22]:=Cell_Info[12,17].BettarySN;
		Catl_CcdBar.PlcToCcd_String[23]:=Cell_Info[12,17].CodeSN;
		Catl_CcdData.PlcToCcd_Int[18]:=1;
		Check1Step:=20;
	20://判断检测结果
		EM12V.CCDStart:=EM12V.Robot2PhotoInplace;
		IF Catl_CcdData.PlcToCcd_Int[15]=2//检测OK
			OR HMI_TestMode_Enable//空机模式
			OR HMI_Function_Enable[12,2]//检测功能未启用
		THEN
			Cell_Info[12,17].Quality:=100;
			SupportNGNum1:=0;
			Check1Step:=30;
		ELSIF Catl_CcdData.PlcToCcd_Int[15]=3//检测NG
		THEN
			Cell_Info[12,17].Quality:=10;
			SupportNGNum1:=SupportNGNum1+1;
			Check1Step:=30;
		ELSIF TON_Check1.Q
		THEN
			H_Messages.Station[12].User_Alarm[21]:=TRUE;//EM12扣支架模组：等待支架上料检测CCD返回检测结果超时，请打开CCD软件查看原因！
			Check1Step:=30;
		END_IF;
	30://流程结束
		Check1Start:=FALSE;
		Catl_CcdData.PlcToCcd_Int[18]:=0;
		Catl_CcdData.PlcToCcd_Int[15]:=0;
		EM12V.CCDStart:=FALSE;
		Check1Step:=0;
END_CASE;

R_Check1(Clk:=HMI_Button[12,4]);
F_Check1(Clk:=HMI_Button[12,4]);

//1#检测触发
IF R_Check1.Q THEN
	Catl_CcdBar.PlcToCcd_String[22]:='1#CellHymson0123456789';
	Catl_CcdBar.PlcToCcd_String[23]:='1#CoverHymson0123456789';
	Catl_CcdData.PlcToCcd_Int[18]:=1;
	Catl_CcdData.CcdToPlc_Int[15]:=0;
END_IF;
IF F_Check1.Q THEN
	Catl_CcdData.PlcToCcd_Int[18]:=0;
END_IF;

(*****************************EM12_扣支架模组状态机*****************************) 

EMNumber := 12;//模组编号
StationNum :=8-1 ;//工位数量--数组编号最大为0..9

Act.Act01_Status[12]:=TRUE;//工位状态机程序
Act.Act02_Condition[12]:=TRUE;//循环扫描程序
//手动动运行程序
Act.Act03_Manual[12]:=  MyStatus.StatusManual;	
//初始化程序
MyStation.EM[12].Resting:=Act.Act04_Init[12];
//自动运行程序			
MyStation.EM[12].Running:=Act.Act05_Auto[12];										
//功能块调用程序						 
Act.Act06_IOCall_FB[12]:=TRUE;
//轴功能块调用程序						 
Act.Act07_AxisCall_FB[12]:=TRUE;
//通讯程序						 
Act.Act08_Communication[12]:=TRUE;
//报警信息程序						 
Act.Act09_AlmAndMesg[12]:=NOT MyStation.EM[12].Shielding
					AND MyStation.EmgStop
					AND MyStation.SafetyDoor
					AND MyStation.SafetyRaster;


FOR StationSum := 0 TO StationNum BY 1 DO
//功能状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowAuto		:=	Act.Act05_Auto_Station[EMNumber,StationSum] OR Act.Act04_Init_Station[EMNumber,StationSum]					;//自动状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowManual	:=	Act.Act03_Manual[EMNumber]																		;//手动状态
Act.Act10_Call_Status[EMNumber,StationSum].AlarmReset	:=	MyInput.Reset_Input																		;//复位状态
Act.Act10_Call_Status[EMNumber,StationSum].Aborting		:= NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor				;//急停中止
Act.Act10_Call_Status[EMNumber,StationSum].StopCmd		:=	MyStation.EM[EMNumber].Stopping	AND NOT MyStation.EM[EMNumber].Resting		;//停止
Act.Act10_Call_Status[EMNumber,StationSum].DoorAborting:=	NOT MyStation.EmgStop	OR NOT MyStation.SafetyDoor				;//门禁中止																		
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[1]	:= MyStation.ProductionMode															;//生产模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[2]	:= MyStation.MaintenanceMode														;//维护模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[3]	:= Act.Act04_Init_Station[EMNumber,StationSum];//初始化模式												
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[4] 	:= Act.Act03_Manual[EMNumber];//手动模式									
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[5] 	:= MyStation.MaintenanceMode;//维修模式			
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[0]	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[1]	:= NOT	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //未复
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[2]	:=	MyStation.EMStation[EMNumber,StationSum].Resting;  //复位中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[3]	:=	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //复位完成
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[4]	:=	Device_Starting;  //自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[5]	:=	Device_Starting;  //单步自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[6]	:=	MyStation.EM[EMNumber].Stopping;  //暂停中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[7]	:=	NOT MyStation.SafetyDoor  AND FALSE;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[8]	:=	NOT MyStation.EmgStop AND FALSE;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].AlarmShield	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
END_FOR;

Act.Act10_Call_Status[EMNumber,0].AllowAuto:=Act.Act10_Call_Status[EMNumber,1].AllowAuto OR	Act.Act10_Call_Status[EMNumber,1].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,2].AllowAuto OR	Act.Act10_Call_Status[EMNumber,3].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,4].AllowAuto OR	Act.Act10_Call_Status[EMNumber,5].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,6].AllowAuto OR	Act.Act10_Call_Status[EMNumber,7].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,8].AllowAuto OR	Act.Act10_Call_Status[EMNumber,9].AllowAuto
																				OR	(Act.Act05_Auto_Station[EMNumber,0] OR Act.Act04_Init_Station[EMNumber,0])
																				;

//SV44_支架上料Z轴安全信号-->SV43_支架料盘移栽X轴
EM12V.Z1_SafetySignal_ToX1:=	EM12V.Axis_Z1.Out.CurrentPos<=HMI_RecipeData.EM12.Axis_Z1.Location_Postion[3]+3
													AND EM12V.Axis_Z1.Out.Homed;
//SV45_支架下料Z轴安全信号-->SV43_支架料盘移栽X轴
EM12V.Z2_SafetySignal_ToX1:=	EM12V.Axis_Z2.Out.CurrentPos<=HMI_RecipeData.EM12.Axis_Z2.Location_Postion[3]+3
													AND EM12V.Axis_Z2.Out.Homed;
//SV43_支架料盘移栽X轴安全信号-->支架上料机器人
EM12V.X1_SafetySignal_ToRobot1:=	EM12V.Axis_X1.Out.LargeScalePosDone[1]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[2]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[3]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[4]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[5]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[6]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[7]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[8]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[9]
													OR EM12V.Axis_X1.Out.LargeScalePosDone[10];
//SV46_支架机器人调宽X轴安全信号-->支架上料机器人取顶盖
EM12V.X2_SafetySignal_ToRobot1Load:=		EM12V.Axis_X2.Out.LargeScalePosDone[1]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[2]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[3]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[4]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[5]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[6]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[7]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[8]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[9]
																	OR EM12V.Axis_X2.Out.LargeScalePosDone[10];
//SV46_支架机器人调宽X轴安全信号-->支架上料机器人放顶盖
EM12V.X2_SafetySignal_ToRobot1UnLoad:=	EM12V.Axis_X2.Out.LargeScalePosDone[0];
(************************** 机器人动作条件************************)
EM12V.Robot1.In.Location_SafeCondition:=ARRAY48_TRUE;
IF EM12V.Robot1.Out.Act.Xvalue<>0 AND EM12V.Robot1.Out.Act.Yvalue<>0 AND EM12V.Robot1.Out.Act.Zvalue<>0
THEN
//支架上料机器人安全信号-->SV43_支架料盘移栽X轴
EM12V.Robot1_SafetySignal_ToX1:=EM12V.Robot1.Out.SafetyArea[0];
//支架上料机器人安全信号-->中转平台
EM12V.Robot1_SafetySignal_ToTransfer:=EM12V.Robot1.Out.SafetyArea[1];
//支架上料机器人安全信号-->支架上板链线机器人
EM12V.Robot1_SafetySignal_ToRobot2:=EM12V.Robot1.Out.SafetyArea[2]
														AND NOT EM12V.Robot1ToTransfer;
END_IF;

//支架上料机器人取料标志
IF	EM12V.Robot1.Out.PosDone[0]
	OR NOT EM12V.Robot1_SafetySignal_ToX1
THEN
	EM12V.Robot1ToX1:=FALSE;
END_IF;

//支架上料机器人放料标志
IF	EM12V.Robot1.Out.PosDone[0]
	OR NOT EM12V.Robot1_SafetySignal_ToTransfer
THEN
	EM12V.Robot1ToTransfer:=FALSE;
END_IF;


(************************** 机器人动作条件************************)
EM12V.Robot2.In.Location_SafeCondition:=ARRAY48_TRUE;
IF //EM12V.Robot2.Out.Act.Xvalue<>0 AND EM12V.Robot2.Out.Act.Yvalue<>0 AND EM12V.Robot2.Out.Act.ZvaluE<>0 
	//机器人实时位置
    EM12H_Robot[1].Out.Axis_X1.ActPos <>0 AND EM12H_Robot[1].Out.Axis_Y1.ActPos<>0 AND EM12H_Robot[1].Out.Axis_Z1.ActPos<>0
	THEN
//支架上板链线机器人安全信号-->中转平台
EM12V.Robot2_SafetySignal_ToTransfer:=EM12V.Robot2.Out.SafetyArea[0];
//支架上板链线机器人安全信号-->EM08下料拉带模组
EM12V.Robot2_SafetySignal_ToEM08:=EM12V.Robot2.Out.SafetyArea[1];
//支架上板链线机器人安全信号-->NG位
EM12V.Robot2_SafetySignal_ToNG:=EM12V.Robot2.Out.SafetyArea[2];
//支架上板链线机器人安全信号-->支架上料机器人
EM12V.Robot2_SafetySignal_ToRobot1:=EM12V.Robot2.Out.SafetyArea[3]
														AND NOT EM12V.Robot2ToTransfer
														AND NOT EM12V.Robot2ToNG;

END_IF;;
//支架上板链线机器人取料标志
IF	EM12V.Robot2.Out.PosDone[0]
	OR NOT EM12V.Robot2_SafetySignal_ToTransfer
THEN
	EM12V.Robot2ToTransfer:=FALSE;
END_IF;

//支架上板链线机器人放料标志
IF	EM12V.Robot2.Out.PosDone[0]
	OR NOT EM12V.Robot2_SafetySignal_ToEM08
THEN
	EM12V.Robot2ToEM08:=FALSE;
END_IF;

//支架上板链线机器人放NG料标志
IF	EM12V.Robot2.Out.PosDone[0]
	OR NOT EM12V.Robot2_SafetySignal_ToNG
THEN
	EM12V.Robot2ToNG:=FALSE;
END_IF;

IF Act.Act06_IOCall_FB[12] THEN (* //CT计算 CycleTime( Enable := Act.Act05_Auto ,//计时使能 Reset := MyInput.Reset_Input ,//错误复位 bClear := CycleTime_bClear ,//清除计时，在初始化程序清除 Complete := CycleTime_Complete ,//完成计时，在自动程序中触发 ProgramStep := AutoStep ,//步骤变量 Condition := AutoStep >= 0 ,//需要计时的步骤条件 SysCycleTime := SystemCycleTime ,//系统扫描周期 HMICycleTime := HMICycleTime[0] //输出给HMI用的步骤时间 ); //工位时间汇总 MyStation.EM[12].CT := HMICycleTime[0].StationCycleTime ;
*)
(*****************************CY0进料托盘阻挡气缸1X030101/X030102/Y030111/Y030112*****************************)
EM12V.Cy_Block1_1.In.Shield :=Act.Act10_Call_Status[12,0].AlarmShield;
Cy_Block1_1( Enable :=TRUE, //功能块使能 DisableSelflock_V :=FALSE,//输入自锁 DisableSelflock_R :=FALSE,//输出自锁 SynControl_V :=FALSE,//同步控制 SynControl_R :=FALSE,//同步控制 ManualTrigDelay_V :=1,//手动触发延时 ManualTrigDelay_R :=1,//手动触发延时 AirPressure_Alarm :=FALSE,//关联气源报警信号 CL_In :=EM12V.Cy_Block1_1.In,//控制输入 CL_P :=HMI_RecipeData.EM12.Cy_Block1_1,//控制输出 Status :=Act.Act10_Call_Status[12,0],//工位状态 CL_Out =>EM12V.Cy_Block1_1.Out//控制输出 );
(*****************************CY1进料托盘阻挡气缸2X030103/X030104/Y030113/Y030114*****************************)
EM12V.Cy_Block1_2.In.Shield :=Act.Act10_Call_Status[12,0].AlarmShield;
Cy_Block1_2( Enable :=TRUE, //功能块使能 DisableSelflock_V :=FALSE,//输入自锁 DisableSelflock_R :=FALSE,//输出自锁 SynControl_V :=FALSE,//同步控制 SynControl_R :=FALSE,//同步控制 ManualTrigDelay_V :=1,//手动触发延时 ManualTrigDelay_R :=1,//手动触发延时 AirPressure_Alarm :=FALSE,//关联气源报警信号 CL_In :=EM12V.Cy_Block1_2.In,//控制输入 CL_P :=HMI_RecipeData.EM12.Cy_Block1_2,//控制输出 Status :=Act.Act10_Call_Status[12,0],//工位状态 CL_Out =>EM12V.Cy_Block1_2.Out//控制输出 );
(*****************************CY2进料托盘阻挡气缸3X030201/X030202/Y030211/Y030212*****************************)
EM12V.Cy_Block1_3.In.Shield :=Act.Act10_Call_Status[12,0].AlarmShield;
Cy_Block1_3( Enable :=TRUE, //功能块使能 DisableSelflock_V :=FALSE,//输入自锁 DisableSelflock_R :=FALSE,//输出自锁 SynControl_V :=FALSE,//同步控制 SynControl_R :=FALSE,//同步控制 ManualTrigDelay_V :=1,//手动触发延时 ManualTrigDelay_R :=1,//手动触发延时 AirPressure_Alarm :=FALSE,//关联气源报警信号 CL_In :=EM12V.Cy_Block1_3.In,//控制输入 CL_P :=HMI_RecipeData.EM12.Cy_Block1_3,//控制输出 Status :=Act.Act10_Call_Status[12,0],//工位状态 CL_Out =>EM12V.Cy_Block1_3.Out//控制输出 );
(*****************************CY3进料托盘阻挡气缸4X030203/X030204/Y030213/Y030214*****************************)
EM12V.Cy_Block1_4.In.Shield :=Act.Act10_Call_Status[12,0].AlarmShield;
Cy_Block1_4( Enable :=TRUE, //功能块使能 DisableSelflock_V :=FALSE,//输入自锁 DisableSelflock_R :=FALSE,//输出自锁 SynControl_V :=FALSE,//同步控制 SynControl_R :=FALSE,//同步控制 ManualTrigDelay_V :=1,//手动触发延时 ManualTrigDelay_R :=1,//手动触发延时 AirPressure_Alarm :=FALSE,//关联气源报警信号 CL_In :=EM12V.Cy_Block1_4.In,//控制输入 CL_P :=HMI_RecipeData.EM12.Cy_Block1_4,//控制输出 Status :=Act.Act10_Call_Status[12,0],//工位状态 CL_Out =>EM12V.Cy_Block1_4.Out//控制输出 );
(*****************************CY4进料托盘阻挡气缸5X030301/X030302/Y030311/Y030312*****************************)
EM12V.Cy_Block1_5.In.Shield :=Act.Act10_Call_Status[12,0].AlarmShield;
Cy_Block1_5( Enable :=TRUE, //功能块使能 DisableSelflock_V :=FALSE,//输入自锁 DisableSelflock_R :=FALSE,//输出自锁 SynControl_V :=FALSE,//同步控制 SynControl_R :=FALSE,//同步控制 ManualTrigDelay_V :=1,//手动触发延时 ManualTrigDelay_R :=1,//手动触发延时 AirPressure_Alarm :=FALSE,//关联气源报警信号 CL_In :=EM12V.Cy_Block1_5.In,//控制输入 CL_P :=HMI_RecipeData.EM12.Cy_Block1_5,//控制输出 Status :=Act.Act10_Call_Status[12,0],//工位状态 CL_Out =>EM12V.Cy_Block1_5.Out//控制输出 );
