ST.xhtml:
(********************************************	OEE		*********************************************)
//(********************************信号映射********************************)
//设备运行
HMI_OEE.MachineRuning:=MyStation.EM[0].Running;
//设备报警
HMI_OEE.MachineAlarm:=MyStation.EM[0].IsAlarm ;
//100ms上升沿
HMI_OEE.Signal_100msRT:=Pulse.T_100ms_RT;
//1000ms上升沿
HMI_OEE.Signal_1000msRT:=Pulse.T_1s_RT;

//(********************************计时器********************************)
// IF (SystemTime.Hour>Time_Hour AND SystemTime.Hour<Time_Hour+12)
// 	OR (SystemTime.Hour=Time_Hour AND SystemTime.Minute>=Time_Minute)
// 	OR (SystemTime.Hour=Time_Hour+12 AND SystemTime.Minute<Time_Minute)
// THEN  
//   IF HMI_OEE.ProductDay_Date[6] >24 THEN
//   	Day_Date_6  := T#1.5S ;
// 	ELSIF  HMI_OEE.ProductDay_Date[6] <= 24  THEN
// 	Day_Date_6  := T#0.7S  ;
//   END_IF  ;
//   ELSE 
//     IF HMI_OEE.ProductNight_Date[6] >24 THEN
//   	Day_Date_6  := T#1.5S ;
// 	ELSIF  HMI_OEE.ProductNight_Date[6] <= 24  THEN
// 	Day_Date_6  := T#0.7S  ;
//   END_IF  ;
//   
// END_IF  ;  
  
  
  

//开始计算堵料时间的计时器
MachinePuttyTON_1(
	In:= Cell_Info[13,1].Quality<>0
		AND HMI_OEE.MachineRuning
		AND NOT HMI_TestMode_Enable
	, PT:=T#2.7S );
//开始计算待料时间的计时器
MachineWaitTON_1(
	In:= Cell_Info[4,0].Quality=0
		AND HMI_OEE.MachineRuning
		AND NOT HMI_TestMode_Enable
	, PT:=T#2.7S );
	
WindrowSignal_1 :=	MachinePuttyTON_1.Q;
WaitMaterialsSignal_1 := MachineWaitTON_1.Q;	

// //开始计算固定LOOS堵料时间的计时器
// MachinePuttyTON_1(
// 	In:= Cell_Info[13,1].Quality<>0
// 		AND HMI_OEE.MachineRuning
// 		AND NOT HMI_TestMode_Enable
// 	, PT:=T#2.7S );
// //开始计算固定LOOS待料时间的计时器
// MachineWaitTON_1(
// 	In:= Cell_Info[13,1].Quality=0
// 		AND HMI_OEE.MachineRuning
// 		AND NOT HMI_TestMode_Enable
// 	, PT:=T#2.7S );
// 	
// WindrowSignal_1 :=	MachinePuttyTON_1.Q;
// WaitMaterialsSignal_1 := MachineWaitTON_1.Q;
	
	
//(********************************时段计算********************************)
IF HMI_OEE.DayWorkingTime=-3 THEN
		Time_Hour:=6;
		Time_Minute:=30;
		HMI_OEE.SpanEnd:=3;
ELSIF HMI_OEE.DayWorkingTime=-2 THEN
		Time_Hour:=7;
		Time_Minute:=0;
		HMI_OEE.SpanEnd:=0;
ELSIF HMI_OEE.DayWorkingTime=-1 THEN
		Time_Hour:=7;
		Time_Minute:=30;
		HMI_OEE.SpanEnd:=3;
ELSIF HMI_OEE.DayWorkingTime=0 THEN
		Time_Hour:=8;
		Time_Minute:=0;
		HMI_OEE.SpanEnd:=0;
ELSIF HMI_OEE.DayWorkingTime=1 THEN
		Time_Hour:=8;
		Time_Minute:=30;
		HMI_OEE.SpanEnd:=3;
ELSIF HMI_OEE.DayWorkingTime=2 THEN
		Time_Hour:=9;
		Time_Minute:=0;
		HMI_OEE.SpanEnd:=0;
ELSIF HMI_OEE.DayWorkingTime=3 THEN
		Time_Hour:=9;
		Time_Minute:=30;
		HMI_OEE.SpanEnd:=3;
END_IF;
FOR i:=0 TO 23 DO
HMI_OEE.Span[i]:=(i+UINT_TO_INT(Time_Hour)-8+24)MOD 24;
END_FOR;

//(********************************信号生成********************************)
//每小时数据保存上升沿
SaveOEEData_R(Clk:=SystemTime.Minute=Time_Minute AND SystemTime.Second=0);
HMI_OEE.Signal_SaveOEEDataRT:=SaveOEEData_R.Q;
//白班数据清除上升沿
DayWorkTime_R(Clk:=SystemTime.Hour=Time_Hour AND SystemTime.Minute=Time_Minute AND SystemTime.Second=0);
HMI_OEE.Signal_DayWorkTimeRT:=DayWorkTime_R.Q;
//夜班数据清除上升沿
NightWorkTime_R(Clk:=SystemTime.Hour=Time_Hour+12 AND SystemTime.Minute=Time_Minute AND SystemTime.Second=0);
HMI_OEE.Signal_NightWorkTimeRT:=NightWorkTime_R.Q;

//(********************************产能数据缓存********************************)
IF HMI_OEE.Signal_SaveOEEDataRT
THEN
	//每小时投入数量
	OneHuorLoadSumTem:=HMI_OEE.OEE_Data[0];
	//每小时OK数量
	OneHuorOKSumTem:=HMI_OEE.OEE_Data[1];
	//每小时NG数量
	OneHuorNGSumTem:=HMI_OEE.OEE_Data[2];
	//每小时宕机时间
	OneHuorStopTimeTem:=HMI_OEE.MachineAlarmTime.Hour*60+HMI_OEE.MachineAlarmTime.Minute+
 						INT_TO_REAL(HMI_OEE.MachineAlarmTime.Second/60);//+
//						HMI_OEE.MachineStopTime.Hour*60+HMI_OEE.MachineStopTime.Minute+
//						INT_TO_REAL(HMI_OEE.MachineStopTime.Second/60);
	//每小时上料待机时间
	OneHuorWaitTimeTem:=HMI_OEE.MachineWaitTime.Hour*60+HMI_OEE.MachineWaitTime.Minute+
						INT_TO_REAL(HMI_OEE.MachineWaitTime.Second/60);
	//每小时下料待机时间
	OneHuorPuttyTimeTem:=HMI_OEE.MachinePuttyTime.Hour*60+HMI_OEE.MachinePuttyTime.Minute+
						INT_TO_REAL(HMI_OEE.MachinePuttyTime.Second/60);
END_IF;

//(********************************7天生产数据保存********************************)
IF HMI_OEE.Signal_DayWorkTimeRT//8点0分0秒保存7天OEE数据
THEN
	HMI_OEE7Day[7]:=HMI_OEE7Day[6];
	HMI_OEE7Day[6]:=HMI_OEE7Day[5];
	HMI_OEE7Day[5]:=HMI_OEE7Day[4];
	HMI_OEE7Day[4]:=HMI_OEE7Day[3];
	HMI_OEE7Day[3]:=HMI_OEE7Day[2];
	HMI_OEE7Day[2]:=HMI_OEE7Day[1];
	HMI_OEE7Day[1]:=HMI_OEE;
END_IF;
//数据查看
IF HMI_OEE.DaySearch>7 OR HMI_OEE.DaySearch<1 THEN
	HMI_OEE.DaySearch:=1;
END_IF;
IF HMI_OEE.Signal_1000msRT THEN
	HMI_OEE7Day[0]:=HMI_OEE7Day[HMI_OEE.DaySearch];//7天生产数据查看
END_IF;

//(********************************生产数据清除********************************)
//清除OEE数据
IF (HMI_OEE.Signal_DayWorkTimeRT//8点0分0秒清除OEE数据
	OR HMI_OEE.Signal_NightWorkTimeRT//20点0分0秒清除OEE数据
	OR HMI_OEE.ClearProductDayDate_Button
