	HMI_OEE.MachineStopTime.Second:=0;
	HMI_OEE.MachineWaitTime.Hour:=0;
	HMI_OEE.MachineWaitTime.Minute:=0;
	HMI_OEE.MachineWaitTime.Second:=0;
	OneHuorLoadSumTem:=0;
	OneHuorOKSumTem:=0;
	OneHuorNGSumTem:=0;
	OneHuorStopTimeTem:=0;
	OneHuorPuttyTimeTem:=0;
	OneHuorWaitTimeTem:=0;
