	HMI_OEE.PuttyTime[9]:=0;
	HMI_OEE.PuttyTime[10]:=0;
	HMI_OEE.PuttyTime[11]:=0;
	HMI_OEE.PuttyTime[12]:=0;
	HMI_OEE.PuttyTime[13]:=0;
	HMI_OEE.PuttyTime[14]:=0;
	HMI_OEE.PuttyTime[15]:=0;
	HMI_OEE.PuttyTime[16]:=0;
	HMI_OEE.PuttyTime[17]:=0;
	HMI_OEE.PuttyTime[18]:=0;
	HMI_OEE.PuttyTime[19]:=0;
	HMI_OEE.PuttyTime[8]:=0;
END_IF;

//清除夜班数据
IF (HMI_OEE.Signal_NightWorkTimeRT//20点0分0秒清除OEE数据
	OR HMI_OEE.ClearNight_Button)
THEN
	//夜班每小时投入数量
	HMI_OEE.LoadNumber[21]:=0;
	HMI_OEE.LoadNumber[22]:=0;
