	HMI_OEE.StopTime[1]:=0;
	HMI_OEE.StopTime[2]:=0;
	HMI_OEE.StopTime[3]:=0;
	HMI_OEE.StopTime[4]:=0;
	HMI_OEE.StopTime[5]:=0;
	HMI_OEE.StopTime[6]:=0;
	HMI_OEE.StopTime[7]:=0;
	HMI_OEE.StopTime[20]:=0;
	//夜班每小时上料待机时间
	HMI_OEE.WaitTime[21]:=0;
	HMI_OEE.WaitTime[22]:=0;
	HMI_OEE.WaitTime[23]:=0;
	HMI_OEE.WaitTime[0]:=0;
	HMI_OEE.WaitTime[1]:=0;
	HMI_OEE.WaitTime[2]:=0;
	HMI_OEE.WaitTime[3]:=0;
	HMI_OEE.WaitTime[4]:=0;
	HMI_OEE.WaitTime[5]:=0;
	HMI_OEE.WaitTime[6]:=0;
	HMI_OEE.WaitTime[7]:=0;
	HMI_OEE.WaitTime[20]:=0;
	//夜班每小时下料待机时间
	HMI_OEE.PuttyTime[21]:=0;
	HMI_OEE.PuttyTime[22]:=0;
	HMI_OEE.PuttyTime[23]:=0;
	HMI_OEE.PuttyTime[0]:=0;
	HMI_OEE.PuttyTime[1]:=0;
	HMI_OEE.PuttyTime[2]:=0;
	HMI_OEE.PuttyTime[3]:=0;
	HMI_OEE.PuttyTime[4]:=0;
	HMI_OEE.PuttyTime[5]:=0;
	HMI_OEE.PuttyTime[6]:=0;
	HMI_OEE.PuttyTime[7]:=0;
	HMI_OEE.PuttyTime[20]:=0;
END_IF;

//白班生产总数据清除
IF HMI_OEE.ClearProductDayDate_Button
	OR HMI_OEE.Signal_DayWorkTimeRT
THEN
Clear(HMI_OEE.ProductDay_Date);
//夜班生产总数据清除
ELSIF HMI_OEE.ClearProductNightDate_Button
	OR HMI_OEE.Signal_NightWorkTimeRT
THEN
Clear(HMI_OEE.ProductNight_Date);
END_IF;

OEE_Clear1(CLK:=SystemTime.Hour=8 AND SystemTime.Minute=20 AND SystemTime.Second=0);
IF OEE_Clear1.Q
THEN
	HMI_OEE.MachineStopTime.Hour:=0;
	HMI_OEE.MachineStopTime.Minute:=0;
	HMI_OEE.MachineStopTime.Second:=0;
	HMI_OEE.MachineAlarmTime.Hour:=0;
	HMI_OEE.MachineAlarmTime.Minute:=0;
	HMI_OEE.MachineAlarmTime.Second:=0;
	HMI_OEE.StopTime[8]:=0;
END_IF

OEE_Clear2(CLK:=SystemTime.Hour=20 AND SystemTime.Minute=20 AND SystemTime.Second=0);
IF OEE_Clear2.Q
THEN
	HMI_OEE.MachineStopTime.Hour:=0;
	HMI_OEE.MachineStopTime.Minute:=0;
	HMI_OEE.MachineStopTime.Second:=0;
	HMI_OEE.MachineAlarmTime.Hour:=0;
	HMI_OEE.MachineAlarmTime.Minute:=0;
	HMI_OEE.MachineAlarmTime.Second:=0;
	HMI_OEE.StopTime[20]:=0;
END_IF


//(********************************时间计算********************************)
//循环计数
IF HMI_OEE.Signal_100msRT
THEN
	MachineOpenTime:=MachineOpenTime+1;
END_IF;
//开机时间
IF MachineOpenTime=10
THEN
MachineOpenTime:=0;
HMI_OEE.MachineOpenTime.Second:=HMI_OEE.MachineOpenTime.Second+1;
END_IF;
IF HMI_OEE.MachineOpenTime.Second=60
THEN
HMI_OEE.MachineOpenTime.Second:=0;
HMI_OEE.MachineOpenTime.Minute:=HMI_OEE.MachineOpenTime.Minute+1;
END_IF;
IF HMI_OEE.MachineOpenTime.Minute=60
THEN
HMI_OEE.MachineOpenTime.Minute:=0;
HMI_OEE.MachineOpenTime.Hour:=HMI_OEE.MachineOpenTime.Hour+1;
END_IF;
//生产时间
IF  HMI_OEE.Signal_100msRT AND 
	HMI_OEE.MachineRuning  AND  
	NOT MachinePuttyTON_1.Q  AND 
	NOT MachineWaitTON_1.Q    
THEN
	MachineAutoTime:=MachineAutoTime+1;
END_IF;

IF MachineAutoTime=10
THEN
	MachineAutoTime:=0;
	HMI_OEE.MachineAutoTime.Second:=HMI_OEE.MachineAutoTime.Second+1;
END_IF;
IF HMI_OEE.MachineAutoTime.Second=60
THEN
	HMI_OEE.MachineAutoTime.Second:=0;
	HMI_OEE.MachineAutoTime.Minute:=HMI_OEE.MachineAutoTime.Minute+1;
END_IF;
IF HMI_OEE.MachineAutoTime.Minute=60
THEN
	HMI_OEE.MachineAutoTime.Minute:=0;
	HMI_OEE.MachineAutoTime.Hour:=HMI_OEE.MachineAutoTime.Hour+1;
END_IF;

//报警时间
IF HMI_OEE.Signal_100msRT
	AND HMI_OEE.MachineAlarm
THEN
	MachineAlarmTime:=MachineAlarmTime+1;
END_IF;
IF MachineAlarmTime=10
THEN
	MachineAlarmTime:=0;
	HMI_OEE.MachineAlarmTime.Second:=HMI_OEE.MachineAlarmTime.Second+1;
END_IF;
IF HMI_OEE.MachineAlarmTime.Second=60
THEN
	HMI_OEE.MachineAlarmTime.Second:=0;
	HMI_OEE.MachineAlarmTime.Minute:=HMI_OEE.MachineAlarmTime.Minute+1;
END_IF;
IF HMI_OEE.MachineAlarmTime.Minute=60
THEN
	HMI_OEE.MachineAlarmTime.Minute:=0;
	HMI_OEE.MachineAlarmTime.Hour:=HMI_OEE.MachineAlarmTime.Hour+1;
END_IF;	
//待机时间
IF HMI_OEE.Signal_100msRT
	AND NOT HMI_OEE.MachineAlarm
	AND NOT HMI_OEE.MachineRuning
THEN
	MachineStopTime:=MachineStopTime+1;
END_IF;
IF MachineStopTime=10
THEN
	MachineStopTime:=0;
	HMI_OEE.MachineStopTime.Second:=HMI_OEE.MachineStopTime.Second+1;
END_IF;
IF HMI_OEE.MachineStopTime.Second=60
THEN
	HMI_OEE.MachineStopTime.Second:=0;
	HMI_OEE.MachineStopTime.Minute:=HMI_OEE.MachineStopTime.Minute+1;
END_IF;

//堵料时间
IF HMI_OEE.Signal_100msRT
	AND MachinePuttyTON_1.Q
THEN
	MachinePuttyTime:=MachinePuttyTime+1;
END_IF;
IF MachinePuttyTime=10
THEN
	MachinePuttyTime:=0;
	HMI_OEE.MachinePuttyTime.Second:=HMI_OEE.MachinePuttyTime.Second+1;
END_IF;
IF HMI_OEE.MachinePuttyTime.Second=60
THEN
	HMI_OEE.MachinePuttyTime.Second:=0;
	HMI_OEE.MachinePuttyTime.Minute:=HMI_OEE.MachinePuttyTime.Minute+1;
END_IF;
	
//待料时间
IF HMI_OEE.Signal_100msRT
	AND MachineWaitTON_1.Q
	AND NOT MachinePuttyTON_1.Q
THEN
	MachineWaitTime:=MachineWaitTime+1;
END_IF;
IF MachineWaitTime=10
THEN
	MachineWaitTime:=0;
	HMI_OEE.MachineWaitTime.Second:=HMI_OEE.MachineWaitTime.Second+1;
END_IF;
IF HMI_OEE.MachineWaitTime.Second=60
THEN
	HMI_OEE.MachineWaitTime.Second:=0;
	HMI_OEE.MachineWaitTime.Minute:=HMI_OEE.MachineWaitTime.Minute+1;
END_IF;

//(********************************上料计数********************************)
//投入电芯数量计算触发
LoadSum_R[0].Clk:=Cell_Info[4,0].Quality<>0;
//上料电芯放反NG产品计算触发
LoadSum_R[5].Clk:=Cell_Info[7,0].Quality=6;
//电芯扫码NG产品计算触发
LoadSum_R[10].Clk:=Cell_Info[7,0].Quality=5;
//电芯MESNG产品计算触发
LoadSum_R[15].Clk:=Cell_Info[7,0].Quality=7;
//顶盖上料数量计算触发
