//顶盖蓝膜不良计算触发
LoadSum_R[35].Clk:=Cell_Info[3,0].Quality=20;
//顶盖放反不良计算触发
LoadSum_R[40].Clk:=Cell_Info[3,0].Quality=10;
//顶盖刻码不良计算触发
LoadSum_R[45].Clk:=Cell_Info[3,0].Quality=40;
//顶盖刻码扫码不良计算触发
LoadSum_R[50].Clk:=Cell_Info[3,0].Quality=41;
//顶盖刻码条码等级NG计算触发
LoadSum_R[55].Clk:=Cell_Info[3,0].Quality=42;
//顶盖MESNG计算触发
LoadSum_R[60].Clk:=Cell_Info[3,0].Quality=50;
//顶盖刻码CCDNG计算触发
LoadSum_R[65].Clk:=Cell_Info[3,0].Quality=43;
FOR i:=0 TO 69 DO
