END_FOR;

//(********************************下料计数********************************)
//OK成品计算触发
DownSum_R[0].Clk:=Cell_Info[13,0].OutboundFinish AND Cell_Info[13,0].Quality=100;
//NG成品计算触发
DownSum_R[5].Clk:=Cell_Info[13,0].Quality<>0 AND Cell_Info[13,0].Quality<>100 AND Cell_Info[13,0].Quality>=10;
//1#离焦量NG计算触发
DownSum_R[10].Clk:=Cell_Info[13,0].Quality=10;
//2#离焦量NG计算触发
DownSum_R[15].Clk:=Cell_Info[13,0].Quality=11;
//离焦量双NG计算触发
DownSum_R[20].Clk:=Cell_Info[13,0].Quality=12;
//1#功率NG计算触发
DownSum_R[25].Clk:=Cell_Info[13,0].Quality=20;
//2#功率NG计算触发
DownSum_R[30].Clk:=Cell_Info[13,0].Quality=21;
//功率双NG计算触发
DownSum_R[35].Clk:=Cell_Info[13,0].Quality=22;
//WDDNG计算触发
DownSum_R[40].Clk:=Cell_Info[13,0].Quality=23;
//1#焊印NG计算触发
DownSum_R[45].Clk:=Cell_Info[13,0].Quality=30;
//2#焊印NG计算触发
DownSum_R[50].Clk:=Cell_Info[13,0].Quality=31;
//焊印双NG计算触发
DownSum_R[55].Clk:=Cell_Info[13,0].Quality=32;
//1#极耳NG计算触发
DownSum_R[60].Clk:=Cell_Info[13,0].Quality=40;
//2#极耳NG计算触发
DownSum_R[65].Clk:=Cell_Info[13,0].Quality=41;
//极耳双NG计算触发
DownSum_R[70].Clk:=Cell_Info[13,0].Quality=42;
//1#焊印胶NG计算触发
DownSum_R[75].Clk:=Cell_Info[13,0].Quality=50;
//2#焊印胶NG计算触发
DownSum_R[80].Clk:=Cell_Info[13,0].Quality=51;
//焊印胶双NG计算触发
DownSum_R[85].Clk:=Cell_Info[13,0].Quality=52;
//1#扣支架NG计算触发
DownSum_R[90].Clk:=Cell_Info[13,0].Quality=60;
//2#扣支架NG计算触发
DownSum_R[95].Clk:=Cell_Info[13,0].Quality=61;
//扣支架双NG计算触发
DownSum_R[100].Clk:=Cell_Info[13,0].Quality=62;
//电芯出站MESNG计算触发
DownSum_R[105].Clk:=Cell_Info[13,0].Quality=70;
//1#焊印点胶NG计算触发
DownSum_R[110].Clk:=Cell_Info[13,0].Quality=55;
//2#焊印点胶NG计算触发
DownSum_R[115].Clk:=Cell_Info[13,0].Quality=56;
//焊印点胶双NG计算触发
DownSum_R[120].Clk:=Cell_Info[13,0].Quality=57;
FOR i:=0 TO 125 DO
	DownSum_R[i]();
END_FOR;
//(********************************白班数量计算********************************)
IF (SystemTime.Hour>Time_Hour AND SystemTime.Hour<Time_Hour+12)
	OR (SystemTime.Hour=Time_Hour AND SystemTime.Minute>=Time_Minute)
	OR (SystemTime.Hour=Time_Hour+12 AND SystemTime.Minute<Time_Minute)
THEN
//////////////////////////////////////上料计数//////////////////////////////////////
//投入电芯数量计算触发
	IF LoadSum_R[0].Q  THEN HMI_OEE.ProductDay_Date[0]:=HMI_OEE.ProductDay_Date[0]+1; END_IF;
	IF LoadSum_R[1].Q  THEN HMI_OEE.ProductDay_Date[0]:=HMI_OEE.ProductDay_Date[0]+1; END_IF;
	HMI_OEE.OEE_Data[0]:=HMI_OEE.ProductDay_Date[0];
//上料电芯放反NG产品计算触发
	IF LoadSum_R[5].Q  THEN HMI_OEE.ProductDay_Date[10]:=HMI_OEE.ProductDay_Date[10]+1; END_IF;
	IF LoadSum_R[6].Q  THEN HMI_OEE.ProductDay_Date[10]:=HMI_OEE.ProductDay_Date[10]+1; END_IF;
//电芯扫码NG产品计算触发
	IF LoadSum_R[10].Q  THEN HMI_OEE.ProductDay_Date[11]:=HMI_OEE.ProductDay_Date[11]+1; END_IF;
	IF LoadSum_R[11].Q  THEN HMI_OEE.ProductDay_Date[11]:=HMI_OEE.ProductDay_Date[11]+1; END_IF;
//电芯MESNG产品计算触发
	IF LoadSum_R[15].Q  THEN HMI_OEE.ProductDay_Date[12]:=HMI_OEE.ProductDay_Date[12]+1; END_IF;
	IF LoadSum_R[16].Q  THEN HMI_OEE.ProductDay_Date[12]:=HMI_OEE.ProductDay_Date[12]+1; END_IF;
//顶盖上料数量计算触发
	IF LoadSum_R[20].Q  THEN HMI_OEE.ProductDay_Date[13]:=HMI_OEE.ProductDay_Date[13]+1; END_IF;
	IF LoadSum_R[21].Q  THEN HMI_OEE.ProductDay_Date[13]:=HMI_OEE.ProductDay_Date[13]+1; END_IF;
//顶盖刻码数量计算触发
	IF LoadSum_R[25].Q  THEN HMI_OEE.ProductDay_Date[14]:=HMI_OEE.ProductDay_Date[14]+1; END_IF;
	IF LoadSum_R[26].Q  THEN HMI_OEE.ProductDay_Date[14]:=HMI_OEE.ProductDay_Date[14]+1; END_IF;
//顶盖批次码不良计算触发
	IF LoadSum_R[30].Q  THEN HMI_OEE.ProductDay_Date[15]:=HMI_OEE.ProductDay_Date[15]+1; END_IF;
	IF LoadSum_R[31].Q  THEN HMI_OEE.ProductDay_Date[15]:=HMI_OEE.ProductDay_Date[15]+1; END_IF;
//顶盖蓝膜不良计算触发
	IF LoadSum_R[35].Q  THEN HMI_OEE.ProductDay_Date[16]:=HMI_OEE.ProductDay_Date[16]+1; END_IF;
	IF LoadSum_R[36].Q  THEN HMI_OEE.ProductDay_Date[16]:=HMI_OEE.ProductDay_Date[16]+1; END_IF;
//顶盖放反不良计算触发
	IF LoadSum_R[40].Q  THEN HMI_OEE.ProductDay_Date[17]:=HMI_OEE.ProductDay_Date[17]+1; END_IF;
	IF LoadSum_R[41].Q  THEN HMI_OEE.ProductDay_Date[17]:=HMI_OEE.ProductDay_Date[17]+1; END_IF;
//顶盖刻码不良计算触发
	IF LoadSum_R[45].Q  THEN HMI_OEE.ProductDay_Date[18]:=HMI_OEE.ProductDay_Date[18]+1; END_IF;
	IF LoadSum_R[46].Q  THEN HMI_OEE.ProductDay_Date[18]:=HMI_OEE.ProductDay_Date[18]+1; END_IF;
//顶盖刻码扫码不良计算触发
	IF LoadSum_R[50].Q  THEN HMI_OEE.ProductDay_Date[19]:=HMI_OEE.ProductDay_Date[19]+1; END_IF;
	IF LoadSum_R[51].Q  THEN HMI_OEE.ProductDay_Date[19]:=HMI_OEE.ProductDay_Date[19]+1; END_IF;
//顶盖刻码条码等级NG计算触发
	IF LoadSum_R[55].Q  THEN HMI_OEE.ProductDay_Date[20]:=HMI_OEE.ProductDay_Date[20]+1; END_IF;
	IF LoadSum_R[56].Q  THEN HMI_OEE.ProductDay_Date[20]:=HMI_OEE.ProductDay_Date[20]+1; END_IF;
//顶盖MESNG计算触发
	IF LoadSum_R[60].Q  THEN HMI_OEE.ProductDay_Date[21]:=HMI_OEE.ProductDay_Date[21]+1; END_IF;
	IF LoadSum_R[61].Q  THEN HMI_OEE.ProductDay_Date[21]:=HMI_OEE.ProductDay_Date[21]+1; END_IF;
//顶盖刻码CCDNG计算触发
	IF LoadSum_R[65].Q  THEN HMI_OEE.ProductDay_Date[22]:=HMI_OEE.ProductDay_Date[22]+1; END_IF;
	IF LoadSum_R[66].Q  THEN HMI_OEE.ProductDay_Date[22]:=HMI_OEE.ProductDay_Date[22]+1; END_IF;

//////////////////////////////////////下料计数//////////////////////////////////////
//OK成品计算触发
	IF DownSum_R[0].Q  THEN HMI_OEE.ProductDay_Date[1]:=HMI_OEE.ProductDay_Date[1]+1; END_IF;
	IF DownSum_R[1].Q  THEN HMI_OEE.ProductDay_Date[1]:=HMI_OEE.ProductDay_Date[1]+1; END_IF;
	HMI_OEE.OEE_Data[1]:=HMI_OEE.ProductDay_Date[1];
//NG成品计算触发
	IF DownSum_R[5].Q  THEN HMI_OEE.ProductDay_Date[2]:=HMI_OEE.ProductDay_Date[2]+1; END_IF;
	IF DownSum_R[6].Q  THEN HMI_OEE.ProductDay_Date[2]:=HMI_OEE.ProductDay_Date[2]+1; END_IF;
	HMI_OEE.OEE_Data[2]:=HMI_OEE.ProductDay_Date[2];
//1#离焦量NG计算触发
	IF DownSum_R[10].Q  THEN HMI_OEE.ProductDay_Date[50]:=HMI_OEE.ProductDay_Date[50]+1; END_IF;
	IF DownSum_R[11].Q  THEN HMI_OEE.ProductDay_Date[50]:=HMI_OEE.ProductDay_Date[50]+1; END_IF;
//2#离焦量NG计算触发
	IF DownSum_R[15].Q  THEN HMI_OEE.ProductDay_Date[51]:=HMI_OEE.ProductDay_Date[51]+1; END_IF;
	IF DownSum_R[16].Q  THEN HMI_OEE.ProductDay_Date[51]:=HMI_OEE.ProductDay_Date[51]+1; END_IF;
//离焦量双NG计算触发
	IF DownSum_R[20].Q  THEN HMI_OEE.ProductDay_Date[52]:=HMI_OEE.ProductDay_Date[52]+1; END_IF;
	IF DownSum_R[21].Q  THEN HMI_OEE.ProductDay_Date[52]:=HMI_OEE.ProductDay_Date[52]+1; END_IF;
//1#功率NG计算触发
	IF DownSum_R[25].Q  THEN HMI_OEE.ProductDay_Date[53]:=HMI_OEE.ProductDay_Date[53]+1; END_IF;
	IF DownSum_R[26].Q  THEN HMI_OEE.ProductDay_Date[53]:=HMI_OEE.ProductDay_Date[53]+1; END_IF;
//2#功率NG计算触发
	IF DownSum_R[30].Q  THEN HMI_OEE.ProductDay_Date[54]:=HMI_OEE.ProductDay_Date[54]+1; END_IF;
	IF DownSum_R[31].Q  THEN HMI_OEE.ProductDay_Date[54]:=HMI_OEE.ProductDay_Date[54]+1; END_IF;
//功率双NG计算触发
	IF DownSum_R[35].Q  THEN HMI_OEE.ProductDay_Date[55]:=HMI_OEE.ProductDay_Date[55]+1; END_IF;
	IF DownSum_R[36].Q  THEN HMI_OEE.ProductDay_Date[55]:=HMI_OEE.ProductDay_Date[55]+1; END_IF;
//WDDNG计算触发
	IF DownSum_R[40].Q  THEN HMI_OEE.ProductDay_Date[56]:=HMI_OEE.ProductDay_Date[56]+1; END_IF;
	IF DownSum_R[41].Q  THEN HMI_OEE.ProductDay_Date[56]:=HMI_OEE.ProductDay_Date[56]+1; END_IF;
//1#焊印NG计算触发
	IF DownSum_R[45].Q  THEN HMI_OEE.ProductDay_Date[57]:=HMI_OEE.ProductDay_Date[57]+1; END_IF;
	IF DownSum_R[46].Q  THEN HMI_OEE.ProductDay_Date[57]:=HMI_OEE.ProductDay_Date[57]+1; END_IF;
//2#焊印NG计算触发
	IF DownSum_R[50].Q  THEN HMI_OEE.ProductDay_Date[58]:=HMI_OEE.ProductDay_Date[58]+1; END_IF;
	IF DownSum_R[51].Q  THEN HMI_OEE.ProductDay_Date[58]:=HMI_OEE.ProductDay_Date[58]+1; END_IF;
//焊印双NG计算触发
	IF DownSum_R[55].Q  THEN HMI_OEE.ProductDay_Date[59]:=HMI_OEE.ProductDay_Date[59]+1; END_IF;
	IF DownSum_R[56].Q  THEN HMI_OEE.ProductDay_Date[59]:=HMI_OEE.ProductDay_Date[59]+1; END_IF;
//1#极耳NG计算触发
	IF DownSum_R[60].Q  THEN HMI_OEE.ProductDay_Date[60]:=HMI_OEE.ProductDay_Date[60]+1; END_IF;
	IF DownSum_R[61].Q  THEN HMI_OEE.ProductDay_Date[60]:=HMI_OEE.ProductDay_Date[60]+1; END_IF;
//2#极耳NG计算触发
	IF DownSum_R[65].Q  THEN HMI_OEE.ProductDay_Date[61]:=HMI_OEE.ProductDay_Date[61]+1; END_IF;
	IF DownSum_R[66].Q  THEN HMI_OEE.ProductDay_Date[61]:=HMI_OEE.ProductDay_Date[61]+1; END_IF;
//极耳双NG计算触发
	IF DownSum_R[70].Q  THEN HMI_OEE.ProductDay_Date[62]:=HMI_OEE.ProductDay_Date[62]+1; END_IF;
	IF DownSum_R[71].Q  THEN HMI_OEE.ProductDay_Date[62]:=HMI_OEE.ProductDay_Date[62]+1; END_IF;
//1#焊印胶NG计算触发
	IF DownSum_R[75].Q  THEN HMI_OEE.ProductDay_Date[63]:=HMI_OEE.ProductDay_Date[63]+1; END_IF;
	IF DownSum_R[76].Q  THEN HMI_OEE.ProductDay_Date[63]:=HMI_OEE.ProductDay_Date[63]+1; END_IF;
//2#焊印胶NG计算触发
	IF DownSum_R[80].Q  THEN HMI_OEE.ProductDay_Date[64]:=HMI_OEE.ProductDay_Date[64]+1; END_IF;
	IF DownSum_R[81].Q  THEN HMI_OEE.ProductDay_Date[64]:=HMI_OEE.ProductDay_Date[64]+1; END_IF;
//焊印胶双NG计算触发
	IF DownSum_R[85].Q  THEN HMI_OEE.ProductDay_Date[65]:=HMI_OEE.ProductDay_Date[65]+1; END_IF;
	IF DownSum_R[86].Q  THEN HMI_OEE.ProductDay_Date[65]:=HMI_OEE.ProductDay_Date[65]+1; END_IF;
//1#扣支架NG计算触发
	IF DownSum_R[90].Q  THEN HMI_OEE.ProductDay_Date[66]:=HMI_OEE.ProductDay_Date[66]+1; END_IF;
	IF DownSum_R[91].Q  THEN HMI_OEE.ProductDay_Date[66]:=HMI_OEE.ProductDay_Date[66]+1; END_IF;
//2#扣支架NG计算触发
	IF DownSum_R[95].Q  THEN HMI_OEE.ProductDay_Date[67]:=HMI_OEE.ProductDay_Date[67]+1; END_IF;
	IF DownSum_R[96].Q  THEN HMI_OEE.ProductDay_Date[67]:=HMI_OEE.ProductDay_Date[67]+1; END_IF;
//扣支架双NG计算触发
	IF DownSum_R[100].Q  THEN HMI_OEE.ProductDay_Date[68]:=HMI_OEE.ProductDay_Date[68]+1; END_IF;
	IF DownSum_R[101].Q  THEN HMI_OEE.ProductDay_Date[68]:=HMI_OEE.ProductDay_Date[68]+1; END_IF;
//电芯出站MESNG计算触发
	IF DownSum_R[105].Q  THEN HMI_OEE.ProductDay_Date[69]:=HMI_OEE.ProductDay_Date[69]+1; END_IF;
	IF DownSum_R[106].Q  THEN HMI_OEE.ProductDay_Date[69]:=HMI_OEE.ProductDay_Date[69]+1; END_IF;
//1#焊印点胶NG计算触发
	IF DownSum_R[110].Q  THEN HMI_OEE.ProductDay_Date[70]:=HMI_OEE.ProductDay_Date[70]+1; END_IF;
	IF DownSum_R[111].Q  THEN HMI_OEE.ProductDay_Date[70]:=HMI_OEE.ProductDay_Date[70]+1; END_IF;
//2#焊印点胶NG计算触发
	IF DownSum_R[115].Q  THEN HMI_OEE.ProductDay_Date[71]:=HMI_OEE.ProductDay_Date[71]+1; END_IF;
	IF DownSum_R[116].Q  THEN HMI_OEE.ProductDay_Date[71]:=HMI_OEE.ProductDay_Date[71]+1; END_IF;
//焊印点胶双NG计算触发
	IF DownSum_R[120].Q  THEN HMI_OEE.ProductDay_Date[72]:=HMI_OEE.ProductDay_Date[72]+1; END_IF;
	IF DownSum_R[121].Q  THEN HMI_OEE.ProductDay_Date[72]:=HMI_OEE.ProductDay_Date[72]+1; END_IF;

//白班下料数量（良品数量+不良品数量）
HMI_OEE.ProductDay_Date[3]:=HMI_OEE.ProductDay_Date[1]+HMI_OEE.ProductDay_Date[2];

//转存
PackTags.Admin.ProdProcessedCount[1].AccCount:=TO_DINT(HMI_OEE.ProductDay_Date[1]);
PackTags.Admin.ProdDefectiveCount[1].AccCount:=TO_DINT(HMI_OEE.ProductDay_Date[2]);
PackTags.Admin.ProdConsumedCount[1].AccCount:=PackTags.Admin.ProdProcessedCount[1].AccCount+PackTags.Admin.ProdDefectiveCount[1].AccCount;

//白班良率计算（良品数量/下料数量）
IF HMI_OEE.ProductDay_Date[3]>0 THEN
HMI_OEE.ProductDay_Date[4]:=HMI_OEE.ProductDay_Date[1]/HMI_OEE.ProductDay_Date[3]*REAL#100;
END_IF;
//白班设备CT计算（设备生产时间(秒)/下料数量）
IF HMI_OEE.ProductDay_Date[3]>0 THEN
HMI_OEE.ProductDay_Date[5]:=INT_TO_REAL((HMI_OEE.MachineAutoTime.Hour*3600+
							HMI_OEE.MachineAutoTime.Minute*60+
							HMI_OEE.MachineAutoTime.Second))/
							HMI_OEE.ProductDay_Date[3];
END_IF;	
//白班PPM（60秒/设备CT）
IF HMI_OEE.ProductDay_Date[5]>0 THEN
HMI_OEE.ProductDay_Date[6]:=60/HMI_OEE.ProductDay_Date[5];
END_IF;	
//白班故障率(报警时间（秒）/运行时间（秒）)
IF HMI_OEE.MachineOpenTime.Hour*3600+HMI_OEE.MachineOpenTime.Minute*60+HMI_OEE.MachineOpenTime.Second>0
THEN
HMI_OEE.ProductDay_Date[7]:=INT_TO_REAL((HMI_OEE.MachineAlarmTime.Hour*3600+
						HMI_OEE.MachineAlarmTime.Minute*60+
						HMI_OEE.MachineAlarmTime.Second))/
						INT_TO_REAL((HMI_OEE.MachineOpenTime.Hour*3600+
						HMI_OEE.MachineOpenTime.Minute*60+
						HMI_OEE.MachineOpenTime.Second))
						*REAL#100;
END_IF;
//白班故障时间（分钟）（故障小时*60+故障分钟+故障秒钟/60）
HMI_OEE.ProductDay_Date[8]:=HMI_OEE.MachineAlarmTime.Hour*60+
						HMI_OEE.MachineAlarmTime.Minute+
						INT_TO_REAL(HMI_OEE.MachineAlarmTime.Second)/60;
//白班实时PPM（实时5min生产数量/5min）
IF HMI_OEE.MachineRuning AND HMI_OEE.Signal_1000msRT THEN
	FOR i:=0 TO 299 BY 1 DO
	HMI_OEE.ProductNum[300-i]:=HMI_OEE.ProductNum[299-i];
	END_FOR;
	HMI_OEE.ProductNum[0]:=HMI_OEE.ProductDay_Date[3];
END_IF;
IF (HMI_OEE.ProductNum[0]-HMI_OEE.ProductNum[300])/5>=1 THEN
	HMI_OEE.ProductDay_Date[9]:=(HMI_OEE.ProductNum[0]-HMI_OEE.ProductNum[300])/5;
ELSE
	HMI_OEE.ProductDay_Date[9]:=1;
END_IF;
 HMI_PPMCurrent_Max :=HMI_OEE.ProductDay_Date[9];

//(********************************夜班数量计算********************************)
ELSE
//////////////////////////////////////上料计数//////////////////////////////////////
//投入电芯数量计算触发
	IF LoadSum_R[0].Q  THEN HMI_OEE.ProductNight_Date[0]:=HMI_OEE.ProductNight_Date[0]+1; END_IF;
	IF LoadSum_R[1].Q  THEN HMI_OEE.ProductNight_Date[0]:=HMI_OEE.ProductNight_Date[0]+1; END_IF;
	HMI_OEE.OEE_Data[0]:=HMI_OEE.ProductNight_Date[0];
//上料电芯放反NG产品计算触发
	IF LoadSum_R[5].Q  THEN HMI_OEE.ProductNight_Date[10]:=HMI_OEE.ProductNight_Date[10]+1; END_IF;
	IF LoadSum_R[6].Q  THEN HMI_OEE.ProductNight_Date[10]:=HMI_OEE.ProductNight_Date[10]+1; END_IF;
//电芯扫码NG产品计算触发
	IF LoadSum_R[10].Q  THEN HMI_OEE.ProductNight_Date[11]:=HMI_OEE.ProductNight_Date[11]+1; END_IF;
	IF LoadSum_R[11].Q  THEN HMI_OEE.ProductNight_Date[11]:=HMI_OEE.ProductNight_Date[11]+1; END_IF;
//电芯MESNG产品计算触发
	IF LoadSum_R[15].Q  THEN HMI_OEE.ProductNight_Date[12]:=HMI_OEE.ProductNight_Date[12]+1; END_IF;
	IF LoadSum_R[16].Q  THEN HMI_OEE.ProductNight_Date[12]:=HMI_OEE.ProductNight_Date[12]+1; END_IF;
//顶盖上料数量计算触发
	IF LoadSum_R[20].Q  THEN HMI_OEE.ProductNight_Date[13]:=HMI_OEE.ProductNight_Date[13]+1; END_IF;
	IF LoadSum_R[21].Q  THEN HMI_OEE.ProductNight_Date[13]:=HMI_OEE.ProductNight_Date[13]+1; END_IF;
//顶盖刻码数量计算触发
	IF LoadSum_R[25].Q  THEN HMI_OEE.ProductNight_Date[14]:=HMI_OEE.ProductNight_Date[14]+1; END_IF;
	IF LoadSum_R[26].Q  THEN HMI_OEE.ProductNight_Date[14]:=HMI_OEE.ProductNight_Date[14]+1; END_IF;
//顶盖批次码不良计算触发
	IF LoadSum_R[30].Q  THEN HMI_OEE.ProductNight_Date[15]:=HMI_OEE.ProductNight_Date[15]+1; END_IF;
	IF LoadSum_R[31].Q  THEN HMI_OEE.ProductNight_Date[15]:=HMI_OEE.ProductNight_Date[15]+1; END_IF;
//顶盖蓝膜不良计算触发
	IF LoadSum_R[35].Q  THEN HMI_OEE.ProductNight_Date[16]:=HMI_OEE.ProductNight_Date[16]+1; END_IF;
	IF LoadSum_R[36].Q  THEN HMI_OEE.ProductNight_Date[16]:=HMI_OEE.ProductNight_Date[16]+1; END_IF;
//顶盖放反不良计算触发
	IF LoadSum_R[40].Q  THEN HMI_OEE.ProductNight_Date[17]:=HMI_OEE.ProductNight_Date[17]+1; END_IF;
	IF LoadSum_R[41].Q  THEN HMI_OEE.ProductNight_Date[17]:=HMI_OEE.ProductNight_Date[17]+1; END_IF;
//顶盖刻码不良计算触发
	IF LoadSum_R[45].Q  THEN HMI_OEE.ProductNight_Date[18]:=HMI_OEE.ProductNight_Date[18]+1; END_IF;
	IF LoadSum_R[46].Q  THEN HMI_OEE.ProductNight_Date[18]:=HMI_OEE.ProductNight_Date[18]+1; END_IF;
//顶盖刻码扫码不良计算触发
	IF LoadSum_R[50].Q  THEN HMI_OEE.ProductNight_Date[19]:=HMI_OEE.ProductNight_Date[19]+1; END_IF;
	IF LoadSum_R[51].Q  THEN HMI_OEE.ProductNight_Date[19]:=HMI_OEE.ProductNight_Date[19]+1; END_IF;
//顶盖刻码条码等级NG计算触发
	IF LoadSum_R[55].Q  THEN HMI_OEE.ProductNight_Date[20]:=HMI_OEE.ProductNight_Date[20]+1; END_IF;
	IF LoadSum_R[56].Q  THEN HMI_OEE.ProductNight_Date[20]:=HMI_OEE.ProductNight_Date[20]+1; END_IF;
//顶盖MESNG计算触发
	IF LoadSum_R[60].Q  THEN HMI_OEE.ProductNight_Date[21]:=HMI_OEE.ProductNight_Date[21]+1; END_IF;
	IF LoadSum_R[61].Q  THEN HMI_OEE.ProductNight_Date[21]:=HMI_OEE.ProductNight_Date[21]+1; END_IF;
//顶盖刻码CCDNG计算触发
	IF LoadSum_R[65].Q  THEN HMI_OEE.ProductNight_Date[22]:=HMI_OEE.ProductNight_Date[22]+1; END_IF;
	IF LoadSum_R[66].Q  THEN HMI_OEE.ProductNight_Date[22]:=HMI_OEE.ProductNight_Date[22]+1; END_IF;
	
//////////////////////////////////////下料计数//////////////////////////////////////
//OK成品计算触发
	IF DownSum_R[0].Q  THEN HMI_OEE.ProductNight_Date[1]:=HMI_OEE.ProductNight_Date[1]+1; END_IF;
	IF DownSum_R[1].Q  THEN HMI_OEE.ProductNight_Date[1]:=HMI_OEE.ProductNight_Date[1]+1; END_IF;
	HMI_OEE.OEE_Data[1]:=HMI_OEE.ProductNight_Date[1];
//NG成品计算触发
	IF DownSum_R[5].Q  THEN HMI_OEE.ProductNight_Date[2]:=HMI_OEE.ProductNight_Date[2]+1; END_IF;
	IF DownSum_R[6].Q  THEN HMI_OEE.ProductNight_Date[2]:=HMI_OEE.ProductNight_Date[2]+1; END_IF;
	HMI_OEE.OEE_Data[2]:=HMI_OEE.ProductNight_Date[2];
//1#离焦量NG计算触发
	IF DownSum_R[10].Q  THEN HMI_OEE.ProductNight_Date[50]:=HMI_OEE.ProductNight_Date[50]+1; END_IF;
	IF DownSum_R[11].Q  THEN HMI_OEE.ProductNight_Date[50]:=HMI_OEE.ProductNight_Date[50]+1; END_IF;
//2#离焦量NG计算触发
	IF DownSum_R[15].Q  THEN HMI_OEE.ProductNight_Date[51]:=HMI_OEE.ProductNight_Date[51]+1; END_IF;
	IF DownSum_R[16].Q  THEN HMI_OEE.ProductNight_Date[51]:=HMI_OEE.ProductNight_Date[51]+1; END_IF;
//离焦量双NG计算触发
	IF DownSum_R[20].Q  THEN HMI_OEE.ProductNight_Date[52]:=HMI_OEE.ProductNight_Date[52]+1; END_IF;
	IF DownSum_R[21].Q  THEN HMI_OEE.ProductNight_Date[52]:=HMI_OEE.ProductNight_Date[52]+1; END_IF;
//1#功率NG计算触发
	IF DownSum_R[25].Q  THEN HMI_OEE.ProductNight_Date[53]:=HMI_OEE.ProductNight_Date[53]+1; END_IF;
	IF DownSum_R[26].Q  THEN HMI_OEE.ProductNight_Date[53]:=HMI_OEE.ProductNight_Date[53]+1; END_IF;
//2#功率NG计算触发
	IF DownSum_R[30].Q  THEN HMI_OEE.ProductNight_Date[54]:=HMI_OEE.ProductNight_Date[54]+1; END_IF;
	IF DownSum_R[31].Q  THEN HMI_OEE.ProductNight_Date[54]:=HMI_OEE.ProductNight_Date[54]+1; END_IF;
//功率双NG计算触发
	IF DownSum_R[35].Q  THEN HMI_OEE.ProductNight_Date[55]:=HMI_OEE.ProductNight_Date[55]+1; END_IF;
	IF DownSum_R[36].Q  THEN HMI_OEE.ProductNight_Date[55]:=HMI_OEE.ProductNight_Date[55]+1; END_IF;
//WDDNG计算触发
	IF DownSum_R[40].Q  THEN HMI_OEE.ProductNight_Date[56]:=HMI_OEE.ProductNight_Date[56]+1; END_IF;
	IF DownSum_R[41].Q  THEN HMI_OEE.ProductNight_Date[56]:=HMI_OEE.ProductNight_Date[56]+1; END_IF;
//1#焊印NG计算触发
	IF DownSum_R[45].Q  THEN HMI_OEE.ProductNight_Date[57]:=HMI_OEE.ProductNight_Date[57]+1; END_IF;
	IF DownSum_R[46].Q  THEN HMI_OEE.ProductNight_Date[57]:=HMI_OEE.ProductNight_Date[57]+1; END_IF;
//2#焊印NG计算触发
	IF DownSum_R[50].Q  THEN HMI_OEE.ProductNight_Date[58]:=HMI_OEE.ProductNight_Date[58]+1; END_IF;
	IF DownSum_R[51].Q  THEN HMI_OEE.ProductNight_Date[58]:=HMI_OEE.ProductNight_Date[58]+1; END_IF;
//焊印双NG计算触发
	IF DownSum_R[55].Q  THEN HMI_OEE.ProductNight_Date[59]:=HMI_OEE.ProductNight_Date[59]+1; END_IF;
	IF DownSum_R[56].Q  THEN HMI_OEE.ProductNight_Date[59]:=HMI_OEE.ProductNight_Date[59]+1; END_IF;
//1#极耳NG计算触发
	IF DownSum_R[60].Q  THEN HMI_OEE.ProductNight_Date[60]:=HMI_OEE.ProductNight_Date[60]+1; END_IF;
	IF DownSum_R[61].Q  THEN HMI_OEE.ProductNight_Date[60]:=HMI_OEE.ProductNight_Date[60]+1; END_IF;
//2#极耳NG计算触发
	IF DownSum_R[65].Q  THEN HMI_OEE.ProductNight_Date[61]:=HMI_OEE.ProductNight_Date[61]+1; END_IF;
	IF DownSum_R[66].Q  THEN HMI_OEE.ProductNight_Date[61]:=HMI_OEE.ProductNight_Date[61]+1; END_IF;
//极耳双NG计算触发
	IF DownSum_R[70].Q  THEN HMI_OEE.ProductNight_Date[62]:=HMI_OEE.ProductNight_Date[62]+1; END_IF;
	IF DownSum_R[71].Q  THEN HMI_OEE.ProductNight_Date[62]:=HMI_OEE.ProductNight_Date[62]+1; END_IF;
//1#焊印胶NG计算触发
	IF DownSum_R[75].Q  THEN HMI_OEE.ProductNight_Date[63]:=HMI_OEE.ProductNight_Date[63]+1; END_IF;
	IF DownSum_R[76].Q  THEN HMI_OEE.ProductNight_Date[63]:=HMI_OEE.ProductNight_Date[63]+1; END_IF;
//2#焊印胶NG计算触发
	IF DownSum_R[80].Q  THEN HMI_OEE.ProductNight_Date[64]:=HMI_OEE.ProductNight_Date[64]+1; END_IF;
	IF DownSum_R[81].Q  THEN HMI_OEE.ProductNight_Date[64]:=HMI_OEE.ProductNight_Date[64]+1; END_IF;
//焊印胶双NG计算触发
	IF DownSum_R[85].Q  THEN HMI_OEE.ProductNight_Date[65]:=HMI_OEE.ProductNight_Date[65]+1; END_IF;
	IF DownSum_R[86].Q  THEN HMI_OEE.ProductNight_Date[65]:=HMI_OEE.ProductNight_Date[65]+1; END_IF;
//1#扣支架NG计算触发
	IF DownSum_R[90].Q  THEN HMI_OEE.ProductNight_Date[66]:=HMI_OEE.ProductNight_Date[66]+1; END_IF;
	IF DownSum_R[91].Q  THEN HMI_OEE.ProductNight_Date[66]:=HMI_OEE.ProductNight_Date[66]+1; END_IF;
//2#扣支架NG计算触发
	IF DownSum_R[95].Q  THEN HMI_OEE.ProductNight_Date[67]:=HMI_OEE.ProductNight_Date[67]+1; END_IF;
	IF DownSum_R[96].Q  THEN HMI_OEE.ProductNight_Date[67]:=HMI_OEE.ProductNight_Date[67]+1; END_IF;
//扣支架双NG计算触发
	IF DownSum_R[100].Q  THEN HMI_OEE.ProductNight_Date[68]:=HMI_OEE.ProductNight_Date[68]+1; END_IF;
	IF DownSum_R[101].Q  THEN HMI_OEE.ProductNight_Date[68]:=HMI_OEE.ProductNight_Date[68]+1; END_IF;
//电芯出站MESNG计算触发
	IF DownSum_R[105].Q  THEN HMI_OEE.ProductNight_Date[69]:=HMI_OEE.ProductNight_Date[69]+1; END_IF;
	IF DownSum_R[106].Q  THEN HMI_OEE.ProductNight_Date[69]:=HMI_OEE.ProductNight_Date[69]+1; END_IF;
//1#焊印点胶NG计算触发
	IF DownSum_R[110].Q  THEN HMI_OEE.ProductNight_Date[70]:=HMI_OEE.ProductNight_Date[70]+1; END_IF;
	IF DownSum_R[111].Q  THEN HMI_OEE.ProductNight_Date[70]:=HMI_OEE.ProductNight_Date[70]+1; END_IF;
//2#焊印点胶NG计算触发
	IF DownSum_R[115].Q  THEN HMI_OEE.ProductNight_Date[71]:=HMI_OEE.ProductNight_Date[71]+1; END_IF;
	IF DownSum_R[116].Q  THEN HMI_OEE.ProductNight_Date[71]:=HMI_OEE.ProductNight_Date[71]+1; END_IF;
//焊印点胶双NG计算触发
	IF DownSum_R[120].Q  THEN HMI_OEE.ProductNight_Date[72]:=HMI_OEE.ProductNight_Date[72]+1; END_IF;
	IF DownSum_R[121].Q  THEN HMI_OEE.ProductNight_Date[72]:=HMI_OEE.ProductNight_Date[72]+1; END_IF;

//夜班下料数量（良品数量+不良品数量）
HMI_OEE.ProductNight_Date[3]:=HMI_OEE.ProductNight_Date[1]+HMI_OEE.ProductNight_Date[2];
//夜班良率计算（良品数量/下料数量）
IF HMI_OEE.ProductNight_Date[3]>0 THEN
HMI_OEE.ProductNight_Date[4]:=HMI_OEE.ProductNight_Date[1]/HMI_OEE.ProductNight_Date[3]*REAL#100;
END_IF;
//夜班设备CT计算（设备生产时间(秒)/下料数量）
IF HMI_OEE.ProductNight_Date[3]>0 THEN
HMI_OEE.ProductNight_Date[5]:=INT_TO_REAL((HMI_OEE.MachineAutoTime.Hour*3600+
							HMI_OEE.MachineAutoTime.Minute*60+
							HMI_OEE.MachineAutoTime.Second))/
							HMI_OEE.ProductNight_Date[3];
END_IF;	
//夜班PPM（60秒/设备CT）
IF HMI_OEE.ProductNight_Date[5]>0 THEN
HMI_OEE.ProductNight_Date[6]:=60/HMI_OEE.ProductNight_Date[5];
END_IF;	
//夜班故障率(报警时间（秒）/运行时间（秒）)
IF HMI_OEE.MachineOpenTime.Hour*3600+HMI_OEE.MachineOpenTime.Minute*60+HMI_OEE.MachineOpenTime.Second>0
THEN
HMI_OEE.ProductNight_Date[7]:=INT_TO_REAL((HMI_OEE.MachineAlarmTime.Hour*3600+
						HMI_OEE.MachineAlarmTime.Minute*60+
						HMI_OEE.MachineAlarmTime.Second))/
						INT_TO_REAL((HMI_OEE.MachineOpenTime.Hour*3600+
						HMI_OEE.MachineOpenTime.Minute*60+
						HMI_OEE.MachineOpenTime.Second))
						*REAL#100;
END_IF;
//夜班故障时间（分钟）（故障小时*60+故障分钟+故障秒钟/60）
HMI_OEE.ProductNight_Date[8]:=HMI_OEE.MachineAlarmTime.Hour*60+
						HMI_OEE.MachineAlarmTime.Minute+
						INT_TO_REAL(HMI_OEE.MachineAlarmTime.Second)/60;
//夜班实时PPM（实时5min生产数量/5min）
IF HMI_OEE.MachineRuning AND HMI_OEE.Signal_1000msRT THEN
	FOR i:=0 TO 299 BY 1 DO
	HMI_OEE.ProductNum[300-i]:=HMI_OEE.ProductNum[299-i];
	END_FOR;
	HMI_OEE.ProductNum[0]:=HMI_OEE.ProductNight_Date[3];
END_IF;
IF (HMI_OEE.ProductNum[0]-HMI_OEE.ProductNum[300])/5>=1 THEN
	HMI_OEE.ProductNight_Date[9]:=(HMI_OEE.ProductNum[0]-HMI_OEE.ProductNum[300])/5;
ELSE
	HMI_OEE.ProductNight_Date[9]:=1;
END_IF;
 HMI_PPMCurrent_Max :=HMI_OEE.ProductNight_Date[9];
END_IF;

//(********************************每小时产能统计********************************)
//计算当前小时
IF SystemTime.Minute>=Time_Minute THEN
	Time_HourTem:=(SystemTime.Hour+(8-Time_Hour)+24) MOD 24;
ELSE
	Time_HourTem:=(SystemTime.Hour+(7-Time_Hour)+24) MOD 24;
END_IF;

//每小时投入数量
HMI_OEE.LoadNumber[Time_HourTem]:=HMI_OEE.OEE_Data[0]-OneHuorLoadSumTem;
//每小时OK数量
HMI_OEE.OKNumber[Time_HourTem]:=HMI_OEE.OEE_Data[1]-OneHuorOKSumTem;
//每小时NG数量
HMI_OEE.NGNumber[Time_HourTem]:=HMI_OEE.OEE_Data[2]-OneHuorNGSumTem;
//每小时宕机时间
HMI_OEE.StopTime[Time_HourTem]:=HMI_OEE.MachineAlarmTime.Hour*60+HMI_OEE.MachineAlarmTime.Minute+
						INT_TO_REAL(HMI_OEE.MachineAlarmTime.Second/60)-OneHuorStopTimeTem;//+
//						HMI_OEE.MachineStopTime.Hour*60+HMI_OEE.MachineStopTime.Minute+
//						INT_TO_REAL(HMI_OEE.MachineStopTime.Second/60)-OneHuorStopTimeTem;
//每小时上料待机时间
HMI_OEE.WaitTime[Time_HourTem]:=HMI_OEE.MachineWaitTime.Hour*60+HMI_OEE.MachineWaitTime.Minute+
						INT_TO_REAL(HMI_OEE.MachineWaitTime.Second/60)-OneHuorWaitTimeTem;
//每小时下料待机时间
HMI_OEE.PuttyTime[Time_HourTem]:=HMI_OEE.MachinePuttyTime.Hour*60+HMI_OEE.MachinePuttyTime.Minute+
						INT_TO_REAL(HMI_OEE.MachinePuttyTime.Second/60)-OneHuorPuttyTimeTem;

//(********************************每班数据汇总********************************)
//白班投入数量汇总
HMI_OEE.LoadNumber[24]:=HMI_OEE.LoadNumber[9]+HMI_OEE.LoadNumber[10]+
													HMI_OEE.LoadNumber[11]+HMI_OEE.LoadNumber[12]+
													HMI_OEE.LoadNumber[13]+HMI_OEE.LoadNumber[14]+
													HMI_OEE.LoadNumber[15]+HMI_OEE.LoadNumber[16]+
													HMI_OEE.LoadNumber[17]+HMI_OEE.LoadNumber[18]+
													HMI_OEE.LoadNumber[19]+HMI_OEE.LoadNumber[8];
//夜班投入数量汇总
HMI_OEE.LoadNumber[25]:=HMI_OEE.LoadNumber[21]+HMI_OEE.LoadNumber[22]+
													HMI_OEE.LoadNumber[23]+HMI_OEE.LoadNumber[0]+
													HMI_OEE.LoadNumber[1]+HMI_OEE.LoadNumber[2]+
													HMI_OEE.LoadNumber[3]+HMI_OEE.LoadNumber[4]+
													HMI_OEE.LoadNumber[5]+HMI_OEE.LoadNumber[6]+
													HMI_OEE.LoadNumber[7]+HMI_OEE.LoadNumber[20];
//白班OK数量汇总
HMI_OEE.OKNumber[24]:=HMI_OEE.OKNumber[9]+HMI_OEE.OKNumber[10]+
													HMI_OEE.OKNumber[11]+HMI_OEE.OKNumber[12]+
													HMI_OEE.OKNumber[13]+HMI_OEE.OKNumber[14]+
													HMI_OEE.OKNumber[15]+HMI_OEE.OKNumber[16]+
													HMI_OEE.OKNumber[17]+HMI_OEE.OKNumber[18]+
													HMI_OEE.OKNumber[19]+HMI_OEE.OKNumber[8];
//夜班OK数量汇总
HMI_OEE.OKNumber[25]:=HMI_OEE.OKNumber[21]+HMI_OEE.OKNumber[22]+
													HMI_OEE.OKNumber[23]+HMI_OEE.OKNumber[0]+
													HMI_OEE.OKNumber[1]+HMI_OEE.OKNumber[2]+
													HMI_OEE.OKNumber[3]+HMI_OEE.OKNumber[4]+
													HMI_OEE.OKNumber[5]+HMI_OEE.OKNumber[6]+
													HMI_OEE.OKNumber[7]+HMI_OEE.OKNumber[20];
//白班NG数量汇总
HMI_OEE.NGNumber[24]:=HMI_OEE.NGNumber[9]+HMI_OEE.NGNumber[10]+
