													HMI_OEE.NGNumber[15]+HMI_OEE.NGNumber[16]+
													HMI_OEE.NGNumber[17]+HMI_OEE.NGNumber[18]+
													HMI_OEE.NGNumber[19]+HMI_OEE.NGNumber[8];
//夜班NG数量汇总
HMI_OEE.NGNumber[25]:=HMI_OEE.NGNumber[21]+HMI_OEE.NGNumber[22]+
													HMI_OEE.NGNumber[23]+HMI_OEE.NGNumber[0]+
													HMI_OEE.NGNumber[1]+HMI_OEE.NGNumber[2]+
													HMI_OEE.NGNumber[3]+HMI_OEE.NGNumber[4]+
