(********************************************	保护盖记忆清除处理		*********************************************)
//获取保护盖属性更换按钮上升沿
R_ChangeProtectCover1(Clk:=HMI_Button[6,0]);
R_ChangeProtectCover2(Clk:=HMI_Button[6,1]);

//1#焊接位保护盖属性更换
IF R_ChangeProtectCover1.Q AND Cell_Info[6,0].Quality=0 THEN
	Cell_Info[6,0].Quality:=100;
	//Cell_Info[6,0].ProtectCoverSN:='1';
ELSIF R_ChangeProtectCover1.Q AND Cell_Info[6,0].Quality=90 THEN
	Cell_Info[6,0].Quality:=0;
ELSIF R_ChangeProtectCover1.Q AND Cell_Info[6,0].Quality=100 THEN
	Cell_Info[6,0].Quality:=90;
END_IF;
//2#焊接位保护盖属性更换
IF R_ChangeProtectCover2.Q AND Cell_Info[6,1].Quality=0 THEN
	Cell_Info[6,1].Quality:=100;
	//Cell_Info[6,1].ProtectCoverSN:='2';
ELSIF R_ChangeProtectCover2.Q AND Cell_Info[6,1].Quality=90 THEN
	Cell_Info[6,1].Quality:=0;
ELSIF R_ChangeProtectCover2.Q AND Cell_Info[6,1].Quality=100 THEN
	Cell_Info[6,1].Quality:=90;
END_IF;

//清除保护盖当前焊接次数
IF Cell_Info[6,0].Quality=0 OR Cell_Info[6,0].Quality=90 THEN
	EM06P.ProtectCoverWeldNum1:=0;
END_IF;
IF Cell_Info[6,1].Quality=0 OR Cell_Info[6,1].Quality=90 THEN
	EM06P.ProtectCoverWeldNum2:=0;
END_IF;

//保护盖达到焊接次数
IF EM06P.ProtectCoverWeldNum1>=EM06P.ProtectCoverWeldSum
THEN
	IF 
		EM05V.Golytec.Out.StationMotionDone[8]//2#焊接位治具到位
		AND EM05V.Golytec.Out.StationMotionDone[7]//缓存位治具到位
		AND NOT EM05V.Golytec.Out.StationMotionDone[10]//避让位治具到位
		AND EM05V.Golytec.Out.StationMotionDone[6]//1#焊接位治具到位
	THEN
		IF Cell_Info[6,0].Quality=100
		THEN
			Cell_Info[6,0].Quality:=90;
		END_IF;
		H_Messages.Station[6].User_Warning[13]:=TRUE;//EM06振镜焊接模组:1#焊接位保护盖使用次数达到设定次数
		EM06P.ProtectCoverWeldNum1:=0;
	END_IF
END_IF;
IF EM06P.ProtectCoverWeldNum2>=EM06P.ProtectCoverWeldSum
THEN
	IF 
		EM05V.Golytec.Out.StationMotionDone[8]//2#焊接位治具到位
		AND EM05V.Golytec.Out.StationMotionDone[7]//缓存位治具到位
		AND NOT EM05V.Golytec.Out.StationMotionDone[10]//避让位治具到位
	THEN
		IF Cell_Info[6,1].Quality=100
		THEN
			Cell_Info[6,1].Quality:=90;
		END_IF;
		H_Messages.Station[6].User_Warning[14]:=TRUE;//EM06振镜焊接模组:2#焊接位保护盖使用次数达到设定次数
		EM06P.ProtectCoverWeldNum2:=0;
	END_IF
	
END_IF;


(********************************************	物料记忆清除		*********************************************)
 //清除物料记忆 OR 产品信息查阅
IF MyStatus.StatusManual THEN//手动模式，清除记忆
	FOR i1:=0 TO MyStation.StationSum DO
		FOR j1:=0 TO 18 DO
			IF Cell_Info[i1,j1].Clear<>0 THEN
			Clear(Cell_Info[i1,j1]);
			FOR j2:=0 TO 9 BY 1 DO
			MyStation.EMStation[i1,j2].ResetComplete:=FALSE;
			END_FOR
			MyStation.EM[i1].ResetComplete:=FALSE;
			END_IF;
		END_FOR;
	END_FOR;
ELSIF MyStatus.StatusAuto THEN//自动模式，产品信息查阅
	FOR i1:=1 TO MyStation.StationSum DO
		FOR j1:=0 TO 18 DO
			IF Cell_Info[i1,j1].Clear<>0 THEN
			Consult_Windows:=TRUE;
			Cell_Info[0,0]:=Cell_Info[i1,j1];
			Cell_Info[i1,j1].Clear:=0;
			END_IF;
		END_FOR;
	END_FOR;
END_IF;

//记忆查询弹窗复位
IF MyInput.Reset_Input AND Consult_Windows THEN
	Consult_Windows:=FALSE;
END_IF;


(********************************************	整机物料记忆处理		*********************************************)
//获取空机模式和局部单动模式上升沿和下降沿
R_TestMode_Enable.Clk:=HMI_TestMode_Enable OR HMI_SingleAutoMode_Enable;
FC_R_TRIG(InOut:=R_TestMode_Enable);
F_TestMode_Enable.Clk:=HMI_TestMode_Enable OR HMI_SingleAutoMode_Enable;
FC_F_TRIG(InOut:=F_TestMode_Enable);

IF R_TestMode_Enable.Q	OR F_TestMode_Enable.Q OR HMI_EQ.HMI_BatteryQuility_Clear THEN
	HMI_BatteryQuility_Clear:=TRUE;
END_IF;

IF  HMI_BatteryQuility_Clear THEN
	FOR i1:=0 TO MyStation.StationSum DO
		IF i1<>6 THEN
			FOR j1:=0 TO 18 DO
				IF (i1=1 AND j1>=4)
					OR (i1=12 AND j1>=12)
					OR (i1<>1 AND i1<>12)
				THEN
					Clear(Cell_Info[i1,j1]);
				END_IF;
			END_FOR;
		END_IF;
		FOR j2:=0 TO 9 BY 1 DO
			MyStation.EMStation[i1,j2].ResetComplete:=FALSE;
		END_FOR
		MyStation.EM[i1].ResetComplete:=FALSE;
	END_FOR;
	HMI_BatteryQuility_Clear:=FALSE;
END_IF;


//设备安全门被打开，需要重新整机初始化
EM06_Door(CLK:= NOT SafetyController.SafetyDoorSum, Q=> );
IF EM06_Door.Q THEN
MyStation.EMStation[5,0].ResetComplete:=FALSE;
MyStation.EMStation[5,1].ResetComplete:=FALSE;
MyStation.EMStation[6,0].ResetComplete:=FALSE;
MyStation.EMStation[6,1].ResetComplete:=FALSE;
MyStation.EMStation[6,2].ResetComplete:=FALSE;
MyStation.EMStation[6,3].ResetComplete:=FALSE;
END_IF  ;

