(********************************************	CT计时		*********************************************)
//程序流程步映射
CycleTime[1].ProgramStep:=EM01V.Process_steps[0];	//步骤名称


//计时功能重置
IF Signal_ResetCompleteRT THEN
	FOR i:=1 TO 35 BY 1 DO
		CycleTime[i].ClearData:=TRUE;
	END_FOR;
END_IF;

//初始值赋值
IF CycleTime[0].SelectNum<=0
	OR CycleTime[0].SelectNum>49
THEN
	CycleTime[0].SelectNum:=1;
END_IF;

//功能块调用
FOR i:=1 TO 35 BY 1 DO
FBCycleTime[i](
	Execute				:=	TRUE												,	//使能
	Reset					:=	MyInput.Reset_Input						,	//复位
 	ClearData				:=	CycleTime[i].ClearData					,   //清除步骤时间列表计时
 	Complete				:=	CycleTime[i].Complete					,   //完成计时输出列表
 	ProgramStep		:=	CycleTime[i].ProgramStep				,   //步骤变量
 	Condition				:=	CycleTime[i].ProgramStep >= 10	 AND MyStation.EM[0].Running,   //开始监控条件
	SysCycleTime		:=	SystemCycleTime								,	//系统扫描周期
	StepNum				:=	63														,	//监控程序步骤数
 	HMICycleTime		:=	CycleTime[i]									//输出步骤号和时间
	);
END_FOR;



(********************************************	CT步骤内容和设定时间显示		*********************************************)
//步骤序号和实时时间显示
IF Signal_1000msRT THEN
CycleTime[0].StepCycleTime.StepNum:=CycleTime[CycleTime[0].SelectNum].StepCycleTime.StepNum;
CycleTime[0].StepCycleTime.StepTime:=CycleTime[CycleTime[0].SelectNum].StepCycleTime.StepTime;
CycleTime[0].StationCycleTime:=CycleTime[CycleTime[0].SelectNum].StationCycleTime;
END_IF;

////////////////////////////FFU启动////////////////////////////

R_FFU_Level(CLK:=FFU_HMILeavl<>FFU_Leavl AND NOT HMI_Function_Enable[0,4] );//1~3档
R_FFU_Start(CLK:= NOT HMI_Function_Enable[0,4] OR R_FFU_Level.Q);
F_FFU_Start(CLK:= NOT HMI_Function_Enable[0,4]);
 TON_SendInterval(In:=FFU_AutoStep = 20 OR FFU_AutoStep = 60 OR FFU_AutoStep = 90 , PT:=T#5S);
 TON_FFU1(IN:=FFU_AutoStep = 100 OR FFU_AutoStep = 30 OR FFU_AutoStep = 70, PT:=T#50MS );
(********************************************	交互流程		*********************************************)

	IF R_FFU_Start.Q THEN
		Clear(TCP_FFU.bySendData);
		ExecuteType  := 1	;
		FFU_AutoStep:=10;
	ELSIF F_FFU_Start.Q
	THEN  
		Clear(TCP_FFU.bySendData);
		ExecuteType  := 2	;
		FFU_AutoStep:=10;
	END_IF;
		
CASE FFU_AutoStep OF
	10: 	//	发送数据处理
			IF 		 ExecuteType = 1 //启动风机
			THEN							
				  TCP_FFU.bySendData[0] := BYTE#16#01;//从站号
				  TCP_FFU.bySendData[1] := BYTE#16#06;//功能代码(读取通道过程值命令）6
				  TCP_FFU.bySendData[2] := BYTE#16#00;//起始地址高字节
				  TCP_FFU.bySendData[3] := BYTE#16#00;//起始地址低字节
				  TCP_FFU.bySendData[4] := BYTE#16#00;//读取个数高字节
				  TCP_FFU.bySendData[5] := BYTE#16#01;//读取个数低字节
				  FFU_TempWord.mWord := MEM.CRC16_Modbus(ADR(TCP_FFU.bySendData), 6);//CRC_16校验				
				  TCP_FFU.bySendData[6] := FFU_TempWord.mByte[0];//CRC_16高字节	  
				  TCP_FFU.bySendData[7] := FFU_TempWord.mByte[1];//CRC_16低字节
				  TCP_FFU.bSendExecute :=TRUE  ; //自动触发
				  FFU_AutoStep:=20;
			ELSIF  ExecuteType = 2 //关闭风机
			THEN
				  TCP_FFU.bySendData[0] := BYTE#16#01;//从站号
				  TCP_FFU.bySendData[1] := BYTE#16#06;//功能代码(读取通道过程值命令）6
				  TCP_FFU.bySendData[2] := BYTE#16#00;//起始地址高字节
				  TCP_FFU.bySendData[3] := BYTE#16#00;//起始地址低字节
				  TCP_FFU.bySendData[4] := BYTE#16#00;//读取个数高字节
				  TCP_FFU.bySendData[5] := BYTE#16#00;//读取个数低字节
				  FFU_TempWord.mWord := MEM.CRC16_Modbus(ADR(TCP_FFU.bySendData), 6);//CRC_16校验				
				  TCP_FFU.bySendData[6] := FFU_TempWord.mByte[0];//CRC_16高字节	  
				  TCP_FFU.bySendData[7] := FFU_TempWord.mByte[1];//CRC_16低字节
				  TCP_FFU.bSendExecute :=TRUE  ; //自动触发
				  FFU_AutoStep:=60;
			END_IF
			
				
	20: 	//	等待反馈接收触发信号完成					
				IF 	 TCP_FFU.bSendDone OR TON_SendInterval.Q
				THEN
						FFU_AutoStep:=30;						
						TCP_FFU.bSendExecute :=FALSE  ; //自动触发
				END_IF; 
	30:	//	等待反馈结果	
				IF  TON_FFU1.Q
				THEN
						FFU_AutoStep:=40;
						
				END_IF;
	40:		//选择档位	
		  TCP_FFU.bySendData[0] := BYTE#16#01;//从站号
		  TCP_FFU.bySendData[1] := BYTE#16#06;//功能代码(读取通道过程值命令）6
		  TCP_FFU.bySendData[2] := BYTE#16#00;//起始地址高字节
		  TCP_FFU.bySendData[3] := BYTE#16#05;//起始地址低字节
		  TCP_FFU.bySendData[4] := BYTE#16#01;//读取个数高字节
		  TCP_FFU.bySendData[5] := INT_TO_BYTE(FFU_HMILeavl);//读取个数低字节
		  FFU_TempWord.mWord := MEM.CRC16_Modbus(ADR(TCP_FFU.bySendData), 6);//CRC_16校验				
		  TCP_FFU.bySendData[6] := FFU_TempWord.mByte[0];//CRC_16高字节	  
		  TCP_FFU.bySendData[7] := FFU_TempWord.mByte[1];//CRC_16低字节
		  TCP_FFU.bSendExecute :=TRUE  ; //自动触发
		   FFU_AutoStep:=60;
	60: 	//	等待反馈接收触发信号完成	
				IF 	 TCP_FFU.bSendDone OR TON_SendInterval.Q
				THEN
						FFU_AutoStep:=  70;						
						TCP_FFU.bSendExecute :=FALSE  ; //自动触发
				END_IF;
	70:	//	等待反馈结果	
				IF  TON_FFU1.Q
				THEN
						FFU_AutoStep:=80;
						TCP_FFU.bSendExecute :=FALSE  ; //自动触发
				END_IF;
	80: 	//	运行状态
		  TCP_FFU.bySendData[0] := BYTE#16#01;//从站号
		  TCP_FFU.bySendData[1] := BYTE#16#03;//功能代码(读取通道过程值命令）
		  TCP_FFU.bySendData[2] := BYTE#16#00;//起始地址高字节
		  TCP_FFU.bySendData[3] := BYTE#16#06;//起始地址低字节
		  TCP_FFU.bySendData[4] := BYTE#16#00;//读取个数高字节
		  TCP_FFU.bySendData[5] := BYTE#16#01;//读取个数低字节
		  FFU_TempWord.mWord := MEM.CRC16_Modbus(ADR(TCP_FFU.bySendData), 6);//CRC_16校验				
		  TCP_FFU.bySendData[6] := FFU_TempWord.mByte[0];//CRC_16高字节	  
		  TCP_FFU.bySendData[7] := FFU_TempWord.mByte[1];//CRC_16低字节
		  TCP_FFU.bSendExecute :=TRUE  ; //自动触发
		   FFU_AutoStep:=90;	
	90: 	//	 等待反馈接收触发信号完成		   
				IF 	 TCP_FFU.bSendDone OR TON_SendInterval.Q
				THEN
						FFU_StepNO:=FFU_StepNO+1;
						TCP_FFU.bSendExecute :=FALSE  ; //自动触发
						FFU_AutoStep:=  100;
				END_IF; 
	100:	//	等待反馈结果	
				IF  TON_FFU1.Q
				THEN
					IF FFU_StepNO>=10 THEN
						IF TCP_FFU.byReadData[0]=BYTE#01
							AND TCP_FFU.byReadData[1]=BYTE#03
							AND TCP_FFU.byReadData[2]=BYTE#02
						THEN
							FFU_State_DWord.mByte[3]:=0;
							FFU_State_DWord.mByte[2]:=0;
							FFU_State_DWord.mByte[1]:=TCP_FFU.byReadData[3];
