							FFU_AutoStep:=  0;
							FFU_StepNO:=0;
						ELSE
							IF FFU_StepNO>=50 THEN
								FFU_AutoStep:=  0;
								FFU_StepNO:=0;
							ELSE
								FFU_AutoStep:=  80;
							END_IF
