(********************************************TCP功能块调用		*********************************************)	
FFU_TCP (
					ServerSelect	:= TCP_FFU.ServerSelect      	,// FALSE为客户端
					sHost       	:= TCP_FFU.sHost             	,// 客户端需填IP地址
					nPort       	:= TCP_FFU.nPort             	,// 端口号
					bReset      	:=TCP_FFU.bReset            		,// 复位
					bEnable     	:=TCP_FFU.bEnable           		,// 功能块使能
					sSendData   	:=TCP_FFU.bySendData        	 	,// 发送数据
					bSendExecute	:=TCP_FFU.bSendExecute      		,// 发送触发
					bConnected  	=>TCP_FFU.bConnected        		,// 链接标志
					bSendDone   	=>TCP_FFU.bSendDone         		,// 发送完成
					sReadData  		:=TCP_FFU.byReadData        	 	,// 接收数据(Byte)
					nReadDaSize 	:=TCP_FFU.nReadDaSize       		,// 接收数据长度
					bReadDone   	:=TCP_FFU.bReadDone         		,// 接收完成
					bConnectedErr	=>TCP_FFU.bConnectedErr     		,// 连接错误
					bBusy       	=>TCP_FFU.bBusy             		,// 忙碌
					bError      	=>TCP_FFU.bError            		,// 错误
					nErrorID    	=>TCP_FFU.nErrorID          		// 错误ID
	// 				HSocket     	=>TCP_PowerMeter.HSocket           	 //链接句柄
						);					
//配置
	TCP_FFU.ServerSelect		:=	FALSE		;//	FALSE为客户端
	TCP_FFU.sHost				:='192.168.0.94';//	IP地址
	TCP_FFU.nPort				:=	5004		;//	端口号
	TCP_FFU.bReset  :=  TCP_FFU.bError  AND MyInput.Reset_Input;
	FFU_TCP.SendLen :=  8;
//客服端掉线,服务器使能复位
IF		TCP_FFU.bError
		OR TCP_FFU.bConnectedErr
		//OR HMI_Function_Enable[0,4]
THEN
		TCP_FFU.bEnable		:=	FALSE	;
ELSIF	NOT	TCP_FFU.bError
			AND NOT TCP_FFU.bConnectedErr
		///	AND NOT HMI_Function_Enable[0,4]
THEN
		TCP_FFU.bEnable		:=	TRUE	;
END_IF;

