(********************************************	EtherCat总线错误报警		*********************************************)
//获取EtherCat总线错误  C口
H_Messages.EtherCat_Alarm[0]						:=	ETHERCAT_C.xError					;//ETHERCAT_C主站报错
pSlave_C 											:= 	ETHERCAT_C.FirstSlave				;
Number_C											:=	0									;
WHILE pSlave_C <> 0 DO
pSlave_C^();
	IF pSlave_C^.wState <> ETC_SLAVE_STATE.ETC_SLAVE_OPERATIONAL
	THEN
	H_Messages.EtherCat_Alarm[Number_C + 1]			:=	TRUE 								;//ETHERCAT_C从站报错,起始位为1
	END_IF
	Number_C										:=	Number_C + 1						;
	pSlave_C 										:= 	pSlave_C^.NextInstance				;
END_WHILE

//获取EtherCat总线错误  D口
	H_Messages.EtherCat_Alarm[100]					:=	ETHERCAT_D.xError				;//ETHERCAT_D主站报错
	pSlave_D 										:= 	ETHERCAT_D.FirstSlave			;
	Number_D										:=	0								;
	WHILE pSlave_D <> 0 DO
	pSlave_D^();
		IF pSlave_D^.wState <> ETC_SLAVE_STATE.ETC_SLAVE_OPERATIONAL
		THEN
		H_Messages.EtherCat_Alarm[Number_D + 101]		:=	TRUE 									;//ETHERCAT_D从站报错,起始位为101 
		END_IF
		Number_D										:=	Number_D + 1							;
		pSlave_D 										:= 	pSlave_D^.NextInstance					;
	END_WHILE


