								;

FOR wi:=50 TO 125 BY 1 DO
	IF wi<90 AND H_Messages.General_MainWarning[wi] THEN   //风扇反馈异常弹窗
		H_Messages.General_Warning[50]:=TRUE;
	ELSIF wi>=110 AND H_Messages.General_MainWarning[wi] THEN   //漏保反馈异常弹窗
		H_Messages.General_Warning[51]:=TRUE;
	ELSIF wi>=90 AND wi<110 AND H_Messages.General_MainWarning[wi] THEN   //电柜温反馈异常弹窗
		H_Messages.General_Warning[52]:=TRUE;
	END_IF
END_FOR

