//功能启用提示弹窗 FunctionWarningSearshSum:=ArySearch(In:=H_Messages.General_FunctionWarning[0], Size:=256, Key:=IKey, InOutPos:=FunctionWarningSearshPos); IF Signal_ResetCompleteRT AND FunctionWarningSearshSum//功能提示 AND NOT MyStation.MaintenanceMode AND NOT MyStatus.StatusManual THEN HMI_EQ.FunctionEnablePopups:=TRUE; END_IF;

(********************************************	初始化信号获取		*********************************************)
FOR i:=0 TO MyStation.StationSum DO
R_Init[i](CLK:=HMI_EQ.ST_Init[i]);
END_FOR;
(********************************************	整机初始化		*********************************************)
//整机初始化命令复位
IF HMI_EQ.ST_Init[0]
	AND (MyStation.EM[0].Running
	OR MyStation.EM[0].IsAlarm
	OR NOT MyStatus.StatusAuto)
THEN
	HMI_EQ.ST_Init[0]:=FALSE;
END_IF;
//整机初始化命令上升沿
IF R_Init[0].Q
	AND MyStatus.StatusAuto
	AND NOT MyStation.EM[0].IsAlarm
	AND NOT MyStation.EM[0].Running
THEN
	FOR i:=1 TO MyStation.StationSum DO
		MyStation.EM[i].Init:=NOT MyStation.EM[i].Shielding;//ST[i]工位初始化
	END_FOR;
END_IF;


(********************************************	模组初始化		*********************************************)
FOR i:=1 TO MyStation.StationSum DO
IF 	R_Init[i].Q THEN
	MyStation.EM[i].Init:=TRUE;
END_IF;
END_FOR;



(********************************************	关联初始化		*********************************************)
IF 	R_Init[2].Q THEN
	MyStation.EM[3].Init:=NOT MyStation.EM[3].Shielding;
END_IF;

IF 	R_Init[3].Q THEN
	MyStation.EM[2].Init:=NOT MyStation.EM[2].Shielding;
END_IF;

IF 	R_Init[5].Q THEN
	MyStation.EM[4].Init:=NOT MyStation.EM[4].Shielding;
	MyStation.EM[6].Init:=NOT MyStation.EM[6].Shielding;
	MyStation.EM[7].Init:=NOT MyStation.EM[7].Shielding;
END_IF;

IF 	R_Init[8].Q THEN
	MyStation.EM[7].Init:=NOT MyStation.EM[7].Shielding;
	MyStation.EM[9].Init:=NOT MyStation.EM[9].Shielding;
	MyStation.EM[10].Init:=NOT MyStation.EM[10].Shielding;
	MyStation.EM[11].Init:=NOT MyStation.EM[11].Shielding;
	MyStation.EM[12].Init:=NOT MyStation.EM[12].Shielding;
	MyStation.EM[13].Init:=NOT MyStation.EM[13].Shielding;
END_IF;

(********************************************	初始化命令复位		*********************************************)
//初始化命令复位
FOR i:=1 TO MyStation.StationSum DO
	IF MyStation.EM[i].Init
		AND (MyStation.EM[0].Running
		OR MyStation.EM[i].Running
		OR MyStation.EM[0].IsAlarm
		OR NOT MyStatus.StatusAuto)
	THEN
		MyStation.EM[i].Init:=FALSE;
	END_IF;
	IF MyStation.EM[i].Init AND NOT ST_Init_Temp[i] THEN
		ST_Init_Temp[i]:=TRUE;
	ELSIF ST_Init_Temp[i] THEN
		MyStation.EM[i].Init:=FALSE;
		ST_Init_Temp[i]:=FALSE;
	END_IF;
END_FOR;


(********************************************	清除初始化流程步		*********************************************)
IF MyStation.EM[1].Init AND NOT Act.Act04_Init[1] THEN Clear(EM01V.Init_Steps); END_IF;
IF MyStation.EM[2].Init AND NOT Act.Act04_Init[2] THEN Clear(EM02V.Init_Steps); END_IF;
IF MyStation.EM[3].Init AND NOT Act.Act04_Init[3] THEN Clear(EM03V.Init_Steps); END_IF;
IF MyStation.EM[4].Init AND NOT Act.Act04_Init[4] THEN Clear(EM04V.Init_Steps); END_IF;
IF MyStation.EM[5].Init AND NOT Act.Act04_Init[5] THEN Clear(EM05V.Init_Steps); END_IF;
IF MyStation.EM[6].Init AND NOT Act.Act04_Init[6] THEN Clear(EM06V.Init_Steps); END_IF;
IF MyStation.EM[7].Init AND NOT Act.Act04_Init[7] THEN Clear(EM07V.Init_Steps); END_IF;
IF MyStation.EM[8].Init AND NOT Act.Act04_Init[8] THEN Clear(EM08V.Init_Steps); END_IF;
IF MyStation.EM[9].Init AND NOT Act.Act04_Init[9] THEN Clear(EM09V.Init_Steps); END_IF;
IF MyStation.EM[10].Init AND NOT Act.Act04_Init[10] THEN Clear(EM10V.Init_Steps); END_IF;
IF MyStation.EM[11].Init AND NOT Act.Act04_Init[11] THEN Clear(EM11V.Init_Steps); END_IF;
IF MyStation.EM[12].Init AND NOT Act.Act04_Init[12] THEN Clear(EM12V.Init_Steps); END_IF;
IF MyStation.EM[13].Init AND NOT Act.Act04_Init[13] THEN Clear(EM13V.Init_Steps); END_IF;



(********************************************	初始化完成标志复位		*********************************************)
//设备急停被按下，需要重新整机初始化 
IF NOT MyStation.EmgStop THEN
	FOR i:=1 TO MyStation.StationSum DO
		MyStation.EM[i].ResetComplete:=FALSE;
	END_FOR;
END_IF;

//设备安全门被打开，需要重新整机初始化 
IF NOT MyStation.SafetyDoor
	OR NOT MyStation.SafetyRaster
THEN
	MyStation.EM[5].ResetComplete:=FALSE;
	MyStation.EM[6].ResetComplete:=FALSE;
END_IF;


FOR i:=1 TO MyStation.StationSum DO
//模组伺服原点标志丢失，需要重新初始化
IF NOT MyStation.EM[i].ServoHomed AND MyStation.EM[i].ResetComplete AND NOT MyStation.EM[i].Resting THEN	MyStation.EM[i].ResetComplete:=FALSE; END_IF;
//模组无效，需要重新初始化
IF MyStation.EM[i].Shielding AND MyStation.EM[i].ResetComplete AND NOT MyStation.EM[i].Resting THEN	MyStation.EM[i].ResetComplete:=FALSE; END_IF;
END_FOR;

//弹窗提示
 HMI_Function_Enable[1,2] :=  NOT  Signal_ResetCompleteRT	
                              AND  MyInput.Start_Input 
							  AND (   ( NOT  MyStation.EM[1].Shielding   AND  NOT MyStation.EM[1].ResetComplete    AND  MyStation.EM[1].Status <> 60 ) 
							  OR   ( NOT  MyStation.EM[2].Shielding   AND  NOT MyStation.EM[2].ResetComplete    AND  MyStation.EM[2].Status <> 60   ) 
							  OR   ( NOT  MyStation.EM[3].Shielding   AND  NOT MyStation.EM[3].ResetComplete    AND  MyStation.EM[3].Status <> 60   ) 
							  OR   ( NOT  MyStation.EM[4].Shielding   AND  NOT MyStation.EM[4].ResetComplete    AND  MyStation.EM[4].Status <> 60   ) 
							  OR   ( NOT  MyStation.EM[5].Shielding   AND  NOT MyStation.EM[5].ResetComplete    AND  MyStation.EM[5].Status <> 60   ) 
							  OR   ( NOT  MyStation.EM[6].Shielding   AND  NOT MyStation.EM[6].ResetComplete    AND  MyStation.EM[6].Status <> 60  ) 
							  OR   ( NOT  MyStation.EM[7].Shielding   AND  NOT MyStation.EM[7].ResetComplete    AND  MyStation.EM[7].Status <> 60  ) 
							  OR   ( NOT  MyStation.EM[8].Shielding   AND  NOT MyStation.EM[8].ResetComplete    AND  MyStation.EM[8].Status <> 60  ) 
							  OR   ( NOT  MyStation.EM[9].Shielding   AND  NOT MyStation.EM[9].ResetComplete    AND  MyStation.EM[9].Status <> 60  ) 
							  OR   ( NOT  MyStation.EM[10].Shielding   AND  NOT MyStation.EM[10].ResetComplete  AND  MyStation.EM[10].Status <> 60  ) 
							  OR   ( NOT  MyStation.EM[11].Shielding   AND  NOT MyStation.EM[11].ResetComplete  AND  MyStation.EM[11].Status <> 60  ) 
							  OR   ( NOT  MyStation.EM[12].Shielding   AND  NOT MyStation.EM[12].ResetComplete  AND  MyStation.EM[12].Status <> 60  ) 							  
							  OR   ( NOT  MyStation.EM[13].Shielding   AND  NOT MyStation.EM[13].ResetComplete  AND  MyStation.EM[13].Status <> 60  ) 
					               )
							  ;

(********************************************	模组报警状态和手自动冲突状态清除		*********************************************)
FOR i:=1 TO 20 DO
	IF MyStation.EM[i].Shielding AND MyStation.EM[i].IsAlarm THEN
		MyStation.EM[i].IsAlarm:=FALSE;
	ELSIF MyStation.EM[i].Shielding AND MyStation.EM[i].Conflict THEN
		MyStation.EM[i].Conflict:=FALSE;
	END_IF;
END_FOR;

(********************************************	设备报警状态		*********************************************)
//整机Alarm汇总
IF Search_Alarm(H_Messages.General_Alarm)//整机报警
//	OR Search_Alarm(H_Messages.EtherCat_Alarm)//总线错误报警
	OR NOT MyStation.EmgStop//整机急停被按下
	OR NOT MyStation.SafetyDoor//整机安全门被打开
	OR NOT MyStation.SafetyRaster//整机安全光栅被遮挡

OR Unit.UN.EventStatus.FAlarmExists  //报警事件激活标志
OR Unit.UN.EventStatus.AlarmExists   //报警事件激活标志
	
	OR MyStation.EM[1].IsAlarm
	OR MyStation.EM[2].IsAlarm
	OR MyStation.EM[3].IsAlarm
	OR MyStation.EM[4].IsAlarm
	OR MyStation.EM[5].IsAlarm
	OR MyStation.EM[6].IsAlarm
	OR MyStation.EM[7].IsAlarm
	OR MyStation.EM[8].IsAlarm
	OR MyStation.EM[9].IsAlarm
	OR MyStation.EM[10].IsAlarm
	OR MyStation.EM[11].IsAlarm
	OR MyStation.EM[12].IsAlarm
	OR MyStation.EM[13].IsAlarm
	OR MyStation.EM[14].IsAlarm
	OR MyStation.EM[15].IsAlarm
	OR MyStation.EM[16].IsAlarm
	OR MyStation.EM[17].IsAlarm
	OR MyStation.EM[18].IsAlarm
	OR MyStation.EM[19].IsAlarm
	OR MyStation.EM[20].IsAlarm
THEN
	MyStation.EM[0].IsAlarm:=TRUE;
END_IF;

