MyStation.EM[0].Conflict:=FALSE
	OR MyStation.EM[1].Conflict
	OR MyStation.EM[2].Conflict
	OR MyStation.EM[3].Conflict
	OR MyStation.EM[4].Conflict
	OR MyStation.EM[5].Conflict
	OR MyStation.EM[6].Conflict
	OR MyStation.EM[7].Conflict
	OR MyStation.EM[8].Conflict
	OR MyStation.EM[9].Conflict
	OR MyStation.EM[10].Conflict
	OR MyStation.EM[11].Conflict
	OR MyStation.EM[12].Conflict
	OR MyStation.EM[13].Conflict
	OR MyStation.EM[14].Conflict
	OR MyStation.EM[15].Conflict
	OR MyStation.EM[16].Conflict
	OR MyStation.EM[17].Conflict
	OR MyStation.EM[18].Conflict
	OR MyStation.EM[19].Conflict
	OR MyStation.EM[20].Conflict;


(********************************************	设备启用状态		*********************************************)
MyStation.EM[0].Shielding :=TRUE
	AND MyStation.EM[1].Shielding
	AND MyStation.EM[2].Shielding
	AND MyStation.EM[3].Shielding
	AND MyStation.EM[4].Shielding
	AND MyStation.EM[5].Shielding
	AND MyStation.EM[6].Shielding
	AND MyStation.EM[7].Shielding
	AND MyStation.EM[8].Shielding
	AND MyStation.EM[9].Shielding
	AND MyStation.EM[10].Shielding
	AND MyStation.EM[11].Shielding
