	AND MyStation.EM[16].Shielding
	AND MyStation.EM[17].Shielding
	AND MyStation.EM[18].Shielding
	AND MyStation.EM[19].Shielding
	AND MyStation.EM[20].Shielding;


(********************************************	设备伺服原点状态		*********************************************)
//汇总伺服原点标志
MyStation.EM[0].ServoHomed:=TRUE
	AND (MyStation.EM[1].ServoHomed OR MyStation.EM[1].Shielding)
	AND (MyStation.EM[2].ServoHomed OR MyStation.EM[2].Shielding)
	AND (MyStation.EM[3].ServoHomed OR MyStation.EM[3].Shielding)
	AND (MyStation.EM[4].ServoHomed OR MyStation.EM[4].Shielding)
	AND (MyStation.EM[5].ServoHomed OR MyStation.EM[5].Shielding)
	AND (MyStation.EM[6].ServoHomed OR MyStation.EM[6].Shielding)
