//获取模组准备好
MyStation.EM[1].Ready:=TRUE;
MyStation.EM[2].Ready:=TRUE;
MyStation.EM[3].Ready:=TRUE;
MyStation.EM[4].Ready:=TRUE;
MyStation.EM[5].Ready:=TRUE;
MyStation.EM[6].Ready:=TRUE;
