MyStation.EM[16].Ready:=TRUE;
MyStation.EM[17].Ready:=TRUE;
MyStation.EM[18].Ready:=TRUE;
MyStation.EM[19].Ready:=TRUE;
MyStation.EM[20].Ready:=TRUE;

//汇总模组准备好
MyStation.EM[0].Ready:=TRUE
	AND (MyStation.EM[1].Ready OR MyStation.EM[1].Shielding)
	AND (MyStation.EM[2].Ready OR MyStation.EM[2].Shielding)
	AND (MyStation.EM[3].Ready OR MyStation.EM[3].Shielding)
	AND (MyStation.EM[4].Ready OR MyStation.EM[4].Shielding)
	AND (MyStation.EM[5].Ready OR MyStation.EM[5].Shielding)
	AND (MyStation.EM[6].Ready OR MyStation.EM[6].Shielding)
	AND (MyStation.EM[7].Ready OR MyStation.EM[7].Shielding)
	AND (MyStation.EM[8].Ready OR MyStation.EM[8].Shielding)
	AND (MyStation.EM[9].Ready OR MyStation.EM[9].Shielding)
	AND (MyStation.EM[10].Ready OR MyStation.EM[10].Shielding)
	AND (MyStation.EM[11].Ready OR MyStation.EM[11].Shielding)
	AND (MyStation.EM[12].Ready OR MyStation.EM[12].Shielding)
	AND (MyStation.EM[13].Ready OR MyStation.EM[13].Shielding)
	AND (MyStation.EM[14].Ready OR MyStation.EM[14].Shielding)
	AND (MyStation.EM[15].Ready OR MyStation.EM[15].Shielding)
	AND (MyStation.EM[16].Ready OR MyStation.EM[16].Shielding)
	AND (MyStation.EM[17].Ready OR MyStation.EM[17].Shielding)
	AND (MyStation.EM[18].Ready OR MyStation.EM[18].Shielding)
	AND (MyStation.EM[19].Ready OR MyStation.EM[19].Shielding)
	AND (MyStation.EM[20].Ready OR MyStation.EM[20].Shielding)
	AND NOT MyStation.EM[0].Shielding;


(********************************************	设备初始化完成状态		*********************************************)
MyStation.EM[0].ResetComplete:=TRUE
	AND (MyStation.EM[1].ResetComplete OR MyStation.EM[1].Shielding)
	AND (MyStation.EM[2].ResetComplete OR MyStation.EM[2].Shielding)
	AND (MyStation.EM[3].ResetComplete OR MyStation.EM[3].Shielding)
	AND (MyStation.EM[4].ResetComplete OR MyStation.EM[4].Shielding)
	AND (MyStation.EM[5].ResetComplete OR MyStation.EM[5].Shielding)
	AND (MyStation.EM[6].ResetComplete OR MyStation.EM[6].Shielding)
	AND (MyStation.EM[7].ResetComplete OR MyStation.EM[7].Shielding)
	AND (MyStation.EM[8].ResetComplete OR MyStation.EM[8].Shielding)
	AND (MyStation.EM[9].ResetComplete OR MyStation.EM[9].Shielding)
	AND (MyStation.EM[10].ResetComplete OR MyStation.EM[10].Shielding)
	AND (MyStation.EM[11].ResetComplete OR MyStation.EM[11].Shielding)
	AND (MyStation.EM[12].ResetComplete OR MyStation.EM[12].Shielding)
	AND (MyStation.EM[13].ResetComplete OR MyStation.EM[13].Shielding)
	AND (MyStation.EM[14].ResetComplete OR MyStation.EM[14].Shielding)
	AND (MyStation.EM[15].ResetComplete OR MyStation.EM[15].Shielding)
	AND (MyStation.EM[16].ResetComplete OR MyStation.EM[16].Shielding)
	AND (MyStation.EM[17].ResetComplete OR MyStation.EM[17].Shielding)
	AND (MyStation.EM[18].ResetComplete OR MyStation.EM[18].Shielding)
	AND (MyStation.EM[19].ResetComplete OR MyStation.EM[19].Shielding)
	AND (MyStation.EM[20].ResetComplete OR MyStation.EM[20].Shielding)
	AND NOT MyStation.EM[0].Shielding;


(********************************************	设备初始化中状态		*********************************************)
//获取模组的初始化中状态
MyStation.EM[1].Resting:=Act.Act04_Init[1];
MyStation.EM[2].Resting:=Act.Act04_Init[2];
MyStation.EM[3].Resting:=Act.Act04_Init[3];
MyStation.EM[4].Resting:=Act.Act04_Init[4];
MyStation.EM[5].Resting:=Act.Act04_Init[5];
MyStation.EM[6].Resting:=Act.Act04_Init[6];
MyStation.EM[7].Resting:=Act.Act04_Init[7];
MyStation.EM[8].Resting:=Act.Act04_Init[8];
