MyStation.EM[10].Resting:=Act.Act04_Init[10];
MyStation.EM[11].Resting:=Act.Act04_Init[11];
MyStation.EM[12].Resting:=Act.Act04_Init[12];
MyStation.EM[13].Resting:=Act.Act04_Init[13];
MyStation.EM[14].Resting:=Act.Act04_Init[14];
