MyStation.EM[18].Resting:=Act.Act04_Init[18];
MyStation.EM[19].Resting:=Act.Act04_Init[19];
MyStation.EM[20].Resting:=Act.Act04_Init[20];


(********************************************	设备运行状态		*********************************************)
//获取模组的运行状态
MyStation.EM[1].Running:=Act.Act05_Auto[1];
MyStation.EM[2].Running:=Act.Act05_Auto[2];
MyStation.EM[3].Running:=Act.Act05_Auto[3];
MyStation.EM[4].Running:=Act.Act05_Auto[4];
MyStation.EM[5].Running:=Act.Act05_Auto[5];
MyStation.EM[6].Running:=Act.Act05_Auto[6];
MyStation.EM[7].Running:=Act.Act05_Auto[7];
MyStation.EM[8].Running:=Act.Act05_Auto[8];
MyStation.EM[9].Running:=Act.Act05_Auto[9];
MyStation.EM[10].Running:=Act.Act05_Auto[10];
MyStation.EM[11].Running:=Act.Act05_Auto[11];
MyStation.EM[12].Running:=Act.Act05_Auto[12];
MyStation.EM[13].Running:=Act.Act05_Auto[13];
MyStation.EM[14].Running:=Act.Act05_Auto[14];
MyStation.EM[15].Running:=Act.Act05_Auto[15];
MyStation.EM[16].Running:=Act.Act05_Auto[16];
