MyStation.EM[18].Running:=Act.Act05_Auto[18];
MyStation.EM[19].Running:=Act.Act05_Auto[19];
MyStation.EM[20].Running:=Act.Act05_Auto[20];

//汇总运行状态
MyStation.EM[0].Running:=TRUE
	AND (MyStation.EM[1].Running OR MyStation.EM[1].Shielding)
	AND (MyStation.EM[2].Running OR MyStation.EM[2].Shielding)
	AND (MyStation.EM[3].Running OR MyStation.EM[3].Shielding)
	AND (MyStation.EM[4].Running OR MyStation.EM[4].Shielding)
	AND (MyStation.EM[5].Running OR MyStation.EM[5].Shielding)
	AND (MyStation.EM[6].Running OR MyStation.EM[6].Shielding)
	AND (MyStation.EM[7].Running OR MyStation.EM[7].Shielding)
	AND (MyStation.EM[8].Running OR MyStation.EM[8].Shielding)
	AND (MyStation.EM[9].Running OR MyStation.EM[9].Shielding)
	AND (MyStation.EM[10].Running OR MyStation.EM[10].Shielding)
	AND (MyStation.EM[11].Running OR MyStation.EM[11].Shielding)
	AND (MyStation.EM[12].Running OR MyStation.EM[12].Shielding)
	AND (MyStation.EM[13].Running OR MyStation.EM[13].Shielding)
	AND (MyStation.EM[14].Running OR MyStation.EM[14].Shielding)
	AND (MyStation.EM[15].Running OR MyStation.EM[15].Shielding)
	AND (MyStation.EM[16].Running OR MyStation.EM[16].Shielding)
	AND (MyStation.EM[17].Running OR MyStation.EM[17].Shielding)
	AND (MyStation.EM[18].Running OR MyStation.EM[18].Shielding)
	AND (MyStation.EM[19].Running OR MyStation.EM[19].Shielding)
	AND (MyStation.EM[20].Running OR MyStation.EM[20].Shielding)
	AND NOT MyStation.EM[0].Shielding;


(********************************************	设备停止状态		*********************************************)
//输出设备停止信号
TP_StationStopping(In:=Signal_StatusManualRT
		OR Signal_StopInputRT
		OR Signal_StationAlarmRT
		, PT:=T#50MS);
MyStation.EM[0].Stopping:=TP_StationStopping.Q
											OR Signal_StatusManualRT
											OR Signal_StopInputRT
											OR Signal_StationAlarmRT;


(********************************************	模组状态映射		*********************************************)

FOR i:=0 TO MyStation.StationSum DO
	
	IF MyStation.EM[i].Shielding
	THEN
		MyStation.EM[i].Status:=0;//屏蔽中	
	ELSIF MyStation.EM[i].IsAlarm
	THEN
		MyStation.EM[i].Status:=10;//报警中
	ELSIF MyStation.EM[i].Conflict
	THEN
		MyStation.EM[i].Status:=20;//手自动冲突
	ELSIF MyStatus.StatusManual
	THEN
		MyStation.EM[i].Status:=30;//手动状态
	ELSIF MyStation.EM[i].Resting
	THEN
		MyStation.EM[i].Status:=40;//初始化中
	ELSIF (NOT MyStation.EM[i].ResetComplete
		OR NOT MyStation.EM[i].ServoHomed)
	THEN
		MyStation.EM[i].Status:=50;//等待初始化
	ELSIF NOT MyStation.EM[i].Running
	THEN
		MyStation.EM[i].Status:=60;//准备OK
	ELSIF MyStation.EM[i].Running
	THEN
		MyStation.EM[i].Status:=70;//运行中
	END_IF;
	HMI_Conflict[i]	:=MyStation.EM[i].Conflict;//模组手自动冲突
	HMI_IsAlarm[i]:=MyStation.EM[i].IsAlarm;//模组报警
END_FOR;


(********************************************	模组状态屏蔽		*********************************************)
FOR i:=1 TO 13 DO
	R_Shielding[i](CLK:= MyStation.EM[i].Shielding);
	F_Shielding[i](CLK:= MyStation.EM[i].Shielding);
	IF R_Shielding[i].Q
	THEN
		FOR j:=0 TO 9 DO
			MyStation.EMStation[i,j].Shielding:= TRUE;
		END_FOR;
	END_IF
	
	IF F_Shielding[i].Q
	THEN
		FOR j:=0 TO 9 DO
			MyStation.EMStation[i,j].Shielding:= FALSE;
		END_FOR;
	END_IF

END_FOR;

(********************************************	配方参数		*********************************************)

//配方初始名称
IF HMI_Recipe.In.RecipeName[0]=0 THEN HMI_Recipe.In.RecipeName[0]:=49; END_IF;
IF HMI_Recipe.In.RecipeName[10]=0 THEN HMI_Recipe.In.RecipeName[10]:=50; END_IF;
IF HMI_Recipe.In.RecipeName[20]=0 THEN HMI_Recipe.In.RecipeName[20]:=51; END_IF;
IF HMI_Recipe.In.RecipeName[30]=0 THEN HMI_Recipe.In.RecipeName[30]:=52; END_IF;
IF HMI_Recipe.In.RecipeName[40]=0 THEN HMI_Recipe.In.RecipeName[40]:=53; END_IF;
IF HMI_Recipe.In.RecipeName[50]=0 THEN HMI_Recipe.In.RecipeName[50]:=54; END_IF;
IF HMI_Recipe.In.RecipeName[60]=0 THEN HMI_Recipe.In.RecipeName[60]:=55; END_IF;
IF HMI_Recipe.In.RecipeName[70]=0 THEN HMI_Recipe.In.RecipeName[70]:=56; END_IF;
IF HMI_Recipe.In.RecipeName[80]=0 THEN HMI_Recipe.In.RecipeName[80]:=57; END_IF;
IF HMI_Recipe.In.RecipeName[90]=0 THEN HMI_Recipe.In.RecipeName[90]:=65; END_IF;


//配方列表数量
HMI_Recipe.In.RecipeListUpdate[1]:=10;



//配方复制操作
IF HMI_Recipe.In.RecipeCopySelect<=10
	AND HMI_Recipe.In.RecipeCopy
THEN
	IF NOT HMI_Recipe.Out.RecipeCopyDone THEN
		RecipeType[HMI_Recipe.IN.RecipeCopySelect]:=HMI_RecipeData;
		HMI_Recipe.Out.RecipeCopyDone:=TRUE;
	END_IF;
	HMI_Recipe.In.RecipeCopy:=FALSE;
END_IF;

//配方更换操作
IF HMI_Recipe.In.RecipeUploadSelect<=10
	AND HMI_Recipe.In.RecipeUpload
THEN
	IF NOT HMI_Recipe.Out.RecipeUploadDone THEN
		HMI_RecipeData:=RecipeType[HMI_Recipe.IN.RecipeUploadSelect];
		HMI_Recipe.Out.RecipeUploadDone:=TRUE;
	END_IF;
	HMI_Recipe.In.RecipeUpload:=FALSE;
END_IF;

//配方复制完成复位
IF NOT HMI_Recipe.Out.RecipeCopyDone THEN
	RecipeCopyDoneTime_Temp:=0;
ELSIF HMI_Recipe.Out.RecipeCopyDone
	AND RecipeCopyDoneTime_Temp>=3
THEN
	HMI_Recipe.Out.RecipeCopyDone:=FALSE;
ELSIF HMI_Recipe.Out.RecipeCopyDone
	AND Signal_1000msRT
THEN
	RecipeCopyDoneTime_Temp:=RecipeCopyDoneTime_Temp+1;
END_IF;

//配方更换完成复位
IF NOT HMI_Recipe.Out.RecipeUploadDone THEN
	RecipeUploadDoneTime_Temp:=0;
ELSIF HMI_Recipe.Out.RecipeUploadDone
	AND RecipeUploadDoneTime_Temp>=3
THEN
	HMI_Recipe.Out.RecipeUploadDone:=FALSE;
ELSIF HMI_Recipe.Out.RecipeUploadDone
	AND Signal_1000msRT
THEN
	RecipeUploadDoneTime_Temp:=RecipeUploadDoneTime_Temp+1;
END_IF;


