	FC_R_TRIG(InOut:=R_VulnerablePart[i]);
	IF R_VulnerablePart[i].Q THEN
		//使用次数计数
		VulnerablePart[i].UseNum:=VulnerablePart[i].UseNum+1;
	END_IF;
END_FOR;
//计数后需要复位操作
Clear(EM05V.VehicleSpringExcute);

//初始参数
IF VulnerablePart[0].LimitSum=0 THEN
	HC_OmronUtils.DtToString(In:= GetTime(), Out=>ChangeTime_String );
FOR i:=1 TO 99 BY 1 DO
	//使用警告次数
	IF VulnerablePart[i].WarningSum=0 THEN VulnerablePart[i].WarningSum:=900000; END_IF;
	//使用报警次数
	IF VulnerablePart[i].LimitSum=0 THEN VulnerablePart[i].LimitSum:=900000; END_IF;
	//更换时间
	VulnerablePart[i].ChangeTime:=LEFT(STR:=ChangeTime_String, SIZE:=19);
END_FOR;
END_IF;
IF VulnerablePart[99].LimitSum>0 THEN
	VulnerablePart[0].LimitSum:=1;
ELSE
	VulnerablePart[0].LimitSum:=0;
END_IF

//输出状态
IF Signal_100msRT THEN
FOR i:=1 TO 99 BY 1 DO
	//使用次数警告
	VulnerablePart[i].Warning:=VulnerablePart[i].UseNum>=VulnerablePart[i].WarningSum;
	//使用次数报警
	VulnerablePart[i].Alarm:=VulnerablePart[i].UseNum>=VulnerablePart[i].LimitSum;
END_FOR;
END_IF;

//更换确认

HC_OmronUtils.DtToString(In:=GetTime(),Out=>DTString);
FOR i:=1 TO 99 BY 1 DO
IF VulnerablePart[i].Confirm THEN
	//使用次数清零
	VulnerablePart[i].UseNum:=0;
	//更换时间
	VulnerablePart[i].ChangeTime:=LEFT(STR:=DTString, SIZE:=19);

END_IF;
END_FOR;

//易损件弹窗
IF Signal_1000msRT THEN
FOR i:=1 TO 50 BY 1 DO
	//易损件警告弹窗
	IF VulnerablePart[i].Warning THEN
		VulnerablePart[0].Warning:=TRUE;
	END_IF;
	//易损件报警弹窗
	IF VulnerablePart[i].Alarm THEN
		VulnerablePart[0].Alarm:=TRUE;
	END_IF;
END_FOR;
END_IF;



//润滑弹窗
