	EM10V.Axis_X1.In.MaxTrqClear_HMI:=FALSE;
	EM10V.Axis_R1.In.MaxTrqClear_HMI:=FALSE;
	EM10V.Axis_Y1.In.MaxTrqClear_HMI:=FALSE;
	EM11V.Axis_Z1.In.MaxTrqClear_HMI:=FALSE;
	EM09V.Axis_Y1.In.MaxTrqClear_HMI:=FALSE;
	EM11V.Axis_R1.In.MaxTrqClear_HMI:=FALSE;
	EM11V.Axis_Y2.In.MaxTrqClear_HMI:=FALSE;
	EM11V.Axis_R2.In.MaxTrqClear_HMI:=FALSE;
	EM11V.Axis_X1.In.MaxTrqClear_HMI:=FALSE;
	EM11V.Axis_Y3.In.MaxTrqClear_HMI:=FALSE;
	EM11V.Axis_X2.In.MaxTrqClear_HMI:=FALSE;
	EM08V.Axis_X1.In.MaxTrqClear_HMI:=FALSE;
	EM13V.Axis_X1.In.MaxTrqClear_HMI:=FALSE;
	EM13V.Axis_X2.In.MaxTrqClear_HMI:=FALSE;
	EM13V.Axis_Z1.In.MaxTrqClear_HMI:=FALSE;
