	EM01H_Robot[0].Out.Axis_R1.ActTrqMaxClear:=FALSE;
	EM03H_Robot[0].Out.Axis_X1.ActTrqMaxClear:=FALSE;
	EM03H_Robot[0].Out.Axis_Y1.ActTrqMaxClear:=FALSE;
	EM03H_Robot[0].Out.Axis_Z1.ActTrqMaxClear:=FALSE;
	EM03H_Robot[0].Out.Axis_R1.ActTrqMaxClear:=FALSE;
END_IF

data.STCode:
IF Operation[0].Reset=1 THEN;
	FOR Num:=0 TO 100 DO ;
		CP_Upper_Alarm[Num]:=0;
		CP_Lower_Alarm[Num]:=0;
	END_FOR;
END_IF;

IF (SystemTime.Hour>8 AND SystemTime.Hour<20)
THEN
	PackTags.Admin.ProdProcessedCount[1].AccCount:= REAL_TO_DINT(HMI_OEE.ProductDay_Date[0]);
	ELSE
	PackTags.Admin.ProdProcessedCount[1].AccCount:= REAL_TO_DINT(HMI_OEE.ProductNight_Date[0]);
END_IF

//--------参数初始化-----------------------------------------------------------------------------------------------------------------------
uiSendDataLimit:=150;//最大发送动作数

//---------最大发送间隔300ms---------------------------------------------------------------------------------------------------------------
tSend(IN:=(NOT bSend_Flag) AND (uiFIFOlen>=1) AND bTcpConnectOK,PT:=T#300ms);

//报文拼接发送
IF((uiFIFOlen>uiSendDataLimit) OR tSend.Q) AND (NOT bSend_Flag) THEN
	Clear(abySendBytes);//报文清空
	//--------报文拼接---------------------------------------------------------------------------------------------------------------------
	abySendBytes[0]:=00;//包头两个0x00
	abySendBytes[1]:=00;//包头两个0x00
	ToAryByte(In:=uiFIFOlen, Order:=HC_OmronUtils._eBYTE_ORDER._LOW_HIGH, AryOut:=abySendBytes[2]);//动作计数
	FOR uiIndex:=0 TO (uiFIFOlen-1) BY 1 DO
		ToAryByte(In:=ausiEMNum[uiIndex], Order:=HC_OmronUtils._eBYTE_ORDER._LOW_HIGH, AryOut:=abySendBytes[uiIndex*6+4]);//工位号 1字节
		ToAryByte(In:=ausiActionParallelNum[uiIndex], Order:=HC_OmronUtils._eBYTE_ORDER._LOW_HIGH, AryOut:=abySendBytes[uiIndex*6+5]);//动作并行号 1字节
		ToAryByte(In:=auiActionNum[uiIndex], Order:=HC_OmronUtils._eBYTE_ORDER._LOW_HIGH, AryOut:=abySendBytes[uiIndex*6+6]);//动作号 2字节
		ToAryByte(In:=auiActionTime[uiIndex], Order:=HC_OmronUtils._eBYTE_ORDER._LOW_HIGH, AryOut:=abySendBytes[uiIndex*6+8]);//动作时间 2字节
	END_FOR;	
	bSend_Flag:=TRUE;//发送标志
	uiSend_Size:=uiFIFOlen*6+4;	//报文长度(字节)
	//--------供调试查看-------------------------------------------------------------------------------------------------------------------
	IF uiFIFOlen>UINT#160 THEN INC(uiCount);END_IF;//大包计数 内部查看
	ARYSHL(InOut:=auiFIFOlen[0],Size:=100,Num:=1);//发送动作数存储供查看
	auiFIFOlen[0]:=uiFIFOlen;
	ARYSHL(InOut:=auiSendTimeInterval[0],Size:=100,Num:=1);
	GetSystemTime(udiTimeMs=>udtSendTime);
	auiSendTimeInterval[0]:=TO_UINT(udtSendTime-udtSendTimeLast);//发送时间间隔存储供查看ms
	udtSendTimeLast:=udtSendTime;
	//--------动作数清零-------------------------------------------------------------------------------------------------------------------
	uiFIFOlen:=0;
END_IF;

//--------配置-------------------------------------------------------------------------------------------------------------------
fbSTC1_ADDRESS.strIPAddr:='192.168.0.207';//服务器IP	【依机台实际配置】
fbSTC1_ADDRESS.uiPort:=UINT#8012;//服务器端口 【依机台实际配置】
fbSTC1_CONNECT_ID:=237;//TCP链接ID【注意不要和程序上其它的TCP链接ID重复】
bErrorReset:=Reset[0] OR MyInput.Reset_Input;//报警复位 	【依机台实际配置】
bEMTimeTcpFun:=TRUE;
bEMTimeTcpFun:=bEMTimeTcpFun;//工位动作计时Tcp启用

//--------进入异常处理流程------------------------------------------------------------------------------------------------------
ftgEMTimeTcpFunClose(CLK:=bEMTimeTcpFun); 
IF ftgEMTimeTcpFunClose.Q OR tEMTCPReConnect.Q THEN 
	uiTcpStep:=UINT#70;	
END_IF;

//--------TCP链接和数据发送-----------------------------------------------------------------------------------------------------
CASE uiTcpStep OF
    0 : 
		IF tPowerOn.Q AND bEMTimeTcpFun THEN 
			uiTcpStep:=UINT#5;
		END_IF;
	5://建立链接
		bTCPStart:=TRUE;
		IF bTcpConnectOK THEN //连接成功
			uiTcpStep:=UINT#10;	
		END_IF;
		IF bfbSTC1_Error THEN //连接失败
			uiTcpStep:=UINT#70;	;
		END_IF;
	 10://发送数据
	 	 IF bSend_Flag THEN 
			 bSendData:=TRUE;
		 END_IF;	 
		 IF bSendDone THEN //发送成功
			 bSendData:=FALSE;
			 bSend_Flag:=FALSE;
		END_IF;
		IF bfbSTS1_Error THEN //发送失败
			bSendData:=FALSE;
			uiTcpStep:=UINT#70;	
		END_IF;		
	70://关闭链接
		bTCPStart:=FALSE;
		bConnectClose:=TRUE;
		IF bConnectCloseDone OR bfbSC1_Error  THEN
			bConnectClose:=FALSE;
			uiTcpStep:=UINT#80;	
		END_IF;	
	80://等待3S
		IF tEMTCPClose.Q THEN 
			uiTcpStep:=UINT#0;	
		END_IF;	
END_CASE;  

//--------计时-------------------------------------------------------------------------------------------------------------------
tPowerOn(IN:=TRUE,PT:=T#20S);//开机20S

tEMTCPClose(IN:=(uiTcpStep=UINT#80),PT:=T#5S);//关闭链接持续5秒

//TCP连接断开三秒重连
tEMTCPReConnect(IN:=(fbSGTS1_TcpStatus<>TCP_STATUS.TCP_ESTABLISHED) AND (NOT bfbSTC1_Busy) AND (NOT tEMTCPReConnect.Q) AND bEMTimeTcpFun AND (uiTcpStep<>UINT#80),PT:=T#3S);

//TCP连接持续断开报警
tEMTcpAlarm(IN:=fbSGTS1_TcpStatus<>TCP_STATUS.TCP_ESTABLISHED,PT:=T#10S);
IF tEMTcpAlarm.Q THEN 
	bTCPConnectNG:=bEMTimeTcpFun;
END_IF;
IF bErrorReset AND  fbSGTS1_TcpStatus=TCP_STATUS.TCP_ESTABLISHED THEN 
	bTCPConnectNG:=FALSE;
END_IF;

//500ms周期轮询TCP状态
tPolling(IN:=((NOT tPolling.Q) AND bEMTimeTcpFun AND (NOT bfbSGTS1_Busy)) , PT:=T#500MS);//

//--------功能调用-------------------------------------------------------------------------------------------------------------------
//建立连接
fbSTC1_diTimeOut:=100;//100ms链接超时时间，系统默认50ms
fbSTC1(xExecute:=bTCPStart,
	   diConnectID:= fbSTC1_CONNECT_ID,
	   stServerAddress:=fbSTC1_ADDRESS,
	   diTimeOut:=fbSTC1_diTimeOut,
	   xDone=>bTcpConnectOK,//TCP连接成功
	   xBusy=>bfbSTC1_Busy,//TCP连接中
	   xError=>bfbSTC1_Error,
	   wErrorID=>wfbSTC1_ErrorID,
	   stConnectInfo=>fbSTC1_ConnectInfo);

//轮询TCP状态
fbSGTS1(xEnable:=bfbSGTS1_Busy OR tPolling.Q, // 链接关闭后需重启查询使能
		diConnectID:=fbSTC1_CONNECT_ID,
		xDone=>bfbSGTS1_Done ,
		xBusy=>bfbSGTS1_Busy ,
		xError=>bfbSGTS1_Error ,
		wErrorID=>wfbSGTS1_ErrorID ,
		eStatus=>fbSGTS1_TcpStatus ,
		stConnectInfo=>fbSGTS1_ConnectInfo);

//数据发送
fbSTS1_uiTimeOut:=UINT#100;////100ms发送超时时间，系统默认50ms
fbSTS1(xExecute:=bSendData ,
	   diConnectID:=fbSTC1_CONNECT_ID ,
	   abyData:=abySendBytes[0] ,
	   uiDataSize:=uiSend_Size ,
	   uiTimeOut:=fbSTS1_uiTimeOut,
	   xDone=>bSendDone ,
	   xBusy=>bfbSTS1_Busy ,
	   xError=>bfbSTS1_Error ,
	   wErrorID=>wfbSTS1_ErrorID);

//关闭连接
fbSC1(xExecute:=bConnectClose ,
		diConnectID:=fbSTC1_CONNECT_ID ,
		xDone=>bConnectCloseDone ,
		xBusy=>bfbSC1_Busy ,
		xError=>bfbSC1_Error ,
		wErrorID=>wfbSC1_ErrorID);

ST.xhtml:
//判断账号当前长度是否大于0
 Login_R(Clk:=LEN(STR:=CATL_Login_String ) > 0);       
 IF Login_R.Q THEN 
	 CATL_Login_Int := 8 ; //触发上位机登入
 END_IF;	 
 
//异常或等待10s后清除复位
TON_LoginClear(In:=LEN(STR:=CATL_Login_String)>0 OR CATL_Login_Int <>10 , PT:=T#10S);
IF TON_LoginClear.Q THEN 
	 CATL_Login_Int  := 10 ; //触发上位机登入
	 CATL_Login_String:='';
END_IF;
	
//CLINK登录
IF (CATL_Login_Int=1 OR CATL_Login_Int=2 OR CATL_Login_Int=3 OR CATL_Login_Int=4 OR CATL_Login_Int=5 OR CATL_Login_Int=7) THEN
	CATL_Login_Level:=CATL_Login_Int;  //权限传递
END_IF;

CATL_Login_JobNumber:=CATL_Login_WorkNumber; //工号传递

