//=======================================标准SPC功能块，勿删=================================================================
//1)  SPC_Alarm 由SPC系统通过Clink下发至PLC
//2)  当SPC_Alarm后三位为‘001’时，触发外部条件S01.Condition[3]（用于声光提示）& SPC_Control（弹窗）
//3）当SPC_Alarm后三位为‘004’时，触发外部条件S01.Condition[4]（用于声光提示）& SPC_Stop（弹窗）& 设备停机（报警）

//=======================================Standard SPC Function Block, Do Not Delete=================================================================
//1)  SPC_Alarm sent to PLC by SPC system through Clink
//2)  When the last three digits of SPC_Alarm are '001', trigger the external condition S01.Condition[3] (used for audio and visual prompts) & SPC_Control (pop-up window)
//3）When the last three digits of SPC_Alarm are '004', trigger the external condition S01.Condition[4] (used for audio and visual prompts) & SPC_Stop (pop-up window) & device shutdown (alarm)

// Function : CATL AG
// (c)Copyright 2025 All Rights Reserved
//=============================================标准智慧停机功能块，勿删=================================================
//   Case  ZHTJ_Stop_Reason
//     0：正常状态；                                                                         0：Normal State；
//     1：TOM停机弹窗、灯光提示；                                                   1：TOM ShutDown Pop-Up Window & Light Prompt；
//     2：TOM停机弹窗、灯光提示、设备停机报警；                              2：TOM ShutDown 8 & Light Prompt & Device Stop；
//     3： MES锁机弹窗、灯光提示；                                                   3：MES Lock Pop-Up Window & Light Prompt； 
//    11：EPM参数超限警告弹窗；                                                    11：EPM Parameter out-of-limit warning Pop-Up Window;
//    12：EPM参数超限停机弹窗、设备停机；                                     12：EPM Parameter out-of-limit Stop Pop-Up Window & Device Stop ;
//    13：上下游设备EPM参数异常已停机警告；                                  13：Abnormal EPM Parameters  of upstream and downstream ShutDown Pop-Up Warning-Window;

data.STCode:
IF HMI_Shield2 THEN
	IF NOT MM THEN
		PackTags.Status.MachineStatus:= 100;
		PackML_AlarmUploading:=10000000;
		TON_103(in:=NOT TON_103.Q ,PT:=T#16S ,Q=> ,ET =>);
		IF TON_103.Q THEN
;
			MM:=TRUE;
		END_IF

	END_IF
	IF MM THEN
			PackML_AlarmUploading:=4509452;
			PackTags.Status.MachineStatus:=45;
	END_IF
	IF AutoRun THEN
		TON_100(in:=NOT TON_100.Q,PT:=T#2H ,Q=> ,ET =>);

		IF TON_100.Q THEN
			MM:=FALSE;
			HMI_Shield2:=FALSE;
		END_IF;
	END_IF
		TON_101(in:=NOT TON_101.Q,PT:=T#2H ,Q=> ,ET =>);
		IF TON_101.Q THEN
			MM:=FALSE;
			HMI_Shield2:=FALSE;
		END_IF;
END_IF

