06V.Cy_Shift2.Out ;// EM06Cy36_2#上保护盖气缸 Cy[36] := EM06V.Cy_WeldDustRemoval1.Out ;// EM06Cy37_1#焊接遮光气缸 Cy[37] := EM06V.Cy_WeldDustRemoval2.Out ;// EM06Cy38_2#焊接遮光气缸 Cy[38] := EM06V.Cy_Clamp2_1.Out ;// EM06Cy39_2#保护盖侧边压紧气缸1 Cy[39] := EM06V.Cy_Clamp2_2.Out ;// EM06Cy40_2#保护盖侧边压紧气缸2 Cy[40] := EM06V.Cy_Location1.Out ;// EM06Cy41_1#保护盖替罪羊 Cy[41] := EM06V.Cy_Location2.Out ;// EM06Cy42_2#保护盖替罪羊 Cy[42] := EM08V.Cy_Check1.Out ;// EM08Cy44_扣支架检测气缸1 Cy[43] := EM09V.Cy_Up1.Out ;// EM09Cy45_除尘升降气缸1 Cy[44] := EM09V.Cy_Up2.Out ;// EM09Cy46_除尘升降气缸2 Cy[45] := EM11V.Cy_Open1_1.Out ;// EM11Cy47_1#开胶气缸1 Cy[46] := EM11V.Cy_Open1_2.Out ;// EM11Cy48_1#开胶气缸2 Cy[47] := EM11V.Cy_Press1_1.Out ;// EM11Cy49_1#压胶气缸1 Cy[48] := EM11V.Cy_Press1_2.Out ;// EM11Cy50_1#压胶气缸2 Cy[49] := EM11V.Cy_Open2_1.Out ;// EM11Cy51_2#开胶气缸1 Cy[50] := EM11V.Cy_Open2_2.Out ;// EM11Cy52_2#开胶气缸2 Cy[51] := EM11V.Cy_Press2_1.Out ;// EM11Cy53_2#压胶气缸1 Cy[52] := EM11V.Cy_Press2_2.Out ;// EM11Cy54_2#压胶气缸2 Cy[53] := EM11V.Cy_Clamp1.Out ;// EM11Cy55_夹胶气缸1 Cy[54] := EM11V.Cy_Clamp2.Out ;// EM11Cy56_夹胶气缸2 Cy[55] := EM11V.Cy_Up1.Out ;// EM11Cy57_接胶气缸1 Cy[56] := EM11V.Cy_Up2.Out ;// EM11Cy58_接胶气缸2 Cy[57] := EM11V.Cy_Cut1.Out ;// EM11Cy59_切胶气缸1 Cy[58] := EM11V.Cy_Cut2.Out ;// EM11Cy60_切胶气缸2 Cy[59] := EM12V.Cy_Up1.Out ;// EM12Cy73_上料平移顶升气缸 Cy[60] := EM12V.Cy_Up2.Out ;// EM12Cy74_下料平移顶升气缸 Cy[61] := EM12V.Cy_Push1.Out ;// EM12Cy75_托盘夹紧气缸1 Cy[62] := EM12V.Cy_Push2.Out ;// EM12Cy76_托盘夹紧气缸2 Cy[63] := EM12V.Cy_Push3.Out ;// EM12Cy77_托盘夹紧气缸3 Cy[64] := EM12V.Cy_Push4.Out ;// EM12Cy78_托盘夹紧气缸4 Cy[65] := EM12V.Cy_Separate1.Out ;// EM12Cy79_分盘下压气缸1 Cy[66] := EM12V.Cy_Separate2.Out ;// EM12Cy80_分盘下压气缸2 Cy[67] := EM12V.Cy_Press1.Out ;// EM12Cy81_支架上板链线取料气缸1 Cy[68] := EM12V.Cy_Press2.Out ;// EM12Cy82_支架上板链线取料气缸2 Cy[69] := EM12V.Cy_Location1.Out ;// EM12Cy83_支架固定气缸1 Cy[70] := EM12V.Cy_Location2.Out ;// EM12Cy84_支架固定气缸2 Cy[71] := EM12V.Cy_Clamp1.Out ;// EM12Cy85_支架夹爪气缸1
Cy[72] := EM01V.Va_Plate1.Out ;// Va0托盘移栽吸真空1Y020814 Cy[73] := EM01V.Va_Plate2.Out ;// Va1托盘移栽吸真空2Y020815 Cy[74] := EM01V.Va_Plate3.Out ;// Va2托盘移栽吸真空3Y020816 Cy[75] := EM01V.Va_Plate4.Out ;// Va7托盘移栽吸真空4Y020605 Cy[76] := EM01V.Va_Cover1.Out ;// Va3顶盖夹爪吸真空1Y020715 Cy[77] := EM01V.Va_Cover2.Out ;// Va4顶盖夹爪吸真空2Y020716 Cy[78] := EM01V.Va_Cover3.Out ;// Va5顶盖检测吸真空1Y020812 Cy[79] := EM01V.Va_Cover4.Out ;// Va6顶盖检测吸真空2Y020813 Cy[80] := EM01V.Va_Cover5.Out ;// Va8顶盖夹爪吸真空3Y020603 Cy[81] := EM01V.Va_Cover6.Out ;// Va9顶盖夹爪吸真空4Y020604 Cy[82] := EM11V.Va_Glue1.Out ;// Va0吸胶真空1Y010215 Cy[83] := EM11V.Va_Glue2.Out ;// Va1吸胶真空2Y010216 Cy[84] := EM12V.Va_Plate1.Out ;// Va0托盘移栽吸真空1Y020202 Cy[85] := EM12V.Va_Plate2.Out ;// Va1托盘移栽吸真空2Y020204 Cy[86] := EM12V.Va_Cover1.Out ;// Va2支架上料吸真空1Y020705 Cy[87] := EM12V.Va_Cover2.Out ;// Va3支架上料吸真空2Y020706 Cy[88] := EM12V.Va_Cover3.Out ;// Va4支架上板链线吸真空1Y020707 Cy[89] := EM12V.Va_Cover4.Out ;// Va5支架上板链线吸真空2Y020708 Cy[90] := EM12V.Va_Cover5.Out ;// Va6支架缓存吸真空1Y020713 Cy[91] := EM12V.Va_Cover6.Out ;// Va7支架缓存吸真空2Y020714 Cy[92] := EM12V.Va_Cover7.Out ;// Va8支架上料吸真空3Y020601 Cy[93] := EM12V.Va_Cover8.Out ;// Va9支架上料吸真空4Y020602
