//真空 Va[0] := EM01V.Va_Plate1.Out ;// Va0托盘移栽吸真空1Y020814 Va[1] := EM01V.Va_Plate2.Out ;// Va1托盘移栽吸真空2Y020815 Va[2] := EM01V.Va_Plate3.Out ;// Va2托盘移栽吸真空3Y020816 Va[3] := EM01V.Va_Plate4.Out ;// Va7托盘移栽吸真空4Y020605 Va[4] := EM01V.Va_Cover1.Out ;// Va3顶盖夹爪吸真空1Y020715 Va[5] := EM01V.Va_Cover2.Out ;// Va4顶盖夹爪吸真空2Y020716 Va[6] := EM01V.Va_Cover3.Out ;// Va5顶盖检测吸真空1Y020812 Va[7] := EM01V.Va_Cover4.Out ;// Va6顶盖检测吸真空2Y020813 Va[8] := EM01V.Va_Cover5.Out ;// Va8顶盖夹爪吸真空3Y020603 Va[9] := EM01V.Va_Cover6.Out ;// Va9顶盖夹爪吸真空4Y020604 Va[10] := EM11V.Va_Glue1.Out ;// Va0吸胶真空1Y010215 Va[11] := EM11V.Va_Glue2.Out ;// Va1吸胶真空2Y010216 Va[12] := EM12V.Va_Plate1.Out ;// Va0托盘移栽吸真空1Y020202 Va[13] := EM12V.Va_Plate2.Out ;// Va1托盘移栽吸真空2Y020204 Va[14] := EM12V.Va_Cover1.Out ;// Va2支架上料吸真空1Y020705 Va[15] := EM12V.Va_Cover2.Out ;// Va3支架上料吸真空2Y020706 Va[16] := EM12V.Va_Cover3.Out ;// Va4支架上板链线吸真空1Y020707 Va[17] := EM12V.Va_Cover4.Out ;// Va5支架上板链线吸真空2Y020708 Va[18] := EM12V.Va_Cover5.Out ;// Va6支架缓存吸真空1Y020713 Va[19] := EM12V.Va_Cover6.Out ;// Va7支架缓存吸真空2Y020714 Va[20] := EM12V.Va_Cover7.Out ;// Va8支架上料吸真空3Y020601 Va[21] := EM12V.Va_Cover8.Out ;// Va9支架上料吸真空4Y020602
(******************************************** 气缸预测性维护监控功能块 *********************************************) FOR n:=0 TO 25 BY 1 DO
FB_真空预测性维护[n]( OpenStart:= Va[n].YR , SwitchOn:= Va[n].XR , AlarmStart:= Va[n].Alarm_Out[0] , AlarmReset:= MyInput.Reset_Input , OpenCycleTime=> FM.VacuumIn[n].OpenTime , AlarmNum=> FM.VacuumOut[n].AlarmNum );
END_FOR;

// g_iCEA_No: INT;
// 	g_iCEA_test1: ARRAY[0..100] OF BOOL;
// 	g_iCEA_test2: ARRAY[0..100] OF BOOL;
// 	g_iCEA_test3: ARRAY[0..100] OF BOOL;
// 	g_iCEA_test4: ARRAY[0..100] OF BOOL;
// 	g_iCEA_test5: ARRAY[0..100] OF BOOL;
// 	g_iCEA_done: ARRAY[0..100] OF BOOL;
// 	g_iCEA_ng: ARRAY[0..100] OF BOOL;
// 	g_iCEA_CYout: ARRAY[0..100] OF BOOL;
// 	g_iCEA_CYsensor: ARRAY[0..100] OF BOOL;
// 	g_iCEA_Status: ARRAY[0..100] OF BOOL;
// 	g_iCEA_shield: ARRAY[0..100] OF BOOL;
// 	g_iCEA_Check_TON: ARRAY[0..100] OF TON;
// 	g_iCEA_Statu_TON: ARRAY[0..100] OF TON;
// 	
// 	g_iCEA_Count: ARRAY[0..100] OF INT;
// 	g_iCEA_CountNG: ARRAY[0..100] OF INT;
// 	g_iCEA_CountOK: ARRAY[0..100] OF INT;
// 	
// 	g_iCEA_rTRIG_ng: ARRAY[0..100] OF R_TRIG;
// 	g_iCEA_rTRIG: ARRAY[0..100] OF R_TRIG;
// 	g_iCEA_CYout_rTRIG: ARRAY[0..100] OF R_TRIG;
// 	g_iCEA_CYout_fTRIG: ARRAY[0..100] OF F_TRIG;

FOR g_iCEA_No := 0 TO 100 BY 1 DO
    //IF g_iCEA_shield[g_iCEA_No] THEN //自愈屏蔽
        g_iCEA_CYout[g_iCEA_No] := Cy[g_iCEA_No].YV OR g_iCEA_test4[g_iCEA_No];//气缸动作
        g_iCEA_CYsensor[g_iCEA_No] := Cy[g_iCEA_No].XV OR g_iCEA_test5[g_iCEA_No];//气缸传感器
        //自愈动作触发
        g_iCEA_Check_TON[g_iCEA_No](IN := g_iCEA_CYout[g_iCEA_No] AND NOT g_iCEA_CYsensor[g_iCEA_No] AND NOT g_iCEA_Status[g_iCEA_No] AND NOT g_iCEA_ng[g_iCEA_No], PT := T#1.5S, Q => , ET => );
        g_iCEA_rTRIG[g_iCEA_No](clk := g_iCEA_Check_TON[g_iCEA_No].Q OR g_iCEA_test1[g_iCEA_No], q => );
        IF g_iCEA_rTRIG[g_iCEA_No].Q THEN
            g_iCEA_Status[g_iCEA_No] := TRUE;
            inc(g_iCEA_Count[g_iCEA_No]);//自愈加1
        END_IF
        //自愈持续时间
        g_iCEA_Statu_TON[g_iCEA_No](IN := g_iCEA_Status[g_iCEA_No] AND g_iCEA_CYout[g_iCEA_No], PT := T#3S, Q => , ET => );
        g_iCEA_rTRIG_ng[g_iCEA_No](clk := g_iCEA_Statu_TON[g_iCEA_No].Q OR g_iCEA_test2[g_iCEA_No], q => );
        IF g_iCEA_rTRIG_ng[g_iCEA_No].Q THEN
            g_iCEA_Status[g_iCEA_No] := FALSE;
			g_iCEA_ng[g_iCEA_No] := TRUE;
            inc(g_iCEA_CountNG[g_iCEA_No]);//自愈ng加1
        END_IF
        //治愈成功，或者刷新状态
        IF (g_iCEA_CYout[g_iCEA_No] AND g_iCEA_CYsensor[g_iCEA_No] AND g_iCEA_Status[g_iCEA_No]) OR g_iCEA_test3[g_iCEA_No] THEN
            g_iCEA_Status[g_iCEA_No] := FALSE;
			g_iCEA_ng[g_iCEA_No] := FALSE;
            g_iCEA_test4[g_iCEA_No] := FALSE;
            g_iCEA_test5[g_iCEA_No] := FALSE;
        END_IF
        //成功次数=自愈次数-ng次数
        g_iCEA_CountOK[g_iCEA_No] := g_iCEA_Count[g_iCEA_No] - g_iCEA_CountNG[g_iCEA_No];
    //END_IF;
END_FOR

