(********************自定义报警********************)
// H_Messages.Station[10].User_Alarm[0] // EM10点胶模组：凸轮表生成中，二次触发报警 // H_Messages.Station[10].User_Alarm[1] // EM10点胶模组：凸轮表生成错误 IF Error_SprialAction[0] THEN H_Messages.Station[10].User_Alarm[2] := TRUE ;// EM10点胶模组：点胶凸轮动作错误---虚轴未准备好 END_IF IF Error_SprialAction[1] THEN H_Messages.Station[10].User_Alarm[3] := TRUE ;// EM10点胶模组：点胶凸轮动作错误---SV31_点胶平移X轴未准备好 END_IF IF Error_SprialAction[2] THEN H_Messages.Station[10].User_Alarm[4] := TRUE ;// // EM10点胶模组：点胶凸轮动作错误---SV34_点胶平移Y轴未准备好 END_IF IF Error_SprialAction[3] THEN H_Messages.Station[10].User_Alarm[5] := TRUE ;// EM10点胶模组：点胶凸轮动作错误---SV31_点胶平移X轴进入凸轮失败 END_IF IF Error_SprialAction[4] THEN H_Messages.Station[10].User_Alarm[6] := TRUE ;// EM10点胶模组：点胶凸轮动作错误---SV34_点胶平移Y轴进入凸轮失败 END_IF IF Error_SprialAction[5] THEN H_Messages.Station[10].User_Alarm[7] := TRUE ;// EM10点胶模组：点胶凸轮动作错误---SV31_点胶平移X轴退出凸轮失败 END_IF
IF Error_SprialAction[6] THEN H_Messages.Station[10].User_Alarm[8] := TRUE ;// EM10点胶模组：点胶凸轮动作错误---SV34_点胶平移Y轴退出凸轮失败 END_IF
(*设定温度赋值*) FOR i:=0 TO 9 BY 1 DO IF HMI_RecipeData.NorsonTemperatureMin[i]=0 THEN HMI_RecipeData.NorsonTemperatureMin[i]:=150; END_IF; IF HMI_RecipeData.NorsonTemperatureMax[i]=0 THEN HMI_RecipeData.NorsonTemperatureMax[i]:=200; END_IF; END_FOR; IF MyInput.Reset_Input THEN Clear(NorsonTemperatureSetErr); END_IF;
IF NOT HMI_TestMode_Enable THEN FOR i:=0 TO 9 BY 1 DO IF HMI_RecipeData.NorsonTemperatureSet[i]<HMI_RecipeData.NorsonTemperatureMin[i] OR HMI_RecipeData.NorsonTemperatureSet[i]>HMI_RecipeData.NorsonTemperatureMax[i] THEN NorsonTemperatureSetErr[i]:=TRUE;//点胶机设定温度错误 END_IF; END_FOR; END_IF ;
H_Messages.Station[10].User_Alarm[9] := NorsonTemperatureSetErr[0] ;// EM10点胶模组：胶桶设定温度超过上下限报警 H_Messages.Station[10].User_Alarm[10] := NorsonTemperatureSetErr[1] ;// EM10点胶模组：胶泵设定温度超过上下限报警 H_Messages.Station[10].User_Alarm[11] := NorsonTemperatureSetErr[2] ;// EM10点胶模组：胶管1设定温度超过上下限报警 H_Messages.Station[10].User_Alarm[12] := NorsonTemperatureSetErr[3] ;// EM10点胶模组：胶枪1设定温度超过上下限报警 H_Messages.Station[10].User_Alarm[13] := NorsonTemperatureSetErr[4] ;// EM10点胶模组：胶管2设定温度超过上下限报警 H_Messages.Station[10].User_Alarm[14] := NorsonTemperatureSetErr[5] ;// EM10点胶模组：胶枪2设定温度超过上下限报警 H_Messages.Station[10].User_Alarm[15] := NorsonTemperatureSetErr[7] ;// EM10点胶模组：胶枪1吹气设定温度超过上下限报警 H_Messages.Station[10].User_Alarm[16] := NorsonTemperatureSetErr[9] ;// EM10点胶模组：胶枪2吹气设定温度超过上下限报警
(*泵速赋值*) FOR i:=0 TO 3 BY 1 DO IF HMI_RecipeData.NorsonMotorSpeedMin[i]=0 THEN HMI_RecipeData.NorsonMotorSpeedMin[i]:=10; END_IF; IF HMI_RecipeData.NorsonMotorSpeedMax[i]=0 THEN HMI_RecipeData.NorsonMotorSpeedMax[i]:=50; END_IF; END_FOR; IF MyInput.Reset_Input THEN Clear(NorsonMotorSpeedSetErr); END_IF;
IF HMI_RecipeData.NorsonMotorSpeed[0]<HMI_RecipeData.NorsonMotorSpeedMin[0] OR HMI_RecipeData.NorsonMotorSpeed[0]>HMI_RecipeData.NorsonMotorSpeedMax[0] THEN NorsonMotorSpeedSetErr[0]:=TRUE;//点胶机设定速度错误 END_IF; H_Messages.Station[10].User_Alarm[17] := NorsonMotorSpeedSetErr[0] ;// EM10点胶模组：主泵设定速度超过上下限报警
IF NOT HMI_Function_Enable[10,0] AND melter_data[0].b_r_Fault THEN H_Messages.Station[10].User_Alarm[18]:=TRUE;//EM10点胶模组：点胶机故障 END_IF;
TON_TankLevelLow( In:=NOT HMI_Function_Enable[10,0] AND melter_data[0].b_r_TankLevelLow , PT:=T#5M); IF TON_TankLevelLow.Q THEN H_Messages.Station[10].User_Alarm[19]:=TRUE;//EM10点胶模组：点胶机长时间液位低未进行处理，禁止开机报警 END_IF;
// IF MyStatus.StatusAuto ///CATL_GJF_820 // AND NOT EM10V.Sen_Have1.Out.Filtered_Q // THEN // H_Messages.Station[10].User_Alarm[20]:=TRUE;//EM10点胶模组：未检测到排胶盒在位报警，请检查接胶盘有料检测 X100403 // END_IF;
IF EM10P.AutoClearGlueNum >= 10 THEN H_Messages.Station[10].User_Alarm[21] := TRUE;//EM10点胶模组：当前排胶次数达到最大值，请及时清理排胶盒 EM10P.AutoClearGlueNum := 0; END_IF;
IF 点胶机._pConnector>0 AND TO_UINT(点胶机.eState)<>8 AND NOT MyStation.EMStation[10,0].Shielding AND NOT HMI_Function_Enable[10,0] THEN H_Messages.Station[10].User_Alarm[22]:=TRUE;//EM10点胶模组：点胶机，EIP连接错误192.168.0.30，请检查网线连接是否正常。 END_IF;
IF EM10P.AutoClearGlueWaitTime>=EM10P.AutoClearGlueWaitTimeSet*60 AND NOT MyStatus.StatusAuto AND NOT HMI_Function_Enable[10,0] THEN H_Messages.Station[10].User_Alarm[23]:=TRUE;//EM10点胶模组：设备待机时间超过设定时间，设备长时间未运行，点胶机需要进行人工排胶，请及时处理！ END_IF; F_Button(Clk:=HMI_Button[10,1] AND HMI_Button[10,2] AND HMI_Button[10,3]); IF F_Button.Q THEN EM10P.AutoClearGlueWaitTime:=0; END_IF;
TON_PumpsOnrErr( In:=NOT HMI_Function_Enable[10,0] AND melter_data[0].b_r_ReadyForOperation AND NOT melter_data[0].b_r_PumpsOn , PT:=T#15S); IF TON_PumpsOnrErr.Q THEN H_Messages.Station[10].User_Alarm[24]:=TRUE;//EM10点胶模组：点胶机主泵无法开启，请将点胶机断电重试，多次出现请联系点胶机供应商； END_IF;
IF MyStatus.StatusAuto AND Act.Act05_Auto_Station[10,0] AND EM10V.Axis_Z1.Out.PosDone[1] AND EM10V.Sen_Have1.Out.Filtered_Q AND EM10V.Sen_Have2.Out.Filtered_Q THEN H_Messages.Station[10].User_Alarm[25]:=TRUE;//EM10点胶模组：检测到 X100404排胶盒满料检查报警，请人工清理 END_IF;
(********************自定义警告********************)
//点胶机未准备就绪 H_Messages.Station[10].User_Warning[0]:=Act.Act05_Auto[10] AND NOT HMI_Function_Enable[10,0] AND NOT melter_data[0].b_r_ReadyForOperation ;
