// EM10点胶模组:手自动冲突 IF NOT Signal_ResetCompleteRT AND MyInput.Start_Input AND NOT MyStation.EM[10].Shielding AND MyStation.EM[10].Conflict THEN H_Messages.Station[10].HinderToPos[25,0] := TRUE ;// EM10点胶模组:手自动冲突 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 IF EM10V.Axis_Z1.Out.Tips_Out[5] THEN H_Messages.Station[10].HinderToPos[25,1] := TRUE ;// EM10点胶模组:SV30_点胶升降Z轴-手自动冲突 END_IF IF EM10V.Axis_X1.Out.Tips_Out[5] THEN H_Messages.Station[10].HinderToPos[25,2] := TRUE ;// EM10点胶模组:SV31_点胶平移X轴-手自动冲突 END_IF IF EM10V.Axis_R1.Out.Tips_Out[5] THEN H_Messages.Station[10].HinderToPos[25,3] := TRUE ;// EM10点胶模组:SV33_点胶毛刷R轴-手自动冲突 END_IF IF EM10V.Axis_Y1.Out.Tips_Out[5] THEN H_Messages.Station[10].HinderToPos[25,4] := TRUE ;// EM10点胶模组:SV34_点胶平移Y轴-手自动冲突 END_IF IF EM10V.Axis_Virtual1.Out.Tips_Out[5] THEN H_Messages.Station[10].HinderToPos[25,5] := TRUE ;// EM10点胶模组:SV100_点胶虚轴-手自动冲突 END_IF END_IF;
(*关闭弹框消除提示*) IF NOT HMI_EQ.ConflictPopups AND NOT H_Messages.ConflictPopups THEN Clear(H_Messages.Station[10].HinderToPos); END_IF;

IF	Act.Act06_IOCall_FB[10]
THEN
//	Y100411	点胶吹气1打开
Blow_GlueDispensing1(
	//BlowName								:='点胶吹气1'										, 
	//BlowOutput								:='Y100411'												, 
	//StrToUnicodeEx						:=StrToUnicodeEx									,
	Auto											:=Act.Act05_Auto[10] 	, 
	StopSelect								:=TRUE													, 
	PT_Blow									:=TIME#0S												, 
	In												:=EM10V.Blow_GlueDispensing1.In					,
	H_In											:=EM10H_Blow[0].H_In						, 
	H_Out										=>EM10H_Blow[0].H_Out						, 
	Out											=>EM10V.Blow_GlueDispensing1.Out				, 
	HMI_Page_Input						:=420														, 
	HMI_ChangePageExecute		:= HMI_SearshPage=99999						//除X外INT类型的感应器编号
														AND HMI_ChangePage_Enable			,//气缸快速查找触发，以输出点查找如
	HMI_Page_Output					:=HMI_ChangePage[0]	
	);

//	Y100412	点胶吹气2打开

Blow_GlueDispensing2(
	//BlowName								:='点胶吹气2'										, 
	//BlowOutput								:='Y100412'												, 
	//StrToUnicodeEx						:=StrToUnicodeEx									,
	Auto											:=Act.Act05_Auto[10] 	, 
	StopSelect								:=TRUE													, 
	PT_Blow									:=TIME#0S												, 
	In												:=EM10V.Blow_GlueDispensing2.In					,
	H_In											:=EM10H_Blow[1].H_In						, 
	H_Out										=>EM10H_Blow[1].H_Out						, 
	Out											=>EM10V.Blow_GlueDispensing2.Out				, 
	HMI_Page_Input						:=420														, 
	HMI_ChangePageExecute		:= HMI_SearshPage=99999						//除X外INT类型的感应器编号
														AND HMI_ChangePage_Enable			,//气缸快速查找触发，以输出点查找如
	HMI_Page_Output					:=HMI_ChangePage[0]	
	);
END_IF;

FOR StationSum := 0 TO StationNum BY 1 DO
	Act.Act05_Auto_Station[EMNumber,StationSum] := Act.Act05_Auto[EMNumber] AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding;
END_FOR;

//设备待机计时
TON_MachineWait(
	In:=NOT (Act.Act05_Auto[10] AND EM10V.Process_steps[0]>=100 AND EM10V.Process_steps[0]<200)
	, PT:=T#10S);
//等待点胶的时间超过30分钟需要自动排胶，1H需要切换到待启动
AutoClearGlue_R(Clk:=GetClk_1s());
IF (melter_data[0].b_r_ReadyForOperation
	AND NOT HMI_Function_Enable[10,0]
		OR HMI_Button[10,6])
	AND TON_MachineWait.Q
	AND AutoClearGlue_R.Q
THEN
	EM10P.AutoClearGlueWaitTime:=EM10P.AutoClearGlueWaitTime+1;
ELSIF (NOT TON_MachineWait.Q
	OR NOT melter_data[0].b_r_ReadyForOperation
	OR HMI_Function_Enable[10,0])
	AND NOT HMI_Button[10,6]
THEN 
	EM10P.AutoClearGlueWaitTime:=0;
END_IF;
//自动排胶待机设定时间（min）
IF EM10P.AutoClearGlueWaitTimeSet<=0 THEN
	EM10P.AutoClearGlueWaitTimeSet:=30;
END_IF;
//设备待机时间超过设定时间，自动排一次胶
IF EM10P.AutoClearGlueWaitTime>=EM10P.AutoClearGlueWaitTimeSet*60
	AND Act.Act05_Auto[10]
THEN
	EM10P.AutoClearGlue:=TRUE;
	EM10P.AutoClearGlueWaitTime:=0;
END_IF;


(******************************************** 点胶机加热控制 *********************************************)
//点胶机待机保温时间（min）
IF EM10P.StandbyTime<=0 THEN
	EM10P.StandbyTime:=45;
END_IF;
//点胶机停止加热时间（h）
IF EM10P.HeatersOffTime<=0 THEN
	EM10P.HeatersOffTime:=2;
END_IF;
IF MyStatus.StatusAuto
	//AND Act.Act05_Auto[10]
	AND NOT MyStation.EM[10].IsAlarm
	OR HMI_Button[10,5]
THEN
	//点胶机进入待机保温或停止加热的计时（s）时间清零
	TimeData_NorsonTemperatureSet:=0;
	IF NOT HMI_Function_Enable[10,0]
	THEN
		//点胶机功能启用，无报警且旋转按钮处于自动状态时-------点胶机启动加热
		TON_r_HeatON(In:=NOT HMI_Function_Enable[10,0] AND NOT melter_data[0].b_r_HeatOn AND NOT melter_data[0].b_w_HeatersOnOff, PT:=T#3S);
		IF TON_r_HeatON.Q THEN
			melter_data[0].b_w_HeatersOnOff:=TRUE;
		TON_r_HeatON(In:=FALSE, PT:=T#3S);
		END_IF;
		//点胶机功能启用，无报警且旋转按钮处于自动状态时-------点胶机关闭待机保温模式
		TON_w_StandbyOn(In:=melter_data[0].b_r_StandByOn AND NOT melter_data[0].b_w_StandbyOnOff, PT:=T#5S);
	    IF  TON_w_StandbyOn.Q THEN
			melter_data[0].b_w_StandbyOnOff:=TRUE;
			TON_w_StandbyOn(In:=FALSE, PT:=T#5S);
		END_IF;
	ELSE
		//点胶机功能未启用-------点胶机停止加热
		TON_r_HeatOff(In:=melter_data[0].b_r_HeatOn AND NOT melter_data[0].b_w_HeatersOnOff, PT:=T#5S);
		IF TON_r_HeatOff.Q THEN
			melter_data[0].b_w_HeatersOnOff:=TRUE;
			TON_r_HeatOff(In:=FALSE, PT:=T#5S);
		END_IF ;
	END_IF;
ELSE
	//点胶机进入待机保温或停止加热的计时（s）时间+1s
	IF AutoClearGlue_R.Q THEN 
		TimeData_NorsonTemperatureSet:=TimeData_NorsonTemperatureSet+1;
	END_IF;
	IF TimeData_NorsonTemperatureSet>=EM10P.StandbyTime*60
		AND TimeData_NorsonTemperatureSet<EM10P.HeatersOffTime*3600
	THEN
		//设备故障时间或待机时间超过点胶机待机保温时间（h）-------点胶机进入待机保温模式
		TON_w_StandbyOn(In:=NOT melter_data[0].b_r_StandByOn AND NOT melter_data[0].b_w_StandbyOnOff, PT:=T#5S);
	    IF  TON_w_StandbyOn.Q THEN
			melter_data[0].b_w_StandbyOnOff:=TRUE;
			TON_w_StandbyOn(In:=FALSE, PT:=T#5S);
		END_IF;
	ELSIF TimeData_NorsonTemperatureSet>=EM10P.HeatersOffTime*3600
	THEN
		//设备故障时间或待机时间超过点胶机停止加热时间（h）-------点胶机停止加热
		TON_r_HeatOff(In:=melter_data[0].b_r_HeatOn AND NOT melter_data[0].b_w_HeatersOnOff, PT:=T#5S);
		IF TON_r_HeatOff.Q THEN
			melter_data[0].b_w_HeatersOnOff:=TRUE;
			TON_r_HeatOff(In:=FALSE, PT:=T#5S);
		END_IF ;
	END_IF;
END_IF;
//待机启动信号复位
TON_w_StandbyOff(In:=melter_data[0].b_w_StandbyOnOff, PT:=T#500MS);
IF TON_w_StandbyOff.Q THEN
    melter_data[0].b_w_StandbyOnOff:=FALSE;
END_IF ;
//加热启动信号复位
TON_w_HeatersOnOff(In:=melter_data[0].b_w_HeatersOnOff, PT:=T#500MS);
IF TON_w_HeatersOnOff.Q THEN 
	melter_data[0].b_w_HeatersOnOff:=FALSE;
END_IF ;

//点胶机温度参数设置
melter_data[0].i_rw_arrTemperatureSp[0]	:=	HMI_RecipeData.NorsonTemperatureSet[0]	;//胶桶温度
melter_data[0].i_rw_arrTemperatureSp[1]	:=	HMI_RecipeData.NorsonTemperatureSet[1]	;//胶泵温度
melter_data[0].i_rw_arrTemperatureSp[2]	:=	HMI_RecipeData.NorsonTemperatureSet[2]	;//胶管1温度
melter_data[0].i_rw_arrTemperatureSp[3]	:=	HMI_RecipeData.NorsonTemperatureSet[3]	;//胶枪1温度
melter_data[0].i_rw_arrTemperatureSp[4]	:=	HMI_RecipeData.NorsonTemperatureSet[4]	;//胶管2温度
melter_data[0].i_rw_arrTemperatureSp[5]	:=	HMI_RecipeData.NorsonTemperatureSet[5]	;//胶枪2温度
melter_data[0].i_rw_arrTemperatureSp[7]	:=	HMI_RecipeData.NorsonTemperatureSet[7]	;//胶枪1吹气温度
melter_data[0].i_rw_arrTemperatureSp[9]	:=	HMI_RecipeData.NorsonTemperatureSet[9]	;//胶枪2吹气温度

//点胶机泵速设置
melter_data[0].r_rw_arrManualMotorSpd_RPM[0]	:=	HMI_RecipeData.NorsonMotorSpeed[0]	;//主泵泵速

//点胶机温度条件
TON_MotorOn(
	In:=NOT HMI_Function_Enable[10,0]
	AND melter_data[0].i_r_arrTemperatureActual[0]>=melter_data[0].i_rw_arrTemperatureSp[0]//胶桶温度
	AND melter_data[0].i_r_arrTemperatureActual[1]>=melter_data[0].i_rw_arrTemperatureSp[1]//胶泵温度
	AND melter_data[0].i_r_arrTemperatureActual[2]>=melter_data[0].i_rw_arrTemperatureSp[2]//胶管1温度
	AND melter_data[0].i_r_arrTemperatureActual[3]>=melter_data[0].i_rw_arrTemperatureSp[3]//胶枪1温度
	AND melter_data[0].i_r_arrTemperatureActual[4]>=melter_data[0].i_rw_arrTemperatureSp[4]//胶管2温度
	AND melter_data[0].i_r_arrTemperatureActual[5]>=melter_data[0].i_rw_arrTemperatureSp[5]//胶枪2温度
	AND melter_data[0].i_r_arrTemperatureActual[7]>=melter_data[0].i_rw_arrTemperatureSp[7]//胶枪1吹气温度
	AND melter_data[0].i_r_arrTemperatureActual[9]>=melter_data[0].i_rw_arrTemperatureSp[9]//胶枪2吹气温度
	,PT:=T#2S);
//主泵使能
melter_data[0].b_rw_MasterPumpEnable:=NOT HMI_Function_Enable[10,0]
																	AND melter_data[0].b_r_ReadyForOperation
																	AND melter_data[0].b_r_HeatOn
																	AND NOT melter_data[0].b_r_StandByOn;

//点胶模式
melter_data[0].i_rw_arrPumpMode[0]:=0;

IF HMI_RecipeData.EM10.Axis_Virtual1.Location_Speed[1] = 0 THEN
HMI_RecipeData.EM10.Axis_Virtual1.Location_Speed[1] := 100;
END_IF
//点胶速度计算(速度=螺旋线长度/时间)（螺旋线长度=螺距/3.14*圈数*360）（时间=圈数*360/虚轴的速度）
//EM10P.SprayGlueSpeed:=((HMI_RecipeData.PC_Sprial_b/3.14)*HMI_RecipeData.PC_Sprial_n*360)/(HMI_RecipeData.PC_Sprial_n*360/HMI_RecipeData.EM10.Axis_Virtual1.Location_Speed[1]);



//如果触发加热信号持续闪烁,点胶机未返回加热中信号时,查看功能块222行的变量w_ReturnIndexChannel和w_PrevIndexChannel,
//看这两个变量值是否跳动,如果无,则检查通讯,如果正常,则先将点胶外设功能变量关闭,然后将功能块227行变量b_ReadSuccess手动复位,然后会该变量会自动置位,
//变量置位后,将点胶外设功能变量开启,等待回复正常.
//如果不行则将248行变量b_CommunicateOK复位
//仍未解决请联系点胶机供应商梁工
//点胶机未加热 未触发加热 延时一段时间后


///////////////////功能块///////////////////////
	first_LPM(enableIn:=NOT HMI_Function_Enable[10,0] 
			, MachineNum:=0 
			, IO_inputByte:=arr_inputByte01  
			, IO_outputByte=> arr_outputByte01
			, Melter:=melter_data );

(*****************************EM10_点胶模组状态机*****************************) 

EMNumber := 10;//模组编号
StationNum :=1-1 ;//工位数量--数组编号最大为0..9

Act.Act01_Status[10]:=TRUE;//工位状态机程序
Act.Act02_Condition[10]:=TRUE;//循环扫描程序
//手动动运行程序
Act.Act03_Manual[10]:=  MyStatus.StatusManual;	
//初始化程序
MyStation.EM[10].Resting:=Act.Act04_Init[10];
//自动运行程序			
MyStation.EM[10].Running:=Act.Act05_Auto[10];										
//功能块调用程序						 
Act.Act06_IOCall_FB[10]:=TRUE;
//轴功能块调用程序						 
Act.Act07_AxisCall_FB[10]:=TRUE;
//通讯程序						 
Act.Act08_Communication[10]:=TRUE;
//报警信息程序						 
Act.Act09_AlmAndMesg[10]:=NOT MyStation.EM[10].Shielding
					AND MyStation.EmgStop
					AND MyStation.SafetyDoor
					AND MyStation.SafetyRaster;


FOR StationSum := 0 TO StationNum BY 1 DO
//功能状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowAuto		:=	Act.Act05_Auto_Station[EMNumber,StationSum] OR Act.Act04_Init_Station[EMNumber,StationSum]					;//自动状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowManual	:=	Act.Act03_Manual[EMNumber]																		;//手动状态
Act.Act10_Call_Status[EMNumber,StationSum].AlarmReset	:=	MyInput.Reset_Input																		;//复位状态
Act.Act10_Call_Status[EMNumber,StationSum].Aborting		:= NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor				;//急停中止
Act.Act10_Call_Status[EMNumber,StationSum].StopCmd		:=	MyStation.EM[EMNumber].Stopping	AND NOT MyStation.EM[EMNumber].Resting		;//停止
Act.Act10_Call_Status[EMNumber,StationSum].DoorAborting:=	NOT MyStation.EmgStop	OR NOT MyStation.SafetyDoor				;//门禁中止																		
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[1]	:= MyStation.ProductionMode															;//生产模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[2]	:= MyStation.MaintenanceMode														;//维护模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[3]	:= Act.Act04_Init_Station[EMNumber,StationSum];//初始化模式												
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[4] 	:= Act.Act03_Manual[EMNumber];//手动模式									
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[5] 	:= MyStation.MaintenanceMode;//维修模式			
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[0]	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[1]	:= NOT	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //未复
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[2]	:=	MyStation.EMStation[EMNumber,StationSum].Resting;  //复位中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[3]	:=	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //复位完成
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[4]	:=	Device_Starting;  //自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[5]	:=	Device_Starting;  //单步自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[6]	:=	MyStation.EM[EMNumber].Stopping;  //暂停中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[7]	:=	NOT MyStation.SafetyDoor AND FALSE;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[8]	:=	NOT MyStation.EmgStop;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].AlarmShield	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
END_FOR;


Act.Act10_Call_Status[EMNumber,0].AllowAuto:=Act.Act10_Call_Status[EMNumber,1].AllowAuto OR	Act.Act10_Call_Status[EMNumber,1].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,2].AllowAuto OR	Act.Act10_Call_Status[EMNumber,3].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,4].AllowAuto OR	Act.Act10_Call_Status[EMNumber,5].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,6].AllowAuto OR	Act.Act10_Call_Status[EMNumber,7].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,8].AllowAuto OR	Act.Act10_Call_Status[EMNumber,9].AllowAuto
																				OR	(Act.Act05_Auto_Station[EMNumber,0] OR Act.Act04_Init_Station[EMNumber,0]);

//--------------输入-----------------------------------//
usiEM01Index:=USINT#13;//工位号
bEM01_Start:=EM10V.Process_steps[0]=120;//计时开始									
bEM01_Stop:=EM10V.Process_steps[0]=0;//计时结束
bEM01_Run:=Act.Act05_Auto_Station[10,0];//工位自动									
														
abEM01ActionStart[1] :=EM10V.Process_steps[0]=100; //1.Z轴到安全位			
abEM01ActionDone[1]	 :=EM10V.Process_steps[0]=110; 
ausiEM01ActionParallelNum[1]:=0;
abEM01ActionStart[2] :=EM10V.Process_steps[0]=110; //2.XY轴到点胶起点			
abEM01ActionDone[2]	 :=EM10V.Process_steps[0]=120; 
ausiEM01ActionParallelNum[2]:=0;
abEM01ActionStart[3] :=EM10V.Process_steps[0]=120; //3.Z轴到点胶点		
abEM01ActionDone[3]	 :=EM10V.Process_steps[0]=140; 
ausiEM01ActionParallelNum[3]:=0;
abEM01ActionStart[4] :=EM10V.Process_steps[0]=140; //4.螺旋点胶		
abEM01ActionDone[4]	 :=EM10V.Process_steps[0]=150; 
ausiEM01ActionParallelNum[4]:=0;
abEM01ActionStart[5] :=EM10V.Process_steps[0]=150; //5.Z轴到点胶等待位吹气
abEM01ActionDone[5]	 :=EM10V.Process_steps[0]=0; 
ausiEM01ActionParallelNum[5]:=0;
//最多62个动作	

//--------------计时-----------------------------------//	
//计时结束 把工位总时间存储进63步									
rtgEM01_Stop(CLK:=bEM01_Stop);									
IF rtgEM01_Stop.Q AND bEM01TimerStart THEN 									
	bEM01TimerStart:=FALSE;	
	FOR uiIndex:=1 TO 62 BY 1 DO															
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);														
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;
	HC_OmronUtils.TimeToNanoSec(In:=tEM01,Out=>liEM01ActionTimeTemp2);
	liEM01ActionTimeTemp2:=liEM01ActionTimeTemp2/1000000;								
	IF liEM01ActionTimeTemp2>LINT#65535 THEN //UINT 范围0-65535，越界处理								
		auiEMTime[usiEM01Index,63]:=65535;							
	ELSE								
		auiEMTime[usiEM01Index,63]:=TO_UINT(liEM01ActionTimeTemp2);							
	END_IF;		
	ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储 
	ausiActionParallelNum[uiFIFOlen]:=USINT#0;//动作并行号 
	auiActionNum[uiFIFOlen]:=UINT#63;//动作号	
	auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,63];//动作时间								
	uiFIFOlen:=uiFIFOlen+1;								
	IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)								
		uiFIFOlen:=166;							
	END_IF;								
END_IF;	

//开始计时									
rtgEM01_Start(CLK:=bEM01_Start);									
IF rtgEM01_Start.Q THEN 									
	bEM01TimerStart:=TRUE;								
	Clear(atEM01ActionStart);								
	Clear(atEM01ActionDone);								
	Clear(abEM01ActionRun);																
END_IF;									
									
//计时									
bEM01TimerEnable:=bEM01TimerStart AND bEM01_Run;									
atEM01(In:=bEM01TimerEnable,PT:=T#1D,Reset:=rtgEM01_Start.Q,ET=>tEM01);									
									
//动作时间计算&数据进缓存									
IF bEM01TimerStart THEN 									
	FOR uiIndex:=1 TO 62 BY 1 DO								
		artgEM01ActionStart[uiIndex](CLK:=abEM01ActionStart[uiIndex]);							
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);							
	    IF artgEM01ActionStart[uiIndex].Q THEN  //开始时刻								
			atEM01ActionStart[uiIndex]:=tEM01;						
			abEM01ActionRun[uiIndex]:=TRUE;//防止动作完成信号反复触发，导致数据量激增						
		END_IF;							
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;								
END_IF;									
									
								
									
//--------------输出-----------------------------------//									
auiEMTime[usiEM01Index,1]	:=auiEMTime[usiEM01Index,1]	; //第1个动作时间							
auiEMTime[usiEM01Index,2]	:=auiEMTime[usiEM01Index,2]	; //第2个动作时间							
auiEMTime[usiEM01Index,3]	:=auiEMTime[usiEM01Index,3]	; //第3个动作时间							
auiEMTime[usiEM01Index,4]	:=auiEMTime[usiEM01Index,4]	; //第4个动作时间							
auiEMTime[usiEM01Index,5]	:=auiEMTime[usiEM01Index,5]	; //第5个动作时间							
auiEMTime[usiEM01Index,6]	:=auiEMTime[usiEM01Index,6]	; //第6个动作时间							
auiEMTime[usiEM01Index,7]	:=auiEMTime[usiEM01Index,7]	; //第7个动作时间							
auiEMTime[usiEM01Index,8]	:=auiEMTime[usiEM01Index,8]	; //第8个动作时间							
auiEMTime[usiEM01Index,9]	:=auiEMTime[usiEM01Index,9]	; //第9个动作时间							
auiEMTime[usiEM01Index,10]	:=auiEMTime[usiEM01Index,10]	; //第10个动作时间
auiEMTime[usiEM01Index,11]	:=auiEMTime[usiEM01Index,11]	; //第11个动作时间							
auiEMTime[usiEM01Index,12]	:=auiEMTime[usiEM01Index,12]	; //第12个动作时间							
auiEMTime[usiEM01Index,63]	:=auiEMTime[usiEM01Index,63]	; //第63个动作时间

FOR StationSum := 0 TO StationNum BY 1 DO
	StationInit_R[StationSum](Clk:=MyStation.EMStation[EMNumber,StationSum].Init OR Act.Act04_Init[EMNumber]);
	IF  StationInit_R[StationSum].Q 
	THEN 
		MyStation.EMStation[EMNumber,StationSum].ResetComplete :=FALSE;
	END_IF;
    IF 	(MyStation.EMStation[EMNumber,StationSum].Init 
		OR Act.Act04_Init[EMNumber])
		AND Inital_Runing
		AND MyInput.AutoSwitch_Input
		AND NOT MyStation.EM[EMNumber].Shielding
		AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
		AND NOT MyStation.EM[EMNumber].IsAlarm
		AND NOT MyStation.EM[0].Running
		AND NOT OperationOut.Abort
		AND NOT OperationOut.Stop
		AND NOT OperationOut.Hold
		AND NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete
	THEN 
		Act.Act04_Init_Station[EMNumber,StationSum] := TRUE;
	ELSE
		Act.Act04_Init_Station[EMNumber,StationSum] := FALSE;
	END_IF;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	IF  MyStation.EMStation[EMNumber,StationSum].ResetComplete OR  MyStation.EMStation[EMNumber,StationSum].Shielding THEN 
		MyStation.EM[EMNumber].ResetComplete :=TRUE;
	ELSIF NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
	THEN 
		MyStation.EM[EMNumber].ResetComplete := FALSE;
		EXIT;
	END_IF;
END_FOR;

