Allow[3] ;//程序保护 (*定位允许[9]*) EM10V.Axis_Y1.In.Location_SafeCondition[9]:=TRUE AND EM10V.MovingAllow[3] ;//程序保护 (*定位允许[10]*) EM10V.Axis_Y1.In.Location_SafeCondition[10]:=TRUE AND EM10V.MovingAllow[3] ;//程序保护 (******************** Axis_Virtual1点胶虚轴动作条件********************) (*轴安全总条件*) EM10V.MovingAllow[4] := TRUE;//程序保护 (*JOG-允许*) EM10V.Axis_Virtual1.In.JOG_SafeCondition[0] := TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*JOG+允许*) EM10V.Axis_Virtual1.In.JOG_SafeCondition[1] := TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*寻参允许*) EM10V.Axis_Virtual1.In.Home_SafeCondition:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许*) EM10V.Axis_Virtual1.In.Location_SafeCondition:=ARRAY32_TRUE;//程序保护 (*定位允许[0]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[0]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[1]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[1]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[2]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[2]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[3]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[3]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[4]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[4]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[5]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[5]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[6]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[6]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[7]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[7]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[8]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[8]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[9]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[9]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护 (*定位允许[10]*) EM10V.Axis_Virtual1.In.Location_SafeCondition[10]:=TRUE AND EM10V.MovingAllow[4] ;//程序保护

