IF EM10P.GlueClearSum<=0 THEN
	EM10P.GlueClearSum:=20;
END_IF;

//1#点胶吹气时间（ms）
IF HMI_RecipeData.BlowTime1<=0 THEN
	HMI_RecipeData.BlowTime1:=200;
END_IF;
//2#点胶吹气时间（ms）
IF HMI_RecipeData.BlowTime2<=0 THEN
	HMI_RecipeData.BlowTime2:=200;
END_IF;
//直喷点胶吹气计时1
TON_Blow1(
	In:=EM10V.Process_steps[0]=150 OR EM10V.Process_steps[1]=135
	, PT:=REAL_TO_TIME( HMI_RecipeData.BlowTime1));
	
//直喷点胶吹气计时2
TON_Blow2(
	In:=EM10V.Process_steps[0]=150 OR EM10V.Process_steps[1]=135
	, PT:=REAL_TO_TIME(HMI_RecipeData.BlowTime2));

//毛刷旋转时间（ms）
IF EM10P.RotationTime<=0 THEN
	EM10P.RotationTime:=500;
END_IF;
//毛刷旋转计时
TON_RotationTime(
	In:=EM10V.Process_steps[0]=180
	, PT:=REAL_TO_TIME(EM10P.RotationTime));

//自动排胶时间（s）
IF EM10P.AutoClearGlueTime<=0 THEN
	EM10P.AutoClearGlueTime:=10;
END_IF;
//自动排胶计时
TON_AutoClearGlue(
	In:=EM10V.Process_steps[0]=330
	, PT:=REAL_TO_TIME(EM10P.AutoClearGlueTime*1000));

//手动排胶时间（s）
IF EM10P.MaunalClearGlueTime<=0 THEN
	EM10P.MaunalClearGlueTime:=10;
END_IF;
//手动排胶计时
TON_ManualClearGlue(
	In:=HMI_Button[10,1]
	AND HMI_Button[10,2]
	AND HMI_Button[10,3]
	, PT:=REAL_TO_TIME(EM10P.MaunalClearGlueTime*1000));

(********************************************	电芯进站流程		*********************************************)
IF Act.Act05_Auto_Station[5,0]
	AND EM05V.ST_CellLocation1.StationAllow
	AND Cell_Info[5,EM05V.ST_CellLocation1.MoverID].Quality=76
	AND Catl_MesData.PlcToPc_Int[4]=0
THEN
	EM05V.ST_CellLocation1.MoverIDTemp:=EM05V.ST_CellLocation1.MoverID;
	//清除上一次接收的数据
	Catl_MesBar.PcToPlc_String[2]:='';
	Catl_MesBar.PcToPlc_String[3]:='';
	//传送电芯条码
	Catl_MesBar.PlcToPc_String[4]:=Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].BettarySN;
	Catl_MesData.PlcToPc_Int[4]:=1;
END_IF;


IF Catl_MesData.PlcToPc_Int[4]=100//MES OK
	OR (Catl_MesData.PlcToPc_Int[4]=1 AND HMI_Function_Enable[0,0])
	OR (Catl_MesData.PlcToPc_Int[4]=1 AND HMI_TestMode_Enable)
THEN
	//=========================================
	//MES条码长度检测
	IF LEN(STR:=Catl_MesBar.PcToPlc_String[2])=0//MES条码
		AND NOT HMI_Function_Enable[0,0]
		AND NOT HMI_TestMode_Enable
	THEN
		IF Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality=76 THEN
			Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality:=7;
		END_IF;
		H_Messages.Station[5].User_Alarm[29]:=TRUE;//EM05环轨模组：上位机反馈电芯进站结果OK，但回传的MES条码是空字符，请检查上位机软件是否出错！
	END_IF;
	
	//=========================================
	//传递记忆
	IF Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality=76 THEN
		Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality:=80;
	END_IF;
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].MesBettarySN:=Catl_MesBar.PcToPlc_String[2];
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].LoadTime_Bettary:=Catl_MesBar.PcToPlc_String[3];
	EntranceNGNum1:=0;
	
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[4]:=0;

ELSIF Catl_MesData.PlcToPc_Int[4]=35//MES NG
	OR Catl_MesData.PlcToPc_Int[4]=55//重码NG
THEN
	//=========================================
	//传递记忆
	IF Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality=76 THEN
		Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality:=7;
	END_IF;
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].MesBettarySN:=Catl_MesBar.PcToPlc_String[2];
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].LoadTime_Bettary:=Catl_MesBar.PcToPlc_String[3];
	EntranceNGNum1:=EntranceNGNum1+1;
	
	//=========================================
	//55 重码NG
	IF Catl_MesData.PlcToPc_Int[4]=55
	THEN
		H_Messages.Station[5].User_Alarm[30]:=TRUE;//EM05环轨模组：上位机反馈电芯进站结果是重码NG，请检查电芯码是否正常；
	END_IF;
	
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[4]:=0;
	
ELSIF Catl_MesData.PlcToPc_Int[4]=45//电芯放反NG
THEN
	//=========================================
	//传递记忆
	IF Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality=76 THEN
		Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality:=6;
	END_IF;
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].MesBettarySN:=Catl_MesBar.PcToPlc_String[2];
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].LoadTime_Bettary:=Catl_MesBar.PcToPlc_String[3];
	EntranceNGNum1:=EntranceNGNum1+1;
	
	//=========================================
	//45 电芯放反NG
	IF Catl_MesData.PlcToPc_Int[4]=45
	THEN
		H_Messages.Station[5].User_Alarm[31]:=TRUE;//EM05环轨模组：上位机反馈电芯进站结果是电芯放反，请检查电芯来料方向是否错误；
	END_IF;
	
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[4]:=0;


ELSIF Catl_MesData.PlcToPc_Int[4]=50  //MES 首件
THEN
	//=========================================
	//传递记忆
	IF Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality=76 THEN
		Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality:=80;
	END_IF;	
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].MesBettarySN:=Catl_MesBar.PcToPlc_String[2];
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].LoadTime_Bettary:=Catl_MesBar.PcToPlc_String[3];
	Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].SampleProductFlag := TRUE ; // 首件标志
	EntranceNGNum1:=0;	
	//=========================================
	//清除信号
	Catl_MesData.PlcToPc_Int[4]:=0;

END_IF;

//轮廓仪扫描开始延时
IF EM05P.CheckStartTime=0 THEN
	EM05P.CheckStartTime:=2000;
END_IF;
TP_Moving_OUT:=MULTIME(In1:=T#1MS, In2:=EM05P.CheckStartTime,OUT=>TP_Moving_Time);
TP_Moving(In:=CheckStep=10, PT:=TP_Moving_Time);
F_Moving(Clk:=TP_Moving.Q);
TP_CheckStart(In:=F_Moving.Q, PT:=T#500MS);
F_Button(Clk:=HMI_Button[5,1]);
//轮廓仪扫描开始
EM05V.CheckStart:=TP_CheckStart.Q;

IF MyStatus.StatusManual THEN
CASE CheckStep OF
	0://等待条件
		IF MyStatus.StatusManual
			AND EM05V.Golytec.Out.Inited
			AND EM05V.Golytec.Out.Station_auto
			AND EM05V.Golytec.In.StationMotionAllow[0]
			AND EM05V.Golytec.In.StationMotionAllow[1]
			AND EM05V.Golytec.In.StationMotionAllow[2]
			AND EM05V.Golytec.In.StationMotionAllow[3]
			AND EM05V.Golytec.In.StationMotionAllow[4]
			AND EM05V.Golytec.In.StationMotionAllow[5]
			AND EM05V.Golytec.In.StationMotionAllow[6]
			AND EM05V.Golytec.In.StationMotionAllow[7]
			AND EM05V.Golytec.In.StationMotionAllow[8]
			AND EM05V.Golytec.In.StationMotionAllow[9]
			AND HMI_Button[5,0]
			AND F_Button.Q
		THEN
			CheckStep:=10;
		END_IF;
	
	10://磁驱移动开始
		EM05H_Golytec.H_In.StationMotion[0]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[1]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[2]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[3]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[4]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[5]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[6]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[7]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[8]:=TRUE;
		EM05H_Golytec.H_In.StationMotion[9]:=TRUE;
		CheckStep:=20;
	
	20://等待
		IF NOT EM05H_Golytec.H_In.StationMotion[0]
			AND NOT EM05H_Golytec.H_In.StationMotion[1]
			AND NOT EM05H_Golytec.H_In.StationMotion[2]
			AND NOT EM05H_Golytec.H_In.StationMotion[3]
			AND NOT EM05H_Golytec.H_In.StationMotion[4]
			AND NOT EM05H_Golytec.H_In.StationMotion[5]
			AND NOT EM05H_Golytec.H_In.StationMotion[6]
			AND NOT EM05H_Golytec.H_In.StationMotion[7]
			AND NOT EM05H_Golytec.H_In.StationMotion[8]
			AND NOT EM05H_Golytec.H_In.StationMotion[9]
		THEN
			CheckStep:=0;
		END_IF;

END_CASE;

ELSE
	HMI_Button[5,0]:=FALSE;
	HMI_Button[5,1]:=FALSE;
	CheckStep:=0;
END_IF;

(*****************************EM05_环轨模组状态机*****************************) 

EMNumber := 5;//模组编号
StationNum :=2-1 ;//工位数量--数组编号最大为0..9
//0--------环轨工位
//1--------整形工位
Act.Act01_Status[5]:=TRUE;//工位状态机程序
Act.Act02_Condition[5]:=TRUE;//循环扫描程序
//手动动运行程序
Act.Act03_Manual[5]:=  MyStatus.StatusManual;	
//初始化程序
MyStation.EM[5].Resting:=Act.Act04_Init[5];
//自动运行程序			
MyStation.EM[5].Running:=Act.Act05_Auto[5];										
//功能块调用程序						 
Act.Act06_IOCall_FB[5]:=TRUE;
//轴功能块调用程序						 
Act.Act07_AxisCall_FB[5]:=TRUE;
//通讯程序						 
Act.Act08_Communication[5]:=TRUE;
//报警信息程序						 
Act.Act09_AlmAndMesg[5]:=NOT MyStation.EM[5].Shielding
					AND MyStation.EmgStop
					AND MyStation.SafetyDoor
					AND MyStation.SafetyRaster;


FOR StationSum := 0 TO StationNum BY 1 DO
//功能状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowAuto		:=	Act.Act05_Auto_Station[EMNumber,StationSum] OR Act.Act04_Init_Station[EMNumber,StationSum]					;//自动状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowManual	:=	Act.Act03_Manual[EMNumber]																		;//手动状态
Act.Act10_Call_Status[EMNumber,StationSum].AlarmReset	:=	MyInput.Reset_Input																		;//复位状态
Act.Act10_Call_Status[EMNumber,StationSum].Aborting		:= NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor				;//急停中止
Act.Act10_Call_Status[EMNumber,StationSum].StopCmd		:=	MyStation.EM[EMNumber].Stopping	AND NOT MyStation.EM[EMNumber].Resting		;//停止
Act.Act10_Call_Status[EMNumber,StationSum].DoorAborting:=	NOT MyStation.EmgStop	OR NOT MyStation.SafetyDoor				;//门禁中止																		
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[1]	:= MyStation.ProductionMode															;//生产模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[2]	:= MyStation.MaintenanceMode														;//维护模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[3]	:= Act.Act04_Init_Station[EMNumber,StationSum];//初始化模式												
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[4] 	:= Act.Act03_Manual[EMNumber];//手动模式									
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[5] 	:= MyStation.MaintenanceMode;//维修模式			
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[0]	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[1]	:= NOT	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //未复
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[2]	:=	MyStation.EMStation[EMNumber,StationSum].Resting;  //复位中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[3]	:=	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //复位完成
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[4]	:=	Device_Starting;  //自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[5]	:=	Device_Starting;  //单步自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[6]	:=	MyStation.EM[EMNumber].Stopping;  //暂停中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[7]	:=	NOT MyStation.SafetyDoor AND FALSE;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[8]	:=	NOT MyStation.EmgStop;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].AlarmShield	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
END_FOR;

Act.Act10_Call_Status[EMNumber,0].AllowAuto:=Act.Act10_Call_Status[EMNumber,1].AllowAuto OR	Act.Act10_Call_Status[EMNumber,1].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,2].AllowAuto OR	Act.Act10_Call_Status[EMNumber,3].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,4].AllowAuto OR	Act.Act10_Call_Status[EMNumber,5].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,6].AllowAuto OR	Act.Act10_Call_Status[EMNumber,7].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,8].AllowAuto OR	Act.Act10_Call_Status[EMNumber,9].AllowAuto
																				OR	(Act.Act05_Auto_Station[EMNumber,0] OR Act.Act04_Init_Station[EMNumber,0]);

//--------------输入-----------------------------------//
usiEM01Index:=USINT#7;//工位号
bEM01_Start:=EM05V.Process_steps[1]=100;//计时开始									
bEM01_Stop:=EM05V.Process_steps[1]=0;//计时结束
bEM01_Run:=Act.Act05_Auto_Station[5,0];//工位自动									
														
abEM01ActionStart[1] :=EM05V.Process_steps[1]=100; //1.治具解锁气缸打开					
abEM01ActionDone[1]	 :=EM05V.Process_steps[1]=110; 
ausiEM01ActionParallelNum[1]:=0;
abEM01ActionStart[2] :=EM05V.Process_steps[1]=110; //2.电芯夹爪上料				
abEM01ActionDone[2]	 :=EM05V.Process_steps[1]=120; 
ausiEM01ActionParallelNum[2]:=0;
abEM01ActionStart[3] :=EM05V.Process_steps[1]=120; //3.治具解锁气缸伸出		
abEM01ActionDone[3]	 :=EM05V.Process_steps[1]=0; 
ausiEM01ActionParallelNum[3]:=0;
//最多62个动作	

//--------------计时-----------------------------------//	
//计时结束 把工位总时间存储进63步									
rtgEM01_Stop(CLK:=bEM01_Stop);									
IF rtgEM01_Stop.Q AND bEM01TimerStart THEN 									
	bEM01TimerStart:=FALSE;	
	FOR uiIndex:=1 TO 62 BY 1 DO															
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);														
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;
	HC_OmronUtils.TimeToNanoSec(In:=tEM01,Out=>liEM01ActionTimeTemp2);
	liEM01ActionTimeTemp2:=liEM01ActionTimeTemp2/1000000;								
	IF liEM01ActionTimeTemp2>LINT#65535 THEN //UINT 范围0-65535，越界处理								
		auiEMTime[usiEM01Index,63]:=65535;							
	ELSE								
		auiEMTime[usiEM01Index,63]:=TO_UINT(liEM01ActionTimeTemp2);							
	END_IF;		
	ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储 
	ausiActionParallelNum[uiFIFOlen]:=USINT#0;//动作并行号 
	auiActionNum[uiFIFOlen]:=UINT#63;//动作号	
	auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,63];//动作时间								
	uiFIFOlen:=uiFIFOlen+1;								
	IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)								
		uiFIFOlen:=166;							
	END_IF;								
END_IF;	

//开始计时									
rtgEM01_Start(CLK:=bEM01_Start);									
IF rtgEM01_Start.Q THEN 									
	bEM01TimerStart:=TRUE;								
	Clear(atEM01ActionStart);								
	Clear(atEM01ActionDone);								
	Clear(abEM01ActionRun);																
END_IF;									
									
//计时									
bEM01TimerEnable:=bEM01TimerStart AND bEM01_Run;									
atEM01(In:=bEM01TimerEnable,PT:=T#1D,Reset:=rtgEM01_Start.Q,ET=>tEM01);									
									
//动作时间计算&数据进缓存									
IF bEM01TimerStart THEN 									
	FOR uiIndex:=1 TO 62 BY 1 DO								
		artgEM01ActionStart[uiIndex](CLK:=abEM01ActionStart[uiIndex]);							
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);							
	    IF artgEM01ActionStart[uiIndex].Q THEN  //开始时刻								
			atEM01ActionStart[uiIndex]:=tEM01;						
			abEM01ActionRun[uiIndex]:=TRUE;//防止动作完成信号反复触发，导致数据量激增						
		END_IF;							
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;								
END_IF;									
									
								
									
//--------------输出-----------------------------------//									
auiEMTime[usiEM01Index,1]	:=auiEMTime[usiEM01Index,1]	; //第1个动作时间							
auiEMTime[usiEM01Index,2]	:=auiEMTime[usiEM01Index,2]	; //第2个动作时间							
auiEMTime[usiEM01Index,3]	:=auiEMTime[usiEM01Index,3]	; //第3个动作时间							
auiEMTime[usiEM01Index,4]	:=auiEMTime[usiEM01Index,4]	; //第4个动作时间							
auiEMTime[usiEM01Index,5]	:=auiEMTime[usiEM01Index,5]	; //第5个动作时间							
auiEMTime[usiEM01Index,6]	:=auiEMTime[usiEM01Index,6]	; //第6个动作时间							
auiEMTime[usiEM01Index,7]	:=auiEMTime[usiEM01Index,7]	; //第7个动作时间							
auiEMTime[usiEM01Index,8]	:=auiEMTime[usiEM01Index,8]	; //第8个动作时间							
auiEMTime[usiEM01Index,9]	:=auiEMTime[usiEM01Index,9]	; //第9个动作时间							
auiEMTime[usiEM01Index,10]	:=auiEMTime[usiEM01Index,10]	; //第10个动作时间
auiEMTime[usiEM01Index,11]	:=auiEMTime[usiEM01Index,11]	; //第11个动作时间							
auiEMTime[usiEM01Index,12]	:=auiEMTime[usiEM01Index,12]	; //第12个动作时间							
auiEMTime[usiEM01Index,63]	:=auiEMTime[usiEM01Index,63]	; //第63个动作时间

//--------------输入-----------------------------------//
usiEM02Index:=USINT#8;//工位号
bEM02_Start:=EM05V.Process_steps[2]=0;//计时开始									
bEM02_Stop:=EM05V.Process_steps[2]=0;//计时结束
bEM02_Run:=Act.Act05_Auto_Station[5,1];//工位自动	

abEM02ActionStart[1] :=EM05V.Process_steps[2]=100; //1.整形Z轴到整形位							
abEM02ActionDone[1]	 :=EM05V.Process_steps[2]=110; 
ausiEM02ActionParallelNum[1]:=0;
abEM02ActionStart[2] :=EM05V.Process_steps[2]=110; //2.治具解锁气缸打开			
abEM02ActionDone[2]	 :=EM05V.Process_steps[2]=120; 	
ausiEM02ActionParallelNum[2]:=0;
abEM02ActionStart[3] :=EM05V.Process_steps[2]=120; //3.整形Y轴张开						
abEM02ActionDone[3]	 :=EM05V.Process_steps[2]=130; 
ausiEM02ActionParallelNum[3]:=0;
abEM02ActionStart[4] :=EM05V.Process_steps[2]=130; //4.治具解锁气缸伸出			
abEM02ActionDone[4]	 :=EM05V.Process_steps[2]=140; 	
ausiEM02ActionParallelNum[4]:=0;
abEM02ActionStart[5] :=EM05V.Process_steps[2]=140; //5.整形Y轴合拢							
abEM02ActionDone[5]	 :=EM05V.Process_steps[2]=150; 
ausiEM02ActionParallelNum[5]:=0;
abEM02ActionStart[6] :=EM05V.Process_steps[2]=150; //6.整形Z轴到安全位							
abEM02ActionDone[6]	 :=EM05V.Process_steps[2]=0; 
ausiEM02ActionParallelNum[6]:=0;
abEM02ActionStart[7] :=StationMovingFlag; //7.链板到位	
abEM02ActionDone[7]	 :=NOT StationMovingFlag; 	
ausiEM02ActionParallelNum[7]:=0;

//最多62个动作	

//--------------计时-----------------------------------//	
//计时结束 把工位总时间存储进63步									
rtgEM02_Stop(CLK:=bEM02_Stop);									
IF rtgEM02_Stop.Q AND bEM02TimerStart THEN 									
	bEM02TimerStart:=FALSE;	
	FOR uiIndex:=1 TO 62 BY 1 DO															
		artgEM02ActionDone[uiIndex](CLK:=abEM02ActionDone[uiIndex]);														
		IF artgEM02ActionDone[uiIndex].Q AND abEM02ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM02ActionRun[uiIndex]:=FALSE;						
			atEM02ActionDone[uiIndex]:=tEM02;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM02ActionDone[uiIndex],Out=>liEM02ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM02ActionStart[uiIndex],Out=>liEM02ActionStart);
			liEM02ActionTimeTemp1:=(liEM02ActionDone-liEM02ActionStart)/1000000;//单位ms						
			IF liEM02ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM02Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM02Index,uiIndex]:=TO_UINT(liEM02ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM02Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM02ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM02Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;
	HC_OmronUtils.TimeToNanoSec(In:=tEM02,Out=>liEM02ActionTimeTemp2);
	liEM02ActionTimeTemp2:=liEM02ActionTimeTemp2/1000000;								
	IF liEM02ActionTimeTemp2>LINT#65535 THEN //UINT 范围0-65535，越界处理								
		auiEMTime[usiEM02Index,63]:=65535;							
	ELSE								
		auiEMTime[usiEM02Index,63]:=TO_UINT(liEM02ActionTimeTemp2);							
	END_IF;		
	ausiEMNum[uiFIFOlen]:=usiEM02Index;//工位号存储 
	ausiActionParallelNum[uiFIFOlen]:=USINT#0;//动作并行号 
	auiActionNum[uiFIFOlen]:=UINT#63;//动作号	
	auiActionTime[uiFIFOlen]:=auiEMTime[usiEM02Index,63];//动作时间								
	uiFIFOlen:=uiFIFOlen+1;								
	IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)								
		uiFIFOlen:=166;							
	END_IF;								
END_IF;	

//开始计时									
rtgEM02_Start(CLK:=bEM02_Start);									
IF rtgEM02_Start.Q THEN 									
	bEM02TimerStart:=TRUE;								
	Clear(atEM02ActionStart);								
	Clear(atEM02ActionDone);								
	Clear(abEM02ActionRun);																
END_IF;									
									
//计时									
bEM02TimerEnable:=bEM02TimerStart AND bEM02_Run;									
atEM02(In:=bEM02TimerEnable,PT:=T#1D,Reset:=rtgEM02_Start.Q,ET=>tEM02);									
									
//动作时间计算&数据进缓存									
IF bEM02TimerStart THEN 									
	FOR uiIndex:=1 TO 62 BY 1 DO								
		artgEM02ActionStart[uiIndex](CLK:=abEM02ActionStart[uiIndex]);							
		artgEM02ActionDone[uiIndex](CLK:=abEM02ActionDone[uiIndex]);							
	    IF artgEM02ActionStart[uiIndex].Q THEN  //开始时刻								
			atEM02ActionStart[uiIndex]:=tEM02;						
			abEM02ActionRun[uiIndex]:=TRUE;//防止动作完成信号反复触发，导致数据量激增						
		END_IF;							
		IF artgEM02ActionDone[uiIndex].Q AND abEM02ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM02ActionRun[uiIndex]:=FALSE;						
			atEM02ActionDone[uiIndex]:=tEM02;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM02ActionDone[uiIndex],Out=>liEM02ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM02ActionStart[uiIndex],Out=>liEM02ActionStart);
			liEM02ActionTimeTemp1:=(liEM02ActionDone-liEM02ActionStart)/1000000;//单位ms						
			IF liEM02ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM02Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM02Index,uiIndex]:=TO_UINT(liEM02ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM02Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM02ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM02Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;								
END_IF;									
									
								
									
//--------------输出-----------------------------------//									
auiEMTime[usiEM02Index,1]	:=auiEMTime[usiEM02Index,1]	; //第1个动作时间							
auiEMTime[usiEM02Index,2]	:=auiEMTime[usiEM02Index,2]	; //第2个动作时间							
auiEMTime[usiEM02Index,3]	:=auiEMTime[usiEM02Index,3]	; //第3个动作时间							
auiEMTime[usiEM02Index,4]	:=auiEMTime[usiEM02Index,4]	; //第4个动作时间							
auiEMTime[usiEM02Index,5]	:=auiEMTime[usiEM02Index,5]	; //第5个动作时间							
auiEMTime[usiEM02Index,6]	:=auiEMTime[usiEM02Index,6]	; //第6个动作时间							
auiEMTime[usiEM02Index,7]	:=auiEMTime[usiEM02Index,7]	; //第7个动作时间							
//auiEMTime[usiEM02Index,8]	:=auiEMTime[usiEM02Index,8]	; //第8个动作时间							
//auiEMTime[usiEM02Index,9]	:=auiEMTime[usiEM02Index,9]	; //第9个动作时间							
//auiEMTime[usiEM02Index,10]	:=auiEMTime[usiEM02Index,10]	; //第10个动作时间			
//auiEMTime[usiEM02Index,11]	:=auiEMTime[usiEM02Index,11]	; //第11个动作时间		
//auiEMTime[usiEM02Index,12]	:=auiEMTime[usiEM02Index,12]	; //第12个动作时间
//auiEMTime[usiEM02Index,13]	:=auiEMTime[usiEM02Index,13]	; //第13个动作时间
auiEMTime[usiEM02Index,63]	:=auiEMTime[usiEM02Index,63]	; //第63个动作时间

(******************************************** 动子ID映射 *********************************************)
EM05V.ST_ScanCode1.MoverID	:=	EM05V.Golytec.Out.StationMoverID[0]	;
EM05V.ST_Buffer2.MoverID	:=	EM05V.Golytec.Out.StationMoverID[1]	;
EM05V.ST_CoverLoad1.MoverID	:=	EM05V.Golytec.Out.StationMoverID[2]	;
EM05V.ST_CoverLoad2.MoverID	:=	EM05V.Golytec.Out.StationMoverID[3]	;
EM05V.ST_CellLoad1.MoverID	:=	EM05V.Golytec.Out.StationMoverID[4]	;
EM05V.ST_CellLocation1.MoverID	:=	EM05V.Golytec.Out.StationMoverID[5]	;
EM05V.ST_Weld1.MoverID	:=	EM05V.Golytec.Out.StationMoverID[6]	;
EM05V.ST_Buffer1.MoverID	:=	EM05V.Golytec.Out.StationMoverID[7]	;
EM05V.ST_Weld2.MoverID	:=	EM05V.Golytec.Out.StationMoverID[8]	;
EM05V.ST_CellUnload1.MoverID	:=	EM05V.Golytec.Out.StationMoverID[9]	;
EM05V.ST_MovingPosition.MoverID	:=	EM05V.Golytec.Out.StationMoverID[10]	;



(******************************************** 动子到位映射 *********************************************)
EM05V.ST_ScanCode1.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[0]	;
EM05V.ST_Buffer2.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[1]	;
EM05V.ST_CoverLoad1.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[2]	;
EM05V.ST_CoverLoad2.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[3]	;
EM05V.ST_CellLoad1.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[4]	;
EM05V.ST_CellLocation1.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[5]	;
EM05V.ST_Weld1.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[6]	;
EM05V.ST_Buffer1.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[7]	;
EM05V.ST_Weld2.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[8]	;
EM05V.ST_CellUnload1.MotionDone	:=	EM05V.Golytec.Out.StationMotionDone[9]	;

EM05V.ST_MovingPosition.MoverInplace:=	EM05V.Golytec.Out.StationMotionDone[10]	;

(******************************************** 工位到位感应器映射 *********************************************)
EM05V.ST_ScanCode1.InplaceSenser	:=	TRUE	;
EM05V.ST_CoverLoad1.InplaceSenser	:=	EM05V.Sen_Inplace1.Out.Filtered_Q OR HMI_Function_Enable[5,41]	;
EM05V.ST_CoverLoad2.InplaceSenser	:=	EM05V.Sen_Inplace2.Out.Filtered_Q OR HMI_Function_Enable[5,42]	;
EM05V.ST_CellLoad1.InplaceSenser	:=	EM05V.Sen_Inplace3.Out.Filtered_Q OR HMI_Function_Enable[5,43]	;
EM05V.ST_CellLocation1.InplaceSenser	:=	EM05V.Sen_Inplace4.Out.Filtered_Q OR HMI_Function_Enable[5,44]	;
EM05V.ST_Weld1.InplaceSenser	:=	EM05V.Sen_Inplace5.Out.Filtered_Q OR HMI_Function_Enable[5,45]	;
EM05V.ST_Buffer1.InplaceSenser	:=	TRUE	;
EM05V.ST_Weld2.InplaceSenser	:=	EM05V.Sen_Inplace6.Out.Filtered_Q OR HMI_Function_Enable[5,46]	;
EM05V.ST_Buffer2.InplaceSenser	:=	TRUE	;
EM05V.ST_CellUnload1.InplaceSenser	:=	EM05V.Sen_Inplace8.Out.Filtered_Q OR HMI_Function_Enable[5,48]	;

(******************************************** 工位移动允许映射 *********************************************)
EM05V.Golytec.In.StationMotionAllow[0]	:=	EM05V.ST_ScanCode1.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[1]	:=	EM05V.ST_CoverLoad1.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[2]	:=	EM05V.ST_CoverLoad2.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[3]	:=	EM05V.ST_CellLoad1.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[4]	:=	EM05V.ST_CellLocation1.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[5]	:=	EM05V.ST_Weld1.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[6]	:=	EM05V.ST_Buffer1.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[7]	:=	EM05V.ST_Weld2.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[8]	:=	EM05V.ST_Buffer2.StationMovingAllow	;
EM05V.Golytec.In.StationMotionAllow[9]	:=	EM05V.ST_CellUnload1.StationMovingAllow	;

(********************************************	焊接首件工位处理		*********************************************)
//1#焊接位
// IF EM06P.SampleProductWeldProcess
// 	AND EM05V.ST_Weld1.MoverInplace
// 	AND EM05V.ST_Weld1.MoverIDEffective
// 	AND (EM06P.WeldMode=0 OR EM06P.WeldMode=1)
// 	AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=0
// 	AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].SampleProductFlag
// THEN
// 	Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].BettarySN:='SampleProduct1-12345678';
// 	Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].WeldJigSN:=INT_TO_STRING(EM05V.ST_Weld1.MoverIDEffectiveValue);
// 	Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality:=80;
// END_IF;
// //2#焊接位
// IF EM06P.SampleProductWeldProcess
// 	AND EM05V.ST_Weld2.MoverInplace
// 	AND EM05V.ST_Weld2.MoverIDEffective
// 	AND (EM06P.WeldMode=0 OR EM06P.WeldMode=2)
// 	AND Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].Quality=0
// 	AND Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].SampleProductFlag
// THEN
// 	Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].BettarySN:='SampleProduct2-12345678';
// 	Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].WeldJigSN:=INT_TO_STRING(EM05V.ST_Weld2.MoverIDEffectiveValue);
// 	Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].Quality:=80;
// END_IF;

(******************************************** 工位请求条件映射 *********************************************)
EM05V.ST_ScanCode1.StationRequestCondition:=NOT EM05V.ST_ScanCode1.MoverIDEffective
																				OR NOT Cell_Info[5,EM05V.ST_ScanCode1.MoverIDEffectiveValue].WeldJigScanFinish;
// EM05V.ST_CoverLoad1.StationRequestCondition:=EM05V.ST_CoverLoad1.MoverIDEffective
// 																				AND NOT EM06P.SampleProductWeldEnable
// 																				AND NOT EM05V.AutoCoverClearFlag
// 																				AND Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].WeldJigScanFinish
// 																				AND Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality=0;
// 																				
EM05V.ST_CoverLoad1.StationRequestCondition:=EM05V.ST_CoverLoad1.MoverIDEffective
												AND NOT EM05V.AutoCoverClearFlag 
												AND Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].WeldJigScanFinish
												AND ((Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality=0																				
															AND ( NOT Cell_Info[3,0].SampleProductFlag AND NOT HMI_Function_Enable[3,0]
																OR ( EM05V.ST_CoverLoad1.MoverID = EM06P.WeldJigSelectNum[0] AND HMI_Function_Enable[3,0]
													)))//无料时判断
													OR ( Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].SampleProductFlag
															AND Cell_Info[3,0].Quality = 0 
															AND (Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality=100//OK
															OR (Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality>0//NGWeldJigSelectNum
															AND Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality<70))//NG
													))
													;//												
																				
																				
EM05V.ST_CoverLoad2.StationRequestCondition:=EM05V.ST_CoverLoad2.MoverIDEffective
																				AND FALSE;
EM05V.ST_CellLoad1.StationRequestCondition:=EM05V.ST_CellLoad1.MoverIDEffective
																				AND NOT EM06P.SampleProductWeldEnable
																				AND NOT EM05V.AutoCellClearFlag
																				AND Cell_Info[5,EM05V.ST_CellLoad1.MoverIDEffectiveValue].Quality=70;
EM05V.ST_CellLocation1.StationRequestCondition:=EM05V.ST_CellLocation1.MoverIDEffective
																				AND NOT EM06P.SampleProductWeldEnable
																				AND (Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality>=75
																				AND Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality<=80
																				AND NOT Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].CellLocationFinish
																				OR Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality=75
																				OR Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality=76
																				//新增：更换旧保护盖时整形保持工位请求，给动子避让条件
																				OR (
																					(Cell_Info[6,0].Quality=90 AND NOT HMI_Function_Enable[6,2] )
																					OR (Cell_Info[6,1].Quality=90 AND NOT HMI_Function_Enable[6,2] ) 
																					OR EM05V.Done[0])
																					) 
																				;
// EM05V.ST_Weld1.StationRequestCondition:=EM05V.ST_Weld1.MoverIDEffective
// 																				AND (NOT EM06P.SampleProductWeldEnable
// 																				AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].CellLocationFinish
// 																				OR EM06P.SampleProductWeldEnable
// 																				AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].SampleProductFlag)
// 																				AND (EM06P.WeldMode=0 AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=80
// 																				OR EM06P.WeldMode=1 AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=80
// 																				OR EM06P.WeldMode=1 AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=90);
// 																				
																													
EM05V.ST_Weld1.StationRequestCondition:=EM05V.ST_Weld1.MoverIDEffective
							AND (Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].CellLocationFinish
							OR Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].SampleProductFlag)
							AND (EM06P.WeldMode=0 AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=80
							OR EM06P.WeldMode=1 AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=80
							OR EM06P.WeldMode=1 AND Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=90);											
																			
																				
																				
EM05V.ST_Buffer1.StationRequestCondition:=EM05V.ST_Buffer1.MoverIDEffective
																				AND (FALSE
																				//新增：更换旧保护盖时缓存保持工位请求，给动子避让条件
																				OR (Cell_Info[6,1].Quality=90));
EM05V.ST_Weld2.StationRequestCondition:=EM05V.ST_Weld2.MoverIDEffective
							AND (Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].CellLocationFinish
							OR Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].SampleProductFlag)
							AND (EM06P.WeldMode=0 AND Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].Quality=90
							OR EM06P.WeldMode=2 AND Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].Quality=80
							OR EM06P.WeldMode=2 AND Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].Quality=90);
EM05V.ST_Buffer2.StationRequestCondition:=EM05V.ST_Buffer2.MoverIDEffective
																				AND FALSE;
EM05V.ST_CellUnload1.StationRequestCondition:=EM05V.ST_CellUnload1.MoverIDEffective
																				AND NOT EM06P.SampleProductWeldEnable
 																				AND NOT (Cell_Info[5,EM05V.ST_CellUnload1.MoverIDEffectiveValue].SampleProductFlag
 																					AND NOT EM05V.Sen_HaveCell6.Out.Filtered_Q)
																				AND (Cell_Info[5,EM05V.ST_CellUnload1.MoverIDEffectiveValue].Quality=100
																				OR Cell_Info[5,EM05V.ST_CellUnload1.MoverIDEffectiveValue].Quality>0
																				AND Cell_Info[5,EM05V.ST_CellUnload1.MoverIDEffectiveValue].Quality<70);
																				//AND NOT Cell_Info[5,EM05V.ST_CellUnload1.MoverIDEffectiveValue].SampleProductFlag;

(******************************************** 工位状态映射 *********************************************)
EM05V.ST_ScanCode1.StationStatus:=TRUE;
EM05V.ST_CoverLoad1.StationStatus:=((NOT EM05V.Sen_HaveCover1.Out.Filtered_Q OR HMI_Button[5,15])
									AND NOT EM05V.Sen_HaveCell1.Out.Filtered_Q)
									OR HMI_TestMode_Enable
									OR
									(EM05V.Sen_HaveCover1.Out.Filtered_Q 
									AND Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].SampleProductFlag);
															
EM05V.ST_CoverLoad2.StationStatus:=TRUE;
EM05V.ST_CellLoad1.StationStatus:=((EM05V.Sen_HaveCover2.Out.Filtered_Q OR HMI_Button[5,16])
															AND NOT  EM05V.Sen_HaveCell2.Out.Filtered_Q)
															OR HMI_TestMode_Enable;
EM05V.ST_CellLocation1.StationStatus:=EM05V.Sen_HaveCell3.Out.Filtered_Q  OR Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].SampleProductFlag
															OR HMI_TestMode_Enable;
EM05V.ST_Weld1.StationStatus:=((EM05V.Sen_HaveCover4.Out.Filtered_Q   OR Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].SampleProductFlag)
															AND ((EM05V.Sen_HaveCell4.Out.Filtered_Q OR HMI_Button[5,18])  OR EM06P.SampleProductWeldEnable   OR Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].SampleProductFlag))
															OR HMI_TestMode_Enable;
EM05V.ST_Buffer1.StationStatus:=TRUE;
EM05V.ST_Weld2.StationStatus:=((EM05V.Sen_HaveCover5.Out.Filtered_Q OR Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].SampleProductFlag)
															AND ((EM05V.Sen_HaveCell5.Out.Filtered_Q OR HMI_Button[5,19]) OR EM06P.SampleProductWeldEnable   OR Cell_Info[5,EM05V.ST_Weld2.MoverIDEffectiveValue].SampleProductFlag))
															OR HMI_TestMode_Enable;
EM05V.ST_Buffer2.StationStatus:=TRUE;
EM05V.ST_CellUnload1.StationStatus:=((EM05V.Sen_HaveCover6.Out.Filtered_Q OR HMI_Button[5,20])
															AND EM05V.Sen_HaveCell6.Out.Filtered_Q)
															OR HMI_TestMode_Enable;
(******************************************** 工位状态映射 *********************************************)

// EM05V.ST_ScanCode1.StationStatus:=TRUE;
