// EM05V.ST_Weld2.StationStatus:=(not EM05V.Sen_HaveCover5.Out.Filtered_Q
// 															AND (NOT EM05V.Sen_HaveCell5.Out.Filtered_Q OR EM06P.SampleProductWeldEnable))
// 															OR HMI_TestMode_Enable;
