// EM05V.ST_CellUnload1.StationStatus:=(not EM05V.Sen_HaveCover6.Out.Filtered_Q
// 															AND not EM05V.Sen_HaveCell6.Out.Filtered_Q)
// 															OR HMI_TestMode_Enable;
// 


(******************************************** 清料条件 *********************************************)
EM05V.CellClearCondition:=
	Cell_Info[5,1].Quality>0 AND Cell_Info[5,1].Quality<=100 AND Cell_Info[5,1].Quality<>70 AND NOT EM05P.VehicleShielding[1]
	OR Cell_Info[5,2].Quality>0 AND Cell_Info[5,2].Quality<=100 AND Cell_Info[5,2].Quality<>70 AND NOT EM05P.VehicleShielding[2]
	OR Cell_Info[5,3].Quality>0 AND Cell_Info[5,3].Quality<=100 AND Cell_Info[5,3].Quality<>70 AND NOT EM05P.VehicleShielding[3]
	OR Cell_Info[5,4].Quality>0 AND Cell_Info[5,4].Quality<=100 AND Cell_Info[5,4].Quality<>70 AND NOT EM05P.VehicleShielding[4]
	OR Cell_Info[5,5].Quality>0 AND Cell_Info[5,5].Quality<=100 AND Cell_Info[5,5].Quality<>70 AND NOT EM05P.VehicleShielding[5]
	OR Cell_Info[5,6].Quality>0 AND Cell_Info[5,6].Quality<=100 AND Cell_Info[5,6].Quality<>70 AND NOT EM05P.VehicleShielding[6]
	OR Cell_Info[5,7].Quality>0 AND Cell_Info[5,7].Quality<=100 AND Cell_Info[5,7].Quality<>70 AND NOT EM05P.VehicleShielding[7]
	OR Cell_Info[5,8].Quality>0 AND Cell_Info[5,8].Quality<=100 AND Cell_Info[5,8].Quality<>70 AND NOT EM05P.VehicleShielding[8]
	OR Cell_Info[5,9].Quality>0 AND Cell_Info[5,9].Quality<=100 AND Cell_Info[5,9].Quality<>70 AND NOT EM05P.VehicleShielding[9]
	OR Cell_Info[5,10].Quality>0 AND Cell_Info[5,10].Quality<=100 AND Cell_Info[5,10].Quality<>70 AND NOT EM05P.VehicleShielding[10];

(******************************************** 工位加工状态显示 *********************************************)
EM05P.H_StationStatus[0]	:=	EM05V.ST_ScanCode1.H_StationStatus	;
EM05P.H_StationStatus[1]	:=	EM05V.ST_CoverLoad1.H_StationStatus	;
EM05P.H_StationStatus[2]	:=	EM05V.ST_CoverLoad2.H_StationStatus	;
EM05P.H_StationStatus[3]	:=	EM05V.ST_CellLoad1.H_StationStatus	;
EM05P.H_StationStatus[4]	:=	EM05V.ST_CellLocation1.H_StationStatus	;
EM05P.H_StationStatus[5]	:=	EM05V.ST_Weld1.H_StationStatus	;
EM05P.H_StationStatus[6]	:=	EM05V.ST_Buffer1.H_StationStatus	;
EM05P.H_StationStatus[7]	:=	EM05V.ST_Weld2.H_StationStatus	;
EM05P.H_StationStatus[8]	:=	EM05V.ST_Buffer2.H_StationStatus	;
EM05P.H_StationStatus[9]	:=	EM05V.ST_CellUnload1.H_StationStatus	;


(******************************************** 逻辑调用 *********************************************)

//治具扫码位1
ST_ScanCode1(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_ScanCode1,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//顶盖上料位1
ST_CoverLoad1(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_CoverLoad1,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//顶盖上料位2
ST_CoverLoad2(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_CoverLoad2,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//电芯上料位1
ST_CellLoad1(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_CellLoad1,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//电芯整形位1
ST_CellLocation1(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_CellLocation1,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//焊接位1
ST_Weld1(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_Weld1,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//焊接位2
ST_Weld2(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_Weld2,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//缓存位1
ST_Buffer1(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_Buffer1,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//缓存位2
ST_Buffer2(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_Buffer2,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);
//电芯下料位1
ST_CellUnload1(
	Auto:= Act.Act05_Auto_Station[5,0],
	StationVar:=EM05V.ST_CellUnload1,
	Parameter:=HMI_RecipeData.EM05.Golytec,
	Persistent1:=EM05P,
	Variable:=EM05V);

(********************************************	1#治具码扫码流程		*********************************************)
TON_Scan1(In:=SR_ScanCode1.ScanStep>0, PT:=T#15S);
CASE SR_ScanCode1.ScanStep	OF
	0://流程开始
		IF Act.Act05_Auto_Station[5,0]
			AND EM05V.ST_ScanCode1.StationAllow
		THEN
			EM05V.ST_ScanCode1.MoverIDTemp:=EM05V.ST_ScanCode1.MoverIDEffectiveValue;
			EM05V.ScanCode1.In.Execute:=FALSE;
			SR_ScanCode1.ScanStep:=10;
		END_IF;
	10://扫码触发
		EM05V.ScanCode1.In.Execute:=TRUE;
		SR_ScanCode1.ScanStep:=20;
	20://判断扫码结果
		IF HMI_Function_Enable[5,0]
		THEN
			IF EM05V.ST_ScanCode1.MoverIDEffective
			THEN
				Cell_Info[5,EM05V.ST_ScanCode1.MoverIDTemp].WeldJigSN:=CONCAT(STR1:=UINT_TO_STRING(EM05V.ST_ScanCode1.MoverIDTemp), STR2:='#');
				Cell_Info[5,EM05V.ST_ScanCode1.MoverIDTemp].WeldJigScanFinish:=TRUE;
				SR_ScanCode1.ScanStep:=40;
			ELSE
				H_Messages.Station[5].User_Alarm[45]:=TRUE;//EM05环轨模组：治具扫码位动子ID超过最大治具编号，未启用焊接循环线治具码扫码枪无法进行生产；
			END_IF;
		ELSIF EM05V.ScanCode1.Out.ReadSuccess//扫码OK
		THEN
			WeldJigSN1:=EM05V.ScanCode1.Out.BarCodeString;
			EM05V.ScanCode1.In.Execute:=FALSE;
			SR_ScanCode1.ScanStep:=30;
		ELSIF EM05V.ScanCode1.Out.ReadFailure//扫码NG
		THEN
			SR_ScanCode1.ErrOut.Err_ScanFailure:=TRUE;//扫码失败
			SR_ScanCode1.ScanStep:=40;
		ELSIF TON_Scan1.Q
		THEN
			SR_ScanCode1.ErrOut.Err_OverTime:=TRUE;//超时错误
			SR_ScanCode1.ScanStep:=40;
		END_IF;
	30://动子ID绑定
		EM05V.Golytec.In.StationNo:=0;
		EM05V.Golytec.In.MoverID:=STRING_TO_UINT(WeldJigSN1);
		EM05V.Golytec.In.MoverIDBangding:=TRUE;
		IF EM05V.Golytec.Out.BindingDone THEN
			EM05V.Golytec.In.MoverIDBangding:=FALSE;
			EM05V.ST_ScanCode1.MoverIDTemp:=EM05V.ST_ScanCode1.MoverID;
			SR_ScanCode1.ScanSteP:=35;
		ELSIF EM05V.Golytec.ErrOut.BindingError THEN
			EM05V.Golytec.In.MoverIDBangding:=FALSE;
			SR_ScanCode1.ScanStep:=40;
		END_IF;
	35://写入条码
		Cell_Info[5,EM05V.ST_ScanCode1.MoverIDTemp].WeldJigSN:=WeldJigSN1;
		Cell_Info[5,EM05V.ST_ScanCode1.MoverIDTemp].WeldJigScanFinish:=TRUE;
		SR_ScanCode1.ScanStep:=40;
	40://流程结束
		EM05V.ScanCode1.In.Execute:=FALSE;
		EM05V.Golytec.In.MoverIDBangding:=FALSE;
		SR_ScanCode1.ScanStep:=0;
	
END_CASE;

(********************************************	1#电芯码扫码流程		*********************************************)
TON_Scan2(In:=SR_ScanCode2.ScanStep>0, PT:=T#15S);
CASE SR_ScanCode2.ScanStep	OF
	0://流程开始
		IF Act.Act05_Auto_Station[5,0]
			AND EM05V.ST_CellLocation1.StationAllow
			AND Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality=75
		THEN
			EM05V.ST_CellLocation1.MoverIDTemp:=EM05V.ST_CellLocation1.MoverID;
			EM05V.ScanCode2.In.Execute:=FALSE;
			SR_ScanCode2.ScanStep:=10;
		END_IF;
	10://扫码触发
		EM05V.ScanCode2.In.Execute:=TRUE;
		SR_ScanCode2.ScanStep:=20;
	20://判断扫码结果
		IF EM05V.ScanCode2.Out.ReadSuccess//扫码OK
			OR HMI_Function_Enable[5,1]
			OR HMI_TestMode_Enable
		THEN  
			Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].BettarySN:=EM05V.ScanCode2.Out.BarCodeString;
			SR_ScanCode2.ScanCodeNGNum:=0;//连续NG清零
			SR_ScanCode2.ScanStep:=30;
		ELSIF EM05V.ScanCode2.Out.ReadFailure//扫码NG
		THEN
			Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].BettarySN:=EM05V.ScanCode2.Out.BarCodeString;
			Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality:=5;
			SR_ScanCode2.ScanCodeNGNum:=SR_ScanCode2.ScanCodeNGNum+1;//连续NG+1
			SR_ScanCode2.ScanStep:=40;
		ELSIF TON_Scan2.Q
		THEN
			SR_ScanCode2.ErrOut.Err_OverTime:=TRUE;//超时错误
			SR_ScanCode2.ScanStep:=40;
		END_IF;
	30://重码检测
		//=========================================
		//电芯码重码检测
		IF NOT HMI_Function_Enable[5,2]
			AND NOT HMI_TestMode_Enable
		THEN
			FOR i:=0 TO 19  DO
				IF Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].BettarySN=SR_ScanCode2.SaveCode[i] THEN
					Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality:=5;
					SR_ScanCode2.ErrOut.Err_Repeat:=TRUE;//重码错误
				END_IF;
			END_FOR;
			SR_ScanCode2.SaveCode[SR_ScanCode2.SaveCodeNum]:=Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].BettarySN;//存码
			SR_ScanCode2.SaveCodeNum:=SR_ScanCode2.SaveCodeNum+1;//入栈序号+1
			IF SR_ScanCode2.SaveCodeNum>19 THEN SR_ScanCode2.SaveCodeNum:=0; END_IF;
		END_IF;
		//=========================================
		//改变物料记忆
		IF Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality=75 THEN
			Cell_Info[5,EM05V.ST_CellLocation1.MoverIDTemp].Quality:=76;
		END_IF;
		//=========================================
		//跳步
		SR_ScanCode2.ScanStep:=40;
	40://流程结束
		EM05V.ScanCode2.In.Execute:=FALSE;
		SR_ScanCode2.ScanStep:=0;
		
END_CASE;

FOR StationSum := 0 TO StationNum BY 1 DO
	StationInit_R[StationSum](Clk:=MyStation.EMStation[EMNumber,StationSum].Init OR Act.Act04_Init[EMNumber]);
	IF  StationInit_R[StationSum].Q 
	THEN 
		MyStation.EMStation[EMNumber,StationSum].ResetComplete :=FALSE;
	END_IF;
    IF 	(MyStation.EMStation[EMNumber,StationSum].Init 
		OR Act.Act04_Init[EMNumber])
		AND Inital_Runing
		AND MyInput.AutoSwitch_Input
		AND NOT MyStation.EM[EMNumber].Shielding
		AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
		AND NOT MyStation.EM[EMNumber].IsAlarm
		AND NOT MyStation.EM[0].Running
		AND NOT OperationOut.Abort
		AND NOT OperationOut.Stop
		AND NOT OperationOut.Hold
		AND NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete
	THEN 
		Act.Act04_Init_Station[EMNumber,StationSum] := TRUE;
	ELSE
		Act.Act04_Init_Station[EMNumber,StationSum] := FALSE;
	END_IF;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	IF  MyStation.EMStation[EMNumber,StationSum].ResetComplete OR  MyStation.EMStation[EMNumber,StationSum].Shielding THEN 
		MyStation.EM[EMNumber].ResetComplete :=TRUE;
	ELSIF NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
	THEN 
		MyStation.EM[EMNumber].ResetComplete := FALSE;
		EXIT;
	END_IF;
END_FOR;

(********************工位停止需要复位所有自动流程触发的信号********************) IF Act.Act02_Condition[5] THEN StateEnd_R(Clk:=MyStation.EM[5].Stopping); //停止上升沿 IF StateEnd_R.Q THEN
//Axis_Z1电芯整形Z轴停止 EM05V.Axis_Z1.In.Location_Auto:= ARRAY32_FALSE; EM05V.Axis_Z1.In.Home_Auto:=FALSE; EM05V.Axis_Z1.In.JOG_Auto[0]:=FALSE; EM05V.Axis_Z1.In.JOG_Auto[1]:=FALSE; //Axis_Y1电芯二次定位夹爪Y轴停止 EM05VA.Axis_Y1.In.ToPos:= ArrayB_40FALSE; EM05VA.Axis_Y1.In.AbsExecute:=FALSE; EM05VA.Axis_Y1.In.HomeExecute:=FALSE; EM05VA.Axis_Y1.In.AutoJogNeg:=FALSE; EM05VA.Axis_Y1.In.AutoJogPos:=FALSE; END_IF; END_IF; (******************** Axis_Z1电芯整形Z轴动作条件********************) (*轴安全总条件*) EM05V.MovingAllow[0] := TRUE;//程序保护 (*JOG-允许*) EM05V.Axis_Z1.In.JOG_SafeCondition[0] := TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*JOG+允许*) EM05V.Axis_Z1.In.JOG_SafeCondition[1] := TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*寻参允许*) EM05V.Axis_Z1.In.Home_SafeCondition:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许*) EM05V.Axis_Z1.In.Location_SafeCondition:=ARRAY32_TRUE;//程序保护 (*定位允许[0]*) EM05V.Axis_Z1.In.Location_SafeCondition[0]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[1]*) EM05V.Axis_Z1.In.Location_SafeCondition[1]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[2]*) EM05V.Axis_Z1.In.Location_SafeCondition[2]:=(EM05V.ST_CellLocation1.MoverInplace OR HMI_SafetyCondition_Enable) AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[3]*) EM05V.Axis_Z1.In.Location_SafeCondition[3]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[4]*) EM05V.Axis_Z1.In.Location_SafeCondition[4]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[5]*) EM05V.Axis_Z1.In.Location_SafeCondition[5]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[6]*) EM05V.Axis_Z1.In.Location_SafeCondition[6]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[7]*) EM05V.Axis_Z1.In.Location_SafeCondition[7]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[8]*) EM05V.Axis_Z1.In.Location_SafeCondition[8]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[9]*) EM05V.Axis_Z1.In.Location_SafeCondition[9]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (*定位允许[10]*) EM05V.Axis_Z1.In.Location_SafeCondition[10]:=TRUE AND EM05V.MovingAllow[0] ;//程序保护 (******************** Axis_Y1电芯二次定位夹爪Y轴动作条件********************) (*轴安全总条件*) (*运动允许，MovingAllow 点动、找零点、相对、绝对条件*) EM05VA.Axis_Y1.In.MovingAllow:=TRUE; (*JOG允许*) EM05VA.Axis_Y1.In.JogAllow:=TRUE;//程序保护 (*寻参允许*) EM05VA.Axis_Y1.In.HomeAllow:=TRUE;//程序保护 (*去手自动冲突位允许*) EM05VA.Axis_Y1.In.ConflictStopToPosAllow:=TRUE;//程序保护 (*定位允许*) EM05VA.Axis_Y1.In.AbsAllow:=ArrayB_40TRUE;
(*定位允许[0]*) EM05VA.Axis_Y1.In.AbsAllow[0]:=TRUE AND EM05V.MovingAllow[1] ;//程序保护 (*定位允许[1]*) EM05VA.Axis_Y1.In.AbsAllow[1]:=TRUE ;//程序保护 (*定位允许[2]*) EM05VA.Axis_Y1.In.AbsAllow[2]:=TRUE ;//程序保护 (*定位允许[3]*) EM05VA.Axis_Y1.In.AbsAllow[3]:=TRUE ;//程序保护 (*定位允许[4]*) EM05VA.Axis_Y1.In.AbsAllow[4]:=TRUE ;//程序保护 (*定位允许[5]*) EM05VA.Axis_Y1.In.AbsAllow[5]:=TRUE AND EM05V.MovingAllow[1] ;//程序保护 (*定位允许[6]*) EM05VA.Axis_Y1.In.AbsAllow[6]:=TRUE ;//程序保护 (*定位允许[7]*) EM05VA.Axis_Y1.In.AbsAllow[7]:=TRUE ;//程序保护 (*定位允许[8]*) EM05VA.Axis_Y1.In.AbsAllow[8]:=TRUE ;//程序保护 (*定位允许[9]*) EM05VA.Axis_Y1.In.AbsAllow[9]:=TRUE ;//程序保护 (*定位允许[10]*) EM05VA.Axis_Y1.In.AbsAllow[10]:=TRUE ;//程序保护 (*****************************CQ1磁驱系统动作条件*****************************) EM05V.ST_ScanCode1.StationMovingAllow := TRUE ; EM05V.ST_CoverLoad1.StationMovingAllow := EM03V.Robot1_SafetySignal_ToEM05 AND NOT EM03V.Robot1ToEM05 OR MyStation.EMStation[3,0].Shielding OR HMI_SafetyCondition_Enable ; EM05V.ST_CoverLoad2.StationMovingAllow := TRUE ; EM05V.ST_CellLoad1.StationMovingAllow := (EM04V.X1_SafetySignal_ToEM05 OR MyStation.EMStation[4,0].Shielding) AND EM05V.Cy_Lock1_1.Out.XV AND EM05V.Cy_Lock1_2.Out.XV OR HMI_SafetyCondition_Enable ; EM05V.ST_CellLocation1.StationMovingAllow := (EM05V.Z1_SafetySignal OR MyStation.EMStation[5,1].Shielding) AND EM05V.Cy_Lock2_1.Out.XV AND EM05V.Cy_Lock2_2.Out.XV OR HMI_SafetyCondition_Enable ; EM05V.ST_Weld1.StationMovingAllow := ((EM06V.Z1_SafetySignal_ToEM05 OR MyStation.EMStation[6,0].Shielding) AND (EM06V.Y1_SafetySignal_ToEM05 OR MyStation.EMStation[6,2].Shielding)) OR HMI_SafetyCondition_Enable ; EM05V.ST_Buffer1.StationMovingAllow := TRUE ; EM05V.ST_Weld2.StationMovingAllow := ((EM06V.Z3_SafetySignal_ToEM05 OR MyStation.EMStation[6,1].Shielding) AND (EM06V.Y2_SafetySignal_ToEM05 OR MyStation.EMStation[6,3].Shielding)) OR HMI_SafetyCondition_Enable ; EM05V.ST_Buffer2.StationMovingAllow := TRUE ; EM05V.ST_CellUnload1.StationMovingAllow := (EM07V.X1_SafetySignal_ToEM05 OR MyStation.EMStation[7,0].Shielding) AND EM05V.Cy_Lock3_1.Out.XV AND EM05V.Cy_Lock3_2.Out.XV OR HMI_SafetyCondition_Enable ;
