rror AND NOT EM05V.ST_CellLoad1.MoverInplaceError AND NOT EM05V.ST_CellLocation1.MoverInplaceError AND NOT EM05V.ST_Weld1.MoverInplaceError AND NOT EM05V.ST_Weld2.MoverInplaceError AND NOT EM05V.ST_Buffer1.MoverInplaceError AND NOT EM05V.ST_Buffer2.MoverInplaceError AND NOT EM05V.ST_CellUnload1.MoverInplaceError //治具有料感应状态无异常 AND NOT EM05V.ST_ScanCode1.StationStatusError AND NOT EM05V.ST_CoverLoad1.StationStatusError AND NOT EM05V.ST_CoverLoad2.StationStatusError AND NOT EM05V.ST_CellLoad1.StationStatusError AND NOT EM05V.ST_CellLocation1.StationStatusError AND NOT EM05V.ST_Weld1.StationStatusError AND NOT EM05V.ST_Weld2.StationStatusError AND NOT EM05V.ST_Buffer1.StationStatusError AND NOT EM05V.ST_Buffer2.StationStatusError AND NOT EM05V.ST_CellUnload1.StationStatusError //焊接首件模式 AND (NOT EM06P.SampleProductWeldEnable OR (EM06P.SampleProductWeldEnable AND EM06P.SampleProductWeldProcess AND EM06P.SampleProductWeldProcessCondition) OR (EM06P.SampleProductWeldEnable AND EM06P.WeldJigSearchProcess AND EM06P.WeldJigSearchProcessCodition))
