_Y1.Out.Alarm_Out[6]; //EM05环轨模组:SV11电芯二次定位夹爪Y轴柔性回弹报警 //H_Messages.Station[5].Object_Alarm[19] := EM05V.Axis_Y1.Out.Alarm_Out[7]; //EM05环轨模组:SV11电芯二次定位夹爪Y轴正限位开关报警 //H_Messages.Station[5].Object_Alarm[20] := EM05V.Axis_Y1.Out.Alarm_Out[8]; //EM05环轨模组:SV11电芯二次定位夹爪Y轴负限位开关报警 //H_Messages.Station[5].Object_Alarm[21] := EM05V.Axis_Y1.Out.Alarm_Out[9]; //EM05环轨模组:SV11电芯二次定位夹爪Y轴未使能报警 //CY0电芯上料位解锁气缸1报警 H_Messages.Station[5].Object_Alarm[22] := EM05V.Cy_Lock1_1.Out.Alarm_Out[0]; //EM05环轨模组:电芯上料位解锁气缸1气缸R缩回安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[23] := EM05V.Cy_Lock1_1.Out.Alarm_Out[1]; //EM05环轨模组:电芯上料位解锁气缸1气缸V伸出安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[24] := EM05V.Cy_Lock1_1.Out.Alarm_Out[2]; //EM05环轨模组:电芯上料位解锁气缸1气缸缩回R/X080201 超时报警标志 H_Messages.Station[5].Object_Alarm[25] := EM05V.Cy_Lock1_1.Out.Alarm_Out[3]; //EM05环轨模组:电芯上料位解锁气缸1气缸伸出V/X080202 超时报警标志 //CY1电芯上料位解锁气缸2报警 H_Messages.Station[5].Object_Alarm[26] := EM05V.Cy_Lock1_2.Out.Alarm_Out[0]; //EM05环轨模组:电芯上料位解锁气缸2气缸R缩回安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[27] := EM05V.Cy_Lock1_2.Out.Alarm_Out[1]; //EM05环轨模组:电芯上料位解锁气缸2气缸V伸出安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[28] := EM05V.Cy_Lock1_2.Out.Alarm_Out[2]; //EM05环轨模组:电芯上料位解锁气缸2气缸缩回R/X080607 超时报警标志 H_Messages.Station[5].Object_Alarm[29] := EM05V.Cy_Lock1_2.Out.Alarm_Out[3]; //EM05环轨模组:电芯上料位解锁气缸2气缸伸出V/X080608 超时报警标志 //CY2电芯整形位解锁气缸1报警 H_Messages.Station[5].Object_Alarm[30] := EM05V.Cy_Lock2_1.Out.Alarm_Out[0]; //EM05环轨模组:电芯整形位解锁气缸1气缸R缩回安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[31] := EM05V.Cy_Lock2_1.Out.Alarm_Out[1]; //EM05环轨模组:电芯整形位解锁气缸1气缸V伸出安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[32] := EM05V.Cy_Lock2_1.Out.Alarm_Out[2]; //EM05环轨模组:电芯整形位解锁气缸1气缸缩回R/X080301 超时报警标志 H_Messages.Station[5].Object_Alarm[33] := EM05V.Cy_Lock2_1.Out.Alarm_Out[3]; //EM05环轨模组:电芯整形位解锁气缸1气缸伸出V/X080302 超时报警标志 //CY3电芯整形位解锁气缸2报警 H_Messages.Station[5].Object_Alarm[34] := EM05V.Cy_Lock2_2.Out.Alarm_Out[0]; //EM05环轨模组:电芯整形位解锁气缸2气缸R缩回安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[35] := EM05V.Cy_Lock2_2.Out.Alarm_Out[1]; //EM05环轨模组:电芯整形位解锁气缸2气缸V伸出安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[36] := EM05V.Cy_Lock2_2.Out.Alarm_Out[2]; //EM05环轨模组:电芯整形位解锁气缸2气缸缩回R/X080609 超时报警标志 H_Messages.Station[5].Object_Alarm[37] := EM05V.Cy_Lock2_2.Out.Alarm_Out[3]; //EM05环轨模组:电芯整形位解锁气缸2气缸伸出V/X080610 超时报警标志 //CY4电芯上板链线位解锁气缸1报警 H_Messages.Station[5].Object_Alarm[38] := EM05V.Cy_Lock3_1.Out.Alarm_Out[0]; //EM05环轨模组:电芯上板链线位解锁气缸1气缸R缩回安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[39] := EM05V.Cy_Lock3_1.Out.Alarm_Out[1]; //EM05环轨模组:电芯上板链线位解锁气缸1气缸V伸出安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[40] := EM05V.Cy_Lock3_1.Out.Alarm_Out[2]; //EM05环轨模组:电芯上板链线位解锁气缸1气缸缩回R/X080401 超时报警标志 H_Messages.Station[5].Object_Alarm[41] := EM05V.Cy_Lock3_1.Out.Alarm_Out[3]; //EM05环轨模组:电芯上板链线位解锁气缸1气缸伸出V/X080402 超时报警标志 //CY5电芯上板链线位解锁气缸2报警 H_Messages.Station[5].Object_Alarm[42] := EM05V.Cy_Lock3_2.Out.Alarm_Out[0]; //EM05环轨模组:电芯上板链线位解锁气缸2气缸R缩回安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[43] := EM05V.Cy_Lock3_2.Out.Alarm_Out[1]; //EM05环轨模组:电芯上板链线位解锁气缸2气缸V伸出安全条件不满足报警标志 H_Messages.Station[5].Object_Alarm[44] := EM05V.Cy_Lock3_2.Out.Alarm_Out[2]; //EM05环轨模组:电芯上板链线位解锁气缸2气缸缩回R/X080505 超时报警标志 H_Messages.Station[5].Object_Alarm[45] := EM05V.Cy_Lock3_2.Out.Alarm_Out[3]; //EM05环轨模组:电芯上板链线位解锁气缸2气缸伸出V/X080506 超时报警标志
