//SV10电芯整形Z轴警告 H_Messages.Station[5].Object_Warning[0] := EM05V.Axis_Z1.Out.Warning; //EM05环轨模组:SV10电芯整形Z轴驱动器发生警告 H_Messages.Station[5].Object_Warning[1] := EM05V.Axis_Z1.Out.Tips_Out[0]; //EM05环轨模组:SV10电芯整形Z轴未使能提示 H_Messages.Station[5].Object_Warning[2] := EM05V.Axis_Z1.Out.Tips_Out[1]; //EM05环轨模组:SV10电芯整形Z轴未回原提示 H_Messages.Station[5].Object_Warning[3] := EM05V.Axis_Z1.Out.Tips_Out[2]; //EM05环轨模组:SV10电芯整形Z轴驱动器警告输入 H_Messages.Station[5].Object_Warning[4] := EM05V.Axis_Z1.Out.Tips_Out[3]; //EM05环轨模组:SV10电芯整形Z轴轴扭矩超过额定值提示 H_Messages.Station[5].Object_Warning[5] := EM05V.Axis_Z1.Out.Tips_Out[4]; //EM05环轨模组:SV10电芯整形Z轴驱动器通讯故障 H_Messages.Station[5].Object_Warning[6] := EM05V.Axis_Z1.Out.Tips_Out[5]; //EM05环轨模组:SV10电芯整形Z轴暂停对比提示 H_Messages.Station[5].Object_Warning[7] := EM05V.Axis_Z1.Out.Tips_Out[6]; //EM05环轨模组:SV10电芯整形Z轴回零接近速度过快提示 H_Messages.Station[5].Object_Warning[8] := EM05V.Axis_Z1.Out.Tips_Out[7]; //EM05环轨模组:SV10电芯整形Z轴多重触发报警提示 H_Messages.Station[5].Object_Warning[9] := EM05V.Axis_Z1.Out.Tips_Out[8]; //EM05环轨模组:SV10电芯整形Z轴整机倍率为0提示 //SV11电芯二次定位夹爪Y轴警告 H_Messages.Station[5].Object_Warning[10] := EM05VA.Axis_Y1.ErrOut.PosSwitchWarning; //EM05环轨模组：SV11_电芯二次定位夹爪Y轴正极限开关异常 H_Messages.Station[5].Object_Warning[11] := EM05VA.Axis_Y1.ErrOut.NegSwitchWarning; //EM05环轨模组：SV11_电芯二次定位夹爪Y轴负极限开关异常 H_Messages.Station[5].Object_Warning[12] := EM05VA.Axis_Y1.ErrOut.ConflictErr; //EM05环轨模组：SV11_电芯二次定位夹爪Y轴手自动冲突 H_Messages.Station[5].Object_Warning[13] := NOT EM05VA.Axis_Y1.Out.EnableOK; //EM05环轨模组：SV11_电芯二次定位夹爪Y轴未使能标记 H_Messages.Station[5].Object_Warning[14] := NOT EM05VA.Axis_Y1.Out.Homed AND MyStation.EM[5].ResetComplete; //EM05环轨模组：SV11_电芯二次定位夹爪Y轴未寻参标记 //H_Messages.Station[5].Object_Warning[15] := EM05V.Axis_Y1.Out.Tips_Out[4]; //EM05环轨模组:SV11电芯二次定位夹爪Y轴驱动器通讯故障 //H_Messages.Station[5].Object_Warning[16] := EM05V.Axis_Y1.Out.Tips_Out[5]; //EM05环轨模组:SV11电芯二次定位夹爪Y轴暂停对比提示 //H_Messages.Station[5].Object_Warning[17] := EM05V.Axis_Y1.Out.Tips_Out[6]; //EM05环轨模组:SV11电芯二次定位夹爪Y轴回零接近速度过快提示 //H_Messa