ation[5].Object_Warning[34] := EM05V.Cy_Lock2_2.Out.Tips_Out[2]; //EM05环轨模组:电芯整形位解锁气缸2气缸暂停对比提示X080610/X080609 H_Messages.Station[5].Object_Warning[35] := EM05V.Cy_Lock2_2.Out.Tips_Out[3]; //EM05环轨模组:电芯整形位解锁气缸2点动时工位状态不对报警 //CY4电芯上板链线位解锁气缸1警告 H_Messages.Station[5].Object_Warning[36] := EM05V.Cy_Lock3_1.Out.Tips_Out[0]; //EM05环轨模组:电芯上板链线位解锁气缸1气缸缩回R预测性提示。动作时间超过记录时间时 ON H_Messages.Station[5].Object_Warning[37] := EM05V.Cy_Lock3_1.Out.Tips_Out[1]; //EM05环轨模组:电芯上板链线位解锁气缸1气缸伸出V预测性提示。动作时间大于记录时间时 ON H_Messages.Station[5].Object_Warning[38] := EM05V.Cy_Lock3_1.Out.Tips_Out[2]; //EM05环轨模组:电芯上板链线位解锁气缸1气缸暂停对比提示X080402/X080401 H_Messages.Station[5].Object_Warning[39] := EM05V.Cy_Lock3_1.Out.Tips_Out[3]; //EM05环轨模组:电芯上板链线位解锁气缸1点动时工位状态不对报警 //CY5电芯上板链线位解锁气缸2警告 H_Messages.Station[5].Object_Warning[40] := EM05V.Cy_Lock3_2.Out.Tips_Out[0]; //EM05环轨模组:电芯上板链线位解锁气缸2气缸缩回R预测性提示。动作时间超过记录时间时 ON H_Messages.Station[5].Object_Warning[41] := EM05V.Cy_Lock3_2.Out.Tips_Out[1]; //EM05环轨模组:电芯上板链线位解锁气缸2气缸伸出V预测性提示。动作时间大于记录时间时 ON H_Messages.Station[5].Object_Warning[42] := EM05V.Cy_Lock3_2.Out.Tips_Out[2]; //EM05环轨模组:电芯上板链线位解锁气缸2气缸暂停对比提示X080506/X080505 H_Messages.Station[5].Object_Warning[43] := EM05V.Cy_Lock3_2.Out.Tips_Out[3]; //EM05环轨模组:电芯上板链线位解锁气缸2点动时工位状态不对报警
END_IF; (********************手自动冲突********************) MyStation.EM[5].Conflict:= EM05V.Axis_Z1.Out.Tips_Out[5] OR EM05VA.Axis_Y1.ErrOut.ConflictErr OR EM05V.Cy_Lock1_1.Out.Tips_Out[3] OR EM05V.Cy_Lock1_2.Out.Tips_Out[3] OR EM05V.Cy_Lock2_1.Out.Tips_Out[3] OR EM05V.Cy_Lock2_2.Out.Tips_Out[3] OR EM05V.Cy_Lock3_1.Out.Tips_Out[3] OR EM05V.Cy_Lock3_2.Out.Tips_Out[3];

(********************自定义报警********************)
IF EM05V.ST_CoverLoad1.MoverInplaceError AND NOT MyStation.EMStation[5,0].Shielding THEN H_Messages.Station[5].User_Alarm[0]:=TRUE;//EM05环轨模组：顶盖上料位1，磁驱动子到位，未检测到感应器信号，请检查顶盖上料位治具到位感应1 X080603 END_IF; IF EM05V.ST_CoverLoad2.MoverInplaceError AND NOT MyStation.EMStation[5,0].Shielding THEN H_Messages.Station[5].User_Alarm[1]:=TRUE;//EM05环轨模组：顶盖上料位2，磁驱动子到位，未检测到感应器信号，请检查顶盖上料位治具到位感应2 X080604 END_IF; IF EM05V.ST_CellLoad1.MoverInplaceError AND NOT MyStation.EMStation[5,0].Shielding THEN H_Messages.Station[5].User_Alarm[2]:=TRUE;//EM05环轨模组：电芯上料位1，磁驱动子到位，未检测到感应器信号，请检查电芯上料位治具到位感应 X080605 END_IF; IF EM05V.ST_CellLocation1.MoverInplaceError AND NOT MyStation.EMStation[5,0].Shielding THEN H_Messages.Station[5].User_Alarm[3]:=TRUE;//EM05环轨模组：电芯整形位1，磁驱动子到位，未检测到感应器信号，请检查电芯整形位治具到位感应 X080606 END_IF; IF EM05V.ST_Weld1.MoverInplaceError AND NOT MyStation.EMStation[5,0].Shielding THEN H_Messages.Station[5].User_Alarm[4]:=TRUE;//EM05环轨模组：焊接位1，磁驱动子到位，未检测到感应器信号，请检查1#焊接工位治具到位感应 X080501 END_IF; IF EM05V.ST_Weld2.MoverInplaceError AND NOT MyStation.EMStation[5,0].Shielding THEN H_Messages.Station[5].User_Alarm[5]:=TRUE;//EM05环轨模组：焊接位2，磁驱动子到位，未检测到感应器信号，请检查2#焊接工位治具到位感应 X080502 END_IF; IF EM05V.ST_Buffer2.MoverInplaceError AND NOT MyStation.EMStation[5,0].Shielding THEN H_Messages.Station[5].User_Alarm[6]:=TRUE;//EM05环轨模组：缓存位2，磁驱动子到位，未检测到感应器信号，请检查电芯焊接后治具到位感应 X080507 END_IF; IF EM05V.ST_CellUnload1.MoverInplaceError AND NOT MyStation.EMStation[5,0].Shielding THEN H_Messages.Station[5].User_Alarm[7]:=TRUE;//EM05环轨模组：电芯下料位1，磁驱动子到位，未检测到感应器信号，请检查电芯上板链线位治具到位感应 X080508 END_IF;
IF EM05V.ST_CoverLoad1.MoverInplaceDelay AND EM05V.ST_CoverLoad1.MoverIDEffective AND NOT EM05P.VehicleShielding[EM05V.ST_CoverLoad1.MoverIDEffectiveValue] AND NOT MyStation.EMStation[5,0].Shielding THEN IF (Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality<>0 AND NOT EM05V.Sen_HaveCover1.Out.Filtered_Q OR Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality=0 AND EM05V.Sen_HaveCover1.Out.Filtered_Q) AND NOT HMI_TestMode_Enable AND NOT HMI_Button[5,15] AND EM03V.Robot1_SafetySignal_ToEM05 AND NOT EM06P.SampleProductWeldEnable AND Act.Act05_Auto_Station[5,0] THEN H_Messages.Station[5].User_Alarm[8]:=TRUE;//EM05环轨模组：顶盖上料位1，顶盖有料感应与有料记忆不相符；请检查顶盖上料位顶盖有料感应 X080602 END_IF; IF (Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality<>0 AND Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality<>70 AND NOT EM05V.Sen_HaveCell1.Out.Filtered_Q OR (Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality=0 OR Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].Quality=70) AND EM05V.Sen_HaveCell1.Out.Filtered_Q) AND NOT HMI_TestMode_Enable AND EM03V.Robot1_SafetySignal_ToEM05 AND NOT EM06P.SampleProductWeldEnable AND Act.Act05_Auto_Station[5,0] AND NOT Cell_Info[5,EM05V.ST_CoverLoad1.MoverIDEffectiveValue].SampleProductFlag THEN H_Messages.Station[5].User_Alarm[9]:=TRUE;//EM05环轨模组：顶盖上料位1，电芯有料感应与有料记忆不相符；请检查顶盖上料位电芯有料感应 X080601 END_IF; END_IF;
IF EM05V.ST_CellLoad1.MoverInplaceDelay AND EM05V.ST_CellLoad1.MoverIDEffective AND NOT EM05P.VehicleShielding[EM05V.ST_CellLoad1.MoverIDEffectiveValue] AND NOT MyStation.EMStation[5,0].Shielding THEN IF (Cell_Info[5,EM05V.ST_CellLoad1.MoverIDEffectiveValue].Quality<>0 AND NOT EM05V.Sen_HaveCover2.Out.Filtered_Q OR Cell_Info[5,EM05V.ST_CellLoad1.MoverIDEffectiveValue].Quality=0 AND EM05V.Sen_HaveCover2.Out.Filtered_Q) AND NOT HMI_TestMode_Enable AND NOT HMI_Button[5,16] AND EM04V.X1_SafetySignal_ToEM05 AND NOT EM06P.SampleProductWeldEnable AND Act.Act05_Auto_Station[5,0] THEN H_Messages.Station[5].User_Alarm[10]:=TRUE;//EM05环轨模组：电芯上料位1，顶盖有料感应与有料记忆不相符；请检查电芯上料位顶盖有料感应 X080204 END_IF; IF (Cell_Info[5,EM05V.ST_CellLoad1.MoverIDEffectiveValue].Quality<>0 AND Cell_Info[5,EM05V.ST_CellLoad1.MoverIDEffectiveValue].Quality<>70 AND NOT EM05V.Sen_HaveCell2.Out.Filtered_Q OR (Cell_Info[5,EM05V.ST_CellLoad1.MoverIDEffectiveValue].Quality=0 OR Cell_Info[5,EM05V.ST_CellLoad1.MoverIDEffectiveValue].Quality=70) AND EM05V.Sen_HaveCell2.Out.Filtered_Q) AND NOT HMI_TestMode_Enable AND EM04V.X1_SafetySignal_ToEM05 AND NOT EM06P.SampleProductWeldEnable AND Act.Act05_Auto_Station[5,0] AND NOT Cell_Info[5,EM05V.ST_CellLoad1.MoverIDEffectiveValue].SampleProductFlag THEN H_Messages.Station[5].User_Alarm[11]:=TRUE;//EM05环轨模组：电芯上料位1，电芯有料感应与有料记忆不相符；请检查电芯上料位电芯有料感应 X080203 END_IF; END_IF;
IF EM05V.ST_CellLocation1.MoverInplaceDelay AND EM05V.ST_CellLocation1.MoverIDEffective AND NOT EM05P.VehicleShielding[EM05V.ST_CellLocation1.MoverIDEffectiveValue] AND NOT MyStation.EMStation[5,0].Shielding THEN IF (Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality<>0 AND NOT EM05V.Sen_HaveCover3.Out.Filtered_Q OR Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality=0 AND EM05V.Sen_HaveCover3.Out.Filtered_Q) AND NOT HMI_TestMode_Enable AND NOT HMI_Button[5,17] AND NOT EM06P.SampleProductWeldEnable AND Act.Act05_Auto[5] THEN H_Messages.Station[5].User_Alarm[12]:=TRUE;//EM05环轨模组：电芯整形位1，顶盖有料感应与有料记忆不相符；请检查电芯整形位顶盖有料感应 X080304 END_IF; IF (Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality<>0 AND Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality<>70 AND NOT EM05V.Sen_HaveCell3.Out.Filtered_Q OR (Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality=0 OR Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].Quality=70) AND EM05V.Sen_HaveCell3.Out.Filtered_Q) AND NOT HMI_TestMode_Enable AND NOT EM06P.SampleProductWeldEnable AND Act.Act05_Auto_Station[5,0] AND NOT Cell_Info[5,EM05V.ST_CellLocation1.MoverIDEffectiveValue].SampleProductFlag THEN H_Messages.Station[5].User_Alarm[13]:=TRUE;//EM05环轨模组：电芯整形位1，电芯有料感应与有料记忆不相符；请检查电芯整形位电芯有料感应 X080303 END_IF; END_IF;
IF EM05V.ST_Weld1.MoverInplaceDelay AND EM05V.ST_Weld1.MoverIDEffective AND NOT EM05P.VehicleShielding[EM05V.ST_Weld1.MoverIDEffectiveValue] AND NOT MyStation.EMStation[5,0].Shielding THEN IF ( ( Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality<>0 AND (Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=70 OR Cell_Info[5,EM05V.ST_Weld1.MoverIDEffectiveValue].Quality=80) AND NOT EM05V.Sen_HaveCell4.Out.Filtered_Q )
