auiEMTime[usiEM01Index,11]	:=auiEMTime[usiEM01Index,11]	; //第11个动作时间							
auiEMTime[usiEM01Index,12]	:=auiEMTime[usiEM01Index,12]	; //第12个动作时间							
auiEMTime[usiEM01Index,13]	:=auiEMTime[usiEM01Index,13]	; //第13个动作时间							
auiEMTime[usiEM01Index,14]	:=auiEMTime[usiEM01Index,14]	; //第14个动作时间	
auiEMTime[usiEM01Index,63]	:=auiEMTime[usiEM01Index,63]	; //第63个动作时间

(********************工位停止需要复位所有自动流程触发的信号********************) IF Act.Act02_Condition[3] THEN StateEnd_R(Clk:=MyStation.EM[3].Stopping); //停止上升沿 IF StateEnd_R.Q THEN
//Axis_X1刻码NG金相首件移栽轴停止 EM03V.Axis_X1.In.Location_Auto:= ARRAY32_FALSE; EM03V.Axis_X1.In.Home_Auto:=FALSE; EM03V.Axis_X1.In.JOG_Auto[0]:=FALSE; EM03V.Axis_X1.In.JOG_Auto[1]:=FALSE;
//刻码NG拉带调速电机启动停止 EM03V.Mo_Roll1.In.StartLeft:=FALSE; EM03V.Mo_Roll1.In.StartRight:=FALSE; EM03V.Mo_Roll1.In.Stop:=TRUE; END_IF;
END_IF; (******************** Axis_X1刻码NG金相首件移栽轴动作条件********************) (*轴安全总条件*) EM03V.MovingAllow[0] := EM03V.Robot1_SafetySignal_ToNG AND NOT EM03V.Robot1ToNG AND EM03V.Cy_Location1.Out.XR AND HMI_EQ.SD_LockStatus[9] OR MyStation.EMStation[3,0].Shielding OR HMI_SafetyCondition_Enable ; //程序保护 (*JOG-允许*) EM03V.Axis_X1.In.JOG_SafeCondition[0] := TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*JOG+允许*) EM03V.Axis_X1.In.JOG_SafeCondition[1] := TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*寻参允许*) EM03V.Axis_X1.In.Home_SafeCondition:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许*) EM03V.Axis_X1.In.Location_SafeCondition:=ARRAY32_TRUE;//程序保护 (*定位允许[0]*) EM03V.Axis_X1.In.Location_SafeCondition[0]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[1]*) EM03V.Axis_X1.In.Location_SafeCondition[1]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[2]*) EM03V.Axis_X1.In.Location_SafeCondition[2]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[3]*) EM03V.Axis_X1.In.Location_SafeCondition[3]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[4]*) EM03V.Axis_X1.In.Location_SafeCondition[4]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[5]*) EM03V.Axis_X1.In.Location_SafeCondition[5]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[6]*) EM03V.Axis_X1.In.Location_SafeCondition[6]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[7]*) EM03V.Axis_X1.In.Location_SafeCondition[7]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[8]*) EM03V.Axis_X1.In.Location_SafeCondition[8]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[9]*) EM03V.Axis_X1.In.Location_SafeCondition[9]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护 (*定位允许[10]*) EM03V.Axis_X1.In.Location_SafeCondition[10]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护
(*定位允许[11]*) EM03V.Axis_X1.In.Location_SafeCondition[11]:=TRUE AND EM03V.MovingAllow[0] ;//程序保护
EM03V.Robot1.In.Location_SafeCondition:=ARRAY48_TRUE;
EM03V.Robot1.In.ToPosAllow[2]:=(EM02V.Z1_SafetySignal_ToEM03 AND EM02V.R1_SafetySignal_ToEM03 OR MyStation.EM[2].Shielding) OR HMI_SafetyCondition_Enable;
//刻码下料机器人安全信号-->EM02_刻码拉带模组 EM03V.Robot1_SafetySignal_ToEM02:=EM03V.Robot1.Out.SafetyArea[0]; //刻码下料机器人安全信号-->EM05_环轨模组 EM03V.Robot1_SafetySignal_ToEM05:=EM03V.Robot1.Out.SafetyArea[1]; //刻码下料机器人安全信号-->NG位 EM03V.Robot1_SafetySignal_ToNG:=EM03V.Robot1.Out.SafetyArea[2] AND EM03V.Robot1.Out.SafetyArea[4] // AND ( ( EM03V.Robot1.Out.PosDone[0] OR // EM03V.Robot1.Out.PosDone[1] OR // EM03V.Robot1.Out.PosDone[2] OR // EM03V.Robot1.Out.PosDone[3] OR // EM03V.Robot1.Out.PosDone[4] OR // EM03V.Robot1.Out.PosDone[5] OR // EM03V.Robot1.Out.PosDone[6] // ) // OR NOT EM03V.Robot1.Out.PosDone[7]) ;
//复位标志 IF EM03V.Robot1.Out.PosDone[0] OR NOT EM03V.Robot1_SafetySignal_ToEM02 THEN EM03V.Robot1ToEM02:=FALSE; END_IF;
IF EM03V.Robot1.Out.PosDone[0] OR NOT EM03V.Robot1_SafetySignal_ToEM05 THEN EM03V.Robot1ToEM05:=FALSE; END_IF;
IF EM03V.Robot1.Out.PosDone[0] OR NOT EM03V.Robot1_SafetySignal_ToNG THEN EM03V.Robot1ToNG:=FALSE; END_IF;
(*****************************Cy0刻码下料夹爪气缸动作条件*****************************) EM03V.Cy_Clamp1.In.SafeCondition_V:=TRUE;//EM03刻码下料夹爪气缸回缩允许 EM03V.Cy_Clamp1.In.SafeCondition_R:=TRUE;//EM03刻码下料夹爪气缸伸出允许 (*****************************Cy1首件确认治具锁定气缸动作条件*****************************) EM03V.Cy_Location1.In.SafeCondition_V:=TRUE;//EM03首件确认治具锁定气缸回缩允许 EM03V.Cy_Location1.In.SafeCondition_R:=TRUE;//EM03首件确认治具锁定气缸伸出允许;
(*****************************Mo0刻码NG拉带调速电机启动动作条件*****************************) EM03V.Mo_Roll1.In.LeftAllow := ( MyStatus.StatusAuto AND HMI_EQ.SD_LockStatus[9] ) OR MyStatus.StatusManual OR ( EM03V.Sen_Button3.Out.Filtered_Q AND EM03V.Sen_Button4.Out.Filtered_Q ) ; //（安全保护，需要写注释） EM03V.Mo_Roll1.In.RightAllow:= ( MyStatus.StatusAuto AND HMI_EQ.SD_LockStatus[9] ) OR MyStatus.StatusManual OR ( EM03V.Sen_Button3.Out.Filtered_Q AND EM03V.Sen_Button4.Out.Filtered_Q ) ; //（安全保护，需要写注释）

