FB_Button1(Button1:= EM03V.Sen_Button1.Out.Filtered_Q
	, Button2:= EM03V.Sen_Button2.Out.Filtered_Q
	, MoRun=> ConfirmButton1);
//下层NG双手确认按钮
FB_Button2(Button1:= EM03V.Sen_Button3.Out.Filtered_Q
	, Button2:= EM03V.Sen_Button4.Out.Filtered_Q
	, MoRun=> ConfirmButton2);

Ary_SenSampleCover[1]:=EM03V.Sen_SampleCover1.Out.Filtered_Q;
Ary_SenSampleCover[2]:=EM03V.Sen_SampleCover2.Out.Filtered_Q;
Ary_SenSampleCover[3]:=EM03V.Sen_SampleCover3.Out.Filtered_Q;
Ary_SenSampleCover[4]:=EM03V.Sen_SampleCover4.Out.Filtered_Q;
Ary_SenSampleCover[5]:=EM03V.Sen_SampleCover5.Out.Filtered_Q;
//计数顶盖有料感应数量
Num_SenSampleCover:=0;
FOR i1:=0 TO 5 BY 1 DO
	IF Ary_SenSampleCover[i1] THEN
		Num_SenSampleCover:=Num_SenSampleCover+1;
	END_IF
END_FOR
//计数焊接治具选择数量
Num_WeldJigSelect:=0;
FOR i2:=0 TO 10 BY 1 DO
	IF EM06P.WeldJigSelect[i2] THEN
		Num_WeldJigSelect:=Num_WeldJigSelect+1;
	END_IF
END_FOR
//检索两个计数是否一致
IF Num_SenSampleCover=Num_WeldJigSelect 
	AND Num_SenSampleCover<>0 
	AND Num_WeldJigSelect<>0
THEN
	EM03V.Process_steps[1]:=105;
ELSE
	H_Messages.General_Warning[17]:=TRUE;//首件选择治具数与顶盖有料数不一致弹窗
	HMI_Function_Enable[3,0]:=FALSE;
	EM03V.Process_steps[1]:=0;
END_IF

//功能启用条件
EM06P.FunctionEnableCondition:=MyStatus.StatusAuto
								AND NOT HMI_EQ.HMI_SelectChange_Enable[10]
								;
//焊接治具选择条件
FOR i:=0 TO 10 BY 1 DO
EM06P.WeldJigSelectCondition[i]:= NOT EM05P.VehicleShielding[i];
END_FOR;								


R_WeldJigSelect(CLK:= HMI_Function_Enable[3,0]);	//启用自动首件 
WeldJigSelectOK:=  Search_Alarm(In:= EM06P.WeldJigSelect);//搜索是否选择治具号
IF R_WeldJigSelect.Q 
	AND  NOT  WeldJigSelectOK
THEN
	HMI_Function_Enable[3,0] := FALSE;
	H_Messages.Station[3].User_Warning[2]	:= TRUE;//未选择自动首件焊接治具
ELSIF  R_WeldJigSelect.Q 
	AND   WeldJigSelectOK
THEN
	//轮询判断当前需要焊接的治具，放入堆栈数据中
	FOR i:=1 TO 14 DO    
		IF EM06P.WeldJigSelect[i]
		THEN 
				WeldJigSelectNum := i;
				StackPush(
					In:=WeldJigSelectNum,
					InOut:=WeldJigSelectNum_Stack[0],
					Size:=14,
					Num:=WeldJigSelect_PushNum
					);
		END_IF;
	END_FOR;
END_IF

//对应治具的顶盖放置完成，
F_DeleteStack[0](CLK:=Cell_Info[3,0].Quality  = 80 AND Cell_Info[3,0].SampleProductFlag);
IF  F_DeleteStack[0].Q
	AND WeldJigSelect_PushNum<>0	
THEN
		StackDel(
		InOut:=WeldJigSelectNum_Stack[0],
		Size:=14,
		Num:=WeldJigSelect_PushNum,
		Offset:=0);
END_IF

//焊接首件完成
IF  HMI_Function_Enable[3,0]
	AND WeldJigSelect_PushNum =  0
THEN
	HMI_Function_Enable[3,0] := FALSE;
END_IF;

//首件模式复位
F_FirstWork(CLK:=HMI_Function_Enable[3,0] );
IF F_FirstWork.Q THEN	
	Clear(WeldJigSelect_PushNum);
	Clear(WeldJigSelectNum_Stack);
	Clear(EM06P.WeldJigSelect);//选择的编号也复位
END_IF

//每天0点0分0秒，传送数据
IF Signal_NewDayRT THEN
	EM06P.WeldJigOldData2:=EM06P.WeldJigOldData1;
	EM06P.WeldJigOldData1:=EM06P.WeldJigData;
	Clear(EM06P.WeldJigData);
END_IF;

EM06P.WeldJigSelectNum[0] :=WeldJigSelectNum_Stack[0];

FOR StationSum := 0 TO StationNum BY 1 DO
	Act.Act05_Auto_Station[EMNumber,StationSum] := Act.Act05_Auto[EMNumber] AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	StationInit_R[StationSum](Clk:=MyStation.EMStation[EMNumber,StationSum].Init OR Act.Act04_Init[EMNumber]);
	IF  StationInit_R[StationSum].Q 
	THEN 
		MyStation.EMStation[EMNumber,StationSum].ResetComplete :=FALSE;
	END_IF;
    IF 	(MyStation.EMStation[EMNumber,StationSum].Init 
		OR Act.Act04_Init[EMNumber])
		AND Inital_Runing
		AND MyInput.AutoSwitch_Input
		AND NOT MyStation.EM[EMNumber].Shielding
		AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
		AND NOT MyStation.EM[EMNumber].IsAlarm
		AND NOT MyStation.EM[0].Running
		AND NOT OperationOut.Abort
		AND NOT OperationOut.Stop
		AND NOT OperationOut.Hold
		AND NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete
	THEN 
		Act.Act04_Init_Station[EMNumber,StationSum] := TRUE;
	ELSE
		Act.Act04_Init_Station[EMNumber,StationSum] := FALSE;
	END_IF;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	IF  MyStation.EMStation[EMNumber,StationSum].ResetComplete OR  MyStation.EMStation[EMNumber,StationSum].Shielding THEN 
		MyStation.EM[EMNumber].ResetComplete :=TRUE;
	ELSIF NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
	THEN 
		MyStation.EM[EMNumber].ResetComplete := FALSE;
		EXIT;
	END_IF;
END_FOR;

IF Act.Act09_AlmAndMesg[3] THEN MyStation.EM[3].IsAlarm:= Search_Alarm(H_Messages.Station[3].Object_Alarm) OR H_Messages.Station[3].Alarm; (********************报警信息********************)
//SV57刻码NG金相首件移栽轴报警 H_Messages.Station[3].Object_Alarm[0] := EM03V.Axis_X1.Out.Alarm; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴驱动器发生错误 H_Messages.Station[3].Object_Alarm[1] := EM03V.Axis_X1.Out.Alarm_Out[0]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴驱动器通讯故障报警 H_Messages.Station[3].Object_Alarm[2] := EM03V.Axis_X1.Out.Alarm_Out[1]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴轴故障报警 H_Messages.Station[3].Object_Alarm[3] := EM03V.Axis_X1.Out.Alarm_Out[2]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴回原安全条件不满足报警 H_Messages.Station[3].Object_Alarm[4] := EM03V.Axis_X1.Out.Alarm_Out[3]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴回原中原点或负限位异常 H_Messages.Station[3].Object_Alarm[5] := EM03V.Axis_X1.Out.Alarm_Out[4]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴轴运动安全条件不满足报警 H_Messages.Station[3].Object_Alarm[6] := EM03V.Axis_X1.Out.Alarm_Out[5]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴扭矩当前值超过阈值报警 H_Messages.Station[3].Object_Alarm[7] := EM03V.Axis_X1.Out.Alarm_Out[6]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴柔性回弹报警 H_Messages.Station[3].Object_Alarm[8] := EM03V.Axis_X1.Out.Alarm_Out[7]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴正限位开关报警 H_Messages.Station[3].Object_Alarm[9] := EM03V.Axis_X1.Out.Alarm_Out[8]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴负限位开关报警 H_Messages.Station[3].Object_Alarm[10] := EM03V.Axis_X1.Out.Alarm_Out[9]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴未使能报警 //CY0刻码下料夹爪气缸报警 H_Messages.Station[3].Object_Alarm[11] := EM03V.Cy_Clamp1.Out.Alarm_Out[0]; //EM03顶盖中转模组:刻码下料夹爪气缸气缸R缩回安全条件不满足报警标志 H_Messages.Station[3].Object_Alarm[12] := EM03V.Cy_Clamp1.Out.Alarm_Out[1]; //EM03顶盖中转模组:刻码下料夹爪气缸气缸V伸出安全条件不满足报警标志 H_Messages.Station[3].Object_Alarm[13] := EM03V.Cy_Clamp1.Out.Alarm_Out[2]; //EM03顶盖中转模组:刻码下料夹爪气缸气缸缩回R/X070402 超时报警标志 H_Messages.Station[3].Object_Alarm[14] := EM03V.Cy_Clamp1.Out.Alarm_Out[3]; //EM03顶盖中转模组:刻码下料夹爪气缸气缸伸出V/X070401 超时报警标志 //CY1首件确认治具锁定气缸报警 H_Messages.Station[3].Object_Alarm[15] := EM03V.Cy_Location1.Out.Alarm_Out[0]; //EM03顶盖中转模组:首件确认治具锁定气缸气缸R缩回安全条件不满足报警标志 H_Messages.Station[3].Object_Alarm[16] := EM03V.Cy_Location1.Out.Alarm_Out[1]; //EM03顶盖中转模组:首件确认治具锁定气缸气缸V伸出安全条件不满足报警标志 H_Messages.Station[3].Object_Alarm[17] := EM03V.Cy_Location1.Out.Alarm_Out[2]; //EM03顶盖中转模组:首件确认治具锁定气缸气缸缩回R/X070302 超时报警标志 H_Messages.Station[3].Object_Alarm[18] := EM03V.Cy_Location1.Out.Alarm_Out[3]; //EM03顶盖中转模组:首件确认治具锁定气缸气缸伸出V/X070301 超时报警标志
(********************警告信息********************)
//SV57刻码NG金相首件移栽轴警告 H_Messages.Station[3].Object_Warning[0] := EM03V.Axis_X1.Out.Warning; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴驱动器发生警告 H_Messages.Station[3].Object_Warning[1] := EM03V.Axis_X1.Out.Tips_Out[0]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴未使能提示 H_Messages.Station[3].Object_Warning[2] := EM03V.Axis_X1.Out.Tips_Out[1]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴未回原提示 H_Messages.Station[3].Object_Warning[3] := EM03V.Axis_X1.Out.Tips_Out[2]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴驱动器警告输入 H_Messages.Station[3].Object_Warning[4] := EM03V.Axis_X1.Out.Tips_Out[3]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴轴扭矩超过额定值提示 H_Messages.Station[3].Object_Warning[5] := EM03V.Axis_X1.Out.Tips_Out[4]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴驱动器通讯故障 H_Messages.Station[3].Object_Warning[6] := EM03V.Axis_X1.Out.Tips_Out[5]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴暂停对比提示 H_Messages.Station[3].Object_Warning[7] := EM03V.Axis_X1.Out.Tips_Out[6]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴回零接近速度过快提示 H_Messages.Station[3].Object_Warning[8] := EM03V.Axis_X1.Out.Tips_Out[7]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴多重触发报警提示 H_Messages.Station[3].Object_Warning[9] := EM03V.Axis_X1.Out.Tips_Out[8]; //EM03顶盖中转模组:SV57刻码NG金相首件移栽轴整机倍率为0提示 //CY0刻码下料夹爪气缸警告 H_Messages.Station[3].Object_Warning[10] := EM03V.Cy_Clamp1.Out.Tips_Out[0]; //EM03顶盖中转模组:刻码下料夹爪气缸气缸缩回R预测性提示。动作时间超过记录时间时 ON H_Messages.Station[3].Object_Warning[11] := EM03V.Cy_Clamp1.Out.Tips_Out[1]; //EM03顶盖中转模组:刻码下料夹爪气缸气缸伸出V预测性提示。动作时间大于记录时间时 ON H_Messages.Station[3].Object_Warning[12] := EM03V.Cy_Clamp1.Out.Tips_Out[2]; //EM03顶盖中转模组:刻码下料夹爪气缸气缸暂停对比提示X070401/X070402 H_Messages.Station[3].Object_Warning[13] := EM03V.Cy_Clamp1.Out.Tips_Out[3]; //EM03顶盖中转模组:刻码下料夹爪气缸点动时工位状态不对报警 //CY1首件确认治具锁定气缸警告 H_Messages.Station[3].Object_Warning[14] := EM03V.Cy_Location1.Out.Tips_Out[0]; //EM03顶盖中转模组:首件确认治具锁定气缸气缸缩回R预测性提示。动作时间超过记录时间时 ON H_Messages.Station[3].Object_Warning[15] := EM03V.Cy_Location1.Out.Tips_Out[1]; //EM03顶盖中转模组:首件确认治具锁定气缸气缸伸出V预测性提示。动作时间大于记录时间时 ON H_Messages.Station[3].Object_Warning[16] := EM03V.Cy_Location1.Out.Tips_Out[2]; //EM03顶盖中转模组:首件确认治具锁定气缸气缸暂停对比提示X070301/X070302 H_Messages.Station[3].Object_Warning[17] := EM03V.Cy_Location1.Out.Tips_Out[3]; //EM03顶盖中转模组:首件确认治具锁定气缸点动时工位状态不对报警
END_IF; (********************手自动冲突********************) MyStation.EM[3].Conflict:= EM03V.Axis_X1.Out.Tips_Out[5] OR EM03V.Cy_Clamp1.Out.Tips_Out[3] OR EM03V.Cy_Location1.Out.Tips_Out[3];

(********************自定义报警********************)
IF (Cell_Info[3,0].Quality<>0 AND NOT EM03V.Sen_HaveCover1.Out.Filtered_Q OR Cell_Info[3,0].Quality=0 AND EM03V.Sen_HaveCover1.Out.Filtered_Q AND NOT EM03V.Cy_Clamp1.Out.XR) AND NOT HMI_TestMode_Enable AND EM03V.Robot1_SafetySignal_ToEM02 AND EM03V.Robot1_SafetySignal_ToEM05 AND EM03V.Robot1_SafetySignal_ToNG AND NOT EM03V.Robot1ToEM02 AND NOT EM03V.Robot1ToEM05 AND NOT EM03V.Robot1ToNG AND Act.Act05_Auto_Station[3,0] AND NOT MyStation.EMStation[3,0].Shielding THEN H_Messages.Station[3].User_Alarm[0]:=TRUE;//EM03顶盖中转模组：夹爪顶盖有料感应与有料记忆不相符；请检查刻码下料有料感应 X070403 END_IF;
IF NOT EM03V.Sen_Avoid1.Out.Filtered_Q AND NOT MyStation.EMStation[3,0].Shielding THEN H_Messages.Station[3].User_Alarm[1]:=TRUE;//EM03顶盖中转模组：检测到防撞感应异常；请检查刻码下料防撞感应 X070404 END_IF;
IF EM03_Robot1._pConnector>0 AND TO_UINT(EM03_Robot1.eState)<>8 AND NOT MyStation.EMStation[3,0].Shielding THEN H_Messages.Station[3].User_Alarm[2]:=TRUE;//EM03顶盖中转模组：机器人EIP网络通讯断开192.168.0.42，请检查网线连接； END_IF; IF EM03V.Robot1.Out.ProgramError THEN MyStation.EM[3].ResetComplete:=FALSE; H_Messages.Station[3].User_Alarm[3]:=TRUE;//EM03顶盖中转模组：机器人软件程序错误RIO_ERROR，请到工控机机器人软件上面查看故障内容； END_IF; IF EM03V.Robot1.Out.RobotError THEN H_Messages.Station[3].User_Alarm[4]:=TRUE;//EM03顶盖中转模组：机器人控制器系统故障RIO_SERROR，请到工控机机器人软件上面查看故障内容； END_IF; IF EM03V.Robot1.ErrOut.Alarm THEN H_Messages.Station[3].User_Alarm[5]:=TRUE;//EM03顶盖中转模组：机器人控制错误，请打开触摸屏机器人操作页面查看错误ID信息； END_IF;
TON_Alarm01( In:=EM03V.Mo_Roll1.Out.RunRight_Q , PT:=T#15S); IF TON_Alarm01.Q THEN IF EM03V.Sen_PosHave.Out.Filtered_Q THEN H_Messages.Station[3].User_Alarm[6]:=TRUE;//EM03顶盖中转模组：刻码NG拉带调速电机持续正转，持续检测到感应器信号报警；请检查顶盖NG有料感应 X080205 END_IF; IF EM03V.Sen_Leave.Out.Filtered_Q THEN H_Messages.Station[3].User_Alarm[7]:=TRUE;//EM03顶盖中转模组：刻码NG拉带调速电机持续正转，持续检测到感应器信号报警；请检查顶盖NG离料感应 X080206 END_IF; H_Messages.Station[3].User_Alarm[8]:=TRUE;//EM03顶盖中转模组：刻码NG拉带调速电机持续正转，调速电机可能无法转动，请检查调速器是否启动； END_IF;
IF EM03H_Robot[0].Out.bErrID <> 0 THEN H_Messages.Station[3].User_Alarm[9]:=TRUE;//EM03顶盖中转模组：机器人运行异常，请检查！ END_IF ;
