H_Messages.Station[3].User_Warning[0]:=Act.Act05_Auto[3] AND EM03V.Sen_Full.Out.Filtered_Q AND NOT MyStation.EMStation[3,1].Shielding ;//EM03顶盖中转模组：NG拉带满料提示
TON_Full( In:=Act.Act05_Auto[3] AND H_Messages.Station[3].User_Warning[0] AND NOT MyInput.Reset_Input , PT:=T#30S); H_Messages.Station[3].User_Warning[1]:=TON_Full.Q;//EM03顶盖中转模组：NG拉带满料提示(声光提示)
