//EM11焊印贴胶模组：切胶气缸2伸出/缩回运动干涉，贴胶模组换胶安全门(SD44-45)未锁紧 IF (NOT EM11V.Cy_Cut2.In.SafeCondition_V AND EM11V.Cy_Cut2.In.Manual_V) OR (NOT EM11V.Cy_Cut2.In.SafeCondition_R AND EM11V.Cy_Cut2.In.Manual_R) THEN H_Messages.Station[11].HinderToPos[8,1]:=TRUE;//EM11焊印贴胶模组：切胶气缸2伸出/缩回运动干涉，贴胶模组换胶安全门(SD44-45/49)未锁紧 HMI_EQ.ConflictPopups:=TRUE; END_IF
// EM11焊印贴胶模组:手自动冲突 IF NOT Signal_ResetCompleteRT AND MyInput.Start_Input AND NOT MyStation.EM[11].Shielding AND MyStation.EM[11].Conflict THEN H_Messages.Station[11].HinderToPos[25,0] := TRUE ;// EM11焊印贴胶模组:手自动冲突 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 IF EM11V.Axis_Z1.Out.Tips_Out[5] THEN H_Messages.Station[11].HinderToPos[25,1] := TRUE ;// EM11焊印贴胶模组:SV35_吸胶头Z轴-手自动冲突 END_IF IF EM11V.Axis_Y1.Out.Tips_Out[5] THEN H_Messages.Station[11].HinderToPos[25,2] := TRUE ;// EM11焊印贴胶模组:SV36_1#拉胶Y轴-手自动冲突 END_IF IF EM11V.Axis_R1.Out.Tips_Out[5] THEN H_Messages.Station[11].HinderToPos[25,3] := TRUE ;// EM11焊印贴胶模组:SV37_1#拉胶R轴-手自动冲突 END_IF IF EM11V.Axis_Y2.Out.Tips_Out[5] THEN H_Messages.Station[11].HinderToPos[25,4] := TRUE ;// EM11焊印贴胶模组:SV38_2#拉胶Y轴-手自动冲突 END_IF IF EM11V.Axis_R2.Out.Tips_Out[5] THEN H_Messages.Station[11].HinderToPos[25,5] := TRUE ;// EM11焊印贴胶模组:SV39_2#拉胶R轴-手自动冲突 END_IF IF EM11V.Axis_X1.Out.Tips_Out[5] THEN H_Messages.Station[11].HinderToPos[25,6] := TRUE ;// EM11焊印贴胶模组:SV40_吸胶头变距X轴-手自动冲突 END_IF IF EM11V.Axis_Y3.Out.Tips_Out[5] THEN H_Messages.Station[11].HinderToPos[25,7] := TRUE ;// EM11焊印贴胶模组:SV41_取胶Y轴-手自动冲突 END_IF IF EM11V.Axis_X2.Out.Tips_Out[5] THEN H_Messages.Station[11].HinderToPos[25,8] := TRUE ;// EM11焊印贴胶模组:SV42_胶卷切换X轴-手自动冲突 END_IF IF EM11V.Cy_Open1_1.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,9] := TRUE ;// EM11焊印贴胶模组:1#开胶气缸1-手自动冲突 END_IF IF EM11V.Cy_Open1_2.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,10] := TRUE ;// EM11焊印贴胶模组:1#开胶气缸2-手自动冲突 END_IF IF EM11V.Cy_Press1_1.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,11] := TRUE ;// EM11焊印贴胶模组:1#压胶气缸1-手自动冲突 END_IF IF EM11V.Cy_Press1_2.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,12] := TRUE ;// EM11焊印贴胶模组:1#压胶气缸2-手自动冲突 END_IF IF EM11V.Cy_Open2_1.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,13] := TRUE ;// EM11焊印贴胶模组:2#开胶气缸1-手自动冲突 END_IF IF EM11V.Cy_Open2_2.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,14] := TRUE ;// EM11焊印贴胶模组:2#开胶气缸2-手自动冲突 END_IF IF EM11V.Cy_Press2_1.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,15] := TRUE ;// EM11焊印贴胶模组:2#压胶气缸1-手自动冲突 END_IF IF EM11V.Cy_Press2_2.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,16] := TRUE ;// EM11焊印贴胶模组:2#压胶气缸2-手自动冲突 END_IF IF EM11V.Cy_Clamp1.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,17] := TRUE ;// EM11焊印贴胶模组:夹胶气缸1-手自动冲突 END_IF IF EM11V.Cy_Clamp2.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,18] := TRUE ;// EM11焊印贴胶模组:夹胶气缸2-手自动冲突 END_IF IF EM11V.Cy_Cut1.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,19] := TRUE ;// EM11焊印贴胶模组:切胶气缸1-手自动冲突 END_IF IF EM11V.Cy_Cut2.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,20] := TRUE ;// EM11焊印贴胶模组:切胶气缸2-手自动冲突 END_IF IF EM11V.Cy_Up1.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,21] := TRUE ;// EM11焊印贴胶模组:接胶气缸1-手自动冲突 END_IF IF EM11V.Cy_Up2.Out.Tips_Out[3] THEN H_Messages.Station[11].HinderToPos[25,22] := TRUE ;// EM11焊印贴胶模组:接胶气缸2-手自动冲突 END_IF END_IF;
