//SV35_吸胶头Z轴安全信号
EM11V.Z1_SafetySignal:=EM11V.Axis_Z1.Out.CurrentPos<=HMI_RecipeData.EM11.Axis_Z1.Location_Postion[1]+3
										AND EM11V.Axis_Z1.Out.Homed;
//SV35_吸胶头Z轴安全信号-->EM08_下料拉带模组
EM11V.Z1_SafetySignal_ToEM08:=ABS(EM11V.Axis_Y3.Out.CurrentPos-HMI_RecipeData.EM11.Axis_Y3.Location_Postion[2])>=3
										AND EM11V.Axis_Y3.Out.Homed
										OR EM11V.Axis_Z1.Out.CurrentPos<=HMI_RecipeData.EM11.Axis_Z1.Location_Postion[4]+3
										AND EM11V.Axis_Z1.Out.Homed
										OR EM11V.Z1_SafetySignal;
//SV35_吸胶头Z轴安全信号-->SV36_1#拉胶Y轴和SV38_2#拉胶Y轴
EM11V.Z1_SafetySignal_ToY1AndY2:=ABS(EM11V.Axis_Y3.Out.CurrentPos-HMI_RecipeData.EM11.Axis_Y3.Location_Postion[1])>=3
										AND EM11V.Axis_Y3.Out.Homed
										OR EM11V.Z1_SafetySignal;
