EM11V.Y1_SafetySignal_ToAxisAviod:=EM11V.Axis_Y1.Out.CurrentPos<=HMI_RecipeData.EM11.Axis_Y1.Location_Postion[2]+3
										AND EM11V.Axis_Y1.Out.Homed;
