										AND EM11V.Axis_Y2.Out.Homed;
//SV36_1#拉胶Y轴-->SV42_胶卷切换X轴
EM11V.Y1_SafetySignal_ToX2:=EM11V.Axis_Y1.Out.CurrentPos<=HMI_RecipeData.EM11.Axis_Y1.Location_Postion[1]+3
										AND EM11V.Axis_Y1.Out.Homed;
