//自动
IF MyStatus.StatusAuto THEN	
	//1#备胶
	IF R_Cy_Press1_1.Q AND 
	( EM11V.Cy_Press1_1.Out.XV OR EM11V.Cy_Press1_1.In.Auto_V )    
	   THEN
