	EM11V.Cy_Block6_211.In.Auto_R := TRUE ;	
    ELSIF R_Cy_Press1_1.Q AND 
    ( EM11V.Cy_Press1_1.Out.XR OR EM11V.Cy_Press1_1.In.Auto_R )     
	   THEN
	EM11V.Cy_Press1_1.In.Auto_V := TRUE ;
		EM11V.Cy_Block6_211.In.Auto_V := TRUE ;	
    END_IF;

	IF R_Cy_Press1_2.Q AND 
	( EM11V.Cy_Press1_2.Out.XV OR EM11V.Cy_Press1_2.In.Auto_V )    
	   THEN
	EM11V.Cy_Press1_2.In.Auto_R := TRUE ;
	EM11V.Cy_Block6_212.In.Auto_R := TRUE ;	
    ELSIF R_Cy_Press1_2.Q AND 
    ( EM11V.Cy_Press1_2.Out.XR OR EM11V.Cy_Press1_2.In.Auto_R )     
	   THEN
	EM11V.Cy_Press1_2.In.Auto_V := TRUE ;
	EM11V.Cy_Block6_212.In.Auto_V := TRUE ;
    END_IF;

	//2#备胶
	IF R_Cy_Press2_1.Q AND 
	( EM11V.Cy_Press2_1.Out.XV OR EM11V.Cy_Press2_1.In.Auto_V )    
	     THEN
	EM11V.Cy_Press2_1.In.Auto_R := TRUE ;
	EM11V.Cy_Block6_411.In.Auto_R := TRUE ;	
    ELSIF R_Cy_Press2_1.Q AND 
    ( EM11V.Cy_Press2_1.Out.XR OR EM11V.Cy_Press2_1.In.Auto_R )   
	     THEN
	EM11V.Cy_Press2_1.In.Auto_V := TRUE ;
	EM11V.Cy_Block6_411.In.Auto_V := TRUE ;	
    END_IF;

	IF R_Cy_Press2_2.Q AND 
	( EM11V.Cy_Press2_2.Out.XV OR EM11V.Cy_Press2_2.In.Auto_V )    
	     THEN
	EM11V.Cy_Press2_2.In.Auto_R := TRUE ;
	EM11V.Cy_Block6_412.In.Auto_R := TRUE ;	
    ELSIF R_Cy_Press2_2.Q AND 
    ( EM11V.Cy_Press2_2.Out.XR OR EM11V.Cy_Press2_2.In.Auto_R )   
	     THEN
	EM11V.Cy_Press2_2.In.Auto_V := TRUE ;
	EM11V.Cy_Block6_412.In.Auto_V := TRUE ;	
    END_IF;
END_IF ;

//手动
IF NOT  MyStatus.StatusAuto THEN
	//1#备胶
	IF R_Cy_Press1_1.Q AND 
	( EM11V.Cy_Press1_1.Out.XV OR EM11V.Cy_Press1_1.In.Manual_V )      
	    THEN
	EM11V.Cy_Press1_1.In.Manual_R := TRUE ;
	EM11V.Cy_Block6_211.In.Manual_R := TRUE ;
    ELSIF R_Cy_Press1_1.Q AND 
    ( EM11V.Cy_Press1_1.Out.XR OR EM11V.Cy_Press1_1.In.Manual_R )     
	    THEN
	EM11V.Cy_Press1_1.In.Manual_V := TRUE ;
	EM11V.Cy_Block6_211.In.Manual_V := TRUE ;
    END_IF;

	IF R_Cy_Press1_2.Q AND 
	( EM11V.Cy_Press1_2.Out.XV OR EM11V.Cy_Press1_2.In.Manual_V )      
	    THEN
	EM11V.Cy_Press1_2.In.Manual_R := TRUE ;
	EM11V.Cy_Block6_212.In.Manual_R := TRUE ;
    ELSIF R_Cy_Press1_2.Q AND 
    ( EM11V.Cy_Press1_2.Out.XR OR EM11V.Cy_Press1_2.In.Manual_R )    
	    THEN
	EM11V.Cy_Press1_2.In.Manual_V := TRUE ;
	EM11V.Cy_Block6_212.In.Manual_V := TRUE ;
    END_IF;

	//2#备胶
	IF R_Cy_Press2_1.Q AND 
	( EM11V.Cy_Press2_1.Out.XV OR EM11V.Cy_Press2_1.In.Manual_V )     
	   THEN
	EM11V.Cy_Press2_1.In.Manual_R := TRUE ;
	EM11V.Cy_Block6_411.In.Manual_R := TRUE ;
    ELSIF R_Cy_Press2_1.Q AND 
    ( EM11V.Cy_Press2_1.Out.XR OR EM11V.Cy_Press2_1.In.Manual_R )    
	   THEN
	EM11V.Cy_Press2_1.In.Manual_V := TRUE ;
	EM11V.Cy_Block6_411.In.Manual_V := TRUE ;
    END_IF;

	IF R_Cy_Press2_2.Q AND 
	( EM11V.Cy_Press2_2.Out.XV OR EM11V.Cy_Press2_2.In.Manual_V )     
	   THEN
	EM11V.Cy_Press2_2.In.Manual_R := TRUE ;
	EM11V.Cy_Block6_412.In.Manual_R := TRUE ;
    ELSIF R_Cy_Press2_2.Q AND 
    ( EM11V.Cy_Press2_2.Out.XR OR EM11V.Cy_Press2_2.In.Manual_R )     
	   THEN
	EM11V.Cy_Press2_2.In.Manual_V := TRUE ;
	EM11V.Cy_Block6_412.In.Manual_V := TRUE ;
    END_IF;
END_IF ;






//HMI_Button[11,0]   1#备胶更换确认
//HMI_Button[11,1]   2#备胶更换确认
//HMI_Button[11,2]   //手动一键拉胶
//HMI_Button[11,3]   //手动一键取胶 
//HMI_Button[11,4]   //手动一键贴胶

//HMI_GlueProcessCheck.PullPos[0]  //手动一键拉胶
//HMI_GlueProcessCheck.GetGulePos[0]   //手动一键取胶
//HMI_GlueProcessCheck.PastePos[0]      //手动一键贴胶


/////////////手动一键拉胶/////////
IF 	HMI_Button[11,2]
	AND Act.Act03_Manual[11]
	AND EM11V.Axis_Y1.Out.Homed
	AND EM11V.Axis_Y2.Out.Homed
	AND EM11V.Axis_X2.Out.Homed
	AND NOT MyStation.EM[11].IsAlarm
THEN
	CASE HMI_GlueProcessCheck.PullPosStep[0] OF
		0://开胶气缸推出
			EM11V.Cy_Open1_1.In.Manual_V	:= EM11V.Axis_X2.Out.PosDone[1];
			EM11V.Cy_Open1_2.In.Manual_V	:= EM11V.Axis_X2.Out.PosDone[1];
			EM11V.Cy_Open2_1.In.Manual_V	:= EM11V.Axis_X2.Out.PosDone[2];
			EM11V.Cy_Open2_2.In.Manual_V	:= EM11V.Axis_X2.Out.PosDone[2];
			IF (EM11V.Cy_Open1_1.Out.XV
				AND EM11V.Cy_Open1_2.Out.XV)
			//	OR NOT EM11V.Axis_X2.Out.PosDone[1])
				AND (EM11V.Cy_Open2_1.Out.XV
				AND EM11V.Cy_Open2_2.Out.XV)
			//	OR NOT EM11V.Axis_X2.Out.PosDone[2])
			THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 10;
				EM11V.Cy_Open1_1.In.Manual_V	:= FALSE;
				EM11V.Cy_Open1_2.In.Manual_V	:= FALSE;
				EM11V.Cy_Open2_1.In.Manual_V	:= FALSE;
				EM11V.Cy_Open2_2.In.Manual_V	:= FALSE;
			END_IF
		10://开胶气缸回退，压胶气缸压紧、切刀气缸回退、辅助气缸回退
			EM11V.Cy_Open1_1.In.Manual_R	:= TRUE;
			EM11V.Cy_Open1_2.In.Manual_R	:= TRUE;
			EM11V.Cy_Open2_1.In.Manual_R	:= TRUE;
			EM11V.Cy_Open2_2.In.Manual_R	:= TRUE;
			EM11V.Cy_Press1_1.In.Manual_V	:= TRUE;
			EM11V.Cy_Press1_2.In.Manual_V	:= TRUE;
			EM11V.Cy_Press2_1.In.Manual_V	:= TRUE;
			EM11V.Cy_Press2_2.In.Manual_V	:= TRUE;
			EM11V.Cy_Cut1.In.Manual_R		:= TRUE;
			EM11V.Cy_Cut2.In.Manual_R		:= TRUE;
			EM11V.Cy_Up1.In.Manual_R		:= TRUE;
			EM11V.Cy_Up2.In.Manual_R		:= TRUE;
			EM11V.Cy_Clamp1.In.Manual_R		:= TRUE;
			EM11V.Cy_Clamp2.In.Manual_R		:= TRUE;
			IF EM11V.Cy_Open1_1.Out.XR
				AND EM11V.Cy_Open1_2.Out.XR
				AND EM11V.Cy_Open2_1.Out.XR
				AND EM11V.Cy_Open2_2.Out.XR
				AND EM11V.Cy_Press1_1.Out.XV
				AND EM11V.Cy_Press1_2.Out.XV
				AND EM11V.Cy_Press2_1.Out.XV
				AND EM11V.Cy_Press2_2.Out.XV
				AND EM11V.Cy_Cut1.Out.XR
				AND EM11V.Cy_Cut2.Out.XR
				AND EM11V.Cy_Up1.Out.XR
				AND EM11V.Cy_Up2.Out.XR
				AND EM11V.Cy_Clamp1.Out.XR
				AND EM11V.Cy_Clamp2.Out.XR
			THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 20;
				EM11V.Cy_Open1_1.In.Manual_R	:= FALSE;
				EM11V.Cy_Open1_2.In.Manual_R	:= FALSE;
				EM11V.Cy_Open2_1.In.Manual_R	:= FALSE;
				EM11V.Cy_Open2_2.In.Manual_R	:= FALSE;
				EM11V.Cy_Press1_1.In.Manual_V	:= FALSE;
				EM11V.Cy_Press1_2.In.Manual_V	:= FALSE;
				EM11V.Cy_Press2_1.In.Manual_V	:= FALSE;
				EM11V.Cy_Press2_2.In.Manual_V	:= FALSE;
				EM11V.Cy_Cut1.In.Manual_R		:= FALSE;
				EM11V.Cy_Cut2.In.Manual_R		:= FALSE;
				EM11V.Cy_Up1.In.Manual_R		:= FALSE;
				EM11V.Cy_Up2.In.Manual_R		:= FALSE;
				EM11V.Cy_Clamp1.In.Manual_R		:= FALSE;
				EM11V.Cy_Clamp2.In.Manual_R		:= FALSE;
			EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= TRUE;
			END_IF
		20://取胶Z轴到安全位
			EM11V.Axis_Z1.In.Location_Move_HMI		:= TRUE;
		
			IF EM11V.Axis_Z1.Out.PosDone[1] THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 30;
				EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= TRUE;
			END_IF
		30://取胶Y轴到贴胶位
			EM11V.Axis_Y3.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Y3.Out.PosDone[2] THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 40;
				EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_Y3.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Y1.In.Location_Select_HMI[1]	:= TRUE;
			EM11V.Axis_Y2.In.Location_Select_HMI[1]	:= TRUE;
			END_IF
		40://拉胶Y轴到取胶位
			EM11V.Axis_Y1.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_Y2.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Y1.Out.PosDone[1] 
				AND EM11V.Axis_Y2.Out.PosDone[1] 
			THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 50;
				EM11V.Axis_Y1.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Y2.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Y1.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_Y2.In.Location_Move_HMI		:= FALSE;
			END_IF
		50://拉胶夹爪气缸夹紧
			EM11V.Cy_Clamp1.In.Manual_V	:= TRUE;
			EM11V.Cy_Clamp2.In.Manual_V	:= TRUE;
			IF EM11V.Cy_Clamp1.Out.XV
				AND EM11V.Cy_Clamp2.Out.XV
			THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 60;
				EM11V.Cy_Clamp1.In.Manual_V	:= FALSE;
				EM11V.Cy_Clamp2.In.Manual_V	:= FALSE;
			END_IF
		60://压胶气缸回退
			EM11V.Cy_Press1_1.In.Manual_R	:= EM11V.Axis_X2.Out.PosDone[1];
			EM11V.Cy_Press1_2.In.Manual_R	:= EM11V.Axis_X2.Out.PosDone[1];
			EM11V.Cy_Press2_1.In.Manual_R	:= EM11V.Axis_X2.Out.PosDone[2];
			EM11V.Cy_Press2_2.In.Manual_R	:= EM11V.Axis_X2.Out.PosDone[2];
			IF (EM11V.Cy_Press1_1.Out.XR
				AND EM11V.Cy_Press1_2.Out.XR
				OR NOT EM11V.Axis_X2.Out.PosDone[1])
				OR (EM11V.Cy_Press2_1.Out.XR
				AND EM11V.Cy_Press2_2.Out.XR
				OR NOT EM11V.Axis_X2.Out.PosDone[2])
			THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 70;
				EM11V.Cy_Press1_1.In.Manual_R	:= FALSE;
				EM11V.Cy_Press1_2.In.Manual_R	:= FALSE;
				EM11V.Cy_Press2_1.In.Manual_R	:= FALSE;
				EM11V.Cy_Press2_2.In.Manual_R	:= FALSE;
			EM11V.Axis_Y1.In.Location_Select_HMI[2]	:= TRUE;
			EM11V.Axis_Y2.In.Location_Select_HMI[2]	:= TRUE;
			END_IF
		70://拉胶轴到拉胶位
			EM11V.Axis_Y1.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_Y2.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Y1.Out.PosDone[2] 
				AND EM11V.Axis_Y2.Out.PosDone[2] 
			THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 80;
				EM11V.Axis_Y1.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_Y2.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_Y1.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_Y2.In.Location_Move_HMI		:= FALSE;
			END_IF
		80://压胶气缸夹紧
			EM11V.Cy_Press1_1.In.Manual_V	:= EM11V.Axis_X2.Out.PosDone[1];
			EM11V.Cy_Press1_2.In.Manual_V	:= EM11V.Axis_X2.Out.PosDone[1];
			EM11V.Cy_Press2_1.In.Manual_V	:= EM11V.Axis_X2.Out.PosDone[2];
			EM11V.Cy_Press2_2.In.Manual_V	:= EM11V.Axis_X2.Out.PosDone[2];
			IF (EM11V.Cy_Press1_1.Out.XV
				AND EM11V.Cy_Press1_2.Out.XV
				OR NOT EM11V.Axis_X2.Out.PosDone[1])
				OR (EM11V.Cy_Press2_1.Out.XV
				AND EM11V.Cy_Press2_2.Out.XV
				OR NOT EM11V.Axis_X2.Out.PosDone[2])
			THEN
				HMI_GlueProcessCheck.PullPosStep[0]	:= 0;
				HMI_Button[11,2]		:= FALSE;
				EM11V.Cy_Press1_1.In.Manual_V	:= FALSE;
				EM11V.Cy_Press1_2.In.Manual_V	:= FALSE;
				EM11V.Cy_Press2_1.In.Manual_V	:= FALSE;
				EM11V.Cy_Press2_2.In.Manual_V	:= FALSE;
			END_IF		
	END_CASE	
ELSIF NOT HMI_Button[11,2]
	OR NOT  Act.Act03_Manual[11]
	OR NOT  EM11V.Axis_Y1.Out.Homed
	OR NOT  EM11V.Axis_Y2.Out.Homed
	OR NOT  EM11V.Axis_X2.Out.Homed
	OR MyStation.EM[11].IsAlarm
THEN 
	HMI_Button[11,2] := FALSE;
	HMI_GlueProcessCheck.PullPosStep[0] := 0;
END_IF
PullPos_F[0](CLK:= HMI_Button[11,2]  );
IF PullPos_F[0].Q THEN
	
		EM11V.Axis_Y1.In.Location_Select_HMI[2]	:= FALSE;
		EM11V.Axis_Y2.In.Location_Select_HMI[2]	:= FALSE;
		EM11V.Axis_Y1.In.Location_Select_HMI[1]	:= FALSE;
		EM11V.Axis_Y2.In.Location_Select_HMI[1]	:= FALSE;
		EM11V.Axis_Y1.In.Location_Move_HMI		:= FALSE;
		EM11V.Axis_Y2.In.Location_Move_HMI		:= FALSE;
		EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= FALSE;
		EM11V.Axis_Y3.In.Location_Move_HMI		:= FALSE;
		EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= FALSE;
		EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
END_IF


/////////////手动一键取胶/////////

IF HMI_Button[11,3]
	AND Act.Act03_Manual[11]
	AND EM11V.Axis_Y1.Out.Homed
	AND EM11V.Axis_Y2.Out.Homed
	AND EM11V.Axis_Y3.Out.Homed
	AND EM11V.Axis_X1.Out.Homed
	AND EM11V.Axis_Z1.Out.Homed
	AND NOT MyStation.EM[11].IsAlarm
THEN
	CASE HMI_GlueProcessCheck.GetGulePosStep[0] OF
		0://真空断开
			EM11V.Va_Glue1.In.Manual_V	:= TRUE;
			EM11V.Va_Glue1.In.Manual_V	:= TRUE;
			IF NOT EM11V.Va_Glue1.Out.XR
				AND NOT  EM11V.Va_Glue1.Out.XR
			THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 10;
				EM11V.Va_Glue1.In.Manual_V	:= FALSE;
				EM11V.Va_Glue1.In.Manual_V	:= FALSE;
			EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= TRUE;
			END_IF	
		10://取胶Z轴到安全位
			EM11V.Axis_Z1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Z1.Out.PosDone[1] THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 20;
				EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= TRUE;
			END_IF
		20://取胶Y轴到贴胶位
			EM11V.Axis_Y3.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Y3.Out.PosDone[2] THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 30;
				EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_Y3.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_R1.In.Location_Select_HMI[1]	:= TRUE;
			EM11V.Axis_R2.In.Location_Select_HMI[1]	:= TRUE;
			EM11V.Axis_X1.In.Location_Select_HMI[1]	:= TRUE;
			END_IF
		30://旋转R轴到取胶位  变距X轴到取胶位
			EM11V.Axis_R1.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_R2.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_X1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_R1.Out.PosDone[1] 
				AND EM11V.Axis_R2.Out.PosDone[1] 
				AND EM11V.Axis_X1.Out.PosDone[1] 
			THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 40;
				EM11V.Axis_R1.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_R2.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_X1.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_R1.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_R2.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_X1.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Y3.In.Location_Select_HMI[1]	:= TRUE;
			END_IF
		40://取胶Y轴到取胶位
			EM11V.Axis_Y3.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Y3.Out.PosDone[1] THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 50;
				EM11V.Axis_Y3.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Y3.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Z1.In.Location_Select_HMI[2]	:= TRUE;
			END_IF
		50://取胶Z轴到取胶位
			EM11V.Axis_Z1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Z1.Out.PosDone[2] THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 60;
				EM11V.Axis_Z1.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
			END_IF
		60://真空打开 辅助气缸顶升
			EM11V.Va_Glue1.In.Manual_R	:= TRUE;
			EM11V.Va_Glue2.In.Manual_R	:= TRUE;
			EM11V.Cy_Up1.In.Manual_V	:= TRUE;
			EM11V.Cy_Up2.In.Manual_V	:= TRUE;
			IF EM11V.Va_Glue1.Out.XR
				AND EM11V.Va_Glue2.Out.XR
				AND EM11V.Cy_Up1.Out.XV
				AND EM11V.Cy_Up2.Out.XV
			THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 70;
				EM11V.Va_Glue1.In.Manual_R	:= FALSE;
				EM11V.Va_Glue2.In.Manual_R	:= FALSE;
				EM11V.Cy_Up1.In.Manual_V	:= FALSE;
				EM11V.Cy_Up1.In.Manual_V	:= FALSE;
			END_IF
		70://切刀气缸伸出
			EM11V.Cy_Cut1.In.Manual_V	:= TRUE;
			EM11V.Cy_Cut2.In.Manual_V	:= TRUE;
			IF EM11V.Cy_Cut1.Out.XV
				AND EM11V.Cy_Cut2.Out.XV
			THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 80;
				EM11V.Cy_Cut1.In.Manual_V	:= FALSE;
				EM11V.Cy_Cut2.In.Manual_V	:= FALSE;
			END_IF
		80://切刀气缸回退 辅助气缸回退 夹爪气缸打开
			EM11V.Cy_Cut1.In.Manual_R	:= TRUE;
			EM11V.Cy_Cut2.In.Manual_R	:= TRUE;
			EM11V.Cy_Up1.In.Manual_R	:= TRUE;
			EM11V.Cy_Up2.In.Manual_R	:= TRUE;
			EM11V.Cy_Clamp1.In.Manual_R	:= TRUE;
			EM11V.Cy_Clamp2.In.Manual_R	:= TRUE;	
			IF EM11V.Cy_Cut1.Out.XR
				AND EM11V.Cy_Cut2.Out.XR
				AND EM11V.Cy_Up1.Out.XR
				AND EM11V.Cy_Up2.Out.XR
				AND EM11V.Cy_Clamp1.Out.XR
				AND EM11V.Cy_Clamp2.Out.XR
			THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 90;
			EM11V.Axis_Y1.In.Location_Select_HMI[3]	:= TRUE;
			EM11V.Axis_Y2.In.Location_Select_HMI[3]	:= TRUE;
			END_IF		
		90://拉胶Y轴到避让位
			EM11V.Axis_Y1.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_Y2.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Y1.Out.PosDone[3] 
				AND EM11V.Axis_Y2.Out.PosDone[3] 
			THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 100;
				EM11V.Axis_Y1.In.Location_Select_HMI[3]	:= FALSE;
				EM11V.Axis_Y2.In.Location_Select_HMI[3]	:= FALSE;
				EM11V.Axis_Y1.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_Y2.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= TRUE;
			END_IF
		100://取胶Z轴到安全位
			EM11V.Axis_Z1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Z1.Out.PosDone[1] THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 110;
				EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= TRUE;
			END_IF
		110://取胶Y轴到贴胶位
			EM11V.Axis_Y3.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Y3.Out.PosDone[2] THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 120;
				EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_Y3.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_R1.In.Location_Select_HMI[2]	:= TRUE;
			EM11V.Axis_R2.In.Location_Select_HMI[2]	:= TRUE;
			EM11V.Axis_X1.In.Location_Select_HMI[2]	:= TRUE;
			END_IF
		120://旋转R轴到取胶位  变距X轴到取胶位
			EM11V.Axis_R1.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_R2.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_X1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_R1.Out.PosDone[2] 
				AND EM11V.Axis_R2.Out.PosDone[2] 
				AND EM11V.Axis_X1.Out.PosDone[2] 
			THEN
				HMI_GlueProcessCheck.GetGulePosStep[0]	:= 0;
				HMI_Button[11,3]	:= FALSE;
				EM11V.Axis_R1.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_R2.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_X1.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_R1.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_R2.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_X1.In.Location_Move_HMI		:= FALSE;
			END_IF	
	END_CASE	
ELSIF	NOT HMI_Button[11,3]
	OR NOT  Act.Act03_Manual[11]
	OR NOT  EM11V.Axis_Y1.Out.Homed
	OR NOT  EM11V.Axis_Y2.Out.Homed
	OR NOT  EM11V.Axis_Y3.Out.Homed
	OR NOT  EM11V.Axis_X1.Out.Homed
	OR NOT  EM11V.Axis_Z1.Out.Homed
	OR NOT  NOT MyStation.EM[11].IsAlarm
THEN 
	HMI_Button[11,3] := FALSE;
	HMI_GlueProcessCheck.GetGulePosStep[0] := 0;
END_IF
GetGulePos_F[0](CLK:= HMI_Button[11,3] );
IF GetGulePos_F[0].Q THEN
	EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= FALSE;
	EM11V.Axis_Z1.In.Location_Select_HMI[2]	:= FALSE;
	EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
	EM11V.Axis_Y3.In.Location_Select_HMI[1]	:= FALSE;
	EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= FALSE;
	EM11V.Axis_Y3.In.Location_Move_HMI		:= FALSE;
	EM11V.Axis_R1.In.Location_Select_HMI[2]	:= FALSE;
	EM11V.Axis_R2.In.Location_Select_HMI[2]	:= FALSE;
	EM11V.Axis_X1.In.Location_Select_HMI[2]	:= FALSE;
	EM11V.Axis_R1.In.Location_Move_HMI		:= FALSE;
	EM11V.Axis_R2.In.Location_Move_HMI		:= FALSE;
	EM11V.Axis_X1.In.Location_Move_HMI		:= FALSE;
	EM11V.Axis_Y1.In.Location_Select_HMI[3]	:= FALSE;
	EM11V.Axis_Y2.In.Location_Select_HMI[3]	:= FALSE;
	EM11V.Axis_Y1.In.Location_Move_HMI		:= FALSE;
	EM11V.Axis_Y2.In.Location_Move_HMI		:= FALSE;
END_IF



/////////////手动一键贴胶/////////

IF HMI_Button[11,4]
	AND Act.Act03_Manual[11]
	AND EM11V.Axis_Y1.Out.Homed
	AND EM11V.Axis_Y2.Out.Homed
	AND EM11V.Axis_Y3.Out.Homed
	AND EM11V.Axis_X1.Out.Homed
	AND EM11V.Axis_Z1.Out.Homed
	AND NOT MyStation.EM[11].IsAlarm
THEN
	CASE HMI_GlueProcessCheck.PastePosStep[0] OF
		0://真空断开
			EM11V.Va_Glue1.In.Manual_R	:= TRUE;
			EM11V.Va_Glue1.In.Manual_R	:= TRUE;
			IF  EM11V.Va_Glue1.Out.XR
				AND   EM11V.Va_Glue1.Out.XR
			THEN
				HMI_GlueProcessCheck.PastePosStep[0]	:= 10;
				EM11V.Va_Glue1.In.Manual_V	:= FALSE;
				EM11V.Va_Glue1.In.Manual_V	:= FALSE;
			EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= TRUE;
			END_IF	
		10://取胶Z轴到安全位
			EM11V.Axis_Z1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Z1.Out.PosDone[1] THEN
				HMI_GlueProcessCheck.PastePosStep[0]	:= 20;
				EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Y1.In.Location_Select_HMI[1]	:= TRUE;
			EM11V.Axis_Y2.In.Location_Select_HMI[1]	:= TRUE;
			EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= TRUE;
			END_IF
		20://取胶Y轴到贴胶位
			EM11V.Axis_Y1.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_Y2.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_Y3.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Y1.Out.PosDone[1]
				AND EM11V.Axis_Y2.Out.PosDone[1]
				AND EM11V.Axis_Y3.Out.PosDone[2]
			THEN
				HMI_GlueProcessCheck.PastePosStep[0]	:= 30;
			EM11V.Axis_Y1.In.Location_Select_HMI[1]	:= FALSE;
			EM11V.Axis_Y2.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Y3.In.Location_Select_HMI[2]	:= FALSE;
			EM11V.Axis_Y1.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Y2.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_Y3.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_R1.In.Location_Select_HMI[2]	:= TRUE;
			EM11V.Axis_R2.In.Location_Select_HMI[2]	:= TRUE;
			EM11V.Axis_X1.In.Location_Select_HMI[2]	:= TRUE;
			END_IF
		30://旋转R轴到取胶位  变距X轴到取胶位
			EM11V.Axis_R1.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_R2.In.Location_Move_HMI		:= TRUE;
			EM11V.Axis_X1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_R1.Out.PosDone[2] 
				AND EM11V.Axis_R2.Out.PosDone[2] 
				AND EM11V.Axis_X1.Out.PosDone[2] 
			THEN
				HMI_GlueProcessCheck.PastePosStep[0]	:= 40;
				EM11V.Axis_R1.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_R2.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_X1.In.Location_Select_HMI[2]	:= FALSE;
				EM11V.Axis_R1.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_R2.In.Location_Move_HMI		:= FALSE;
				EM11V.Axis_X1.In.Location_Move_HMI		:= FALSE;
			EM11V.Axis_Z1.In.Location_Select_HMI[3]	:= TRUE;
			END_IF
		40://取胶Z轴到取胶位
			EM11V.Axis_Z1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Z1.Out.PosDone[3] THEN
				HMI_GlueProcessCheck.PastePosStep[0]	:= 50;
				EM11V.Axis_Z1.In.Location_Select_HMI[3]	:= FALSE;
				EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
			END_IF
		50://真空打开 辅助气缸顶升
			EM11V.Va_Glue1.In.Manual_V	:= TRUE;
			EM11V.Va_Glue2.In.Manual_V	:= TRUE;
			IF NOT  EM11V.Va_Glue1.Out.XR
				AND NOT EM11V.Va_Glue2.Out.XR
			THEN
				HMI_GlueProcessCheck.PastePosStep[0]	:= 60;
				EM11V.Va_Glue1.In.Manual_V	:= FALSE;
				EM11V.Va_Glue2.In.Manual_V	:= FALSE;
			EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= TRUE;
			END_IF
		60://取胶Z轴到安全位
			EM11V.Axis_Z1.In.Location_Move_HMI		:= TRUE;
			IF EM11V.Axis_Z1.Out.PosDone[1] THEN
				HMI_GlueProcessCheck.PastePosStep[0]	:= 70;
				HMI_Button[11,4]	:= FALSE;
				EM11V.Axis_Z1.In.Location_Select_HMI[1]	:= FALSE;
				EM11V.Axis_Z1.In.Location_Move_HMI		:= FALSE;
			END_IF
	END_CASE		
ELSIF NOT  HMI_Button[11,4]
	OR NOT  Act.Act03_Manual[11]
	OR NOT  EM11V.Axis_Y1.Out.Homed
	OR NOT  EM11V.Axis_Y2.Out.Homed
	OR NOT  EM11V.Axis_Y3.Out.Homed
	OR NOT  EM11V.Axis_X1.Out.Homed
	OR NOT  EM11V.Axis_Z1.Out.Homed
	OR NOT  MyStation.EM[11].IsAlarm
THEN
	HMI_Button[11,4] :=FALSE;
	HMI_GlueProcessCheck.PastePosStep[0] := 0;
END_IF

/////////////手动一键循环/////////

IF HMI_GlueProcessCheck.AutoGlueTrigger[0]
	AND Act.Act03_Manual[11]
	AND EM11V.Axis_Y1.Out.Homed
	AND EM11V.Axis_Y2.Out.Homed
	AND EM11V.Axis_Y3.Out.Homed
	AND EM11V.Axis_X1.Out.Homed
	AND EM11V.Axis_X2.Out.Homed
	AND EM11V.Axis_Z1.Out.Homed
	AND NOT MyStation.EM[11].IsAlarm
THEN
	CASE HMI_GlueProcessCheck.AutoGlueStep[0] OF
		0://一键拉胶
			HMI_Button[11,2] := TRUE;
			IF HMI_GlueProcessCheck.PullPosStep[0] <> 0 THEN
				HMI_GlueProcessCheck.AutoGlueStep[0] := 10;
			END_IF
		10://等待拉胶完成
			IF NOT HMI_Button[11,2] THEN	
				HMI_GlueProcessCheck.AutoGlueStep[0] := 20;
			END_IF
		20://一键取胶
			HMI_Button[11,3] := TRUE;
			IF HMI_GlueProcessCheck.GetGulePosStep[0] <> 0 THEN
				HMI_GlueProcessCheck.AutoGlueStep[0] := 30;
			END_IF
		30://等待取胶完成
			IF NOT HMI_Button[11,3] THEN	
				HMI_GlueProcessCheck.AutoGlueStep[0] := 40;
			END_IF
		40://一键贴胶
			HMI_Button[11,4] := TRUE;
			IF HMI_GlueProcessCheck.PastePosStep[0] <> 0 THEN
				HMI_GlueProcessCheck.AutoGlueStep[0] := 50;
			END_IF
			
		50://等待贴胶完成
			IF NOT HMI_Button[11,4] THEN	
				HMI_GlueProcessCheck.AutoGlueStep[0] := 0;
				HMI_GlueProcessCheck.AutoGlueTrigger[0] := FALSE;
			END_IF		
	END_CASE
ELSIF NOT HMI_GlueProcessCheck.AutoGlueTrigger[0]
	OR NOT  Act.Act03_Manual[11]
	OR NOT  EM11V.Axis_Y1.Out.Homed
	OR NOT  EM11V.Axis_Y2.Out.Homed
	OR NOT  EM11V.Axis_Y3.Out.Homed
	OR NOT  EM11V.Axis_X1.Out.Homed
	OR NOT  EM11V.Axis_X2.Out.Homed
	OR NOT  EM11V.Axis_Z1.Out.Homed
	OR   MyStation.EM[11].IsAlarm
THEN 
HMI_GlueProcessCheck.AutoGlueStep[0] := 0;
				HMI_GlueProcessCheck.AutoGlueTrigger[0] := FALSE;
END_IF

data.STCode:
FOR StationSum := 0 TO StationNum BY 1 DO
	Act.Act05_Auto_Station[EMNumber,StationSum] := Act.Act05_Auto[EMNumber] AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding;
END_FOR;

ST.xhtml:
IF Act.Act07_AxisCall_FB[13] THEN //轴原点确认 MyStation.EM[13].ServoHomed:=(EM13V.Axis_X1.Out.Homed OR MyStation.EMStation[13,0].Shielding) AND (EM13V.Axis_X2.Out.Homed OR MyStation.EMStation[13,0].Shielding) AND (EM13V.Axis_Z1.Out.Homed OR MyStation.EMStation[13,0].Shielding) AND (EM13V.Axis_R1.Out.Homed OR MyStation.EMStation[13,0].Shielding) AND (EM13V.Axis_Z2.Out.Homed OR MyStation.EMStation[13,0].Shielding) AND (EM13V.Axis_Z3.Out.Homed OR MyStation.EMStation[13,1].Shielding) AND (EM13V.Axis_Z4.Out.Homed OR MyStation.EMStation[13,1].Shielding) AND (EM13V.Axis_Y1.Out.Homed OR MyStation.EMStation[13,0].Shielding);
(*----------------回原点方式----------需要按实际更改 1: HomingMode:=HMC_HOMING_MODE.PassHomeSwHomeSwTurn 附近避让 / 近原点输入 OFF 2: HomingMode:=HMC_HOMING_MODE.InHomeSwHomeSwTurn 附近避让 / 近原点输入 ON 3: HomingMode:=HMC_HOMING_MODE.PassHomeSwHome; 近原点输入 OFF 4: HomingMode:=HMC_HOMING_MODE.InHomeSw; 近原点输入 ON 5: HomingMode:=HMC_HOMING_MODE.PassLimitSw; 极限输入 OFF-----------------------------增量式轴，限位感应器回原使用 (升降Z轴使用) 6: HomingMode:=HMC_HOMING_MODE.HomeSwMaskDistanceHomeSwTurn 附近避让 原点输入屏蔽距离 7: HomingMode:=HMC_HOMING_MODE.OnlyLimit; 仅极限输入 8: HomingMode:=HMC_HOMING_MODE.HomeSwHoldTimeHomeSwTurn; 附近避让 接触时间---------------增量式轴，直线电机 9: HomingMode:=HMC_HOMING_MODE.ZeroSw; 无近原点输入 接触原点输入-----------增量式DD马达，回原使用 12: HomingMode:=HMC_HOMING_MODE.ZeroPositionPreset; 原点预设---------------------------------绝对式轴，无回原动作使用
----------------原点复位开始方向---------- 0: StartDir := MC_DIRECTION.positive 正方向 1: StartDir := MC_DIRECTION.negative 负方向
------检测到原点停止方向---------- 0: Home_SwDir := MC_DIRECTION.positive 正方向 1: Home_SwDir := MC_DIRECTION.negative 负方向
-------原点输入信号---------- 0: HomeInput := HMC_ZERO_SIGNAL.ZPhase 使用 Z 相输入 1: HomeInput := HMC_ZERO_SIGNAL.ExternalSignal 使用外部原点输入
-------编码器类型设置---------- -------类型预设 EC.EM2.AxisIn[0].EncoderSelect:= 0:增量式 （默认），1:绝对式 -------原点偏移--------无此需求可省略以下项 -------回原偏移 Home_Offest:=REAL#XXX;默认0:不偏移。值不等于0时，自动启动偏移功能 // (正值往正方向偏移，负值往负方向偏移） -------回原后设定位置 Home_SetPos:=REAL#XXX;默认0:不改变。偏移完成后,将当前位置设为0值 // 默认使用7号模式回原 *) // 'NOP'
IF MyStatus.StatusManual THEN EM13V.Axis_X1.In.AbsModel := ARRAY32_FALSE; EM13V.Axis_X2.In.AbsModel := ARRAY32_FALSE; ELSE
EM13V.Axis_X1.In.AbsModel := ARRAY32_TRUE; EM13V.Axis_X2.In.AbsModel := ARRAY32_TRUE; END_IF
HMI_RecipeData.EM13.Axis_X2.Location_Speed[1] := HMI_RecipeData.EM13.Axis_X1.Location_Speed[1]; HMI_RecipeData.EM13.Axis_X2.Location_Acc := HMI_RecipeData.EM13.Axis_X1.Location_Acc; HMI_RecipeData.EM13.Axis_X2.Location_Dec := HMI_RecipeData.EM13.Axis_X1.Location_Dec;
HMI_RecipeData.EM13.Axis_X2.Location_Postion[3]:=HMI_RecipeData.EM13.Axis_X2.Location_Postion[1];
(********************Axis_X11#电芯下料X轴********************) EM13V.Axis_X1.In.Home_Mode :=TRUE;//FALES基础回原模式，TRUE带参回原 HMI_RecipeData.EM13.Axis_X1.Home_Offest :=0;//回原偏移 HMI_RecipeData.EM13.Axis_X1.Home_SetPos :=0;//回原完成后设定位置 HMI_RecipeData.EM13.Axis_X1.Home_Mode :=7;//回原模式(预设：按实际需求更改) HMI_RecipeData.EM13.Axis_X1.Home_StartDir :=1;//回原方向选择 0:正方向 1:负方向 HMI_RecipeData.EM13.Axis_X1.Home_SwDir :=0;//原点检测方向 0:正方向 1:负方向 HMI_RecipeData.EM13.Axis_X1.Home_Input :=1;//回原原点输入方式 0:Z相(默认),1:外部原点 HMI_RecipeData.EM13.Axis_X1.Location_SpeedSwitch :=FALSE ; HMI_RecipeData.EM13.Axis_X1.Accuracy[0] := 0.4;//手自动冲突范围 HMI_RecipeData.EM13.Axis_X1.Accuracy[3] := 0.4;//大范围到位 EM13V.Axis_X1.In.EncoderSelect :=0;//编码器类型选择 0:增量式 （默认），1:绝对式
Axis_SV49( Enable :=TRUE,//输入使能 VelFactor :=HMI_RecipeData.GeneralOverride, //整机倍率 Offline :=Catl_HMI_Status, //HMI在线状态 FunSimulation :=FALSE, //仿真开启 Axis_Map :=AxisSV49, //轴变量 Axis_Drive := SV49,//驱动器 Status :=Act.Act10_Call_Status[13,0], //状态机 Axis_In :=EM13V.Axis_X1.In, //轴控制指令 Axis_Out :=EM13V.Axis_X1.Out, //轴状态 Axis_P :=HMI_RecipeData.EM13.Axis_X1, //轴参数 Axis_Sim :=EM13V.Axis_X1.SimulateVar//轴仿真参数 );
(********************Axis_X22#电芯下料X轴********************) EM13V.Axis_X2.In.Home_Mode :=TRUE;//FALES基础回原模式，TRUE带参回原 HMI_RecipeData.EM13.Axis_X2.Home_Offest :=0;//回原偏移 HMI_RecipeData.EM13.Axis_X2.Home_SetPos :=0;//回原完成后设定位置 HMI_RecipeData.EM13.Axis_X2.Home_Mode :=7;//回原模式(预设：按实际需求更改) HMI_RecipeData.EM13.Axis_X2.Home_StartDir :=1;//回原方向选择 0:正方向 1:负方向 HMI_RecipeData.EM13.Axis_X2.Home_SwDir :=0;//原点检测方向 0:正方向 1:负方向 HMI_RecipeData.EM13.Axis_X2.Home_Input :=1;//回原原点输入方式 0:Z相(默认),1:外部原点 HMI_RecipeData.EM13.Axis_X2.Location_SpeedSwitch :=FALSE ; HMI_RecipeData.EM13.Axis_X2.Accuracy[0] := 0.4;//手自动冲突范围 HMI_RecipeData.EM13.Axis_X2.Accuracy[3] := 0.4;//大范围到位 EM13V.Axis_X2.In.EncoderSelect :=0;//编码器类型选择 0:增量式 （默认），1:绝对式
