(********************Axis_Y1 SV11_电芯二次定位夹爪Y轴********************) Axis_SV11( AxisName :=STRING_TO_WSTRING('SV11_电芯二次定位夹爪Y轴') ,//轴名称, Axis_REF :=AxisSV11 ,//轴 StrToUnicodeEx :=StrToUnicodeEx ,//字符转Unicode的单周期变量 Reset :=MyInput.Reset_Input ,//复位 Auto :=Act.Act05_Auto_Station[5,1] OR Act.Act04_Init_Station[5,1] ,//自动 Manual :=Act.Act03_Manual[5] ,//手动 Aborting :=MyStation.EM[5].Stopping //报警立停 AND NOT MyStation.EM[5].Resting OR NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor , Pause :=FALSE ,//阻挡暂停(解除阻挡后继续动作，只对绝对定位有效) bConflictEnable :=TRUE ,//手自动冲突使能 rScope :=0.3 ,//手自动冲突波动范围 bConflictState :=Act.Act05_Auto_Station[5,1] , InitDone :=MyStation.EMStation[5,1].ResetComplete ,//初始化完成 Popups :=HMI_EQ.ConflictPopups , Parameter :=HMI_RecipeData.EM05.Axis_Y1 ,//轴参数结构体 GeneralOverride :=HMI_RecipeData.GeneralOverride , In :=EM05VA.Axis_Y1.In ,//轴输入结构体 H_In :=EM05H_Axis[1].H_In , H_Out :=EM05H_Axis[1].H_Out ,//轴触摸屏输出结构体 Out =>EM05VA.Axis_Y1.Out ,//轴输出结构体 ErrOut =>EM05VA.Axis_Y1.ErrOut ,//轴错误结构体 AbsAxis :=FALSE ,//增量式轴为FASLE,绝对式轴为TRUE, Input_6010 :=SV11_Input_6010 , Ready_6011 := SV11_Ready_6011 , Actpos_6020 :=SV11_Actpos_6020 , ActVelo_6021 := SV11_ActVelo_6021 , ActTorque_6022 := SV11_ActTorque_6022 , DriverAlarm1_6030_01 := SV11_DriverAlarm1_6030_01 , DriverAlarm2_6030_02 := SV11_DriverAlarm2_6030_02 , DriverAlarm3_6030_03 := SV11_DriverAlarm3_6030_03 , DriverAlarm4_6030_04 :=SV11_DriverAlarm4_6030_04 , Output_7010 =>SV11_Output_7010 , ControlWord_7011 =>SV11_ControlWord_7011 , StartFlag_7012 =>SV11_StartFlag_7012 , OperationMode_7020 =>SV11_OperationMode_7020 , Speed_7021 =>SV11_Speed_7021 , Position_7022 =>SV11_Position_7022 , Acc_7023 =>SV11_Acc_7023 , Dec_7024 =>SV11_Dec_7024 , HMI_Page_Input :=191 ,//在触摸屏操作的页面 HMI_ChangePageExecute :=HMI_SearshPage=1 //除UM外，INT类型的轴编号 AND HMI_ChangePage_Enable ,//轴快速查找触发 HMI_Page_Output :=HMI_ChangePage[0], // 快速跳转到目标页面 SimulateVar :=EM05VA.Axis_Y1.SimulateVar ,// 轴仿真变量 Simulate :=FALSE //轴仿真变量 );
(********************CQ1_循环线磁驱********************) IF Act.Act07_AxisCall_FB[5] THEN
HMI_RecipeData.EM05.Golytec.TrayTotalNo:=10;//总动子数 HMI_RecipeData.EM05.Golytec.MaxCarNo:=10;//最大的动子编号 HMI_RecipeData.EM05.Golytec.StationNoTotal:=10;//总工位数 HMI_RecipeData.EM05.Golytec.GlobalVelocityMax:=2000;//自动速度最大值
HMI_MaintenanceMode[0]:= MyStation.MaintenanceMode ; HMI_MaintenanceMode[1]:= MyStatus.StatusManual ; HMI_MaintenanceMode[2]:= SafetyController.SafetyDoorSum; HMI_MaintenanceMode[3]:= HMI_Button[5,21];
FB_Golytec.DS_Stop:=MyStation.SafetyDoor; FB_Golytec( EmgStop := FALSE , Reset := MyInput.Reset_Input ,// 复位 Auto := Act.Act05_Auto[5] , // 自动 Hmx_Manual := Act.Act03_Manual[5] ,// 手动 HMI_MaintenanceMode := HMI_MaintenanceMode ,// 手动、有安全门信号 释放权限 Aborting := MyStation.EM[0].Stopping AND NOT MyStation.EM[5].Resting OR NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor , InitDone := MyStation.EM[5].ResetComplete ,// 初始化完成 Parameter := HMI_RecipeData.EM05.Golytec , GeneralOverride := HMI_RecipeData.GeneralOverride ,// 整机速率 In := EM05V.Golytec.In , Out => EM05V.Golytec.Out , H_In := EM05H_Golytec.H_In , H_Out := EM05H_Golytec.H_Out , ErrOut => EM05V.Golytec.ErrOut ,// 程序错误 GolytecInputToPLC :=EM05V.GolytecInput , PLCOutputToGolytec :=EM05V.GolytecOutput );
//限制速度 HMI_RecipeData.EM05.Golytec.GlobalVelocityMax:=2000;
IF MyStation.EM[5].ResetComplete AND NOT EM05V.Golytec.Out.Inited THEN MyStation.EMStation[5,0].ResetComplete:=FALSE; MyStation.EM[5].ResetComplete:=FALSE; END_IF; //回到上次位，TRUE是不启用 EM05H_Golytec.H_In.ToLastPos:=TRUE;
END_IF;
END_IF;
