	IF HMI_RecipeData.EM08.Axis_X1.Home_Speed >= 5 AND MyStatus.StatusManual THEN //回原速度
		HMI_RecipeData.EM08.Axis_X1.Home_Speed	:=	10 ; 	
	ELSIF HMI_RecipeData.EM08.Axis_X1.Home_Speed >= 5 AND MyStatus.StatusAuto THEN //回原速度
		HMI_RecipeData.EM08.Axis_X1.Home_Speed	:=	5  ; 	
	END_IF;

