IF Act.Act07_AxisCall_FB[7] THEN //轴原点确认 MyStation.EM[7].ServoHomed:=EM07V.Axis_Z1.Out.Homed AND EM07V.Axis_R1.Out.Homed AND EM07V.Axis_X1.Out.Homed;
IF MyStatus.StatusManual THEN EM07V.Axis_X1.In.AbsModel := ARRAY32_FALSE; ELSE
EM07V.Axis_X1.In.AbsModel := ARRAY32_TRUE; END_IF (*----------------回原点方式----------需要按实际更改 1: HomingMode:=HMC_HOMING_MODE.PassHomeSwHomeSwTurn 附近避让 / 近原点输入 OFF 2: HomingMode:=HMC_HOMING_MODE.InHomeSwHomeSwTurn 附近避让 / 近原点输入 ON 3: HomingMode:=HMC_HOMING_MODE.PassHomeSwHome; 近原点输入 OFF 4: HomingMode:=HMC_HOMING_MODE.InHomeSw; 近原点输入 ON 5: HomingMode:=HMC_HOMING_MODE.PassLimitSw; 极限输入 OFF-----------------------------增量式轴，限位感应器回原使用 (升降Z轴使用) 6: HomingMode:=HMC_HOMING_MODE.HomeSwMaskDistanceHomeSwTurn 附近避让 原点输入屏蔽距离 7: HomingMode:=HMC_HOMING_MODE.OnlyLimit; 仅极限输入 8: HomingMode:=HMC_HOMING_MODE.HomeSwHoldTimeHomeSwTurn; 附近避让 接触时间---------------增量式轴，直线电机 9: HomingMode:=HMC_HOMING_MODE.ZeroSw; 无近原点输入 接触原点输入-----------增量式DD马达，回原使用 12: HomingMode:=HMC_HOMING_MODE.ZeroPositionPreset; 原点预设---------------------------------绝对式轴，无回原动作使用
----------------原点复位开始方向---------- 0: StartDir := MC_DIRECTION.positive 正方向 1: StartDir := MC_DIRECTION.negative 负方向
------检测到原点停止方向---------- 0: Home_SwDir := MC_DIRECTION.positive 正方向 1: Home_SwDir := MC_DIRECTION.negative 负方向
-------原点输入信号---------- 0: HomeInput := HMC_ZERO_SIGNAL.ZPhase 使用 Z 相输入 1: HomeInput := HMC_ZERO_SIGNAL.ExternalSignal 使用外部原点输入
-------编码器类型设置---------- -------类型预设 EC.EM2.AxisIn[0].EncoderSelect:= 0:增量式 （默认），1:绝对式 -------原点偏移--------无此需求可省略以下项 -------回原偏移 Home_Offest:=REAL#XXX;默认0:不偏移。值不等于0时，自动启动偏移功能 // (正值往正方向偏移，负值往负方向偏移） -------回原后设定位置 Home_SetPos:=REAL#XXX;默认0:不改变。偏移完成后,将当前位置设为0值 // 默认使用7号模式回原 *) // 'NOP' EM07V.Axis_Z1.In.FallbackEnabled := TRUE; EM07V.Axis_Z1.In.Crash_Safe := TRUE; HMI_RecipeData.EM07.Axis_Z1.Flexibility_Back := 50; HMI_RecipeData.EM07.Axis_Z1.AbsPosBackVal := 1; EM07V.Axis_Z1.In.Crash_Trigger := ( NOT EM07V.Sen_Avoid1.Out.Filtered_Q AND NOT HMI_Function_Enable[7,48] ) OR ( NOT EM07V.Sen_Avoid2.Out.Filtered_Q AND NOT HMI_Function_Enable[7,47] ) OR ( NOT EM07V.Sen_Avoid3.Out.Filtered_Q AND NOT HMI_Function_Enable[7,46] ) OR ( NOT EM07V.Sen_Avoid4.Out.Filtered_Q AND NOT HMI_Function_Enable[7,45] ) //OR ( NOT EM07V.Sen_Avoid5.Out.Filtered_Q AND NOT HMI_Function_Enable[7,44] ) OR NOT EM07V.Sen_Avoid6.Out.Filtered_Q OR NOT EM07V.Sen_Avoid7.Out.Filtered_Q OR NOT EM07V.Sen_Avoid8.Out.Filtered_Q ;
