IF Act.Act07_AxisCall_FB[10] THEN //轴原点确认 MyStation.EM[10].ServoHomed:=EM10V.Axis_Z1.Out.Homed AND EM10V.Axis_X1.Out.Homed AND EM10V.Axis_R1.Out.Homed AND EM10V.Axis_Y1.Out.Homed AND (EM10V.Axis_Virtual1.Out.Homed OR TRUE);
(*----------------回原点方式----------需要按实际更改 1: HomingMode:=HMC_HOMING_MODE.PassHomeSwHomeSwTurn 附近避让 / 近原点输入 OFF 2: HomingMode:=HMC_HOMING_MODE.InHomeSwHomeSwTurn 附近避让 / 近原点输入 ON 3: HomingMode:=HMC_HOMING_MODE.PassHomeSwHome; 近原点输入 OFF 4: HomingMode:=HMC_HOMING_MODE.InHomeSw; 近原点输入 ON 5: HomingMode:=HMC_HOMING_MODE.PassLimitSw; 极限输入 OFF-----------------------------增量式轴，限位感应器回原使用 (升降Z轴使用) 6: HomingMode:=HMC_HOMING_MODE.HomeSwMaskDistanceHomeSwTurn 附近避让 原点输入屏蔽距离 7: HomingMode:=HMC_HOMING_MODE.OnlyLimit; 仅极限输入 8: HomingMode:=HMC_HOMING_MODE.HomeSwHoldTimeHomeSwTurn; 附近避让 接触时间---------------增量式轴，直线电机 9: HomingMode:=HMC_HOMING_MODE.ZeroSw; 无近原点输入 接触原点输入-----------增量式DD马达，回原使用 12: HomingMode:=HMC_HOMING_MODE.ZeroPositionPreset; 原点预设---------------------------------绝对式轴，无回原动作使用
----------------原点复位开始方向---------- 0: StartDir := MC_DIRECTION.positive 正方向 1: StartDir := MC_DIRECTION.negative 负方向
------检测到原点停止方向---------- 0: Home_SwDir := MC_DIRECTION.positive 正方向 1: Home_SwDir := MC_DIRECTION.negative 负方向
-------原点输入信号---------- 0: HomeInput := HMC_ZERO_SIGNAL.ZPhase 使用 Z 相输入 1: HomeInput := HMC_ZERO_SIGNAL.ExternalSignal 使用外部原点输入
-------编码器类型设置---------- -------类型预设 EC.EM2.AxisIn[0].EncoderSelect:= 0:增量式 （默认），1:绝对式 -------原点偏移--------无此需求可省略以下项 -------回原偏移 Home_Offest:=REAL#XXX;默认0:不偏移。值不等于0时，自动启动偏移功能 // (正值往正方向偏移，负值往负方向偏移） -------回原后设定位置 Home_SetPos:=REAL#XXX;默认0:不改变。偏移完成后,将当前位置设为0值 // 默认使用7号模式回原 *) // 'NOP' (********************Axis_Z1点胶升降Z轴********************) EM10V.Axis_Z1.In.Home_Mode :=TRUE;//FALES基础回原模式，TRUE带参回原 HMI_RecipeData.EM10.Axis_Z1.Home_Offest :=0;//回原偏移 HMI_RecipeData.EM10.Axis_Z1.Home_SetPos :=0;//回原完成后设定位置 HMI_RecipeData.EM10.Axis_Z1.Home_Mode :=7;//回原模式(预设：按实际需求更改) HMI_RecipeData.EM10.Axis_Z1.Home_StartDir :=1;//回原方向选择 0:正方向 1:负方向 HMI_RecipeData.EM10.Axis_Z1.Home_SwDir :=0;//原点检测方向 0:正方向 1:负方向 HMI_RecipeData.EM10.Axis_Z1.Home_Input :=1;//回原原点输入方式 0:Z相(默认),1:外部原点 HMI_RecipeData.EM10.Axis_Z1.Location_SpeedSwitch :=FALSE ; HMI_RecipeData.EM10.Axis_Z1.Accuracy[0] := 0.4;//手自动冲突范围 HMI_RecipeData.EM10.Axis_Z1.Accuracy[3] := 0.3;//大范围到位 EM10V.Axis_Z1.In.EncoderSelect :=0;//编码器类型选择 0:增量式 （默认），1:绝对式
