IF Act.Act09_AlmAndMesg[4] THEN MyStation.EM[4].IsAlarm:= Search_Alarm(H_Messages.Station[4].Object_Alarm) OR H_Messages.Station[4].Alarm; (********************报警信息********************)
//SV08电芯上焊接治具Z轴报警 H_Messages.Station[4].Object_Alarm[0] := EM04V.Axis_Z1.Out.Alarm; //EM04电芯上料模组:SV08电芯上焊接治具Z轴驱动器发生错误 H_Messages.Station[4].Object_Alarm[1] := EM04V.Axis_Z1.Out.Alarm_Out[0]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴驱动器通讯故障报警 H_Messages.Station[4].Object_Alarm[2] := EM04V.Axis_Z1.Out.Alarm_Out[1]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴轴故障报警 H_Messages.Station[4].Object_Alarm[3] := EM04V.Axis_Z1.Out.Alarm_Out[2]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴回原安全条件不满足报警 H_Messages.Station[4].Object_Alarm[4] := EM04V.Axis_Z1.Out.Alarm_Out[3]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴回原中原点或负限位异常 H_Messages.Station[4].Object_Alarm[5] := EM04V.Axis_Z1.Out.Alarm_Out[4]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴轴运动安全条件不满足报警 H_Messages.Station[4].Object_Alarm[6] := EM04V.Axis_Z1.Out.Alarm_Out[5]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴扭矩当前值超过阈值报警 H_Messages.Station[4].Object_Alarm[7] := EM04V.Axis_Z1.Out.Alarm_Out[6]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴柔性回弹报警 H_Messages.Station[4].Object_Alarm[8] := EM04V.Axis_Z1.Out.Alarm_Out[7]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴正限位开关报警 H_Messages.Station[4].Object_Alarm[9] := EM04V.Axis_Z1.Out.Alarm_Out[8]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴负限位开关报警 H_Messages.Station[4].Object_Alarm[10] := EM04V.Axis_Z1.Out.Alarm_Out[9]; //EM04电芯上料模组:SV08电芯上焊接治具Z轴未使能报警 //SV09电芯上焊接治具X轴报警 H_Messages.Station[4].Object_Alarm[11] := EM04V.Axis_X1.Out.Alarm; //EM04电芯上料模组:SV09电芯上焊接治具X轴驱动器发生错误 H_Messages.Station[4].Object_Alarm[12] := EM04V.Axis_X1.Out.Alarm_Out[0]; //EM04电芯上料模组:SV09电芯上焊接治具X轴驱动器通讯故障报警 H_Messages.Station[4].Object_Alarm[13] := EM04V.Axis_X1.Out.Alarm_Out[1]; //EM04电芯上料模组:SV09电芯上焊接治具X轴轴故障报警 H_Messages.Station[4].Object_Alarm[14] := EM04V.Axis_X1.Out.Alarm_Out[2]; //EM04电芯上料模组:SV09电芯上焊接治具X轴回原安全条件不满足报警 H_Messages.Station[4].Object_Alarm[15] := EM04V.Axis_X1.Out.Alarm_Out[3]; //EM04电芯上料模组:SV09电芯上焊接治具X轴回原中原点或负限位异常 H_Messages.Station[4].Object_Alarm[16] := EM04V.Axis_X1.Out.Alarm_Out[4]; //EM04电芯上料模组:SV09电芯上焊接治具X轴轴运动安全条件不满足报警 H_Messages.Station[4].Object_Alarm[17] := EM04V.Axis_X1.Out.Alarm_Out[5]; //EM04电芯上料模组:SV09电芯上焊接治具X轴扭矩当前值超过阈值报警 H_Messages.Station[4].Object_Alarm[18] := EM04V.Axis_X1.Out.Alarm_Out[6]; //EM04电芯上料模组:SV09电芯上焊接治具X轴柔性回弹报警 H_Messages.Station[4].Object_Alarm[19] := EM04V.Axis_X1.Out.Alarm_Out[7]; //EM04电芯上料模组:SV09电芯上焊接治具X轴正限位开关报警 H_Messages.Station[4].Object_Alarm[20] := EM04V.Axis_X1.Out.Alarm_Out[8]; //EM04电芯上料模组:SV09电芯上焊接治具X轴负限位开关报警 H_Messages.Station[4].Object_Alarm[21] := EM04V.Axis_X1.Out.Alarm_Out[9]; //EM04电芯上料模组:SV09电芯上焊接治具X轴未使能报警 //CY0电芯上料夹爪气缸报警 H_Messages.Station[4].Object_Alarm[22] := EM04V.Cy_Clamp1.Out.Alarm_Out[0]; //EM04电芯上料模组:电芯上料夹爪气缸气缸R缩回安全条件不满足报警标志 H_Messages.Station[4].Object_Alarm[23] := EM04V.Cy_Clamp1.Out.Alarm_Out[1]; //EM04电芯上料模组:电芯上料夹爪气缸气缸V伸出安全条件不满足报警标志 H_Messages.Station[4].Object_Alarm[24] := EM04V.Cy_Clamp1.Out.Alarm_Out[2]; //EM04电芯上料模组:电芯上料夹爪气缸气缸缩回R/X080102 超时报警标志 H_Messages.Station[4].Object_Alarm[25] := EM04V.Cy_Clamp1.Out.Alarm_Out[3]; //EM04电芯上料模组:电芯上料夹爪气缸气缸伸出V/X080101 超时报警标志
