// EM04电芯上料模组:SV09_电芯上焊接治具X轴运动干涉提示,原因:SV09电芯上焊接治具X轴无原点标记 IF (EM04V.Axis_X1.In.Location_Select_HMI[0] // EM04电芯上料模组SV09电芯上焊接治具X轴定位0触发 OR EM04V.Axis_X1.In.Location_Select_HMI[1] // EM04电芯上料模组SV09电芯上焊接治具X轴定位1触发 OR EM04V.Axis_X1.In.Location_Select_HMI[2] // EM04电芯上料模组SV09电芯上焊接治具X轴定位2触发 OR EM04V.Axis_X1.In.Location_Select_HMI[3] // EM04电芯上料模组SV09电芯上焊接治具X轴定位3触发 OR EM04V.Axis_X1.In.Location_Select_HMI[4] // EM04电芯上料模组SV09电芯上焊接治具X轴定位4触发 OR EM04V.Axis_X1.In.Location_Select_HMI[5] // EM04电芯上料模组SV09电芯上焊接治具X轴定位5触发 OR EM04V.Axis_X1.In.Location_Select_HMI[6] // EM04电芯上料模组SV09电芯上焊接治具X轴定位6触发 OR EM04V.Axis_X1.In.Location_Select_HMI[7] // EM04电芯上料模组SV09电芯上焊接治具X轴定位7触发 OR EM04V.Axis_X1.In.Location_Select_HMI[8] // EM04电芯上料模组SV09电芯上焊接治具X轴定位8触发 OR EM04V.Axis_X1.In.Location_Select_HMI[9] // EM04电芯上料模组SV09电芯上焊接治具X轴定位9触发 OR EM04V.Axis_X1.In.Location_Select_HMI[10]) // EM04电芯上料模组SV09电芯上焊接治具X轴定位10触发 AND EM04V.Axis_X1.In.Location_Move_HMI AND NOT EM04V.Axis_X1.Out.Homed THEN H_Messages.Station[4].HinderToPos[1,0] := TRUE ;// EM04电芯上料模组:SV09_电芯上焊接治具X轴运动干涉提示,原因:SV09_电芯上焊接治具X轴无原点标记 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 END_IF;
// EM04电芯上料模组：SV09_电芯上焊接治具X轴运动干涉，SV08_电芯上焊接治具Z轴不在安全位 IF (EM04V.Axis_X1.In.Location_Select_HMI[0] // EM04电芯上料模组SV09电芯上焊接治具X轴定位0触发 OR EM04V.Axis_X1.In.Location_Select_HMI[1] // EM04电芯上料模组SV09电芯上焊接治具X轴定位1触发 OR EM04V.Axis_X1.In.Location_Select_HMI[2] // EM04电芯上料模组SV09电芯上焊接治具X轴定位2触发 OR EM04V.Axis_X1.In.Location_Select_HMI[3] // EM04电芯上料模组SV09电芯上焊接治具X轴定位3触发 OR EM04V.Axis_X1.In.Location_Select_HMI[4] // EM04电芯上料模组SV09电芯上焊接治具X轴定位4触发 OR EM04V.Axis_X1.In.Location_Select_HMI[5] // EM04电芯上料模组SV09电芯上焊接治具X轴定位5触发 OR EM04V.Axis_X1.In.Location_Select_HMI[6] // EM04电芯上料模组SV09电芯上焊接治具X轴定位6触发 OR EM04V.Axis_X1.In.Location_Select_HMI[7] // EM04电芯上料模组SV09电芯上焊接治具X轴定位7触发 OR EM04V.Axis_X1.In.Location_Select_HMI[8] // EM04电芯上料模组SV09电芯上焊接治具X轴定位8触发 OR EM04V.Axis_X1.In.Location_Select_HMI[9] // EM04电芯上料模组SV09电芯上焊接治具X轴定位9触发 OR EM04V.Axis_X1.In.Location_Select_HMI[10]) // EM04电芯上料模组SV09电芯上焊接治具X轴定位10触发 AND EM04V.Axis_X1.In.Location_Move_HMI AND NOT HMI_SafetyCondition_Enable AND NOT EM04V.Z1_SafetySignal THEN H_Messages.Station[4].HinderToPos[1,1] := TRUE ;// EM04电芯上料模组：SV09_电芯上焊接治具X轴运动干涉，SV08_电芯上焊接治具Z轴不在安全位 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 END_IF;
// EM04电芯上料模组:手自动冲突 IF NOT Signal_ResetCompleteRT AND MyInput.Start_Input AND NOT MyStation.EM[4].Shielding AND MyStation.EM[4].Conflict THEN H_Messages.Station[4].HinderToPos[25,0] := TRUE ;// EM04电芯上料模组:手自动冲突 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 IF EM04V.Axis_Z1.Out.Tips_Out[5] THEN H_Messages.Station[4].HinderToPos[25,1] := TRUE ;// EM04电芯上料模组:SV08_电芯上焊接治具Z轴-手自动冲突 END_IF IF EM04V.Axis_X1.Out.Tips_Out[5] THEN H_Messages.Station[4].HinderToPos[25,2] := TRUE ;// EM04电芯上料模组:SV09_电芯上焊接治具X轴-手自动冲突 END_IF IF EM04V.Cy_Clamp1.Out.Tips_Out[3] THEN H_Messages.Station[4].HinderToPos[25,3] := TRUE ;// EM04电芯上料模组:进料托盘阻挡气缸1-手自动冲突 END_IF IF EM04V.Clamp.ErrOut.ConflictErr THEN H_Messages.Station[4].HinderToPos[25,4] := TRUE ;// EM04电芯上料模组:电动夹爪-手自动冲突 END_IF END_IF;
(*关闭弹框消除提示*) IF NOT HMI_EQ.ConflictPopups AND NOT H_Messages.ConflictPopups THEN Clear(H_Messages.Station[4].HinderToPos); END_IF;

(*****************************EM04_电芯上料模组状态机*****************************) 

EMNumber := 4;//模组编号
StationNum :=1-1 ;//工位数量--数组编号最大为0..9
//0------电芯上料
Act.Act01_Status[4]:=TRUE;//工位状态机程序
Act.Act02_Condition[4]:=TRUE;//循环扫描程序
//手动动运行程序
Act.Act03_Manual[4]:=  MyStatus.StatusManual;	
//初始化程序
MyStation.EM[4].Resting:=Act.Act04_Init[4];
//自动运行程序			
MyStation.EM[4].Running:=Act.Act05_Auto[4];										
//功能块调用程序						 
Act.Act06_IOCall_FB[4]:=TRUE;
//轴功能块调用程序						 
Act.Act07_AxisCall_FB[4]:=TRUE;
//通讯程序						 
Act.Act08_Communication[4]:=TRUE;
//报警信息程序						 
Act.Act09_AlmAndMesg[4]:=NOT  MyStation.EM[4].Shielding
					AND MyStation.EmgStop
					AND MyStation.SafetyDoor
					AND MyStation.SafetyRaster;


FOR StationSum := 0 TO StationNum BY 1 DO
//功能状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowAuto		:=	Act.Act05_Auto_Station[EMNumber,StationSum] OR Act.Act04_Init_Station[EMNumber,StationSum]					;//自动状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowManual	:=	Act.Act03_Manual[EMNumber]																		;//手动状态
Act.Act10_Call_Status[EMNumber,StationSum].AlarmReset	:=	MyInput.Reset_Input																		;//复位状态
Act.Act10_Call_Status[EMNumber,StationSum].Aborting		:= NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor				;//急停中止
Act.Act10_Call_Status[EMNumber,StationSum].StopCmd		:=	MyStation.EM[EMNumber].Stopping	AND NOT MyStation.EM[EMNumber].Resting		;//停止
Act.Act10_Call_Status[EMNumber,StationSum].DoorAborting:=	NOT MyStation.EmgStop	OR NOT MyStation.SafetyDoor				;//门禁中止																		
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[1]	:= MyStation.ProductionMode															;//生产模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[2]	:= MyStation.MaintenanceMode														;//维护模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[3]	:= Act.Act04_Init_Station[EMNumber,StationSum];//初始化模式												
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[4] 	:= Act.Act03_Manual[EMNumber];//手动模式									
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[5] 	:= MyStation.MaintenanceMode;//维修模式			
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[0]	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[1]	:= NOT	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //未复
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[2]	:=	MyStation.EMStation[EMNumber,StationSum].Resting;  //复位中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[3]	:=	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //复位完成
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[4]	:=	Device_Starting;  //自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[5]	:=	Device_Starting;  //单步自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[6]	:=	MyStation.EM[EMNumber].Stopping;  //暂停中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[7]	:=	NOT MyStation.SafetyDoor AND FALSE;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[8]	:=	NOT MyStation.EmgStop;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].AlarmShield	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
END_FOR;

Act.Act10_Call_Status[EMNumber,0].AllowAuto:=Act.Act10_Call_Status[EMNumber,1].AllowAuto OR	Act.Act10_Call_Status[EMNumber,1].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,2].AllowAuto OR	Act.Act10_Call_Status[EMNumber,3].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,4].AllowAuto OR	Act.Act10_Call_Status[EMNumber,5].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,6].AllowAuto OR	Act.Act10_Call_Status[EMNumber,7].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,8].AllowAuto OR	Act.Act10_Call_Status[EMNumber,9].AllowAuto
																				OR	(Act.Act05_Auto_Station[EMNumber,0] OR Act.Act04_Init_Station[EMNumber,0]);

//--------------输入-----------------------------------//
usiEM01Index:=USINT#6;//工位号
bEM01_Start:=EM04V.Process_steps[0]=230 ;//计时开始									
bEM01_Stop:=NOT (EM04V.Process_steps[0]=170);//计时结束
bEM01_Run:=Act.Act05_Auto_Station[3,0];//工位自动									
														
abEM01ActionStart[1] :=EM04V.Process_steps[0]=100; //1.上芯夹爪打开					
abEM01ActionDone[1]	 :=EM04V.Process_steps[0]=110; 
ausiEM01ActionParallelNum[1]:=0;
abEM01ActionStart[2] :=EM04V.Process_steps[0]=110; //2.Z轴到安全位				
abEM01ActionDone[2]	 :=EM04V.Process_steps[0]=120; 
ausiEM01ActionParallelNum[2]:=0;
abEM01ActionStart[3] :=EM04V.Process_steps[0]=120; //3.X轴到取料位		
abEM01ActionDone[3]	 :=EM04V.Process_steps[0]=130; 
ausiEM01ActionParallelNum[3]:=0;
abEM01ActionStart[4] :=EM04V.Process_steps[0]=130; //4.Z轴到取料位				
abEM01ActionDone[4]	 :=EM04V.Process_steps[0]=140; 
ausiEM01ActionParallelNum[4]:=0;
abEM01ActionStart[5] :=EM04V.Process_steps[0]=140; //5.上芯夹爪夹紧				
abEM01ActionDone[5]	 :=EM04V.Process_steps[0]=160; 
ausiEM01ActionParallelNum[5]:=0;
abEM01ActionStart[6] :=EM04V.Process_steps[0]=160; //6.Z轴到安全位					
abEM01ActionDone[6]	 :=EM04V.Process_steps[0]=170; 
ausiEM01ActionParallelNum[6]:=0;
abEM01ActionStart[7] :=EM04V.Process_steps[0]=170; //7.X轴到放料位			
abEM01ActionDone[7]	 :=EM04V.Process_steps[0]=0; 
ausiEM01ActionParallelNum[7]:=0;
abEM01ActionStart[8] :=EM04V.Process_steps[0]=230; //8.Z轴到放料位
abEM01ActionDone[8]	 :=EM04V.Process_steps[0]=240; 
ausiEM01ActionParallelNum[8]:=0;
abEM01ActionStart[9] :=EM04V.Process_steps[0]=240; //9.上芯夹爪打开		
abEM01ActionDone[9]	 :=EM04V.Process_steps[0]=260; 
ausiEM01ActionParallelNum[9]:=0;
abEM01ActionStart[10] :=EM04V.Process_steps[0]=250; //10.下压气缸上升				
abEM01ActionDone[10] :=EM04V.Process_steps[0]=260; 
ausiEM01ActionParallelNum[10]:=0;
abEM01ActionStart[11] :=EM04V.Process_steps[0]=260; //11.Z轴到安全位						
abEM01ActionDone[11]	 :=EM04V.Process_steps[0]=270; 
ausiEM01ActionParallelNum[11]:=0;
abEM01ActionStart[12] :=EM04V.Process_steps[0]=270; //12.X轴到取料位					
abEM01ActionDone[12]	 :=EM04V.Process_steps[0]=0; 
ausiEM01ActionParallelNum[12]:=0;
//最多62个动作	

//--------------计时-----------------------------------//	
//计时结束 把工位总时间存储进63步									
rtgEM01_Stop(CLK:=bEM01_Stop);									
IF rtgEM01_Stop.Q AND bEM01TimerStart THEN 									
	bEM01TimerStart:=FALSE;	
	FOR uiIndex:=1 TO 62 BY 1 DO															
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);														
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;
	HC_OmronUtils.TimeToNanoSec(In:=tEM01,Out=>liEM01ActionTimeTemp2);
	liEM01ActionTimeTemp2:=liEM01ActionTimeTemp2/1000000;								
	IF liEM01ActionTimeTemp2>LINT#65535 THEN //UINT 范围0-65535，越界处理								
		auiEMTime[usiEM01Index,63]:=65535;							
	ELSE								
		auiEMTime[usiEM01Index,63]:=TO_UINT(liEM01ActionTimeTemp2);							
	END_IF;		
	ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储 
	ausiActionParallelNum[uiFIFOlen]:=USINT#0;//动作并行号 
	auiActionNum[uiFIFOlen]:=UINT#63;//动作号	
	auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,63];//动作时间								
	uiFIFOlen:=uiFIFOlen+1;								
	IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)								
		uiFIFOlen:=166;							
	END_IF;								
END_IF;	

//开始计时									
rtgEM01_Start(CLK:=bEM01_Start);									
IF rtgEM01_Start.Q THEN 									
	bEM01TimerStart:=TRUE;								
	Clear(atEM01ActionStart);								
	Clear(atEM01ActionDone);								
	Clear(abEM01ActionRun);																
END_IF;									
									
//计时									
bEM01TimerEnable:=bEM01TimerStart AND bEM01_Run;									
atEM01(In:=bEM01TimerEnable,PT:=T#1D,Reset:=rtgEM01_Start.Q,ET=>tEM01);									
									
//动作时间计算&数据进缓存									
IF bEM01TimerStart THEN 									
	FOR uiIndex:=1 TO 62 BY 1 DO								
		artgEM01ActionStart[uiIndex](CLK:=abEM01ActionStart[uiIndex]);							
		artgEM01ActionDone[uiIndex](CLK:=abEM01ActionDone[uiIndex]);							
	    IF artgEM01ActionStart[uiIndex].Q THEN  //开始时刻								
			atEM01ActionStart[uiIndex]:=tEM01;						
			abEM01ActionRun[uiIndex]:=TRUE;//防止动作完成信号反复触发，导致数据量激增						
		END_IF;							
		IF artgEM01ActionDone[uiIndex].Q AND abEM01ActionRun[uiIndex] THEN  //完成时刻							
			uiIndexLast:=uiIndex;						
			abEM01ActionRun[uiIndex]:=FALSE;						
			atEM01ActionDone[uiIndex]:=tEM01;	
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionDone[uiIndex],Out=>liEM01ActionDone);
			HC_OmronUtils.TimeToNanoSec(In:=atEM01ActionStart[uiIndex],Out=>liEM01ActionStart);
			liEM01ActionTimeTemp1:=(liEM01ActionDone-liEM01ActionStart)/1000000;//单位ms						
			IF liEM01ActionTimeTemp1>LINT#65535 THEN //UINT 范围0-65535，越界处理						
				auiEMTime[usiEM01Index,uiIndex]:=65535;					
			ELSE						
				auiEMTime[usiEM01Index,uiIndex]:=TO_UINT(liEM01ActionTimeTemp1);					
			END_IF;		
			ausiEMNum[uiFIFOlen]:=usiEM01Index;//工位号存储	
			ausiActionParallelNum[uiFIFOlen]:=ausiEM01ActionParallelNum[uiIndex];//动作并行号	
			auiActionNum[uiFIFOlen]:=uiIndex;//动作号	
			auiActionTime[uiFIFOlen]:=auiEMTime[usiEM01Index,uiIndex];//动作时间						
			uiFIFOlen:=uiFIFOlen+1;						
			IF uiFIFOlen>UINT#166 THEN //最大166个动作记录(1000Byte)						
				uiFIFOlen:=166;					
			END_IF;						
		END_IF;							
	END_FOR;								
END_IF;									
									
								
									
//--------------输出-----------------------------------//									
//auiEMTime[usiEM01Index,1]	:=auiEMTime[usiEM01Index,1]	; //第1个动作时间							
//auiEMTime[usiEM01Index,2]	:=auiEMTime[usiEM01Index,2]	; //第2个动作时间							
//auiEMTime[usiEM01Index,3]	:=auiEMTime[usiEM01Index,3]	; //第3个动作时间							
auiEMTime[usiEM01Index,4]	:=auiEMTime[usiEM01Index,4]	; //第4个动作时间							
auiEMTime[usiEM01Index,5]	:=auiEMTime[usiEM01Index,5]	; //第5个动作时间							
auiEMTime[usiEM01Index,6]	:=auiEMTime[usiEM01Index,6]	; //第6个动作时间							
auiEMTime[usiEM01Index,7]	:=auiEMTime[usiEM01Index,7]	; //第7个动作时间							
auiEMTime[usiEM01Index,8]	:=auiEMTime[usiEM01Index,8]	; //第8个动作时间							
auiEMTime[usiEM01Index,9]	:=auiEMTime[usiEM01Index,9]	; //第9个动作时间							
auiEMTime[usiEM01Index,10]	:=auiEMTime[usiEM01Index,10]	; //第10个动作时间
auiEMTime[usiEM01Index,11]	:=auiEMTime[usiEM01Index,11]	; //第11个动作时间							
auiEMTime[usiEM01Index,12]	:=auiEMTime[usiEM01Index,12]	; //第12个动作时间							
auiEMTime[usiEM01Index,63]	:=auiEMTime[usiEM01Index,63]	; //第63个动作时间

//SV08_电芯上焊接治具Z轴安全信号
EM04V.Z1_SafetySignal:=EM04V.Axis_Z1.Out.CurrentPos<=HMI_RecipeData.EM04.Axis_Z1.Location_Postion[1]+3
													AND EM04V.Axis_Z1.Out.Homed;
//SV09_电芯上焊接治具X轴安全信号-->电芯上料物流线
EM04V.X1_SafetySignal_ToLine:=(ABS(EM04V.Axis_X1.Out.CurrentPos-HMI_RecipeData.EM04.Axis_X1.Location_Postion[1])>=3
													AND EM04V.Axis_X1.Out.Homed)
													OR EM04V.Z1_SafetySignal;
//SV09_电芯上焊接治具X轴安全信号-->EM05环轨模组
EM04V.X1_SafetySignal_ToEM05:=(ABS(EM04V.Axis_X1.Out.CurrentPos-HMI_RecipeData.EM04.Axis_X1.Location_Postion[2])>=3
													AND EM04V.Axis_X1.Out.Homed)
													OR EM04V.Z1_SafetySignal;

FOR StationSum := 0 TO StationNum BY 1 DO
	Act.Act05_Auto_Station[EMNumber,StationSum] := Act.Act05_Auto[EMNumber] AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding;
END_FOR;

IF Act.Act06_IOCall_FB[4]  THEN
EM04V.Clamp.In.MovingAllow:=TRUE;
EM04V.Clamp.In.HomeAllow:=EM04V.Z1_SafetySignal OR TRUE ;
EM04V.Clamp.In.JogAllow:=TRUE;
Axis_Clamp1(
	Resert:= MyInput.Reset_Input , 
	Aborting:= MyStation.EM[4].IsAlarm AND FALSE, 
	EmgStop:=NOT MyStation.EmgStop , 
	Auto:=MyStatus.StatusAuto , 
	Manual:=MyStatus.StatusManual , 
	bConflictState:= TRUE, 
	InitDone:=MyStation.EM[EMNumber].ResetComplete , 
	rScope:=0.3 , 
	HMI_Press1_XV:= TRUE, 
	HMI_Press2_XV:= TRUE, 
	HMI_Press3_XV:= TRUE, 
	HMI_Press4_XV:= TRUE, 	
    HMI_TestMode_E:= HMI_TestMode_Enable, 	
	In:=EM04V.Clamp.In , 
	Out:=EM04V.Clamp.Out , 
	H_In:=EM04H_Cy[0].H_In , 
	H_Out:= EM04H_Cy[0].H_Out ,
	ErrOut:=EM04V.Clamp.ErrOut , 
	Parameter:=HMI_RecipeData.EM04.Clamp )
	;

	
(*
	//CT计算
	CycleTime(
		Enable			:=	Act.Act05_Auto							,//计时使能
		Reset			:=	MyInput.Reset_Input						,//错误复位
		bClear			:=	CycleTime_bClear						,//清除计时，在初始化程序清除
		Complete		:=	CycleTime_Complete						,//完成计时，在自动程序中触发
		ProgramStep		:=	AutoStep								,//步骤变量
		Condition		:=	AutoStep >= 0							,//需要计时的步骤条件
		SysCycleTime	:=	SystemCycleTime							,//系统扫描周期
		HMICycleTime	:=	HMICycleTime[0]							//输出给HMI用的步骤时间
		);
	//工位时间汇总
	MyStation.EM[4].CT	:=	HMICycleTime[0].StationCycleTime	;

*)


