peData.EM11.Axis_R1.Location_Acc;;//SV37_1#拉胶R轴 HMI_RecipeData.EM11.Axis_Y2.Location_Dec:= HMI_RecipeData.EM11.Axis_Y2.Location_Acc;;//SV38_2#拉胶Y轴 HMI_RecipeData.EM11.Axis_R2.Location_Dec:= HMI_RecipeData.EM11.Axis_R2.Location_Acc;;//SV39_2#拉胶R轴 HMI_RecipeData.EM11.Axis_X1.Location_Dec:= HMI_RecipeData.EM11.Axis_X1.Location_Acc;;//SV40_吸胶头变距X轴 HMI_RecipeData.EM11.Axis_Y3.Location_Dec:= HMI_RecipeData.EM11.Axis_Y3.Location_Acc;;//SV41_取胶Y轴 HMI_RecipeData.EM11.Axis_X2.Location_Dec:= HMI_RecipeData.EM11.Axis_X2.Location_Acc;;//SV42_胶卷切换X轴 HMI_RecipeData.EM12.Axis_X1.Location_Dec:= HMI_RecipeData.EM12.Axis_X1.Location_Acc;;//SV43_支架料盘移栽X轴 HMI_RecipeData.EM12.Axis_Z1.Location_Dec:= HMI_RecipeData.EM12.Axis_Z1.Location_Acc;;//SV44_支架上料Z轴 HMI_RecipeData.EM12.Axis_Z2.Location_Dec:= HMI_RecipeData.EM12.Axis_Z2.Location_Acc;;//SV45_支架下料Z轴 HMI_RecipeData.EM12.Axis_X2.Location_Dec:= HMI_RecipeData.EM12.Axis_X2.Location_Acc;;//SV46_支架机器人调宽X轴 HMI_RecipeData.EM12.Axis_Y1.Location_Dec:= HMI_RecipeData.EM12.Axis_Y1.Location_Acc;;//SV47_支架NG缓存Y轴 HMI_RecipeData.EM13.Axis_X1.Location_Dec:= HMI_RecipeData.EM13.Axis_X1.Location_Acc;;//SV49_1#电芯下料X轴 HMI_RecipeData.EM13.Axis_X2.Location_Dec:= HMI_RecipeData.EM13.Axis_X2.Location_Acc;;//SV50_2#电芯下料X轴 HMI_RecipeData.EM13.Axis_Z1.Location_Dec:= HMI_RecipeData.EM13.Axis_Z1.Location_Acc;;//SV51_1#电芯下料Z轴 HMI_RecipeData.EM13.Axis_R1.Location_Dec:= HMI_RecipeData.EM13.Axis_R1.Location_Acc;;//SV52_1#电芯下料R轴 HMI_RecipeData.EM13.Axis_Z2.Location_Dec:= HMI_RecipeData.EM13.Axis_Z2.Location_Acc;;//SV53_2#电芯下料Z轴 HMI_RecipeData.EM13.Axis_Z3.Location_Dec:= HMI_RecipeData.EM13.Axis_Z3.Location_Acc;;//SV54_1#下料提升机Z轴 HMI_RecipeData.EM13.Axis_Z4.Location_Dec:= HMI_RecipeData.EM13.Axis_Z4.Location_Acc;;//SV55_2#下料提升机Z轴 HMI_RecipeData.EM13.Axis_Y1.Location_Dec:= HMI_RecipeData.EM13.Axis_Y1.Location_Acc;;//SV56_下料NG拉带平移Y轴
