Axis_SV45( Enable :=TRUE,//输入使能 VelFactor :=HMI_RecipeData.GeneralOverride, //整机倍率 Offline :=Catl_HMI_Status, //HMI在线状态 FunSimulation :=FALSE, //仿真开启 Axis_Map :=AxisSV45, //轴变量 Axis_Drive := SV44_45,//驱动器 Status :=Act.Act10_Call_Status[12,3], //状态机 Axis_In :=EM12V.Axis_Z2.In, //轴控制指令 Axis_Out :=EM12V.Axis_Z2.Out, //轴状态 Axis_P :=HMI_RecipeData.EM12.Axis_Z2, //轴参数 Axis_Sim :=EM12V.Axis_Z2.SimulateVar//轴仿真参数 );
(********************Axis_X2支架机器人调宽X轴********************) EM12V.Axis_X2.In.Home_Mode :=TRUE;//FALES基础回原模式，TRUE带参回原 HMI_RecipeData.EM12.Axis_X2.Home_Offest :=0;//回原偏移 HMI_RecipeData.EM12.Axis_X2.Home_SetPos :=0;//回原完成后设定位置 HMI_RecipeData.EM12.Axis_X2.Home_Mode :=7;//回原模式(预设：按实际需求更改) HMI_RecipeData.EM12.Axis_X2.Home_StartDir :=1;//回原方向选择 0:正方向 1:负方向 HMI_RecipeData.EM12.Axis_X2.Home_SwDir :=0;//原点检测方向 0:正方向 1:负方向 HMI_RecipeData.EM12.Axis_X2.Home_Input :=1;//回原原点输入方式 0:Z相(默认),1:外部原点 HMI_RecipeData.EM12.Axis_X2.Location_SpeedSwitch :=FALSE ; HMI_RecipeData.EM12.Axis_X2.Accuracy[0] := 0.4;//手自动冲突范围 HMI_RecipeData.EM12.Axis_X2.Accuracy[3] := 0.3;//大范围到位 EM12V.Axis_X2.In.EncoderSelect :=0;//编码器类型选择 0:增量式 （默认），1:绝对式
Axis_SV46( Enable :=TRUE,//输入使能 VelFactor :=HMI_RecipeData.GeneralOverride, //整机倍率 Offline :=Catl_HMI_Status, //HMI在线状态 FunSimulation :=FALSE, //仿真开启 Axis_Map :=AxisSV46, //轴变量 Axis_Drive := SV46_47,//驱动器 Status :=Act.Act10_Call_Status[12,5], //状态机 Axis_In :=EM12V.Axis_X2.In, //轴控制指令 Axis_Out :=EM12V.Axis_X2.Out, //轴状态 Axis_P :=HMI_RecipeData.EM12.Axis_X2, //轴参数 Axis_Sim :=EM12V.Axis_X2.SimulateVar//轴仿真参数 );
(********************Axis_Y1支架NG缓存Y轴********************) EM12V.Axis_Y1.In.Home_Mode :=TRUE;//FALES基础回原模式，TRUE带参回原 HMI_RecipeData.EM12.Axis_Y1.Home_Offest :=0;//回原偏移 HMI_RecipeData.EM12.Axis_Y1.Home_SetPos :=0;//回原完成后设定位置 HMI_RecipeData.EM12.Axis_Y1.Home_Mode :=7;//回原模式(预设：按实际需求更改) HMI_RecipeData.EM12.Axis_Y1.Home_StartDir :=1;//回原方向选择 0:正方向 1:负方向 HMI_RecipeData.EM12.Axis_Y1.Home_SwDir :=0;//原点检测方向 0:正方向 1:负方向 HMI_RecipeData.EM12.Axis_Y1.Home_Input :=1;//回原原点输入方式 0:Z相(默认),1:外部原点 HMI_RecipeData.EM12.Axis_Y1.Location_SpeedSwitch :=FALSE ; HMI_RecipeData.EM12.Axis_Y1.Accuracy[0] := 0.4;//手自动冲突范围 HMI_RecipeData.EM12.Axis_Y1.Accuracy[3] := 0.3;//大范围到位 EM12V.Axis_Y1.In.EncoderSelect :=0;//编码器类型选择 0:增量式 （默认），1:绝对式
