//机器人自动运行命令 IF NOT EM01V.Robot1.Out.Running AND Act.Act05_Auto[1] AND EM01V.Robot1.Out.EnableOK AND EM01V.Robot1.Out.Ready AND NOT MyStation.EM[0].IsAlarm AND NOT MyStation.EM[0].Stopping AND NOT EM01V.Robot1.Out.Paused THEN EM01V.Robot1.In.Run:=TRUE; ELSIF NOT EM01V.Robot1.Out.Running AND Act.Act05_Auto[1] AND EM01V.Robot1.Out.EnableOK AND EM01V.Robot1.Out.Ready AND NOT MyStation.EM[0].IsAlarm AND NOT MyStation.EM[0].Stopping AND EM01V.Robot1.Out.Paused THEN EM01V.Robot1.In.bContinue:=TRUE; ELSIF EM01V.Robot1.Out.Running THEN EM01V.Robot1.In.Run:=FALSE; EM01V.Robot1.In.bContinue:=FALSE; END_IF;
//机器人停止命令 IF MyStation.EM[1].Stopping AND NOT MyStation.EM[1].Resting AND EM01V.Robot1.Out.Running THEN EM01V.Robot1.In.Run:=FALSE; Clear(EM01V.Robot1.In.ToPos); EM01V.Robot1.In.Pause:=TRUE; ELSIF EM01V.Robot1.In.Pause AND NOT EM01V.Robot1.Out.Running THEN EM01V.Robot1.In.Pause:=FALSE; END_IF;
//清除机器人命令 IF NOT Act.Act05_Auto[1] AND NOT Act.Act04_Init[1] THEN EM01V.Robot1.In.Run:=FALSE; END_IF;
//终止并卸载程序需要模组初始化 IF EM01H_Robot[0].In.SystemStop THEN MyStation.EM[1].ResetComplete:=FALSE; MyStation.EMStation[1,3].ResetComplete:=FALSE; END_IF;
//防撞反弹 F_EM01Avoid(Clk:=EM01V.Sen_Avoid5.Out.Filtered_Q OR EM01V.Sen_Avoid6.Out.Filtered_Q); TP_EM01Avoid(In:=F_EM01Avoid.Q (*AND MyStatus.StatusAuto*), PT:=T#2S); IF TP_EM01Avoid.Q
THEN EM01V.Robot1.In.Rebound_Execute:=TRUE; MyStation.EM[1].ResetComplete:=FALSE; MyStation.EMStation[1,3].ResetComplete:=FALSE; ELSE EM01V.Robot1.In.Rebound_Execute:=FALSE; END_IF;
END_IF;

IF Act.Act07_AxisCall_FB[2] THEN //轴原点确认 MyStation.EM[2].ServoHomed:=(EM02V.Axis_X1.Out.Homed OR MyStation.EMStation[2,0].Shielding) AND (EM02V.Axis_R1.Out.Homed OR MyStation.EMStation[2,1].Shielding) AND (EM02V.Axis_Z1.Out.Homed OR MyStation.EMStation[2,1].Shielding);
(*----------------回原点方式----------需要按实际更改 1: HomingMode:=HMC_HOMING_MODE.PassHomeSwHomeSwTurn 附近避让 / 近原点输入 OFF 2: HomingMode:=HMC_HOMING_MODE.InHomeSwHomeSwTurn 附近避让 / 近原点输入 ON 3: HomingMode:=HMC_HOMING_MODE.PassHomeSwHome; 近原点输入 OFF 4: HomingMode:=HMC_HOMING_MODE.InHomeSw; 近原点输入 ON 5: HomingMode:=HMC_HOMING_MODE.PassLimitSw; 极限输入 OFF-----------------------------增量式轴，限位感应器回原使用 (升降Z轴使用) 6: HomingMode:=HMC_HOMING_MODE.HomeSwMaskDistanceHomeSwTurn 附近避让 原点输入屏蔽距离 7: HomingMode:=HMC_HOMING_MODE.OnlyLimit; 仅极限输入 8: HomingMode:=HMC_HOMING_MODE.HomeSwHoldTimeHomeSwTurn; 附近避让 接触时间---------------增量式轴，直线电机 9: HomingMode:=HMC_HOMING_MODE.ZeroSw; 无近原点输入 接触原点输入-----------增量式DD马达，回原使用 12: HomingMode:=HMC_HOMING_MODE.ZeroPositionPreset; 原点预设---------------------------------绝对式轴，无回原动作使用
----------------原点复位开始方向---------- 0: StartDir := MC_DIRECTION.positive 正方向 1: StartDir := MC_DIRECTION.negative 负方向
------检测到原点停止方向---------- 0: Home_SwDir := MC_DIRECTION.positive 正方向 1: Home_SwDir := MC_DIRECTION.negative 负方向
-------原点输入信号---------- 0: HomeInput := HMC_ZERO_SIGNAL.ZPhase 使用 Z 相输入 1: HomeInput := HMC_ZERO_SIGNAL.ExternalSignal 使用外部原点输入
-------编码器类型设置---------- -------类型预设 EC.EM2.AxisIn[0].EncoderSelect:= 0:增量式 （默认），1:绝对式 -------原点偏移--------无此需求可省略以下项 -------回原偏移 Home_Offest:=REAL#XXX;默认0:不偏移。值不等于0时，自动启动偏移功能 // (正值往正方向偏移，负值往负方向偏移） -------回原后设定位置 Home_SetPos:=REAL#XXX;默认0:不改变。偏移完成后,将当前位置设为0值 // 默认使用7号模式回原*) // 'NOP' (********************Axis_X1刻码移栽X轴********************) EM02V.Axis_X1.In.Home_Mode :=TRUE;//FALES基础回原模式，TRUE带参回原 HMI_RecipeData.EM02.Axis_X1.Home_Offest :=0;//回原偏移 HMI_RecipeData.EM02.Axis_X1.Home_SetPos :=0;//回原完成后设定位置 HMI_RecipeData.EM02.Axis_X1.Home_Mode :=8;//回原模式(预设：按实际需求更改) HMI_RecipeData.EM02.Axis_X1.Home_StartDir :=0;//回原方向选择 0:正方向 1:负方向 HMI_RecipeData.EM02.Axis_X1.Home_SwDir :=1;//原点检测方向 0:正方向 1:负方向 HMI_RecipeData.EM02.Axis_X1.Home_Input :=1;//回原原点输入方式 0:Z相(默认),1:外部原点
HMI_RecipeData.EM02.Axis_X1.Location_SpeedSwitch :=FALSE ; HMI_RecipeData.EM02.Axis_X1.Accuracy[0] := 0.4;//手自动冲突范围 HMI_RecipeData.EM02.Axis_X1.Accuracy[3] := 0.4;//大范围到位 EM02V.Axis_X1.In.EncoderSelect :=1;//编码器类型选择 0:增量式 （默认），1:绝对式
Axis_SV05( Enable :=TRUE,//输入使能 VelFactor :=HMI_RecipeData.GeneralOverride, //整机倍率 Offline :=Catl_HMI_Status, //HMI在线状态 FunSimulation :=FALSE, //仿真开启 Axis_Map :=AxisSV05, //轴变量 Axis_Drive := SV05,//驱动器 Status :=Act.Act10_Call_Status[2,0], //状态机 Axis_In :=EM02V.Axis_X1.In, //轴控制指令 Axis_Out :=EM02V.Axis_X1.Out, //轴状态 Axis_P :=HMI_RecipeData.EM02.Axis_X1, //轴参数 Axis_Sim :=EM02V.Axis_X1.SimulateVar//轴仿真参数 ); (********************Axis_R1刻码翻转R轴********************) EM02V.Axis_R1.In.Home_Mode :=TRUE;//FALES基础回原模式，TRUE带参回原 HMI_RecipeData.EM02.Axis_R1.Home_Offest :=0;//回原偏移 HMI_RecipeData.EM02.Axis_R1.Home_SetPos :=0;//回原完成后设定位置 HMI_RecipeData.EM02.Axis_R1.Home_Mode :=7;//回原模式(预设：按实际需求更改) HMI_RecipeData.EM02.Axis_R1.Home_StartDir :=1;//回原方向选择 0:正方向 1:负方向 HMI_RecipeData.EM02.Axis_R1.Home_SwDir :=0;//原点检测方向 0:正方向 1:负方向 HMI_RecipeData.EM02.Axis_R1.Home_Input :=1;//回原原点输入方式 0:Z相(默认),1:外部原点
HMI_RecipeData.EM02.Axis_R1.Location_SpeedSwitch :=FALSE ; HMI_RecipeData.EM02.Axis_R1.Accuracy[0] := 0.4;//手自动冲突范围 HMI_RecipeData.EM02.Axis_R1.Accuracy[3] := 0.3;//大范围到位 EM02V.Axis_R1.In.EncoderSelect :=0;//编码器类型选择 0:增量式 （默认），1:绝对式
Axis_SV06( Enable :=TRUE,//输入使能 VelFactor :=HMI_RecipeData.GeneralOverride, //整机倍率 Offline :=Catl_HMI_Status, //HMI在线状态 FunSimulation :=FALSE, //仿真开启 Axis_Map :=AxisSV06, //轴变量 Axis_Drive := SV06_07,//驱动器 Status :=Act.Act10_Call_Status[2,1], //状态机 Axis_In :=EM02V.Axis_R1.In, //轴控制指令 Axis_Out :=EM02V.Axis_R1.Out, //轴状态 Axis_P :=HMI_RecipeData.EM02.Axis_R1, //轴参数 Axis_Sim :=EM02V.Axis_R1.SimulateVar//轴仿真参数 ); (********************Axis_Z1刻码升降Z轴********************) EM02V.Axis_Z1.In.Home_Mode :=TRUE;//FALES基础回原模式，TRUE带参回原 HMI_RecipeData.EM02.Axis_Z1.Home_Offest :=0;//回原偏移 HMI_RecipeData.EM02.Axis_Z1.Home_SetPos :=0;//回原完成后设定位置 HMI_RecipeData.EM02.Axis_Z1.Home_Mode :=7;//回原模式(预设：按实际需求更改) HMI_RecipeData.EM02.Axis_Z1.Home_StartDir :=1;//回原方向选择 0:正方向 1:负方向 HMI_RecipeData.EM02.Axis_Z1.Home_SwDir :=0;//原点检测方向 0:正方向 1:负方向 HMI_RecipeData.EM02.Axis_Z1.Home_Input :=1;//回原原点输入方式 0:Z相(默认),1:外部原点
HMI_RecipeData.EM02.Axis_Z1.Location_SpeedSwitch :=FALSE ; HMI_RecipeData.EM02.Axis_Z1.Accuracy[0] := 0.4;//手自动冲突范围 HMI_RecipeData.EM02.Axis_Z1.Accuracy[3] := 0.3;//大范围到位 EM02V.Axis_R1.In.EncoderSelect :=0;//编码器类型选择 0:增量式 （默认），1:绝对式
Axis_SV07( Enable :=TRUE,//输入使能 VelFactor :=HMI_RecipeData.GeneralOverride, //整机倍率 Offline :=Catl_HMI_Status, //HMI在线状态 FunSimulation :=FALSE, //仿真开启 Axis_Map :=AxisSV07, //轴变量 Axis_Drive := SV06_07,//驱动器 Status :=Act.Act10_Call_Status[2,1], //状态机 Axis_In :=EM02V.Axis_Z1.In, //轴控制指令 Axis_Out :=EM02V.Axis_Z1.Out, //轴状态 Axis_P :=HMI_RecipeData.EM02.Axis_Z1, //轴参数 Axis_Sim :=EM02V.Axis_Z1.SimulateVar//轴仿真参数 ); END_IF;
//板链线治具位置一键计算 IF HMI_Button[2,0] THEN FOR i:=2 TO 14 DO HMI_RecipeData.EM02.Axis_X1.Location_Postion[i]:=HMI_RecipeData.EM02.Axis_X1.Location_Postion[i-1]+HMI_RecipeData.EM02.Axis_X1.Location_Postion[0]; END_FOR; END_IF; //板链线回原定位位置赋值 HMI_RecipeData.EM02.Axis_X1.Home_SetPos :=0; //只要板链线回原就要把移动位置记忆赋值为1 IF EM02V.Axis_X1.Out.Cmd_Busy[0] AND NOT EM02P.AxisHomingFlag AND NOT Act.Act05_Auto[2] AND NOT Act.Act04_Init[2] THEN EM02P.AxisMoveNumber:=1; EM02P.AxisMovingFlag:=FALSE; //EM02V.Axis_X1.In.Home_HMI:=FALSE; END_IF;
//板链线触发点位计算 IF EM02P.AxisMoveNumber<14 THEN EM02V.AxisMoveNumber:=EM02P.AxisMoveNumber+1; ELSIF EM02P.AxisMoveNumber>=14 THEN EM02V.AxisMoveNumber:=1; END_IF;
//板链线轴到位标志 EM02V.Axis_InPlace_Flag := EM02V.Axis_X1.Out.PosDone[1] OR EM02V.Axis_X1.Out.PosDone[2] OR EM02V.Axis_X1.Out.PosDone[3] OR EM02V.Axis_X1.Out.PosDone[4] OR EM02V.Axis_X1.Out.PosDone[5] OR EM02V.Axis_X1.Out.PosDone[6] OR EM02V.Axis_X1.Out.PosDone[7] OR EM02V.Axis_X1.Out.PosDone[8] OR EM02V.Axis_X1.Out.PosDone[9] OR EM02V.Axis_X1.Out.PosDone[10] OR EM02V.Axis_X1.Out.PosDone[11] OR EM02V.Axis_X1.Out.PosDone[12] OR EM02V.Axis_X1.Out.PosDone[13] OR EM02V.Axis_X1.Out.PosDone[14];
//板链线轴到位延时标志 TON_EM02Axis_InPlace(In:=EM02V.Axis_InPlace_Flag, PT:=T#200MS); EM02V.Axis_InPlace_Delay:=TON_EM02Axis_InPlace.Q;

