(******************************************** 物流线交互信号 *********************************************) //////////////////////////////////////////上料////////////////////////////////////////// EM01V.LinkOut_Request1 := Act.Act05_Auto[1] AND Act.Act05_Auto_Station[1,0] AND NOT HMI_Function_Enable[1,0] AND NOT HMI_TestMode_Enable AND (Cell_Info[1,0].Quality=0 OR Cell_Info[1,0].Quality=20) AND Cell_Info[1,1].Quality=0 //AND NOT EM01V.Sen_TrayInplace1_1.Out.Filtered_Q //AND NOT EM01V.Sen_TrayInplace1_2.Out.Filtered_Q AND NOT EM01V.Sen_ForkHavePlate1.Out.Filtered_Q //AND NOT EM01V.Sen_HaveTray1_1.Out.Filtered_Q //AND NOT EM01V.Sen_HaveTray1_2.Out.Filtered_Q AND EM01V.Cy_Location1.Out.XR AND EM01V.Cy_Up1.Out.XR AND EM01V.Axis_Z1.Out.PosDone[2] ;// 设备To物流线：请求取料 EM01V.LinkOut_Assign1 := Act.Act05_Auto[1] AND Act.Act05_Auto_Station[1,0] AND NOT HMI_Function_Enable[1,0] AND EM01V.LinkOut_Request1 AND EM01V.LinkIn_Allow1 ;// 设备To物流线：上料请求分配 // EM01V.LinkOut_Done1 := Act.Act05_Auto[1] // AND Act.Act05_Auto_Station[1,0] // AND NOT HMI_Function_Enable[1,0] // AND NOT HMI_TestMode_Enable // AND Cell_Info[1,0].Quality=100 // AND (EM01V.Sen_TrayInplace1_1.Out.Filtered_Q // OR EM01V.Sen_TrayInplace1_2.Out.Filtered_Q) // //AND EM01V.Sen_HaveTray1_2.Out.Filtered_Q // AND EM01V.Axis_Z1.Out.PosDone[2] // ;// 设备To物流线：取料完成 EM01V.LinkOut_MovingAllow1 := EM01V.LinkOut_Request1 //AND NOT EM01V.LinkOut_Assign1 AND EM01V.LinkIn_Allow1 AND NOT EM01V.LinkOut_Done1 ;// 设备To物流线：上料移动允许(现场和物流线的再确认) EM01V.LinkOut_SafetySD := (MyStation.EmgStop AND MyInput.SafetyDoor_Input[22] AND MyInput.SafetyDoor_Input[23] AND MyInput.SafetyDoor_Input[24] );// 设备To物流线：安全门禁
//分配响应计时 TON_Assigned1( In:=EM01V.LinkOut_Assign1 AND EM01V.LinkIn_Allow1 AND EM01V.LinkIn_SafetySD , PT:=T#200MS); EM01V.LinkIn_Assigned1 := TON_Assigned1.Q;// 物流线To设备：上料分配响应
TON_3(IN:=EM01V.LinkOut_Done1,PT:=T#1S); IF TON_3.Q THEN EM01V.LinkOut_Done1:=FALSE; END_IF
//////////////////////////////////////////下料////////////////////////////////////////// EM01V.LinkOut_Request2 := Act.Act05_Auto[1] AND Act.Act05_Auto_Station[1,1] AND NOT HMI_Function_Enable[1,0] AND NOT HMI_TestMode_Enable AND (Cell_Info[1,2].Quality=100 OR Cell_Info[1,2].Quality=80) AND EM01V.Cy_Location2.Out.XR AND EM01V.Cy_Up2.Out.XR AND EM01V.Axis_Z2.Out.PosDone[2] ;// 设备To物流线：请求下料 EM01V.LinkOut_Assign2 := Act.Act05_Auto[1] AND Act.Act05_Auto_Station[1,1] AND NOT HMI_Function_Enable[1,0] AND EM01V.LinkOut_Request2 AND EM01V.LinkIn_Allow2 ;// 设备To物流线：下料请求分配 EM01V.LinkOut_Done2 := Act.Act05_Auto[1] AND Act.Act05_Auto_Station[1,1] AND NOT HMI_Function_Enable[1,0] AND NOT HMI_TestMode_Enable AND Cell_Info[1,2].Quality=0 AND EM01V.Cy_Location2.Out.XR AND EM01V.Cy_Up2.Out.XR AND EM01V.Axis_Z2.Out.PosDone[2] ;// 设备To物流线：下料完成 EM01V.LinkOut_MovingAllow2 := EM01V.LinkOut_Request2 AND EM01V.LinkIn_Allow2 //AND NOT EM01V.LinkOut_Assign2 AND NOT EM01V.LinkOut_Done2 ;// 设备To物流线：下料移动允许(现场和物流线的再确认)
//分配响应计时 TON_Assigned2( In:=EM01V.LinkOut_Assign2 AND EM01V.LinkIn_Allow2 AND EM01V.LinkIn_SafetySD , PT:=T#200MS); EM01V.LinkIn_Assigned2 := TON_Assigned2.Q;// 物流线To设备：下料分配响应

data.STCode:
//下料底托更换属性
