TON_Shield2(IN:= NOT EM01V.Sen_UnLoadTrayOut4.Out.Filtered_Q
				AND NOT EM01V.Sen_UnLoadTrayOut3.Out.Filtered_Q AND
				 NOT EM01V.Sen_UnLoadTrayOut2.Out.Filtered_Q
				AND NOT EM01V.Sen_UnLoadTrayOut1.Out.Filtered_Q
				AND NOT EM01V.Sen_HaveTray2_1.Out.Filtered_Q
				AND EM01V.LinkOut_SafetyGrating_Shield
				, PT:=T#5S );//出料完成延时 
				
