		AND NOT EM01V.Sen_HaveTray2_1.Out.Filtered_Q
		AND EM01V.LinkOut_SafetyGrating_Shield
		AND TON_Shield2.Q 
		OR (F_LoadTrayOut.Q AND Act.Act05_Auto_Station[1,1])
	THEN
		EM01V.LinkOut_SafetyGrating_Shield:=FALSE; //出料安全光栅屏蔽
	END_IF
// ELSE
// 	EM01V.LinkOut_SafetyGrating_Shield:=FALSE; //出料安全光栅屏蔽
// END_IF

IF TON_LoadTrayOut.Q THEN
	EM01V.LinkOut_SafetyGrating_Shield:=FALSE; //出料安全光栅屏蔽
END_IF

