// EM01顶盖上料模组:SV03_顶盖吸塑盘下料Z轴运动干涉提示,原因:SV03顶盖吸塑盘下料Z轴无原点标记 IF (EM01V.Axis_Z2.In.Location_Select_HMI[0] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位0触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[1] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位1触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[2] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位2触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[3] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位3触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[4] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位4触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[5] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位5触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[6] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位6触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[7] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位7触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[8] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位8触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[9] // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位9触发 OR EM01V.Axis_Z2.In.Location_Select_HMI[10]) // EM01顶盖上料模组SV03顶盖吸塑盘下料Z轴定位10触发 AND EM01V.Axis_Z2.In.Location_Move_HMI AND NOT EM01V.Axis_Z2.Out.Homed THEN H_Messages.Station[1].HinderToPos[2,0] := TRUE ;// EM01顶盖上料模组:SV03_顶盖吸塑盘下料Z轴运动干涉提示,原因:SV03_顶盖吸塑盘下料Z轴无原点标记 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 END_IF;
// EM01顶盖上料模组:SV03_顶盖吸塑盘下料Z轴运动干涉提示,原因:顶盖移栽替罪羊不在放置位2 IF (EM01V.Axis_Z2.In.JOG_HMI[1] OR EM01V.Axis_Z2.In.JOG_HMI[0] OR EM01V.Axis_Z2.In.Location_Move_HMI OR EM01V.Axis_Z2.In.Home_HMI) AND NOT EM01V.MovingAllow[2] THEN H_Messages.Station[1].HinderToPos[2,1] := TRUE ;// EM01顶盖上料模组:SV03_顶盖吸塑盘下料Z轴运动干涉提示,原因:顶盖移栽替罪羊不在放置位2 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 END_IF;
// EM01顶盖上料模组:SV02_顶盖吸塑盘上料Z轴运动干涉提示,原因:Z1轴运动条件不满足，检查气缸状态 IF (NOT EM01V.Axis_z2.In.Home_SafeCondition AND EM01V.Axis_Z2.In.Home_HMI ) OR ( NOT EM01V.Axis_Z2.In.Location_SafeCondition[2] AND EM01V.Axis_Z2.In.Location_Move_HMI) THEN H_Messages.Station[1].HinderToPos[2,2] := TRUE ;// EM01顶盖上料模组:SV02_顶盖吸塑盘上料Z轴运动干涉提示,原因:Z2轴运动条件不满足，检查气缸状态 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 END_IF;
// EM01顶盖上料模组:SV04_顶盖上料机器人调宽X轴运动干涉提示,原因:SV04顶盖上料机器人调宽X轴无原点标记 IF (EM01V.Axis_X2.In.Location_Select_HMI[0] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位0触发 OR EM01V.Axis_X2.In.Location_Select_HMI[1] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位1触发 OR EM01V.Axis_X2.In.Location_Select_HMI[2] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位2触发 OR EM01V.Axis_X2.In.Location_Select_HMI[3] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位3触发 OR EM01V.Axis_X2.In.Location_Select_HMI[4] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位4触发 OR EM01V.Axis_X2.In.Location_Select_HMI[5] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位5触发 OR EM01V.Axis_X2.In.Location_Select_HMI[6] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位6触发 OR EM01V.Axis_X2.In.Location_Select_HMI[7] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位7触发 OR EM01V.Axis_X2.In.Location_Select_HMI[8] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位8触发 OR EM01V.Axis_X2.In.Location_Select_HMI[9] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位9触发 OR EM01V.Axis_X2.In.Location_Select_HMI[10] // EM01顶盖上料模组SV04顶盖上料机器人调宽X轴定位10触发 OR EM01V.Axis_X2.In.Location_Select_HMI[11]) AND EM01V.Axis_X2.In.Location_Move_HMI AND NOT EM01V.Axis_X2.Out.Homed THEN H_Messages.Station[1].HinderToPos[3,0] := TRUE ;// EM01顶盖上料模组:SV04_顶盖上料机器人调宽X轴运动干涉提示,原因:SV04_顶盖上料机器人调宽X轴无原点标记 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 END_IF;
//EM01顶盖上料模组：SV04_顶盖上料机器人调宽X轴运动干涉，未检测到顶盖上料机器人在取料区域安全信 IF (EM01V.Axis_X2.In.JOG_HMI[1] OR EM01V.Axis_X2.In.JOG_HMI[0] OR EM01V.Axis_X2.In.Location_Move_HMI OR EM01V.Axis_X2.In.Home_HMI) AND NOT HMI_SafetyCondition_Enable AND NOT EM01V.Robot1_SafetySignal_ToX1 THEN H_Messages.Station[1].HinderToPos[3,1] :=TRUE;//EM01顶盖上料模组：SV04_顶盖上料机器人调宽X轴运动干涉，未检测到顶盖上料机器人在取料区域安全信号 HMI_EQ.ConflictPopups:=TRUE; END_IF;
//EM01顶盖上料模组：SV04_顶盖上料机器人调宽X轴运动干涉，未检测到顶盖上料机器人在放料区域安全 IF (EM01V.Axis_X2.In.JOG_HMI[1] OR EM01V.Axis_X2.In.JOG_HMI[0] OR EM01V.Axis_X2.In.Location_Move_HMI OR EM01V.Axis_X2.In.Home_HMI) AND NOT HMI_SafetyCondition_Enable AND NOT EM01V.Robot1_SafetySignal_ToEM02 THEN H_Messages.Station[1].HinderToPos[3,2]:=TRUE;//EM01顶盖上料模组：SV04_顶盖上料机器人调宽X轴运动干涉，未检测到顶盖上料机器人在放料区域安全信号 HMI_EQ.ConflictPopups:=TRUE; END_IF;
//EM01顶盖上料模组：顶盖上料机器人运动干涉，SV01_顶盖吸塑盘移载X轴不在放顶盖位 IF ( EM01H_Robot[0].In.Location_Auto[1] OR EM01H_Robot[0].In.Location_Auto[2] OR EM01H_Robot[0].In.Location_Auto[3] OR EM01H_Robot[0].In.Location_Auto[4] OR EM01H_Robot[0].In.Location_Auto[5] OR EM01H_Robot[0].In.Location_Auto[6] OR EM01H_Robot[0].In.Location_Auto[7] OR EM01H_Robot[0].In.Location_Auto[8] OR EM01H_Robot[0].In.Location_Auto[9] OR EM01H_Robot[0].In.Location_Auto[10]) AND NOT HMI_SafetyCondition_Enable AND NOT EM01V.X1_SafetySignal_ToRobot1 THEN EM01H_Robot[0].Out.HinderRobot[0]:=TRUE;//EM01顶盖上料模组：顶盖上料机器人运动干涉，SV01_顶盖吸塑盘移载X轴不在放顶盖位 HMI_EQ.ConflictPopups:=TRUE; END_IF;
//EM01顶盖上料模组：顶盖上料机器人运动干涉，SV04_顶盖上料机器人调宽X轴不在取顶盖位 IF ( EM01H_Robot[0].In.Location_Auto[1] OR EM01H_Robot[0].In.Location_Auto[2] OR EM01H_Robot[0].In.Location_Auto[3] OR EM01H_Robot[0].In.Location_Auto[4] OR EM01H_Robot[0].In.Location_Auto[5] OR EM01H_Robot[0].In.Location_Auto[6] OR EM01H_Robot[0].In.Location_Auto[7] OR EM01H_Robot[0].In.Location_Auto[8] OR EM01H_Robot[0].In.Location_Auto[9] OR EM01H_Robot[0].In.Location_Auto[10]) AND NOT HMI_SafetyCondition_Enable AND NOT EM01V.X2_SafetySignal_ToRobot1Load THEN EM01H_Robot[0].Out.HinderRobot[1]:=TRUE;//EM01顶盖上料模组：顶盖上料机器人运动干涉，SV04_顶盖上料机器人调宽X轴不在取顶盖位 HMI_EQ.ConflictPopups:=TRUE; END_IF;
//EM01顶盖上料模组：顶盖上料机器人运动干涉，SV04_顶盖上料机器人调宽X轴不在放顶盖位 IF EM01H_Robot[0].In.Location_Auto[22] AND NOT HMI_SafetyCondition_Enable AND NOT EM01V.X2_SafetySignal_ToRobot1UnLoad THEN EM01H_Robot[0].Out.HinderRobot[2]:=TRUE;//EM01顶盖上料模组：顶盖上料机器人运动干涉，SV04_顶盖上料机器人调宽X轴不在放顶盖位 HMI_EQ.ConflictPopups:=TRUE; END_IF;
//EM01顶盖上料模组：顶盖上料机器人运动干涉，SV05_刻码移栽X轴不在工位上 IF EM01H_Robot[0].In.Location_AutO[22] AND NOT HMI_SafetyCondition_Enable AND NOT EM02V.X1_SafetySignal AND NOT MyStation.EM[2].Shielding THEN EM01H_Robot[0].Out.HinderRobot[3]:=TRUE;//EM01顶盖上料模组：顶盖上料机器人运动干涉，SV05_刻码移栽X轴不在工位上 HMI_EQ.ConflictPopups:=TRUE; END_IF;
// EM01顶盖上料模组:手自动冲突 IF NOT Signal_ResetCompleteRT AND MyInput.Start_Input AND NOT MyStation.EM[1].Shielding AND MyStation.EM[1].Conflict THEN H_Messages.Station[1].HinderToPos[25,0] := TRUE ;// EM01顶盖上料模组:手自动冲突 H_Messages.ConflictPopups := TRUE ;// 干涉弹框标志位 IF EM01V.Axis_X1.Out.Tips_Out[5] THEN H_Messages.Station[1].HinderToPos[25,1] := TRUE ;// EM01顶盖上料模组:SV01_顶盖吸塑盘移载X轴-手自动冲突 END_IF IF EM01V.Axis_Z1.Out.Tips_Out[5] THEN H_Messages.Station[1].HinderToPos[25,2] := TRUE ;// EM01顶盖上料模组:SV02_顶盖吸塑盘上料Z轴-手自动冲突 END_IF IF EM01V.Axis_Z2.Out.Tips_Out[5] THEN H_Messages.Station[1].HinderToPos[25,3] := TRUE ;// EM01顶盖上料模组:SV03_顶盖吸塑盘下料Z轴-手自动冲突 END_IF IF EM01V.Axis_X2.Out.Tips_Out[5] THEN H_Messages.Station[1].HinderToPos[25,4] := TRUE ;// EM01顶盖上料模组:SV04_顶盖上料机器人调宽X轴-手自动冲突 END_IF IF EM01V.Cy_Up1.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,5] := TRUE ;// EM01顶盖上料模组:进料托盘顶升气缸-手自动冲突 END_IF IF EM01V.Cy_Location1.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,6] := TRUE ;// EM01顶盖上料模组:进料托盘导向气缸-手自动冲突 END_IF IF EM01V.Cy_Up2.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,7] := TRUE ;// EM01顶盖上料模组:出料托盘顶升气缸-手自动冲突 END_IF IF EM01V.Cy_Location2.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,8] := TRUE ;// EM01顶盖上料模组:出料托盘导向气缸-手自动冲突 END_IF IF EM01V.Cy_Push1.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,9] := TRUE ;// EM01顶盖上料模组:料盘搬运定位气缸1-手自动冲突 END_IF IF EM01V.Cy_Push2.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,10] := TRUE ;// EM01顶盖上料模组:料盘搬运定位气缸2-手自动冲突 END_IF IF EM01V.Cy_Push3.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,11] := TRUE ;// EM01顶盖上料模组:料盘搬运夹紧气缸1-手自动冲突 END_IF IF EM01V.Cy_Push4.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,12] := TRUE ;// EM01顶盖上料模组:料盘搬运夹紧气缸2-手自动冲突 END_IF IF EM01V.Cy_Separate1.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,13] := TRUE ;// EM01顶盖上料模组:料盘搬运分盘气缸1-手自动冲突 END_IF IF EM01V.Cy_Separate2.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,14] := TRUE ;// EM01顶盖上料模组:料盘搬运分盘气缸2-手自动冲突 END_IF IF EM01V.Cy_TryInplace1.Out.Tips_Out[3] THEN H_Messages.Station[1].HinderToPos[25,15] := TRUE ;// EM01顶盖上料模组:托盘到位矫正气缸-手自动冲突 END_IF END_IF;
(*关闭弹框消除提示*) IF NOT HMI_EQ.ConflictPopups AND NOT H_Messages.ConflictPopups THEN Clear(H_Messages.Station[1].HinderToPos); Clear(EM01H_Robot[0].Out.HinderRobot); END_IF;

//SV02_顶盖吸塑盘上料Z轴安全信号-->SV01_顶盖吸塑盘移载X轴
EM01V.Z1_SafetySignal_ToX1:=	EM01V.Axis_Z1.Out.CurrentPos<=HMI_RecipeData.EM01.Axis_Z1.Location_Postion[4]+3
													AND EM01V.Axis_Z1.Out.Homed;
//SV03_顶盖吸塑盘下料Z轴安全信号-->SV01_顶盖吸塑盘移载X轴
EM01V.Z2_SafetySignal_ToX1:=	EM01V.Axis_Z2.Out.CurrentPos<=HMI_RecipeData.EM01.Axis_Z2.Location_Postion[4]+3
													AND EM01V.Axis_Z2.Out.Homed;
//SV02_顶盖吸塑盘上料Z轴安全信号-->托盘可通过安全高度
EM01V.Z1_SafetySignal_ToTray:=EM01V.Axis_Z1.Out.CurrentPos>=HMI_RecipeData.EM01.Axis_Z1.Location_Postion[3]-3
													AND EM01V.Axis_Z1.Out.Homed;
//SV03_顶盖吸塑盘下料Z轴安全信号-->托盘可通过安全高度
EM01V.Z2_SafetySignal_ToTray:=EM01V.Axis_Z2.Out.CurrentPos>=HMI_RecipeData.EM01.Axis_Z2.Location_Postion[3]-3
													AND EM01V.Axis_Z2.Out.Homed;
//SV01_顶盖吸塑盘移载X轴安全信号-->顶盖上料机器人
EM01V.X1_SafetySignal_ToRobot1:=	EM01V.Axis_X1.Out.LargeScalePosDone[1]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[2]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[3]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[4]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[5]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[6]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[7]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[8]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[9]
													OR EM01V.Axis_X1.Out.LargeScalePosDone[10];
//SV04_顶盖上料机器人调宽X轴安全信号-->顶盖上料机器人取顶盖
EM01V.X2_SafetySignal_ToRobot1Load:=		EM01V.Axis_X2.Out.LargeScalePosDone[1]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[2]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[3]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[4]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[5]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[6]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[7]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[8]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[9]
																	OR EM01V.Axis_X2.Out.LargeScalePosDone[10];
//SV04_顶盖上料机器人调宽X轴安全信号-->顶盖上料机器人放顶盖
EM01V.X2_SafetySignal_ToRobot1UnLoad:=	EM01V.Axis_X2.Out.LargeScalePosDone[1];

(************************** 机器人动作条件************************)
EM01V.Robot1.In.Location_SafeCondition:=ARRAY48_TRUE;
IF EM01V.Robot1.Out.Act.Xvalue<>0 AND EM01V.Robot1.Out.Act.Yvalue<>0 AND EM01V.Robot1.Out.Act.Zvalue<>0
THEN
//顶盖上料机器人安全信号-->SV01_顶盖吸塑盘移载X轴
EM01V.Robot1_SafetySignal_ToX1:=EM01V.Robot1.Out.SafetyArea[0];
//顶盖上料机器人安全信号-->EM02_刻码拉带模组
EM01V.Robot1_SafetySignal_ToEM02:=EM01V.Robot1.Out.SafetyArea[1];
END_IF;

//顶盖上料机器人取料标志
IF	EM01V.Robot1.Out.PosDone[0]
	OR NOT EM01V.Robot1_SafetySignal_ToX1
THEN
	EM01V.Robot1ToX1:=FALSE;
END_IF;

//顶盖上料机器人放料标志
IF	EM01V.Robot1.Out.PosDone[0]
	OR NOT EM01V.Robot1_SafetySignal_ToEM02
THEN
	EM01V.Robot1ToEM02:=FALSE;
END_IF;

(******************************************料盘参数**************************************************)
IF //料盘X方向总数，不能小于1
	HMI_RecipeData.EM01PlateSumX<1 THEN
	HMI_RecipeData.EM01PlateSumX:=1;
END_IF;
IF //料盘Y方向总数，不能小于1
	HMI_RecipeData.EM01PlateSumRobot<1 THEN
	HMI_RecipeData.EM01PlateSumRobot:=1;
END_IF;

//当前取料次数>=总次数，改变料盘属性
IF EM01P.PlateTakeNum>=HMI_RecipeData.EM01PlateSumX*HMI_RecipeData.EM01PlateSumRobot
THEN
	IF Cell_Info[1,4].Quality=100 THEN
		Cell_Info[1,4].Quality:=90;
	END_IF;
	EM01P.PlateTakeNum:=0;
END_IF;
//无料时当前取料次数清零
IF Cell_Info[1,4].Quality=0 THEN
	EM01P.PlateTakeNum:=0;
END_IF;

//料盘X方向位置
EM01P.PlateTakePositionX:=(EM01P.PlateTakeNum/HMI_RecipeData.EM01PlateSumRobot)+1;
//料盘Y方向位置
EM01P.PlateTakePositionRobot:=(EM01P.PlateTakeNum MOD HMI_RecipeData.EM01PlateSumRobot)+1;
//料盘Y方向等待位
EM01P.PlateTakeWaitPositionRobot:=EM01P.PlateTakePositionRobot+10;
//料盘变距轴跟随模式
IF NOT HMI_Function_Enable[1,1] THEN
	EM01P.PlateSumChange:=HMI_RecipeData.EM01PlateSumX;
	EM01P.PlateTakePositionChange:=EM01P.PlateTakePositionX;
ELSE
	EM01P.PlateSumChange:=HMI_RecipeData.EM01PlateSumRobot;
	EM01P.PlateTakePositionChange:=EM01P.PlateTakePositionRobot;
END_IF;

FOR StationSum := 0 TO StationNum BY 1 DO
	StationInit_R[StationSum](Clk:=MyStation.EMStation[EMNumber,StationSum].Init OR Act.Act04_Init[EMNumber]);
	IF  StationInit_R[StationSum].Q 
	THEN 
		MyStation.EMStation[EMNumber,StationSum].ResetComplete :=FALSE;
	END_IF;
    IF 	(MyStation.EMStation[EMNumber,StationSum].Init 
		OR Act.Act04_Init[EMNumber])
		AND Inital_Runing
		AND MyInput.AutoSwitch_Input
		AND NOT MyStation.EM[EMNumber].Shielding
		AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
		AND NOT MyStation.EM[EMNumber].IsAlarm
		AND NOT MyStation.EM[0].Running
		AND NOT OperationOut.Abort
		AND NOT OperationOut.Stop
		AND NOT OperationOut.Hold
		AND NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete
	THEN 
		Act.Act04_Init_Station[EMNumber,StationSum] := TRUE;
	ELSE
		Act.Act04_Init_Station[EMNumber,StationSum] := FALSE;
	END_IF;
END_FOR;

FOR StationSum := 0 TO StationNum BY 1 DO
	IF  MyStation.EMStation[EMNumber,StationSum].ResetComplete OR  MyStation.EMStation[EMNumber,StationSum].Shielding THEN 
		MyStation.EM[EMNumber].ResetComplete :=TRUE;
	ELSIF NOT MyStation.EMStation[EMNumber,StationSum].ResetComplete AND NOT MyStation.EMStation[EMNumber,StationSum].Shielding
	THEN 
		MyStation.EM[EMNumber].ResetComplete := FALSE;
		EXIT;
	END_IF;
END_FOR;

(*****************************EM01_焊后除尘模组状态机*****************************) 

EMNumber := 1;//模组编号
StationNum :=4-1 ;//工位数量--数组编号最大为0..9
//0--------除尘模组
Act.Act01_Status[1]:=TRUE;//工位状态机程序
Act.Act02_Condition[1]:=TRUE;//循环扫描程序
//手动动运行程序
Act.Act03_Manual[1]:=  MyStatus.StatusManual;	
//初始化程序
MyStation.EM[1].Resting:=Act.Act04_Init[1];
//自动运行程序			
MyStation.EM[1].Running:=Act.Act05_Auto[1];										
//功能块调用程序						 
Act.Act06_IOCall_FB[1]:=TRUE;
//轴功能块调用程序						 
Act.Act07_AxisCall_FB[1]:=TRUE;
//通讯程序						 
Act.Act08_Communication[1]:=TRUE;
//报警信息程序						 
Act.Act09_AlmAndMesg[1]:= NOT MyStation.EM[1].Shielding
					AND MyStation.EmgStop
					AND MyStation.SafetyDoor
					AND MyStation.SafetyRaster;


FOR StationSum := 0 TO StationNum BY 1 DO
//功能状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowAuto		:=	Act.Act05_Auto_Station[EMNumber,StationSum] OR Act.Act04_Init_Station[EMNumber,StationSum]					;//自动状态
Act.Act10_Call_Status[EMNumber,StationSum].AllowManual	:=	Act.Act03_Manual[EMNumber]																		;//手动状态
Act.Act10_Call_Status[EMNumber,StationSum].AlarmReset	:=	MyInput.Reset_Input																		;//复位状态
Act.Act10_Call_Status[EMNumber,StationSum].Aborting		:= NOT MyStation.EmgStop OR NOT MyStation.SafetyDoor				;//急停中止
Act.Act10_Call_Status[EMNumber,StationSum].StopCmd		:=	MyStation.EM[EMNumber].Stopping	AND NOT MyStation.EM[EMNumber].Resting		;//停止
Act.Act10_Call_Status[EMNumber,StationSum].DoorAborting:=	NOT MyStation.EmgStop	OR NOT MyStation.SafetyDoor				;//门禁中止																		
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[1]	:= MyStation.ProductionMode															;//生产模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[2]	:= MyStation.MaintenanceMode														;//维护模式										
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[3]	:= Act.Act04_Init_Station[EMNumber,StationSum];//初始化模式												
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[4] 	:= Act.Act03_Manual[EMNumber];//手动模式									
Act.Act10_Call_Status[EMNumber,StationSum].ModeBit[5] 	:= MyStation.MaintenanceMode;//维修模式			
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[0]	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[1]	:= NOT	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //未复
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[2]	:=	MyStation.EMStation[EMNumber,StationSum].Resting;  //复位中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[3]	:=	MyStation.EMStation[EMNumber,StationSum].ResetComplete;  //复位完成
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[4]	:=	Device_Starting;  //自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[5]	:=	Device_Starting;  //单步自动中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[6]	:=	MyStation.EM[EMNumber].Stopping;  //暂停中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[7]	:=	NOT MyStation.SafetyDoor AND FALSE;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].StatusBit[8]	:=	NOT MyStation.EmgStop;  //停止中
Act.Act10_Call_Status[EMNumber,StationSum].AlarmShield	:= MyStation.EMStation[EMNumber,StationSum].Shielding;  //工位屏蔽中
END_FOR;

Act.Act10_Call_Status[EMNumber,0].AllowAuto:=Act.Act10_Call_Status[EMNumber,1].AllowAuto OR	Act.Act10_Call_Status[EMNumber,1].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,2].AllowAuto OR	Act.Act10_Call_Status[EMNumber,3].AllowAuto 
																				OR	Act.Act10_Call_Status[EMNumber,4].AllowAuto OR	Act.Act10_Call_Status[EMNumber,5].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,6].AllowAuto OR	Act.Act10_Call_Status[EMNumber,7].AllowAuto
																				OR	Act.Act10_Call_Status[EMNumber,8].AllowAuto OR	Act.Act10_Call_Status[EMNumber,9].AllowAuto
																				OR	(Act.Act05_Auto_Station[EMNumber,0] OR Act.Act04_Init_Station[EMNumber,0]);

//--------------输入-----------------------------------//
usiEM01Index:=USINT#1;//工位号
