bEM01_Run:=Act.Act05_Auto_Station[1,2];//工位自动									
														
abEM01ActionStart[3] :=EM01V.Process_steps[2]=120; //上料Z轴上升							
abEM01ActionDone[3]	 :=EM01V.Process_steps[2]=130; 
