data.STCode:
//=========顶盖托盘上下料物流线========= //=========输入映射========= LinkSignal_Input[0,0] := X020804 ;// 顶盖堆栈物流线允许取料 LinkSignal_Input[0,1] := X020805 ;// 顶盖堆栈物流对接安全信号 LinkSignal_Input[0,2] := X020806 ;// 顶盖堆栈物流线允许放料
EM01V.LinkIn_Allow1 := LinkSignal_Input[0,0] ;// 物流线To设备：允许上料 EM01V.LinkIn_SafetySD := LinkSignal_Input[0,1] ;// 物流线To设备：安全门禁 EM01V.LinkIn_Allow2 := LinkSignal_Input[0,2] ;// 物流线To设备：允许下料
//=========输出映射========= LinkSignal_Output[0,0] := HMI_LinkSignal[0,40] XOR EM01V.LinkOut_Request1 ;// 设备To物流线：请求上料 LinkSignal_Output[0,1] := HMI_LinkSignal[0,41] XOR EM01V.LinkOut_Done1 ;// 设备To物流线：上料完成 LinkSignal_Output[0,2] := HMI_LinkSignal[0,42] XOR EM01V.LinkOut_MovingAllow1 ;// 设备To物流线：上料移动允许 LinkSignal_Output[0,3] := HMI_LinkSignal[0,43] XOR EM01V.LinkOut_SafetySD ;// 设备To物流线：安全门禁 LinkSignal_Output[0,4] := HMI_LinkSignal[0,44] XOR EM01V.LinkOut_Request2 ;// 设备To物流线：请求下料 LinkSignal_Output[0,5] := HMI_LinkSignal[0,45] XOR EM01V.LinkOut_Done2 ;// 设备To物流线：下料完成 LinkSignal_Output[0,6] := HMI_LinkSignal[0,46] XOR EM01V.LinkOut_MovingAllow2 ;// 设备To物流线：下料移动允许
Y020801 := LinkSignal_Output[0,0] ;// 顶盖堆栈物料线设备取料准备 Y020802 := LinkSignal_Output[0,1] ;// 顶盖堆栈物料线设备取料完成 Y020803 := LinkSignal_Output[0,2] ;// 顶盖堆栈物料线设备取料可通过 Y020804 := LinkSignal_Output[0,3] ;// 顶盖堆栈物料线设备对接安全信号 Y020805 := LinkSignal_Output[0,4] ;// 顶盖堆栈物料线设备放料准备 Y020806 := LinkSignal_Output[0,5] ;// 顶盖堆栈物料线设备放料完成 Y020807 := LinkSignal_Output[0,6] ;// 顶盖堆栈物料线设备放料可通过
//HMI状态显示 AryMove(In:=LinkSignal_Input[0,0], AryOut:=HMI_LinkSignal[0,0], Size:=20); AryMove(In:=LinkSignal_Output[0,0], AryOut:=HMI_LinkSignal[0,20], Size:=20);

//=========电芯上料物流线=========
//=========输入映射=========
LinkSignal_Input[1,0]	:=	X020807	;//	上料物流线允许取料
LinkSignal_Input[1,1]	:=	X020808	;//	上料物流对接安全信号


EM04V.LinkIn_Allow	:=	LinkSignal_Input[1,0]	;//	物流线To设备：允许取料
EM04V.LinkIn_SafetySD	:=	LinkSignal_Input[1,1]	;//	物流线To设备：安全门禁


//=========输出映射=========
LinkSignal_Output[1,0]	:=	HMI_LinkSignal[1,40]	XOR	EM04V.LinkOut_Request	;//	设备To物流线：请求取料
LinkSignal_Output[1,1]	:=	HMI_LinkSignal[1,41]	XOR	EM04V.LinkOut_Done	;//	设备To物流线：取料完成
LinkSignal_Output[1,2]	:=	HMI_LinkSignal[1,42]	XOR	EM04V.LinkOut_MovingAllow	;//	设备To物流线：移动允许
LinkSignal_Output[1,3]	:=	HMI_LinkSignal[1,43]	XOR	EM04V.LinkOut_SafetySD	;//	设备To物流线：安全门禁


